    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    LTE_PHY_RX_API_UU_RXINDICATIONS_CGI cgi;
} LTE_PHY_RX_API_UU_RXINDICATIONS;

// Dynamic array for storing LTE_PHY_RX_API_UU_RXINDICATIONS structures
typedef struct {
    size_t capacity;
    size_t size;
    LTE_PHY_RX_API_UU_RXINDICATIONS *elements;
} LTE_PHY_RX_API_UU_RXINDICATIONS_ARRAY;

// Function to manage the dynamic array of LTE_PHY_RX_API_UU_RXINDICATIONS structures
void manage_array(LTE_PHY_RX_API_UU_RXINDICATIONS_ARRAY *array, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, LTE_PHY_RX_API_UU_RXINDICATIONS_CGI cgi) {
    // Check if the array needs to be resized
    if (array->size == array->capacity) {
        array->capacity *= 2;
        LTE_PHY_RX_API_UU_RXINDICATIONS *new_elements = realloc(array->elements, sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS) * array->capacity);
        if (new_elements == NULL) {
            // Handle memory allocation failure safely
            return;
        }
        array->elements = new_elements;
    }

    // Append the new structure to the array
    LTE_PHY_RX_API_UU_RXINDICATIONS *new_element = &array->elements[array->size++];
    new_element->rx_ue_information_tag = rx_ue_information_tag;
    new_element->rnti = rnti;
    new_element->cgi = cgi;
}

// Function to clear the dynamic array of LTE_PHY_RX_API_UU_RXINDICATIONS structures safely
void clear_array(LTE_PHY_RX_API_UU_RXINDICATIONS_ARRAY *array) {
    // Lock the array to prevent concurrent modifications
    pthread_mutex_lock(&array->mutex);

    // Clear the array by setting its size to 0
    array->size = 0;

    // Unlock the array
    pthread_mutex_unlock(&array->mutex);
}
