void allocate_offsets(long *offset_array, int *key_array, int num_records) {
    // Allocate memory for offset array
    offset_array = (long *)malloc(num_records * sizeof(long));
    if (!offset_array) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        exit(1);
    }

    // Allocate memory for key array
    key_array = (int *)malloc(num_records * sizeof(int));
    if (!key_array) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        exit(1);
    }

    // Initialize offset and key arrays
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i * INCREMENT;
        key_array[i] = rand() % MAX_KEY;
    }
}

// Function to deallocate memory for arrays of long and int offsets
