// Define the regular expression for filtering lines
const char* regex = ".*";

// Define the maximum memory usage limit (in bytes)
const size_t max_mem_usage = 1024 * 1024; // 1 MB

// Define the buffer size for reading input files (in bytes)
const size_t buffer_size = 1024; // 1 KB

int main(int argc, char* argv[]) {
    // Initialize variables
    int verbose = 0;
    const char* output_path = NULL;
    regex_t reg;

    // Parse command line arguments
    while ((opt = getopt(argc, argv, "vo:r:")) != -1) {
        switch (opt) {
            case 'v':
                verbose = 1;
                break;
            case 'o':
                output_path = optarg;
                break;
            case 'r':
                regex = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-v] [-o output_file] [-r regular_expression]\n", argv[0]);
                return 1;
        }
    }

    // Check if input files were provided
    if (optind >= argc) {
        printf("No input files specified. Using stdin.\n");
        optind = 1;
    }

    // Initialize the regular expression for filtering lines
    int reti = regcomp(&reg, regex, REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Failed to compile regular expression\n");
        return 1;
    }

    // Process each input file sequentially and print the number of matching lines
    for (int i = optind; i < argc; i++) {
        FILE* infile = fopen(argv[i], "r");
        if (!infile) {
            perror("fopen");
            return 1;
        }

        // Create a buffer for reading input files
        char* buffer = (char*)malloc(buffer_size);
        size_t match_count = 0;

        while ((read = fread(buffer, sizeof(char), buffer_size, infile))) {
            const char* line = strtok(buffer, "\n");
            while (line) {
                // Apply the regular expression filter to each line
                regexec(&reg, line, 0, NULL, 0);

                // Increment the match count if the line matches
                if (reti == 0) {
                    match_count++;
                }

                line = strtok(NULL, "\n");
            }
        }

        printf("Processed %s with %lu matching lines\n", argv[i], match_count);

        // Close the input file and free the buffer
        fclose(infile);
        free(buffer);
    }

    // Clean up the regular expression object
    regfree(&reg);

    return 0;
}
```
