#include <openssl/evp.h>

struct EVP_CIPHER *select_cipher(const char* cipher, const char* mode) {
    if (strcmp(cipher, "AES-128") == 0 && strcmp(mode, "CBC") == 0) {
        return EVP_aes_128_cbc();
    } else if (strcmp(cipher, "AES-128") == 0 && strcmp(mode, "GCM") == 0) {
        return EVP_aes_128_gcm();
    } else if (strcmp(cipher, "AES-256") == 0 && strcmp(mode, "CBC") == 0) {
        return EVP_aes_256_cbc();
    } else if (strcmp(cipher, "AES-256") == 0 && strcmp(mode, "GCM") == 0) {
        return EVP_aes_256_gcm();
    } else if (strcmp(cipher, "ChaCha20") == 0 && strcmp(mode, "CTR") == 0) {
        return EVP_chacha20_ctr();
    } else {
        // Handle invalid cipher/mode combination or unknown cipher/mode
        return NULL;
    }
}

struct EVP_CIPHER *configure_cipher(const char* cipher, const char* mode, int key_size, int iv_len) {
    struct EVP_CIPHER *cipher = select_cipher(cipher, mode);

    // Handle invalid cipher/mode combination or unknown cipher/mode
    if (!cipher) {
        return NULL;
    }

    // Set key size and initialization vector length
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, cipher, NULL, NULL);
    if (key_size > 0) {
        EVP_CIPHER_CTX_set_key_length(ctx, key_size);
    }
    if (iv_len > 0) {
        EVP_CIPHER_CTX_set_iv_length(ctx, iv_len);
    }

    // Handle error in setting key length or IV length
    if (EVP_EncryptInit(ctx, cipher, NULL, NULL) < 0) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
```
This code uses the `openssl/evp.h` header file to provide access to the OpenSSL library's cryptographic functions, including AES and ChaCha20 encryption algorithms and CBC, GCM, and CTR modes. The `select_cipher()` function selects the appropriate cipher and mode based on the user input strings "AES-128", "AES-256", "ChaCha20", "CBC", "GCM", or "CTR". If an invalid combination is provided, it returns `NULL`.

The `configure_cipher()` function takes the selected cipher and mode, as well as the key size and initialization vector length (if applicable) as input. It creates a new context using `EVP_CIPHER_CTX_new()`, selects the appropriate cipher and mode using `EVP_EncryptInit()`, sets the key length and IV length (if applicable) using `EVP_CIPHER_CTX_set_key_length()` and `EVP_CIPHER_CTX_set_iv_length()`, respectively, and returns a pointer to the context. If an error occurs while setting the key length or initialization vector length, it returns `NULL`.

Note that this code assumes that the user has already provided valid input for the cipher, mode, key size, and IV length (if applicable). It also assumes that the user has access to the OpenSSL library's cryptographic functions.']

