public class PokemonBattleReport {
    private static final Map<String, List<String>> POKEMON_TYPES = new HashMap<>(); // map of pokemon names to their types
    private static final Map<String, String> WEAKNESS_MAP = new HashMap<>(); // map of weaknesses between pokemon types
    private static final Map<String, String> RESISTANCE_MAP = new HashMap<>(); // map of resistances between pokemon types
    private static final Map<String, String> IMMUNITY_MAP = new HashMap<>(); // map of immunities between pokemon types
    private static final List<String> POKEMON_LIST = new ArrayList<>(); // list of all the available pokemon names

    // initialize maps and lists with data from external API
    static {
        // populate POKEMON_TYPES, WEAKNESS_MAP, RESISTANCE_MAP, IMMUNITY_MAP, and POKEMON_LIST
        // this code is not included in the sample, but it would be how you retrieve the data from an external API
    }

    public static PokemonBattleReport generateReport(String pokemonName) {
        if (POKEMON_TYPES.containsKey(pokemonName)) {
            List<String> types = POKEMON_TYPES.get(pokemonName);
            // calculate weaknesses, resistances, and immunities for each type
            Map<String, List<String>> weaknessMap = new HashMap<>();
            Map<String, List<String>> resistanceMap = new HashMap<>();
            Map<String, List<String>> immunityMap = new HashMap<>();

            for (String type : types) {
                // calculate weaknesses and resistances for each type
                weaknessMap.put(type, WEAKNESS_MAP.get(type));
                resistanceMap.put(type, RESISTANCE_MAP.get(type));

                // calculate immunities for each type
                List<String> immunities = new ArrayList<>();
                if (IMMUNITY_MAP.containsKey(type)) {
                    immunities = IMMUNITY_MAP.get(type);
                }
                immunityMap.put(type, immunities);
            }

            // calculate overall effectiveness score for each type
            Map<String, Double> effectivenessScores = new HashMap<>();
            for (String type : types) {
                List<String> weaknesses = weaknessMap.get(type);
                List<String> resistances = resistanceMap.get(type);
                List<String> immunities = immunityMap.get(type);

                double effectivenessScore = 0;
                for (String weakness : weaknesses) {
                    effectivenessScore += POKEMON_TYPES.get(weakness).size();
                }
                for (String resistance : resistances) {
                    effectivenessScore -= POKEMON_TYPES.get(resistance).size();
                }
                for (String immunity : immunities) {
                    effectivenessScore = 0;
                }

                effectivenessScores.put(type, effectivenessScore);
            }

            return new PokemonBattleReport(pokemonName, types, weaknessMap, resistanceMap, immunityMap, effectivenessScores);
        } else {
            throw new IllegalArgumentException("Pokemon not found: " + pokemonName);
        }
    }

    private PokemonBattleReport(String pokemonName, List<String> types, Map<String, List<String>> weaknessMap, Map<String, List<String>> resistanceMap, Map<String, List<String>> immunityMap, Map<String, Double> effectivenessScores) {
        this.pokemonName = pokemonName;
        this.types = types;
        this.weaknessMap = weaknessMap;
        this.resistanceMap = resistanceMap;
        this.immunityMap = immunityMap;
        this.effectivenessScores = effectivenessScores;
    }

    public String getPokemonName() {
        return pokemonName;
    }

    public List<String> getTypes() {
        return types;
    }

    public Map<String, List<String>> getWeaknessMap() {
        return weaknessMap;
    }

    public Map<String, List<String>> getResistanceMap() {
        return resistanceMap;
    }

    public Map<String, List<String>> getImmunityMap() {
        return immunityMap;
    }

    public Map<String, Double> getEffectivenessScores() {
        return effectivenessScores;
    }
}
