#include <openssl/des.h>

#define MAX_ALGORITHMS 10
#define MAX_KEY_LENGTH 64
#define MAX_IV_LENGTH 16
#define DEFAULT_ALGORITHM "AES"

typedef enum {
    AES = 0,
    DES,
} algorithm;

struct encryption_algorithm {
    const char* name;
    size_t key_length;
    size_t iv_length;
    void (*encrypt)(const uint8_t* plaintext, const size_t plaintext_size, uint8_t* ciphertext);
    void (*decrypt)(const uint8_t* ciphertext, const size_t ciphertext_size, uint8_t* plaintext);
};

struct encryption_algorithm algorithms[MAX_ALGORITHMS] = {
    {"AES", 32, 16, (void*)aes_encrypt, (void*)aes_decrypt},
    {"DES", 8,  8,  (void*)des_encrypt, (void*)des_decrypt}
};

int encrypt(const char* algorithm, const uint8_t* plaintext, const size_t plaintext_size, uint8_t* ciphertext) {
    int index = find_algorithm(algorithm);
    if (index == -1) {
        return -1;
    }
    struct encryption_algorithm* algo = &algorithms[index];
    algo->encrypt(plaintext, plaintext_size, ciphertext);
}

int decrypt(const char* algorithm, const uint8_t* ciphertext, const size_t ciphertext_size, uint8_t* plaintext) {
    int index = find_algorithm(algorithm);
    if (index == -1) {
        return -1;
    }
    struct encryption_algorithm* algo = &algorithms[index];
    algo->decrypt(ciphertext, ciphertext_size, plaintext);
}

int find_algorithm(const char* name) {
    for (int i = 0; i < MAX_ALGORITHMS; i++) {
        if (strcmp(algorithms[i].name, name) == 0) {
            return i;
        }
    }
    return -1;
}
