// C code for a semaphore management library in C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/mman.h>
#include <semaphore.h>

// Define the maximum number of semaphores that can be created
#define MAX_SEMAPHORES 1024

// Define the maximum length of a semaphore name
#define MAX_NAME_LEN 64

// Struct to store information about each semaphore
struct Semaphore {
	char name[MAX_NAME_LEN]; // Name of the semaphore
	int initial_value; // Initial value of the semaphore
	sem_t *sem; // Pointer to the semaphore object
	pthread_mutex_t mutex; // Mutex for locking access to the semaphore
};

// Array to store all created semaphores
struct Semaphore semaphores[MAX_SEMAPHORES];

// Function to create a new semaphore with a given name and initial value
int create_semaphore(char *name, int initial_value) {
	int i;

	// Check if the maximum number of semaphores has been reached
	if (MAX_SEMAPHORES <= 0) {
		printf("Maximum number of semaphores reached\n");
		return -1;
	}

	// Check if a semaphore with the same name already exists
	for (i = 0; i < MAX_SEMAPHORES; i++) {
		if (!strcmp(semaphores[i].name, name)) {
			printf("Semaphore with name '%s' already exists\n", name);
			return -1;
		}
	}

	// Create a new semaphore object
	sem_t *sem = malloc(sizeof(sem_t));
	if (sem == NULL) {
		printf("Error creating semaphore\n");
		return -1;
	}

	// Initialize the semaphore with the given initial value
	if (sem_init(sem, 0, initial_value)) {
		printf("Error initializing semaphore\n");
		free(sem);
		return -1;
	}

	// Store the new semaphore in the array of semaphores
	strcpy(semaphores[MAX_SEMAPHORES].name, name);
	semaphores[MAX_SEMAPHORES].initial_value = initial_value;
	semaphores[MAX_SEMAPHORES].sem = sem;
	pthread_mutex_init(&(semaphores[MAX_SEMAPHORES].mutex), NULL);

	// Increment the number of created semaphores
	MAX_SEMAPHORES++;

	return 0;
}

// Function to delete a semaphore with a given name
int delete_semaphore(char *name) {
	int i;

	// Find the index of the semaphore with the given name
	for (i = 0; i < MAX_SEMAPHORES; i++) {
		if (!strcmp(semaphores[i].name, name)) {
			break;
		}
	}

	// If the semaphore was not found, return an error
	if (i == MAX_SEMAPHORES) {
		printf("Semaphore with name '%s' does not exist\n", name);
		return -1;
	}

	// Lock the mutex associated with the semaphore to prevent race conditions
	pthread_mutex_lock(&(semaphores[i].mutex));

	// Delete the semaphore object and free its memory
	sem_destroy(semaphores[i].sem);
	free(semaphores[i].sem);

	// Decrement the number of created semaphores
	MAX_SEMAPHORES--;

	// Move the last semaphore in the array to the position of the deleted semaphore
	memmove(&semaphores[i], &semaphores[MAX_SEMAPHORES], sizeof(struct Semaphore));

	// Unlock the mutex associated with the semaphore
	pthread_mutex_unlock(&(semaphores[i].mutex));

	return 0;
}

// Function to acquire a semaphore with a given name
int acquire_semaphore(char *name) {
	int i;

	// Find the index of the semaphore with the given name
	for (i = 0; i < MAX_SEMAPHORES; i++) {
		if (!strcmp(semaphores[i].name, name)) {
			break;
		}
	}

	// If the semaphore was not found, return an error
	if (i == MAX_SEMAPHORES) {
		printf("Semaphore with name '%s' does not exist\n", name);
		return -1;
	}

	// Lock the mutex associated with the semaphore to prevent race conditions
	pthread_mutex_lock(&(semaphores[i].mutex));

	// Acquire the semaphore using the POSIX API
	if (sem_wait(semaphores[i].sem)) {
		printf("Error acquiring semaphore\n");
		pthread_mutex_unlock(&(semaphores[i].mutex));
		return -1;
	}

	// Unlock the mutex associated with the semaphore
	pthread_mutex_unlock(&(semaphores[i].mutex));

	return 0;
}

// Function to release a semaphore with a given name
int release_semaphore(char *name) {
	int i;

	// Find the index of the semaphore with the given name
	for (i = 0; i < MAX_SEMAPHORES; i++) {
		if (!strcmp(semaphores[i].name, name)) {
			break;
		}
	}

	// If the semaphore was not found, return an error
	if (i == MAX_SEMAPHORES) {
		printf("Semaphore with name '%s' does not exist\n", name);
		return -1;
	}

	// Lock the mutex associated with the semaphore to prevent race conditions
	pthread_mutex_lock(&(semaphores[i].mutex));

	// Release the semaphore using the POSIX API
	if (sem_post(semaphores[i].sem)) {
		printf("Error releasing semaphore\n");
		pthread_mutex_unlock(&(semaphores[i].mutex));
		return -1;
	}

	// Unlock the mutex associated with the semaphore
	pthread_mutex_unlock(&(semaphores[i].mutex));

	return 0;
}

// Function to print a log message for a given semaphore event
void log_event(char *name, char *action) {
	printf("Semaphore '%s': %s\n", name, action);
}

int main() {
	create_semaphore("sem1", 0);
	create_semaphore("sem2", 0);

	acquire_semaphore("sem1");
	release_semaphore("sem1");

	delete_semaphore("sem1");

	return 0;
}']

