    // Caching mechanism to minimize API calls and reduce load times when the configuration file does not change frequently
    let cache_path = get_cache_path(profile_name);
    if cache_exists(&cache_path) {
        machine_code = read_cache(&cache_path)?;
    } else {
        write_cache(&cache_path, &machine_code)?;
    }

