    file.read_to_string(&mut contents)?;

    let config: ConfigurationFile = serde_json::from_str(&contents).map_err(|e| e.to_string())?;

    Ok(config)
}

fn get_cache_path(profile_name: &str) -> PathBuf {
    let mut cache_path = PathBuf::new();
    cache_path.push("machine_code");
    cache_path.set_extension("json");
    cache_path.set_file_name(format!("{}.cache", profile_name));

    cache_path
}

fn cache_exists(path: &PathBuf) -> bool {
    path.exists() && !path.is_dir()
}

fn read_cache(path: &PathBuf) -> Result<Vec<u8>, String> {
    let mut file = File::open(&path)?;
    let mut contents = Vec::new();
    file.read_to_end(&mut contents)?;

    Ok(contents)
}

fn write_cache(path: &PathBuf, contents: &[u8]) -> Result<(), String> {
    let mut file = File::create(&path)?;
    file.write_all(contents)?;

    Ok(())
}
```
