fn InitializeEnvironmentWithDirectory(directory_name: &str, env_var: &mut String) -> Result<(), Box<dyn std::error::Error>> {
    if !env_var.is_empty() && !env_var.starts_with(directory_name) {
        return Err("Environment variable already set and does not correspond to the provided directory name.".into());
    } else if !fs::metadata(directory_name).exists() {
        fs::create_dir(directory_name)?;
        *env_var = directory_name.to_string();
    }

    Ok(())
