import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.nio.file.Paths;
import java.util.logging.Level;
import java.util.logging.Logger;

public MoSTState loadStateOrRecycleTheme(String filePath) throws IOException {
    // Verify if a default theme directory is configured within the application's settings
    String defaultThemeDir = getDefaultThemeDirectory();

    // If no default theme directory is configured, attempt to load a fallback configuration from an external JSON file in the assets directory
    if (defaultThemeDir == null) {
        try {
            defaultThemeDir = Paths.get("assets/fallback_theme.json").toString();
        } catch (Exception e) {
            Logger.getLogger(MoSTState.class.getName()).log(Level.WARNING, "Failed to load fallback theme configuration", e);
            defaultThemeDir = "default_theme"; // Set the default theme directory to a predefined default value
        }
    }

    // Read a state object from the specified file path using an ObjectInputStream
    FileInputStream inputStream = new FileInputStream(filePath);
    ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);
    MoSTState state;
    try {
        state = (MoSTState) objectInputStream.readObject();
    } catch (ClassNotFoundException e) {
        Logger.getLogger(MoSTState.class.getName()).log(Level.WARNING, "Failed to deserialize state", e);
        state = null;
    } finally {
        objectInputStream.close();
    }

    // Check if the read state is an instance of the MoSTState class and return it if so
    if (state instanceof MoSTState) {
        return state;
    } else {
        // If the read state is not an instance of the MoSTState class, recycle the theme bitmap and set it to null
        recycleThemeBitmap(defaultThemeDir);
        return null;
    }
}

private void recycleThemeBitmap(String defaultThemeDir) {
    // Verify if the default theme directory is configured within the application's settings
    if (defaultThemeDir == null || !new File(defaultThemeDir).exists()) {
        Logger.getLogger(MoSTState.class.getName()).log(Level.WARNING, "Invalid default theme directory");
        return;
    }

    // Parse a PNG file from the cache root directory and store it in the theme cache
    File cacheRootDirectory = new File(defaultThemeDir);
    File[] cacheFiles = cacheRootDirectory.listFiles();
    if (cacheFiles == null || cacheFiles.length == 0) {
        Logger.getLogger(MoSTState.class.getName()).log(Level.WARNING, "No cached files found");
        return;
    }

    // Recycle the theme bitmap and set it to null afterward
    for (File cacheFile : cacheFiles) {
        if (cacheFile.isFile() && cacheFile.getName().endsWith(".png")) {
            Logger.getLogger(MoSTState.class.getName()).log(Level.INFO, "Recycling theme bitmap: " + cacheFile.getName());
            cacheFile.delete();
            break;
        }
    }
}

private String getDefaultThemeDirectory() {
    // Verify if a default theme directory is configured within the application's settings
    String defaultThemeDir = null;
    try {
        defaultThemeDir = Paths.get("app/theme").toString();
    } catch (Exception e) {
        Logger.getLogger(MoSTState.class.getName()).log(Level.WARNING, "Failed to load default theme directory", e);
    }
    return defaultThemeDir;
}
