```cpp
#include <iostream>

void insertStringAfter(std::forward_list<std::string>& list, const std::string& str) {
  // Locate the first occurrence of the first string parameter within the forward list
  auto it = list.begin();
  while (it != list.end() && *it != str) {
    ++it;
  }

  if (it == list.end()) {
    // If the first string parameter is not present in the list, append the second string parameter to the end of the list
    list.push_back(str);
  } else {
    // Insert the second string parameter immediately after the first string parameter
    list.insert_after(it, str);
  }
}
