import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServiceManager {
    private final ExecutorService executorService;
    private final List<Service> services;

    public ServiceManager() {
        this.executorService = Executors.newCachedThreadPool();
        this.services = new ArrayList<>();
    }

    public void startService(Service service) {
        if (service == null) {
            throw new IllegalArgumentException("Service cannot be null");
        }
        synchronized (this.services) {
            this.services.add(service);
        }
        executorService.submit(() -> {
            try {
                service.start();
            } catch (Exception e) {
                // handle error
            }
        });
    }

    public void stopService(String name) {
        synchronized (this.services) {
            Service service = this.getServiceByName(name);
            if (service != null) {
                try {
                    service.stop();
                } catch (Exception e) {
                    // handle error
                }
            }
        }
    }

    public void pauseService(String name) {
        synchronized (this.services) {
            Service service = this.getServiceByName(name);
            if (service != null) {
                try {
                    service.pause();
                } catch (Exception e) {
                    // handle error
                }
            }
        }
    }

    public void resumeService(String name) {
        synchronized (this.services) {
            Service service = this.getServiceByName(name);
            if (service != null) {
                try {
                    service.resume();
                } catch (Exception e) {
                    // handle error
                }
            }
        }
    }

    private Service getServiceByName(String name) {
        for (Service service : this.services) {
            if (service.getName().equals(name)) {
                return service;
            }
        }
        return null;
    }
}

class Service {
    private final String name;
    private final InputStream inputStream;
    private final OutputStream outputStream;
    private volatile boolean running;
    private volatile boolean paused;

    public Service(String name, InputStream inputStream, OutputStream outputStream) {
        this.name = name;
        this.inputStream = inputStream;
        this.outputStream = outputStream;
        this.running = false;
        this.paused = false;
    }

    public String getName() {
        return this.name;
    }

    public void start() throws Exception {
        synchronized (this) {
            if (!this.running && !this.paused) {
                this.running = true;
                new Thread(() -> {
                    try {
                        while (true) {
                            if (Thread.currentThread().isInterrupted()) {
                                break;
                            }
                            byte[] buffer = new byte[1024];
                            int read = this.inputStream.read(buffer);
                            if (read > 0) {
                                this.outputStream.write(buffer, 0, read);
                            } else {
                                break;
                            }
                        }
                    } catch (Exception e) {
                        // handle error
                    }
                }, "Service-" + this.name).start();
            }
        }
    }

    public void stop() throws Exception {
        synchronized (this) {
            if (this.running || this.paused) {
                this.running = false;
                this.paused = false;
                Thread.currentThread().interrupt();
            }
        }
    }

    public void pause() throws Exception {
        synchronized (this) {
            if (this.running && !this.paused) {
                this.running = false;
                this.paused = true;
            }
        }
    }

    public void resume() throws Exception {
        synchronized (this) {
            if (!this.running && this.paused) {
                this.running = true;
                this.paused = false;
            }
        }
    }
}
```
