// Theme Management System

import java.util.concurrent.*;
import java.util.logging.*;
import org.apache.commons.io.*;
import org.apache.commons.codec.*;

public class ThemeManager {
    private static final Logger logger = Logger.getLogger(ThemeManager.class.getName());
    private static final long THEME_RECYCLING_DELAY = 15 * 60 * 1000; // 15 minutes in milliseconds
    private static final int MAX_THEMES = 100; // maximum number of themes to cache
    private static final int THEME_SIZE_LIMIT = 1024 * 1024; // 1 MB limit for each theme

    private ConcurrentHashMap<String, byte[]> themeCache;
    private ExecutorService executor;

    public ThemeManager() {
        this.themeCache = new ConcurrentHashMap<>();
        this.executor = Executors.newSingleThreadExecutor();
    }

    // Adds a theme to the cache, overwriting any existing theme with the same name
    public void addTheme(String themeName, byte[] themeData) {
        if (themeCache.size() >= MAX_THEMES) {
            // Recycle least recently used theme when maximum size is reached
            recycleOldestTheme();
        }

        if (themeData == null || themeData.length > THEME_SIZE_LIMIT) {
            logger.warning("Invalid theme data received for " + themeName);
            return;
        }

        themeCache.put(themeName, themeData);
    }

    // Returns a cached theme by name, or null if not found
    public byte[] getTheme(String themeName) {
        return themeCache.get(themeName);
    }

    // Removes a theme from the cache by name
    public void removeTheme(String themeName) {
        themeCache.remove(themeName);
    }

    // Recycles the least recently used theme in the cache, if any
    private void recycleOldestTheme() {
        if (themeCache.isEmpty()) {
            return;
        }

        long currentTime = System.currentTimeMillis();
        String oldestThemeName = null;
        long oldestLastAccessed = Long.MAX_VALUE;

        for (Map.Entry<String, byte[]> entry : themeCache.entrySet()) {
            if (entry.getValue() == null) {
                continue; // Ignore removed themes
            }

            long lastAccessed = currentTime - entry.getValue().getLastModified();
            if (lastAccessed < oldestLastAccessed) {
                oldestThemeName = entry.getKey();
                oldestLastAccessed = lastAccessed;
            }
        }

        if (oldestThemeName != null) {
            logger.info("Recycling old theme " + oldestThemeName);
            removeTheme(oldestThemeName);
        }
    }

    // Updates a cached theme from the external theme provider service, if necessary
    public void updateTheme(String themeName) {
        byte[] themeData = getTheme(themeName);
        long currentTime = System.currentTimeMillis();
        boolean needsUpdate = false;

        if (themeData != null && currentTime - themeData.getLastModified() < THEME_RECYCLING_DELAY) {
            // Theme is still valid, check for updates every 15 minutes
            executor.schedule(() -> updateTheme(themeName), 15 * 60 * 1000, TimeUnit.MILLISECONDS);
        } else {
            needsUpdate = true;
        }

        if (needsUpdate) {
            logger.info("Updating theme " + themeName);
            downloadTheme(themeName);
        }
    }

    // Downloads a theme from the external theme provider service and adds it to the cache
    private void downloadTheme(String themeName) {
        try {
            byte[] themeData = IOUtils.toByteArray(new URL("https://external-theme-provider.com/" + themeName));
            addTheme(themeName, themeData);
            updateTheme(themeName); // Update again after 15 minutes to maintain freshness
        } catch (IOException e) {
            logger.log(Level.WARNING, "Error downloading theme", e);
        }
    }
}

// Usage example:
