struct DataPoint {
    float value;
    unsigned long timestamp;
};

struct PerformanceMetrics {
    float max_weighted_value;
    int max_weighted_index;
    unsigned long last_minute_timestamp;
};

struct SensorData {
    struct DataPoint *data_points;
    int data_point_count;
    unsigned long sliding_window_size;
    struct PerformanceMetrics metrics;
};

struct SensorData *init_sensor_data(int data_point_count, int sliding_window_size) {
    struct SensorData *sensor_data = (struct SensorData *)malloc(sizeof(struct SensorData));
    if (!sensor_data) {
        return NULL;
    }
    sensor_data->data_points = (struct DataPoint *)malloc(sizeof(struct DataPoint) * data_point_count);
    if (!sensor_data->data_points) {
        free(sensor_data);
        return NULL;
    }
    sensor_data->data_point_count = data_point_count;
    sensor_data->sliding_window_size = sliding_window_size;
    memset(&sensor_data->metrics, 0, sizeof(struct PerformanceMetrics));
    return sensor_data;
}

void free_sensor_data(struct SensorData *sensor_data) {
    if (sensor_data && sensor_data->data_points) {
        free(sensor_data->data_points);
        free(sensor_data);
    }
}

void process_data_point(struct SensorData *sensor_data, float value, unsigned long timestamp) {
    // Sliding window management
    if (sensor_data->data_point_count < sensor_data->sliding_window_size) {
        sensor_data->data_points[sensor_data->data_point_count++] = (struct DataPoint){value, timestamp};
    } else {
        // Replace oldest data point with newest one
        int old_index = 0;
        for (int i = 1; i < sensor_data->sliding_window_size; i++) {
            if (sensor_data->data_points[i].timestamp > sensor_data->data_points[old_index].timestamp) {
                old_index = i;
            }
        }
        // Update value and timestamp of oldest data point
        float old_value = sensor_data->data_points[old_index].value;
        unsigned long old_timestamp = sensor_data->data_points[old_index].timestamp;
        sensor_data->data_points[old_index] = (struct DataPoint){value, timestamp};
        // Update performance metrics
        if (value > old_value) {
            sensor_data->metrics.max_weighted_value += value - old_value;
            sensor_data->metrics.max_weighted_index++;
        } else {
            sensor_data->metrics.max_weighted_value -= old_value - value;
            if (sensor_data->metrics.max_weighted_index > 0) {
                sensor_data->metrics.max_weighted_index--;
            }
        }
    }
    // Update performance metrics
    if (timestamp >= sensor_data->metrics.last_minute_timestamp + 60) {
        float weighted_value = 0;
        for (int i = 0; i < sensor_data->sliding_window_size; i++) {
            float weight = (float)(timestamp - sensor_data->data_points[i].timestamp) / (sensor_data->metrics.last_minute_timestamp + 60);
            weighted_value += weight * sensor_data->data_points[i].value;
        }
        if (weighted_value > sensor_data->metrics.max_weighted_value) {
            sensor_data->metrics.max_weighted_value = weighted_value;
            sensor_data->metrics.max_weighted_index = timestamp;
        }
        // Update last minute timestamp
        sensor_data->metrics.last_minute_timestamp += 60;
    }
}

void process_data_stream(struct SensorData *sensor_data, FILE *data_file) {
    char line[128];
    while (fgets(line, sizeof(line), data_file)) {
