#include <iostream>

// Define attack structures for each attack
struct Attack {
    int duration; // in seconds
    int cost; // in mana points
};

// Define an attack selection structure that contains a list of available attacks and their corresponding costs
struct AttackSelection {
    std::vector<Attack> availableAttacks;
    int manaPool;
    bool isCooldownActive;
    double cooldownTimer; // in seconds
};

// Define the CharacterState class that contains information about the character's state, including their mana pool and cooldown status
class CharacterState {
private:
    int manaPool;
    bool isCooldownActive;
    double cooldownTimer; // in seconds
public:
    CharacterState(int initialMana) : manaPool(initialMana), isCooldownActive(false), cooldownTimer(0.0) {}
    int getMana() { return manaPool; }
    bool isOnCooldown() { return isCooldownActive; }
    double getCooldownTimeRemaining() { return cooldownTimer; }
    void updateState(const AttackSelection& selection) {
        // Update the character's state based on the selected attack and any changes to their mana pool
        if (selection.isCooldownActive) {
            // Defer the attack and resume once resources are replenished
            isCooldownActive = true;
            cooldownTimer = selection.cooldownTimer - (time(NULL) - selection.cooldownStartTime);
        } else {
            // Update the mana pool and start a new cooldown period if necessary
            int cost = selection.availableAttacks[selection.selectedAttack].cost;
            if (cost > 0 && manaPool >= cost) {
                manaPool -= cost;
                isCooldownActive = true;
                cooldownTimer = selection.availableAttacks[selection.selectedAttack].duration;
            } else {
                // Handle edge case: insufficient mana
                std::cout << "Insufficient mana, deferring attack" << std::endl;
            }
        }
    }
};

// Implement the dynamic cooldown logic that ensures smooth transitions between attacks without causing performance bottlenecks or excessive resource consumption
void updateCooldown(CharacterState& state) {
    if (state.isOnCooldown()) {
        // Update the cooldown timer and check for expiration
        state.cooldownTimer -= time(NULL);
        if (state.getCooldownTimeRemaining() <= 0) {
            state.isCooldownActive = false;
            std::cout << "Attack cooldown completed" << std::endl;
        }
    }
}

// Define the attack selection function that selects an attack from the available options, considering current mana availability and cooldown status
void selectAttack(CharacterState& state) {
    AttackSelection selection = getAvailableAttacks(state); // Get a list of all available attacks and their corresponding costs
    if (selection.availableAttacks.empty()) {
        // Handle edge case: no attacks available
        std::cout << "No attacks available, deferring attack" << std::endl;
        return;
    } else {
        // Select an attack based on the character's mana availability and cooldown status
        selection.selectedAttack = 0;
        for (int i = 1; i < selection.availableAttacks.size(); ++i) {
            if (selection.availableAttacks[i].cost <= selection.manaPool && !state.isOnCooldown(i)) {
                selection.selectedAttack = i;
            }
        }
    }
    // Update the character's state and print the selected attack number and remaining mana points
    updateState(selection);
    std::cout << "Selected attack: " << selection.availableAttacks[selection.selectedAttack].cost << " / " << selection.manaPool << std::endl;
}

// Define the function that integrates seamlessly with the existing game engine, adhering to the framework's conventions and performance expectations
void update(CharacterState& state) {
    // Update the character's state based on their actions during the last frame
    selectAttack(state);
    updateCooldown(state);
}
```
