namespace DynamicRandomGenerator
{
    public class RandomNumberGenerator
    {
        // Constant for the default range
        private const int DEFAULT_RANGE = 10000;

        // Private fields for the current minimum and maximum values
        private int _minimumValue;
        private int _maximumValue;

        // Constructor with custom initialization parameters
        public RandomNumberGenerator(int minimum, int maximum)
        {
            if (minimum > maximum)
                throw new ArgumentException("Minimum value cannot be greater than maximum value");

            _minimumValue = minimum;
            _maximumValue = maximum;
        }

        // Default constructor with default range
        public RandomNumberGenerator() : this(DEFAULT_RANGE, DEFAULT_RANGE) { }

        // Private helper method to generate a random number within the current range
        private int GenerateRandomInt(int minimum, int maximum)
        {
            return new Random().Next(minimum, maximum + 1);
        }

        // Public method to generate an integer within the current range
        public int GenerateInteger()
        {
            return GenerateRandomInt(_minimumValue, _maximumValue);
        }

        // Public method to generate a float within the current range
        public float GenerateFloat()
        {
            return (float)GenerateRandomInt(_minimumValue, _maximumValue);
        }

        // Public method to update the range dynamically without disrupting existing sequences of random numbers generated post-update
        public void UpdateRange(int minimum, int maximum)
        {
            if (_minimumValue > maximum || _maximumValue < minimum)
                throw new ArgumentException("New range must be within existing range");

            // Update the private fields for the current minimum and maximum values
            _minimumValue = minimum;
            _maximumValue = maximum;
        }

        // Public method to reset the range to its initial state, discarding all previously generated numbers
        public void ResetRange()
        {
            _minimumValue = DEFAULT_RANGE;
            _maximumValue = DEFAULT_RANGE;
        }

        // Override the ToString method to provide a clear, user-friendly display of the current range
        public override string ToString()
        {
            return $"Random Number Generator ({_minimumValue} - {_maximumValue})";
        }
    }
}
