// Define a shared callback function for accumulating reduction results
function reduceCallback(result, item) {
  if (typeof item !== 'number') {
    // Handle non-numeric elements gracefully
    return result;
  } else {
    // Accumulate the numeric values
    return result + item;
  }
}

// Define a function for performing asynchronous reductions on multiple arrays
function reduceAsync(arrays, initialValue = null) {
  // Create a promise for each array reduction and await all of them to complete
  const promises = arrays.map((arr) => Promise.all(arr).then((values) => values.reduce(reduceCallback, initialValue)));
  return Promise.all(promises);
}

// Define sample inputs for testing the function
