#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <unistd.h>

#define DEFAULT_THEME_DIR "/path/to/default/theme"

// Theme resources cache
struct theme_cache {
    char *name;
    int ref_count;
    void *data;
};

static pthread_mutex_t theme_cache_lock = PTHREAD_MUTEX_INITIALIZER;
static struct theme_cache *theme_cache = NULL;

// Function to initialize a new theme cache entry
void init_theme_cache(char *name) {
    pthread_mutex_lock(&theme_cache_lock);
    if (!theme_cache) {
        theme_cache = malloc(sizeof(struct theme_cache));
        theme_cache->name = strdup(name);
        theme_cache->ref_count = 1;
        theme_cache->data = NULL;
    } else {
        struct theme_cache *current = theme_cache;
        while (current->next) {
            current = current->next;
        }
        current->next = malloc(sizeof(struct theme_cache));
        current->next->name = strdup(name);
        current->next->ref_count = 1;
        current->next->data = NULL;
    }
    pthread_mutex_unlock(&theme_cache_lock);
}

// Function to increase the reference count of a theme cache entry
void inc_ref_count(char *name) {
    pthread_mutex_lock(&theme_cache_lock);
    struct theme_cache *current = theme_cache;
    while (current && strcmp(current->name, name)) {
        current = current->next;
    }
    if (current) {
        current->ref_count++;
    } else {
        init_theme_cache(name);
    }
    pthread_mutex_unlock(&theme_cache_lock);
}

// Function to decrease the reference count of a theme cache entry and remove it if necessary
void dec_ref_count(char *name) {
    pthread_mutex_lock(&theme_cache_lock);
    struct theme_cache *current = theme_cache;
    while (current && strcmp(current->name, name)) {
        current = current->next;
    }
    if (current && current->ref_count == 1) {
        free(current->data);
        current->data = NULL;
        if (!current->next) {
            free(theme_cache);
            theme_cache = NULL;
        } else {
            struct theme_cache *tmp = current->next;
            current->next = tmp->next;
            free(tmp);
        }
    } else if (current) {
        current->ref_count--;
    }
    pthread_mutex_unlock(&theme_cache_lock);
}

// Function to load a theme bitmap from disk and add it to the cache
void load_theme_bitmap(char *name) {
    pthread_mutex_lock(&theme_cache_lock);
    struct theme_cache *current = theme_cache;
    while (current && strcmp(current->name, name)) {
        current = current->next;
    }
    if (!current || !current->data) {
        FILE *file = fopen(name, "rb");
        if (file) {
            fseek(file, 0, SEEK_END);
            long size = ftell(file);
            rewind(file);
            current->data = malloc(size);
            fread(current->data, 1, size, file);
            fclose(file);
        } else {
            printf("Error: Failed to open theme bitmap file %s\n", name);
        }
    }
    pthread_mutex_unlock(&theme_cache_lock);
}

// Function to get a pointer to the theme bitmap data for a given entry
