char* modified_filename(const char* input_filename) {
    // Validate input filename
    if (input_filename == NULL || strlen(input_filename) > 256) {
        return NULL;
    }

    // Allocate memory for the new filename
    size_t new_filename_length = strlen(input_filename) + 10;
    char* new_filename = malloc(new_filename_length);
    if (new_filename == NULL) {
        return NULL;
    }

    // Count the number of vowels in the input filename
    int vowel_count = 0;
    for (size_t i = 0; i < strlen(input_filename); i++) {
        if (isalpha(input_filename[i]) && isvowel(input_filename[i])) {
            vowel_count++;
        }
    }

    // Create the new filename by concatenating the input filename with the vowel count and an 'X'
    snprintf(new_filename, new_filename_length, "%s%dX", input_filename, vowel_count);

    // Return the modified filename
    return new_filename;
}
