1. AES-256-CBC Cipher Initialization in C using OpenSSL:
```c
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

void* init_aes_cbc(const char* password, size_t iv_len, size_t key_len) {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;

    // Initialize the cipher context and set the IV length
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        ERR_load_crypto_strings();
        fprintf(stderr, "EVP_CIPHER_CTX_new(): %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Set the key length and derive the encryption key from the password using a SHA-256 hash function
    cipher = EVP_aes_256_cbc();
    if (!cipher) {
        ERR_load_crypto_strings();
        fprintf(stderr, "EVP_aes_256_cbc(): %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }
    if (EVP_CIPHER_key_length(cipher) != key_len) {
        fprintf(stderr, "Invalid key length: must be %d bytes\n", EVP_CIPHER_key_length(cipher));
        return NULL;
    }
    unsigned char key[EVP_MAX_KEY_LENGTH];
    if (!EVP_BytesToKey(cipher, EVP_sha256(), NULL, (unsigned char*)password, strlen(password), 1, key, NULL)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "EVP_BytesToKey(): %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Initialize the cipher context with the derived key and IV length
    if (!EVP_CipherInit_ex(ctx, cipher, NULL, key, NULL, EVP_CIPH_ENCRYPT)) {
        ERR_load_crypto_strings();
        fprintf(stderr, "EVP_CipherInit_ex(): %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }
    if (!EVP_CIPHER_CTX_set_iv_length(ctx, iv_len)) {
        fprintf(stderr, "EVP_CIPHER_CTX_set_iv_length(): %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Return a pointer to the cipher context
    return ctx;
}
```
This function takes in a password, IV length, and key length as input. It initializes an AES-256-CBC cipher with the given password using the OpenSSL library. The function derives the encryption key from the password using a SHA-256 hash function and sets it as the encryption key for the cipher. It then sets the IV length to 16 bytes and initializes the cipher context with the derived key and IV length. Finally, the function returns a pointer to the cipher context.

The function checks for any errors that may occur during initialization of the cipher and prints an error message if one is encountered. It also ensures that the cipher is securely enabled before returning a pointer to it.

2. Theme Caching System for Mobile Application:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define DEFAULT_THEME_DIR "/path/to/default/theme/directory"

struct theme {
    char* name;
    unsigned char* data;
    size_t size;
};

struct theme_cache {
    struct theme* themes[MAX_THEMES]; // MAX_THEMES is a constant representing the maximum number of themes to cache
    int num_themes;
    pthread_mutex_t mutex; // mutex for protecting the cache
};

struct theme_cache* init_theme_cache() {
    struct theme_cache* cache = malloc(sizeof(struct theme_cache));
    if (!cache) {
        fprintf(stderr, "Failed to allocate memory for theme cache\n");
        return NULL;
    }
    memset(cache->themes, 0, sizeof(cache->themes));
    cache->num_themes = 0;
    if (pthread_mutex_init(&cache->mutex, NULL)) {
        fprintf(stderr, "Failed to initialize mutex for theme cache\n");
        return NULL;
    }
    return cache;
}

void cleanup_theme_cache(struct theme_cache* cache) {
    if (pthread_mutex_destroy(&cache->mutex)) {
        fprintf(stderr, "Failed to destroy mutex for theme cache\n");
    }
    free(cache);
}

void add_theme(struct theme_cache* cache, const char* name, unsigned char* data, size_t size) {
    struct theme* theme = malloc(sizeof(struct theme));
    if (!theme) {
        fprintf(stderr, "Failed to allocate memory for new theme\n");
        return;
    }
    theme->name = strdup(name);
    theme->data = data;
    theme->size = size;
    pthread_mutex_lock(&cache->mutex);
    cache->themes[cache->num_themes++] = theme;
    pthread_mutex_unlock(&cache->mutex);
}

struct theme* get_theme(struct theme_cache* cache, const char* name) {
    struct theme* theme = NULL;
    for (int i = 0; i < cache->num_themes; i++) {
        if (!strcmp(cache->themes[i]->name, name)) {
            theme = cache->themes[i];
            break;
        }
    }
    return theme;
}

void* load_theme_from_file(const char* filepath) {
    struct stat sb;
    if (stat(filepath, &sb)) {
        fprintf(stderr, "Failed to get file status: %s\n", strerror(errno));
        return NULL;
    }
    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open theme file for reading: %s\n", strerror(errno));
        return NULL;
    }
    size_t size = sb.st_size;
    unsigned char* data = malloc(size);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for theme file contents\n");
        close(fd);
        return NULL;
    }
    ssize_t nread = read(fd, data, size);
    if (nread < 0) {
        fprintf(stderr, "Failed to read from theme file: %s\n", strerror(errno));
        free(data);
        close(fd);
        return NULL;
    }
    close(fd);
    return data;
}

void* load_theme_from_cache(struct theme_cache* cache, const char* name) {
    struct theme* theme = get_theme(cache, name);
    if (theme) {
        return theme->data;
    }
    unsigned char* data = NULL;
    size_t size = 0;
    const char* filepath = get_theme_filepath(name);
    if (!filepath) {
        fprintf(stderr, "Failed to get theme file path for %s\n", name);
        return NULL;
    }
    data = load_theme_from_file(filepath);
    if (!data) {
        fprintf(stderr, "Failed to load theme file contents from %s\n", filepath);
        return NULL;
    }
    size = strlen((char*)data);
    add_theme(cache, name, data, size);
    return data;
}

void* get_theme_by_name(struct theme_cache* cache, const char* name) {
    unsigned char* data = NULL;
    if (strlen(name) > 0 && strcmp(name, "default")) {
        data = load_theme_from_file(get_theme_filepath(name));
    } else {
        data = load_theme_from_cache(cache, name);
    }
    if (!data) {
        fprintf(stderr, "Failed to load theme %s\n", name);
        return NULL;
    }
    size_t size = strlen((char*)data);
    return data;
}
```
This code provides a caching system for managing themes in a mobile application. The `init_theme_cache()` function initializes the theme cache and returns a pointer to it. The `cleanup_theme_cache()` function cleans up the resources used by the theme cache.

The `add_theme()` function adds a new theme to the cache. It takes in a theme name, a pointer to the theme data, and the size of the theme data as input. The function creates a new `struct theme` object with the given name, data, and size, and then locks the mutex for the theme cache before adding the theme to the cache.

The `get_theme()` function retrieves a theme from the cache based on its name. It takes in the theme cache pointer and the theme name as input. The function searches the cache for the specified theme and returns a pointer to it if found, or NULL otherwise.

The `load_theme_from_file()` function loads a theme file from disk into memory. It takes in a file path as input and returns a pointer to the loaded data, or NULL on failure. The function first gets the file status using the `stat()` system call, then opens the file for reading using the `open()` system call. If successful, it reads the file contents into memory using the `read()` system call, closes the file descriptor, and returns a pointer to the loaded data.

The `load_theme_from_cache()` function loads a theme from the cache based on its name. It takes in the theme cache pointer and the theme name as input. The function first searches the cache for the specified theme using the `get_theme()` function, then returns a pointer to its data if found, or NULL otherwise.

The `get_theme_by_name()` function retrieves a theme from the cache based on its name. It takes in the theme cache pointer and the theme name as input. The function first checks if the theme is already cached using the `get_theme()` function, then loads it from disk into memory using the `load_theme_from_file()` function if not found in the cache. If successful, it returns a pointer to its data, otherwise it returns NULL.

The `struct theme` object contains the theme name, a pointer to the theme data, and the size of the theme data. The `struct theme_cache` object contains an array of `struct theme` objects, the number of themes in the cache, and a mutex for protecting the cache.']

