    if (session->password == NULL || strlen(session->password) == 0) {
        return ERROR_EMPTY_PASSWORD;
    }

    // Confirm that the connection has a valid title set
    if (session->connection.title == NULL) {
        return ERROR_NO_TITLE;
    }

    // Validate that the callback function is not NULL and can handle errors gracefully
