        return ERROR_NULL_CALLBACK;
    }

    // Decoding the Base64-encoded password must be done efficiently to minimize latency during peak usage times
    char* decodedPassword = base64_decode(session->password);

    // Decrypt the password using Triple DES encryption with a given key and IV, ensuring the decryption process does not block other concurrent sessions
    DES_key_schedule schedule;
    des_set_key(&schedule, KEY, sizeof(KEY));
    unsigned char iv[8];
    memcpy(iv, IV, 8);
    int ret = des_cbc_encrypt((const unsigned char*)decodedPassword, (unsigned char*)session->password, strlen(session->password), &schedule, iv, DES_DECRYPT);

    // Check if the decryption process was successful
    if (ret == 0) {
        return ERROR_DECRYPTION;
    }

    // Clean up memory used by the decoded password
    free(decodedPassword);

    // Return the decrypted password along with a success indicator
