using System;
using System.Security.Cryptography;
using System.Text;

public static class AESDecryption
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv = null)
    {
        // Validate input lengths and formats
        if (ciphertext == null || key == null)
            throw new ArgumentException("Invalid input");

        int blockSize = 16; // AES block size in bytes
        int padLength = 32; // PKCS7 padding length in bytes

        // Create a new instance of the AES algorithm with the given key and IV
        using (var aesAlg = new AesCbc(key, iv))
        {
            // Decrypt the ciphertext using the AES algorithm
            var decryptedBytes = aesAlg.Decrypt(ciphertext);

            // Verify the integrity of the decrypted data using a HMAC-SHA256 hash
            using (var hmac = new HMACSHA256(key))
            {
                byte[] expectedHash = hmac.ComputeHash(decryptedBytes);
                if (!expectedHash.SequenceEqual(ciphertext.SkipLast(padLength)))
                    throw new CryptographicException("Decryption failed: HMAC-SHA256 verification failed");
            }

            // Unpad the decrypted data (if necessary)
            int padIndex = decryptedBytes.FindLastIndex(b => b == 0);
            if (padIndex >= 0 && padIndex <= blockSize - 1)
                return decryptedBytes.Take(decryptedBytes.Length - padIndex).ToArray();
            else
                return decryptedBytes;
        }
    }
}
