// Define structure for record
typedef struct {
    int key;
} record_t;

// Function to allocate memory for arrays
void allocate_memory(int num_records, long **offset_array, int **key_array) {
    // Calculate total memory required for records
    size_t total_mem = (size_t)(num_records * sizeof(record_t));

    // Allocate memory for offset array
    *offset_array = malloc(total_mem);
    if (*offset_array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array.\n");
        exit(1);
    }

    // Allocate memory for key array
    *key_array = malloc(total_mem);
    if (*key_array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for key array.\n");
        exit(1);
    }

    // Initialize offset and key arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*offset_array)[i] = (long)(*key_array)[i] * INCREMENT_FACTOR;
        (*key_array)[i] = rand() % MAX_KEY_VALUE;
    }
}

// Function to deallocate memory for arrays
void deallocate_memory(int num_records, long *offset_array, int *key_array) {
    free(offset_array);
    free(key_array);
}

#define INCREMENT_FACTOR 10 // Increment factor for offset values
#define MAX_KEY_VALUE 1000000 // Maximum value for keys

int main() {
    int num_records = 10000000; // Number of records to generate
    long *offset_array; // Pointer to offset array
    int *key_array; // Pointer to key array

    allocate_memory(num_records, &offset_array, &key_array);

    for (int i = 0; i < num_records; i++) {
        printf("Record %d: offset=%ld, key=%d\n", i, offset_array[i], key_array[i]);
    }

    deallocate_memory(num_records, offset_array, key_array);

    return 0;
}
