import json
from abc import ABC, abstractmethod

class JSONSerializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @abstractmethod
    def from_json(self, json_string: str):
        pass

class Registry:
    _registry = {}

    @staticmethod
    def add_factory(id: str, factory):
        if id in Registry._registry:
            raise ValueError("ID already exists in registry")
        Registry._registry[id] = factory

    @staticmethod
    def get_factory(id: str) -> Callable[[], JSONSerializable]:
        if id not in Registry._registry:
            raise ValueError("ID does not exist in registry")
        return Registry._registry[id]

class JSONSerializer:
    def to_json(self, instance):
        # Use the instance's type to determine which factory function to use
        factory = self.get_factory(type(instance))
        json_string = factory().to_json()
        return json_string

    def from_json(self, json_string: str):
        # Use the JSON string to determine which subclass to instantiate
        data = json.loads(json_string)
        id = data["type"]
        factory = self.get_factory(id)
        instance = factory().from_json(json_string)
        return instance

class MyClass(JSONSerializable):
    def __init__(self, field1: str, field2: int):
        self.field1 = field1
        self.field2 = field2

    def to_json(self) -> str:
        data = {
            "type": "MyClass",
            "field1": self.field1,
            "field2": self.field2
        }
        return json.dumps(data)

    @staticmethod
    def from_json(json_string: str):
        data = json.loads(json_string)
        field1 = data["field1"]
        field2 = data["field2"]
        instance = MyClass(field1, field2)
        return instance

# Add a factory function for the subclass to the registry
Registry.add_factory("MyClass", lambda: MyClass)

# Use the serializer to convert an instance of the class to a JSON string
serializer = JSONSerializer()
my_instance = MyClass("hello", 123)
json_string = serializer.to_json(my_instance)
print(json_string)

# Use the serializer to create a new instance of the subclass from a JSON string
new_instance = serializer.from_json(json_string)
print(new_instance)']

