record_arrays allocate_records(int num_records, int record_size) {
    // Calculate the total size of the arrays based on the number of records and record size
    int total_size = num_records * (sizeof(long) + sizeof(int));

    // Check if the total size exceeds the memory usage limit
    if (total_size > MEMORY_USAGE_LIMIT) {
        fprintf(stderr, "Memory usage limit exceeded.\n");
        return NULL;
    }

    // Allocate memory for the arrays of offset values and keys
