    int* keys = (int*) malloc(total_size);

    // Initialize the arrays with default values
    memset(offsets, 0, total_size);
    memset(keys, 0, total_size);

    return (record_arrays){ offsets, keys };
}

// Define a function to deallocate memory for an array of records
void deallocate_records(record_arrays* arrays) {
    // Check if the arrays are valid
    if (!arrays || !arrays->offsets || !arrays->keys) return;

    // Deallocate memory for the arrays of offset values and keys
    free(arrays->offsets);
    free(arrays->keys);
}

