    // Initialize a variable to store the largest integer found so far
    int largest = INT_MIN;

    // Iterate over the arrays and find the largest integer
    for (int i = 0; i < arrays->num_records; ++i) {
        if (arrays->keys[i] > largest) {
            largest = arrays->keys[i];
        }
    }

    return largest;
}

// Define a function to handle failed requests and retry them a limited number of times
