// Define error codes and status flags
#define ERROR_OUT_OF_MEMORY -1
#define ERROR_TIMEOUT -2
#define STATUS_SUCCESS 0

int init_data(int n, int max_memory_kb, int max_time_ms, int min_val, int max_val, int max_sum) {
    // Allocate memory for the offset and key arrays
    long* offsets = malloc(n * sizeof(long));
    int* keys = malloc(n * sizeof(int));
    struct record* records = malloc(n * sizeof(struct record));
    if (offsets == NULL || keys == NULL || records == NULL) {
        free_data(offsets, keys, records);
        return ERROR_OUT_OF_MEMORY;
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % max_memory_kb * 1024;
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
    }

    // Allocate memory for the records array and initialize it with random values within the specified range
    struct record* records = malloc(n * sizeof(struct record));
    if (records == NULL) {
        free_data(offsets, keys, records);
        return ERROR_OUT_OF_MEMORY;
    }
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    // Validate the sum of all offsets does not exceed the maximum sum threshold
    long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += offsets[i];
    }
    if (sum > max_sum) {
        // Adjust the values by incrementing them uniformly until the condition is met, while minimizing the impact on overall system performance
        int count = 0;
        while (sum > max_sum && count < n) {
            offsets[count]++;
            sum--;
            count++;
        }
    }

    // Create a compressed data structure that minimizes memory usage by removing any zero values from the keys array
    int* keys_compressed = malloc(n * sizeof(int));
    if (keys_compressed == NULL) {
        free_data(offsets, keys, records);
        return ERROR_OUT_OF_MEMORY;
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (keys[i] != 0) {
            keys_compressed[count++] = keys[i];
        }
    }

    // Copy the contents of the offset and key arrays into the compressed data structure
    struct compressed_data* data = malloc(sizeof(struct compressed_data));
    if (data == NULL) {
        free_data(offsets, keys, records);
        return ERROR_OUT_OF_MEMORY;
    }
    data->offsets = offsets;
    data->keys = keys_compressed;
    data->records = records;

    // Return the compressed data structure along with a pointer to the initialized records array
    return STATUS_SUCCESS;
}

void free_data(struct compressed_data* data) {
    if (data != NULL) {
        free(data->offsets);
        free(data->keys);
        free(data->records);
        free(data);
    }
}
