// Enum for different encryption algorithms
enum class EncryptionAlgorithm {
  AES_128,
  AES_256,
  ChaCha20
};

// Enum for different modes of operation
enum class Mode {
  CBC,
  GCM,
  CTR
};

// Struct for storing encryption parameters
struct EncryptionParameters {
  EncryptionAlgorithm algorithm; // Algorithm used for encryption
  Mode mode;                     // Mode of operation
  int keySize;                   // Size of the encryption key (in bits)
  std::string initializationVector; // Initialization vector for CBC and GCM modes
};

// Class for generating random numbers using OpenSSL's RAND_bytes function
class RandomNumberGenerator {
public:
  // Generate a random number between min and max inclusive
  static int generateRandomNumber(int min, int max) {
    std::vector<unsigned char> buf(sizeof(int));
    RAND_bytes(buf.data(), sizeof(int));
    return *reinterpret_cast<int*>(buf.data()) % (max - min + 1) + min;
  }
};

// Class for encryption and decryption using OpenSSL's AES, ChaCha20, and GCM functions
class Encryption {
public:
  // Constructor that initializes the encryption parameters
  Encryption(const EncryptionParameters& params) : params_(params) {}

  // Encrypt data using the specified mode of operation
  std::string encrypt(const std::string& data, const std::string& initializationVector) {
    switch (params_.algorithm) {
      case EncryptionAlgorithm::AES_128:
        return AES_encrypt(data, initializationVector, params_.keySize);
      case EncryptionAlgorithm::AES_256:
        return AES_encrypt(data, initializationVector, params_.keySize);
      case EncryptionAlgorithm::ChaCha20:
        return ChaCha20_encrypt(data, initializationVector, params_.keySize);
    }
  }

  // Decrypt data using the specified mode of operation
  std::string decrypt(const std::string& data, const std::string& initializationVector) {
    switch (params_.algorithm) {
      case EncryptionAlgorithm::AES_128:
        return AES_decrypt(data, initializationVector, params_.keySize);
      case EncryptionAlgorithm::AES_256:
        return AES_decrypt(data, initializationVector, params_.keySize);
      case EncryptionAlgorithm::ChaCha20:
        return ChaCha20_decrypt(data, initializationVector, params_.keySize);
    }
  }

private:
  // Function for encrypting data using AES-128/256 with CBC or GCM mode of operation
  std::string AES_encrypt(const std::string& data, const std::string& initializationVector, int keySize) {
    // Initialize the AES context and set the encryption parameters
    AES_KEY ctx;
    if (keySize == 128) {
      AES_set_encrypt_key(data.c_str(), 128, &ctx);
    } else {
      AES_set_encrypt_key(data.c_str(), 256, &ctx);
    }

    // Set the initialization vector for CBC and GCM modes of operation
    std::string iv = initializationVector;
    if (params_.mode == Mode::CBC) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 255);
    } else if (params_.mode == Mode::GCM) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 65535);
    }

    // Encrypt the data using AES-128/256 with the specified mode of operation
    std::string encryptedData;
    if (params_.mode == Mode::CBC) {
      encryptedData = CBC_encrypt(data, iv, &ctx);
    } else if (params_.mode == Mode::GCM) {
      encryptedData = GCM_encrypt(data, iv, &ctx);
    }

    // Return the encrypted data
    return encryptedData;
  }

  // Function for decrypting data using AES-128/256 with CBC or GCM mode of operation
  std::string AES_decrypt(const std::string& data, const std::string& initializationVector, int keySize) {
    // Initialize the AES context and set the decryption parameters
    AES_KEY ctx;
    if (keySize == 128) {
      AES_set_decrypt_key(data.c_str(), 128, &ctx);
    } else {
      AES_set_decrypt_key(data.c_str(), 256, &ctx);
    }

    // Set the initialization vector for CBC and GCM modes of operation
    std::string iv = initializationVector;
    if (params_.mode == Mode::CBC) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 255);
    } else if (params_.mode == Mode::GCM) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 65535);
    }

    // Decrypt the data using AES-128/256 with the specified mode of operation
    std::string decryptedData;
    if (params_.mode == Mode::CBC) {
      decryptedData = CBC_decrypt(data, iv, &ctx);
    } else if (params_.mode == Mode::GCM) {
      decryptedData = GCM_decrypt(data, iv, &ctx);
    }

    // Return the decrypted data
    return decryptedData;
  }

  // Function for encrypting data using ChaCha20 with CBC or GCM mode of operation
  std::string ChaCha20_encrypt(const std::string& data, const std::string& initializationVector, int keySize) {
    // Initialize the ChaCha20 context and set the encryption parameters
    ChaCha20_ctx ctx;
    if (keySize == 128) {
      ChaCha20_set_encrypt_key(data.c_str(), 128, &ctx);
    } else {
      ChaCha20_set_encrypt_key(data.c_str(), 256, &ctx);
    }

    // Set the initialization vector for CBC and GCM modes of operation
    std::string iv = initializationVector;
    if (params_.mode == Mode::CBC) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 255);
    } else if (params_.mode == Mode::GCM) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 65535);
    }

    // Encrypt the data using ChaCha20 with the specified mode of operation
    std::string encryptedData;
    if (params_.mode == Mode::CBC) {
      encryptedData = CBC_encrypt(data, iv, &ctx);
    } else if (params_.mode == Mode::GCM) {
      encryptedData = GCM_encrypt(data, iv, &ctx);
    }

    // Return the encrypted data
    return encryptedData;
  }

  // Function for decrypting data using ChaCha20 with CBC or GCM mode of operation
  std::string ChaCha20_decrypt(const std::string& data, const std::string& initializationVector, int keySize) {
    // Initialize the ChaCha20 context and set the decryption parameters
    ChaCha20_ctx ctx;
    if (keySize == 128) {
      ChaCha20_set_decrypt_key(data.c_str(), 128, &ctx);
    } else {
      ChaCha20_set_decrypt_key(data.c_str(), 256, &ctx);
    }

    // Set the initialization vector for CBC and GCM modes of operation
    std::string iv = initializationVector;
    if (params_.mode == Mode::CBC) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 255);
    } else if (params_.mode == Mode::GCM) {
      iv = iv + RandomNumberGenerator::generateRandomNumber(0, 65535);
    }

    // Decrypt the data using ChaCha20 with the specified mode of operation
    std::string decryptedData;
    if (params_.mode == Mode::CBC) {
      decryptedData = CBC_decrypt(data, iv, &ctx);
    } else if (params_.mode == Mode::GCM) {
      decryptedData = GCM_decrypt(data, iv, &ctx);
    }

    // Return the decrypted data
    return decryptedData;
  }
};

// Class for generating HMAC signatures using OpenSSL's HMAC function
class HMAC {
public:
  // Constructor that initializes the HMAC key
  HMAC(const std::string& hmacKey) : hmacKey_(hmacKey) {}

  // Generate a HMAC signature for the given data using the specified algorithm and digest size
  std::string generateHMACSignature(const std::string& data, const std::string& algorithm = "SHA-256", int digestSize = 32) {
    // Initialize the HMAC context and set the encryption parameters
    HMAC_CTX ctx;
    if (algorithm == "SHA-1") {
      HMAC_Init_ex(&ctx, hmacKey_.c_str(), hmacKey_.size(), EVP_sha1(), NULL);
    } else if (algorithm == "SHA-256") {
      HMAC_Init_ex(&ctx, hmacKey_.c_str(), hmacKey_.size(), EVP_sha256(), NULL);
    } else if (algorithm == "SHA-384") {
      HMAC_Init_ex(&ctx, hmacKey_.c_str(), hmacKey_.size(), EVP_sha384(), NULL);
    } else if (algorithm == "SHA-512") {
      HMAC_Init_ex(&ctx, hmacKey_.c_str(), hmacKey_.size(), EVP_sha512(), NULL);
    }

    // Set the digest size and generate the HMAC signature
    HMAC_CTX_set_flags(&ctx, EVP_MD_CTX_FLAG_DIGEST_SIZE_BITS);
    HMAC_Update(&ctx, data.c_str(), data.size());
    unsigned char* digest = new unsigned char[digestSize];
    int length = 0;
    HMAC_Final(&ctx, digest, &length);
    std::string signature(reinterpret_cast<char*>(digest), length);

    // Clean up the HMAC context and return the generated signature
    delete[] digest;
    HMAC_CTX_cleanup(&ctx);
    return signature;
  }

private:
  std::string hmacKey_; // HMAC key used for generating signatures
};

// Class for handling encryption and decryption of data with seamless integration with existing logging and monitoring systems, enabling comprehensive performance tracking and debugging.
class EncryptionHandler {
public:
  // Constructor that initializes the encryption parameters from a configuration file at runtime
  EncryptionHandler(const std::string& configFile) : params_(configFile) {}

  // Encrypt data using the specified encryption algorithm and mode of operation, with HMAC signature generation for message integrity checks
  std::string encrypt(const std::string& data) {
    // Initialize the encryption context and set the encryption parameters
    std::unique_ptr<Encryption> enc = std::make_unique<Encryption>(params_);

    // Generate a random initialization vector for CBC and GCM modes of operation
    if (params_.mode == Mode::CBC || params_.mode == Mode::GCM) {
      std::string iv = RandomNumberGenerator::generateRandomNumber(0, 255);
      enc->setInitializationVector(iv);
    }

    // Encrypt the data using the specified encryption algorithm and mode of operation
    std::string encryptedData = enc->encrypt(data);

    // Generate a HMAC signature for the encrypted data
    std::unique_ptr<HMAC> hmac = std::make_unique<HMAC>(params_.hmacKey);
    std::string signature = hmac->generateHMACSignature(encryptedData);

    // Return the encrypted data with HMAC signature
    return encryptedData + signature;
  }

  // Decrypt data using the specified encryption algorithm and mode of operation, with HMAC signature validation for message integrity checks
  std::string decrypt(const std::string& data) {
    // Initialize the encryption context and set the encryption parameters
    std::unique_ptr<Encryption> enc = std::make_unique<Encryption>(params_);

    // Validate the HMAC signature for the encrypted data
    if (data.size() > params_.hmacKey.size()) {
      std::string hmacSignature = data.substr(data.size() - params_.hmacKey.size());
      std::unique_ptr<HMAC> hmac = std::make_unique<HMAC>(params_.hmacKey);
      if (hmac->validateHMACSignature(encryptedData, hmacSignature)) {
        return encryptedData;
      } else {
        // Return an error message if the HMAC signature is invalid
        return "Invalid HMAC signature";
      }
    } else {
      return "Invalid data format";
    }
  }

private:
  EncryptionParameters params_; // Encryption parameters for the specified encryption algorithm and mode of operation
};

int main() {
  std::string configFile = "/path/to/config.json"; // Path to the configuration file
  std::unique_ptr<EncryptionHandler> handler = std::make_unique<EncryptionHandler>(configFile);

  // Encrypt data using the specified encryption algorithm and mode of operation, with HMAC signature generation for message integrity checks
  std::string encryptedData = handler->encrypt("Hello, World!");

  // Decrypt data using the specified encryption algorithm and mode of operation, with HMAC signature validation for message integrity checks
  std::string decryptedData = handler->decrypt(encryptedData);

  return 0;
}
```
