// Semaphore Management Library - C Implementation

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Metadata Structure for Each Semaphore
struct semaphore_metadata {
    char name[256]; // Unique Name of the Semaphore
    int value; // Initial Value of the Semaphore
    pid_t owner_pid; // Process ID of the Owner
    time_t last_accessed; // Timestamp of Last Access
    size_t usage_count; // Number of Times Acquired
};

// Global List of All Semaphores
struct semaphore {
    char name[256];
    int value;
    struct semaphore_metadata metadata;
} *semaphores = NULL;
size_t num_semaphores = 0;
pthread_mutex_t semaphores_lock = PTHREAD_MUTEX_INITIALIZER;

// Creates a New Semaphore
int create_semaphore(const char *name, int initial_value) {
    if (get_semaphore_by_name(name)) {
        return -1; // Semaphore with same name already exists
    }

    struct semaphore new_semaphore = {};
    strncpy(new_semaphore.name, name, 256);
    new_semaphore.value = initial_value;

    pthread_mutex_lock(&semaphores_lock);
    semaphores[num_semaphores++] = new_semaphore;
    pthread_mutex_unlock(&semaphores_lock);

    return 0; // Successfully created the semaphore
}

// Retrieves a Semaphore by Name
struct semaphore *get_semaphore_by_name(const char *name) {
    for (size_t i = 0; i < num_semaphores; i++) {
        if (!strcmp(semaphores[i].name, name)) {
            return &semaphores[i];
        }
    }
    return NULL; // Semaphore not found
}

// Acquires a Semaphore by Name
int acquire_semaphore(const char *name) {
    struct semaphore *semaphore = get_semaphore_by_name(name);
    if (!semaphore) {
        return -1; // Semaphore not found
    }

    pthread_mutex_lock(&semaphores_lock);
    semaphore->metadata.usage_count++;
    pthread_mutex_unlock(&semaphores_lock);

    return 0; // Successfully acquired the semaphore
}

// Releases a Semaphore by Name
int release_semaphore(const char *name) {
    struct semaphore *semaphore = get_semaphore_by_name(name);
    if (!semaphore) {
        return -1; // Semaphore not found
    }

    pthread_mutex_lock(&semaphores_lock);
    semaphore->metadata.usage_count--;
    pthread_mutex_unlock(&semaphores_lock);

    return 0; // Successfully released the semaphore
}

// Deletes a Semaphore by Name
int delete_semaphore(const char *name) {
    struct semaphore *semaphore = get_semaphore_by_name(name);
    if (!semaphore) {
        return -1; // Semaphore not found
    }

    pthread_mutex_lock(&semaphores_lock);
    size_t index = 0;
    while (index < num_semaphores && strcmp(semaphores[index].name, name)) {
        index++;
    }
    if (index == num_semaphores) {
        pthread_mutex_unlock(&semaphores_lock);
        return -1; // Semaphore not found
    }

    semaphores[index] = semaphores[--num_semaphores];
    pthread_mutex_unlock(&semaphores_lock);

    return 0; // Successfully deleted the semaphore
}

// Main Function for Testing
int main() {
    create_semaphore("semaphore1", 10);
    create_semaphore("semaphore2", 5);
    acquire_semaphore("semaphore1");
    acquire_semaphore("semaphore2");
    release_semaphore("semaphore1");
    delete_semaphore("semaphore2");

    return 0;
}']

