import java.util.Arrays;
import java.util.concurrent.TimeUnit;
import java.security.MessageDigest;

public class DisjointPairs {
    public static void main(String[] args) {
        int[] arr = new int[] {1, 2, 3, 4, 5, 6};
        System.out.println("Number of disjoint pairs: " + findDisjointPairs(arr));
    }

    private static int findDisjointPairs(int[] arr) {
        // Initialize a Union-Find data structure with the number of elements in the array
        UnionFind uf = new UnionFind(arr.length);

        // Iterate through the array and union the pairs that are not disjoint
        for (int i = 0; i < arr.length - 1; i++) {
            if (!uf.isDisjoint(i, i + 1)) {
                uf.union(i, i + 1);
            }
        }

        // Return the number of disjoint pairs
        return uf.numDisjoint();
    }
}

class UnionFind {
    private int[] parent;
    private int[] rank;
    private int numElements;

    public UnionFind(int n) {
        this.parent = new int[n];
        this.rank = new int[n];
        this.numElements = n;

        // Initialize each element as its own parent and of rank 0
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        // Find the root element of the tree that x belongs to
        while (x != parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    public void union(int x, int y) {
        // Union the trees that x and y belong to
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        // Rank is used to determine which tree is "larger"
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootX] = rootY;
        }
    }

    public boolean isDisjoint(int x, int y) {
        // Check if the trees that x and y belong to are disjoint (i.e., they have no common elements)
        return find(x) != find(y);
    }

    public int numDisjoint() {
        // Return the number of disjoint pairs in the array
        int count = 0;
        for (int i = 0; i < parent.length; i++) {
            if (!isDisjoint(i, i + 1)) {
                count++;
            }
        }
        return count;
    }
}
