            replica_bitmap[i][added_replica] = true;
            dht->addReplica(i, added_replica);
        }
    }

    // Implement dynamic node addition and removal mechanisms to minimize contention and maximize throughput
    const int node_count_limit = 0.5 * (dht->getNodeCount() + tolerance);
    while (dht->getNodeCount() > node_count_limit) {
        // Find the most overloaded node
        int overloaded_node = -1;
        for (int i = 0; i < dht->getNodeCount(); ++i) {
            if (node_load[i] > node_load_limit) {
                overloaded_node = i;
                break;
            }
        }

        // Remove some replicas from the overloaded node to balance the load
        while (overloaded_node != -1 && node_load[overloaded_node] > node_load_limit) {
            int max_replica = -1;
            for (int j = 0; j < dht->getKeyCapacity(); ++j) {
