        if (added_node != -1) {
            node_bitmap[added_node] = true;
            dht->addNode(added_node);
        }
    }

    // Ensure system stability by tolerating a predefined number of simultaneous node failures without degradation
    const int failure_tolerance = 0.5 * (dht->getNodeCount() + tolerance);
    while (dht->getFailureCount() > failure_tolerance) {
        // Find the most overloaded node
        int overloaded_node = -1;
        for (int i = 0; i < dht->getNodeCount(); ++i) {
            if (node_load[i] > node_load_limit) {
