            }

            // Remove the most overloaded replica from the overloaded node
            int removed_replica = max_replica;
            replica_bitmap[overloaded_node][removed_replica] = false;
            dht->removeReplica(overloaded_node, removed_replica);
        }

        // Remove a node from the system
        if (dht->getNodeCount() > failure_tolerance) {
            int failed_node = -1;
            for (int i = 0; i < dht->getNodeCount(); ++i) {
                if (!node_bitmap[i]) {
