            }

            // Remove a node from the system
            if (failed_node != -1) {
                node_bitmap[failed_node] = false;
                dht->removeNode(failed_node);
            }
        }
    }

    // Balance memory usage between data arrays and metadata structures while maintaining performance benchmarks
    const int mem_limit = 0.5 * (dht->getTotalMemory() - tolerance);
    while (dht->getUsedMemory() > mem_limit) {
        // Find the node with the highest load
        int max_load = -1;
        for (int i = 0; i < dht->getNodeCount(); ++i) {
            if (node_load[i] > max_load) {
