            int max_replica = -1;
            for (int j = 0; j < dht->getKeyCapacity(); ++j) {
                if (replica_bitmap[max_load][j]) {
                    if (max_replica == -1 || replica_count[max_load][j] > max_replica) {
                        max_replica = j;
                    }
                }
            }

            // Remove the most overloaded replica from the most loaded node
            int removed_replica = max_replica;
            replica_bitmap[max_load][removed_replica] = false;
            dht->removeReplica(max_load, removed_replica);
        }
    }

    // Handle network latency and bandwidth constraints effectively, minimizing the impact on data consistency and availability
    const int network_latency = 0.5 * (dht->getNetworkLatency() - tolerance);
    while (dht->getAverageLatency() > network_latency) {
        // Find the node with the highest load
