using System;
using System.Net.Http;
using System.Threading;

public class DynamicRangeRandomGenerator
{
    private int _minValue;
    private int _maxValue;
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly Random _random = new Random();

    public DynamicRangeRandomGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");
        }

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public DynamicRangeRandomGenerator() : this(Constants.DEFAULT_MIN_VALUE, Constants.DEFAULT_MAX_VALUE) { }

    private int GenerateRandomIntegerInternal(bool inclusiveMin, bool inclusiveMax)
    {
        if (inclusiveMin && inclusiveMax)
        {
            return _random.Next(_minValue, _maxValue + 1);
        }
        else if (!inclusiveMin && !inclusiveMax)
        {
            return _random.Next(_minValue + 1, _maxValue);
        }
        else if (inclusiveMin && !inclusiveMax)
        {
            return _random.Next(_minValue, _maxValue);
        }
        else // (!inclusiveMin && inclusiveMax)
        {
            return _random.Next(_minValue + 1, _maxValue + 1);
        }
    }

    public int GenerateRandomInteger(bool inclusiveMin = false, bool inclusiveMax = true) => GenerateRandomIntegerInternal(inclusiveMin, inclusiveMax);

    public float GenerateRandomFloat()
    {
        return (float)(_random.NextDouble() * (_maxValue - _minValue)) + _minValue;
    }

    public void UpdateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");
        }

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void ResetRange()
    {
        _minValue = Constants.DEFAULT_MIN_VALUE;
        _maxValue = Constants.DEFAULT_MAX_VALUE;
    }

    public override string ToString()
    {
        return $"Current range: [{_minValue}, {_maxValue}]";
    }
}
