// Function to validate and process user input
void processInput(float* array, int* capacity) {
    // Initialize an empty array of maximum capacity 500
    *capacity = 500;
    array = (float*)malloc(*capacity * sizeof(float));

    // Read input from standard input until the user enters "done"
    char line[1024];
    int index = 0;
    while (fgets(line, sizeof(line), stdin) != NULL && strcmp(line, "done\n") != 0) {
        float inputValue = atof(line);

        // Validate the input value is within a specified range
        if (inputValue >= -100.0f && inputValue <= 100.0f) {
            array[index] = inputValue;
            index++;
        } else {
            printf("Invalid input value: %f\n", inputValue);
        }
    }

    // If the array is empty, print a message indicating so
    if (index == 0) {
        printf("No valid inputs were entered\n");
        return;
    }

    // Sort the array in descending order without using any additional data structures
    for (int i = 0; i < index - 1; i++) {
        for (int j = i + 1; j < index; j++) {
            if (array[i] < array[j]) {
                float temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }

    // Find and print the average of the numbers in the array
    float sum = 0.0f;
    for (int i = 0; i < index; i++) {
        sum += array[i];
    }
    printf("Average: %f\n", sum / index);
