  for (let i = 0; i < recordArray.length; i++) {
    const intValue = getRandomInt(10, 100);
    recordArray[i].intField = intValue;
  }

  // Loop through the test labels and run each test
  for (const label of testLabels) {
    // Reset the mocking library after each test
    blueslip.reset();

    console.log(`Running ${moduleName} tests with ${label}`);

    const startTime = Date.now();
    module[label](longOffsetArray, intKeyArray, recordArray);
    const endTime = Date.now();

    // Log the test results to the console
    console.log(`${moduleName} tests with ${label} completed in ${endTime - startTime} milliseconds`);
