  unsigned char iv[16];
} aes256cbc_ctx;

// Define the password validation schema
const char *password_validation = "^(?=.*[0-9])(?=.*[a-zA-Z]).{16,}$";

// Function to initialize AES-256-CBC cipher using a given password
aes256cbc_ctx* init_aes256cbc(const char *password) {
  // Check if the password meets the validation criteria
  if (strlen(password) < 16 || !regexec(password_validation, password)) {
    fprintf(stderr, "Error: Invalid password. Must be at least 16 characters long and contain a mix of letters and numbers.\n");
    return NULL;
  }

  // Derive the encryption key and IV from the password using OpenSSL
  unsigned char derived_key[32], derived_iv[16];
  EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), key_length, iv, NULL);

  // Generate a new IV each time the function is called using a secure random number generator
  unsigned char *iv_ptr = malloc(16);
  RAND_bytes(iv_ptr, 16);

  // Store the salt securely alongside the password
  const char *salt = "ThisIsASecureSalt";

  // Initialize the AES-256-CBC cipher using the derived key and IV
  aes256cbc_ctx *ctx = malloc(sizeof(aes256cbc_ctx));
  AES_set_encrypt_key(derived_key, 256, &ctx->key);
  memcpy(ctx->iv, iv_ptr, 16);

  // Cleanup function to properly disable the cipher and free all resources when it is no longer needed
  void cleanup_aes256cbc(aes256cbc_ctx *ctx) {
    AES_free((void*)&ctx->key);
    free(iv_ptr);
  }

  return ctx;
}
