// Structure for metadata
typedef struct {
    time_t timestamp;
    int status;
    void* record;
} metadata;

// Function to allocate memory for arrays and initialize records
void* allocate_memory(int num_records, int offset_factor) {
    // Calculate the total size of memory required for all arrays
    long buffer_size = sizeof(long) * num_records;
    buffer_size += sizeof(int) * num_records;
    buffer_size += sizeof(char) * (num_records * 10); // Assumes each record name is at most 10 characters long
    buffer_size += sizeof(record) * num_records;

    // Allocate memory for arrays
    void* memory = malloc(buffer_size);
    if (memory == NULL) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize offset values based on key
    long* offsets = memory;
    int* keys = (int*)((char*)offsets + num_records * sizeof(long));
    char* buffer_names = (char*)keys + num_records * sizeof(int);
    record* records = (record*)buffer_names + num_records * 10; // Assumes each record name is at most 10 characters long

    for (int i = 0; i < num_records; i++) {
        offsets[i] = keys[i] * offset_factor;
        records[i].value = rand() % 100; // Randomly generate value within range
    }

    // Initialize metadata structures and link them to records
    metadata* metadatas = malloc(num_records * sizeof(metadata));
    if (metadatas == NULL) {
        printf("Error: Failed to allocate memory for metadata\n");
        free(memory);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        metadatas[i].timestamp = time(NULL);
        metadatas[i].status = 1; // Set status to 1
        metadatas[i].record = &records[i];
    }

    return memory;
}

// Function to deallocate memory allocated by allocate_memory()
void deallocate_memory(void* memory) {
    free(memory);
}
```
