  int64_t offset;       // Long offset value derived from key using formula
  time_t timestamp;     // Timestamp indicating last updated
};

// Define the database as an array of records
struct Record* database = NULL;
size_t num_records = 0;
size_t max_records = 10000000;

// Function to insert a new record into the database
void insert_record(uint32_t key, int64_t offset) {
  // Check if the database is full
  if (num_records == max_records) {
    // Double the size of the database if it's full
    struct Record* new_database = realloc(database, sizeof(struct Record) * max_records * 2);
    if (!new_database) {
      printf("Error: Out of memory!\n");
      exit(1);
    }
    database = new_database;
    max_records *= 2;
  }

  // Insert the new record into the database
  struct Record* record = &database[num_records];
  record->key = key;
  record->offset = offset;
  record->timestamp = time(NULL);
  num_records++;
}

// Function to retrieve a record from the database
struct Record* get_record(uint32_t key) {
  // Search for the record in the database
  for (size_t i = 0; i < num_records; i++) {
    if (database[i].key == key) {
      return &database[i];
    }
  }

  // If the record is not found, return NULL
  return NULL;
}

// Function to update a record in the database
void update_record(uint32_t key, int64_t offset) {
  // Search for the record in the database
  struct Record* record = get_record(key);
  if (record != NULL) {
    record->offset = offset;
    record->timestamp = time(NULL);
  } else {
    printf("Error: Record not found!\n");
  }
}

// Function to print all records in the database
void print_records() {
  // Iterate over each record in the database and print its key, offset, and timestamp
  for (size_t i = 0; i < num_records; i++) {
    printf("Record %d: key=%d, offset=%ld, timestamp=%ld\n", i + 1, database[i].key, database[i].offset, database[i].timestamp);
  }
}
```
