    FILE* output = popen(commandLine, "r");
    if (!output) {
        free(records);
        return -1;
    }

    // Capture and return the standard output and error streams
    char buffer[BUFSIZ];
    int status = 0;
    while (fgets(buffer, BUFSIZ, output)) {
        printf("%s", buffer);
    }
    if (!feof(output)) {
        fprintf(stderr, "Error: %d\n", errno);
        status = -1;
    }
    pclose(output);

    // Verify the successful completion of the external process and handle any exceptions gracefully
    if (status != 0) {
        free(records);
        return -1;
    }

    // Free dynamically allocated memory to prevent leaks
    free(records);
    return status;
}
