#include <stdio.h>
#include <syslog.h>

// Define log levels
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3
#define CRITICAL 4

// Structure to represent a log entry
struct LogEntry {
    char message[512];
    int level;
};

// Structure to represent the logger class
typedef struct {
    // Array of log entries
    struct LogEntry *entries;

    // Number of log entries in the array
    size_t num_entries;

    // Buffer size for storing logs before sending them to the remote server
    size_t buffer_size;

    // Flag to indicate if logs should be flushed to the remote server
    bool flush_logs;
} Logger;

// Function to initialize the logger class
Logger *init_logger(size_t buffer_size) {
    // Allocate memory for the log entries array
    struct LogEntry *entries = (struct LogEntry *)malloc(buffer_size * sizeof(struct LogEntry));

    // Check if memory allocation was successful
    if (!entries) {
        printf("Error: Failed to allocate memory for log entries.\n");
        return NULL;
    }

    // Initialize the logger class
    Logger *logger = (Logger *)malloc(sizeof(Logger));
    logger->entries = entries;
    logger->num_entries = 0;
    logger->buffer_size = buffer_size;
    logger->flush_logs = false;

    return logger;
}

// Function to add a log entry to the logger class
void add_log_entry(Logger *logger, const char *message, int level) {
    // Check if the logger is initialized
    if (!logger) {
        printf("Error: Logger not initialized.\n");
        return;
    }

    // Check if the log entry is within the buffer size
    if (logger->num_entries >= logger->buffer_size) {
        printf("Warning: Log entry exceeds buffer size, dropping oldest entry.\n");
        memmove(logger->entries, &logger->entries[1], (logger->num_entries - 1) * sizeof(struct LogEntry));
        --logger->num_entries;
    }

    // Add the log entry to the array
    logger->entries[logger->num_entries].message = message;
    logger->entries[logger->num_entries].level = level;
    ++logger->num_entries;
}

// Function to flush logs to a remote server
void flush_logs(Logger *logger) {
    // Check if the logger is initialized and flushing is enabled
    if (!logger || !logger->flush_logs) {
        return;
    }

    // Iterate over the log entries and send them to the remote server
    for (int i = 0; i < logger->num_entries; ++i) {
        // Check if the log entry is within the buffer size
        if (i >= logger->buffer_size) {
            printf("Warning: Log entry exceeds buffer size, dropping oldest entry.\n");
            memmove(logger->entries, &logger->entries[1], (logger->num_entries - 1) * sizeof(struct LogEntry));
            --logger->num_entries;
        }

        // Send the log entry to the remote server
        syslog(LOG_INFO, "%s", logger->entries[i].message);
    }

    // Reset the number of log entries
    logger->num_entries = 0;
}

// Function to free the memory allocated for the logger class
void free_logger(Logger *logger) {
    // Check if the logger is initialized
    if (!logger) {
        return;
    }

    // Free the memory allocated for the log entries array
    free(logger->entries);

    // Free the memory allocated for the logger class
    free(logger);
}
```
This code defines a `Logger` class that allows you to add log entries with different levels (DEBUG, INFO, WARNING, ERROR, CRITICAL) and log rotation policies. The `init_logger()` function initializes the logger class with a specified buffer size for storing logs before sending them to the remote server. The `add_log_entry()` function adds a new log entry to the logger class, while the `flush_logs()` function sends all the log entries stored in the logger class to the remote server. Finally, the `free_logger()` function frees the memory allocated for the logger class.

The `Logger` class also supports asynchronous logging, which can improve application responsiveness by not blocking the main thread while sending logs to the remote server. However, this also introduces complexity in managing log sequence and timestamps accurately. You must decide on an appropriate buffer size for storing logs before sending them to the remote server, balancing between memory usage and the risk of losing important log entries.

You should also consider the scalability of your solution, especially as the number of concurrent users and log entries increases. You may need to adjust the buffer size or add additional features to handle large amounts of data.']

