NFAPI_CRC_INDICATION_PDU_T *generateAndQueryNfapiIndications(int supervisorID) {
  // Initialize the NFAPI indication PDU list
  NFAPI_CRC_INDICATION_PDU_T *indications = NULL;

  // Retrieve employee names, cities, and addresses from the 'Employees' table where the supervisor's ID matches the provided parameter
  char *query = "SELECT * FROM Employees WHERE SupervisorID = ?";
  sqlite3_stmt *statement = prepareStatement(query);
  bindIntegerParameter(statement, 1, supervisorID);
  executeQuery(statement);
  int numRows = getNumRows(statement);

  // Allocate memory for the NFAPI indication PDUs and populate them with the retrieved data
  indications = malloc(numRows * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  for (int i = 0; i < numRows; i++) {
    getRow(statement);
    NFAPI_CRC_INDICATION_PDU_T *indication = &indications[i];
    indication->RX_UE_INFORMATION_TAG.SFN = 0x1234;
    indication->RX_UE_INFORMATION_TAG.Slot = 0x5678;
    indication->RX_UE_INFORMATION_TAG.UEID = getInt(statement, "EmployeeID");
    indication->RX_UE_INFORMATION_TAG.RNTI = getInt(statement, "RNTI");
    indication->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
    strcpy(indication->CRC_INDICATION_REL8_TAG.CSI_RSRP, getString(statement, "CSI_RSRP"));
    indication->CRC_INDICATION_REL8_TAG.CSI_RSRQ = (float)getDouble(statement, "CSI_RSRQ");
  }

  // Clean up the database connection
  closeStatement(statement);

