// Function to manage the dynamic array of RX indications
int process_and_store_indications(char *filePath, char *outputDir, int maxIndications) {
    // Initialize variables for managing the RX indications
    struct LTE_PHY_RX_API_UU_RXINDICATIONS *rxIndications = NULL;
    size_t rxIndicationCount = 0;
    int retVal = 0;

    // Check if the maximum number of indications is valid
    if (maxIndications <= MIN_INDICATIONS) {
        maxIndications = MIN_INDICATIONS;
    } else if (maxIndications > MAX_INDICATIONS) {
        maxIndications = MAX_INDICATIONS;
    }

    // Initialize the dynamic array of RX indications
    rxIndications = malloc(sizeof(struct LTE_PHY_RX_API_UU_RXINDICATIONS) * maxIndications);
    if (rxIndications == NULL) {
        fprintf(stderr, "Failed to allocate memory for RX indications\n");
        return 1;
    }

