    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Parse the RX indication from the buffer
        struct LTE_PHY_RX_API_UU_RXINDICATIONS *rxIndication = &rxIndications[rxIndicationCount];
        sscanf(buffer, "%u %u", &rxIndication->rnti, &rxIndication->cgi.cellId);
