    if (retVal != 0) {
        fprintf(stderr, "Error converting JPEG to PDF\n");
        free(rxIndications);
        return 1;
    }

    // Free the memory used by the dynamic array of RX indications
    free(rxIndications);

    return retVal;
}

// Function to clear the dynamic array of RX indications
