// Define the dynamic array for storing RX indications
typedef struct {
    LTE_PHY_RX_API_UU_RXINDICATIONS** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} LTE_PHY_RX_API_UU_RXINDICATIONS_DYNAMIC_ARRAY;

// Initialize the dynamic array with a given capacity
LTE_PHY_RX_API_UU_RXINDICATIONS_DYNAMIC_ARRAY init_dynamic_array(size_t capacity) {
    LTE_PHY_RX_API_UU_RXINDICATIONS_DYNAMIC_ARRAY array;
    array.data = (LTE_PHY_RX_API_UU_RXINDICATIONS**)malloc(capacity * sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS*));
    array.capacity = capacity;
    array.size = 0;
    pthread_mutex_init(&array.mutex, NULL);
    return array;
}

// Append a new RX indication to the dynamic array
void append_rx_indication(LTE_PHY_RX_API_UU_RXINDICATIONS_DYNAMIC_ARRAY* array, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, char* LTE_PHY_RX_API_UU_RXINDICATIONS_CGI) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        // Reallocate the memory to double the size of the array
        array->data = realloc(array->data, 2 * array->capacity * sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS*));
        array->capacity = 2 * array->capacity;
    }
    // Allocate memory for the new RX indication structure
    LTE_PHY_RX_API_UU_RXINDICATIONS* new_rx_indication = (LTE_PHY_RX_API_UU_RXINDICATIONS*)malloc(sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS));
    // Set the fields of the new RX indication structure
    new_rx_indication->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_rx_indication->RNTI = RNTI;
    new_rx_indication->LTE_PHY_RX_API_UU_RXINDICATIONS_CGI = LTE_PHY_RX_API_UU_RXINDICATIONS_CGI;
    // Add the new RX indication to the array
    array->data[array->size++] = new_rx_indication;
    pthread_mutex_unlock(&array->mutex);
}

// Free the memory used by the dynamic array
void free_dynamic_array(LTE_PHY_RX_API_UU_RXINDICATIONS_DYNAMIC_ARRAY* array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]->LTE_PHY_RX_API_UU_RXINDICATIONS_CGI);
        free(array->data[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}
