// Define the record structure
typedef struct {
    int key;
    long offset;
    float data;
} Record;

// Define the memory pool size and the increment factor for the offset values
#define POOL_SIZE 10000000
#define INCREMENT_FACTOR 10

// Define the cache hit rate and latency metrics
float cache_hit_rate = 0.0;
float cache_latency = 0.0;

// Define the memory allocation function
void* allocateMemory(size_t size) {
    // Allocate memory from the pool
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // If the allocation failed, increase the pool size and retry
        POOL_SIZE *= 2;
        ptr = malloc(size);
    }
    return ptr;
}

// Define the deallocation function
void freeMemory(void* ptr) {
    // Free the memory from the pool
    free(ptr);
}

// Define the function to initialize a record structure
Record initRecord(int key, long offset, float data) {
    Record record;
    record.key = key;
    record.offset = offset;
    record.data = data;
    return record;
}

// Define the function to add a new record to the collection
void addRecord(int key, long offset, float data) {
    // Allocate memory for the new record
    Record* new_record = (Record*)allocateMemory(sizeof(Record));

    // Initialize the new record
    *new_record = initRecord(key, offset, data);

    // Add the new record to the collection
    records[records_count++] = new_record;
}

// Define the function to remove a record from the collection
void removeRecord(int key) {
    // Find the index of the record with the given key
    int i;
    for (i = 0; i < records_count; i++) {
        if (records[i]->key == key) {
            break;
        }
    }

    // If the record was found, remove it from the collection
    if (i < records_count) {
        // Free the memory for the record
        freeMemory(records[i]);

        // Remove the record from the collection
        records_count--;
        records[i] = records[records_count];
    }
}

// Define the function to update a record in the collection
void updateRecord(int key, long offset, float data) {
    // Find the index of the record with the given key
    int i;
    for (i = 0; i < records_count; i++) {
        if (records[i]->key == key) {
            break;
        }
    }

    // If the record was found, update its offset and data values
    if (i < records_count) {
        records[i]->offset = offset;
        records[i]->data = data;
    }
}

// Define the function to search for a record in the collection
Record* findRecord(int key) {
    // Find the index of the record with the given key
    int i;
    for (i = 0; i < records_count; i++) {
        if (records[i]->key == key) {
            break;
        }
    }

    // If the record was found, return its pointer
    if (i < records_count) {
        return records[i];
    } else {
        return NULL;
    }
}

// Define the function to print all records in the collection
void printRecords() {
    // Iterate over each record and print its key, offset, and data values
    for (int i = 0; i < records_count; i++) {
        Record* record = records[i];
        printf("Record %d: key=%d, offset=%ld, data=%.2f\n", i+1, record->key, record->offset, record->data);
    }
}

// Define the function to deallocate all memory allocated for the collection
void clearRecords() {
    // Free each record in the collection
    for (int i = 0; i < records_count; i++) {
        freeMemory(records[i]);
    }

    // Set the number of records to 0
    records_count = 0;
}

