typedef struct {
    int num_records;
    int max_sum;
    int max_memory_kb;
    record* records;
    long* offsets;
    int* keys;
    compressed_data* data;
} initialization_result;

// Implement a function to initialize the arrays and structures
void init(int n, int min_val, int max_val, int max_sum, int max_memory_kb, initialization_parameters* params) {
    // Allocate memory for the offset and key arrays
    params->offsets = malloc(sizeof(long) * n);
    params->keys = malloc(sizeof(int) * n);

    // Initialize the offset and key arrays with unique values
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        params->offsets[i] = rand() % max_val + min_val;
        params->keys[i] = rand() % max_val + min_val;
    }

    // Allocate memory for the record array and populate it with random values
    params->records = malloc(sizeof(record) * n);
    for (int i = 0; i < n; ++i) {
        params->records[i].offset = params->offsets[i];
        params->records[i].key = params->keys[i];
    }

    // Ensure that the total memory allocation does not exceed the maximum allowed memory limit
    int total_memory = sizeof(long) * n + sizeof(int) * n + sizeof(record) * n;
    if (total_memory > max_memory_kb * 1024) {
        // Reduce the number of records or increase the maximum allowed memory limit
        params->num_records = n - total_memory / max_memory_kb * 1024;
        printf("Reducing number of records from %d to %d due to memory limit\n", n, params->num_records);
    }

    // Initialize the timestamp field for each record and populate the compressed data structure
    params->data = malloc(sizeof(compressed_data) * params->num_records);
    for (int i = 0; i < params->num_records; ++i) {
        params->data[i].record = &params->records[i];
        params->data[i].offset = &params->offsets[i];
        params->data[i].key = &params->keys[i];
    }

    // Validate the sum of all offset values does not exceed the maximum sum threshold
    long sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += params->offsets[i];
        if (sum > max_sum) {
            // Reduce the number of records or increase the maximum allowed sum threshold
            params->num_records = i - sum / max_sum;
            printf("Reducing number of records from %d to %d due to sum limit\n", n, params->num_records);
            break;
        }
    }

    // Copy the contents of the offset and key arrays into a new dynamically allocated structure of type compressed_data
    params->compressed_data = malloc(sizeof(compressed_data) * params->num_records);
    for (int i = 0; i < params->num_records; ++i) {
        params->compressed_data[i].offset = &params->offsets[i];
        params->compressed_data[i].key = &params->keys[i];
    }
}

// Implement a function to free all allocated memory
void free_memory(initialization_result* result) {
    if (result != NULL) {
        free(result->offsets);
        free(result->keys);
        free(result->records);
        free(result->data);
        free(result->compressed_data);
    }
}
