// Struct to hold the cipher context and configuration data
typedef struct {
    EVP_CIPHER_CTX *ctx;
    const char *cipher;
    int key_len;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

// Function to load the configuration file and create a cipher context
int create_cipher_context(const char *config_file, CipherContext **ctx) {
    // Open the configuration file for reading
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        return -1;
    }

    // Create a new cipher context and initialize it to defaults
    CipherContext *context = malloc(sizeof(CipherContext));
    if (context == NULL) {
        fclose(fp);
        return -2;
    }
    memset(&context->ctx, 0, sizeof(EVP_CIPHER_CTX));
    context->cipher = "aes-256-cbc"; // Default cipher algorithm and key size
    context->key_len = 32;
    memset(context->iv, 0, EVP_MAX_IV_LENGTH);

    // Read the configuration file line by line
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Skip blank lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse the line and update the cipher context accordingly
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (strcmp(key, "cipher") == 0) {
            context->cipher = value;
        } else if (strcmp(key, "key_len") == 0) {
            context->key_len = atoi(value);
        } else if (strcmp(key, "iv") == 0) {
            strncpy((char *)context->iv, value, EVP_MAX_IV_LENGTH);
        }
    }

    // Close the configuration file and return the cipher context
    fclose(fp);
    *ctx = context;
    return 0;
}

// Function to destroy a cipher context and free its resources
void destroy_cipher_context(CipherContext *ctx) {
    EVP_CIPHER_CTX_cleanup(&ctx->ctx);
    free(ctx);
}

// Function to encrypt or decrypt data using a cipher context
int cipher_data(CipherContext *ctx, const unsigned char *input, int input_len, unsigned char **output) {
    // Check that the context is valid and the input length is non-zero
    if (ctx == NULL || input_len <= 0) {
        return -1;
    }

    // Create a new output buffer for the encrypted data
    int out_len = input_len + EVP_MAX_BLOCK_LENGTH;
    unsigned char *out = malloc(out_len);
    if (out == NULL) {
        return -2;
    }

    // Initialize the cipher context with the configuration data
    int ret = EVP_EncryptInit_ex(&ctx->ctx, ctx->cipher, NULL, NULL, ctx->iv);
    if (ret != 1) {
        free(out);
        return -3;
    }

    // Set the key length and key material for the encryption
    ret = EVP_CIPHER_CTX_set_key_length(&ctx->ctx, ctx->key_len);
    if (ret != 1) {
        free(out);
        return -4;
    }
    ret = EVP_EncryptInit_ex(&ctx->ctx, NULL, NULL, ctx->key, ctx->iv);
    if (ret != 1) {
        free(out);
        return -5;
    }

    // Encrypt the input data and store it in the output buffer
    ret = EVP_EncryptUpdate(&ctx->ctx, out, &out_len, input, input_len);
    if (ret != 1) {
        free(out);
        return -6;
    }

    // Set the IV for the next encryption operation and store it in the output buffer
    ret = EVP_CIPHER_CTX_ctrl(&ctx->ctx, EVP_CTRL_GCM_IV_GEN, EVP_MAX_IV_LENGTH, ctx->iv);
    if (ret <= 0) {
        free(out);
        return -7;
    }
    memcpy(*output, ctx->iv, ret);

    // Free the output buffer and return the encrypted data
    free(out);
    *output = malloc(input_len + EVP_MAX_BLOCK_LENGTH);
    if (*output == NULL) {
        return -8;
    }
    memcpy(*output, input, input_len);
    return input_len + ret;
}
