    // Set the CGI field based on the cell ID and frequency
    new_struct->CGI->cell_id = get_cell_id();
    new_struct->CGI->frequency = get_frequency();

    // Append the new structure to the array
    ue_rx_indications = realloc(ue_rx_indications, sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS*) * (num_ues + 1));
    ue_rx_indications[num_ues++] = new_struct;

    // Release lock to allow other threads to access the dynamic array
    pthread_mutex_unlock(&ue_rx_indications_lock);
}

// Function to clear the RX indications array safely before reusing it
void clear_ue_rx_indications() {
    // Acquire lock to ensure thread-safe access to the dynamic array
    pthread_mutex_lock(&ue_rx_indications_lock);

    // Release all memory allocated for each structure in the array
    int i;
    for (i = 0; i < num_ues; i++) {
        free(ue_rx_indications[i]->RNTI);
        free(ue_rx_indications[i]);
