    num_ues = 0;
    ue_rx_indications = (LTE_PHY_RX_API_UU_RXINDICATIONS**) malloc(sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS*) * INITIAL_UE_COUNT);

    // Release lock to allow other threads to access the dynamic array
    pthread_mutex_unlock(&ue_rx_indications_lock);
}

