void classify_ip_packets(struct packet *packet) {
    // Acquire lock to ensure thread-safe access to the dynamic array
    pthread_mutex_lock(&ue_rx_indications_lock);

    // Iterate through each UE in the RX indications array and check if its QoS markings match the incoming packet
    int i;
    for (i = 0; i < num_ues; i++) {
        if (strcmp(ue_rx_indications[i]->RNTI, packet->RNTI) == 0 && ue_rx_indications[i]->CGI.cell_id == packet->cell_id && ue_rx_indications[i]->CGI.frequency == packet->frequency) {
