// Define the item structure
typedef struct {
    char* name;
    double value;
} item;

// Define a dynamic array to store items
typedef struct {
    item** data;
    size_t capacity;
    size_t size;
} item_array;

// Initialize the item array with a given capacity
void init_item_array(item_array* arr, size_t capacity) {
    arr->data = (item**)malloc(capacity * sizeof(item*));
    arr->capacity = capacity;
    arr->size = 0;
}

// Insert an item into the array
void insert_item(item_array* arr, const char* name, double value) {
    if (arr->size == arr->capacity) {
        // Double the capacity if the array is full
        size_t new_capacity = arr->capacity * 2;
        item** new_data = (item**)realloc(arr->data, new_capacity * sizeof(item*));
        if (!new_data) {
            // Reallocation failed, abort
            return;
        }
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
    item* new_item = (item*)malloc(sizeof(item));
    if (!new_item) {
        // Memory allocation failed, abort
        return;
    }
    new_item->name = strdup(name);
    new_item->value = value;
    arr->data[arr->size++] = new_item;
}

// Delete an item from the array
void delete_item(item_array* arr, const char* name) {
    size_t i = 0;
    while (i < arr->size && strcmp(arr->data[i]->name, name) != 0) {
        i++;
    }
    if (i < arr->size) {
        // Found the item to delete
        free(arr->data[i]);
        arr->data[i] = NULL;
        arr->size--;
    } else {
        // Item not found, ignore
    }
}

// Retrieve an item from the array
item* retrieve_item(item_array* arr, const char* name) {
    size_t i = 0;
    while (i < arr->size && strcmp(arr->data[i]->name, name) != 0) {
        i++;
    }
    if (i < arr->size) {
        // Found the item to retrieve
        return arr->data[i];
    } else {
        // Item not found, return NULL
        return NULL;
    }
}

// Update the maximum length of names and the acceptable range of values stored in `item` structures
void update_item_fields(item_array* arr, size_t max_name_len, double min_value, double max_value) {
    // Check if the new fields are valid
    if (max_name_len <= 0 || min_value >= max_value) {
        return;
    }
    for (size_t i = 0; i < arr->size; i++) {
        item* curr_item = arr->data[i];
        // Update the name length if necessary
        size_t new_name_len = strlen(curr_item->name);
        if (new_name_len > max_name_len) {
            free(curr_item->name);
            curr_item->name = (char*)malloc((max_name_len + 1) * sizeof(char));
            strncpy(curr_item->name, name, max_name_len);
            curr_item->name[max_name_len] = '\0';
        }
        // Update the value range if necessary
        if (curr_item->value < min_value || curr_item->value > max_value) {
            curr_item->value = max(min_value, min(curr_item->value, max_value));
        }
    }
}

// Find the longest string in the array and print it to standard output
void find_longest_string(item_array* arr) {
    size_t longest = 0;
    for (size_t i = 0; i < arr->size; i++) {
        item* curr_item = arr->data[i];
        if (strlen(curr_item->name) > longest) {
            longest = strlen(curr_item->name);
        }
    }
    printf("%s\n", arr->data[longest]->name);
}
