Here's a sample implementation of the C function to manage a dynamic collection of sensor data records:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>

// Define constants for number of sensors, maximum timestamp, and tag range
#define NUM_SENSORS 10000000
#define MAX_TIMESTAMP 999999999
#define TAG_RANGE 'Z' - 'A' + 1

// Define data structure for sensor data record
typedef struct {
    long timestamp;
    double measurement;
    char tag;
} SensorDataRecord;

// Define array to store sensor data records
SensorDataRecord *records = NULL;
size_t numRecords = 0;
size_t maxRecords = NUM_SENSORS;

// Function to add a new sensor data record
void addRecord(long timestamp, double measurement, char tag) {
    // Check if maximum number of records has been reached
    if (numRecords == maxRecords) {
        printf("Maximum number of records has been reached\n");
        return;
    }

    // Initialize new record with provided values
    SensorDataRecord *newRecord = malloc(sizeof(SensorDataRecord));
    newRecord->timestamp = timestamp;
    newRecord->measurement = measurement / 1000.0 + tag - 'A';
    newRecord->tag = tag;

    // Add new record to the array and update number of records
    records[numRecords++] = newRecord;
}

// Function to remove a sensor data record by its index
void removeRecord(size_t index) {
    if (index < numRecords) {
        SensorDataRecord *recordToRemove = records[index];
        free(recordToRemove);

        // Shift remaining records forward to fill the gap
        for (size_t i = index; i < numRecords - 1; i++) {
            records[i] = records[i + 1];
        }
        numRecords--;
    }
}

// Function to find and print the average of all measurements in the array
void printAverage() {
    if (numRecords == 0) {
        printf("No records found\n");
        return;
    }

    double totalMeasurement = 0.0;
    for (size_t i = 0; i < numRecords; i++) {
        SensorDataRecord *record = records[i];
        totalMeasurement += record->measurement;
    }

    double average = totalMeasurement / (double)numRecords;
    printf("Average measurement: %f\n", average);
}

// Function to sort the array in descending order by timestamp
void sortByTimestamp() {
    if (numRecords == 0) {
        printf("No records found\n");
        return;
    }

    // Use bubble sort algorithm to sort array in descending order by timestamp
    for (size_t i = 0; i < numRecords - 1; i++) {
        for (size_t j = i + 1; j < numRecords; j++) {
            if (records[i]->timestamp < records[j]->timestamp) {
                SensorDataRecord *temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
}
```
