const int MAX_KEY_VALUE = 1024; // maximum value for a key
const int RANDOM_SEED = 1337; // seed for random number generator

// Function to allocate memory for an array of 'offset' structures
struct offset *allocate_offsets(size_t n) {
    if (n > MAX_OFFSET_SIZE) {
        fprintf(stderr, "Error: requested size exceeds maximum allowed\n");
        return NULL;
    }
    struct offset *array = malloc(sizeof(struct offset) * n);
    if (!array) {
        perror("malloc failed");
        return NULL;
    }
    memset(array, 0, sizeof(struct offset) * n);
    return array;
}

// Function to allocate memory for an array of 'key' structures
struct key *allocate_keys(size_t n) {
    if (n > MAX_KEY_SIZE) {
        fprintf(stderr, "Error: requested size exceeds maximum allowed\n");
        return NULL;
    }
    struct key *array = malloc(sizeof(struct key) * n);
    if (!array) {
        perror("malloc failed");
        return NULL;
    }
    memset(array, 0, sizeof(struct key) * n);
    return array;
}

// Function to allocate memory for an array of 'record' structures
struct record *allocate_records(size_t n) {
    if (n > MAX_OFFSET_SIZE) {
        fprintf(stderr, "Error: requested size exceeds maximum allowed\n");
        return NULL;
    }
    struct record *array = malloc(sizeof(struct record) * n);
    if (!array) {
        perror("malloc failed");
        return NULL;
    }
    memset(array, 0, sizeof(struct record) * n);
    return array;
}

// Function to validate keys against a pre-existing list of known identifiers
int validate_keys(struct key *key_list, struct key *new_key) {
    // Check if the new key is in the list of known identifiers
    for (size_t i = 0; i < MAX_KEY_SIZE; ++i) {
        if (key_list[i].value == new_key->value) {
            return 1;
        }
    }
    return 0;
}

// Function to initialize a record with a random value within a specified range
int init_record(struct record *record, int min, int max) {
    // Generate a random number within the specified range
    srand(RANDOM_SEED);
    int value = (int)(min + ((max - min + 1) * rand() / (RAND_MAX + 1.0)));
    record->value = value;
    return 0;
}

// Function to handle partial failures gracefully by releasing all previously allocated resources before exiting
void cleanup(struct offset *offsets, struct key *keys, struct record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

// Main function to manage memory for multiple interconnected data structures under specific operational constraints
void manage_memory(size_t n_offsets, size_t n_keys, size_t n_records, int min_key_value, int max_key_value) {
    // Allocate memory for the offset array
    struct offset *offsets = allocate_offsets(n_offsets);
    if (!offsets) {
        cleanup(NULL, NULL, NULL);
        return;
    }

    // Allocate memory for the key array
    struct key *keys = allocate_keys(n_keys);
    if (!keys) {
        cleanup(offsets, NULL, NULL);
        return;
    }

    // Initialize the keys with unique values within the specified range
    for (size_t i = 0; i < n_keys; ++i) {
        keys[i].value = MIN_KEY_VALUE + rand() % (max_key_value - min_key_value + 1);
    }

    // Allocate memory for the record array
    struct record *records = allocate_records(n_records);
    if (!records) {
        cleanup(offsets, keys, NULL);
        return;
    }

    // Initialize each record with a random value within the specified range and a pointer to an offset structure
    for (size_t i = 0; i < n_records; ++i) {
        init_record(&records[i], min_key_value, max_key_value);
        records[i].offset = &offsets[rand() % n_offsets];
    }

    // Validate the keys against a pre-existing list of known identifiers to avoid conflicts
    for (size_t i = 0; i < n_keys; ++i) {
        if (!validate_keys(keys, &keys[i])) {
            cleanup(offsets, keys, records);
            return;
        }
    }

    // Release all previously allocated resources before exiting
    cleanup(offsets, keys, records);
}
