void modifyVector(const string& filePath, vector<int>& vec, int key1, int key2, int newKey) {
    ifstream fin(filePath);
    map<string, int> keys;
    string line;
    while (getline(fin, line)) {
        istringstream iss(line);
        int key;
        if (iss >> key) {
            keys[to_string(key)] = key;
        }
    }

    // find the first occurrence of key2 in vec
