  // Start the application with the configured log level and rotation policies
  LOG4CPLUS_DEBUG(logger, "Starting application with log level " << log_level << " and rotation policies of " << rotation_size << " bytes and " << rotation_time << " seconds");

  // Implement error handling for missing or incomplete configuration data across all sources
  if (!json_config) {
