// Struct to hold information about a cryptographic hash function or cipher
struct HashCipher {
    char *name;
    void (*func)(void*);
    void *param;
};

// List of pointers to structs containing available hash functions and ciphers
static struct HashCipher *availableHashCiphers = NULL;

// Function to return a dynamically allocated list of available hash functions and ciphers
struct HashCipher** getAvailableHashCiphers(void) {
    // Check if the list has already been initialized
    if (availableHashCiphers == NULL) {
        // Initialize the list with available cryptographic libraries
        int numHashFunctions = 0, numCiphers = 0;
        struct HashCipher **hashCiphers = getAvailableCryptographicLibraries(&numHashFunctions, &numCiphers);

        // Allocate memory for the list of structs
        availableHashCiphers = (struct HashCipher**)malloc(sizeof(struct HashCipher*) * (numHashFunctions + numCiphers));
        if (availableHashCiphers == NULL) {
            perror("Failed to allocate memory for list of available hash functions and ciphers");
            return NULL;
        }

        // Fill the list with pointers to the available hash functions and ciphers
        int i = 0;
        for (i = 0; i < numHashFunctions; i++) {
            struct HashCipher *hashCipher = (struct HashCipher*)malloc(sizeof(struct HashCipher));
            hashCipher->name = hashCiphers[i];
            hashCipher->func = NULL;
            hashCipher->param = NULL;
            availableHashCiphers[i] = hashCipher;
        }

        for (int i = 0; i < numCiphers; i++) {
            struct HashCipher *hashCipher = (struct HashCipher*)malloc(sizeof(struct HashCipher));
            hashCipher->name = ciphers[i];
            hashCipher->func = NULL;
            hashCipher->param = NULL;
            availableHashCiphers[numHashFunctions + i] = hashCipher;
        }
    }

    // Return the list of pointers to structs
    return availableHashCiphers;
}

// Function to check for the availability of each hash function or cipher based on system capabilities and configuration settings
struct HashCipher** getAvailableCryptographicLibraries(int *numHashFunctions, int *numCiphers) {
    // Initialize the number of available hash functions and ciphers to 0
    *numHashFunctions = 0;
    *numCiphers = 0;

    // Get a list of all available cryptographic libraries
    char **cryptographicLibraries = getAllAvailableCryptographicLibraries();
    if (cryptographicLibraries == NULL) {
        perror("Failed to get list of available cryptographic libraries");
        return NULL;
    }

    // Iterate over the list and check for each library's availability
    int i = 0, j = 0;
    for (i = 0; i < numHashFunctions && i < INT_MAX; i++) {
        if (isHashFunctionAvailable(cryptographicLibraries[i])) {
            (*numHashFunctions)++;
        }

        if (isCipherAvailable(cryptographicLibraries[i])) {
            (*numCiphers)++;
        }
