        public async Task Main()
        {
            // Load configuration settings from JSON file and store in cache
            var config = JsonConvert.DeserializeObject<StreamingApplicationConfig>(File.ReadAllText("config.json"));
            _cache.Set("Config", config, new MemoryCacheEntryOptions());

            // Create instances of external services
            var weatherService = new WeatherService();
            var satelliteImageryService = new SatelliteImageryService();
            var trafficUpdateService = new TrafficUpdateService();

            // Initialize streaming application
            await InitializeStreamingApplication();

            // Start streaming data from external services
            await Task.WhenAll(
                StreamWeatherData(),
                StreamSatelliteImagery(),
                StreamTrafficUpdates()
            );
        }

        private async Task InitializeStreamingApplication()
        {
            var config = _cache.Get("Config") as StreamingApplicationConfig;

            // Set initial resolution, frame rate, and quality settings based on configuration
            var resolution = config.Resolution;
            var frameRate = config.FrameRate;
            var quality = config.Quality;

            // Set up logging intervals based on configuration
            var loggingIntervals = config.LoggingIntervals;

            // Start streaming data from external services
            await weatherService.StreamWeatherData(resolution, frameRate, quality);
            await satelliteImageryService.StreamSatelliteImagery(resolution, frameRate, quality);
            await trafficUpdateService.StreamTrafficUpdates();
        }

        private async Task StreamWeatherData()
        {
