                var adjustedQuality = config.AdjustedQuality;

                // Update streaming application with new settings
                satelliteImageryService.UpdateStreamingSettings(adjustedResolution, adjustedFrameRate, adjustedQuality);
            }
        }

        private async Task StreamTrafficUpdates()
        {
