namespace WebAPI
{
    public static class ResourceManagement
    {
        public static TResource ManageResourceLifecycle<TResource>(string resourceId, string requestBody) where TResource : new()
        {
            // Check if the requested resource exists and throw an exception if not found
            var resource = GetResource(resourceId);
            if (resource == null)
            {
                throw new ResourceNotFoundException($"Resource with ID '{resourceId}' does not exist.");
            }

            // Update the resource based on the request body and return the updated resource object
            UpdateResource(resource, requestBody);

            return resource;
        }

        public static TResource GetResource<TResource>(string resourceId) where TResource : new()
        {
            // Check if the requested resource exists in the cache
            var cachedResource = GetCachedResource(resourceId);
            if (cachedResource != null)
            {
                return cachedResource;
            }

            // If not found in the cache, query the database for the resource
            using (var dbContext = new MyDbContext())
            {
                var resource = dbContext.Resources.FirstOrDefault(r => r.Id == resourceId);
                if (resource != null)
                {
                    // Cache the resource in memory to avoid unnecessary database queries
                    SetCachedResource(resource);
                    return resource;
                }
            }

            return null;
        }

        public static void UpdateResource<TResource>(TResource resource, string requestBody) where TResource : new()
        {
            // Parse the request body and update the resource properties
            var updatedProperties = ParseRequestBody(requestBody);
            foreach (var property in updatedProperties)
            {
                resource.GetType().GetProperty(property.Key).SetValue(resource, property.Value);
            }

            // Save the updated resource to the database
            using (var dbContext = new MyDbContext())
            {
                dbContext.Resources.Update(resource);
                dbContext.SaveChanges();
            }
        }

        public static void DeleteResource<TResource>(string resourceId) where TResource : new()
        {
            // Check if the requested resource exists and throw an exception if not found
            var resource = GetCachedResource(resourceId);
            if (resource == null)
            {
                throw new ResourceNotFoundException($"Resource with ID '{resourceId}' does not exist.");
            }

            // Delete the resource from the database
            using (var dbContext = new MyDbContext())
            {
                var deletedResource = dbContext.Resources.FirstOrDefault(r => r.Id == resourceId);
                if (deletedResource != null)
                {
                    dbContext.Resources.Remove(deletedResource);
                    dbContext.SaveChanges();

                    // Clear the cache for the deleted resource
                    ClearCachedResource(resourceId);
                }
            }
        }

        public static TResource ParseXmlDocument<TResource>(string xmlString) where TResource : new()
        {
            var document = new XmlDocument();
            document.LoadXml(xmlString);

            // Use XPath to locate the first element in the document that matches the specified name
            var xpathQuery = $"//{typeof(TResource).Name}[1]";
            var xmlNode = document.SelectSingleNode(xpathQuery);

            if (xmlNode == null)
            {
                throw new XmlException($"Could not find any element with name '{typeof(TResource).Name}' in the XML document.");
            }

            // Parse the XML node and populate the resource properties
            var resource = new TResource();
            foreach (var property in typeof(TResource).GetProperties())
            {
                var attributeValue = xmlNode.Attributes[property.Name];
                if (attributeValue == null)
                {
                    continue;
                }

                var propertyValue = Convert.ChangeType(attributeValue.Value, property.PropertyType);
                resource.GetType().GetProperty(property.Name).SetValue(resource, propertyValue);
            }

            return resource;
        }

        public static void SetCachedResource<TResource>(string resourceId) where TResource : new()
        {
            // Check if the requested resource exists in the cache
            var cachedResource = GetCachedResource(resourceId);
            if (cachedResource != null)
            {
                return;
            }

            // If not found in the cache, query the database for the resource
            using (var dbContext = new MyDbContext())
            {
                var resource = dbContext.Resources.FirstOrDefault(r => r.Id == resourceId);
                if (resource != null)
                {
                    // Cache the resource in memory to avoid unnecessary database queries
                    SetCachedResource(resource);
                }
            }
        }

        public static void ClearCachedResource<TResource>(string resourceId) where TResource : new()
        {
            // Remove the cached resource from memory
            var cachedResources = GetCachedResources();
            if (cachedResources.ContainsKey(resourceId))
            {
                cachedResources.Remove(resourceId);
            }
        }

        public static Dictionary<string, TResource> GetCachedResources<TResource>() where TResource : new()
        {
            return new Dictionary<string, TResource>();
        }
    }
}
