// Cryptographic context structure
typedef struct {
  AES_KEY aes_key; // Encryption key
  unsigned char iv[16]; // Initialization vector (IV)
} crypto_ctx;

// Generate a new IV using a cryptographically secure random number generator
static void generate_iv(unsigned char *iv) {
  int i = 0;
  while (i < 16) {
    iv[i] = (unsigned char)rand();
    i++;
  }
}

// Derive an encryption key and IV from a given password
crypto_ctx derive_key(const char *password, int salt) {
  crypto_ctx ctx;
  unsigned char derived_key[32]; // Encryption key (32 bytes)
  unsigned char derived_iv[16]; // Initialization vector (IV) (16 bytes)

  if (strlen(password) < 8) {
    printf("WARNING: Password is less than 8 characters long. Skipping...\n");
    return NULL;
  }

  // Derive encryption key from password using OpenSSL library
  AES_set_encrypt_key(password, strlen(password), &ctx->aes_key);

  // Generate a new IV for each invocation
  generate_iv(ctx->iv);

  return ctx;
}

// Cleanup routine to release resources and disable the cipher
void cleanup_crypto(crypto_ctx *ctx) {
  AES_KEY_free(&ctx->aes_key);
  free(ctx);
}
