    unsigned short rnti;
    unsigned char crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    // Get environment variable for CRC storage path
    char *storage_path = getenv("CRC_STORAGE_PATH");
    if (storage_path == NULL) {
        // Generate default directory name based on timestamp and process ID
        char default_dir_name[256];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        sprintf(default_dir_name, "/tmp/crc_storage_%04d%02d%02d_%02d%02d",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min);
        // Create default directory if it does not exist
        int status = mkdir(default_dir_name, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);
        if (status == 0) {
            // Set environment variable to newly created directory path
            setenv("CRC_STORAGE_PATH", default_dir_name, 1);
        } else if (status != EEXIST) {
            // Handle other error cases
            perror("mkdir");
        }
    }

    // Check if directory for storing CRC PDUs exists
    struct stat sb;
    int dir_exists = stat(storage_path, &sb);
    if (dir_exists != 0 && errno == ENOENT) {
        perror("stat");
        exit(1);
    }

    // Create file descriptor for storage directory
    int fd;
    if ((fd = open(storage_path, O_RDONLY)) < 0) {
        perror("open");
        exit(1);
    }

    // Read list of CRC PDUs from file
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getdelim(&line, &len, '\n', fd)) != -1) {
        // Add new CRC PDU to list
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdu == NULL) {
            perror("malloc");
            exit(1);
        }
        new_pdu->valid = 1;
        sscanf(line, "%u %u %u %d", &new_pdu->rx_ue_information_tag,
               &new_pdu->rnti, &new_pdu->crc_indication_rel8_tag,
               &new_pdu->crcflag);
        list = realloc(list, (num_crc_pdus + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (list == NULL) {
            perror("realloc");
            exit(1);
        }
        list[num_crc_pdus++] = new_pdu;
    }
    free(line);
    close(fd);
}
