struct TemperatureRecord {
    double temperature;
    char* unit;
};

// Function to read file and calculate average temperature
void calculateAverageTemperature(const char* filename) {
    // Open file for reading
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: could not open file %s\n", filename);
        return;
    }

    // Allocate memory for struct array and initialize size to 0
    struct TemperatureRecord* records = malloc(sizeof(struct TemperatureRecord));
    int size = 0;

    // Read file line by line and process each record
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Split line into temperature value and unit using string manipulation functions
        double temperature;
        char* unit;
        if (sscanf(line, "%lf%s", &temperature, &unit) != 2) {
            printf("Warning: malformed entry in file %s\n", filename);
            continue;
        }

        // Validate temperature unit and handle invalid entries
        if (strcmp(unit, "C") && strcmp(unit, "F")) {
            printf("Error: invalid temperature unit %s for record %d in file %s\n", unit, size + 1, filename);
            continue;
        }

        // Reallocate memory for records if necessary to accommodate new entry
        if (size == 0 || size == size * sizeof(struct TemperatureRecord)) {
            struct TemperatureRecord* temp = realloc(records, size + sizeof(struct TemperatureRecord));
            if (temp == NULL) {
                printf("Error: could not allocate memory for record %d in file %s\n", size + 1, filename);
                break;
            } else {
                records = temp;
            }
        }

        // Add new temperature record to array and increment size
        records[size].temperature = temperature;
        records[size].unit = unit;
        size++;
    }

    // Calculate average temperature and print result
    double averageTemperature = 0.0;
    for (int i = 0; i < size; i++) {
        if (strcmp(records[i].unit, "C") == 0) {
            averageTemperature += records[i].temperature;
        } else {
            averageTemperature += (records[i].temperature - 32.0) / 1.8;
        }
    }
    printf("Average temperature: %.2f\n", averageTemperature / size);

    // Deallocate memory for records and close file
    free(records);
    fclose(file);
}
