// DNS resolution function
int dnsResolve(const char *hostname, struct in_addr *addr) {
    int status = 0;
    struct addrinfo hints, *res;

    // initialize hints
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0;
    hints.ai_flags = AI_ADDRCONFIG | AI_V4MAPPED;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        status = -1; // error
    } else {
        // get IPv4 address
        struct addrinfo *ipv4 = res;
        while (ipv4) {
            if (ipv4->ai_family == AF_INET) {
                memcpy(addr, &((struct sockaddr_in *) ipv4->ai_addr)->sin_addr, sizeof(*addr));
                break;
            }
            ipv4 = ipv4->ai_next;
        }
        freeaddrinfo(res); // free memory allocated by getaddrinfo
    }
    return status;
}

// establish connection to remote server
int connectToServer(const char *hostname, int port) {
    struct in_addr addr;
    if (dnsResolve(hostname, &addr) == -1) { // DNS resolution failed
        return -1; // error
    }

    int sock = socket(AF_INET, SOCK_STREAM, 0); // create socket
    if (sock < 0) { // socket creation failed
        perror("socket");
        return -2;
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET; // IPv4
    serverAddr.sin_port = htons(port);
    memcpy(&serverAddr.sin_addr, &addr, sizeof(struct in_addr));

    if (connect(sock, (struct sockaddr *) &serverAddr, sizeof(serverAddr)) < 0) { // connection failed
        perror("connect");
        return -3;
    }

    return sock; // successful connection
}

// establish multiple connections to remote servers in parallel
void connectToServersParallel(const char *hostname, int port, int num_connections) {
    struct in_addr addr;
    if (dnsResolve(hostname, &addr) == -1) { // DNS resolution failed
        return; // error
    }

    int sock[num_connections]; // array of socket descriptors
    for (int i = 0; i < num_connections; i++) {
        sock[i] = socket(AF_INET, SOCK_STREAM, 0); // create socket
        if (sock[i] < 0) { // socket creation failed
            perror("socket");
            continue;
        }
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET; // IPv4
    serverAddr.sin_port = htons(port);
    memcpy(&serverAddr.sin_addr, &addr, sizeof(struct in_addr));

    // establish connections in parallel using thread pool
    pthread_t threads[num_connections];
    for (int i = 0; i < num_connections; i++) {
        int *sock_id = &sock[i];
        if (pthread_create(&threads[i], NULL, connectToServerThread, (void *) sock_id) != 0) { // thread creation failed
            perror("pthread_create");
            continue;
        }
    }

    for (int i = 0; i < num_connections; i++) {
        pthread_join(threads[i], NULL); // wait for threads to complete
    }
}

// thread function for establishing connection in parallel
