#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <float.h>

#define MAX_ELEMENTS 500 // default maximum capacity of the dynamic array
#define MAX_RANGE FLT_MAX // maximum range for validation

typedef struct {
    float *arr;
    size_t count, capacity;
} DynamicArray;

void createDynamicArray(DynamicArray *array) {
    array->capacity = MAX_ELEMENTS;
    array->count = 0;
    array->arr = (float *)malloc(sizeof(float) * array->capacity);
}

void destroyDynamicArray(DynamicArray *array) {
    free(array->arr);
    array->capacity = 0;
    array->count = 0;
    array->arr = NULL;
}

int validateInput(float input, float range) {
    if (input > -range && input < range) return 1;
    else return 0;
}

void processInput(DynamicArray *array, float input, float range) {
    if (!validateInput(input, range)) {
        printf("Invalid input: %f\n", input);
        return;
    }
    if (array->count == array->capacity) {
        // resize the array if necessary
        array->arr = (float *)realloc(array->arr, 2 * sizeof(float) * array->capacity);
        array->capacity *= 2;
    }
    array->arr[array->count++] = input;
}

void printArray(DynamicArray *array) {
    if (array->count == 0) {
        printf("Empty array\n");
        return;
    }
    for (int i = 0; i < array->count - 1; i++) {
        printf("%f ", array->arr[i]);
    }
    printf("%f\n", array->arr[array->count - 1]);
}

void calculateStats(DynamicArray *array) {
    float sum = 0, avg = 0;
    for (int i = 0; i < array->count; i++) {
        sum += array->arr[i];
    }
    if (array->count > 0) {
        avg = sum / array->count;
    } else {
        printf("No valid inputs found\n");
        return;
    }
    printf("Total count: %d\n", array->count);
    printf("Sum: %f\n", sum);
    printf("Average: %f\n", avg);
}

void sortArray(DynamicArray *array) {
    if (array->count > 0) {
        qsort(array->arr, array->count, sizeof(float), compareNumbers);
    }
}

int main() {
    DynamicArray array;
    createDynamicArray(&array);
    // read inputs from standard input
    float input, range = MAX_RANGE;
    while (scanf("%f", &input) == 1 && validateInput(input, range)) {
        processInput(&array, input, range);
    }
    // print the array
    printf("Array: ");
    printArray(&array);
    // calculate and print statistics
    calculateStats(&array);
    // sort the array in descending order without using any additional data structures
    sortArray(&array);
    // print the sorted array
    printf("Sorted array: ");
    printArray(&array);
    // destroy the dynamic array
    destroyDynamicArray(&array);
    return 0;
}']

