// Function to initialize the system-wide data structure for managing records
void init_records(int n, int min_val, int max_val, int buffer_size, long max_memory_kb) {
    // Allocate memory for the offset and keys arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));

    // Initialize the offset and keys arrays
    for (int i = 0; i < n; i++) {
        offsets[i] = i + 1;
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
