// Define the record structure
typedef struct {
    int key;
    long offset;
} record;

// Define the database structure
struct database {
    record* records; // Array of records
    size_t num_records; // Number of records in the database
    double key_increment_factor; // Increment factor for generating offsets
};

// Function to allocate and initialize a new record with a given key
record* alloc_record(int key) {
    record* r = (record*) malloc(sizeof(record));
    if (!r) {
        fprintf(stderr, "Error: unable to allocate memory for record\n");
        return NULL;
    }
    r->key = key;
    r->offset = (long) key * key_increment_factor;
    return r;
}

// Function to update the key increment factor dynamically
void update_key_increment_factor(double new_factor) {
    // Update the key increment factor only if it has changed
    if (new_factor != key_increment_factor) {
        key_increment_factor = new_factor;
        // Recompute offsets for all records in the database
        for (size_t i = 0; i < num_records; ++i) {
            records[i].offset = (long) records[i].key * key_increment_factor;
        }
    }
}

// Function to add a new record with a given key and value
int add_record(int key, int value) {
    // Check if the record already exists
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].key == key) {
            return -1; // Record with the same key already exists
        }
    }
    // Allocate a new record and add it to the database
    record* r = alloc_record(key);
    if (!r) {
        fprintf(stderr, "Error: unable to allocate memory for record\n");
        return -1;
    }
    records[num_records++] = *r;
    return 0;
}

// Function to update a record with a given key and value
int update_record(int key, int value) {
    // Find the record with the matching key
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].key == key) {
            records[i].value = value;
            return 0;
        }
    }
    // If the record is not found, add a new one
    return add_record(key, value);
}

// Function to query a range of records based on keys
void query_records(int start_key, int end_key) {
    // Iterate over all records within the specified range
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].key >= start_key && records[i].key <= end_key) {
            printf("%d: %ld\n", records[i].key, records[i].offset);
        }
    }
}

// Function to handle external data sources for reading initial keys and values from standard input
void read_keys(FILE* fp) {
