            add_record(key, 0); // Add the record with a default value of 0
        } else {
            fprintf(stderr, "Error: unable to read key from line %s\n", line);
        }
    }
}

// Function to handle concurrent client requests efficiently
void handle_client_request(int request) {
    // Handle the request based on its type
    switch (request) {
        case 1: // Add a new record with a given key and value
            add_record(key, value);
            break;
        case 2: // Update an existing record with a given key and value
            update_record(key, value);
            break;
        case 3: // Query records within a range of keys (inclusive)
            query_records(start_key, end_key);
            break;
    }
}

// Function to write data to disk periodically
void write_data() {
    // Write the database structure to disk
    FILE* fp = fopen("database.bin", "wb");
    if (fp) {
        fwrite(&num_records, sizeof(size_t), 1, fp);
        fwrite(&key_increment_factor, sizeof(double), 1, fp);
        for (size_t i = 0; i < num_records; ++i) {
            record* r = &records[i];
            fwrite(&r->key, sizeof(int), 1, fp);
            fwrite(&r->offset, sizeof(long), 1, fp);
        }
    } else {
        fprintf(stderr, "Error: unable to open file for writing\n");
    }
}

// Function to read data from disk on startup
void read_data() {
    // Read the database structure from disk
    FILE* fp = fopen("database.bin", "rb");
    if (fp) {
        fread(&num_records, sizeof(size_t), 1, fp);
        fread(&key_increment_factor, sizeof(double), 1, fp);
        records = (record*) malloc(num_records * sizeof(record));
        for (size_t i = 0; i < num_records; ++i) {
            record* r = &records[i];
            fread(&r->key, sizeof(int), 1, fp);
            fread(&r->offset, sizeof(long), 1, fp);
        }
    } else {
        fprintf(stderr, "Error: unable to open file for reading\n");
    }
}

// Main function to manage memory and perform database operations
