    while (1) {
        int request = 0; // Request type to be handled
        printf("Enter a request (1: add, 2: update, 3: query): ");
        scanf("%d", &request);

        switch (request) {
            case 1:
                int key = 0; // Key value to be added
                int value = 0; // Value for the new record
                printf("Enter a key and value: ");
