                add_record(key, value);
                break;
            case 2:
                int key = 0; // Key value to be updated
                int value = 0; // New value for the record
                printf("Enter a key and new value: ");
                scanf("%d %d", &key, &value);
                update_record(key, value);
                break;
            case 3:
                int start_key = 0; // Start of the range of keys to be queried (inclusive)
                int end_key = 0; // End of the range of keys to be queried (exclusive)
                printf("Enter a start and end key for the query: ");
                scanf("%d %d", &start_key, &end_key);
                query_records(start_key, end_key);
                break;
        }

        // Write data to disk periodically to prevent data loss
        if (time(NULL) - last_write > 10 * 60) { // Every 10 minutes
            write_data();
            last_write = time(NULL);
        }
    }

    return 0;
}
