};

// Define the function for managing the dataset
void manage_dataset(struct dataset* dataset, int key, double measurement) {
    // Check if the key is already in the dataset
    struct record* record = NULL;
    for (size_t i = 0; i < dataset->size; i++) {
        if (dataset->records[i]->key == key) {
            record = dataset->records[i];
            break;
        }
    }

    // If the key is not in the dataset, add a new record
    if (record == NULL) {
        // Check if the capacity of the dataset has been reached
        if (dataset->size >= dataset->capacity) {
            // Double the capacity of the dataset and reallocate memory for the records array
            size_t new_capacity = dataset->capacity * 2;
            struct record** new_records = malloc_wrapper(new_capacity * sizeof(struct record*));
            memcpy(new_records, dataset->records, dataset->size);
            free_wrapper(dataset->records);
            dataset->records = new_records;
            dataset->capacity = new_capacity;
