void periodic_archival(struct dataset* dataset) {
    // Set up a timer for periodic archival
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double interval = 60.0 * 60.0 * 24.0; // Archival interval: once every 24 hours
    double next_archival_time = (double) ts.tv_sec + interval;
    while (true) {
        // Check if it's time for archival
        struct timespec current_ts;
        clock_gettime(CLOCK_REALTIME, &current_ts);
        double current_time = (double) current_ts.tv_sec + (double) current_ts.tv_nsec / 1000000000.0;
        if (current_time >= next_archival_time) {
            // Archive the old records and update the archival time
            archive_old_records(dataset);
            clock_gettime(CLOCK_REALTIME, &ts);
            next_archival_time = (double) ts.tv_sec + interval;
        } else {
            // Sleep for a while before checking again
            struct timespec sleep_ts;
            double sleep_time = next_archival_time - current_time;
            sleep_ts.tv_nsec = (long) (sleep_time * 1000000000);
            nanosleep(&sleep_ts, NULL);
        }
    }
