using namespace std;

class CompressionFramework {
public:
    // Constructor and destructor
    CompressionFramework() {}
    ~CompressionFramework() {}

    // Static member variable to store the current compression configuration
    static CompressionConfig config;

    // Function to set the compression algorithm and level at runtime
    void setCompressionAlgorithm(CompressionAlgorithm algorithm, int level) {
        config.algorithm = algorithm;
        config.level = level;
    }

    // Function to compress data using the current configuration
    string compress(string inputData) {
        switch (config.algorithm) {
            case CompressionAlgorithm::DEFLATE:
                return deflateCompress(inputData, config.level);
            case CompressionAlgorithm::LZMA:
                return lzmaCompress(inputData, config.level);
            case CompressionAlgorithm::ZSTD:
                return zstdCompress(inputData, config.level);
        }
    }

    // Function to decompress data using the current configuration
    string decompress(string compressedData) {
        switch (config.algorithm) {
            case CompressionAlgorithm::DEFLATE:
                return deflateDecompress(compressedData, config.level);
            case CompressionAlgorithm::LZMA:
                return lzmaDecompress(compressedData, config.level);
            case CompressionAlgorithm::ZSTD:
                return zstdDecompress(compressedData, config.level);
        }
    }
};

// Implementation of the compression functions using Zlib library
string deflateCompress(string inputData, int level) {
    // Initialize the compressor with the specified level and window size
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    deflateInit(&strm, level);

    // Compress the input data using the compressor
    string outputData = "";
    int result = 0;
    do {
        char in[CHUNK] = {};
        char out[CHUNK] = {};
        strm.avail_in = fread(in, 1, CHUNK, inputData);
        if (strm.avail_in == 0) break;
        strm.next_in = in;
        do {
            strm.avail_out = CHUNK;
            strm.next_out = out;
            result = deflate(&strm, Z_FINISH);
            if (result == Z_STREAM_END) break;
            outputData += string(out, strm.avail_out);
        } while (result == Z_OK);
    } while (result == Z_OK);

    // Clean up and return the compressed data
    deflateEnd(&strm);
    return outputData;
}

