    CLzmaEncProps props;
    LzmaEncProps_Init(&props);
    LzmaEnc_SetProps(encHandle, &props);

    // Compress the input data using the compressor
    string outputData = "";
    int result = 0;
    do {
        char in[CHUNK] = {};
        char out[CHUNK] = {};
