    for (int i = 0; i < num_records; i++) {
        event->records[i].offset = incr_factor * i;
    }

    return event;
}

// Function to dynamically allocate memory for a record, containing a long offset, an int key, a double value, and a dynamically allocated string label.
struct event_record* create_record(long offset, int key, double value, char* label) {
    struct event_record* record = alloc_record(sizeof(struct event_record));
    if (record == NULL) {
        printf("Error: Out of memory\n");
        return NULL;
    }

