struct Attack {
    std::string name;
    double value;
};

class DynamicAttackManager {
public:
    DynamicAttackManager() : max_name_length(0), min_value(-std::numeric_limits<double>::max()), max_value(std::numeric_limits<double>::max()) {}

    ~DynamicAttackManager() {
        for (auto& attack : attacks) {
            delete attack.second;
        }
    }

    void insert(const std::string& name, double value) {
        auto it = attacks.find(name);
        if (it != attacks.end()) {
            it->second->value = value;
        } else {
            Attack* new_attack = new Attack{name, value};
            attacks[name] = new_attack;
            max_name_length = std::max(max_name_length, name.size());
            min_value = std::min(min_value, value);
            max_value = std::max(max_value, value);
        }
    }

    void delete(const std::string& name) {
        auto it = attacks.find(name);
        if (it != attacks.end()) {
            delete it->second;
            attacks.erase(it);
            --num_attacks;
        }
    }

    Attack* find(const std::string& name) const {
        auto it = attacks.find(name);
        if (it != attacks.end()) {
            return it->second;
        } else {
            return nullptr;
        }
    }

    void print_longest_attack() const {
        std::cout << "Longest attack: ";
        auto longest = *std::max_element(attacks.begin(), attacks.end(), [](const auto& a, const auto& b) { return a->name.size() < b->name.size(); });
        std::cout << longest->name << " (" << longest->value << ")" << std::endl;
    }

    void print_attack(const std::string& name) const {
        auto attack = find(name);
        if (attack != nullptr) {
            std::cout << "Attack: " << attack->name << " (" << attack->value << ")" << std::endl;
        } else {
            std::cout << "Attack not found!" << std::endl;
        }
    }

    void update_max_name_length() {
        max_name_length = 0;
        for (const auto& attack : attacks) {
            max_name_length = std::max(max_name_length, attack.first.size());
        }
    }

    void update_min_value(double value) {
        min_value = std::min(min_value, value);
    }

    void update_max_value(double value) {
        max_value = std::max(max_value, value);
    }

private:
    std::unordered_map<std::string, Attack*> attacks;
    size_t num_attacks = 0;
    size_t max_name_length = 0;
    double min_value = std::numeric_limits<double>::max();
    double max_value = -std::numeric_limits<double>::max();
};
```

