        (*data_points)[i].value = rand()%((max_val-min_val)*1000 + 1) / 1000.0 + min_val; // Generate random value within range
    }
}

// Define function to validate data and return compressed array
void compress(int n, int max_memory_mb, double max_avg_abs, data_point **data_points, char ***identifiers) {
    // Compress identifiers array by removing duplicates
    int *unique = (int*)malloc(sizeof(int)*n);
    if (unique == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for unique identifier indices\n");
        exit(1);
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (!unique[i]) { // If current index is not a duplicate, set it as a unique index and increment count
            unique[i] = 1;
            count++;
        } else { // Else, mark current index as a duplicate and skip to next iteration
            continue;
        }
    }
    *identifiers = (char**)malloc(sizeof(char*)*count);
    if (*identifiers == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for compressed identifiers array\n");
        exit(1);
    }
    int index = 0;
    for (int i = 0; i < n; i++) {
        if (!unique[i]) { // If current index is a unique index, copy identifier string and increment compressed index
            strcpy((*identifiers)[index++], (*identifiers)[i]);
        }
    }

    // Compress data points array by removing duplicates and calculating average absolute value of values
    int *unique_values = (int*)malloc(sizeof(int)*n);
    if (unique_values == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for unique value indices\n");
        exit(1);
    }
    count = 0;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        if (!unique_values[i]) { // If current index is not a duplicate, set it as a unique index and increment count
            unique_values[i] = 1;
            count++;
            sum += (*data_points)[i].value;
        } else { // Else, mark current index as a duplicate and skip to next iteration
            continue;
        }
    }
    *data_points = (data_point*)malloc(sizeof(data_point)*count);
    if (*data_points == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for compressed data points array\n");
        exit(1);
    }
    index = 0;
    double avg = sum / count; // Calculate average absolute value of values in the compressed array
    if (avg > max_avg_abs) { // If average absolute value exceeds maximum threshold, return error code
        fprintf(stderr, "Error: average absolute value of data points exceeds maximum threshold\n");
        exit(1);
    } else { // Else, copy compressed array and return with success
        for (int i = 0; i < count; i++) {
            (*data_points)[index++] = (*data_points)[i];
        }
    }
}

// Define function to free memory allocated by init_arrays
void free_memory(data_point **data_points, char ***identifiers) {
    // Free data points array and identifiers array
    if (*data_points != NULL) {
        free(*data_points);
    }
    if (*identifiers != NULL) {
        for (int i = 0; i < (*identifiers)[i]; i++) {
            free((*identifiers)[i]);
        }
        free(*identifiers);
    }
}
