typedef struct {
    int rnti;
    char cell_id[20];
    double timestamp;
} LTE_PHY_RX_API_UU_RXINDICATIONS;

// Memory pool for allocating and managing memory
struct memory_pool {
    size_t capacity;  // total number of elements in the pool
    size_t size;      // current number of allocated elements
    LTE_PHY_RX_API_UU_RXINDICATIONS *array;
};

// Dynamic array for storing LTE_PHY_RX_API_UU_RXINDICATIONS structures
struct dynamic_array {
    size_t capacity;  // total number of elements in the array
    size_t size;      // current number of allocated elements
    LTE_PHY_RX_API_UU_RXINDICATIONS *data;
};

// Memory allocator for dynamic arrays
void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("malloc");
        exit(1);
    }
    return ptr;
}

// Memory deallocator for dynamic arrays
void free_memory(void *ptr) {
    free(ptr);
}

// Initialize a memory pool with the specified capacity
struct memory_pool* initialize_memory_pool(size_t capacity) {
    struct memory_pool* pool = (struct memory_pool*) allocate_memory(sizeof(struct memory_pool));
    pool->capacity = capacity;
    pool->size = 0;
    pool->array = (LTE_PHY_RX_API_UU_RXINDICATIONS *) allocate_memory(capacity * sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS));
    return pool;
}

// Free a memory pool and its associated memory
void free_memory_pool(struct memory_pool* pool) {
    if (!pool) {
        return;
    }
    free_memory(pool->array);
    free_memory(pool);
}

// Initialize a dynamic array with the specified capacity
struct dynamic_array* initialize_dynamic_array(size_t capacity) {
    struct dynamic_array* arr = (struct dynamic_array*) allocate_memory(sizeof(struct dynamic_array));
    arr->capacity = capacity;
    arr->size = 0;
    arr->data = (LTE_PHY_RX_API_UU_RXINDICATIONS *) allocate_memory(capacity * sizeof(LTE_PHY_RX_API_UU_RXINDICATIONS));
    return arr;
}

// Free a dynamic array and its associated memory
void free_dynamic_array(struct dynamic_array* arr) {
    if (!arr) {
        return;
    }
    free_memory(arr->data);
    free_memory(arr);
}

// Append a new LTE_PHY_RX_API_UU_RXINDICATIONS structure to the dynamic array
bool append_to_dynamic_array(struct dynamic_array* arr, int rnti, char cell_id[20], double timestamp) {
    if (arr->size == arr->capacity) {
        return false;
    }
    LTE_PHY_RX_API_UU_RXINDICATIONS *elem = &(arr->data[arr->size++]);
    elem->rnti = rnti;
    strncpy(elem->cell_id, cell_id, 20);
    elem->timestamp = timestamp;
    return true;
}

// Clear the dynamic array and reset its size to zero
void clear_dynamic_array(struct dynamic_array* arr) {
    arr->size = 0;
}

// Serialize the dynamic array to a file in binary format
bool serialize_to_file(struct dynamic_array* arr, const char *filename) {
    FILE *fptr = fopen(filename, "wb");
    if (!fptr) {
        perror("fopen");
        return false;
    }
    for (size_t i = 0; i < arr->size; ++i) {
        LTE_PHY_RX_API_UU_RXINDICATIONS *elem = &(arr->data[i]);
        if (fwrite(&(elem->rnti), sizeof(int), 1, fptr) != 1 ||
