        return false;
    }
    while (arr->size < arr->capacity && !feof(fptr)) {
        LTE_PHY_RX_API_UU_RXINDICATIONS *elem = &(arr->data[arr->size++]);
        if (fread(&(elem->rnti), sizeof(int), 1, fptr) != 1 ||
