            fread(&(elem->timestamp), sizeof(double), 1, fptr) != 1) {
            perror("fread");
            return false;
        }
    }
    if (fclose(fptr) == EOF) {
        perror("fclose");
        return false;
    }
    return true;
}

// Filter the dynamic array based on configurable criteria such as RNTI range, cell ID, or time window
void filter_dynamic_array(struct dynamic_array* arr, int rnti_min, int rnti_max, char cell_id[20], double timestamp) {
    for (size_t i = 0; i < arr->size; ++i) {
        LTE_PHY_RX_API_UU_RXINDICATIONS *elem = &(arr->data[i]);
        if ((rnti_min <= elem->rnti && elem->rnti <= rnti_max) ||
            (cell_id != NULL && strncmp(elem->cell_id, cell_id, 20) == 0) ||
            (timestamp != 0.0 && fabs(elem->timestamp - timestamp) < 1e-9)) {
            // Element meets filter criteria; do nothing
        } else {
            // Element does not meet filter criteria; swap with the last element and decrease size
            arr->size--;
            if (i != arr->size) {
