    bool is_enabled; // Whether the logging framework is enabled or not
    FILE *log_file; // Log file handle
    uint64_t total_entries; // Total number of log entries generated so far
} LOGGING_FRAMEWORK;

// Define the structure to represent a traffic management system
typedef struct {
    bool is_enabled; // Whether the traffic management system is enabled or not
    uint32_t *flows; // Array of flow IDs (from 0 to N-1)
    uint32_t n_flows; // Number of flows in the array
} TRAFFIC_MANAGEMENT_SYSTEM;

// Define the structure to represent a dynamic array of LTE PHY RX indications
typedef struct {
    LTE_PHY_RX_API_UU_RXINDICATIONS **array; // Array of LTE PHY RX indication structures
    uint32_t size; // Size of the array (in number of elements)
    uint32_t count; // Number of valid elements in the array
} DYNAMIC_ARRAY;

// Define the structure to represent a routing table
typedef struct {
    ROUTING_TABLE_ENTRY **table; // Array of routing table entries
    uint32_t size; // Size of the routing table (in number of rows)
    uint32_t count; // Number of valid routing table entries
} ROUTING_TABLE;

// Define the structure to represent a QoS policy table
typedef struct {
    QOS_POLICY **table; // Array of QoS policy structures
    uint32_t size; // Size of the QoS policy table (in number of rows)
    uint32_t count; // Number of valid QoS policy entries
} QOS_POLICY_TABLE;

