#include <sys/stat.h>
#include <fcntl.h>

// Global variables
int total_memory = 0; // Total memory usage in bytes
int increment_factor = 10; // Increment factor for seat number offset
int *seat_numbers; // Array of seat numbers
int num_reservations = 0; // Number of reservations
int *ticket_availability; // Array of ticket availability statuses
int *event_keys; // Array of event keys
char *csv_file; // CSV file for exporting reservations
struct timespec last_update; // Time of the last update

// Function to dynamically manage memory for the large-scale event ticket reservation system
void manage_memory(int key, int seat_number) {
    // Increment total memory usage
    total_memory += sizeof(int);

    // Check if there is enough memory to allocate new reservations
    if (total_memory >= 10 * 1024 * 1024) {
        printf("Not enough memory to allocate new reservation\n");
        return;
    }

    // Allocate new memory for the reservation
    seat_numbers = realloc(seat_numbers, (num_reservations + 1) * sizeof(int));
    event_keys = realloc(event_keys, (num_reservations + 1) * sizeof(int));
    ticket_availability = realloc(ticket_availability, (num_reservations + 1) * sizeof(int));

    // Initialize the new reservation
    seat_numbers[num_reservations] = key * increment_factor;
    event_keys[num_reservations] = key;
    ticket_availability[num_reservations] = 1;

    // Increment the number of reservations
    num_reservations++;
}

// Function to dynamically manage memory for the large-scale event ticket reservation system
void free_memory(int key) {
    // Find the index of the reservation with the given key
    int i;
    for (i = 0; i < num_reservations; i++) {
        if (event_keys[i] == key) {
            break;
        }
    }

    // Check if the reservation was found
    if (i >= num_reservations) {
        printf("Reservation with key %d not found\n", key);
        return;
    }

    // Decrement total memory usage
    total_memory -= sizeof(int);

    // Free the memory for the reservation
    free(seat_numbers[i]);
    free(event_keys[i]);
    free(ticket_availability[i]);

    // Shift the elements in the arrays to fill the gap left by the freed reservation
    memmove(&seat_numbers[i], &seat_numbers[i + 1], (num_reservations - i - 1) * sizeof(int));
    memmove(&event_keys[i], &event_keys[i + 1], (num_reservations - i - 1) * sizeof(int));
    memmove(&ticket_availability[i], &ticket_availability[i + 1], (num_reservations - i - 1) * sizeof(int));

    // Decrement the number of reservations
    num_reservations--;
}

// Function to track total memory usage in bytes
int get_total_memory() {
    return total_memory;
}

// Function to query reservations within a specified key range
void query_reservations(int start, int end) {
    // Find the indices of the first and last reservations in the range
    int i = 0;
    while (i < num_reservations && event_keys[i] < start) {
        i++;
    }
    int j = num_reservations - 1;
    while (j >= 0 && event_keys[j] > end) {
        j--;
    }

    // Print the reservations within the range
    for (int k = i; k <= j; k++) {
        printf("Reservation with key %d and seat number %d\n", event_keys[k], seat_numbers[k]);
    }
}

