    table->size = init_size;
    table->num_nodes = min_nodes;
    table->nodes = (struct node**) calloc(init_size, sizeof(struct node*));
    return table;
}

// Load data from file into the hash table
void load_data(const char* input_file, struct hash_table* table) {
