// Add a new node to the hash table with the given identifier, timestamp, and weight
void add_node(struct hash_table* table, const char* identifier, int timestamp, double weight) {
    // Check if the hash table needs to be resized
    if (table->num_nodes >= table->size * 0.75) {
        resize_hash_table(table);
    }

    // Calculate the hash value for the identifier
    size_t hash = hash(identifier);

    // Find the index of the bucket to store the node in
    int index = hash % table->size;

    // Create a new node and add it to the bucket
    struct node* new_node = (struct node*) malloc(sizeof(struct node));
    new_node->identifier = identifier;
    new_node->timestamp = timestamp;
    new_node->record = (struct record*) malloc(sizeof(struct record));
    new_node->record->value = value;
    new_node->record->weight = weight;
    new_node->next = table->nodes[index];
    table->nodes[index] = new_node;
}

// Resize the hash table to double its size and rehash all nodes
void resize_hash_table(struct hash_table* table) {
    // Create a new hash table with twice the size of the current one
    struct hash_table* new_table = (struct hash_table*) malloc(sizeof(struct hash_table));
    new_table->size = table->size * 2;
    new_table->num_nodes = 0;
    new_table->nodes = (struct node**) calloc(new_table->size, sizeof(struct node*));

    // Rehash all nodes in the old hash table to the new one
    for (int i = 0; i < table->size; ++i) {
        struct node* current = table->nodes[i];
        while (current != NULL) {
            size_t new_hash = hash(current->identifier);
            int new_index = new_hash % new_table->size;
            struct node* new_node = (struct node*) malloc(sizeof(struct node));
            new_node->identifier = current->identifier;
            new_node->timestamp = current->timestamp;
            new_node->record = current->record;
            new_node->next = new_table->nodes[new_index];
            new_table->nodes[new_index] = new_node;
            current = current->next;
        }
    }

    // Free memory for the old hash table and replace it with the new one
    free(table);
    table = new_table;
}

// Serialize the entire data structure to a file using a binary format
void serialize_data(const char* output_file, struct hash_table* table) {
    FILE* fp = fopen(output_file, "wb");
    if (fp == NULL) {
        perror("Error opening output file");
        return;
    }

    // Write the number of nodes to the file
    int num_nodes = table->num_nodes;
    fwrite(&num_nodes, sizeof(int), 1, fp);

    // Write each node to the file in order
    for (int i = 0; i < table->size; ++i) {
        struct node* current = table->nodes[i];
        while (current != NULL) {
            fwrite(current->identifier, sizeof(char), strlen(current->identifier), fp);
            fwrite(&current->timestamp, sizeof(int), 1, fp);
            fwrite(&current->record->value, sizeof(int), 1, fp);
            fwrite(&current->record->weight, sizeof(double), 1, fp);
            current = current->next;
        }
    }

    fclose(fp);
}

// Free memory for the hash table and its nodes
void free_memory(struct hash_table* table) {
    for (int i = 0; i < table->size; ++i) {
        struct node* current = table->nodes[i];
        while (current != NULL) {
            struct node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->nodes);
    free(table);
}
```
