void allocateAndInitializeArrays(int longSize, int intSize, int doubleSize, struct record *recordArr, int recordCount) {
    // Allocate memory for arrays of long, int, and double
    long *longArr = (long *)malloc(longSize * sizeof(long));
    int *intArr = (int *)malloc(intSize * sizeof(int));
    double *doubleArr = (double *)malloc(doubleSize * sizeof(double));

    // Initialize arrays of long, int, and double
    for (int i = 0; i < longSize; i++) {
        longArr[i] = i + 1;
    }
    for (int i = 0; i < intSize; i++) {
        intArr[i] = i + 1;
    }
    for (int i = 0; i < doubleSize; i++) {
        doubleArr[i] = (double)i / 2.0;
    }

    // Initialize custom record structure array
    for (int i = 0; i < recordCount; i++) {
        struct record *record = &(recordArr[i]);
        record->id = i + 1;
        record->value = (double)i / 2.0;
        strcpy(record->name, "Record ");
        strcat(record->name, (char*)(&(record->id)));
    }
}

void executeCommand(const char *command, const char *targetDirectory) {
    // Ensure target directory exists and create it if necessary
    struct stat dirStat;
    if (stat(targetDirectory, &dirStat) != 0 || !S_ISDIR(dirStat.st_mode)) {
        mkdir(targetDirectory, 0755);
    }

    // Execute specified command using `Runtime.getRuntime().exec()`
    FILE *fPipe = popen(command, "r");
    if (!fPipe) {
        printf("Error executing command: %s\n", command);
        exit(EXIT_FAILURE);
    }

    // Redirect standard input and error streams to `PipedInputStream` and `PipedOutputStream` for inter-process communication
    FILE *fStdout = fopen("stdout.txt", "w");
    FILE *fStderr = fopen("stderr.txt", "w");

    // Implement a timeout mechanism to prevent indefinite hang-ups
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long int startTime = (long int)(tv.tv_sec * 1000) + (long int)(tv.tv_usec / 1000);

    // Read from the pipe until end-of-file or timeout occurs
    while (!feof(fPipe)) {
        if ((long int)(tv.tv_sec * 1000) + (long int)(tv.tv_usec / 1000) - startTime > 1000) { // 1 second timeout
            printf("Timeout occurred, terminating...\n");
            break;
        }
        char buffer[128];
        fgets(buffer, sizeof(buffer), fPipe);
        fputs(buffer, fStdout);
    }

    // Close file streams and pipes
    pclose(fPipe);
    fclose(fStdout);
    fclose(fStderr);
}

void deleteDirectory(const char *directory) {
    // Delete specified directory if it exists prior to execution
    if (remove(directory)) {
        printf("Error deleting directory: %s\n", directory);
        exit(EXIT_FAILURE);
    }
}

int main() {
    // Define memory limit and array sizes
    const int MEMORY_LIMIT = 1024 * 1024; // 1 MB
    const int LONG_SIZE = 100;
    const int INT_SIZE = 50;
    const int DOUBLE_SIZE = 20;
    const int RECORD_COUNT = 10;

    manageMemory(MEMORY_LIMIT); // Verify available system memory and exit if insufficient

