    char remote_ip_address[16]; // IPv4/IPv6 address string
    unsigned short remote_port;
} TCP_CONNECTION_INFO;

// Dynamic array for storing TCP connection information
static TCP_CONNECTION_INFO **connections = NULL;
static int connections_count = 0;
static int connections_capacity = 0;

// Function to append a new connection to the dynamic array
int add_connection(const char *ip_address, unsigned short port) {
    if (connections == NULL || connections_count >= connections_capacity) {
        // Allocate more memory for the connections array if necessary
        connections = realloc(connections, sizeof(TCP_CONNECTION_INFO*) * (connections_capacity + 1));
        if (connections == NULL) {
            fprintf(stderr, "Failed to allocate memory for connections array\n");
            return -1;
        }
        // Initialize the new connection structure and add it to the array
        TCP_CONNECTION_INFO *connection = malloc(sizeof(TCP_CONNECTION_INFO));
        if (connection == NULL) {
            fprintf(stderr, "Failed to allocate memory for a new connection\n");
            return -1;
        }
        connection->connection_id = connections_count;
        inet_pton(AF_INET6, ip_address, &connection->remote_ip_address);
        connection->remote_port = port;
        connections[connections_count] = connection;
        ++connections_count;
    } else {
        // Add the new connection to the end of the array
        TCP_CONNECTION_INFO *connection = malloc(sizeof(TCP_CONNECTION_INFO));
        if (connection == NULL) {
            fprintf(stderr, "Failed to allocate memory for a new connection\n");
            return -1;
        }
        connection->connection_id = connections_count;
        inet_pton(AF_INET6, ip_address, &connection->remote_ip_address);
        connection->remote_port = port;
        connections[connections_count] = connection;
        ++connections_count;
    }
    return 0;
}

// Function to remove a connection from the dynamic array
int remove_connection(int connection_id) {
    // Check if the connection exists in the array
    for (int i = 0; i < connections_count; ++i) {
        if (connections[i]->connection_id == connection_id) {
            TCP_CONNECTION_INFO *connection = connections[i];
            // Free the memory allocated to the connection structure
            free(connection);
            --connections_count;
            break;
        }
    }
    return 0;
}

// Function to retrieve a connection from the dynamic array by its ID
TCP_CONNECTION_INFO* get_connection(int connection_id) {
    for (int i = 0; i < connections_count; ++i) {
        if (connections[i]->connection_id == connection_id) {
            return connections[i];
        }
    }
    // Connection not found in the array
    return NULL;
}

// Function to clear the dynamic array safely and reuse it for subsequent operations
void clear_connections() {
    if (connections != NULL) {
        for (int i = 0; i < connections_count; ++i) {
            free(connections[i]);
        }
        free(connections);
        connections = NULL;
        connections_count = 0;
        connections_capacity = 0;
    }
}
```
