// Function to allocate memory for a log entry
struct LogEntry* allocLogEntry(uint64_t timestamp, char* message, int priority, void* metadata) {
  struct LogEntry* entry = malloc(sizeof(struct LogEntry));
  if (entry == NULL) {
    return NULL;
  }

