}

// Function to retrieve a log entry from the hash table
struct LogEntry* getLogEntryFromTable(struct LogHashTable* table, uint64_t timestamp) {
  // Lock the mutex to synchronize access to the hash table
  pthread_mutex_lock(&table->mutex);

  // Find the index of the log entry in the hash table
  int index = findIndexOfLogEntry(table, timestamp);

