        // Method for deflating data using the DEFLATE algorithm
        std::vector<unsigned char> deflate(const std::vector<unsigned char>& data, int level) {
            // Initialize zlib stream with default compression options
            z_stream strm = {};
            strm.zalloc = Z_NULL;
            strm.zfree = Z_NULL;
            strm.opaque = Z_NULL;
            deflateInit(&strm, level);

            // Allocate memory for compressed data
            std::vector<unsigned char> out(data.size() * 1.5 + 16);

            // Compress input data in chunks of manageable size
            const int CHUNK_SIZE = 1024;
            unsigned long totalIn = 0, totalOut = 0;
            while (totalIn < data.size()) {
                strm.avail_in = std::min(CHUNK_SIZE, data.size() - totalIn);
                strm.next_in = reinterpret_cast<Bytef*>(const_cast<unsigned char*>(&data[totalIn]));
                deflate(&strm, Z_NO_FLUSH);

                // Make sure we have enough space in the output buffer for compressed data
                unsigned long outSize = strm.avail_out;
                if (totalOut + outSize > out.size()) {
                    out.resize(totalOut + outSize * 2);
                }

                // Copy compressed data to output buffer
                memcpy(&out[totalOut], strm.next_out, outSize);
                totalOut += outSize;
            }

            // Finish compression and return compressed data
            deflateEnd(&strm);
            out.resize(totalOut);
            return out;
        }

        // Method for LZMA compressing data using the LZMA algorithm
        std::vector<unsigned char> lzma_compress(const std::vector<unsigned char>& data, int level) {
            // Initialize LZMA stream with default compression options
            auto strm = lzmastream(lzmastream());
            strm.setLevel(level);

            // Allocate memory for compressed data
            std::vector<unsigned char> out(data.size() * 1.5 + 16);

            // Compress input data in chunks of manageable size
            const int CHUNK_SIZE = 1024;
            unsigned long totalIn = 0, totalOut = 0;
            while (totalIn < data.size()) {
                strm.avail_in = std::min(CHUNK_SIZE, data.size() - totalIn);
                strm.next_in = reinterpret_cast<Bytef*>(const_cast<unsigned char*>(&data[totalIn]));
                strm.avail_out = out.size() - totalOut;
                strm.next_out = reinterpret_cast<Bytef*>(&out[totalOut]);
                lzma_code(strm, LZMA_FINISH);

                // Make sure we have enough space in the output buffer for compressed data
                totalOut += strm.avail_out;
            }

            // Finish compression and return compressed data
            out.resize(totalOut);
            return out;
        }

        // Method for ZSTD compressing data using the ZSTD algorithm
        std::vector<unsigned char> zstd_compress(const std::vector<unsigned char>& data, int level) {
            // Initialize ZSTD stream with default compression options
            auto strm = zstdstream(zstdstream());
            strm.setLevel(level);

            // Allocate memory for compressed data
            std::vector<unsigned char> out(data.size() * 1.5 + 16);

            // Compress input data in chunks of manageable size
            const int CHUNK_SIZE = 1024;
            unsigned long totalIn = 0, totalOut = 0;
            while (totalIn < data.size()) {
                strm.avail_in = std::min(CHUNK_SIZE, data.size() - totalIn);
                strm.next_in = reinterpret_cast<Bytef*>(const_cast<unsigned char*>(&data[totalIn]));
                strm.avail_out = out.size() - totalOut;
                strm.next_out = reinterpret_cast<Bytef*>(&out[totalOut]);
                zstd_code(strm, ZSTD_FINISH);

                // Make sure we have enough space in the output buffer for compressed data
                totalOut += strm.avail_out;
            }

            // Finish compression and return compressed data
            out.resize(totalOut);
            return out;
        }

        // Method for deflating data using the DEFLATE algorithm
        std::vector<unsigned char> deflate(const std::vector<unsigned char>& data, int level) {
            // Initialize zlib stream with default compression options
            z_stream strm = {};
            strm.zalloc = Z_NULL;
            strm.zfree = Z_NULL;
            strm.opaque = Z_NULL;
            deflateInit(&strm, level);

            // Allocate memory for compressed data
            std::vector<unsigned char> out(data.size() * 1.5 + 16);

            // Compress input data in chunks of manageable size
            const int CHUNK_SIZE = 1024;
            unsigned long totalIn = 0, totalOut = 0;
            while (totalIn < data.size()) {
                strm.avail_in = std::min(CHUNK_SIZE, data.size() - totalIn);
                strm.next_in = reinterpret_cast<Bytef*>(const_cast<unsigned char*>(&data[totalIn]));
                deflate(&strm, Z_NO_FLUSH);

                // Make sure we have enough space in the output buffer for compressed data
                unsigned long outSize = strm.avail_out;
                if (totalOut + outSize > out.size()) {
                    out.resize(totalOut + outSize * 2);
                }

                // Copy compressed data to output buffer
                memcpy(&out[totalOut], strm.next_out, outSize);
                totalOut += outSize;
            }

            // Finish compression and return compressed data
            deflateEnd(&strm);
            out.resize(totalOut);
            return out;
        }

        // Method for LZMA decompressing data using the LZMA algorithm
        std::vector<unsigned char> lzma_decompress(const std::vector<unsigned char>& data, int level) {
            // Initialize LZMA stream with default compression options
            auto strm = lzmastream(lzmastream());
            strm.setLevel(level);

            // Allocate memory for decompressed data
            std::vector<unsigned char> out(data.size() * 2 + 16);

            // Decompress input data in chunks of manageable size
            const int CHUNK_SIZE = 1024;
            unsigned long totalIn = 0, totalOut = 0;
            while (totalIn < data.size()) {
                strm.avail_in = std::min(CHUNK_SIZE, data.size() - totalIn);
                strm.next_in = reinterpret_cast<Bytef*>(const_cast<unsigned char*>(&data[totalIn]));
                strm.avail_out = out.size() - totalOut;
                strm.next_out = reinterpret_cast<Bytef*>(&out[totalOut]);
                lzma_code(strm, LZMA_FINISH);

                // Make sure we have enough space in the output buffer for decompressed data
                totalOut += strm.avail_out;
            }

            // Finish decompression and return decompressed data
            out.resize(totalOut);
            return out;
        }

        // Method for ZSTD decompressing data using the ZSTD algorithm
        std::vector<unsigned char> zstd_decompress(const std::vector<unsigned char>& data, int level) {
            // Initialize ZSTD stream with default compression options
            auto strm = zstdstream(zstdstream());
            strm.setLevel(level);

            // Allocate memory for decompressed data
            std::vector<unsigned char> out(data.size() * 2 + 16);

            // Decompress input data in chunks of manageable size
