void allocArrays(int numRecords) {
    // Calculate the total size needed for the arrays
    long offsetSize = sizeof(long) * numRecords;
    int keySize = sizeof(int) * numRecords;
    char identifierSize = strlen("Hello World!") + 1; // +1 for the null terminator

    // Allocate memory for the arrays
    long *offsets = (long *) malloc(offsetSize);
    int *keys = (int *) malloc(keySize);
    char **identifiers = (char **) malloc(sizeof(char *) * numRecords);

    // Initialize the arrays with random values
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand() % INT_MAX;
        offsets[i] = keys[i] * 10 + i;
        identifiers[i] = malloc(identifierSize);
    }
}

// Function to deallocate the memory allocated for the arrays
void deallocArrays(long *offsets, int *keys, char **identifiers) {
    // Free the memory used by each element in the arrays
    free(offsets);
    free(keys);
    for (int i = 0; i < numRecords; i++) {
        free(identifiers[i]);
    }
}

