    // Initialize variables to keep track of the largest integer and longest string
    int largestInteger = INT_MIN;
    char *longestString = NULL;

    for (int i = 0; i < numRecords; i++) {
        if (keys[i] > largestInteger) {
            largestInteger = keys[i];
        }

        // Check if the current string is longer than the longest string found so far
        int strLen = strlen(identifiers[i]);
        if (strLen > strlen(longestString)) {
            longestString = identifiers[i];
        }
    }

    printf("Largest integer: %d\n", largestInteger);
    printf("Longest string: %s\n", longestString);
