class DNSCache {
public:
    DNSCache() {}

    ~DNSCache() {}

    // Function to add a new entry to the cache or update an existing one
    void add(const std::string& hostname, const std::string& ip_address) {
        auto it = cache_.find(hostname);
        if (it != cache_.end()) {
            it->second.ip_address = ip_address;
        } else {
            cache_.emplace(hostname, HostnameIP{hostname, ip_address});
        }
    }

    // Function to retrieve a hostname's IP address from the cache
