    if (ptr == NULL) {
        printf("Error: Failed to allocate %zu bytes\n", size);
        exit(1);
    }
    return ptr;
}

void myFree(void* ptr) {
    free(ptr);
}

// Function to generate unique keys and labels for records
int generateUniqueKeyAndLabel(Record* record, int min_key, int max_key, char* label_prefix) {
    // Initialize key and label
    record->key = (rand() % (max_key - min_key)) + min_key;
    char buffer[10];
    sprintf(buffer, "%s%d", label_prefix, record->key);
    record->label = myAlloc(strlen(buffer) + 1);
    strcpy(record->label, buffer);

    // Check for duplicate keys or labels and adjust if necessary
    int i;
    for (i = 0; i < num_records; i++) {
        if (records[i].key == record->key || strcmp(records[i].label, record->label) == 0) {
            break;
        }
    }
    if (i != num_records) {
        // Key or label is not unique, generate new key and label
        do {
            record->key = (rand() % (max_key - min_key)) + min_key;
            sprintf(buffer, "%s%d", label_prefix, record->key);
            record->label = myAlloc(strlen(buffer) + 1);
            strcpy(record->label, buffer);
        } while (i != num_records && (records[i].key == record->key || strcmp(records[i].label, record->label) == 0));
    }

    return 0;
}

// Function to generate unique timestamps for records
time_t generateUniqueTimestamp() {
    // Initialize timestamp
    time_t timestamp = time(NULL);

    // Check for duplicate timestamps and adjust if necessary
    int i;
    for (i = 0; i < num_records; i++) {
        if (records[i].timestamp == timestamp) {
            break;
        }
    }
    if (i != num_records) {
        // Timestamp is not unique, generate new timestamp
        do {
            timestamp = time(NULL);
        } while (i != num_records && records[i].timestamp == timestamp);
    }

    return timestamp;
}

// Function to create and initialize a record structure
Record* createRecord() {
    Record* record = myAlloc(sizeof(Record));
    generateUniqueKeyAndLabel(record, MIN_KEY, MAX_KEY, LABEL_PREFIX);
    record->offset = 0;
    record->timestamp = generateUniqueTimestamp();
    return record;
}

// Function to add a record to the records array
void addRecord(Record* record) {
    // Check if maximum number of unique keys, labels, and timestamps has been reached
    if (num_records >= MAX_NUM_RECORDS) {
        printf("Error: Maximum number of unique keys, labels, and timestamps exceeded\n");
        exit(1);
    }

    // Add record to records array
    records[num_records++] = *record;
}

// Function to free all memory allocated for the records array
void freeRecords() {
    int i;
    for (i = 0; i < num_records; i++) {
        myFree(records[i].label);
    }
    myFree(records);
}
