// Define a record structure to store offset, key, and value
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define a function to initialize an array of records with random values
void init_records(Record* records, int num_records) {
    srand(time(NULL)); // seed the RNG

    for (int i = 0; i < num_records; i++) {
        records[i].offset = i * 1000000;
        records[i].key = rand() % 1000000;
        records[i].value = rand() % 1000000;
    }
}

// Define a function to find the largest integer in an array of records
int find_largest(Record* records, int num_records) {
    int largest = INT_MIN; // initialize with smallest possible value

    for (int i = 0; i < num_records; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }

    return largest;
}

// Define a function to deallocate an array of records
void deallocate(Record* records) {
    free(records);
}

int main() {
    // Read the number of records from standard input
    int num_records = 0;
    scanf("%d", &num_records);

    // Dynamically allocate an array of records with the given size
    Record* records = malloc(sizeof(Record) * num_records);

    // Initialize the array with random values
    init_records(records, num_records);

    // Find and print the largest integer in the array
    int largest = find_largest(records, num_records);
    printf("Largest integer: %d\n", largest);

    // Deallocate the memory used by the records array
    deallocate(records);

    return 0;
}
