    return 0;
}

// function to validate an integer for range and type correctness
int validate_integer(int* integer) {
    if (*integer < 0 || *integer > 1000000) { // out of range
        fprintf(stderr, "Error: integer is out of range\n");
        return -1;
    } else if (*integer % 2 != 0) { // not even
        fprintf(stderr, "Error: integer is not even\n");
        return -1;
    }
    return 0;
}

// function to add an integer to the array and update its frequency
void add_integer(int* integer) {
    pthread_mutex_lock(&mutex); // acquire the mutex
    if (integer_count == MAX_INTEGERS) { // maximum number of integers reached
        fprintf(stderr, "Error: maximum number of integers reached\n");
        return;
    }
    struct Integer* new_integer = malloc(sizeof(struct Integer)); // allocate memory for the integer
    if (new_integer == NULL) { // allocation failed
        perror("malloc");
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_integer->value = *integer; // set the value of the integer
    new_integer->frequency = 1; // set the frequency to 1
    integers[integer_count++] = new_integer; // add the integer to the array
    pthread_mutex_unlock(&mutex); // release the mutex
}

// function to remove an integer from the array and update its frequency
void remove_integer(int* integer) {
    pthread_mutex_lock(&mutex); // acquire the mutex
    for (size_t i = 0; i < integer_count; i++) { // loop through the integers in the array
        if (integers[i]->value == *integer) { // found the integer to remove
            struct Integer* removed_integer = integers[i]; // save the pointer to the removed integer
            integers[i] = integers[--integer_count]; // move the last integer to the current position
            free(removed_integer); // free the memory of the removed integer
            break; // stop the loop
        }
    }
    pthread_mutex_unlock(&mutex); // release the mutex
}

// function to log the processing time, memory consumption, and the top 10 most frequent integers
void log_statistics() {
    struct timespec start_time; // timestamp for the start of the logging interval
    struct timespec end_time; // timestamp for the end of the logging interval
    clock_gettime(CLOCK_REALTIME, &start_time); // get the current time
    pthread_mutex_lock(&mutex); // acquire the mutex
    for (size_t i = 0; i < integer_count; i++) { // loop through the integers in the array
        if (integers[i]->frequency > 0) { // only log the integers with non-zero frequency
            fprintf(stderr, "Integer %d occurred %d times\n", integers[i]->value, integers[i]->frequency);
        }
    }
    pthread_mutex_unlock(&mutex); // release the mutex
    clock_gettime(CLOCK_REALTIME, &end_time); // get the current time
    fprintf(stderr, "Logging interval: %ld seconds\n", (long)(end_time.tv_sec - start_time.tv_sec));
}

// function to handle incoming integers from multiple clients and process them concurrently
void* handle_client(void* arg) {
    int sock = *((int*)arg); // socket for the client
    int integer; // integer read from the client
    while (1) {
        if (read_integer(sock, &integer) < 0) { // error occurred during reading
            break;
        }
        validate_integer(&integer); // validate the integer
        add_integer(&integer); // add the integer to the array and update its frequency
    }
    remove_integer(&integer); // remove the integer from the array and update its frequency
    free(arg); // free the memory of the client socket
    return NULL;
}

// main function that starts the server and handles incoming clients
int main() {
    struct sockaddr_in server_address; // server address
    int server_sock = 0; // socket for the server
    pthread_t thread[MAX_CLIENTS]; // array of threads for handling incoming clients

    // initialize the server address and create a socket
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = htonl(INADDR_ANY);
    server_address.sin_port = htons(8080);
    if ((server_sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) { // error creating the socket
        perror("socket");
        return 1;
    }

    // bind the server address to the socket and listen for incoming clients
    if (bind(server_sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) { // error binding the socket
        perror("bind");
        close(server_sock);
        return 1;
    }
    if (listen(server_sock, MAX_CLIENTS) < 0) { // error listening for incoming clients
        perror("listen");
        close(server_sock);
        return 1;
    }

    // initialize the queue and mutex for managing incoming integers
    queue = malloc(sizeof(struct Queue));
    if (queue == NULL) { // allocation failed
        perror("malloc");
        close(server_sock);
        return 1;
    }
    pthread_mutex_init(&mutex, NULL);

    // start the logging thread
    pthread_create(&thread[0], NULL, log_statistics, NULL);

    // handle incoming clients concurrently and process their integers
    while (1) {
        int client_sock = accept(server_sock, NULL, NULL); // accept an incoming client connection
        if (client_sock < 0) { // error accepting the client connection
            perror("accept");
            close(server_sock);
            return 1;
        }
        pthread_create(&thread[1], NULL, handle_client, &client_sock); // create a thread to handle the client
    }
}
