// Define a function to allocate memory for an array of records
void allocateRecords(Record **records, size_t numRecords) {
    // Allocate memory for the record array using the specified allocation strategy
    if (ALLOCATION_STRATEGY_CONTIGUOUS) {
        *records = malloc(numRecords * sizeof(Record));
    } else {
