using namespace std;

// Attack structure to store attack name and strength
struct Attack {
    string name;
    double value;
};

// Vector of attacks to store all the attacks in memory
vector<Attack> attacks;

// Map to store all the attacks by their names for quick lookup
unordered_map<string, int> attackMap;

// Maximum length of the name of an attack
const int MAX_NAME_LENGTH = 256;

// Minimum and maximum acceptable values for the strength of an attack
const double MIN_VALUE = 0.1;
const double MAX_VALUE = 100.0;

// Cooldown period in seconds between two consecutive selections
const int COOLDOWN_PERIOD = 9;

// Time point when the last attack was selected
chrono::time_point<chrono::system_clock> lastAttackTime;

// Function to insert an attack into the collection
void insertAttack(const string& name, double value) {
    // Check if the name is within the acceptable range and the value is within the acceptable range
    if (name.length() <= MAX_NAME_LENGTH && value >= MIN_VALUE && value <= MAX_VALUE) {
        // Create a new attack structure with the given name and value
        Attack newAttack = { name, value };

        // Insert the new attack into the vector of attacks
        attacks.push_back(newAttack);

        // Insert the new attack into the map by its name
        attackMap[name] = attacks.size() - 1;
    } else {
        // Throw an exception if the name or value is not within the acceptable range
        throw invalid_argument("Invalid attack name or value");
    }
}

// Function to delete an attack from the collection by its name
void deleteAttack(const string& name) {
    // Check if the attack exists in the map
    auto it = attackMap.find(name);
    if (it != attackMap.end()) {
        // Get the index of the attack in the vector of attacks
        int index = it->second;

        // Remove the attack from the vector of attacks and the map
        attacks.erase(attacks.begin() + index);
        attackMap.erase(name);
    } else {
        // Throw an exception if the attack does not exist
        throw invalid_argument("Attack does not exist");
    }
}

// Function to retrieve an attack from the collection by its name
Attack getAttack(const string& name) {
    // Check if the attack exists in the map
    auto it = attackMap.find(name);
    if (it != attackMap.end()) {
        // Get the index of the attack in the vector of attacks
        int index = it->second;

        // Return the attack at the given index from the vector of attacks
        return attacks[index];
    } else {
        // Throw an exception if the attack does not exist
        throw invalid_argument("Attack does not exist");
    }
}

// Function to retrieve all attacks that have a name containing a given substring
vector<Attack> getAttacksByName(const string& substr) {
    // Create a vector of attacks to store the filtered attacks
    vector<Attack> filteredAttacks;

    // Iterate over each attack in the collection
    for (int i = 0; i < attacks.size(); i++) {
        // Check if the name of the attack contains the given substring
        if (attacks[i].name.find(substr) != string::npos) {
            // Add the attack to the vector of filtered attacks
            filteredAttacks.push_back(attacks[i]);
        }
    }

    // Return the vector of filtered attacks
    return filteredAttacks;
}

// Function to retrieve all attacks that have a value within a given range
vector<Attack> getAttacksByValue(double minValue, double maxValue) {
    // Create a vector of attacks to store the filtered attacks
    vector<Attack> filteredAttacks;

    // Iterate over each attack in the collection
    for (int i = 0; i < attacks.size(); i++) {
        // Check if the value of the attack is within the given range
        if (attacks[i].value >= minValue && attacks[i].value <= maxValue) {
            // Add the attack to the vector of filtered attacks
            filteredAttacks.push_back(attacks[i]);
        }
    }

    // Return the vector of filtered attacks
    return filteredAttacks;
}

// Function to randomly select one of two predefined attacks for a character to use
void simulateCharacterAttack() {
    // Get the current time point
    chrono::time_point<chrono::system_clock> now = chrono::system_clock::now();

    // Check if the cooldown period has passed since the last attack selection
    if (now - lastAttackTime >= chrono::seconds(COOLDOWN_PERIOD)) {
        // Select one of two predefined attacks randomly
        int selectedAttack = rand() % 2;

        // Print the selected attack number to the console
        cout << "Selected attack: " << selectedAttack + 1 << endl;

        // Update the last attack time to the current time point
        lastAttackTime = now;
    } else {
        // Throw an exception if the cooldown period has not passed yet
        throw invalid_argument("Cooldown period has not passed yet");
    }
}

// Function to persist the attack collection to disk
void persistAttacksToDisk() {
    // Create a JSON object with the attack collection
    json attacksJSON = json::array();

    // Iterate over each attack in the collection
    for (int i = 0; i < attacks.size(); i++) {
        // Add the attack to the JSON array
        attacksJSON.push_back(attacks[i]);
    }

    // Create a JSON string with the attack collection
    string attacksJSONString = attacksJSON.dump();

    // Write the attack collection to disk in a JSON file
    ofstream outFile("attacks.json");
    if (outFile.is_open()) {
        outFile << attacksJSONString;
        outFile.close();
    } else {
        // Throw an exception if the file could not be opened for writing
        throw invalid_argument("Could not open file for writing");
    }
}

// Function to load the attack collection from disk
void loadAttacksFromDisk() {
    // Read the attack collection from a JSON file
    ifstream inFile("attacks.json");
    if (inFile.is_open()) {
        string attacksJSONString;
        getline(inFile, attacksJSONString);
        inFile.close();

        // Create a JSON object with the attack collection
        json attacksJSON = json::parse(attacksJSONString);

        // Iterate over each attack in the JSON array
        for (int i = 0; i < attacksJSON.size(); i++) {
            // Get the attack name and value from the JSON object
            string name = attacksJSON[i]["name"];
            double value = attacksJSON[i]["value"];

            // Insert the attack into the collection
            insertAttack(name, value);
        }
    } else {
        // Throw an exception if the file could not be opened for reading
        throw invalid_argument("Could not open file for reading");
    }
}
