#include <mutex>

// Global variables for buffer and logging system
constexpr size_t BUFFER_SIZE = 1024 * 1024; // 1 MB
std::vector<std::string> buffer(BUFFER_SIZE);
std::unordered_set<std::string> uniqueWords;
std::ofstream outfile("log.txt");
std::mutex logMutex;

// Function to read lines from file and store in buffer
void dynamicFileReader() {
    std::ifstream infile("large_text_file.txt");
    size_t lineNumber = 0;
    size_t memoryUsage = 0;
    std::string line;
    while (std::getline(infile, line)) {
        // Add line to buffer and update metrics
        buffer[lineNumber] = line;
        ++lineNumber;
        memoryUsage += line.size() + 1;
        uniqueWords.insert(line);

        // Periodically persist buffer contents to disk
        if (memoryUsage > BUFFER_SIZE / 2) {
            persistenceThread();
            memoryUsage = 0;
        }
    }

    // Log final metrics and deallocate resources
    logMutex.lock();
    outfile << "Total lines read: " << lineNumber << std::endl;
    outfile << "Total unique words: " << uniqueWords.size() << std::endl;
    outfile << "Memory usage: " << memoryUsage << std::endl;
    outfile.close();
    buffer.clear();
    logMutex.unlock();
}

// Thread for persisting buffer contents to disk
void persistenceThread() {
    // Sleep for 5 seconds to allow cooldown period between selections
    std::this_thread::sleep_for(std::chrono::seconds(5));

    // Lock log mutex to prevent concurrent access during disk I/O
    logMutex.lock();

    // Persist buffer contents to disk
    outfile << "Persisting buffer contents to disk" << std::endl;
    for (const auto& line : buffer) {
        outfile << line << std::endl;
    }

    // Clear buffer and deallocate resources
    buffer.clear();
    logMutex.unlock();
}

// Function to randomly select one of two predefined lines for display
void randomSelection() {
    // Implement a mechanism for selecting one of two predefined lines
    // with a cooldown period between selections (e.g., 5 seconds)
    std::this_thread::sleep_for(std::chrono::seconds(5));
    size_t selectedLine = rand() % 2;

    // Print selected line number to console
    std::cout << "Selected line: " << selectedLine << std::endl;
}
