double get_average_temperature(struct temp_measurement *measurements, int count) {
  double total = 0;
  for (int i = 0; i < count; i++) {
    if (strcmp(measurements[i].unit, "C") == 0) {
      total += measurements[i].value;
    } else if (strcmp(measurements[i].unit, "F") == 0) {
      total += (measurements[i].value - 32) * 5 / 9;
    } else {
      // Handle invalid units gracefully
      continue;
    }
  }
  return total / count;
}

