void Manager::addEvent(const Event& event) {
    if (events_.size() >= events_.capacity()) {
        // Resize the vector to make room for new events
        events_.resize(events_.capacity() * 2);
    }
    events_.push_back(event);
}

void Manager::removeEvent(long offset) {
    if (hasEvent(offset)) {
        // Remove the event from the vector
        events_.erase(std::find_if(events_.begin(), events_.end(), [offset](const Event& e) {
            return e.offset == offset;
        }));
    }
}

bool Manager::hasEvent(long offset) const {
    return std::any_of(events_.begin(), events_.end(), [offset](const Event& e) {
        return e.offset == offset;
    });
}

const Event& Manager::getEvent(long offset) const {
    auto it = std::find_if(events_.begin(), events_.end(), [offset](const Event& e) {
        return e.offset == offset;
    });
    if (it != events_.end()) {
        return *it;
    } else {
        throw std::out_of_range("Event not found");
    }
}

void Manager::addAttack(const Attack& attack) {
    if (attacks_.size() >= attacks_.capacity()) {
        // Resize the map to make room for new attacks
        attacks_.resize(attacks_.capacity() * 2);
    }
    attacks_[attack.name] = attack;
}

void Manager::removeAttack(const std::string& name) {
    if (hasAttack(name)) {
        // Remove the attack from the map
        attacks_.erase(name);
    }
}

bool Manager::hasAttack(const std::string& name) const {
    return attacks_.find(name) != attacks_.end();
}

const Attack& Manager::getAttack(const std::string& name) const {
    auto it = attacks_.find(name);
    if (it != attacks_.end()) {
        return it->second;
    } else {
        throw std::out_of_range("Attack not found");
    }
}

// Query performance metrics
long Manager::totalMemoryUsage() const {
    return events_.size() * sizeof(Event) + attacks_.size() * sizeof(Attack);
}

long Manager::queryTime(long key, bool inclusive) const {
    long start = 0;
    if (inclusive) {
        // Start at the beginning of the vector if the query is inclusive
        start = events_.begin()->offset;
    } else {
        // Otherwise, start at the next element
        start = events_.begin()[1].offset;
    }

    long end = events_.end()->offset;
    if (!inclusive) {
        // If the query is exclusive, end at the previous element
        --end;
    }

    // Search for the first event that matches the key
    auto it = std::find_if(events_.begin(), events_.end(), [key](const Event& e) {
        return e.key == key;
    });

    if (it != events_.end()) {
        long offset = it->offset;
        // Find the first event that is outside the query range
        while (start <= offset && offset < end) {
            ++offset;
        }
        return offset - start;
    } else {
        return 0;
    }
}

// Persistent storage mechanism
void Manager::saveToDisk() {
    // Serialize the attacks to JSON
    std::string json = "{";
    for (const auto& attack : attacks_) {
        json += "\"" + attack.first + "\":{";
        json += "\"name\":\"" + attack.second.name + "\",";
        json += "\"strength\":" + std::to_string(attack.second.strength) + ",";
        json += "},";
    }
    // Remove the last comma and close the JSON object
    json = json.substr(0, json.size() - 1) + "}";

    // Serialize the events to JSON
    for (const auto& event : events_) {
        json += "\"" + std::to_string(event.offset) + "\":{";
        json += "\"key\":" + std::to_string(event.key) + ",";
        json += "\"availabilityStatus\":\"" + std::to_string(event.availabilityStatus) + "\"";
        json += "},";
    }
    // Remove the last comma and close the JSON object
    json = json.substr(0, json.size() - 1) + "}";

    // Save the JSON to disk
    std::ofstream ofs("attacks.json");
    ofs << json;
    ofs.close();
}
```
This implementation uses a `std::vector<Event>` and a `std::unordered_map<std::string, Attack>` for the event reservation system and attack collection, respectively. The `Manager` class provides methods to add, remove, and query events and attacks, as well as to save the data to disk.

The query performance metrics are calculated using a binary search algorithm that starts at the beginning of the vector or after the previous event depending on whether the query is inclusive or exclusive. The total memory usage is calculated by summing the sizes of both vectors.

The persistent storage mechanism uses JSON serialization and saves the data to disk in a separate file called `attacks.json`.

Note that this implementation is not thread-safe, so if you plan to use it in a multi-threaded environment, you should add synchronization mechanisms.']

