void manage_memory(size_t size1, size_t size2, size_t size3) {
    // Allocate memory for the three arrays
    double* double_array = (double*)malloc(sizeof(double) * size1);
    char* char_array = (char*)malloc(sizeof(char) * size2);
    element_t* struct_array = (element_t*)malloc(sizeof(element_t) * size3);

    // Check for allocation failures
    if (!double_array || !char_array || !struct_array) {
        fprintf(stderr, "Error: Failed to allocate memory for arrays\n");
        exit(1);
    }

    // Populate the struct array with char and double values from other arrays
    for (size_t i = 0; i < size3; i++) {
        struct_array[i].c = char_array[i];
        struct_array[i].d = double_array[i];
    }

    // Free the memory for the arrays when they are no longer needed
    free(double_array);
    free(char_array);
    free(struct_array);
}
```
