// Define the log entry structure
typedef struct {
    char* message;
    int priority;
    time_t timestamp;
    enum severity_level severity;
} log_entry;

// Define a pool of log entries with a fixed size
#define LOG_ENTRY_POOL_SIZE 1024
log_entry* log_entry_pool = NULL;
size_t num_entries_allocated = 0;
size_t num_entries_available = LOG_ENTRY_POOL_SIZE;

// Function to allocate a new log entry and initialize it with a unique string identifier
log_entry* alloc_log_entry(char* message, int priority, enum severity_level severity) {
    // Check if the pool is full
    if (num_entries_available == 0) {
        return NULL;
    }

    // Allocate a new log entry from the pool
    log_entry* entry = &log_entry_pool[num_entries_allocated];
    num_entries_allocated++;
    num_entries_available--;

    // Initialize the log entry with the given parameters
    entry->message = message;
    entry->priority = priority;
    entry->timestamp = time(NULL);
    entry->severity = severity;

    return entry;
}

// Function to free a log entry and add it back to the pool
void free_log_entry(log_entry* entry) {
    // Check if the entry is valid
    if (entry == NULL) {
        return;
    }

    // Free the message string
    free(entry->message);
    entry->message = NULL;

    // Add the entry back to the pool
    num_entries_allocated--;
    num_entries_available++;
}

// Function to allocate a new log entry and initialize it with a unique string identifier
int alloc_log_entry_threadsafe(char* message, int priority, enum severity_level severity) {
    // Create a mutex for thread-safe access to the pool
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock the mutex before accessing the pool
    pthread_mutex_lock(&mutex);

    // Allocate a new log entry from the pool
    log_entry* entry = alloc_log_entry(message, priority, severity);

    // Unlock the mutex after accessing the pool
    pthread_mutex_unlock(&mutex);

    return entry;
}

// Function to free a log entry and add it back to the pool
void free_log_entry_threadsafe(log_entry* entry) {
    // Create a mutex for thread-safe access to the pool
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock the mutex before accessing the pool
    pthread_mutex_lock(&mutex);

    // Free the log entry and add it back to the pool
    free_log_entry(entry);

    // Unlock the mutex after accessing the pool
    pthread_mutex_unlock(&mutex);
}']

