// Define the maximum size of the configuration settings collection
#define MAX_SETTINGS_SIZE 1024

// Define the data structure to hold a single configuration setting
typedef struct {
    char* name;
    bool enabled;
    double default_value;
} config_setting_t;

// Define a hash table for storing the configuration settings
static config_setting_t* settings_table[MAX_SETTINGS_SIZE];

// Define a lock to protect concurrent access to the configuration settings
pthread_mutex_t settings_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to add a new configuration setting to the collection
bool config_add(const char* name, bool enabled, double default_value) {
    // Acquire the lock for exclusive access to the configuration settings
    pthread_mutex_lock(&settings_lock);

    // Check if there is enough space in the hash table for a new setting
    int free_slot = -1;
    for (int i = 0; i < MAX_SETTINGS_SIZE && free_slot == -1; i++) {
        if (settings_table[i] == NULL) {
            free_slot = i;
        }
    }
    if (free_slot == -1) {
        pthread_mutex_unlock(&settings_lock);
        return false;
    }

    // Create a new configuration setting and add it to the hash table
    config_setting_t* new_setting = malloc(sizeof(config_setting_t));
    new_setting->name = strdup(name);
    new_setting->enabled = enabled;
    new_setting->default_value = default_value;
    settings_table[free_slot] = new_setting;

    // Release the lock and return success
    pthread_mutex_unlock(&settings_lock);
    return true;
}

// Define a function to update an existing configuration setting in the collection
bool config_update(const char* name, bool enabled, double default_value) {
    // Acquire the lock for exclusive access to the configuration settings
    pthread_mutex_lock(&settings_lock);

    // Find the existing configuration setting with the given name
    int index = -1;
    for (int i = 0; i < MAX_SETTINGS_SIZE && index == -1; i++) {
        if (settings_table[i] != NULL && strcmp(name, settings_table[i]->name) == 0) {
            index = i;
        }
    }
    if (index == -1) {
        pthread_mutex_unlock(&settings_lock);
        return false;
    }

    // Update the existing configuration setting and release the lock
    config_setting_t* setting = settings_table[index];
    setting->enabled = enabled;
    setting->default_value = default_value;
    pthread_mutex_unlock(&settings_lock);
    return true;
}

// Define a function to remove an existing configuration setting from the collection
bool config_remove(const char* name) {
    // Acquire the lock for exclusive access to the configuration settings
    pthread_mutex_lock(&settings_lock);

    // Find the existing configuration setting with the given name
    int index = -1;
    for (int i = 0; i < MAX_SETTINGS_SIZE && index == -1; i++) {
        if (settings_table[i] != NULL && strcmp(name, settings_table[i]->name) == 0) {
            index = i;
        }
    }
    if (index == -1) {
        pthread_mutex_unlock(&settings_lock);
        return false;
    }

    // Remove the existing configuration setting and release the lock
    config_setting_t* setting = settings_table[index];
    free(setting->name);
    free(setting);
    settings_table[index] = NULL;
    pthread_mutex_unlock(&settings_lock);
    return true;
}

// Define a function to retrieve an existing configuration setting from the collection
config_setting_t* config_get(const char* name) {
    // Acquire the lock for shared access to the configuration settings
    pthread_mutex_lock(&settings_lock);

    // Find the existing configuration setting with the given name
    int index = -1;
    for (int i = 0; i < MAX_SETTINGS_SIZE && index == -1; i++) {
        if (settings_table[i] != NULL && strcmp(name, settings_table[i]->name) == 0) {
            index = i;
        }
    }
    pthread_mutex_unlock(&settings_lock);

    // Return the existing configuration setting or NULL if not found
    return (index != -1) ? settings_table[index] : NULL;
}
