#ifndef ENVIRONMENTAL_SENSOR_RECORD_H
#define ENVIRONMENTAL_SENSOR_RECORD_H

// Structure to represent an environmental sensor record
typedef struct {
    long timestamp;
    int status_code;
    float temperature;
} environmental_sensor_record_t;

// Dynamic list of environmental sensor records, with thread-safe operations and custom memory pool management.
#define MAX_RECORD_COUNT 1000
typedef struct {
    int count; // Number of records in the list
    environmental_sensor_record_t *records[MAX_RECORD_COUNT];
} record_list_t;

// Function to insert a new record into the list, handling invalid records by setting temperature to NaN.
void insert_record(record_list_t *list, long timestamp, int status_code, float temperature) {
    // Check if the list is full and needs to be resized.
    if (list->count == MAX_RECORD_COUNT) {
        // Resize the list by doubling its size.
        record_list_t *new_list = malloc(sizeof(record_list_t));
        new_list->count = 0;
        for (int i = 0; i < MAX_RECORD_COUNT; ++i) {
            new_list->records[i] = NULL;
        }
        // Copy the existing records to the new list.
        pthread_mutex_lock(&list->mutex);
        for (int i = 0; i < MAX_RECORD_COUNT && list->count > 0; ++i) {
            environmental_sensor_record_t *record = list->records[i];
            if (record != NULL) {
                new_list->records[new_list->count++] = record;
            }
        }
        pthread_mutex_unlock(&list->mutex);
        // Swap the old and new lists.
        pthread_mutex_lock(&list->mutex);
        list->records = new_list->records;
        list->count = new_list->count;
        pthread_mutex_unlock(&list->mutex);
    }
    // Insert the new record.
    int index = list->count++;
    list->records[index] = malloc(sizeof(environmental_sensor_record_t));
    list->records[index]->timestamp = timestamp;
    list->records[index]->status_code = status_code;
    if (temperature < -273 || temperature > 1000) {
        list->records[index]->temperature = NAN;
    } else {
        list->records[index]->temperature = temperature;
    }
}

// Function to remove a record from the list by its index.
void remove_record(record_list_t *list, int index) {
    // Check if the index is valid.
    if (index < 0 || index >= list->count) {
        return;
    }
    // Remove the record at the specified index.
    pthread_mutex_lock(&list->mutex);
    free(list->records[index]);
    --list->count;
    for (int i = index; i < list->count; ++i) {
        environmental_sensor_record_t *record = list->records[i];
        list->records[i] = record + 1;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to iterate over the records in the list, calling a provided function on each one.
void iterate_over_records(record_list_t *list, void (*callback)(environmental_sensor_record_t *)) {
    // Iterate over the records and call the callback function on each one.
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        environmental_sensor_record_t *record = list->records[i];
        callback(record);
    }
    pthread_mutex_unlock(&list->mutex);
}

#endif // ENVIRONMENTAL_SENSOR_RECORD_H
