    Record* record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return NULL;
    }
    memset(record, 0, sizeof(Record));
    return record;
}

// Define a function to free memory for a record
void free_record(Record* record) {
