        free(record);
    }
}

// Define a function to allocate memory for a dataset
Dataset* alloc_dataset() {
    Dataset* dataset = malloc(sizeof(Dataset));
    if (!dataset) {
        fprintf(stderr, "Failed to allocate memory for dataset\n");
        return NULL;
    }
    memset(dataset, 0, sizeof(Dataset));
    return dataset;
}

// Define a function to free memory for a dataset
void free_dataset(Dataset* dataset) {
    if (dataset) {
        // Free all the records in the dataset
        for (int i = 0; i < dataset->num_records; ++i) {
            free_record(&dataset->records[i]);
        }
        free(dataset);
    }
}

