void add_record(Dataset* dataset, Record* record) {
    // Reallocate memory for the records array if necessary
    if (dataset->num_records == dataset->capacity) {
        int new_size = dataset->capacity * 2;
        Record** new_records = realloc(dataset->records, new_size * sizeof(Record*));
        if (!new_records) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            return;
        }
        dataset->capacity = new_size;
        dataset->records = new_records;
    }
    // Add the record to the end of the records array
    dataset->records[dataset->num_records++] = record;
}

