        record->value = rand_float_range(0.0f, 100.0f); // Generate a random float value within the range of 0.0 to 100.0
        strcpy(record->metadata, "Test"); // Copy a string into the metadata field
        add_record(dataset, record);
    }

    // Query records based on a range of keys and print them to standard output
    query_records(dataset, -50, 50);

    // Find the largest integer in the dataset and print it to standard output
    int largest = find_largest_integer(dataset);
    printf("Largest integer: %d\n", largest);

    // Persist the records to disk periodically
    persist_records(dataset);

    // Load the records from disk and print them to standard output
    load_records(dataset);

    // Free the memory allocated for the dataset and all its records
    free_dataset(dataset);

    return 0;
}
