// Define the structure to hold the records
typedef struct record {
    long offset;
    int key;
    double value;
    char status;
} Record;

// Define a global variable to keep track of the number of allocated records
static size_t num_records = 0;

// Define a global array to hold the records
Record* records = NULL;

// Define a mutex to synchronize access to the data source and allocated memory
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate memory for the records
void allocate_records(size_t num) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if there is enough memory available to allocate the new records
    if (num > 0 && records == NULL) {
        // Allocate memory for the records
        records = (Record*) malloc(sizeof(Record) * num);
        assert(records != NULL);

        // Reset the number of allocated records to zero
        num_records = 0;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to deallocate memory for the records
void deallocate_records() {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if there are any allocated records
    if (records != NULL) {
        // Deallocate memory for the records
        free(records);
        records = NULL;

        // Reset the number of allocated records to zero
        num_records = 0;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to update the offset value for a record
void update_offset(int key, long new_offset) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if there are any allocated records
    if (records != NULL) {
        // Search for the record with the specified key
        for (size_t i = 0; i < num_records; i++) {
            if (records[i].key == key) {
                // Update the offset value for the record
                records[i].offset = new_offset;

                // Break from the loop as we have found the record
                break;
            }
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to retrieve the status flag for a record
char get_status(int key) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if there are any allocated records
    if (records != NULL) {
