// Struct for log entries
typedef struct {
    long timestamp; // Timestamp of the log entry
    int message_id; // Unique identifier for each log entry
    int priority_level; // Priority level of the log entry (1-5)
    char* message; // Message content of the log entry
} LogEntry;

// Configuration file struct
typedef struct {
    int max_entries; // Maximum number of entries to store in memory
    long mem_usage_threshold; // Memory usage threshold (in bytes)
    int default_priority_level; // Default priority level for filtering
} ConfigFile;

// Global variables
int num_entries = 0; // Current number of log entries stored in memory
long total_mem_usage = 0; // Total memory usage by the program
ConfigFile config; // Configuration file struct
pthread_mutex_t mem_usage_lock = PTHREAD_MUTEX_INITIALIZER; // Lock for memory usage monitoring
pthread_cond_t mem_usage_cond = PTHREAD_COND_INITIALIZER; // Condition variable for memory usage monitoring
bool mem_usage_alert = false; // Flag indicating whether an alert has been triggered

// Function to initialize the log entry struct
void initLogEntry(LogEntry* entry) {
    entry->timestamp = time(NULL); // Set timestamp to current system time
    entry->message_id = rand(); // Generate unique message ID using a hash function
    entry->priority_level = 0; // Default priority level is 0 (lowest)
}

// Function to add a new log entry to the memory array
void addLogEntry(LogEntry* entry, char* message) {
    pthread_mutex_lock(&mem_usage_lock);
    initLogEntry(entry); // Initialize the log entry struct
    entry->message = strdup(message); // Copy the message content to the log entry struct
    total_mem_usage += sizeof(LogEntry) + strlen(message) + 1; // Update memory usage
    num_entries++; // Increment number of entries stored in memory
    if (total_mem_usage > config.mem_usage_threshold && !mem_usage_alert) {
        mem_usage_alert = true; // Trigger alert if memory usage exceeds threshold
        pthread_cond_signal(&mem_usage_cond); // Signal condition variable to wake up monitoring thread
    }
    pthread_mutex_unlock(&mem_usage_lock);
}

// Function to deallocate all allocated memory
void freeAllMemory() {
    for (int i = 0; i < num_entries; i++) {
        free(log_entries[i].message); // Free message content of each log entry
    }
    free(log_entries); // Free memory array of log entries
}

// Function to read log messages from a file
void readLogMessagesFromFile(const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    char line[1024]; // Buffer for reading lines from the file
    while (fgets(line, sizeof(line), fp)) {
        // Parse the log message content and add it to the memory array
        LogEntry entry;
        initLogEntry(&entry);
        entry.message = strdup(line);
        total_mem_usage += sizeof(LogEntry) + strlen(line) + 1;
        num_entries++;
    }
    fclose(fp);
}

// Function to handle file I/O gracefully for reading log messages from multiple files
void readLogMessagesFromFiles(char** filenames, int num_files) {
    // Iterate through each file and read its contents
    for (int i = 0; i < num_files; i++) {
        readLogMessagesFromFile(filenames[i]);
    }
}

// Function to filter log entries based on specified priority level and output them to a file
void filterLogEntries(int priority_level) {
    // Open the output file for appending
    FILE* fp = fopen("filtered_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening filtered log file");
        return;
    }
    // Iterate through each log entry and check its priority level against the specified one
    for (int i = 0; i < num_entries; i++) {
        if (log_entries[i].priority_level >= priority_level) {
            fprintf(fp, "%ld %s\n", log_entries[i].timestamp, log_entries[i].message);
        }
    }
    // Close the output file
    fclose(fp);
}

// Function to handle concurrent writes to the output file safely
void filterLogEntriesConcurrently(int priority_level) {
    pthread_mutex_lock(&mem_usage_lock);
    if (num_entries > 0 && !mem_usage_alert) {
        filterLogEntries(priority_level); // Filter log entries and output them to the filtered log file
        mem_usage_alert = false; // Reset alert flag
    }
    pthread_mutex_unlock(&mem_usage_lock);
}

// Function to monitor memory usage and trigger an alert if it exceeds a threshold
void monitorMemoryUsage() {
    while (true) {
        pthread_mutex_lock(&mem_usage_lock);
        if (total_mem_usage > config.mem_usage_threshold && !mem_usage_alert) {
            mem_usage_alert = true; // Trigger alert if memory usage exceeds threshold
            pthread_cond_signal(&mem_usage_cond); // Signal condition variable to wake up monitoring thread
        }
        pthread_mutex_unlock(&mem_usage_lock);
    }
}

// Function to load default configuration file parameters
void loadDefaultConfig() {
    config.max_entries = 1000; // Default maximum number of entries
    config.mem_usage_threshold = 1000000; // Default memory usage threshold (in bytes)
    config.default_priority_level = 3; // Default priority level for filtering (medium)
}

// Function to handle missing or malformed configuration files gracefully
void loadConfigFile(char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        loadDefaultConfig(); // Load default parameters if necessary
        return;
    }
    char line[1024]; // Buffer for reading lines from the file
    while (fgets(line, sizeof(line), fp)) {
        // Parse each line of the config file and update the corresponding parameter value
        if (strcmp(line, "max_entries:") == 0) {
            int max_entries;
            if (fscanf(fp, "%d", &max_entries) != 1) {
                perror("Error parsing config file");
                loadDefaultConfig(); // Load default parameters if necessary
                return;
            }
            config.max_entries = max_entries; // Update maximum number of entries
        } else if (strcmp(line, "mem_usage_threshold:") == 0) {
            long mem_usage_threshold;
            if (fscanf(fp, "%ld", &mem_usage_threshold) != 1) {
                perror("Error parsing config file");
                loadDefaultConfig(); // Load default parameters if necessary
                return;
            }
            config.mem_usage_threshold = mem_usage_threshold; // Update memory usage threshold
        } else if (strcmp(line, "default_priority_level:") == 0) {
            int default_priority_level;
            if (fscanf(fp, "%d", &default_priority_level) != 1) {
                perror("Error parsing config file");
                loadDefaultConfig(); // Load default parameters if necessary
                return;
            }
            config.default_priority_level = default_priority_level; // Update default priority level for filtering
        }
    }
    fclose(fp);
}
