import logging
import jsonschema
import yaml
from pyYAML import YAMLParser

class ConfigurationManager:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.parser = YAMLParser()
        self.schemas = {
            "server": {
                "type": "object",
                "properties": {
                    "host": {"type": "string"},
                    "port": {"type": "integer"}
                },
                "required": ["host", "port"]
            }
        }

    def load_configuration(self, filepath):
        self.logger.info("Loading configuration from %s", filepath)
        with open(filepath, "r") as f:
            config = self.parser.load(f)
        return config

    def update_configuration(self, config):
        self.logger.info("Updating configuration")
        try:
            jsonschema.validate(config, self.schemas["server"])
            self.logger.debug("Configuration validated successfully")
        except jsonschema.ValidationError as e:
            self.logger.error("Configuration validation failed: %s", str(e))
            raise
        return config

    def save_configuration(self, filepath, config):
        self.logger.info("Saving configuration to %s", filepath)
        with open(filepath, "w") as f:
            self.parser.dump(config, f)

    def get_server_settings(self):
        return self.load_configuration("server_config.yaml")

    def update_server_settings(self, config):
        updated_config = self.update_configuration(config)
        self.save_configuration("server_config.yaml", updated_config)
        return updated_config

class ServerSettings:
    def __init__(self, host, port):
        self.host = host
        self.port = port

if __name__ == "__main__":
    manager = ConfigurationManager()
    server_settings = ServerSettings("localhost", 8080)
    updated_config = manager.update_server_settings(server_settings)
    print(updated_config)']

