    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        int key;
        double weight;
        char name[1024];

        // Parse the input data and allocate memory for the name string
        if (sscanf(line, "%d %lf %s", &key, &weight, name) != 3) {
            fprintf(stderr, "Error parsing input: %s\n", line);
            exit(EXIT_FAILURE);
        }
        size_t name_len = strlen(name);
        records = realloc(records, (num_records + 1) * sizeof(*records));
        total_mem += (sizeof(*records) - sizeof(char*)) + name_len;
        records[num_records].key = key;
        records[num_records].weight = weight;
        records[num_records].name = malloc((name_len + 1) * sizeof(char));
        strcpy(records[num_records].name, name);
        num_records++;
    }
    fclose(fp);

    // Calculate the offset for each record based on its key and weight
    double increment = 0.1;
    double divisor = 2.0;
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = (double)records[i].key * increment + records[i].weight / divisor;
    }

    // Check for duplicate keys and deallocate any associated names
    size_t* key_counts = calloc(num_records, sizeof(*key_counts));
    for (size_t i = 0; i < num_records; i++) {
        key_counts[i]++;
    }
    for (size_t i = 0; i < num_records; i++) {
        if (key_counts[i] > 1) {
            free(records[i].name);
            records[i].name = NULL;
        }
    }
    free(key_counts);

    // Print the offset for each record and deallocate all memory when done
    printf("Offsets:\n");
    for (size_t i = 0; i < num_records; i++) {
        printf("%zu: %.2lf\n", records[i].key, records[i].offset);
    }
    free(records);
}
