['```
import json
import os
import time
from collections import deque
from concurrent.futures import ProcessPoolExecutor
from typing import Dict, List, Tuple

class LogEntry:
    def __init__(self, timestamp: int, user_id: str, action_type: str, metadata: dict):
        self.timestamp = timestamp
        self.user_id = user_id
        self.action_type = action_type
        self.metadata = metadata

class LogFileParser:
    def __init__(self, file_path: str):
        self.file_path = file_path
        self.log_entries = []

    def parse(self) -> List[LogEntry]:
        with open(self.file_path, "r") as f:
            for line in f:
                log_entry = json.loads(line)
                self.log_entries.append(LogEntry(**log_entry))
        return self.log_entries

class LogProcessor:
    def __init__(self, filter_criteria: Dict[str, str], config: dict):
        self.filter_criteria = filter_criteria
        self.config = config

    def process(self, log_entries: List[LogEntry]) -> Tuple[List[LogEntry], int]:
        filtered_log_entries = []
        for entry in log_entries:
            if self._filter_entry(entry):
                filtered_log_entries.append(entry)
        return filtered_log_entries, len(filtered_log_entries)

    def _filter_entry(self, entry: LogEntry) -> bool:
        for field, value in self.filter_criteria.items():
            if getattr(entry, field) != value:
                return False
        return True

def process_log_entries(file_path: str, filter_criteria: Dict[str, str], config: dict):
    parser = LogFileParser(file_path)
    log_entries = parser.parse()
    processor = LogProcessor(filter_criteria, config)
    filtered_log_entries, num_matches = processor.process(log_entries)
    return filtered_log_entries, num_matches
```
The above code defines a `LogEntry` class that represents an event with various attributes, a `LogFileParser` class that parses and processes log files containing structured JSON entries, and a `LogProcessor` class that extracts specific events based on a provided filter criteria and aggregates relevant data for further analysis.

