typedef struct {
    char *file_path;
    time_t last_modified;
    off_t file_size;
} file_record;

file_record* initialize_records(int num_files) {
    // Allocate memory for an array of `num_files` structures.
    file_record *records = (file_record*)malloc(sizeof(file_record) * num_files);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        exit(1);
    }

    // Initialize each structure with a file path, last modified timestamp, and file size in bytes.
    for (int i = 0; i < num_files; i++) {
        char *file_path = malloc(MAX_FILENAME_LENGTH);
        if (file_path == NULL) {
            perror("Failed to allocate memory for file path");
            exit(1);
        }
        // Read the file path from standard input.
        fgets(file_path, MAX_FILENAME_LENGTH, stdin);

        // Parse the last modified timestamp and file size from the file metadata.
        struct stat sb;
        if (stat(file_path, &sb) == -1) {
            perror("Failed to get file metadata");
            exit(1);
        }
        records[i].last_modified = sb.st_mtime;
        records[i].file_size = sb.st_size;
    }

    // Calculate the total memory usage in bytes for all records.
    size_t total_memory_usage = 0;
    for (int i = 0; i < num_files; i++) {
        total_memory_usage += records[i].file_size;
    }

    // Print the average file size across all processed files.
    printf("Average file size: %.2f\n", (double)total_memory_usage / (double)num_files);

    return records;
}

void deallocate_records(file_record *records, int num_files) {
    // Deallocate memory for each file path.
    for (int i = 0; i < num_files; i++) {
        free(records[i].file_path);
    }

    // Deallocate memory for the array of `num_files` structures.
    free(records);
}
