/* C Implementation of Dynamic Array for Records with Union-Find Data Structure */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
} Record;

int main() {
    /* Dynamic array for storing records */
    Record *records = NULL;
    size_t capacity = 0;
    size_t count = 0;

    /* Union-Find data structure to efficiently identify and manage disjoint sets of elements */
    int *union_find = NULL;
    size_t union_find_size = 0;

    /* Increment factor for calculating offset values */
    long increment = 1;

    /* Total memory usage in bytes allocated for all records */
    size_t total_memory = 0;

    /* Memory allocation and initialization of records array */
    printf("Enter the number of records: ");
    scanf("%zu", &capacity);
    records = (Record *)malloc(capacity * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records array\n");
        exit(EXIT_FAILURE);
    }
    memset(records, 0, capacity * sizeof(Record));
    total_memory += capacity * sizeof(Record);

    /* Memory allocation and initialization of union-find data structure */
    union_find_size = capacity;
    union_find = (int *)malloc(union_find_size * sizeof(int));
    if (!union_find) {
        fprintf(stderr, "Error: failed to allocate memory for union-find data structure\n");
        exit(EXIT_FAILURE);
    }
    memset(union_find, 0, union_find_size * sizeof(int));

    /* Reading list of integers from standard input */
    printf("Enter the list of integers: ");
    for (size_t i = 0; i < capacity; ++i) {
        scanf("%d", &records[i].key);
        union_find[i] = i;
    }

    /* Calculating offset values based on increment factor and key values */
    for (size_t i = 0; i < capacity; ++i) {
        records[i].offset = increment * records[i].key;
        total_memory += sizeof(long);
    }

    /* Finding largest integer in the array using a helper function */
    int max_index = find_max(records, capacity);
    printf("Largest integer: %d\n", records[max_index].key);

    /* Printing number of disjoint pairs and milliseconds taken to perform disjointness checks for each pair */
    int num_disjoint_pairs = 0;
    long total_time = 0;
    for (size_t i = 0; i < capacity - 1; ++i) {
        for (size_t j = i + 1; j < capacity; ++j) {
            int find_result = find(union_find, union_find_size, i, j);
            if (find_result == i) {
                union_find[find_result] = j;
                num_disjoint_pairs++;
                total_time += calculate_disjointness_checks(i, j);
            }
        }
    }
    printf("Number of disjoint pairs: %d\n", num_disjoint_pairs);
    printf("Time taken to perform disjointness checks (milliseconds): %ld\n", total_time);

    /* Deallocating memory for records and union-find data structure */
    free(records);
    free(union_find);

    return 0;
}

/* Helper function to find the largest integer in an array of records */
int find_max(Record *records, size_t count) {
    int max_index = 0;
    for (size_t i = 1; i < count; ++i) {
        if (records[i].key > records[max_index].key) {
            max_index = i;
        }
    }
    return max_index;
}

/* Helper function to find the root of a union-find set */
int find(int *union_find, size_t union_find_size, int index1, int index2) {
    if (index1 == index2) {
        return index1;
    }
    for (int i = 0; i < union_find_size; ++i) {
        if (union_find[index1] == union_find[index2]) {
            return find(union_find, union_find_size, index1, i);
        }
    }
    return -1;
}

/* Helper function to calculate the number of milliseconds taken to perform disjointness checks for a pair */
long calculate_disjointness_checks(int index1, int index2) {
    clock_t start = clock();
    find(union_find, union_find_size, index1, index2);
    return (clock() - start) * 1000 / CLOCKS_PER_SEC;
}

/* Logging mechanism to record detailed information about memory allocation, performance metrics, and error handling during execution */
void log(char *message) {
    fprintf(stderr, "%s\n", message);
}

/* Error handling scheme to manage unexpected inputs or conditions gracefully */
int handle_error() {
    fprintf(stderr, "Error: failed to allocate memory for records array\n");
    exit(EXIT_FAILURE);
}']

