typedef struct {
    int value;
    char buffer[buffer_size];
} record;

// Function to initialize the arrays of long offsets and int keys
void init_arrays(int n, long max_sum, long max_memory_kb) {
    // Allocate memory for the offset array
    long *offsets = malloc(n * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Allocate memory for the keys array
    int *keys = malloc(n * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        exit(1);
    }

    // Initialize the offset array with unique values and ensure that the sum of all offsets does not exceed max_sum
    long current_sum = 0;
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % 1000;
        if (current_sum + offsets[i] > max_sum) {
            offsets[i] -= current_sum - max_sum;
        }
        current_sum += offsets[i];
    }

    // Initialize the keys array with sorted positive integers and ensure that there are no duplicates
    for (int i = 0; i < n; i++) {
        keys[i] = rand() % max_int_value + 1;
        for (int j = i + 1; j < n; j++) {
            if (keys[j] == keys[i]) {
                keys[j]++;
            }
        }
