    record *records = malloc(n * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Set the timestamp field of each record with the current time plus a random offset between 0 and 60 seconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    for (int i = 0; i < n; i++) {
        records[i].timestamp = ts.tv_sec + rand() % 60;
    }

    // Fill the buffer field of each record with random alphanumeric characters
    char *buffer = malloc(n * sizeof(char) * buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffers\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }

    // Set the value field of each record with a random integer value within a specified range [min_val, max_val]
    int min_val = 0;
    int max_val = max_int_value - 1;
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    // Ensure that the total memory allocation does not exceed a user-defined maximum memory limit max_memory_kb, which is provided in kilobytes
    long total_memory_usage = n * (sizeof(long) + sizeof(int) + buffer_size);
    if (total_memory_usage > max_memory_kb * 1024) {
        fprintf(stderr, "Total memory usage exceeds maximum limit\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }

    // Implement a custom memory pool to manage memory allocation and deallocation efficiently
    struct mempool {
        long size;
        void *memory;
    };

    struct mempool *mempools = malloc(n * sizeof(struct mempool));
    if (mempools == NULL) {
        fprintf(stderr, "Failed to allocate memory for mempools\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }

    // Optimize the memory pool for large-scale data sets, minimizing fragmentation and maximizing cache utilization
    long best_size = 0;
    long best_usage = 0;
    for (int i = 0; i < n; i++) {
        struct mempool *mempool = &mempools[i];
        mempool->size = rand() % (max_memory_kb - total_memory_usage) + 1;
        mempool->memory = malloc(mempool->size);
        if (mempool->memory == NULL) {
            fprintf(stderr, "Failed to allocate memory for mempools\n");
            free(offsets);
            free(keys);
            free(records);
            exit(1);
        }

        // Record the best size and usage found so far
        if (mempool->size > best_size || (mempool->size == best_size && mempool->usage > best_usage)) {
            best_size = mempool->size;
            best_usage = mempool->usage;
        }
