    // Implement a mechanism to validate that the sum of all long offset values does not exceed max_sum
    if (current_sum > max_sum) {
        fprintf(stderr, "Sum of offsets exceeds maximum limit\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
