    struct compressed_data {
        long *offsets;
        int *keys;
        record *records;
    };

    struct compressed_data *compressed = malloc(sizeof(struct compressed_data));
    if (compressed == NULL) {
        fprintf(stderr, "Failed to allocate memory for compressed data\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }

    // Minimize memory usage by removing any zero values from the keys array and by using a compact representation
    int non_zero_count = 0;
    for (int i = 0; i < n; i++) {
        if (keys[i] != 0) {
            non_zero_count++;
        }
    }

    compressed->offsets = malloc(non_zero_count * sizeof(long));
    compressed->keys = malloc(non_zero_count * sizeof(int));
    compressed->records = malloc(non_zero_count * sizeof(record));
    if (compressed->offsets == NULL || compressed->keys == NULL || compressed->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for compressed data\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }

    int j = 0;
    for (int i = 0; i < n; i++) {
        if (keys[i] != 0) {
            compressed->offsets[j] = offsets[i];
            compressed->keys[j] = keys[i];
            compressed->records[j++] = records[i];
        }
    }
}
