// Function to process a directory of files
void processDirectory(const char *path, const char *algorithm) {
    // Open the directory
    DIR *dir = opendir(path);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", path);
        return;
    }

    // Create a vector to store file information
    std::vector<FileInfo> files;

    // Iterate over the contents of the directory and process each file
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over hidden files and directories
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Build the file path and validate it
        char *filePath = malloc(strlen(path) + strlen(entry->d_name) + 1);
        if (filePath == NULL) {
            printf("Error: unable to allocate memory for file path\n");
            return;
        }
        sprintf(filePath, "%s/%s", path, entry->d_name);
        struct stat fileStat;
        if (stat(filePath, &fileStat) == -1) {
            printf("Error: unable to access file %s\n", filePath);
            free(filePath);
            continue;
        }

        // Add the file information to the vector
        FileInfo info;
        info.name = strdup(entry->d_name);
        info.size = fileStat.st_size;
        info.modTime = fileStat.st_mtime;
        files.push_back(info);
    }

    // Close the directory
    closedir(dir);

    // Sort the vector by file name
    std::sort(files.begin(), files.end(), [](const FileInfo &a, const FileInfo &b) {
        return strcmp(a.name, b.name) < 0;
    });

    // Process each file in the vector based on the algorithm selected
    for (FileInfo info : files) {
        if (strcmp(algorithm, "checksum") == 0) {
            unsigned int checksum = checksum(info.name);
            printf("%s: %u\n", info.name, checksum);
        } else if (strcmp(algorithm, "metadata") == 0) {
            extractMetadata(info.name);
        }
    }
}

// Main function to run the processing algorithm on a directory
int main(int argc, char *argv[]) {
    // Validate command line arguments
    if (argc < 3) {
        printf("Usage: %s <algorithm> <directory>\n", argv[0]);
        return 1;
    }

    // Set the processing algorithm and directory path
    const char *algorithm = argv[1];
    const char *path = argv[2];

    // Validate the file system resources
    struct stat dirStat;
    if (stat(path, &dirStat) == -1) {
        printf("Error: unable to access directory %s\n", path);
        return 1;
    } else if (!S_ISDIR(dirStat.st_mode)) {
        printf("%s is not a valid directory\n", path);
        return 1;
    }

    // Run the processing algorithm on the directory
    processDirectory(path, algorithm);

    // Return successfully
    return 0;
}
