// Custom hash function for collision resolution
unsigned int custom_hash(char* key) {
  unsigned int hash = 0;
  for (int i = 0; i < strlen(key); i++) {
    hash = hash * 31 + key[i];
  }
  return hash % 1024;
}

// Data structure to store records and weights
typedef struct node {
  char* id;
  int timestamp;
  double weight;
  struct node* next;
} node_t;

// Hash table for efficient timestamp-based lookups
node_t** hash_table = NULL;
int num_nodes = 0;
int load_factor = 0.75; // Load factor threshold to balance performance and resource usage

// Function to allocate memory for a new node
node_t* allocate_node(char* id, int timestamp) {
  node_t* new_node = (node_t*)malloc(sizeof(node_t));
  if (new_node == NULL) {
    printf("Memory allocation failed\n");
    return NULL;
  }
  new_node->id = id;
  new_node->timestamp = timestamp;
  new_node->weight = (double)rand() / RAND_MAX; // Initialize weight as a random value between 0.0 and 1.0
  new_node->next = NULL;
  return new_node;
}

// Function to add a new node to the hash table
void add_node(char* id, int timestamp) {
  // Calculate offset for custom hash function
  unsigned int offset = custom_hash(id) % num_nodes;

  // Create a new node and add it to the linked list
  node_t* new_node = allocate_node(id, timestamp);
  if (new_node == NULL) {
    return;
  }
  new_node->next = hash_table[offset];
  hash_table[offset] = new_node;
}

// Function to retrieve a node from the hash table by id
node_t* get_node(char* id) {
  // Calculate offset for custom hash function
  unsigned int offset = custom_hash(id) % num_nodes;

  // Search for the node in the linked list
  node_t* current = hash_table[offset];
  while (current != NULL) {
    if (strcmp(current->id, id) == 0) {
      return current;
    }
    current = current->next;
  }
  return NULL;
}

// Function to update the weight of a node in the hash table
void update_weight(char* id, double new_weight) {
  // Retrieve the node from the hash table
  node_t* node = get_node(id);
  if (node == NULL) {
    return;
  }

  // Update the weight of the node
  node->weight = new_weight;
}

// Function to remove a node from the hash table by id
void remove_node(char* id) {
  // Calculate offset for custom hash function
  unsigned int offset = custom_hash(id) % num_nodes;

  // Search for the node in the linked list
  node_t* current = hash_table[offset];
  node_t* previous = NULL;
  while (current != NULL) {
    if (strcmp(current->id, id) == 0) {
      // Remove the node from the linked list
      if (previous == NULL) {
        hash_table[offset] = current->next;
      } else {
        previous->next = current->next;
      }
      free(current);
      return;
    }
    previous = current;
    current = current->next;
  }
}

// Function to serialize the hash table to a file
void serialize_table(FILE* file) {
  // Write the number of nodes in the hash table to the file
  fwrite(&num_nodes, sizeof(int), 1, file);

  // Iterate through each node in the hash table and write it to the file
  for (int i = 0; i < num_nodes; i++) {
    node_t* current = hash_table[i];
    while (current != NULL) {
      fwrite(current->id, sizeof(char), strlen(current->id), file);
      fwrite(&current->timestamp, sizeof(int), 1, file);
      fwrite(&current->weight, sizeof(double), 1, file);
      current = current->next;
    }
  }
}

// Function to deserialize the hash table from a file
void deserialize_table(FILE* file) {
  // Read the number of nodes in the hash table from the file
  fread(&num_nodes, sizeof(int), 1, file);

  // Allocate memory for the hash table and initialize it to NULL
  hash_table = (node_t**)malloc(num_nodes * sizeof(node_t*));
  if (hash_table == NULL) {
    printf("Memory allocation failed\n");
    return;
  }
  for (int i = 0; i < num_nodes; i++) {
    hash_table[i] = NULL;
  }

  // Iterate through each node in the file and add it to the hash table
  while (!feof(file)) {
    char* id = (char*)malloc(sizeof(char) * MAX_ID_LENGTH);
    if (id == NULL) {
      printf("Memory allocation failed\n");
      return;
    }
    int timestamp;
    double weight;
    fread(id, sizeof(char), MAX_ID_LENGTH, file);
    fread(&timestamp, sizeof(int), 1, file);
    fread(&weight, sizeof(double), 1, file);
    add_node(id, timestamp);
    free(id);
  }
}

// Function to resize the hash table based on a defined load factor threshold
void resize_table() {
  // Calculate the new number of nodes based on the current load factor and the previous number of nodes
  int new_num_nodes = (int)(load_factor * num_nodes);

  // Allocate memory for the new hash table and initialize it to NULL
  node_t** new_hash_table = (node_t**)malloc(new_num_nodes * sizeof(node_t*));
  if (new_hash_table == NULL) {
    printf("Memory allocation failed\n");
    return;
  }
  for (int i = 0; i < new_num_nodes; i++) {
    new_hash_table[i] = NULL;
  }

  // Iterate through each node in the previous hash table and add it to the new hash table
  for (int i = 0; i < num_nodes; i++) {
    node_t* current = hash_table[i];
    while (current != NULL) {
      unsigned int offset = custom_hash(current->id) % new_num_nodes;
      if (new_hash_table[offset] == NULL) {
        new_hash_table[offset] = current;
      } else {
        current->next = new_hash_table[offset];
        new_hash_table[offset] = current;
      }
      current = current->next;
    }
  }

  // Free the previous hash table and set the new hash table as the current one
  free(hash_table);
  hash_table = new_hash_table;
  num_nodes = new_num_nodes;
}
