import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ThemeCache {
    private static final int THEME_CACHE_SIZE = 1000; // maximum number of themes to cache
    private static final long THEME_CACHE_TIMEOUT = TimeUnit.MINUTES.toMillis(15); // minimum idle time before recycling a theme
    private static final int RETENTION_THRESHOLD = 30; // number of recently used themes to retain in cache

    private ConcurrentHashMap<String, Theme> themeCache; // map of theme names to their corresponding bitmaps
    private ScheduledExecutorService cleanupService; // service for periodically clearing unused themes from the cache

    public ThemeCache() {
        this.themeCache = new ConcurrentHashMap<>();
        this.cleanupService = Executors.newSingleThreadScheduledExecutor();
        this.cleanupService.scheduleAtFixedRate(this::clearUnusedThemes, 0, 10, TimeUnit.MINUTES);
    }

    public void cacheTheme(String name, Bitmap bitmap) {
        if (bitmap == null || name == null) return; // invalid input, do not cache
        Theme theme = new Theme(name, bitmap);
        themeCache.put(name, theme);
    }

    public void recycleTheme(String name) {
        Theme theme = themeCache.get(name);
        if (theme == null) return; // no such theme in cache, do not attempt to recycle
        if (!isRecyclable(theme)) return; // theme is not recyclable, do not attempt to recycle
        cleanupService.submit(() -> {
            themeCache.remove(name);
            theme.bitmap.recycle();
        });
    }

    public Bitmap getThemeBitmap(String name) {
        Theme theme = themeCache.get(name);
        if (theme == null) return null; // no such theme in cache, attempt to fetch from external service
        long now = System.currentTimeMillis();
        if (now - theme.lastAccessed < THEME_CACHE_TIMEOUT) return null; // theme is still being used, do not attempt to recycle
        recycleTheme(name); // recycle the theme if it has been idle for too long
        return theme.bitmap;
    }

    private void clearUnusedThemes() {
        Iterator<String> iterator = themeCache.keySet().iterator();
        while (iterator.hasNext()) {
            String name = iterator.next();
            Theme theme = themeCache.get(name);
            if (!theme.isRecyclable) continue; // skip non-recyclable themes
            long now = System.currentTimeMillis();
            if (now - theme.lastAccessed < THEME_CACHE_TIMEOUT) continue; // skip recently used themes
            cleanupService.submit(() -> {
                themeCache.remove(name);
                theme.bitmap.recycle();
            });
        }
    }

    private boolean isRecyclable(Theme theme) {
        return theme != null && !theme.isRecyclable; // only recycle themes that are not currently being used
    }
}

class Theme {
    public final String name;
    public final Bitmap bitmap;
    private long lastAccessed = System.currentTimeMillis();
    private boolean isRecyclable = true;

    public Theme(String name, Bitmap bitmap) {
        this.name = name;
        this.bitmap = bitmap;
    }

    public void markLastAccessed() {
        lastAccessed = System.currentTimeMillis();
    }
}
```
