      return Math.min(MAX_INTERVAL_MS, rollingWindowAvg * 2);
    } else if (rollingWindowAvg > LATENCY_PEAK_LOAD_MS) {
      return Math.max(MIN_INTERVAL_MS, rollingWindowAvg / 2);
    } else {
      return rollingWindowAvg;
    }
  }

