#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SUM 1000000000 // maximum sum of offset values (in kilobytes)
#define BUFFER_SIZE 256    // size of record buffers (in bytes)
#define MIN_VAL 1          // minimum value for random integer generation
#define MAX_VAL 100        // maximum value for random integer generation
#define MAX_MEMORY_KB 100000 // maximum memory allocation in kilobytes

typedef struct {
    long offset;
    int key;
    char buffer[BUFFER_SIZE];
} record;

void initialize_data(int n, int max_sum, int max_memory_kb) {
    srand((unsigned)time(NULL)); // seed random number generator

    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    record *records = malloc(n * sizeof(record));

    // initialize offset and key arrays
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % max_sum;
        keys[i] = rand() % MAX_VAL + MIN_VAL;
    }

    // compress keys array to remove leading zeros and consecutive duplicates
    int j = 0;
    for (int i = 1; i < n; i++) {
        if (keys[i] != keys[i - 1]) {
            keys[j++] = keys[i];
        }
    }
    keys = realloc(keys, j * sizeof(int));
    n = j;

    // initialize records array
    for (int i = 0; i < n; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        for (int j = 0; j < BUFFER_SIZE; j++) {
            records[i].buffer[j] = rand() % 26 + 'a'; // random alphanumeric characters
        }
    }

    // deallocate memory
    free(offsets);
    free(keys);
    free(records);
}
