    dataItem_t* data;
    struct node* next;
} node_t;

// Hash table to store the mappings between names and nodes in the linked list
typedef struct {
    char** keys;
    node_t** values;
    int size;
    float loadFactor;
} hashTable_t;

// Cache to store recently accessed items
