// Function to insert a new data item into the list, ensuring no duplicates
void insertDataItem(dataItem_t* data) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the name is already in the hash table, and return early if it is
    int index = searchHashTable(data->name);
    if (index != -1) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Create a new node for the data item
    node_t* newNode = malloc(sizeof(node_t));
    newNode->data = data;
    newNode->next = NULL;

    // Insert the new node at the beginning of the linked list
    if (head == NULL) {
        head = newNode;
    } else {
        newNode->next = head;
        head = newNode;
    }

    // Add the name to the hash table
    addHashTableEntry(data->name, newNode);

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to delete a data item from the list based on its name
void deleteDataItem(char* name) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Search for the node with the given name in the linked list
    int index = searchHashTable(name);
    if (index == -1) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the node from the linked list and free its memory
    node_t* toDelete = head;
    for (int i = 0; i < index; i++) {
        toDelete = toDelete->next;
    }
    head = toDelete->next;
    free(toDelete);

    // Remove the name from the hash table
    removeHashTableEntry(name);

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a data item from the list based on its name
dataItem_t* getDataItem(char* name) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Search for the node with the given name in the linked list
    int index = searchHashTable(name);
    if (index == -1) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Return the data item from the found node
    node_t* current = head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return current->data;
}

// Function to search for a name in the hash table, returning its index if found
int searchHashTable(char* name) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Search for the given name in the hash table
    int index = -1;
    for (int i = 0; i < hashTable.size; i++) {
        if (strcmp(hashTable.keys[i], name) == 0) {
            index = i;
            break;
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
    return index;
}

// Function to add an entry to the hash table, growing it if necessary
void addHashTableEntry(char* name, node_t* node) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the hash table needs to be grown
    int size = hashTable.size;
    if (size == 0 || size * loadFactor < hashTable.keys->length) {
        // Create a new array of keys and values, double the size of the old one
        char** newKeys = malloc(sizeof(char*) * size * 2);
        node_t** newValues = malloc(sizeof(node_t*) * size * 2);

        // Copy over the old keys and values to the new array
        for (int i = 0; i < size; i++) {
            newKeys[i] = hashTable.keys[i];
            newValues[i] = hashTable.values[i];
        }

        // Free the old arrays and update the pointers to the new ones
        free(hashTable.keys);
        free(hashTable.values);
        hashTable.keys = newKeys;
        hashTable.values = newValues;
    }

    // Add the name and node to the hash table
    hashTable.keys[size] = name;
    hashTable.values[size] = node;
    hashTable.size++;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove an entry from the hash table, shrinking it if necessary
void removeHashTableEntry(char* name) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Search for the given name in the hash table
    int index = -1;
    for (int i = 0; i < hashTable.size; i++) {
