    hashTable.size--;

    // Shrink the array of keys and values if necessary
    int size = hashTable.size;
    float loadFactor = 0.75;
    if (size * loadFactor < hashTable.keys->length) {
        char** newKeys = malloc(sizeof(char*) * size);
        node_t** newValues = malloc(sizeof(node_t*) * size);

        // Copy over the old keys and values to the new array
        for (int i = 0; i < size; i++) {
