    rec->timestamp = t + rand() % 61;
  }

  // Allocate memory for the buffer field in each record, if necessary
  for (size_t i = 0; i < n; i++) {
    Record* rec = pool->records[keys[i]];
    if (rec->offset > buffer_size) {
      rec->buffer = (char*)malloc(rec->offset * sizeof(char));
    }
  }

  // Free any unnecessary memory in the custom memory pool, if necessary
  for (size_t i = 0; i < n; i++) {
    Record* rec = pool->records[keys[i]];
    if (rec->buffer == NULL) {
      free(rec);
    }
  }

