// Define a record manager class that manages the records
class RecordManager {
public:
    // Constructor
    RecordManager(const size_t capacity, const int increment) :
        capacity_(capacity),
        increment_(increment) {}

    // Method to add a new record to the vector
    void addRecord(const long offset, const int key, const int value) {
        // Acquire the lock to prevent concurrent access
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the vector needs to be resized
        if (records_.size() == capacity_) {
            // Resize the vector by the specified increment
            records_.resize(records_.size() + increment_);
        }

        // Add the new record to the vector
        records_.push_back({ offset, key, value });
    }

    // Method to retrieve a specific record from the vector
