using namespace std;

struct Record {
  int key;
  long offset;
};

class DynamicRecordCollection {
 private:
  // Map to store record keys and their corresponding offsets
  map<int, long> recordMap_;

  // Array to store record values
  vector<Record> records_;

  // Mutex to protect concurrent access to the collection
  mutex collectionMutex_;

  // File stream for persisting the collection to disk
  ofstream collectionFile;

  // Periodically persist the collection to disk every 5 minutes
  const long PERSIST_INTERVAL = 5 * 60 * 1000;

  // Dynamic update mechanism for maximum allowable length of record keys
  const int MAX_KEY_LENGTH = 256;

 public:
  DynamicRecordCollection() {
    // Initialize the map and vector
    recordMap_.clear();
    records_.clear();
  }

  ~DynamicRecordCollection() {
    // Close the file stream if it's still open
    if (collectionFile.is_open()) {
      collectionFile.close();
    }
  }

  void insert(int key, long offset) {
    // Acquire the mutex before modifying the collection
    std::lock_guard<std::mutex> lock(collectionMutex_);

    // Check if the record already exists in the map
    auto it = recordMap_.find(key);
    if (it != recordMap_.end()) {
      return;
    }

    // Add a new record to the map and vector
    recordMap_[key] = offset;
    records_.push_back({ key, offset });
  }

  void remove(int key) {
    // Acquire the mutex before modifying the collection
    std::lock_guard<std::mutex> lock(collectionMutex_);

    // Check if the record exists in the map
    auto it = recordMap_.find(key);
    if (it == recordMap_.end()) {
      return;
    }

    // Remove the record from the map and vector
    recordMap_.erase(it);
    for (auto& record : records_) {
      if (record.key == key) {
        records_.erase(record);
        break;
      }
    }
  }

  bool contains(int key) {
    // Acquire the mutex before accessing the collection
    std::lock_guard<std::mutex> lock(collectionMutex_);

    // Check if the record exists in the map
    return recordMap_.find(key) != recordMap_.end();
  }

  long getOffset(int key) {
    // Acquire the mutex before accessing the collection
    std::lock_guard<std::mutex> lock(collectionMutex_);

    // Check if the record exists in the map
    auto it = recordMap_.find(key);
    if (it == recordMap_.end()) {
      return -1;
    }

    // Return the offset value for the key
    return it->second;
  }

  void query(const string& searchTerm) {
    // Acquire the mutex before accessing the collection
    std::lock_guard<std::mutex> lock(collectionMutex_);

    // Loop through each record and check if its key matches the search term
    for (auto& record : records_) {
      if (record.key == searchTerm) {
        // Print out the matching record
        cout << "Record found: " << record.key << " -> " << record.offset << endl;
      }
    }
  }

  void updateMaxKeyLength(int newMaxLength) {
    // Acquire the mutex before modifying the collection
    std::lock_guard<std::mutex> lock(collectionMutex_);

    // Update the maximum allowable length of record keys
    MAX_KEY_LENGTH = newMaxLength;
  }
};
```
