    if (list == NULL) {
        return NULL;
    }
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&list->mutex);
    list->head = NULL;
    list->num_nodes = 0;
    pthread_mutex_unlock(&list->mutex);
    return list;
}

void destroy_node_list(struct node_list* list) {
    if (list == NULL) {
        return;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
