            // If the node to be removed is the head of the list, set the new head
            if (current == list->head) {
                list->head = current->next;
            }
            free(current);
            pthread_mutex_lock(&list->mutex);
            list->num_nodes--;
            pthread_mutex_unlock(&list->mutex);
            break;
        }
        current = current->next;
    }
}

void resize_array(struct node_list* list, size_t new_size) {
    struct node* new_head = malloc(new_size * sizeof(struct node));
    if (new_head == NULL) {
        return;
