    struct node* current = list->head;
    while (current != NULL) {
        new_head[i].value = current->value;
        new_head[i].active = current->active;
        current = current->next;
        i++;
    }
    // Free the old list
    free(list->head);
    list->head = new_head;
    pthread_mutex_unlock(&list->mutex);
}

void print_node_list(struct node_list* list) {
    struct node* current = list->head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");
}
