function generatePEMCertificate(oauthRequest) {
  // Validate the OAuth request to ensure it contains all necessary information
  if (!oauthRequest || !oauthRequest.clientId || !oauthRequest.clientSecret || !oauthRequest.serverEndpoint) {
    return null;
  }

  // Retrieve the private key and certificate files from the secure server endpoint
  const url = new URL(oauthRequest.serverEndpoint);
  const options = {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${oauthRequest.clientId}:${oauthRequest.clientSecret}`,
    },
  };

  try {
    const response = await fetch(url, options);
    if (response.status !== 200) {
      console.error(`Failed to retrieve certificate from server: ${response.status}`);
      return null;
    }

    // Combine the private key and certificate files into a single PEM file
    const pem = response.body.getReader().read().then(({ value }) => {
      if (!value) {
        console.error('Failed to retrieve certificate from server');
        return null;
      }

      // Handle potential errors during the retrieval process and log appropriate messages for debugging purposes
      try {
        const pem = new TextDecoder().decode(value);
        if (!pem) {
          console.error('Failed to decode certificate from server');
          return null;
        }

        // Return the combined PEM file
        return pem;
      } catch (err) {
        console.error(`Error decoding certificate from server: ${err}`);
        return null;
      }
    });
  } catch (err) {
    console.error(`Error retrieving certificate from server: ${err}`);
    return null;
  }
}
