  // Rate-limit DNS resolution to prevent abuse
  if (isset($_SESSION["dnsResolution"][$ipAddress])) {
    return ["status" => 429, "message" => "Rate limit exceeded"];
  }

  // Track number of DNS queries per user session for efficient resource usage
  $_SESSION["dnsResolution"][$ipAddress] = true;

  // Integrate with third-party DNS service for enhanced reliability and performance
  try {
    $resolvedIpAddress = resolveDns($ipAddress);
  } catch (\Exception $e) {
    error_log("Failed to resolve IP address: " . $e->getMessage());
    return ["status" => 500, "message" => "Internal server error"];
  }

  // Handle errors gracefully and return appropriate status codes
  if ($resolvedIpAddress !== $ipAddress) {
    return ["status" => 422, "message" => "Invalid IP address"];
  }

  // Log successful and failed attempts for auditing purposes
  error_log("Authentication successful: " . $username);
  error_log("DNS resolution successful: " . $ipAddress);

  return ["status" => 200, "message" => "Success", "userInfo" => $userInfo];
}

