// Structure to represent a session object
typedef struct Session {
    long timestamp;
    int session_id;
    double activity_level;
} Session;

// Function to dynamically manage memory for and initialize a list of session objects
Session* create_session_list(int capacity) {
    // Allocate memory for the list of sessions
    Session* sessions = malloc(capacity * sizeof(Session));

    // Initialize each session object with default values
    for (int i = 0; i < capacity; i++) {
        sessions[i].timestamp = -1;
        sessions[i].session_id = -1;
        sessions[i].activity_level = 0.0;
    }

    return sessions;
}

// Function to add a new session object to the list and update its activity level
void add_session(Session* sessions, int capacity, long timestamp, int session_id, double activity_level) {
    // Find the index of the first empty slot in the list
    int i = 0;
    while (sessions[i].timestamp != -1 && i < capacity) {
        i++;
    }

    // If no empty slots found, resize the list and add a new session object
    if (i == capacity) {
        sessions = realloc(sessions, (capacity + 1) * sizeof(Session));
        sessions[capacity].timestamp = -1;
        sessions[capacity].session_id = -1;
        sessions[capacity].activity_level = 0.0;
        capacity++;
    }

    // Add the new session object and update its activity level
    sessions[i].timestamp = timestamp;
    sessions[i].session_id = session_id;
    sessions[i].activity_level = activity_level;
}

// Function to find and print the most active session within a specified time window
void get_most_active_session(Session* sessions, int capacity, long start_timestamp, long end_timestamp) {
    // Find the index of the first session object with a timestamp greater than or equal to start_timestamp
    int i = 0;
    while (i < capacity && sessions[i].timestamp < start_timestamp) {
        i++;
    }

    // If no session objects found, return -1
    if (i == capacity) {
        printf("-1\n");
        return;
    }

    // Find the index of the last session object with a timestamp less than or equal to end_timestamp
    int j = i;
    while (j < capacity && sessions[j].timestamp <= end_timestamp) {
        j++;
    }

    // If no session objects found, return -1
    if (j == capacity) {
        printf("-1\n");
        return;
    }

    // Find the most active session within the specified time window
    int max_session = i;
    for (int k = i + 1; k < j; k++) {
        if (sessions[k].activity_level > sessions[max_session].activity_level) {
            max_session = k;
        }
    }

    // Print the most active session ID and activity level
    printf("%d %lf\n", sessions[max_session].session_id, sessions[max_session].activity_level);
}

// Function to read a list of timestamps from standard input and update the session objects
void read_timestamps(Session* sessions, int capacity) {
    // Read a line of input from standard input
    char* line = malloc(1024 * sizeof(char));
    gets(line);

    // Parse the input line into tokens separated by spaces
    char* token = strtok(line, " ");
    while (token != NULL) {
        // If the current token is a valid timestamp...
        if (is_valid_timestamp(token)) {
            long timestamp = atol(token);

            // Find the index of the session object with the corresponding timestamp
            int i = 0;
            while (i < capacity && sessions[i].timestamp != timestamp) {
                i++;
            }

            // If a valid session object found...
            if (i < capacity) {
                // Update its activity level
                double activity_level = get_activity_level(sessions, capacity, i);
                add_session(sessions, capacity, timestamp, sessions[i].session_id, activity_level + 1.0);
            }
        }

        token = strtok(NULL, " ");
    }
}

// Function to validate a timestamp input and convert it to an integer value
bool is_valid_timestamp(char* timestamp) {
    // Check if the input string is a valid integer
    for (int i = 0; i < strlen(timestamp); i++) {
        if (!isdigit(timestamp[i])) {
            return false;
        }
    }

    return true;
}

// Function to get the activity level of a session object
double get_activity_level(Session* sessions, int capacity, int index) {
    return sessions[index].activity_level;
}
