typedef struct {
    size_t size;
    size_t capacity;
    RX_UE_INFORMATION_TAG* data;
} LTE_PHY_RX_API_UU_RXINDICATIONS_ARRAY;

// Define the function to manage the dynamic array of LTE_PHY_RX_API_UU_RXINDICATIONS structures
void manage_rx_ue_information(LTE_PHY_RX_API_UU_RXINDICATIONS_ARRAY* array, uint32_t rx_ue_information_tag, uint16_t rnti, uint8_t* lte_phy_rx_api_uu_rxindications_cgi) {
    // Create a semaphore for synchronizing access to the array
    sem_t* sem = sem_open("/sem", O_CREAT, 0644, 1);

    // Acquire the semaphore and check if there is enough space in the array
    sem_wait(sem);
    if (array->size >= array->capacity) {
        // If not, double the capacity of the array
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(RX_UE_INFORMATION_TAG));
    }

    // Insert a new element into the array
    RX_UE_INFORMATION_TAG* element = &array->data[array->size++];
    element->rx_ue_information_tag = rx_ue_information_tag;
    element->rnti = rnti;
    memcpy(element->lte_phy_rx_api_uu_rxindications_cgi, lte_phy_rx_api_uu_rxindications_cgi, 4);

    // Release the semaphore
    sem_post(sem);
}

// Define a function to clear the array of LTE_PHY_RX_API_UU_RXINDICATIONS structures
void clear_rx_ue_information(LTE_PHY_RX_API_UU_RXINDICATIONS_ARRAY* array) {
    // Create a semaphore for synchronizing access to the array
    sem_t* sem = sem_open("/sem", O_CREAT, 0644, 1);

    // Acquire the semaphore and clear the array
    sem_wait(sem);
    array->size = 0;
    free(array->data);
    array->data = NULL;

    // Release the semaphore
    sem_post(sem);
}
