    unordered_map<string, Resource> resources;

    // The total memory usage in bytes allocated for all resources
    size_t totalMemoryUsage = 0;

    // The maximum length of names allowed in the resource structures
    int maxNameLength = 32;

    // The acceptable range of values stored in the `resource` structures
    float minValue, maxValue;

public:
    ResourcePool(float minValue, float maxValue) : minValue(minValue), maxValue(maxValue) {}

    // Insert a resource into the pool
    void insertResource(const string& name, const float& capacity) {
        if (totalMemoryUsage + sizeof(Resource) > 5000000) {
            // Handle memory exhaustion
            return;
        }

        Resource r = {name, capacity};

        resources[r.name] = r;

        totalMemoryUsage += sizeof(Resource);
    }

    // Delete a resource from the pool
    void deleteResource(const string& name) {
        if (resources.count(name) == 0) {
            return;
        }

        Resource r = resources[name];
        totalMemoryUsage -= sizeof(Resource);

        resources.erase(name);
    }

    // Retrieve a resource from the pool based on its name
    const Resource& getResource(const string& name) {
        return resources[name];
    }

    // Find and print the resource with the highest capacity
    void findHighestCapacity() {
        auto it = resources.begin();
        for (; it != resources.end(); ++it) {
            if (it->second.capacity > 0) {
                break;
            }
        }

        cout << "Resource with highest capacity: " << it->first << ", " << it->second.capacity << endl;
    }

    // Query the collection based on a substring match within the resource names
    vector<string> queryResources(const string& substr) {
        vector<string> results;
        for (auto it = resources.begin(); it != resources.end(); ++it) {
            if (it->first.find(substr) != string::npos) {
                results.push_back(it->first);
            }
        }
        return results;
    }

    // Serialize the resource collection to a JSON format for easy data interchange and storage
    json serialize() {
        json j;
        for (auto it = resources.begin(); it != resources.end(); ++it) {
            j[it->first] = it->second.capacity;
        }
        return j;
    }

    // Deserialize the resource collection from a JSON format
    void deserialize(const json& j) {
        for (auto it = resources.begin(); it != resources.end(); ++it) {
            auto capacity = j[it->first].get<float>();
            Resource r = {it->first, capacity};
            resources[r.name] = r;
        }
    }

    // Dynamic update mechanism for the maximum length of names allowed in the resource structures
    void updateMaxNameLength(int newMaxNameLength) {
        if (newMaxNameLength < 0) {
            return;
        }

        maxNameLength = newMaxNameLength;
    }

    // Dynamic update mechanism for the acceptable range of values stored in the `resource` structures
    void updateMinMaxValues(float newMinValue, float newMaxValue) {
        if (newMinValue > newMaxValue || newMinValue < 0 || newMaxValue > 100) {
            return;
        }

        minValue = newMinValue;
        maxValue = newMaxValue;
    }
};
