// Define a struct to represent a single record in the dataset
struct Record {
    long offset;
    int key;
    int value;
};

// Define a buffer structure to store records and manage memory usage
struct Buffer {
    struct Record *records; // Array of records
    size_t capacity; // Maximum number of records that can be stored in the buffer
    size_t count; // Number of records currently stored in the buffer
};

// Initialize a new buffer with the specified capacity
void init_buffer(struct Buffer *buf, size_t capacity) {
    buf->records = (struct Record *)malloc(capacity * sizeof(struct Record));
    if (!buf->records) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        exit(1);
    }
    buf->capacity = capacity;
    buf->count = 0;
}

// Insert a new record into the buffer
void insert_record(struct Buffer *buf, long offset, int key, int value) {
    if (buf->count == buf->capacity) {
        // Resize the buffer if it is full
        buf->capacity += 10;
        buf->records = (struct Record *)realloc(buf->records, buf->capacity * sizeof(struct Record));
        if (!buf->records) {
            fprintf(stderr, "Failed to resize buffer\n");
            exit(1);
        }
    }
    // Add the new record to the end of the buffer
    buf->records[buf->count].offset = offset;
    buf->records[buf->count].key = key;
    buf->records[buf->count].value = value;
    buf->count++;
}

// Find and print the largest integer in the buffer
void find_largest(struct Buffer *buf) {
    int largest = -1; // Initialize with a small negative value
    for (int i = 0; i < buf->count; i++) {
        if (buf->records[i].value > largest) {
            largest = buf->records[i].value;
        }
    }
    printf("Largest integer: %d\n", largest);
}

// Read a list of integers from standard input and store them in an array
void read_integers(struct Buffer *buf) {
    int n; // Number of integers to read
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int key, value;
        scanf("%d %d", &key, &value);
        insert_record(buf, key * 100, key, value);
    }
}

// Free the memory used by the buffer
void free_buffer(struct Buffer *buf) {
    free(buf->records);
}

int main() {
    struct Buffer buf;
    init_buffer(&buf, 1000); // Initialize with a capacity of 1000 records

    read_integers(&buf); // Read integers from standard input and store them in the buffer

    find_largest(&buf); // Find and print the largest integer in the buffer

    free_buffer(&buf); // Free the memory used by the buffer

    return 0;
}
```
