```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/aes.h>

// Define the structure for a record in the library
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the array to store the records
Record *records = NULL;
size_t num_records = 0;

// Define the fixed increment factor for calculating offsets
const int INCREMENT_FACTOR = 10;

// Define the range of random values for initializing the int field
const int MIN_VALUE = 0;
const int MAX_VALUE = 100;

// Define the maximum number of records that can be stored in the library
#define MAX_NUM_RECORDS 10000000

// Function to add a new record to the library
void add_record(Record *record) {
    // Check if the array is full and needs to be resized
    if (num_records >= MAX_NUM_RECORDS) {
        records = realloc(records, num_records * 2 * sizeof(Record));
    }

    // Calculate the offset for the new record
    record->offset = INCREMENT_FACTOR * record->key;

    // Initialize the int field of the new record to a random value within the range
    record->value = MIN_VALUE + (rand() % (MAX_VALUE - MIN_VALUE));

    // Add the new record to the array
    records[num_records++] = *record;
}

// Function to remove a record from the library by key
void remove_record(int key) {
    // Find the index of the record with the given key in the array
    size_t i = 0;
    while (i < num_records && records[i].key != key) {
        i++;
    }

    // Check if the record was found and remove it from the array
    if (i < num_records) {
        memmove(&records[i], &records[i + 1], (num_records - i - 1) * sizeof(Record));
        num_records--;
    }
}

// Function to retrieve a record from the library by key
void get_record(int key, Record *record) {
    // Find the index of the record with the given key in the array
    size_t i = 0;
    while (i < num_records && records[i].key != key) {
        i++;
    }

    // Check if the record was found and return it
    if (i < num_records) {
        memcpy(record, &records[i], sizeof(Record));
    } else {
        // Record not found, set all fields to 0
        memset(record, 0, sizeof(Record));
    }
}

// Function to clear the library and free the memory allocated for it
void clear_library() {
    // Free the memory allocated for the records array
    free(records);
    records = NULL;
    num_records = 0;
}
