    int hash_val = hash(identifier) % ht->size;
    struct node* current = ht->buckets[hash_val];
    struct node* previous = NULL;

    while (current != NULL && strcmp(current->identifier, identifier) != 0) {
        previous = current;
        current = current->next;
    }

