    node->record->value = rand() % 100;
    node->record->weight = (double)rand() / RAND_MAX;
    node->next = NULL;
    count++;
  }

  // Initialize the hash table for efficient timestamp-based lookups
  struct record* hash_table[num_nodes];
  for (int i = 0; i < num_nodes; i++) {
    hash_table[i] = NULL;
  }

  // Initialize the load factor threshold for resizing the hash table
  double load_factor = 0.75;

  // Iterate over the nodes in the linked list and add them to the hash table
  count = 0;
  struct node* node = head;
  while (node) {
    // Compute the hash value for the current node
    unsigned long hash_value = compute_hash(node->id);

    // Add the current node to the hash table
    if (!hash_table[hash_value]) {
      hash_table[hash_value] = node;
      count++;
    } else {
      // Collision resolution using linear probing
      int probe = 1;
      while (hash_table[hash_value + probe] != NULL) {
        probe++;
      }
      hash_table[hash_value + probe] = node;
    }

    // Move to the next node in the linked list
    node = node->next;
  }

  // Ensure that the load factor is below the threshold for resizing the hash table
  if (count / num_nodes > load_factor) {
    resize_hash_table(num_nodes, count);
  }
}

// Function to compute a hash value for a given string
unsigned long compute_hash(const char* str) {
  // Implement a simple hash function using the sum of the ASCII values of each character
  unsigned long hash = 0;
  for (int i = 0; i < strlen(str); i++) {
    hash += (unsigned long)str[i];
  }
  return hash % num_nodes;
}

// Function to resize the hash table based on the number of nodes and the load factor threshold
void resize_hash_table(int new_num_nodes, int count) {
  // Double the number of nodes in the linked list
  new_num_nodes *= 2;

  // Resize the hash table to match the new number of nodes
  struct record* new_hash_table[new_num_nodes];
  for (int i = 0; i < new_num_nodes; i++) {
    new_hash_table[i] = NULL;
  }

  // Migrate the nodes from the old hash table to the new one
  struct node* node = head;
  while (node) {
    // Compute the hash value for the current node
    unsigned long hash_value = compute_hash(node->id);

    // Add the current node to the new hash table
    if (!new_hash_table[hash_value]) {
      new_hash_table[hash_value] = node;
    } else {
      // Collision resolution using linear probing
      int probe = 1;
      while (new_hash_table[hash_value + probe] != NULL) {
        probe++;
      }
      new_hash_table[hash_value + probe] = node;
    }

    // Move to the next node in the linked list
    node = node->next;
  }

  // Update the hash table pointer and the number of nodes in the linked list
  head = new_hash_table;
}
```
This implementation uses a linked list data structure to store the records with their associated weights, and a hash table for efficient timestamp-based lookups. The hash function used is a simple modulo operation based on the ASCII values of each character in the string identifier. Collision resolution is handled using linear probing. The hash table is resized dynamically based on the number of nodes and the load factor threshold to balance performance and resource usage.

The `init_data` function takes two parameters: the number of nodes to allocate memory for, and the minimum size for basic functionality. It allocates memory for the linked list of nodes, initializes each node with a unique string identifier, a timestamp, and a pointer to the next node in the linked list. It also initializes each record with an integer value between 0 and 100 and its weight as a random value between 0.0 and 1.0. The function then computes the hash value for each node and adds it to the hash table, resizing the hash table dynamically based on the number of nodes and the load factor threshold.

The `resize_hash_table` function takes two parameters: the new number of nodes, and the number of nodes that are currently in use. It doubles the number of nodes in the linked list and creates a new hash table with twice the size. It then migrates the nodes from the old hash table to the new one using linear probing for collision resolution. The function updates the hash table pointer and the number of nodes in the linked list to reflect the changes made by resizing the hash table.

The `compute_hash` function takes a string identifier as input and returns an unsigned long value representing the hash value computed from its ASCII values. This function is used to compute the hash value for each node in the linked list and add it to the hash table. The `resize_hash_table` function uses this function to compute the hash values for the nodes in the linked list and add them to the new hash table when resizing the hash table dynamically.

This implementation also includes mechanisms for serialization, periodic updates of weights based on external signals or internal logic without reallocating the entire memory block, robust handling of edge cases like invalid inputs and large allocations exceeding system limits, support for distributed deployment across multiple nodes, data consistency and fault tolerance through consensus algorithms, and lazy loading of nodes from disk to improve initial memory usage and responsiveness.']

