using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using ImageMetadataExtractor;
using MetadataExtractor;

public static class ImageProcessor {
    public static async Task<ProcessedImage> ProcessImageAndExtractMetadataAsync(string filePath) {
        var image = new MagickImage(filePath);
        if (!IsSupportedBitsPerSample(image.Depth)) {
            throw new ArgumentException("Unsupported bits per sample", nameof(filePath));
        }

        // Extract metadata
        var exifReader = new ExifReader();
        var xmpReader = new XmpReader();
        var metadata = await Task.WhenAll(exifReader.ReadMetadataAsync(image), xmpReader.ReadMetadataAsync(image));
        var extractedMetadata = metadata.SelectMany(x => x).ToDictionary(x => x.Tag, x => x.Value);

        // Compute MD5 hash
        using (var stream = new MemoryStream()) {
            image.Write(stream);
            var md5Hash = MD5.Create().ComputeHash(stream);
            var md5HashString = BitConverter.ToString(md5Hash).Replace("-", "");
        }

        // Generate report
        var dimensions = $"{image.Width} x {image.Height}";
        var resolution = $"{image.ResolutionX} dpi";
        var compressionMethod = image.CompressionMethod;
        var appliedTags = string.Join(", ", extractedMetadata.Keys);

        // Integrate with external metadata extraction service
        try {
            var httpClient = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Post, "https://metadata-extraction-service/extract");
            var payload = new { filePath };
            request.Content = new StringContent(JsonConvert.SerializeObject(payload), Encoding.UTF8, "application/json");
            var response = await httpClient.SendAsync(request);
            if (response.IsSuccessStatusCode) {
                var responseContent = await response.Content.ReadAsStringAsync();
                var externalMetadata = JsonConvert.DeserializeObject<Metadata>(responseContent);
                extractedMetadata.AddRange(externalMetadata);
            }
        } catch (Exception ex) {
            Console.WriteLine($"Failed to integrate with external metadata extraction service: {ex.Message}");
        }

        return new ProcessedImage {
            FilePath = filePath,
            Dimensions = dimensions,
            Resolution = resolution,
            CompressionMethod = compressionMethod,
            AppliedTags = appliedTags,
            ExtractedMetadata = extractedMetadata,
            Md5Hash = md5HashString
        };
    }

    private static bool IsSupportedBitsPerSample(ushort bitsPerSample) {
        return bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16;
    }
}

public class ProcessedImage {
    public string FilePath { get; set; }
    public string Dimensions { get; set; }
    public string Resolution { get; set; }
    public string CompressionMethod { get; set; }
    public string AppliedTags { get; set; }
    public Dictionary<string, object> ExtractedMetadata { get; set; }
