// Function to add a new key-value pair to the hash table
void addKeyValuePair(int key, double weight) {
    // Check if the load factor exceeds the maximum threshold
    if (loadFactor >= MAX_LOAD_FACTOR) {
        resizeHashTable();
    }

    unsigned long int index = customHash(key);
    KeyWeightPair* newKeyWeightPair = malloc(sizeof(KeyWeightPair));
    newKeyWeightPair->key = key;
    newKeyWeightPair->weight = weight;

    // If the hash table slot is empty, insert the new pair directly
    if (hashTable[index] == NULL) {
        hashTable[index] = newKeyWeightPair;
    } else {
        KeyWeightPair* currentNode = hashTable[index];

        // Traverse the list and find the end of the list
        while (currentNode->next != NULL) {
            currentNode = currentNode->next;
        }

        // Insert the new pair at the end of the list
        currentNode->next = newKeyWeightPair;
    }

    numKeys++;
}

// Function to remove a key-value pair from the hash table
void removeKeyValuePair(int key) {
    unsigned long int index = customHash(key);
    KeyWeightPair* currentNode = hashTable[index];

    // If the list is empty, do nothing
    if (currentNode == NULL) {
        return;
    }

    // If the key matches the first element in the list, remove it directly
    if (currentNode->key == key) {
        hashTable[index] = currentNode->next;
        free(currentNode);
        numKeys--;
        return;
    }

    // Traverse the list and find the matching key-value pair
    while (currentNode->next != NULL) {
        if (currentNode->next->key == key) {
            KeyWeightPair* temp = currentNode->next;
            currentNode->next = temp->next;
            free(temp);
            numKeys--;
            return;
        }

        currentNode = currentNode->next;
    }
}

