        if (currentNode->next->key == key) {
            currentNode->next->weight = weight;
            return;
        }

        currentNode = currentNode->next;
    }
}

// Function to retrieve the weight of an existing key-value pair in the hash table
double getWeight(int key) {
    unsigned long int index = customHash(key);
    KeyWeightPair* currentNode = hashTable[index];

    // If the list is empty, return 0
