    // Traverse the list and find the matching key-value pair
    while (currentNode->next != NULL) {
        if (currentNode->next->key == key) {
            return currentNode->next->weight;
        }

        currentNode = currentNode->next;
    }

    return 0;
}

// Function to resize the hash table when the load factor exceeds the maximum threshold
void resizeHashTable() {
    int oldSize = HASH_TABLE_SIZE;
    KeyWeightPair** oldHashTable = hashTable;
    HASH_TABLE_SIZE *= 2;
    hashTable = malloc(HASH_TABLE_SIZE * sizeof(KeyWeightPair*));

