#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <chrono>
#include <thread>

using namespace std;

// Attack class to store attack name and strength
class Attack {
 public:
  string name;
  double strength;
};

// DynamicAttackManager class to manage attacks
class DynamicAttackManager {
 private:
  vector<Attack> attacks_; // Vector of attacks
  size_t maxNameLength_;   // Maximum length of attack names
  double maxStrength_;     // Maximum strength of all attacks
  size_t totalSize_;       // Total memory usage in bytes

 public:
  DynamicAttackManager() : maxNameLength_(0), maxStrength_(0), totalSize_(0) {}

  // Insert an attack into the manager
  void insert(const string& name, double strength) {
    attacks_.push_back({name, strength});
    maxNameLength_ = max(maxNameLength_, name.size());
    maxStrength_ = max(maxStrength_, strength);
    totalSize_ += sizeof(Attack);
  }

  // Delete an attack from the manager
  void delete(const string& name) {
    auto it = find(attacks_.begin(), attacks_.end(), [&](const Attack& a) { return a.name == name; });
    if (it != attacks_.end()) {
      totalSize_ -= sizeof(*it);
      attacks_.erase(it);
    }
  }

  // Find the attack with the longest name in the manager
  const Attack& findLongestName() const {
    return *max_element(attacks_.begin(), attacks_.end(), [](const Attack& a, const Attack& b) { return a.name < b.name; });
  }

  // Find all attacks that contain the specified substring in their name
  vector<Attack> findSubstring(const string& substring) const {
    vector<Attack> matches;
    for (const Attack& attack : attacks_) {
      if (attack.name.find(substring) != string::npos) {
        matches.push_back(attack);
      }
    }
    return matches;
  }

  // Serialize the attack collection to JSON format
  string serialize() const {
    json j;
    for (const Attack& attack : attacks_) {
      j["attacks"].push_back({{"name", attack.name}, {"strength", attack.strength}});
    }
    return j.dump();
  }

  // Deserialize the attack collection from JSON format
  void deserialize(const string& jsonStr) {
    json j = json::parse(jsonStr);
    attacks_.clear();
    for (const auto& attack : j["attacks"]) {
      attacks_.push_back({{"name", attack["name"]}, {"strength", attack["strength"]}});
    }
  }

  // Save the attack collection to disk periodically
  void saveToDisk() const {
    ofstream file("attacks.json");
    if (file) {
      file << serialize();
      file.close();
    }
  }

  // Load the attack collection from disk
  void loadFromDisk() {
    ifstream file("attacks.json");
    if (file) {
      string jsonStr;
      while (getline(file, line)) {
        jsonStr += line + "\n";
      }
      deserialize(jsonStr);
    }
  }
};

// Simulate a cooldown period for attack selection
void simulateCooldown() {
  this_thread::sleep_for(chrono::seconds(9));
}

int main() {
  // Load attacks from disk
  DynamicAttackManager manager;
  manager.loadFromDisk();

  // Print the longest attack name
  const Attack& longestName = manager.findLongestName();
  cout << "The longest attack name is: " << longestName.name << endl;

  // Query attacks based on a specified substring
  vector<Attack> matches = manager.findSubstring("fire");
  for (const Attack& match : matches) {
    cout << "Attack with name containing the substring 'fire': " << match.name << endl;
  }

  // Insert and delete attacks dynamically
  manager.insert("new attack", 10);
  manager.delete("new attack");

  // Serialize and deserialize the attack collection to/from JSON format
  string jsonStr = manager.serialize();
  manager.deserialize(jsonStr);

  // Save the attack collection to disk periodically
  manager.saveToDisk();

  // Simulate cooldown period for attack selection
  simulateCooldown();

  return 0;
}
