void manageCollections(int numRecords, int numItems, char** recordNames, char** itemNames, double* values) {
    // Initialize the largest integer and longest string
    int largestInt = INT_MIN;
    char* longestString = "";

    // Create a dynamic collection of items
    Item* items = (Item*) malloc(sizeof(Item) * numItems);

    // Loop through each item and store its name and value
    for (int i = 0; i < numItems; i++) {
        items[i].name = strdup(itemNames[i]);
        items[i].value = values[i];
    }

    // Loop through each record and find the largest integer and longest string
    for (int i = 0; i < numRecords; i++) {
        int currentInt = 0;
        char* currentString = "";
        for (int j = 0; j < strlen(recordNames[i]); j++) {
            if (isdigit(recordNames[i][j])) {
                currentInt *= 10;
                currentInt += recordNames[i][j] - '0';
            } else {
                currentString = strdup(recordNames[i] + j);
                break;
            }
        }
        if (currentInt > largestInt) {
            largestInt = currentInt;
        }
        if (strlen(currentString) > strlen(longestString)) {
            longestString = currentString;
        }
    }

    // Print the results
    printf("Largest integer: %d\n", largestInt);
    printf("Longest string: %s\n", longestString);

    // Clean up the items and record names
    for (int i = 0; i < numItems; i++) {
        free(items[i].name);
    }
    free(items);
    for (int i = 0; i < numRecords; i++) {
        free(recordNames[i]);
