    int numMatchingItems = 0;

    // Loop through each item and check if its name contains the specified substring
    for (int i = 0; i < numItems; i++) {
        char* itemName = items[i].name;
        while (*itemName != '\0') {
            if (*itemName == *substring) {
                matchingItems[numMatchingItems] = &items[i];
                numMatchingItems++;
                break;
            }
            itemName++;
        }
    }

    // Print the results
    printf("Found %d items with substring '%s':\n", numMatchingItems, substring);
    for (int i = 0; i < numMatchingItems; i++) {
        Item* matchingItem = matchingItems[i];
        printf("%s: %f\n", matchingItem->name, matchingItem->value);
    }

    // Clean up the list of matching items
