// Define the structure for a record
typedef struct {
    int key;
} Record;

// Function to initialize an array of records with random values
void init_records(Record* records, size_t num_records, int min_val, int max_val) {
    // Allocate memory for the offset and key arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    // Initialize the offset and key arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_val - min_val + 1) + min_val;
        keys[i] = rand() % max_val;
    }

    // Allocate memory for the record array
    Record* record_array = (Record*)malloc(num_records * sizeof(Record));

    // Initialize each record with the corresponding offset and key
    for (size_t i = 0; i < num_records; i++) {
        record_array[i].key = keys[i];
        record_array[i].offset = offsets[i];
    }

    // Verify the integrity of the data structure
    for (size_t i = 0; i < num_records; i++) {
        if (record_array[i].key != keys[i] || record_array[i].offset != offsets[i]) {
            printf("Error: Integrity check failed!\n");
            return;
        }
    }

    // Print the initialized array of records
    printf("Initialized array of %zu records:\n", num_records);
    for (size_t i = 0; i < num_records; i++) {
        printf("%d: offset=%ld, key=%d\n", i, record_array[i].offset, record_array[i].key);
    }

    // Free the allocated memory
    free(offsets);
    free(keys);
    free(record_array);
}
```
