    crc_array[j - 1] = crc_array[j];
  }
  --crc_array->length;

  // Release the mutex lock
  pthread_mutex_unlock(&crc_array_mutex);
}

// Function for serializing the entire array for persistent storage
void serialize(void) {
  // Acquire the mutex lock
  pthread_mutex_lock(&crc_array_mutex);

  // Serialize the array
  FILE *file = fopen("crc_data.bin", "wb");
  if (file == NULL) {
