}

// Function for deserializing the entire array from persistent storage
void deserialize(void) {
  // Acquire the mutex lock
  pthread_mutex_lock(&crc_array_mutex);

  // Deserialize the array
  FILE *file = fopen("crc_data.bin", "rb");
  if (file == NULL) {
