    // Open the input file for reading
    if ((context->file_descriptor = open(context->input_file_path, O_RDONLY)) < 0) {
        fprintf(stderr, "Error: Failed to open input file %s\n", context->input_file_path);
        return;
    }

    // Create a temporary file for output
    char* temp_output_path = (char*) malloc(strlen(context->output_file_path) + 6);
    strcpy(temp_output_path, context->output_file_path);
    strcat(temp_output_path, ".tmp");
    if ((context->file_descriptor = open(temp_output_path, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR)) < 0) {
        fprintf(stderr, "Error: Failed to create temporary output file %s\n", temp_output_path);
        return;
    }
    free(temp_output_path);

    // Read input file and write to the temporary output file
    size_t read_size = 0;
    char* buffer = (char*) malloc(BUFSIZ);
    while ((read_size = read(context->file_descriptor, buffer, BUFSIZ)) > 0) {
        write(context->file_descriptor, buffer, read_size);
    }
    free(buffer);

    // Close the input file and temporary output file
    close(context->file_descriptor);
    close(context->file_descriptor);

    // Call the third-party library to convert the JPEG file into multiple formats
    struct jpeg_decompress_struct cinfo;
    struct jpeg_compress_struct cdest;
    JSAMPARRAY buffer;
    int row_stride;
    char* output_buffer = (char*) malloc(BUFSIZ);
    FILE* output_file;
    if (!jpeg_read_header(&cinfo, context->input_file_path, TRUE)) {
        fprintf(stderr, "Error: Failed to read JPEG header\n");
        return;
    }
    jpeg_calc_output_dimensions(&cinfo);
    if (!jpeg_start_decompress(&cinfo)) {
        fprintf(stderr, "Error: Failed to start decompression\n");
        return;
    }
    while (cinfo.output_scanline < cinfo.output_height) {
        buffer = jpeg_read_scanlines(&cinfo, &buffer[0], 1);
        row_stride = cinfo.output_width * 3;
        for (int i = 0; i < row_stride; i++) {
            output_buffer[i] = buffer[0][i];
        }
    }
    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    // Create the output files for each format
    char* output_file_path;
    FILE* output_file;
    if (strcmp(context->config.output_format, "PDF") == 0) {
        output_file_path = (char*) malloc(strlen(context->output_file_path) + 4);
        strcpy(output_file_path, context->output_file_path);
        strcat(output_file_path, ".pdf");
        if ((output_file = fopen(output_file_path, "wb")) == NULL) {
            fprintf(stderr, "Error: Failed to create output file %s\n", output_file_path);
            return;
        }
    } else if (strcmp(context->config.output_format, "PNG") == 0) {
        output_file_path = (char*) malloc(strlen(context->output_file_path) + 4);
        strcpy(output_file_path, context->output_file_path);
        strcat(output_file_path, ".png");
        if ((output_file = fopen(output_file_path, "wb")) == NULL) {
            fprintf(stderr, "Error: Failed to create output file %s\n", output_file_path);
            return;
        }
    } else if (strcmp(context->config.output_format, "SVG") == 0) {
        output_file_path = (char*) malloc(strlen(context->output_file_path) + 4);
        strcpy(output_file_path, context->output_file_path);
        strcat(output_file_path, ".svg");
        if ((output_file = fopen(output_file_path, "wb")) == NULL) {
            fprintf(stderr, "Error: Failed to create output file %s\n", output_file_path);
            return;
        }
    } else {
        fprintf(stderr, "Error: Unsupported output format %s\n", context->config.output_format);
        return;
    }

    // Convert the input JPEG file into each requested format using the third-party library
    if (!jpeg_write_header(&cdest, output_file, TRUE)) {
        fprintf(stderr, "Error: Failed to write JPEG header\n");
        return;
    }
    jpeg_set_quality(&cdest, context->config.quality, TRUE);
    jpeg_start_compress(&cdest, TRUE);
    while (cinfo.output_scanline < cinfo.output_height) {
        buffer = jpeg_read_scanlines(&cinfo, &buffer[0], 1);
        row_stride = cinfo.output_width * 3;
        for (int i = 0; i < row_stride; i++) {
            output_buffer[i] = buffer[0][i];
        }
    }
    jpeg_finish_compress(&cdest);
    jpeg_destroy_decompress(&cinfo);

    // Clean up temporary files and resources
    close(context->file_descriptor);
    fclose(output_file);
}
