#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>

// Define constants for memory management
#define MEM_POOL_SIZE 10000 // Size of the custom memory pool in records
#define MAX_RECORDS 10000000 // Maximum number of records to be stored
#define OFFSET_INCREMENT 100 // Fixed increment factor for offset values
#define KEY_MIN 1 // Minimum value for int keys
#define KEY_MAX 1000000000 // Maximum value for int keys
#define VALUE_MIN -1000000000 // Minimum value for record values
#define VALUE_MAX 1000000000 // Maximum value for record values

// Define data structures and types
typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} DataRecord;

// Function to generate a random integer within the specified range
int getRandomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to parse an integer from a string
int parseInt(const char* str) {
    int value = 0;
    sscanf(str, "%d", &value);
    return value;
}

// Function to validate an integer is within the specified range
bool isValidInt(int num, int min, int max) {
    return (num >= min && num <= max);
}

// Custom memory pool for efficient allocation and deallocation of DataRecords
typedef struct {
    DataRecord* records; // Array of DataRecords
    size_t count; // Number of allocated records
} MemoryPool;

void initMemoryPool(MemoryPool* pool) {
    pool->records = (DataRecord*) malloc(sizeof(DataRecord) * MEM_POOL_SIZE);
    pool->count = 0;
}

void addToMemoryPool(MemoryPool* pool, DataRecord record) {
    if (pool->count < MEM_POOL_SIZE) {
        pool->records[pool->count] = record;
        pool->count++;
    } else {
        printf("Error: Memory pool overflow\n");
    }
}

void destroyMemoryPool(MemoryPool* pool) {
    free(pool->records);
    pool->count = 0;
}

// Function to dynamically manage memory for the flexible data processing system
void dynamicMemoryManagement(const char* filename, int key_increment, int value_range) {
    // Initialize variables and allocate memory for arrays
    int* offset_array = (int*) malloc(sizeof(int) * MAX_RECORDS);
    int* key_array = (int*) malloc(sizeof(int) * MAX_RECORDS);
    Record* value_array = (Record*) malloc(sizeof(Record) * MAX_RECORDS);
    long total_mem = 0; // Total memory usage in bytes

    // Initialize arrays and custom memory pool
    for (int i = 0; i < MAX_RECORDS; i++) {
        offset_array[i] = i * key_increment;
        key_array[i] = getRandomInt(KEY_MIN, KEY_MAX);
        value_array[i].value = getRandomInt(VALUE_MIN, VALUE_MAX);
    }
    initMemoryPool(&memory_pool);

    // Read stream of integers from file and validate them
    FILE* fp = fopen(filename, "r");
    int line = 0;
    while (fscanf(fp, "%d", &value) != EOF) {
        if (isValidInt(value, KEY_MIN, KEY_MAX)) {
            // Add valid integer to the array and update total memory usage
            offset_array[line] = key_increment * value;
            key_array[line] = value;
            addToMemoryPool(&memory_pool, (DataRecord) { .offset = offset_array[line], .key = key_array[line], .record = value_array[line] });
            total_mem += sizeof(int); // For the int key and record value
            line++;
        } else {
            printf("Error: Invalid integer in line %d\n", line + 1);
        }
    }
    fclose(fp);

    // Find and print the largest integer in the array
    int largest_int = -1;
    for (int i = 0; i < line; i++) {
        if (key_array[i] > largest_int) {
            largest_int = key_array[i];
        }
    }
    printf("Largest integer in the array: %d\n", largest_int);

    // Clean up memory and exit
    free(offset_array);
    free(key_array);
    destroyMemoryPool(&memory_pool);
    printf("Total memory usage: %lu bytes\n", total_mem);
}

int main() {
    srand((unsigned int) time(NULL)); // Seed the random number generator
    dynamicMemoryManagement("input.txt", OFFSET_INCREMENT, VALUE_RANGE);
    return 0;
