#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to store user profiles
struct profile {
    char* username;
    char* email;
    time_t creation_timestamp;
    struct session* sessions;
};

// Structure to store session data
struct session {
    time_t login_timestamp;
    time_t logout_timestamp;
    int session_id;
    struct session* next;
};

// Function to manage dynamic collections of user profiles and session data
void manage_profiles(FILE* input) {
    // Hash table to store user profiles by email
    struct profile** profiles = malloc(sizeof(struct profile*) * 1000000);
    for (int i = 0; i < 1000000; i++) {
        profiles[i] = NULL;
    }

    // Hash table to store session data by user email and session id
    struct session** sessions = malloc(sizeof(struct session*) * 10000000);
    for (int i = 0; i < 10000000; i++) {
        sessions[i] = NULL;
    }

    // Read input from standard input
    char line[256];
    while (fgets(line, sizeof(line), input)) {
        if (strncmp(line, "REGISTRATION", 12) == 0) {
            // Extract registration details
            char* username = strtok(line, ":");
            char* email = strtok(NULL, ":");
            time_t creation_timestamp = time(NULL);

            // Create new profile structure and add to hash table
            struct profile* new_profile = malloc(sizeof(struct profile));
            new_profile->username = username;
            new_profile->email = email;
            new_profile->creation_timestamp = creation_timestamp;
            new_profile->sessions = NULL;
            profiles[hash(email)] = new_profile;
        } else if (strncmp(line, "SESSION", 7) == 0) {
            // Extract session details
            char* email = strtok(line, ":");
            int session_id = atoi(strtok(NULL, ":"));
            time_t login_timestamp = time(NULL);
            time_t logout_timestamp = time(NULL);

            // Add session to hash table for user profile
            struct session* new_session = malloc(sizeof(struct session));
            new_session->login_timestamp = login_timestamp;
            new_session->logout_timestamp = logout_timestamp;
            new_session->session_id = session_id;
            new_session->next = profiles[hash(email)]->sessions;
            profiles[hash(email)]->sessions = new_session;
        }
    }

    // Deallocate memory for hash tables and linked lists
    for (int i = 0; i < 1000000; i++) {
        if (profiles[i]) {
            free(profiles[i]->username);
            free(profiles[i]->email);
            free(profiles[i]);
            for (struct session* s = profiles[i]->sessions; s != NULL;) {
                struct session* next = s->next;
                free(s);
                s = next;
            }
        }
    }
}

// Function to calculate the total active time for each user across all sessions
void calculate_active_time() {
    // Hash table to store total active time by user email
    struct profile** total_active_time = malloc(sizeof(struct profile*) * 1000000);
    for (int i = 0; i < 1000000; i++) {
        total_active_time[i] = NULL;
    }

    // Iterate over all sessions and calculate total active time for each user
    for (struct profile* p = profiles; p != NULL;) {
        struct session* s = p->sessions;
        while (s != NULL) {
            int user_id = hash(p->email);
            if (total_active_time[user_id] == NULL) {
                total_active_time[user_id] = malloc(sizeof(struct profile));
                total_active_time[user_id]->username = p->username;
                total_active_time[user_id]->email = p->email;
                total_active_time[user_id]->creation_timestamp = p->creation_timestamp;
            }
            total_active_time[user_id]->total_active_time += s->logout_timestamp - s->login_timestamp;
            s = s->next;
        }
    }

    // Deallocate memory for hash table and linked lists
    for (int i = 0; i < 1000000; i++) {
        if (total_active_time[i]) {
            free(total_active_time[i]->username);
            free(total_active_time[i]->email);
            free(total_active_time[i]);
        }
    }
}

// Function to search for users who have logged in within a specified time range
void query_users(time_t start, time_t end) {
    // Hash table to store matching user profiles by email
    struct profile** matches = malloc(sizeof(struct profile*) * 1000000);
    for (int i = 0; i < 1000000; i++) {
        matches[i] = NULL;
    }

    // Iterate over all user profiles and session logs to find matching users
    for (struct profile* p = profiles; p != NULL;) {
        struct session* s = p->sessions;
        while (s != NULL) {
            if (s->login_timestamp >= start && s->logout_timestamp <= end) {
                int user_id = hash(p->email);
                matches[user_id] = p;
            }
            s = s->next;
        }
    }

    // Print matching users to standard output
    for (int i = 0; i < 1000000; i++) {
        if (matches[i]) {
            printf("%s %s\n", matches[i]->username, matches[i]->email);
        }
    }

    // Deallocate memory for hash table and linked lists
    for (int i = 0; i < 1000000; i++) {
        if (matches[i]) {
            free(matches[i]);
        }
    }
}

// Function to deallocate all allocated memory upon completion
void cleanup() {
    for (int i = 0; i < 1000000; i++) {
        if (profiles[i]) {
            free(profiles[i]->username);
            free(profiles[i]->email);
            free(profiles[i]);
            for (struct session* s = profiles[i]->sessions; s != NULL;) {
                struct session* next = s->next;
                free(s);
                s = next;
            }
        }
    }
}
