// Custom memory pool structure to manage memory allocations
typedef struct MemoryPool {
    size_t size; // current allocated size of the pool
    void *buffer; // pointer to the start of the buffer
} MemoryPool;

// Record structure to store values and references to keys
typedef struct Record {
    int value;
    int key;
} Record;

// Function to initialize the data structures
void init_data(long **offsets, int **keys, Record **records) {
    // Allocate memory for the offset array
    *offsets = (long *)malloc(sizeof(long) * INITIAL_SIZE);
    if (*offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Allocate memory for the key array
    *keys = (int *)malloc(sizeof(int) * INITIAL_SIZE);
    if (*keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        exit(1);
    }

    // Allocate memory for the record array
    *records = (Record *)malloc(sizeof(Record) * INITIAL_SIZE);
    if (*records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the offset, key, and record arrays
    memset(*offsets, 0, sizeof(long) * INITIAL_SIZE);
    memset(*keys, -1, sizeof(int) * INITIAL_SIZE);
    memset(*records, 0, sizeof(Record) * INITIAL_SIZE);
}

// Function to resize the memory pool and arrays
void resize_data(long **offsets, int **keys, Record **records, size_t new_size) {
    // Reallocate memory for the offset array
    *offsets = (long *)realloc(*offsets, sizeof(long) * new_size);
    if (*offsets == NULL) {
        printf("Error: Failed to reallocate memory for offsets\n");
        exit(1);
    }

    // Reallocate memory for the key array
    *keys = (int *)realloc(*keys, sizeof(int) * new_size);
    if (*keys == NULL) {
        printf("Error: Failed to reallocate memory for keys\n");
        exit(1);
    }

    // Reallocate memory for the record array
    *records = (Record *)realloc(*records, sizeof(Record) * new_size);
    if (*records == NULL) {
        printf("Error: Failed to reallocate memory for records\n");
        exit(1);
    }
}

// Function to insert a record into the data structures
void insert_record(long offset, int key, Record *record) {
    // Check if the offset already exists in the array
    for (size_t i = 0; i < num_offsets; i++) {
        if (offset == offsets[i]) {
            printf("Error: Offset already exists\n");
            return;
        }
    }

    // Check if the key already exists in the array
    for (size_t i = 0; i < num_keys; i++) {
        if (key == keys[i]) {
            printf("Error: Key already exists\n");
            return;
        }
    }

    // Insert the record into the arrays
    offsets[num_offsets] = offset;
    keys[num_keys] = key;
    records[num_records] = record;

    num_offsets++;
    num_keys++;
    num_records++;
}

// Function to sort the records based on their offsets in ascending order
void sort_records(long **offsets, Record **records) {
    // Bubble sort implementation for simplicity
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (size_t i = 0; i < num_records - 1; i++) {
            if ((*offsets)[i] > (*offsets)[i + 1]) {
                swap((*offsets)[i], (*offsets)[i + 1]);
                swap((*records)[i], (*records)[i + 1]);
                swapped = true;
            }
        }
    }
}

// Function to free all allocated memory upon completion
void cleanup_data(long **offsets, int **keys, Record **records) {
    // Free the offset array
    free(*offsets);

    // Free the key array
    free(*keys);

    // Free the record array
    free(*records);
}
```
Note: This implementation uses a custom memory pool to manage memory allocations, which allows for automatic resizing and bounds checking. The memory pool is implemented using a fixed-size buffer that can be expanded or shrunk as needed. The `init_data()` function initializes the memory pool and arrays with an initial size of 1024 bytes. The `resize_data()` function reallocates the memory pool and arrays to accommodate varying data sizes. The `insert_record()` function inserts a record into the arrays, checking for duplicates and expanding the memory pool as needed. The `sort_records()` function sorts the records based on their offsets in ascending order. The `cleanup_data()` function frees all allocated memory upon completion.

