        private readonly CloudStorageClient cloudStorageClient;
        private readonly MetadataTransformer metadataTransformer;

        public FileMetadataProcessor(string directoryPath = null, List<string> supportedExtensions = null)
        {
            this.directoryPath = directoryPath ?? DEFAULT_DIRECTORY_PATH;
            this.supportedExtensions = supportedExtensions ?? new List<string> { ".jpg", ".png" };
            this.cloudStorageClient = new CloudStorageClient();
            this.metadataTransformer = new MetadataTransformer();
        }

        public async Task ProcessDirectoryAsync()
        {
            // Initialize the directory path and supported file extensions if needed
            await InitializeDirectoryPathAndExtensionsAsync();

            // Extract metadata from files in the directory
            IEnumerable<FileMetadata> fileMetadatas = GetFileMetadatas();

            // Transform the metadata into a standardized JSON format
            var transformedMetadatas = new List<TransformedFileMetadata>();
            foreach (var fileMetadata in fileMetadatas)
            {
                transformedMetadatas.Add(metadataTransformer.Transform(fileMetadata));
            }

            // Validate the transformed data for consistency and completeness
            var validatedTransformedMetadatas = new List<ValidatedTransformedFileMetadata>();
            foreach (var transformedMetadata in transformedMetadatas)
            {
                if (IsValid(transformedMetadata))
                {
                    validatedTransformedMetadatas.Add(transformedMetadata);
                }
            }

            // Send the validated metadata to a cloud storage service
            await cloudStorageClient.SendFileMetadataAsync(validatedTransformedMetadatas);
        }

        private async Task InitializeDirectoryPathAndExtensionsAsync()
        {
            if (!Directory.Exists(directoryPath))
            {
                Directory.CreateDirectory(directoryPath);
            }

            foreach (var extension in supportedExtensions)
            {
                cloudStorageClient.AddSupportedExtension(extension);
            }
        }

        private IEnumerable<FileMetadata> GetFileMetadatas()
        {
            var fileMetadatas = new List<FileMetadata>();
            foreach (var extension in supportedExtensions)
            {
                fileMetadatas.AddRange(GetFileMetadatasByExtension(extension));
            }

            return fileMetadatas;
        }

        private IEnumerable<FileMetadata> GetFileMetadatasByExtension(string extension)
        {
            var files = Directory.EnumerateFiles(directoryPath, $"*{extension}");
            var fileMetadatas = new List<FileMetadata>();

            foreach (var file in files)
            {
                var metadata = GetFileMetadata(file);
                if (metadata != null)
                {
                    fileMetadatas.Add(metadata);
                }
            }

            return fileMetadatas;
        }

        private FileMetadata GetFileMetadata(string filePath)
        {
            try
            {
                using (var stream = new FileStream(filePath, FileMode.Open))
                {
                    return ReadFileMetadata(stream);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading metadata for file {filePath}: {ex}");
                return null;
            }
        }

        private FileMetadata ReadFileMetadata(Stream stream)
        {
            // Implement a method to read file metadata from the stream and transform it into a standardized JSON format
            var json = new JObject();
            json.Add("file_path", stream.Name);
            json.Add("file_size", stream.Length);
            json.Add("file_modified", File.GetLastWriteTime(stream.Name));

            return new TransformedFileMetadata
            {
                FilePath = stream.Name,
                Json = json
            };
        }

