        {
            // Implement a method to validate the transformed metadata for consistency and completeness
            return true;
        }

        public async Task ResetDirectoryAsync()
        {
            directoryPath = DEFAULT_DIRECTORY_PATH;
            cloudStorageClient.Reset();
            await InitializeDirectoryPathAndExtensionsAsync();
        }

        public override string ToString()
        {
