public class UserActivityLogProcessor {
    private static final Logger logger = Logger.getLogger(UserActivityLogProcessor.class);

    public static void processLogs(String logs) {
        List<UserActivity> userActivities = new ArrayList<>();

        try {
            // Parse JSON string to list of UserActivity objects
            JsonObject jsonObject = new JsonParser().parse(logs).getAsJsonObject();
            for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
                String userId = entry.getKey();
                JsonArray activityLogs = entry.getValue().getAsJsonArray();
                for (int i = 0; i < activityLogs.size(); i++) {
                    JsonObject activityLog = activityLogs.get(i).getAsJsonObject();
                    long timestamp = Long.parseLong(activityLog.get("timestamp").getAsString());
                    String eventType = activityLog.get("event_type").getAsString();
                    userActivities.add(new UserActivity(userId, timestamp, eventType));
                }
            }
        } catch (Exception e) {
            logger.error("Error parsing JSON: " + e.getMessage());
            return;
        }

        // Validate and extract fields from user activities
        for (UserActivity activity : userActivities) {
            try {
                validateAndExtractFields(activity);
            } catch (Exception e) {
                logger.error("Error processing user activity: " + e.getMessage());
                continue;
            }
        }

        // Write user activities to NoSQL database for temporary storage
        saveUserActivitiesToDatabase(userActivities);

        // Retry failed records after a configurable delay
        List<UserActivity> failedRecords = getFailedRecords();
        if (!failedRecords.isEmpty()) {
            logger.info("Retrying " + failedRecords.size() + " failed records...");
            retryProcessing(failedRecords);
        }
    }

