    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        perror("Error: Unable to allocate memory for new record");
        return;
    }
    new_record->key = key;
    new_record->label = label;
    hashMapPut(record_map, new_record);
}

// Get a record from the record map
