void delete_record(int key) {
    hashMapRemove(record_map, key);
}

// Update a record in the record map
void update_record(int key, char label) {
    Record *record = (Record *)hashMapGet(record_map, key);
    if (!record) {
        perror("Error: Unable to find record with given key");
        return;
    }
    record->label = label;
