    if (record) {
        result = record->label;
    } else {
        perror("Error: Unable to find record with given key");
    }
    sem_post(semaphore);
    return result;
}

// Implement a thread-safe write operation for the record map
void *write_record(int key, char label, sem_t *semaphore) {
    void *result = NULL;
    sem_wait(semaphore);
    Record *record = get_record(key);
    if (record) {
        update_record(key, label);
        result = record->label;
    } else {
        perror("Error: Unable to find record with given key");
    }
    sem_post(semaphore);
    return result;
}

// Implement a batch processing mode for incremental updates
void *batch_update(int num_records, char **labels, sem_t *semaphore) {
    void *result = NULL;
    sem_wait(semaphore);
    for (int i = 0; i < num_records; i++) {
        update_record(i, labels[i]);
    }
    result = "Batch update complete";
    sem_post(semaphore);
    return result;
}

// Implement a partial retrieval mode for incremental updates
void *partial_retrieval(int start_key, int end_key, char **labels, sem_t *semaphore) {
