    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    double *weights = malloc(num_records * sizeof(double));

    // Allocate memory for the array of records
    struct record *records = malloc(num_records * sizeof(struct record));

    // Initialize the offsets, keys, and weights
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * 10;
        keys[i] = i % 100;
        weights[i] = ((double)rand() / RAND_MAX) * 10.0;
    }

    // Initialize the status flag of each record as inactive
    for (int i = 0; i < num_records; i++) {
        records[i].status = 'I';
    }

    // Allocate memory for and initialize the array of random values for the int value
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }

    // Print the allocated memory details
    printf("Memory Details:\n");
    printf("Offsets: %ld bytes\n", num_records * sizeof(long));
    printf("Keys: %ld bytes\n", num_records * sizeof(int));
    printf("Weights: %ld bytes\n", num_records * sizeof(double));
    printf("Records: %ld bytes\n", num_records * sizeof(struct record));
}

void deallocate_memory() {
    // Deallocate the memory for the arrays of offsets, keys, and weights
    free(offsets);
    free(keys);
    free(weights);

    // Deallocate the memory for the array of records
    free(records);
}

