    // Search for the record with the specified key and return a pointer to it
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            return &records[i];
        }
    }

    // If no matching record is found, return a special indicator
    return NULL;
}

void update_status(int key, char status) {
    // Search for the record with the specified key and update its status flag
    struct record *record = query_record(key);
    if (record != NULL) {
        record->status = status;
    }
}

