using System;
using System.Threading.Tasks;
using MyApp.Services;
using MyApp.Utilities;

namespace MyApp.Controllers
{
    public class HttpPostController : ControllerBase
    {
        private readonly IService _service;
        private readonly ICachingService _cachingService;

        public HttpPostController(IService service, ICachingService cachingService)
        {
            _service = service;
            _cachingService = cachingService;
        }

        [HttpPost]
        public async Task<ActionResult> UpdateElementAsync([FromQuery] int pageSectionId, [FromQuery] int elementId, [FromBody] string htmlContent)
        {
            // validate input parameters
            if (pageSectionId < 0 || elementId < 0 || string.IsNullOrWhiteSpace(htmlContent))
            {
                return BadRequest();
            }

            try
            {
                // update element's HTML content using service class
                await _service.UpdateElementAsync(pageSectionId, elementId, htmlContent);

                // cache updated page section
                await _cachingService.SetCacheAsync(pageSectionId, TimeSpan.FromMinutes(30), async () =>
                {
                    var pageSection = await _service.GetPageSectionAsync(pageSectionId);
                    return JsonSerializer.Serialize(pageSection, new JsonSerializerOptions { WriteIndented = true });
                });

                // refresh page
                return Ok("refresh");
            }
            catch (Exception ex)
            {
                return StatusCode((int)HttpStatusCode.InternalServerError, ex);
            }
        }
    }
}
```
