// Function to validate if the indices array can be compressed by removing any leading zeros and consecutive duplicates
bool compress_indices(unsigned int *indices, int n) {
    // Initialize variables
    bool compression = false;
    int current_index = 0;
    int previous_index = 0;

    // Loop through indices array to check for leading zeros and consecutive duplicates
    for (int i = 0; i < n; i++) {
        if (indices[i] == 0) {
            current_index++;
            compression = true;
        } else {
            if (previous_index + 1 == indices[i]) {
                previous_index = indices[i];
                current_index++;
                compression = true;
            } else {
                previous_index = indices[i];
                current_index = 0;
            }
        }
    }

    // If leading zeros or consecutive duplicates were found, compress the array
    if (compression) {
        int new_size = n - current_index;
        unsigned int *new_indices = (unsigned int *)malloc(new_size * sizeof(unsigned int));
        if (new_indices == NULL) {
            printf("Error: failed to allocate memory for compressed indices\n");
            return false;
        }

        // Copy non-duplicate and non-leading zero values from original array to new array
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (indices[i] != previous_index || current_index == 0) {
                new_indices[j++] = indices[i];
            } else {
                current_index--;
            }
        }

        // Free original array and assign pointer to compressed array
        free(indices);
        *indices = new_indices;
    }

    return true;
}

