#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <pthread.h>

// Memory pool allocator implementation
struct memory_pool {
    void *memory;
    size_t size;
};

struct record {
    int value;
    char label;
    double timestamp;
};

void* allocate_record(struct memory_pool *pool) {
    if (pool->size == 0) {
        return NULL;
    }

    void *memory = pool->memory;
    pool->memory += sizeof(struct record);
    pool->size -= sizeof(struct record);
    return memory;
}

void free_record(struct memory_pool *pool, void *memory) {
    if (memory == NULL) {
        return;
    }

    size_t offset = (char *)memory - (char *)pool->memory;
    pool->size += sizeof(struct record);
    pool->memory += offset;
}

// Function implementation
void generate_records(int count, struct memory_pool *pool) {
    srand((unsigned int)time(NULL));

    for (int i = 0; i < count; i++) {
        struct record *record = allocate_record(pool);
        if (record == NULL) {
            break;
        }

        record->value = rand() % 100;
        record->label = (char)(i % 26 + 'a');
        record->timestamp = get_time();
    }
}

// Thread-safe memory allocation and deallocation
void* allocate_memory(size_t size) {
    void *memory = malloc(size);
    if (memory == NULL) {
        return NULL;
    }

    pthread_mutex_lock(&memory_pool.mutex);
    memory_pool.size += size;
    pthread_mutex_unlock(&memory_pool.mutex);

    return memory;
}

void free_memory(void *memory) {
    if (memory == NULL) {
        return;
    }

    pthread_mutex_lock(&memory_pool.mutex);
    size_t offset = (char *)memory - (char *)memory_pool.memory;
    memory_pool.size -= offset;
    pthread_mutex_unlock(&memory_pool.mutex);

    free(memory);
}

// Logging mechanism
void log(int level, const char *message) {
    // Asynchronous write to console and file outputs
    if (level == LOG_INFO) {
        printf("%s\n", message);
    } else if (level == LOG_WARNING) {
        fprintf(stderr, "%s\n", message);
    } else if (level == LOG_ERROR) {
        fprintf(stderr, "%s\n", message);
    }
}

// Error handling
void handle_error(const char *message) {
    // Detailed error codes and messages for debugging and monitoring purposes
    printf("%s: %d (%s)\n", message, errno, strerror(errno));
}
