// Structure to hold record information
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Array of records
Record* records = NULL;

// Number of records in the array
size_t num_records = 0;

// Increment factor for calculating offsets
int increment_factor = 1;

// Random value range
int random_value_range = 10;

// Total memory usage in bytes allocated for all records
size_t total_memory_usage = 0;

// Function to allocate and initialize memory for a new record
void addRecord(int key, int value) {
    // Calculate offset using increment factor and key
    long offset = (long)(key * increment_factor);

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        printf("Failed to allocate memory for new record\n");
        return;
    }

    // Initialize the new record
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;

    // Add the new record to the array of records
    records[num_records] = new_record;
    num_records++;

    // Update total memory usage
    total_memory_usage += sizeof(Record);
}

// Function to deallocate all allocated memory
void clearRecords() {
    for (size_t i = 0; i < num_records; i++) {
        free(records[i]);
    }
    records = NULL;
    num_records = 0;
    total_memory_usage = 0;
}

