using System;
using UnityEngine;

public class DynamicRangeDataHandler {
    private int minValue;
    private int maxValue;
    private float[] cache = new float[1024]; // Initialize the cache with 1024 elements

    public DynamicRangeDataHandler(int min, int max) {
        if (min > max) {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");
        }
        this.minValue = min;
        this.maxValue = max;
    }

    public float GenerateRandomFloat() {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt() {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    private bool ValidateRange(int min, int max) {
        if (min > max) {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");
        }
        return true;
    }

    public void SetRange(int min, int max) {
        ValidateRange(min, max);
        this.minValue = min;
        this.maxValue = max;
    }

    private float GetCachedValue(int index) {
        if (index < 0 || index >= cache.Length) {
            throw new ArgumentOutOfRangeException("Cache index out of range");
        }
        return cache[index];
    }

    public float GetRandomFloatFromCache() {
        int index = UnityEngine.Random.Range(0, cache.Length);
        return GetCachedValue(index);
    }

    private void SetCacheValue(int index, float value) {
        if (index < 0 || index >= cache.Length) {
            throw new ArgumentOutOfRangeException("Cache index out of range");
        }
        cache[index] = value;
    }

    public void SetRandomFloatToCache() {
        int index = UnityEngine.Random.Range(0, cache.Length);
        float value = GenerateRandomFloat();
        SetCacheValue(index, value);
    }

    private bool ValidateInput(object input) {
        if (input is not int && input is not float) {
            throw new ArgumentException("Invalid input type");
        }
        return true;
    }

    public void ResetRangeToDefault() {
        this.minValue = 0;
        this.maxValue = 1024;
    }

    public override string ToString() {
        return $"Minimum value: {this.minValue}, Maximum value: {this.maxValue}";
    }
}
