    time_t last_accessed;
    bool accessed;
};

// Callback function to reset the access flag on a record's metadata
void reset_access_flag(struct metadata* meta) {
    meta->accessed = false;
}

// Callback function for post-initialization processing
void process_metadata(struct record* rec, struct metadata* meta) {
    // Application-specific logic on each record's metadata
