int generate_records(size_t num_records, long offset_range, int key_range, void* memory_manager) {
    // Initialize variables for tracking failed attempts and peak memory consumption
    int failed_attempts = 0;
    size_t peak_memory = 0;

    // Allocate memory for the records using the custom memory manager
    struct record* recs = (struct record*)custom_memory_manager(num_records * sizeof(struct record));
    if (!recs) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    // Initialize the records with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        recs[i].offset = rand() % offset_range + 1;
        recs[i].key = rand() % key_range + 1;

        // Allocate memory for the metadata structure and initialize it with default values
        struct metadata* meta = (struct metadata*)custom_memory_manager(sizeof(struct metadata));
        if (!meta) {
            printf("Error: Memory allocation failed\n");
            return -1;
        }
        recs[i].meta = meta;
        meta->created_at = time(NULL);
        meta->last_accessed = 0;
        meta->accessed = false;
    }

    // Track the total number of failed attempts and peak memory consumption
    for (int i = 0; i < num_records; i++) {
        if (!recs[i].meta) {
            failed_attempts++;
            continue;
        }
        size_t cur_memory = sizeof(struct record) + sizeof(struct metadata);
        peak_memory = (cur_memory > peak_memory) ? cur_memory : peak_memory;
    }

    // Reset the access flag on each record's metadata using a custom callback function
    for (int i = 0; i < num_records; i++) {
        if (!recs[i].meta) continue;
        reset_access_flag(recs[i].meta);
    }

    // Provide an option to reset the access flag on each record's metadata using a custom callback function
    for (int i = 0; i < num_records; i++) {
        if (!recs[i].meta) continue;
        process_metadata(recs + i, recs[i].meta);
    }

    // Return the total number of failed attempts and peak memory consumption as part of the result
    printf("Total failed attempts: %d\n", failed_attempts);
    printf("Peak memory consumption: %zu bytes\n", peak_memory);
    return 0;
}
