    total_memory_usage += num_weights * sizeof(double);

    // Allocate memory for the record array
    records = malloc(num_records * sizeof(struct Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records.\n");
        return;
    }
    total_memory_usage += num_records * sizeof(struct Record);
}

// Define a function to initialize the arrays and populate them with random data
void initialize_arrays(int num_keys, int num_weights) {
    // Initialize the offset array
    long *offsets = (long *)malloc(num_keys * sizeof(long));
    for (int i = 0; i < num_keys; i++) {
        offsets[i] = (rand() % 100 + 1) * 100;
    }

    // Initialize the key array
    int *keys = (int *)malloc(num_keys * sizeof(int));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // Initialize the weight array
    double *weights = (double *)malloc(num_weights * sizeof(double));
    for (int i = 0; i < num_weights; i++) {
        weights[i] = rand() % 100 + 1.0 / 100;
    }

    // Initialize the record array
    struct Record *records = (struct Record *)malloc(num_records * sizeof(struct Record));
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[rand() % num_keys];
        records[i].weight = weights[rand() % num_weights];
    }
}

// Define a function to track the total memory usage in bytes allocated for all records and ensure that the function can handle up to 10 million records efficiently without causing a segmentation fault or excessive resource consumption.
void track_memory_usage(int num_records) {
    // Calculate the total memory usage in bytes
    long total_memory = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(double) * num_records;

    // Check if the total memory usage exceeds a predefined limit and trigger compaction if necessary
    if (total_memory > 10000000) {
        printf("Total memory usage exceeded limit, triggering compaction...\n");
        compact();
    }
}

// Define a function to sort the records based on their offset values in descending order.
void sort_records(int num_records) {
    // Create an array of pointers to the records
    struct Record **records = (struct Record **)malloc(num_records * sizeof(struct Record *));

    // Initialize the array with pointers to the records
    for (int i = 0; i < num_records; i++) {
        records[i] = &records[i];
    }

    // Sort the array using the offset values as keys
    qsort(records, num_records, sizeof(struct Record *), compare_offsets);
}

// Define a function to mark records with offset values below a certain threshold for potential removal.
void mark_records_for_removal(int num_records, int min_offset) {
    // Create an array of pointers to the records
    struct Record **records = (struct Record **)malloc(num_records * sizeof(struct Record *));

    // Initialize the array with pointers to the records
    for (int i = 0; i < num_records; i++) {
        records[i] = &records[i];
    }

    // Iterate over the array and mark records with offset values below the minimum threshold for potential removal.
    for (int i = 0; i < num_records; i++) {
        if (records[i]->offset < min_offset) {
            records[i] = NULL;
        }
    }
}

// Define a function to remove marked records from the array while minimizing fragmentation and maintaining contiguous memory blocks.
void compact() {
    // Create an array of pointers to the records
    struct Record **records = (struct Record **)malloc(num_records * sizeof(struct Record *));

    // Initialize the array with pointers to the records
    for (int i = 0; i < num_records; i++) {
        records[i] = &records[i];
    }

    // Iterate over the array and remove marked records.
    int j = 0;
    for (int i = 0; i < num_records; i++) {
        if (records[i] != NULL) {
            records[j++] = records[i];
        }
    }

    // Update the number of records and total memory usage.
    num_records = j;
    total_memory_usage -= sizeof(long) * (num_records - j);
}

// Define a function to periodically log the total memory usage and the number of records retained, ensuring that this logging does not significantly impact performance.
void log_memory_usage() {
    // Calculate the current time in seconds
    double t = (double)time(NULL);

    // Log the total memory usage and number of records
    printf("At %f: Total memory usage is %ld bytes, with %d records retained.\n", t, total_memory_usage, num_records);
}

// Define a function to deallocate all allocated memory when done, ensuring no memory leaks occur.
void deallocate_memory() {
    // Free the record array
    free(records);
    records = NULL;

    // Free the offset array
    free(offsets);
    offsets = NULL;

    // Free the key array
    free(keys);
    keys = NULL;

    // Free the weight array
    free(weights);
