#define LOG_FILE "/var/log/dns-resolver.log"
#define LOG_LEVEL 3
#define TIMEOUT 10 // seconds
#define LATENCY 5 // ms
#define PACKET_LOSS 20 // %

// Custom logging function
void log(int level, const char *format, ...) {
    va_list args;
    struct tm *tm;
    time_t now;
    FILE *fp = NULL;

    if (level > LOG_LEVEL) {
        return;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        exit(1);
    }

    now = time(NULL);
    tm = localtime(&now);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d [%d] ", 
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, 
            tm->tm_hour, tm->tm_min, tm->tm_sec, level);
    va_start(args, format);
    vfprintf(fp, format, args);
    fclose(fp);
}

// DNS resolution function
int dns_resolve(const char *hostname, u_char **ipaddr) {
    struct addrinfo hints, *res;
    int error;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;

    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error) {
        log(3, "getaddrinfo() failed: %s\n", gai_strerror(error));
        return -1;
    }

    *ipaddr = res->ai_addr->sa_data[0];

    freeaddrinfo(res);
    return 0;
}

// Establish a connection to the remote address
int establish_connection(u_char *ipaddr, int port) {
    struct sockaddr_in server_addr;
    int sockfd;
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket()");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    server_addr.sin_addr.s_addr = ipaddr[0];

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect()");
        return -1;
    }

    return sockfd;
}

// Read a line from the file and parse the numeric fields
int read_line(FILE *file, char **line, int *last2avg) {
    int c;
    int i = 0;
    int count = 0;
    int length = 100; // initial buffer size

    if (!file || !line || !last2avg) {
        return -1;
    }

    *line = malloc(length);
    if (!*line) {
        perror("malloc()");
        return -1;
    }

    while ((c = fgetc(file)) != EOF && c != '\n') {
        if (i >= length) {
            char *temp;
            int new_length = length * 2;

            temp = realloc(*line, new_length);
            if (!temp) {
                perror("realloc()");
                return -1;
            }

            length = new_length;
            *line = temp;
        }

        (*line)[i++] = c;
    }

    (*line)[i] = '\0';

    // Parse last two numeric fields and compute average
    char *token = strtok(*line, ",");
    while (count < 2 && token != NULL) {
        int value = atoi(token);
        if (value > 0) {
            count++;
            *last2avg += value;
        }
        token = strtok(NULL, ",");
    }

    return i;
}

// Free memory allocated for the line
void free_line(char **line) {
    if (*line) {
        free(*line);
    }
}

// Compute average of last two numeric fields and print results in comma-separated format
void compute_average(int *last2avg, char **line) {
    int avg = 0;
    if (*last2avg > 0) {
        avg = *last2avg / 2;
    }

    sprintf(*line, "%d", avg);
}

int main(int argc, char **argv) {
    int sockfd;
    u_char ipaddr[4];
    int port = atoi(argv[1]);
    int last2avg = 0;
    char *line = NULL;
    FILE *file = fopen("/path/to/large/text/file", "r");

    if (!file) {
        perror("fopen()");
        return -1;
    }

    // Limit process capabilities and implement timeout mechanism for DNS queries
    cap_t caps = cap_get_proc();
    cap_clear(caps);
    cap_set_flag(caps, CAP_NET_RAW, CAP_CLEAR);
    cap_set_flag(caps, CAP_SETUID, CAP_CLEAR);
    cap_set_flag(caps, CAP_SETGID, CAP_CLEAR);
    if (cap_set_proc(caps) < 0) {
        perror("cap_set_proc()");
        return -1;
    }
    cap_free(caps);

    while ((sockfd = establish_connection(ipaddr, port)) == -1) {
        sleep(TIMEOUT); // sleep for TIMEOUT seconds before trying again
    }

    // Simulate network latency and packet loss
    srand(time(NULL));
    if (PACKET_LOSS > rand() % 100) {
        log(3, "Packet loss detected. Retrying connection...\n");
        close(sockfd);
        sockfd = establish_connection(ipaddr, port);
        if (sockfd == -1) {
            perror("establish_connection()");
            return -1;
        }
    }

    // Read line by line from the file and parse numeric fields
    while ((read_line(file, &line, &last2avg)) != -1) {
        log(3, "Reading line %d\n", last2avg);
        compute_average(&last2avg, &line);
        log(3, "Computed average: %s\n", line);
    }

    // Free memory allocated for the line
    free_line(&line);

    // Close socket and exit program
    close(sockfd);
    return 0;
}
