#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

// Record structure to store name and value
struct record {
    string name;
    double value;
};

// Thread-safe buffer for storing records
class record_buffer {
public:
    // Constructor
    record_buffer() : size_(0), capacity_(1000000) {}

    // Add a new record to the buffer
    void add_record(const string& name, double value) {
        unique_lock<mutex> lock(mutex_);
        while (size_ >= capacity_) {
            cv_.wait(lock);
        }
        records_.push_back({name, value});
        size_++;
        cv_.notify_all();
    }

    // Get the largest record in the buffer
    record get_largest_record() {
        unique_lock<mutex> lock(mutex_);
        if (size_ == 0) return {};
        int max_index = distance(records_.begin(), max_element(records_.begin(), records_.end(),
            [](const record& r1, const record& r2) { return r1.value < r2.value; }));
        return records_[max_index];
    }

    // Update the maximum length of names and acceptable range of values
    void update_parameters(int max_name_length, double min_value, double max_value) {
        unique_lock<mutex> lock(mutex_);
        max_name_length_ = max_name_length;
        min_value_ = min_value;
        max_value_ = max_value;
    }

private:
    int size_; // Number of records in the buffer
    int capacity_; // Maximum number of records in the buffer
    vector<record> records_; // Vector of record structures
    mutex mutex_; // Mutex for protecting concurrent access to the buffer
    condition_variable cv_; // Condition variable for waiting for space in the buffer
    int max_name_length_; // Maximum length of names allowed in the buffer
    double min_value_; // Minimum value allowed in the buffer
    double max_value_; // Maximum value allowed in the buffer
};

// Main function to manage dynamic records
void manageDynamicRecords(const string& filename) {
    ifstream file(filename);
    record_buffer buffer;
    int line_number = 0;
    while (file.good()) {
        string line;
        getline(file, line);
        line_number++;
        if (!line.empty()) {
            try {
                // Parse the line and validate the record
                vector<string> tokens = split(line, ' ');
                if (tokens.size() != 2) throw invalid_argument("Invalid record format");
                string name = tokens[0];
                double value = stod(tokens[1]);
                if (name.length() > buffer.max_name_length_) throw out_of_range("Name too long");
                if (value < buffer.min_value_ || value > buffer.max_value_) throw out_of_range("Value outside range");
                // Add the record to the buffer
                buffer.add_record(name, value);
            } catch (const exception& e) {
                cerr << "Error parsing line " << line_number << ": " << e.what() << endl;
            }
        }
    }
    // Find and print the largest record in the buffer
    cout << "Largest record: ";
    record largest = buffer.get_largest_record();
    if (largest) {
        cout << "name=" << largest.name << ", value=" << largest.value;
    } else {
        cout << "no records found";
    }
    cout << endl;
}

// Split a string into tokens using a given delimiter
vector<string> split(const string& s, char delim) {
    vector<string> tokens;
    string token;
    istringstream stream(s);
    while (getline(stream, token, delim)) {
        tokens.push_back(token);
    }
    return tokens;
}
