    int* arr = malloc(n * sizeof(int));
    if (!arr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return arr;
}

// Function to generate a random integer within a specified range
int rand_int(int min, int max) {
    // Use the time as a seed for the RNG
    srand(time(NULL));

    // Generate a random number between the given range
    return rand() % (max - min + 1) + min;
}

// Function to initialize an array of records with random values within a specified range
Record* init_records(size_t n, int min_val, int max_val) {
    Record* arr = malloc(n * sizeof(Record));
    if (!arr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; i++) {
        arr[i].val = rand_int(min_val, max_val);
    }
    return arr;
}

// Function to initialize an array of long offsets based on the corresponding keys
long* init_offsets(size_t n) {
    long* arr = alloc_long_array(n);

    // Initialize each offset as the key multiplied by a fixed increment factor
    for (size_t i = 0; i < n; i++) {
        arr[i] = i * 10;
    }
    return arr;
}

// Function to validate that the sum of all long offsets does not exceed a user-defined maximum sum threshold
void validate_offsets(long* offsets, size_t n) {
    // Calculate the sum of all offsets and check if it exceeds the maximum sum threshold
    long sum = 0;
    for (size_t i = 0; i < n; i++) {
        sum += offsets[i];
    }
    if (sum > MAX_SUM) {
        // Print an error message and exit the program if the validation fails
        fprintf(stderr, "Sum of all long offsets exceeds maximum sum threshold\n");
        exit(EXIT_FAILURE);
    }
}

// Function to compress the keys array by removing any zero values
CompressedData* compress_keys(int* keys, size_t n) {
    // Create a new compressed data structure and initialize its arrays
    CompressedData* cd = malloc(sizeof(CompressedData));
    cd->records = alloc_int_array(n);
    cd->offsets = alloc_long_array(n);
    cd->num_records = 0;

    // Iterate over the keys array and copy non-zero values to the compressed data structure
    for (size_t i = 0; i < n; i++) {
        if (keys[i] != 0) {
            cd->records[cd->num_records++] = keys[i];
            cd->offsets[i] = i * 10;
        }
    }
    return cd;
}

// Function to copy the contents of the offset and keys arrays into the compressed data structure, ensuring data integrity and minimizing memory footprint
void copy_data(long* offsets, int* keys, size_t n) {
    // Iterate over the arrays and copy each value to the corresponding index in the compressed data structure
    for (size_t i = 0; i < n; i++) {
        cd->offsets[i] = offsets[i];
        cd->records[i] = keys[i];
    }
}

// Function to decompress the compressed data structure and verify that the copied data is accurate
