    size_t key_size = n * sizeof(int);
    long total_memory = offset_size + key_size;

    // Check if the total memory exceeds the maximum allowed
    if (total_memory > max_memory_kb * 1024) {
        return -2;
    }

    // Initialize the arrays for offsets and keys
    long *offsets = malloc(offset_size);
    int *keys = malloc(key_size);

    // Check if memory allocation failed
    if (offsets == NULL || keys == NULL) {
        return -3;
    }

    // Generate random values for the offsets and keys
