    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % max_memory_kb * 1024;
        keys[i] = rand() % max_sum;
    }

    // Compress the keys array by removing any zero values
    int compressed_size = n - countZeroValues(keys, n);
    int *compressed_keys = malloc(compressed_size * sizeof(int));

    // Check if memory allocation failed
    if (compressed_keys == NULL) {
        return -4;
    }

    // Copy the non-zero values from the keys array to the compressed array
    int index = 0;
    for (int i = 0; i < n; i++) {
        if (keys[i] != 0) {
            compressed_keys[index++] = keys[i];
        }
    }

    // Create a new structure of type CompressedData to store the compressed data
    typedef struct {
        int *compressed_keys;
        int num_keys;
    } CompressedData;
    CompressedData *compressed_data = malloc(sizeof(CompressedData));

    // Check if memory allocation failed
    if (compressed_data == NULL) {
        return -5;
    }

    // Initialize the compressed data structure
    compressed_data->num_keys = compressed_size;
    compressed_data->compressed_keys = compressed_keys;

    // Copy the contents of the offset and keys arrays into the compressed data structure
    memcpy(compressed_data->compressed_keys, keys, n * sizeof(int));

    // Free any unused memory
    free(offsets);
    free(keys);

    return 0;
}

// Define a function to optimize the data structure
void optimizeDataStructure(CompressedData *compressed_data) {
    // Check for valid input parameters
    if (compressed_data == NULL || compressed_data->num_keys <= 0) {
        return;
    }

    // Calculate the total memory required for the arrays
    size_t offset_size = compressed_data->num_keys * sizeof(long);
    size_t key_size = compressed_data->num_keys * sizeof(int);
    long total_memory = offset_size + key_size;

    // Check if the total memory exceeds the maximum allowed
    if (total_memory > max_memory_kb * 1024) {
        return;
    }

    // Initialize the arrays for offsets and keys
    long *offsets = malloc(offset_size);
    int *keys = malloc(key_size);

    // Check if memory allocation failed
    if (offsets == NULL || keys == NULL) {
        return;
    }

    // Copy the contents of the compressed data structure into the offset and keys arrays
    memcpy(offsets, compressed_data->compressed_keys, compressed_data->num_keys * sizeof(int));
    memcpy(keys, compressed_data->compressed_keys, compressed_data->num_keys * sizeof(int));

    // Free any unused memory
    free(compressed_data->compressed_keys);
    free(compressed_data);

    return;
}

// Define a function to deserialize and load data from a binary file
void deserializeAndLoadData(const char *filename, CompressedData **compressed_data) {
    // Check for valid input parameters
    if (filename == NULL || compressed_data == NULL) {
        return;
    }

    // Open the binary file in read mode
    FILE *file = fopen(filename, "rb");

    // Check if the file could not be opened
    if (file == NULL) {
        return;
    }

    // Allocate memory for the compressed data structure
    CompressedData *data = malloc(sizeof(CompressedData));

    // Check if memory allocation failed
    if (data == NULL) {
        fclose(file);
        return;
    }

    // Deserialize the data from the file
    fread(&data->num_keys, sizeof(int), 1, file);
    data->compressed_keys = malloc(data->num_keys * sizeof(int));

    // Check if memory allocation failed
    if (data->compressed_keys == NULL) {
        free(data);
        fclose(file);
        return;
    }

    // Read the compressed keys from the file
    fread(data->compressed_keys, sizeof(int), data->num_keys, file);

    // Close the file
    fclose(file);

    // Set the output parameter to point to the deserialized data
    *compressed_data = data;

    return;
}

// Define a function to count the number of zero values in an array
int countZeroValues(int *array, int size) {
    int count = 0;

    // Iterate through the array and count the number of zero values
    for (int i = 0; i < size; i++) {
        if (array[i] == 0) {
            count++;
        }
    }

    return count;
}
