  if (num_users >= MAX_USERS) {
    return -1;
  }

  // Create a new user account with the provided ID, name, email, and password
  struct user* created = &users[num_users];
  created->id = num_users + 1;
  strcpy(created->name, user->name);
  strcpy(created->email, user->email);
  strcpy(created->password, user->password);

