  // Check if the user ID is valid
  if (id < 1 || id > MAX_USERS) {
    return -1;
  }

  // Delete the user account with the provided ID
  struct user* deleted = &users[id - 1];
  memset(deleted, 0, sizeof(struct user));

  return 0;
}

