void handle_user_accounts(json_object* request) {
  // Check if the request is a POST request
  if (strcmp(request->type, "POST")) {
    return;
  }

  // Get the user ID from the request
  int id = json_object_get_int(request, "id");

  // Check if the user ID is valid
  if (id < 1 || id > MAX_USERS) {
    return;
  }

  // Get the name, email, and password from the request
  char* name = json_object_get_string(request, "name");
  char* email = json_object_get_string(request, "email");
  char* password = json_object_get_string(request, "password");

  // Update or create the user account with the provided ID, name, email, and password
  if (update_user(id, name, email, password) == -1) {
    return;
  }
}

// Main function to handle incoming temperature readings and user accounts
int main() {
  // Initialize the mutex lock for memory management
  pthread_mutex_init(&mem_lock, NULL);

  // Read input from standard input
  while (1) {
    // Read a line of input from standard input
    char* input = readline(stdin);

    // Check if the input is a temperature reading and its unit string
    struct temp_reading* reading = parse_temp_reading(input);
