#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    double value;
} item;

struct collection {
    item** items;
    int size;
    int capacity;
};

struct persistence_layer {
    FILE* file;
    pthread_mutex_t mutex;
};

struct query_cache {
    char*** keys;
    double**** values;
    int size;
};

void collection_init(struct collection* coll) {
    coll->items = malloc(sizeof(item*) * 10);
    coll->size = 0;
    coll->capacity = 10;
}

void collection_insert(struct collection* coll, char* name, double value) {
    pthread_mutex_lock(&coll->mutex);
    if (coll->size == coll->capacity) {
        // Resize the array of items
        coll->items = realloc(coll->items, sizeof(item*) * (coll->capacity + 10));
        coll->capacity += 10;
    }
    item* new_item = malloc(sizeof(item));
    new_item->name = strdup(name);
    new_item->value = value;
    coll->items[coll->size++] = new_item;
    pthread_mutex_unlock(&coll->mutex);
}

void collection_delete(struct collection* coll, char* name) {
    pthread_mutex_lock(&coll->mutex);
    for (int i = 0; i < coll->size; i++) {
        if (strcmp(coll->items[i]->name, name) == 0) {
            free(coll->items[i]->name);
            free(coll->items[i]);
            coll->items[i] = coll->items[--coll->size];
            break;
        }
    }
    pthread_mutex_unlock(&coll->mutex);
}

double collection_get(struct collection* coll, char* name) {
    pthread_mutex_lock(&coll->mutex);
    for (int i = 0; i < coll->size; i++) {
        if (strcmp(coll->items[i]->name, name) == 0) {
            double value = coll->items[i]->value;
            pthread_mutex_unlock(&coll->mutex);
            return value;
        }
    }
    pthread_mutex_unlock(&coll->mutex);
    return -1;
}

void collection_update(struct collection* coll, char* name, double new_value) {
    pthread_mutex_lock(&coll->mutex);
    for (int i = 0; i < coll->size; i++) {
        if (strcmp(coll->items[i]->name, name) == 0) {
            coll->items[i]->value = new_value;
            pthread_mutex_unlock(&coll->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&coll->mutex);
}

void collection_destroy(struct collection* coll) {
    for (int i = 0; i < coll->size; i++) {
        free(coll->items[i]->name);
        free(coll->items[i]);
    }
    free(coll->items);
}

void persistence_layer_init(struct persistence_layer* layer) {
    layer->file = fopen("collection.dat", "a+");
    if (layer->file == NULL) {
        printf("Error: unable to open file for persistence\n");
        exit(1);
    }
    pthread_mutex_init(&layer->mutex, NULL);
}

void persistence_layer_write(struct persistence_layer* layer, struct collection* coll) {
    fprintf(layer->file, "%d\n", coll->size);
    for (int i = 0; i < coll->size; i++) {
        fprintf(layer->file, "%s %lf\n", coll->items[i]->name, coll->items[i]->value);
    }
}

void persistence_layer_read(struct persistence_layer* layer, struct collection* coll) {
    char buffer[1024];
    fgets(buffer, 1024, layer->file);
    int count = atoi(buffer);
    for (int i = 0; i < count; i++) {
        fgets(buffer, 1024, layer->file);
        char* name = strtok(buffer, " ");
        double value = atof(strtok(NULL, " "));
        collection_insert(coll, name, value);
    }
}

void query_cache_init(struct query_cache* cache) {
    cache->keys = malloc(sizeof(char**) * 10);
    cache->values = malloc(sizeof(double**) * 10);
    cache->size = 0;
}

void query_cache_insert(struct query_cache* cache, char* key, double* value) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->size == cache->capacity) {
        // Resize the arrays of keys and values
        cache->keys = realloc(cache->keys, sizeof(char**) * (cache->capacity + 10));
        cache->values = realloc(cache->values, sizeof(double**) * (cache->capacity + 10));
        cache->capacity += 10;
    }
    cache->keys[cache->size] = strdup(key);
    cache->values[cache->size] = value;
    cache->size++;
    pthread_mutex_unlock(&cache->mutex);
}

double* query_cache_get(struct query_cache* cache, char* key) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->keys[i], key) == 0) {
            double* value = cache->values[i];
            pthread_mutex_unlock(&cache->mutex);
            return value;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

void query_cache_destroy(struct query_cache* cache) {
    for (int i = 0; i < cache->size; i++) {
        free(cache->keys[i]);
        free(cache->values[i]);
    }
    free(cache->keys);
    free(cache->values);
}

void collection_update_max_length(struct collection* coll, int new_max_length) {
    pthread_mutex_lock(&coll->mutex);
    for (int i = 0; i < coll->size; i++) {
        char* old_name = coll->items[i]->name;
        if (strlen(old_name) > new_max_length) {
            // Reallocate the name field to a larger size
            int old_length = strlen(old_name);
            coll->items[i]->name = realloc(coll->items[i]->name, sizeof(char*) * (new_max_length + 1));
            memcpy(coll->items[i]->name, old_name, new_max_length);
            coll->items[i]->name[new_max_length] = '\0';
        }
    }
    pthread_mutex_unlock(&coll->mutex);
}

void collection_update_value_range(struct collection* coll, double new_min_value, double new_max_value) {
    pthread_mutex_lock(&coll->mutex);
    for (int i = 0; i < coll->size; i++) {
        if (coll->items[i]->value < new_min_value || coll->items[i]->value > new_max_value) {
            // Reallocate the value field to a larger size
            int old_length = sizeof(double);
            coll->items[i]->value = realloc(coll->items[i]->value, old_length + 2 * sizeof(double));
            memcpy(coll->items[i]->value + old_length, &new_min_value, sizeof(double));
            memcpy(coll->items[i]->value + 2 * old_length, &new_max_value, sizeof(double));
        }
    }
    pthread_mutex_unlock(&coll->mutex);
}
