    if (!collection->items) {
        fprintf(stderr, "Failed to allocate memory for items\n");
        exit(EXIT_FAILURE);
    }

    return collection;
}

// Define function to insert item into collection
void insert_item(collection_t* collection, char* name, double value) {
    // Check if there is enough space in the items array
    if (collection->size == collection->capacity) {
        // Dynamically resize items array
        int new_capacity = collection->capacity * 2;
        collection->items = (item_t*)realloc(collection->items, new_capacity * sizeof(item_t));
        if (!collection->items) {
            fprintf(stderr, "Failed to resize items array\n");
            exit(EXIT_FAILURE);
        }
        collection->capacity = new_capacity;
    }

    // Insert item into the items array
    collection->items[collection->size].name = strdup(name);
    collection->items[collection->size].value = value;
    ++collection->size;
}

// Define function to delete item from collection
void delete_item(collection_t* collection, char* name) {
    // Find the index of the item to delete
    int i;
    for (i = 0; i < collection->size; ++i) {
        if (strcmp(collection->items[i].name, name) == 0) {
            break;
        }
    }

    // If the item was not found, return
    if (i == collection->size) {
        fprintf(stderr, "Item %s not found in collection\n", name);
        exit(EXIT_FAILURE);
    }

    // Shift remaining items down and update size
    for (int j = i; j < collection->size - 1; ++j) {
        collection->items[j] = collection->items[j + 1];
    }
    --collection->size;
}

// Define function to retrieve item from collection
item_t* get_item(collection_t* collection, char* name) {
    // Find the index of the item to retrieve
    int i;
    for (i = 0; i < collection->size; ++i) {
        if (strcmp(collection->items[i].name, name) == 0) {
            break;
        }
    }

    // If the item was not found, return NULL
    if (i == collection->size) {
        fprintf(stderr, "Item %s not found in collection\n", name);
        return NULL;
    }

    // Return the item at the index
    return &collection->items[i];
}

// Define function to free all allocated memory for collection
void free_collection(collection_t* collection) {
    // Free items array and collection structure
    free(collection->items);
    free(collection);
}
```
