#include <iostream>
#include <cstring>
#include <vector>
#include <algorithm>
#include <mutex>
#include <fstream>
#include <thread>

using namespace std;

struct attack {
    char* name;
    double value;
};

class DynamicAttackCollection {
private:
    vector<attack> attacks;
    mutex mutex_;
    ofstream file_;
    int max_name_length_ = 0;
    double min_value_ = DBL_MAX, max_value_ = -DBL_MAX;
    bool persist_to_disk_ = false;

public:
    DynamicAttackCollection() {}

    ~DynamicAttackCollection() {
        if (persist_to_disk_) {
            file_.close();
        }
    }

    void initialize(int size) {
        mutex_.lock();
        attacks.reserve(size);
        for (int i = 0; i < size; ++i) {
            attack a;
            a.name = new char[1024];
            strcpy(a.name, "");
            a.value = 0.0;
            attacks.push_back(a);
        }
        mutex_.unlock();
    }

    void add(const char* name, double value) {
        mutex_.lock();
        attack a;
        a.name = new char[strlen(name) + 1];
        strcpy(a.name, name);
        a.value = value;
        attacks.push_back(a);
        if (strlen(name) > max_name_length_) {
            max_name_length_ = strlen(name);
        }
        if (value < min_value_) {
            min_value_ = value;
        } else if (value > max_value_) {
            max_value_ = value;
        }
        mutex_.unlock();
    }

    void remove(const char* name) {
        mutex_.lock();
        for (int i = 0; i < attacks.size(); ++i) {
            if (!strcmp(attacks[i].name, name)) {
                delete[] attacks[i].name;
                attacks.erase(attacks.begin() + i);
                break;
            }
        }
        mutex_.unlock();
    }

    attack* get_by_name(const char* name) {
        mutex_.lock();
        for (int i = 0; i < attacks.size(); ++i) {
            if (!strcmp(attacks[i].name, name)) {
                mutex_.unlock();
                return &attacks[i];
            }
        }
        mutex_.unlock();
        return nullptr;
    }

    attack* get_random() {
        mutex_.lock();
        int index = rand() % attacks.size();
        attack* a = &attacks[index];
        mutex_.unlock();
        return a;
    }

    void persist(const char* filename) {
        if (persist_to_disk_) {
            file_.close();
        }
        file_.open(filename, ios::out | ios::binary);
        mutex_.lock();
        for (int i = 0; i < attacks.size(); ++i) {
            attack a = attacks[i];
            file_ << a.name << ":" << a.value << endl;
        }
        mutex_.unlock();
    }

    void load(const char* filename) {
        if (persist_to_disk_) {
            file_.close();
        }
        file_.open(filename, ios::in | ios::binary);
        mutex_.lock();
        while (!file_.eof()) {
            attack a;
            char name[1024];
            double value;
            file_ >> name >> value;
            a.name = new char[strlen(name) + 1];
            strcpy(a.name, name);
            a.value = value;
            attacks.push_back(a);
        }
        mutex_.unlock();
    }

    void set_persist_to_disk(bool persist_to_disk) {
        mutex_.lock();
        persist_to_disk_ = persist_to_disk;
        mutex_.unlock();
    }
};

void manageDynamicAttackCollection() {
    DynamicAttackCollection collection;
    collection.initialize(1000000);
    while (true) {
        char command[128];
        scanf("%s", command);
        if (!strcmp(command, "add")) {
            char name[1024];
            double value;
            scanf("%s %lf", name, &value);
            collection.add(name, value);
        } else if (!strcmp(command, "remove")) {
            char name[1024];
            scanf("%s", name);
            collection.remove(name);
        } else if (!strcmp(command, "get_by_name")) {
            char name[1024];
            scanf("%s", name);
            attack* a = collection.get_by_name(name);
            if (a != nullptr) {
                printf("Name: %s\nValue: %lf\n", a->name, a->value);
            } else {
                printf("Not found\n");
            }
        } else if (!strcmp(command, "get_random")) {
            attack* a = collection.get_random();
            printf("Name: %s\nValue: %lf\n", a->name, a->value);
        } else if (!strcmp(command, "persist")) {
            char filename[1024];
            scanf("%s", filename);
            collection.set_persist_to_disk(true);
            collection.persist(filename);
        } else if (!strcmp(command, "load")) {
            char filename[1024];
            scanf("%s", filename);
            collection.load(filename);
        } else {
            printf("Invalid command\n");
        }
    }
}
```
This code implements the `DynamicAttackCollection` class that manages a collection of `attack` structures. The class provides methods for initializing, adding, removing, and retrieving attacks from the collection. It also provides a mechanism to persist the collection to disk periodically, allowing data persistence in case of system crashes.

The `manageDynamicAttackCollection` function is the main entry point for the code. It creates an instance of the `DynamicAttackCollection` class and enters an infinite loop where it reads commands from standard input and executes them on the collection. The supported commands are:

* `add`: Adds a new attack to the collection. Takes two arguments: the name of the attack and its value.
* `remove`: Removes an attack from the collection based on its name. Takes one argument: the name of the attack to remove.
* `get_by_name`: Retrieves an attack from the collection based on its name. Takes one argument: the name of the attack to retrieve.
* `get_random`: Selects a random attack from the collection and prints its name and value to standard output.
* `persist`: Persists the collection to disk periodically, allowing data persistence in case of system crashes. Takes one argument: the filename to persist to.
* `load`: Loads the collection from a previously saved file on disk. Takes one argument: the filename to load from.

The function also includes a testing framework using the `require` function to load a mock library called `blueslip`. The testing framework executes tests and resets the `blueslip` library after each test run.']

