import java.util.*;
import java.util.concurrent.*;
import java.io.*;

class Transaction {
    private String transactionID;
    private String customerID;
    private long timestamp;
    private String transactionType;
    private double amount;
    private Details details;

    public Transaction(String transactionID, String customerID, long timestamp, String transactionType, double amount) {
        this.transactionID = transactionID;
        this.customerID = customerID;
        this.timestamp = timestamp;
        this.transactionType = transactionType;
        this.amount = amount;
        this.details = new Details();
    }

    public String getTransactionID() { return transactionID; }
    public String getCustomerID() { return customerID; }
    public long getTimestamp() { return timestamp; }
    public String getTransactionType() { return transactionType; }
    public double getAmount() { return amount; }
    public Details getDetails() { return details; }
}

class Details {
    // additional metadata about the transaction
}

class Account {
    private String accountID;
    private double balance;

    public Account(String accountID, double balance) {
        this.accountID = accountID;
        this.balance = balance;
    }

    public String getAccountID() { return accountID; }
    public double getBalance() { return balance; }
}

class AccountCollection {
    private HashMap<String, Account> accounts;
    private int maxAccountIDLength;
    private double minTransactionAmount;
    private double maxTransactionAmount;

    public AccountCollection(int maxAccountIDLength, double minTransactionAmount, double maxTransactionAmount) {
        this.accounts = new HashMap<>();
        this.maxAccountIDLength = maxAccountIDLength;
        this.minTransactionAmount = minTransactionAmount;
        this.maxTransactionAmount = maxTransactionAmount;
    }

    public void addAccount(String accountID, double balance) {
        accounts.put(accountID, new Account(accountID, balance));
    }

    public void removeAccount(String accountID) {
        accounts.remove(accountID);
    }

    public Account getAccount(String accountID) {
        return accounts.get(accountID);
    }

    public int getMaxAccountIDLength() { return maxAccountIDLength; }
    public double getMinTransactionAmount() { return minTransactionAmount; }
    public double getMaxTransactionAmount() { return maxTransactionAmount; }
}

class TransactionProcessor {
    private AccountCollection accounts;
    private int cooldownPeriod; // 5 seconds
    private long lastProcessedTime;
    private long processingTime;
    private ArrayList<String> transactionLog;
    private boolean isCachingEnabled;
    private Cache cache;
    private String cacheName;
    private String cacheSize;

    public TransactionProcessor(int maxAccountIDLength, double minTransactionAmount, double maxTransactionAmount) {
        accounts = new AccountCollection(maxAccountIDLength, minTransactionAmount, maxTransactionAmount);
        cooldownPeriod = 5000; // 5 seconds in milliseconds
        lastProcessedTime = System.currentTimeMillis();
        processingTime = 0;
        transactionLog = new ArrayList<>();
        isCachingEnabled = false;
        cacheName = "account_cache";
        cacheSize = "1024MB";
    }

    public void processTransaction(Transaction transaction) {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastProcessedTime < cooldownPeriod) {
            // ignore transactions within the cooldown period
            return;
        }
        lastProcessedTime = currentTime;

        String transactionID = transaction.getTransactionID();
        String customerID = transaction.getCustomerID();
        long timestamp = transaction.getTimestamp();
        String transactionType = transaction.getTransactionType();
        double amount = transaction.getAmount();

        if (transactionType.equals("DEPOSIT")) {
            Account account = accounts.getAccount(customerID);
            if (account == null) {
                account = new Account(customerID, 0);
                accounts.addAccount(customerID, account);
            }
            account.setBalance(account.getBalance() + amount);
        } else if (transactionType.equals("WITHDRAWAL")) {
            Account account = accounts.getAccount(customerID);
            if (account == null) {
                // ignore withdrawals for non-existent accounts
                return;
            }
            double newBalance = account.getBalance() - amount;
            if (newBalance < 0) {
                // ignore withdrawals that result in negative balances
                return;
            }
            account.setBalance(newBalance);
        } else {
            // ignore unknown transaction types
            return;
        }

        processingTime += System.currentTimeMillis() - currentTime;
    }

    public void enableCaching(String cacheName, String cacheSize) {
        isCachingEnabled = true;
        this.cacheName = cacheName;
        this.cacheSize = cacheSize;
        cache = new Cache(cacheName, cacheSize);
    }

    public void disableCaching() {
        isCachingEnabled = false;
    }

    public void updateCache(Transaction transaction) {
        if (!isCachingEnabled) {
            return;
        }
        String customerID = transaction.getCustomerID();
        double balance = accounts.getAccount(customerID).getBalance();
        cache.put(customerID, balance);
    }

    public void getCache(String customerID) {
        if (!isCachingEnabled) {
            return;
        }
        Double balance = cache.get(customerID);
        if (balance == null) {
            // ignore invalid customer IDs
            return;
        }
        accounts.getAccount(customerID).setBalance(balance);
    }
}

class Cache {
    private HashMap<String, Double> cache;
    private String name;
    private long size;

    public Cache(String name, long size) {
        this.name = name;
        this.size = size;
        cache = new HashMap<>();
    }

    public void put(String key, Double value) {
        cache.put(key, value);
    }

    public Double get(String key) {
        return cache.get(key);
    }
}

class MonitoringSystem {
    private long memoryUsage;
    private int transactionThroughput;
    private long lastUpdateTime;
    private boolean isConnected;
    private String monitoringServiceURL;

    public MonitoringSystem(String monitoringServiceURL) {
        this.monitoringServiceURL = monitoringServiceURL;
        memoryUsage = 0;
        transactionThroughput = 0;
        lastUpdateTime = System.currentTimeMillis();
        isConnected = false;
    }

    public void updateMemoryUsage(long memoryUsage) {
        this.memoryUsage = memoryUsage;
    }

    public long getMemoryUsage() { return memoryUsage; }

    public void updateTransactionThroughput(int transactionThroughput) {
        this.transactionThroughput = transactionThroughput;
    }

    public int getTransactionThroughput() { return transactionThroughput; }

    public boolean isConnected() { return isConnected; }

    public void updateConnectionStatus(boolean isConnected) { this.isConnected = isConnected; }
}

class ConfigurationInterface {
    private HashMap<String, String> parameters;
    private boolean isModified;

    public ConfigurationInterface() {
        parameters = new HashMap<>();
        isModified = false;
    }

    public void addParameter(String name, String value) {
        if (!parameters.containsKey(name)) {
            parameters.put(name, value);
        } else {
            parameters.replace(name, value);
        }
    }

    public void removeParameter(String name) {
        if (parameters.containsKey(name)) {
            parameters.remove(name);
        }
    }

    public String getParameterValue(String name) {
        return parameters.get(name);
    }

    public boolean isModified() { return isModified; }
}

class BackupMechanism {
    private File backupFile;
    private long lastBackupTime;
    private int backupInterval;

    public BackupMechanism(String filePath, int backupInterval) {
        this.backupFile = new File(filePath);
        this.lastBackupTime = System.currentTimeMillis();
        this.backupInterval = backupInterval;
    }

    public void backup(TransactionProcessor transactionProcessor) throws IOException {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastBackupTime > backupInterval) {
            FileOutputStream fos = new FileOutputStream(backupFile);
            ObjectOutputStream oos = new ObjectOutputStream(fos);
            oos.writeObject(transactionProcessor);
            oos.close();
            lastBackupTime = currentTime;
        }
    }
}
