#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define MIN_RANGE 0
#define MAX_RANGE 100

// Structure to represent a record
typedef struct {
    int timestamp;
    bool status;
    int reference;
} Record;

// Global variables
int numRecords = 0;
Record *records = NULL;

// Function to add a new record
void addRecord(int timestamp, bool status, int reference) {
    // Check if the number of records exceeds the maximum allowed
    if (numRecords >= MAX_RECORDS) {
        printf("Maximum number of records exceeded.\n");
        return;
    }

    // Allocate memory for a new record
    Record *newRecord = malloc(sizeof(Record));
    if (!newRecord) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Assign values to the new record
    newRecord->timestamp = timestamp;
    newRecord->status = status;
    newRecord->reference = reference;

    // Add the new record to the list of records
    records[numRecords++] = *newRecord;
}

// Function to retrieve a record by index
void getRecord(int index) {
    if (index < 0 || index >= numRecords) {
        printf("Invalid record index.\n");
        return;
    }

    Record *record = &records[index];
    printf("Timestamp: %d\nStatus: %s\nReference: %d\n", record->timestamp, (record->status ? "true" : "false"), record->reference);
}

// Function to update a record by index
void updateRecord(int index, int timestamp, bool status, int reference) {
    if (index < 0 || index >= numRecords) {
        printf("Invalid record index.\n");
        return;
    }

    Record *record = &records[index];
    record->timestamp = timestamp;
    record->status = status;
    record->reference = reference;
}

// Function to delete a record by index
void deleteRecord(int index) {
    if (index < 0 || index >= numRecords) {
        printf("Invalid record index.\n");
        return;
    }

    // Shift all records after the specified index to fill the gap
    for (int i = index + 1; i < numRecords; i++) {
        records[i - 1] = records[i];
    }

    // Decrease the number of records
    numRecords--;
}

// Function to retrieve total memory usage in bytes
long getMemoryUsage() {
    return sizeof(Record) * numRecords + sizeof(records);
}

int main() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        addRecord(rand() % MIN_RANGE, rand() % MAX_RANGE, rand());
    }

    getRecord(5);
    updateRecord(5, 1000, true, 2000);
    deleteRecord(5);

    printf("Total memory usage: %ld bytes\n", getMemoryUsage());

    return 0;
}']

