using System;
using System.Security.Cryptography;
using System.Text;

namespace Crypto
{
    public class AESDecryption
    {
        private static readonly byte[] _defaultIV = new byte[16]; // 128-bit IV for AES-CBC
        private static readonly HashAlgorithm _hashAlgorithm = SHA256.Create();

        public static void Decrypt(string ciphertext, string key, string iv = null)
        {
            // Validate input parameters
            if (ciphertext == null || key == null) throw new ArgumentNullException("Input parameter is null");

            // Convert the ciphertext and key to byte arrays
            var cipherBytes = Encoding.UTF8.GetBytes(ciphertext);
            var keyBytes = Encoding.UTF8.GetBytes(key);

            // Initialize the AES-CBC algorithm with the provided or generated IV
            using (var aesAlgorithm = new AesCbc(keyBytes, iv ?? GenerateIV()))
            {
                // Decrypt the ciphertext and verify its integrity using the HMAC-SHA256 hash
                var decryptedBytes = aesAlgorithm.Decrypt(cipherBytes);
                if (!VerifyIntegrity(decryptedBytes, _hashAlgorithm.ComputeHash(decryptedBytes)))
                {
                    throw new CryptographicException("Invalid HMAC-SHA256 hash");
                }

                // Output the decrypted data
                Console.WriteLine(Encoding.UTF8.GetString(decryptedBytes));
            }
        }

        private static string GenerateIV()
        {
            // Generate a secure random IV for each decryption operation
            using (var rng = new RNGCryptoServiceProvider())
            {
                var ivBytes = new byte[16];
                rng.GetBytes(ivBytes);
                return Convert.ToBase64String(ivBytes);
            }
        }

        private static bool VerifyIntegrity(byte[] data, byte[] expectedHash)
        {
            // Compute the HMAC-SHA256 hash of the decrypted data and compare it to the expected value
            var actualHash = _hashAlgorithm.ComputeHash(data);
            return StructuralComparisons.StructuralEqualityComparer.Equals(actualHash, expectedHash);
        }
    }
}
