                ""currency"": {""type"": ""string""},
                ""timestamp"": {""type"": ""integer""}
              },
              ""required"": [ ""amount"", ""currency"", ""timestamp"" ]
            }");
            var validationResults = schema.Validate(JsonConvert.SerializeObject(transaction));
