    char status; // Status flag for the record
    struct record* next; // Pointer to next record in linked list
};

// Structures for memory pool management
typedef struct {
    int size; // Number of records in the pool
    int used; // Number of records currently used
    struct record** records; // Array of pointers to records
} mempool_t;

// Function prototypes
void init_mempool(int capacity);
struct record* allocate_record();
void free_record(struct record* record);
void update_status(struct record* record, char status);
char get_status(struct record* record);
void destroy_mempool();

// Global variables for memory pool management
static mempool_t mempool;

// Initializes the memory pool with a given capacity
void init_mempool(int capacity) {
    // Allocate an array of pointers to records
    mempool.records = (struct record**)calloc(capacity, sizeof(struct record*));

    // Initialize the number of records in the pool and used slots
    mempool.size = capacity;
    mempool.used = 0;
}

// Allocates a new record from the memory pool
struct record* allocate_record() {
    struct record* record;

    // Check if there are any available records in the pool
    if (mempool.used < mempool.size) {
        // Get the next available record
        int index = mempool.used++;
        record = mempool.records[index];

        // Initialize the record's fields
        record->timestamp = time(NULL);
        record->status = ' ';
        record->next = NULL;
    } else {
        // If no available records, allocate a new one using malloc
        record = (struct record*)malloc(sizeof(struct record));
        record->next = NULL;
    }

    return record;
}

// Frees a given record back to the memory pool
void free_record(struct record* record) {
    // Check if the record is in the pool
    int index = mempool.used-- - 1;
    if (index >= 0 && index < mempool.size) {
        // Move the last used record to the freed slot
        struct record* temp = mempool.records[mempool.used];
        mempool.records[index] = temp;
        mempool.records[mempool.used] = NULL;
    } else {
        // If not in the pool, free it using free()
        free(record);
    }
}

// Updates the status of a given record
void update_status(struct record* record, char status) {
    record->status = status;
}

// Returns the status of a given record
char get_status(struct record* record) {
    return record->status;
}

// Destroys the memory pool and all allocated records
void destroy_mempool() {
    // Free all allocated records in the pool
    for (int i = 0; i < mempool.size; i++) {
        if (mempool.records[i] != NULL) {
            free(mempool.records[i]);
        }
    }

    // Free the memory pool array
    free(mempool.records);
}
