#include <functional>
#include <cmath>

// Define data structure for sensor data records
struct SensorData {
    float value;
    uint64_t timestamp;
    uint32_t id;
};

// Define vector for storing sensor data records
using SensorVector = std::vector<SensorData>;

// Define map for tracking total memory usage
using MemoryUsageMap = std::map<uint64_t, size_t>;

// Define mutex and condition variable for thread synchronization
std::mutex mtx;
std::condition_variable cv;

// Define atomic flag for signaling when all threads are finished
std::atomic_bool isDone;

// Define function to read byte identifiers from file
void readByteIdentifiersFromFile(const std::string& filename, SensorVector& sensorData) {
    // Open file in binary mode
    std::ifstream fin(filename, std::ios::binary);
    if (!fin.is_open()) {
        throw std::runtime_error("Failed to open input file");
    }

    // Read byte identifiers from file
    uint8_t byteId;
    while (fin.read((char*)&byteId, sizeof(uint8_t))) {
        // Calculate scaling factor based on the byte identifier
        float value = byteId * 0.1f;

        // Generate timestamp and ID for device identification
        uint64_t timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        uint32_t id = sensorData.size() + 1;

        // Add sensor data record to vector
        SensorData record{value, timestamp, id};
        sensorData.push_back(record);
    }

    fin.close();
}

// Define function to allocate memory for sensor data records
void allocateMemoryForSensorDataRecords(const SensorVector& sensorData) {
    // Calculate total number of bytes needed for all records
    size_t totalBytes = 0;
    for (const auto& record : sensorData) {
        totalBytes += sizeof(record);
    }

    // Allocate memory for all records
    void* memory = std::malloc(totalBytes);
    if (!memory) {
        throw std::bad_alloc();
    }

    // Copy data from vector to allocated memory
    size_t offset = 0;
    for (const auto& record : sensorData) {
        memcpy((char*)memory + offset, &record, sizeof(record));
        offset += sizeof(record);
    }

    // Add memory usage entry to map
    MemoryUsageMap::iterator it = memoryUsage.find(std::this_thread::get_id());
    if (it == memoryUsage.end()) {
        memoryUsage[std::this_thread::get_id()] = totalBytes;
    } else {
        it->second += totalBytes;
    }
}

// Define function to deallocate memory for sensor data records
void deallocateMemoryForSensorDataRecords(const SensorVector& sensorData) {
    // Calculate total number of bytes needed for all records
    size_t totalBytes = 0;
    for (const auto& record : sensorData) {
        totalBytes += sizeof(record);
    }

    // Deallocate memory for all records
    void* memory = std::malloc(totalBytes);
    if (!memory) {
        throw std::bad_alloc();
    }

    // Add memory usage entry to map
    MemoryUsageMap::iterator it = memoryUsage.find(std::this_thread::get_id());
    if (it == memoryUsage.end()) {
        memoryUsage[std::this_thread::get_id()] -= totalBytes;
    } else {
        it->second -= totalBytes;
    }
}

// Define function to log errors and performance metrics
void logErrorsAndPerformanceMetrics(const std::string& message, const SensorVector& sensorData) {
    // Write message to log file
    std::ofstream fout("log.txt", std::ios::app);
    if (fout.is_open()) {
        fout << message;
        for (const auto& record : sensorData) {
            fout << " " << record.value << "," << record.timestamp << "," << record.id;
        }
        fout << std::endl;
        fout.close();
    } else {
        throw std::runtime_error("Failed to open log file");
    }
}

// Define function for parallel processing of sensor data records
void processSensorDataRecords(const SensorVector& sensorData, const std::function<void(const SensorData&)>& callback) {
    // Create thread pool with optimal number of threads based on dataset size
    int numThreads = 4; // Replace with actual value
    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        threads.push_back(std::thread([&]() {
            // Loop until all records are processed
            while (!isDone || !sensorDataQueue.empty()) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [&]() { return !sensorDataQueue.empty() || isDone; });

                // Pop record from queue and process it in the callback function
                SensorData record = sensorDataQueue.front();
                sensorDataQueue.pop_front();
                lock.unlock();

                callback(record);
            }
        }));
    }

    // Add all records to the queue for processing
    for (const auto& record : sensorData) {
        std::unique_lock<std::mutex> lock(mtx);
        sensorDataQueue.push_back(record);
        cv.notify_all();
    }

    // Signal that all threads are finished processing data
    isDone = true;
    cv.notify_all();

    // Join all threads to wait for completion
    for (std::thread& thread : threads) {
        thread.join();
    }
}

// Define main function for testing
int main() {
    // Declare variables and constants
    const std::string filename = "input.txt";
    SensorVector sensorData;
    MemoryUsageMap memoryUsage;
    isDone = false;

    try {
        // Read byte identifiers from file and initialize sensor data records
        readByteIdentifiersFromFile(filename, sensorData);

        // Allocate memory for all sensor data records
        allocateMemoryForSensorDataRecords(sensorData);

        // Process sensor data records in parallel using a thread pool
        processSensorDataRecords(sensorData, [&](const SensorData& record) {
            logErrorsAndPerformanceMetrics("Processed record: " + std::to_string(record.value), sensorData);
        });

        // Deallocate memory for all sensor data records
        deallocateMemoryForSensorDataRecords(sensorData);
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    return 0;
}']

