        return;
    }

    // Populate the temperature and timestamp data structures
    for (int i = 0; i < numReadings; i++) {
        SensorRecord record;
        record.temperature = temperatures[i];
        record.timestamp = timestamps[i];
        sensorRecords[i] = record;
