// Define a custom memory pool to manage dynamic memory allocation and deallocation efficiently
typedef struct {
    size_t capacity;
    void* block;
    size_t usage;
} mempool_t;

// Initialize the memory pool with a given capacity and create an empty block
void init_mempool(mempool_t* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->block = malloc(sizeof(data_point) * capacity);
    pool->usage = 0;
}

// Allocate memory for a single data point from the memory pool
void* alloc_mempool(mempool_t* pool) {
    if (pool->usage == pool->capacity) {
        // Memory pool is full, return NULL
        return NULL;
    }
    pool->usage++;
    return pool->block + sizeof(data_point) * (pool->usage - 1);
}

// Free memory for a single data point from the memory pool
void free_mempool(mempool_t* pool, void* ptr) {
    if (ptr == NULL) {
        // Memory pool is empty, do nothing
        return;
    }
    pool->usage--;
}

// Generate a random integer within the specified range [min_val, max_val]
