}

// Adjust the values array to meet the sum constraint without altering their relative order
void adjust_values(double* values, size_t n, double max_sum) {
    // Calculate the current sum of all values
    double current_sum = 0;
    for (int i = 0; i < n; i++) {
        current_sum += values[i];
    }

    // If the current sum exceeds the maximum allowed, adjust the values array accordingly
    if (current_sum > max_sum) {
        double excess = current_sum - max_sum;
        for (int i = 0; i < n; i++) {
            values[i] -= (values[i] / excess) * (1.0 / (n - i));
        }
    }
}

// Optimize the indices array by removing leading zeros and consecutive duplicates while maintaining uniqueness and positivity
void optimize_indices(unsigned int* indices, size_t n) {
    // Remove leading zeros from the indices array
    unsigned int prev = 0;
    for (int i = 0; i < n; i++) {
        if (indices[i] == 0) {
            prev++;
        } else {
            break;
        }
    }

    // Remove consecutive duplicates from the indices array
    unsigned int current = 0;
    for (int i = 0; i < n; i++) {
        if (indices[i] != current) {
            prev++;
            current = indices[i];
        } else {
            indices[prev++] = current;
        }
    }

    // Trim the indices array to remove any unnecessary leading zeros or consecutive duplicates
    n -= (prev - i);
}

