    char* destination_location;
    int dataset_size;
} DATA_PROCESSOR;

// Define the array of data processor structures
DATA_PROCESSOR* data_processors = NULL;
int num_data_processors = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to append a new data processor structure to the array
void append_data_processor(DATA_PROCESSOR* data_processor) {
    pthread_mutex_lock(&mutex);
    // Reallocate memory for the array if necessary
    num_data_processors++;
    DATA_PROCESSOR** new_data_processors = realloc(data_processors, sizeof(DATA_PROCESSOR*) * num_data_processors);
    if (new_data_processors == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    data_processors = new_data_processors;
    // Add the new data processor structure to the array
    data_processors[num_data_processors - 1] = data_processor;
    pthread_mutex_unlock(&mutex);
}

// Function to clear the array of data processor structures safely
void clear_data_processors() {
    pthread_mutex_lock(&mutex);
    // Free the memory allocated for the array
    free(data_processors);
    data_processors = NULL;
    num_data_processors = 0;
    pthread_mutex_unlock(&mutex);
}

// Function to calculate the dataset size based on the source and destination locations
int get_dataset_size(char* source_location, char* destination_location) {
    // Calculate the distance between the source and destination locations using Haversine formula
    double lat1 = atof(source_location);
    double lon1 = atof(destination_location);
    double R = 6371; // Radius of the Earth in km
    double dLat = (lat2 - lat1) * M_PI / 180;
    double dLon = (lon2 - lon1) * M_PI / 180;
    double a = sin(dLat/2) * sin(dLat/2) + cos(lat1 * M_PI / 180) * cos(lat2 * M_PI / 180) * sin(dLon/2) * sin(dLon/2);
    double c = 2 * atan2(sqrt(a), sqrt(1-a));
    double distance = R * c;
    // Calculate the dataset size based on the distance and current data transfer rate
    double dataset_size = distance / 10.0; // 10 kbps as an example
    return (int)dataset_size;
}

// Function to add a new data processor structure with calculated dataset size
void add_data_processor(char* source_location, char* destination_location) {
    DATA_PROCESSOR* data_processor = malloc(sizeof(DATA_PROCESSOR));
    if (data_processor == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    // Set the fields of the data processor structure
    data_processor->process_id = 1;
    data_processor->source_location = source_location;
    data_processor->destination_location = destination_location;
    data_processor->dataset_size = get_dataset_size(source_location, destination_location);
    // Append the new data processor structure to the array
    append_data_processor(data_processor);
}

// Function to remove a data processor structure from the array based on its process ID
void remove_data_processor(int process_id) {
    pthread_mutex_lock(&mutex);
    // Find the index of the data processor structure with the given process ID
    int i;
    for (i = 0; i < num_data_processors; i++) {
        if (data_processors[i]->process_id == process_id) {
            break;
        }
    }
    // If the data processor structure is found, remove it from the array and free its memory
    if (i < num_data_processors) {
        DATA_PROCESSOR* temp = data_processors[i];
        free(temp);
        for (int j = i; j < num_data_processors - 1; j++) {
            data_processors[j] = data_processors[j + 1];
        }
        num_data_processors--;
    } else {
        printf("Data processor with process ID %d not found\n", process_id);
    }
    pthread_mutex_unlock(&mutex);
}

