    // Allocate memory for the array of pointers
    record_t** records = malloc(mem_block_size);
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for %zu records\n", num_records);
        return NULL;
    }

    // Initialize the array of pointers
    for (size_t i = 0; i < num_records + 1; i++) {
