    size_t num_records = sizeof(record_t*) * (num_records + 1);

    // Find the largest key in the array of records
    for (size_t i = 0; i < num_records; i++) {
        if (records[i]->key > largest_key) {
            largest_key = records[i]->key;
        }
    }

    return largest_key;
}

// Define function to query the records based on a range of keys
record_t** query_records(record_t** records, int start_key, int end_key) {
    size_t num_records = sizeof(record_t*) * (num_records + 1);

    // Create an array of pointers to store the matching records
    record_t** matching_records = malloc(sizeof(record_t*) * num_records);
    if (!matching_records) {
        fprintf(stderr, "Error: Failed to allocate memory for %zu matching records\n", num_records);
        return NULL;
    }

    // Initialize the array of pointers
    for (size_t i = 0; i < num_records + 1; i++) {
        matching_records[i] = malloc(sizeof(record_t));
        if (!matching_records[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for record %zu\n", i);
            return NULL;
        }
    }

    // Loop through the records and store the matching ones in the array of pointers
    size_t num_matching_records = 0;
    for (size_t i = 0; i < num_records + 1; i++) {
        if (records[i]->key >= start_key && records[i]->key <= end_key) {
            matching_records[num_matching_records++] = records[i];
        }
    }

    return matching_records;
}

// Define function to persist the records to disk periodically
void persist_records(record_t** records) {
    if (!records) return;

    size_t num_records = sizeof(record_t*) * (num_records + 1);

    // Open the disk file for writing and seek to the end of the file
    FILE* disk_file = fopen(disk_file_path, "a");
    if (!disk_file) {
        fprintf(stderr, "Error: Failed to open disk file %s for writing\n", disk_file_path);
        return;
