    // Write the records to the disk file
    for (size_t i = 0; i < num_records + 1; i++) {
        fprintf(disk_file, "%d %d %.3lf\n", records[i]->key, records[i]->offset, records[i]->measurement);
    }

    // Close the disk file
    fclose(disk_file);
}
