// Define a function to traverse a directory and its subdirectories
void traverse_directory(const char* directory, const size_t min_file_size, const size_t max_file_size) {
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    // Initialize a list to store file entries
    struct file_entry* files = malloc(sizeof(struct file_entry));
    if (files == NULL) {
        fprintf(stderr, "Error allocating memory for file entries\n");
        return;
    }

    // Iterate through the directory and its subdirectories
    while ((dirent* entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            struct stat st;
            if (stat(entry->d_name, &st) == 0) {
                size_t file_size = st.st_size;
                time_t timestamp = st.st_mtime;

                // Check if the file size meets the minimum and maximum thresholds
                if (file_size >= min_file_size && file_size <= max_file_size) {
                    // Allocate memory for a new file entry
                    struct file_entry* new_file = malloc(sizeof(struct file_entry));
                    if (new_file == NULL) {
                        fprintf(stderr, "Error allocating memory for file entry\n");
                        return;
                    }

                    // Initialize the new file entry with the file name and size
                    strncpy(new_file->filename, entry->d_name, strlen(entry->d_name));
                    new_file->file_size = file_size;
                    new_file->timestamp = timestamp;

                    // Add the new file entry to the list of files
                    files = realloc(files, (num_files + 1) * sizeof(struct file_entry));
                    if (files == NULL) {
                        fprintf(stderr, "Error reallocating memory for file entries\n");
                        return;
                    }

                    files[num_files++] = new_file;
                }
            } else {
                perror("Error getting file size");
                return;
            }
        }
    }

    // Close the directory stream
    closedir(dir);
}

// Define a function to calculate and store the total size of all files
void calculate_total_size() {
    size_t total_size = 0;
    for (int i = 0; i < num_files; i++) {
        total_size += files[i].file_size;
    }

    // Store the total size in a global variable
    total_size_var = total_size;
}

// Define a function to track total memory usage
void track_memory_usage() {
    size_t current_memory_usage = get_total_memory_usage();

    // Check if the current memory usage exceeds the maximum allowed
    if (current_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Error: Exceeded maximum memory usage\n");
        return;
    }

    // Store the current memory usage in a global variable
    memory_usage_var = current_memory_usage;
}

// Define a function to filter files based on a minimum and maximum size threshold
void filter_files(const size_t min_file_size, const size_t max_file_size) {
    // Create a new list to store filtered file entries
    struct file_entry* filtered_files = malloc(sizeof(struct file_entry));

    for (int i = 0; i < num_files; i++) {
        size_t file_size = files[i].file_size;

        // Check if the file size meets the minimum and maximum thresholds
        if (file_size >= min_file_size && file_size <= max_file_size) {
            filtered_files = realloc(filtered_files, (num_filtered_files + 1) * sizeof(struct file_entry));
            if (filtered_files == NULL) {
                fprintf(stderr, "Error reallocating memory for filtered files\n");
                return;
            }

            filtered_files[num_filtered_files++] = files[i];
        }
    }

    // Free the original list of file entries
    free(files);

    // Set the new list of file entries as the filtered list
    files = filtered_files;
}

// Define a function to query files based on a range of timestamps
void query_files(const time_t min_timestamp, const time_t max_timestamp) {
    for (int i = 0; i < num_files; i++) {
        if (files[i].timestamp >= min_timestamp && files[i].timestamp <= max_timestamp) {
            // Do something with the file entry
            printf("File %s has timestamp %lu\n", files[i].filename, files[i].timestamp);
        }
    }
}

// Define a function to update dynamic memory management strategies
void update_memory_management() {
    // Check if the total size of all files exceeds the maximum allowed
    if (total_size > MAX_TOTAL_SIZE) {
        fprintf(stderr, "Error: Exceeded maximum total size\n");
        return;
    }

    // Update the memory usage tracking variable
    track_memory_usage();
}

// Define a function to validate inputs and handle invalid data gracefully
void validate_inputs(const char* directory, const size_t min_file_size, const size_t max_file_size) {
    // Check if the directory is valid
    if (directory == NULL || !is_directory(directory)) {
        fprintf(stderr, "Error: Invalid directory\n");
        return;
    }

    // Check if the minimum and maximum file size thresholds are valid
    if (min_file_size < 0 || max_file_size <= min_file_size) {
        fprintf(stderr, "Error: Invalid file size threshold\n");
        return;
    }
}

// Define a function to persist data to disk
void persist_data() {
    // Open the persistence layer for writing
    FILE* out = fopen("data.bin", "wb");

    if (out == NULL) {
        perror("Error opening output file");
        return;
    }

    // Write the number of files to disk
    int num_files = get_num_files();
    fwrite(&num_files, sizeof(int), 1, out);

    // Write each file entry to disk
    for (int i = 0; i < num_files; i++) {
        struct file_entry* file = get_file(i);
        fwrite(file->filename, sizeof(char), strlen(file->filename) + 1, out);
        fwrite(&file->file_size, sizeof(size_t), 1, out);
        fwrite(&file->timestamp, sizeof(time_t), 1, out);
    }

    // Close the output file stream
    fclose(out);
}

// Define a function to load data from disk
void load_data() {
    // Open the persistence layer for reading
    FILE* in = fopen("data.bin", "rb");

    if (in == NULL) {
        perror("Error opening input file");
        return;
    }

    // Read the number of files from disk
    int num_files = get_num_files();

    // Allocate memory for the list of file entries
    struct file_entry* files = malloc(num_files * sizeof(struct file_entry));

    if (files == NULL) {
        fprintf(stderr, "Error allocating memory for file entries\n");
        return;
    }

    // Read each file entry from disk and add it to the list
    for (int i = 0; i < num_files; i++) {
        struct file_entry* new_file = malloc(sizeof(struct file_entry));

        if (new_file == NULL) {
            fprintf(stderr, "Error allocating memory for file entry\n");
            return;
        }

        char filename[256];
        size_t file_size;
        time_t timestamp;

        // Read the file name and size from disk
        fread(filename, sizeof(char), 256, in);
        fread(&file_size, sizeof(size_t), 1, in);
        fread(&timestamp, sizeof(time_t), 1, in);

        // Initialize the new file entry with the read data
        strncpy(new_file->filename, filename, strlen(filename));
        new_file->file_size = file_size;
        new_file->timestamp = timestamp;

        files[i] = new_file;
    }

    // Close the input file stream
    fclose(in);
}
