// Define the data structure to store the records
struct record {
    long offset;
    int key;
    double measurement;
};

// Define a linked list to store the records in memory-efficient manner
struct record_list {
    struct record *head;
    struct record *tail;
};

// Define the function to manage the dynamic database of records
void manage_records(struct record_list *records, int key) {
    // Check if the key is already in the list
    bool found = false;
    for (struct record *record = records->head; record != NULL; record = record->next) {
        if (record->key == key) {
            found = true;
            break;
        }
    }

    // If the key is not in the list, insert a new record
    if (!found) {
        struct record *new_record = malloc(sizeof(struct record));
        new_record->offset = key * INCREMENT_FACTOR;
        new_record->key = key;
        new_record->measurement = 0.0;
        records->tail = new_record;
    }
}

// Define the function to find and print the largest integer in the list
void find_largest(struct record_list *records) {
    // Initialize the largest key to zero
    int largest_key = 0;

    // Find the largest key in the list
    for (struct record *record = records->head; record != NULL; record = record->next) {
        if (record->key > largest_key) {
            largest_key = record->key;
        }
    }

    // Print the largest key
    printf("Largest integer: %d\n", largest_key);
}

// Define the function to handle external clients querying the records based on a range of keys
void handle_query(struct record_list *records, int lower_bound, int upper_bound) {
    // Initialize the result list to store the queried records
    struct record_list queried_records = {NULL, NULL};

    // Iterate over the records in the range of keys and insert them into the result list
    for (struct record *record = records->head; record != NULL; record = record->next) {
        if (record->key >= lower_bound && record->key <= upper_bound) {
            struct record *new_record = malloc(sizeof(struct record));
            new_record->offset = record->offset;
            new_record->key = record->key;
            new_record->measurement = record->measurement;
            queried_records.tail = new_record;
        }
    }

    // Print the queried records
    printf("Queried records:\n");
    for (struct record *record = queried_records.head; record != NULL; record = record->next) {
        printf("%d: offset=%ld, key=%d, measurement=%.2f\n", record->offset, record->key, record->measurement);
    }
}

// Define the function to persist the records to disk periodically
void persist_records(struct record_list *records) {
    // Open a file for writing and write the records to it
    FILE *file = fopen("records.bin", "wb");
    if (file == NULL) {
        printf("Error: unable to open file for writing\n");
        return;
    }
    for (struct record *record = records->head; record != NULL; record = record->next) {
        fwrite(&record, sizeof(struct record), 1, file);
    }
    fclose(file);
}

// Define the function to handle concurrent access by multiple clients
void handle_concurrent_access(struct record_list *records) {
    // Use a mutex to protect the records list from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Modify the records in the list
    for (struct record *record = records->head; record != NULL; record = record->next) {
        record->measurement += 0.1;
    }

    pthread_mutex_unlock(&mutex);
}

// Define the function to handle updates in configuration parameters
void update_config(struct record_list *records, int key, double measurement) {
    // Use an atomic update to modify the records list without reallocating memory
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (struct record *record = records->head; record != NULL; record = record->next) {
        if (record->key == key) {
            record->measurement = measurement;
        }
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    // Define the list to store the records
    struct record_list records = {NULL, NULL};

    // Initialize the list with some sample records
    for (int i = 0; i < 10; i++) {
        struct record *new_record = malloc(sizeof(struct record));
        new_record->offset = i * INCREMENT_FACTOR;
        new_record->key = i;
        new_record->measurement = 0.0;
        records.tail = new_record;
    }

    // Handle external clients querying the records based on a range of keys
    handle_query(&records, 5, 10);

    // Persist the records to disk periodically
    persist_records(&records);

    // Handle concurrent access by multiple clients
    pthread_t thread;
    pthread_create(&thread, NULL, handle_concurrent_access, &records);

    // Update configuration parameters in the list without reallocating memory
    update_config(&records, 2, 1.5);

    return 0;
}
