struct Attack {
    std::string name;
    double value;
};

class CombatStrategyManager {
public:
    // Constructor initializes the attack collection and sets the maximum memory usage
    CombatStrategyManager(size_t maxMemoryUsage) : maxMemoryUsage_(maxMemoryUsage), attacks_{} {}

    // Destructor deallocates all allocated memory for the attack collection
    ~CombatStrategyManager() {
        for (auto& attack : attacks_) {
            delete attack;
        }
        attacks_.clear();
    }

    // Adds a new attack to the collection, returns true if successful and false otherwise
    bool addAttack(const std::string& name, double value) {
        if (memoryUsage() + sizeof(Attack) > maxMemoryUsage_) {
            return false;
        }
        attacks_.push_back(new Attack{name, value});
        return true;
    }

    // Removes an attack from the collection by name, returns true if successful and false otherwise
    bool removeAttack(const std::string& name) {
        auto it = std::find_if(attacks_.begin(), attacks_.end(), [&](auto* attack) { return attack->name == name; });
        if (it != attacks_.end()) {
            delete *it;
            attacks_.erase(it);
            return true;
        }
        return false;
    }

    // Finds and returns the attack with the longest name in the collection, or nullptr if none found
    Attack* getLongestAttack() {
        auto it = std::max_element(attacks_.begin(), attacks_.end(), [](auto& lhs, auto& rhs) { return lhs->name.length() < rhs->name.length(); });
        if (it != attacks_.end()) {
            return *it;
        }
        return nullptr;
    }

    // Finds and returns all attacks whose names contain the specified substring, or an empty vector if none found
    std::vector<Attack*> getAttacksBySubstring(const std::string& substring) {
        std::vector<Attack*> attacks;
        for (auto& attack : attacks_) {
            if (attack->name.find(substring) != std::string::npos) {
                attacks.push_back(attack);
            }
        }
        return attacks;
    }

    // Returns the total memory usage in bytes for all attacks in the collection
    size_t memoryUsage() const {
        return attacks_.size() * sizeof(Attack);
    }

    // Deallocates all allocated memory for the attack collection and resets the maximum memory usage
    void clear() {
        for (auto& attack : attacks_) {
            delete attack;
        }
        attacks_.clear();
        maxMemoryUsage_ = 0;
    }

private:
    // The maximum amount of memory that can be used by the attack collection in bytes
    size_t maxMemoryUsage_;

    // A vector of dynamically allocated Attack objects, with each object representing an attack
    std::vector<Attack*> attacks_;
};
