// Define the structure for temperature records
typedef struct {
    double temperature;
    char* unit;
} TempRecord;

// Function to dynamically allocate memory for an array of TempRecord structures
TempRecord** allocateMemory(size_t numRecords) {
    // Calculate the size of the memory block required for the array
    size_t memSize = sizeof(TempRecord*) * (numRecords + 1);

    // Allocate the memory block and initialize the first element to NULL
    TempRecord** records = malloc(memSize);
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    records[0] = NULL;

    // Initialize the total memory usage counter
    size_t memUsage = 0;

    // Loop through each record and allocate memory for its TempRecord structure
    for (size_t i = 1; i <= numRecords; i++) {
        records[i] = malloc(sizeof(TempRecord));
        if (!records[i]) {
            printf("Memory allocation failed\n");
            break;
        }

        // Initialize the temperature and unit pointers to NULL
        records[i]->temperature = 0.0;
        records[i]->unit = NULL;

        memUsage += sizeof(TempRecord);
    }

    // Return the allocated memory block and total memory usage counter
    return records;
}

// Function to deallocate memory for an array of TempRecord structures
void deallocateMemory(TempRecord** records) {
    if (!records || !records[0]) {
        printf("Invalid input\n");
        return;
    }

    // Loop through each record and free its memory
    for (size_t i = 1; i <= records[0]->numRecords; i++) {
        free(records[i]);
    }

    // Free the memory block allocated for the array of pointers
    free(records);
}

// Function to read temperature readings and their units from standard input
int readInput(TempRecord** records, size_t* numRecords) {
    if (!records || !numRecords) {
        printf("Invalid input\n");
        return -1;
    }

    // Initialize the number of records to 0
    *numRecords = 0;

    // Read temperature readings and their units from standard input
    while (1) {
        // Allocate memory for a new TempRecord structure
        TempRecord* record = malloc(sizeof(TempRecord));
        if (!record) {
            printf("Memory allocation failed\n");
            break;
        }

        // Read the temperature value and unit from standard input
        double temperature;
        char unit[10];
        scanf("%lf %s", &temperature, unit);

        // Check for mismatched temperature and unit pairs
        if (strlen(unit) > 5) {
            printf("Invalid unit\n");
            break;
        }

        // Initialize the temperature and unit pointers
        record->temperature = temperature;
        record->unit = malloc(sizeof(char) * (strlen(unit) + 1));
        if (!record->unit) {
            printf("Memory allocation failed\n");
            break;
        }

        // Copy the unit string to the TempRecord structure
        strcpy(record->unit, unit);

        // Increment the number of records and reallocate memory for the array of pointers if necessary
        (*numRecords)++;
        if (*numRecords % 10 == 0) {
            size_t memSize = sizeof(TempRecord*) * ((*numRecords) + 1);
            TempRecord** newRecords = realloc(records, memSize);
            if (!newRecords) {
                printf("Memory allocation failed\n");
                break;
            }
            records = newRecords;
        }

        // Store the new record in the array of pointers
        records[*numRecords] = record;
    }

    return 0;
}

// Function to calculate and print the average temperature across all recorded measurements
void calculateAverage(TempRecord** records, size_t numRecords) {
    if (!records || !numRecords) {
        printf("Invalid input\n");
        return;
    }

    // Initialize the sum of temperatures and the number of records to 0
    double sum = 0.0;
    size_t count = 0;

    // Loop through each record and calculate the average temperature
    for (size_t i = 1; i <= numRecords; i++) {
        sum += records[i]->temperature;
        count++;
    }

    // Print the average temperature
    printf("Average temperature: %.2f %s\n", sum / count, records[0]->unit);
}

