// Define the hash function to map timestamps to nodes
unsigned long hash_function(int timestamp) {
    // Implement a simple hash function that returns the timestamp modulo the size of the table
    return timestamp % HASH_TABLE_SIZE;
}

// Define the data structure for the hash table
struct hash_table {
    struct node* nodes;
    int size;
};

// Define the data structure for the record
struct record {
    int total_memory_usage;
    int random_values[RANDOM_VALUE_COUNT];
};

// Define the constants for the hash table and the record
#define HASH_TABLE_SIZE 10000000
#define RANDOM_VALUE_COUNT 10

// Define the function to allocate memory for a node
struct node* alloc_node(char* id, int timestamp) {
    struct node* new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Error: failed to allocate memory for a new node\n");
        exit(1);
    }
    new_node->id = id;
    new_node->timestamp = timestamp;
    new_node->next = NULL;
    return new_node;
}

// Define the function to allocate memory for a record
struct record* alloc_record(int total_memory_usage) {
    struct record* new_record = malloc(sizeof(struct record));
    if (new_record == NULL) {
        printf("Error: failed to allocate memory for a new record\n");
        exit(1);
    }
    new_record->total_memory_usage = total_memory_usage;
    for (int i = 0; i < RANDOM_VALUE_COUNT; i++) {
        new_record->random_values[i] = rand() % MAX_RANDOM_VALUE;
    }
    return new_record;
}

// Define the function to deallocate memory for a node
void dealloc_node(struct node* node) {
    free(node);
}

// Define the function to deallocate memory for a record
void dealloc_record(struct record* record) {
    free(record);
}

// Define the function to insert a new node into the hash table
void insert_node(struct hash_table* table, struct node* node) {
    // Calculate the index of the node in the hash table based on its timestamp
    int index = hash_function(node->timestamp);

    // If there is already a node at the index, link it to the new node
    if (table->nodes[index] != NULL) {
        table->nodes[index]->next = node;
    } else {
        table->nodes[index] = node;
    }
}

// Define the function to update a record in the hash table
void update_record(struct hash_table* table, struct node* node) {
    // Calculate the index of the node in the hash table based on its timestamp
    int index = hash_function(node->timestamp);

    // If there is no node at the index, create a new record and insert it into the hash table
    if (table->nodes[index] == NULL) {
        struct record* new_record = alloc_record(0);
        table->nodes[index] = new_record;
    }

    // Update the record with the total memory usage and random values from the node
    table->nodes[index]->total_memory_usage += node->total_memory_usage;
    for (int i = 0; i < RANDOM_VALUE_COUNT; i++) {
        table->nodes[index]->random_values[i] += node->random_values[i];
    }
}

// Define the function to delete a record from the hash table
void delete_record(struct hash_table* table, struct node* node) {
    // Calculate the index of the node in the hash table based on its timestamp
    int index = hash_function(node->timestamp);

    // If there is no node at the index, do nothing
    if (table->nodes[index] == NULL) {
        return;
    }

    // If the node to be deleted is the first node in the linked list, update the hash table and delete the record
    if (node == table->nodes[index]) {
        table->nodes[index] = node->next;
        dealloc_record(node);
    } else {
        // Find the previous node in the linked list that points to the node to be deleted
        struct node* prev_node = table->nodes[index];
        while (prev_node->next != node) {
            prev_node = prev_node->next;
        }

        // Update the hash table and delete the record
        prev_node->next = node->next;
        dealloc_record(node);
    }
}

// Define the function to serialize the entire data structure to a file
void serialize(struct hash_table* table, FILE* file) {
    // Write the size of the hash table to the file
    fwrite(&table->size, sizeof(int), 1, file);

    // Iterate over all nodes in the hash table and write them to the file
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        struct node* node = table->nodes[i];
        while (node != NULL) {
            fwrite(&node->id, sizeof(char), strlen(node->id) + 1, file);
            fwrite(&node->timestamp, sizeof(int), 1, file);
            fwrite(&node->total_memory_usage, sizeof(int), 1, file);
            for (int j = 0; j < RANDOM_VALUE_COUNT; j++) {
                fwrite(&node->random_values[j], sizeof(int), 1, file);
            }

            node = node->next;
        }
    }
}

// Define the function to deserialize the entire data structure from a file
void deserialize(struct hash_table* table, FILE* file) {
    // Read the size of the hash table from the file
    fread(&table->size, sizeof(int), 1, file);

    // Iterate over all nodes in the hash table and read them from the file
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        struct node* node = malloc(sizeof(struct node));
        if (node == NULL) {
            printf("Error: failed to allocate memory for a new node\n");
            exit(1);
        }

        // Read the id, timestamp, total memory usage, and random values from the file
        fread(&node->id, sizeof(char), strlen(node->id) + 1, file);
        fread(&node->timestamp, sizeof(int), 1, file);
        fread(&node->total_memory_usage, sizeof(int), 1, file);
        for (int j = 0; j < RANDOM_VALUE_COUNT; j++) {
            fread(&node->random_values[j], sizeof(int), 1, file);
        }

        // Insert the node into the hash table
        insert_node(table, node);
    }
}

// Define the function to deallocate memory for all records in the hash table
void dealloc_records(struct hash_table* table) {
    // Iterate over all nodes in the hash table and delete each record
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        struct node* node = table->nodes[i];
        while (node != NULL) {
            dealloc_record(node);

            node = node->next;
        }
    }
}
