        this.configuration = configuration;
    }

    public void processTransaction(Transaction transaction) {
        synchronized (transactionLock) {
            // Initialize the transaction with random values
            transaction.setId(random.nextLong());
            transaction.setCustomerId(random.nextInt(10));
            transaction.setTimestamp(new Date().getTime());
            transaction.setTransactionType(random.nextInt(3));
            transaction.setAmount(random.nextInt(1000) + 1);

            // Add the transaction to the map
            transactions.put(transaction.getId(), transaction);
        }

        synchronized (accountLock) {
            // Retrieve the account associated with the transaction
            Account account = accounts.get(transaction.getCustomerId());

            // Update the account balance based on the transaction type
            if (transaction.getTransactionType() == 0) {
                account.deposit(transaction.getAmount());
            } else if (transaction.getTransactionType() == 1) {
                account.withdraw(transaction.getAmount());
            } else {
                throw new IllegalArgumentException("Invalid transaction type");
            }
        }
    }

