// Define the structure to hold item information
typedef struct {
    char* name;
    double value;
} item_t;

// Define a linked list node for managing items
typedef struct item_node {
    item_t item;
    struct item_node* next;
} item_node_t;

// Define a data structure to store all items in the collection
struct item_collection {
    int max_length; // maximum length of names in the collection
    int num_items; // number of items in the collection
    item_node_t* head; // pointer to the first node in the linked list
};

// Function to allocate memory for a new item and initialize it with default values
item_t* create_item() {
    item_t* item = malloc(sizeof(item_t));
    if (item == NULL) {
        perror("Failed to allocate memory for an item");
        return NULL;
    }
    item->name = NULL;
    item->value = 0.0;
    return item;
}

// Function to add a new item to the collection
void add_item(struct item_collection* collection, const char* name, double value) {
    // Allocate memory for the item
    item_t* item = create_item();
    if (item == NULL) {
        return;
    }

    // Set the name and value of the item
    strcpy(item->name, name);
    item->value = value;

    // Add the item to the linked list
    collection->num_items++;
    if (collection->head == NULL) {
        collection->head = malloc(sizeof(item_node_t));
        collection->head->next = NULL;
    } else {
        item_node_t* new_node = malloc(sizeof(item_node_t));
        new_node->item = *item;
        new_node->next = collection->head;
        collection->head = new_node;
    }
}

// Function to delete an item from the collection by name
void delete_item(struct item_collection* collection, const char* name) {
    // Find the item in the linked list
    item_node_t* current = collection->head;
    while (current != NULL && strcmp(current->item.name, name) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return; // the item was not found
    }

    // Remove the item from the linked list
    collection->num_items--;
    if (current == collection->head) {
        collection->head = current->next;
    } else {
        item_node_t* previous = current->previous;
        previous->next = current->next;
        free(current);
    }
}

// Function to retrieve an item from the collection by name
item_t* get_item(struct item_collection* collection, const char* name) {
    // Find the item in the linked list
    item_node_t* current = collection->head;
    while (current != NULL && strcmp(current->item.name, name) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL; // the item was not found
    }

    // Return a pointer to the item
    return &current->item;
}

