    record_node_t* head; // pointer to the first node in the linked list
};

// Function to allocate memory for a new record and initialize it with default values
record_t* create_record() {
    record_t* record = malloc(sizeof(record_t));
    if (record == NULL) {
        perror("Failed to allocate memory for a record");
        return NULL;
    }
    record->key = 0;
    record->metric = 0.0;
    record->timestamp = time(NULL);
    return record;
}

// Function to add a new record to the collection
void add_record(struct record_collection* collection, int key, double metric) {
    // Allocate memory for the record
    record_t* record = create_record();
    if (record == NULL) {
        return;
    }

    // Set the key and value of the record
    record->key = key;
    record->metric = metric;

    // Add the record to the linked list
    collection->num_records++;
    if (collection->head == NULL) {
        collection->head = malloc(sizeof(record_node_t));
        collection->head->next = NULL;
    } else {
        record_node_t* new_node = malloc(sizeof(record_node_t));
        new_node->record = *record;
        new_node->next = collection->head;
        collection->head = new_node;
    }
}

// Function to delete a record from the collection by key
void delete_record(struct record_collection* collection, int key) {
    // Find the record in the linked list
    record_node_t* current = collection->head;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }
    if (current == NULL) {
        return; // the record was not found
    }

    // Remove the record from the linked list
    collection->num_records--;
    if (current == collection->head) {
        collection->head = current->next;
    } else {
        record_node_t* previous = current->previous;
        previous->next = current->next;
        free(current);
    }
}

// Function to retrieve a record from the collection by key
record_t* get_record(struct record_collection* collection, int key) {
    // Find the record in the linked list
    record_node_t* current = collection->head;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL; // the record was not found
    }

    // Return a pointer to the record
    return &current->record;
}

// Function to update the maximum length of keys in the collection
void set_max_length(struct record_collection* collection, int max_length) {
    collection->max_length = max_length;
}

// Function to get the maximum length of keys in the collection
int get_max_length(struct record_collection* collection) {
    return collection->max_length;
}

// Function to dynamically update the number of records in the collection
void set_num_records(struct record_collection* collection, int num_records) {
    collection->num_records = num_records;
}

// Function to get the number of records in the collection
int get_num_records(struct record_collection* collection) {
    return collection->num_records;
}

// Function to dynamically update the maximum value in the collection
void set_max_value(struct record_collection* collection, double max_value) {
    collection->max_value = max_value;
}

// Function to get the maximum value in the collection
double get_max_value(struct record_collection* collection) {
    return collection->max_value;
}

// Function to deallocate all allocated memory for the collection
void free_records(struct record_collection* collection) {
    // Free each record in the linked list
    while (collection->head != NULL) {
        record_node_t* current = collection->head;
        collection->head = current->next;
        free(current);
    }
}
