        cd->offset[i] = ok->offset[i];
    }

    // Allocate memory for key array
    cd->keys = (int *)malloc(n * sizeof(int));
    if (!cd->keys) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        exit(EXIT_FAILURE);
    }

    // Copy key values into compressed data structure
    for (int i = 0; i < n; i++) {
        cd->keys[i] = ok->keys[i];
    }
}
