#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <thread>

struct Attack {
    std::string name;
    double value;
};

class AttackManager {
public:
    // Constructor to initialize the attack collection and logging system
    AttackManager(const std::string& filename) : file_(filename), log_() {
        readAttacksFromFile();
        startLogging();
    }

    // Destructor to write the attack collection to disk and clean up resources
    ~AttackManager() {
        stopLogging();
        writeAttacksToFile();
    }

    // Inserts a new attack into the collection
    void insertAttack(const std::string& name, double value) {
        Attack attack;
        attack.name = name;
        attack.value = value;
        attacks_.emplace_back(std::move(attack));
        logInsertion(name, value);
    }

    // Deletes an attack from the collection by its name
    void deleteAttack(const std::string& name) {
        auto it = std::find_if(attacks_.begin(), attacks_.end(), [&](const Attack& attack) { return attack.name == name; });
        if (it != attacks_.end()) {
            attacks_.erase(it);
            logDeletion(name);
        }
    }

    // Returns a list of all attacks that match the given substring in their names
    std::vector<Attack> queryAttacks(const std::string& substring) const {
        std::vector<Attack> results;
        for (const auto& attack : attacks_) {
            if (attack.name.find(substring) != std::string::npos) {
                results.emplace_back(attack);
            }
        }
        return results;
    }

private:
    // Reads the attack collection from a file and initializes the data structures
    void readAttacksFromFile() {
        std::ifstream input(file_);
        if (input) {
            std::string line;
            while (std::getline(input, line)) {
                auto tokens = splitString(line, ':');
                Attack attack;
                attack.name = tokens[0];
                attack.value = std::stod(tokens[1]);
                attacks_.emplace_back(std::move(attack));
            }
        } else {
            throw std::runtime_error("Failed to read from file");
        }
    }

    // Writes the attack collection to a file in case of a system crash or power failure
    void writeAttacksToFile() {
        std::ofstream output(file_, std::ios::binary);
        if (output) {
            for (const auto& attack : attacks_) {
                output << attack.name << ":" << attack.value << "\n";
            }
        } else {
            throw std::runtime_error("Failed to write to file");
        }
    }

    // Starts the logging thread and initializes the logging data structures
    void startLogging() {
        log_ = std::make_unique<std::mutex>();
        logThread_ = std::thread(&AttackManager::logLoop, this);
    }

    // Stops the logging thread and writes any remaining logs to disk
    void stopLogging() {
        if (log_) {
            log_->unlock();
        }
        logThread_.join();
    }

    // Logs an insertion of a new attack
    void logInsertion(const std::string& name, double value) {
        std::lock_guard<std::mutex> lock(*log_);
        log_.emplace_back("I", name, value);
    }

    // Logs a deletion of an attack
    void logDeletion(const std::string& name) {
        std::lock_guard<std::mutex> lock(*log_);
        log_.emplace_back("D", name, 0.0);
    }

    // The logging loop runs in a separate thread and periodically flushes the logs to disk
    void logLoop() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::lock_guard<std::mutex> lock(*log_);
            writeLogsToFile();
        }
    }

    // Writes the logs to disk in case of a system crash or power failure
    void writeLogsToFile() {
        std::ofstream output(file_, std::ios::app | std::ios::binary);
        if (output) {
            for (const auto& log : log_) {
                output << log.first << ":" << log.second << "\n";
            }
        } else {
            throw std::runtime_error("Failed to write logs to file");
        }
    }

    // Splits a string into tokens based on a given delimiter
    std::vector<std::string> splitString(const std::string& s, char delim) const {
        std::vector<std::string> tokens;
        std::stringstream ss(s);
        std::string token;
        while (getline(ss, token, delim)) {
            tokens.push_back(token);
        }
        return tokens;
    }

    // The attack collection and logging data structures
    std::vector<Attack> attacks_;
    std::unique_ptr<std::mutex> log_;
    std::thread logThread_;
};

int main() {
    AttackManager manager("attacks.txt");
    manager.insertAttack("Fireball", 10.0);
    manager.deleteAttack("Ice Spike");
    auto attacks = manager.queryAttacks("Fire");
    for (const auto& attack : attacks) {
        std::cout << attack.name << ":" << attack.value << "\n";
    }
}']

