#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the struct for an order node
struct order_node {
    char* order_id;
    int timestamp;
    double price;
    long long quantity;

    // Pointers to left and right children, and a sibling pointer for concurrent access control
    struct order_node* left;
    struct order_node* right;
    struct order_node* sibling;
};

// Define the custom comparator function for maintaining stable ordering based on priority levels
int compare_order_nodes(const void* node1, const void* node2) {
    // Calculate the priority level of each node based on price and quantity
    double priority_level1 = ((struct order_node*)node1)->price * ((struct order_node*)node1)->quantity;
    double priority_level2 = ((struct order_node*)node2)->price * ((struct order_node*)node2)->quantity;

    // Compare the priority levels to determine the ordering of the nodes
    if (priority_level1 < priority_level2) {
        return -1;
    } else if (priority_level1 > priority_level2) {
        return 1;
    } else {
        return 0;
    }
}

// Define the function for bulk insertion of order nodes into the BST
void bulk_insert(struct order_node** root, struct order_node* new_node) {
    // Check if the tree is empty and insert the first node
    if (*root == NULL) {
        *root = new_node;
        return;
    }

    // Insert the node into the BST using a recursive approach
    struct order_node** current = root;
    while (*current != NULL) {
        compare_order_nodes(new_node, *current);
        if (compare_order_nodes(new_node, *current) < 0) {
            // If the new node is less than the current node, insert it to the left
            if ((*current)->left == NULL) {
                (*current)->left = new_node;
                return;
            } else {
                current = &((*current)->left);
            }
        } else {
            // If the new node is greater than the current node, insert it to the right
            if ((*current)->right == NULL) {
                (*current)->right = new_node;
                return;
            } else {
                current = &((*current)->right);
            }
        }
    }
}

// Define the function for bulk deletion of order nodes from the BST
void bulk_delete(struct order_node** root, struct order_node* target_node) {
    // Check if the tree is empty
    if (*root == NULL) {
        return;
    }

    // Delete the node from the BST using a recursive approach
    struct order_node** current = root;
    while (*current != NULL && compare_order_nodes(target_node, *current) != 0) {
        if (compare_order_nodes(target_node, *current) < 0) {
            // If the target node is less than the current node, move to the left
            current = &((*current)->left);
        } else {
            // If the target node is greater than the current node, move to the right
            current = &((*current)->right);
        }
    }

    // If the target node is found, delete it from the BST
    if (*current != NULL) {
        struct order_node* tmp;
        if ((*current)->left == NULL && (*current)->right == NULL) {
            tmp = *current;
            *current = NULL;
            free(tmp);
        } else if ((*current)->left != NULL && (*current)->right != NULL) {
            tmp = *current;
            *current = tmp->right;
            tmp->right = NULL;
            free(tmp);
        } else if ((*current)->left != NULL) {
            tmp = *current;
            *current = tmp->left;
            tmp->left = NULL;
            free(tmp);
        } else {
            tmp = *current;
            *current = tmp->right;
            tmp->right = NULL;
            free(tmp);
        }
    }
}

// Define the function for retrieving an order node from the BST
struct order_node* retrieve_order(struct order_node** root, char* order_id) {
    // Check if the tree is empty
    if (*root == NULL) {
        return NULL;
    }

    // Search for the target order ID in the BST using a recursive approach
    struct order_node** current = root;
    while (*current != NULL && strcmp((*current)->order_id, order_id) != 0) {
        if (strcmp(order_id, (*current)->order_id) < 0) {
            // If the target order ID is less than the current node's order ID, move to the left
            current = &((*current)->left);
        } else {
            // If the target order ID is greater than the current node's order ID, move to the right
            current = &((*current)->right);
        }
    }

    // Return the found order node or NULL if not found
    return *current;
}

// Define the function for updating an existing order in the BST
void update_order(struct order_node** root, char* order_id, int timestamp, double price, long long quantity) {
    // Retrieve the target order node from the BST
    struct order_node* found_node = retrieve_order(root, order_id);

    // If the target order is not found, return
    if (found_node == NULL) {
        return;
    }

    // Update the fields of the target order node
    found_node->timestamp = timestamp;
    found_node->price = price;
    found_node->quantity = quantity;
}

// Define the function for deleting an existing order from the BST
void delete_order(struct order_node** root, char* order_id) {
    // Retrieve the target order node from the BST
    struct order_node* found_node = retrieve_order(root, order_id);

    // If the target order is not found, return
    if (found_node == NULL) {
        return;
    }

    // Delete the target order node from the BST
    bulk_delete(root, found_node);
}

// Define the function for maintaining a least-recently-used (LRU) cache of order IDs
void lru_cache(struct order_node** root, char* order_id) {
    // Check if the tree is empty
    if (*root == NULL) {
        return;
    }

    // Search for the target order ID in the BST using a recursive approach
    struct order_node** current = root;
    while (*current != NULL && strcmp((*current)->order_id, order_id) != 0) {
        if (strcmp(order_id, (*current)->order_id) < 0) {
            // If the target order ID is less than the current node's order ID, move to the left
            current = &((*current)->left);
        } else {
            // If the target order ID is greater than the current node's order ID, move to the right
            current = &((*current)->right);
        }
    }

    // If the target order is not found in the BST, return
    if (*current == NULL) {
        return;
    }

    // Remove the target order node from its position in the BST
    struct order_node* tmp = *current;
    *current = NULL;
    free(tmp);

    // Add the target order node to the end of the LRU cache
    lru_cache(root, order_id);
}

// Define the function for resizing the LRU cache based on a configurable hit rate threshold
void resize_lru_cache(struct order_node** root, float hit_rate_threshold) {
    // Check if the tree is empty
    if (*root == NULL) {
        return;
    }

    // Calculate the current cache size and capacity
    int current_size = 0;
    struct order_node* current = *root;
    while (current != NULL) {
        current_size++;
        current = current->left;
    }
    int current_capacity = current_size / hit_rate_threshold;

    // Check if the current capacity is less than the minimum required capacity for efficient lookup
    if (current_capacity < 10) {
        return;
    }

    // Resize the cache by removing excess nodes from the beginning of the BST
    while (current_size > current_capacity) {
        struct order_node* tmp = *root;
        *root = NULL;
        free(tmp);
        current_size--;
    }
}
```
