#include <string.h>

// Define the structure to store item information
typedef struct {
    char* name;
    double value;
    int category;
} item_t;

// Define the collection structure
typedef struct {
    item_t* items; // pointer to an array of items
    size_t count;  // number of items in the collection
    size_t capacity; // maximum number of items that can be stored
} collection_t;

// Define a function to initialize and allocate memory for the collection
void init_collection(collection_t* coll) {
    coll->items = (item_t*)malloc(sizeof(item_t) * 1000000); // allocate memory for 10 million items
    coll->count = 0;
    coll->capacity = 1000000;
}

// Define a function to insert an item into the collection
void insert_item(collection_t* coll, const char* name, double value, int category) {
    if (coll->count == coll->capacity) { // if the collection is full, reallocate more memory
        size_t new_capacity = coll->capacity * 2;
        item_t* new_items = (item_t*)realloc(coll->items, sizeof(item_t) * new_capacity);
        if (!new_items) { // if reallocation fails, print an error message and exit
            printf("Error: failed to allocate memory for the collection\n");
            exit(1);
        }
        coll->items = new_items;
        coll->capacity = new_capacity;
    }
    size_t index = coll->count++; // get the next available index in the array
    coll->items[index].name = strdup(name);
    coll->items[index].value = value;
    coll->items[index].category = category;
}

// Define a function to delete an item from the collection
void delete_item(collection_t* coll, size_t index) {
    if (index >= coll->count) return; // if the index is out of range, do nothing
    for (size_t i = index + 1; i < coll->count - 1; i++) { // shift all items after the deleted item one position to the left
        coll->items[i - 1] = coll->items[i];
    }
    coll->count--;
}

// Define a function to retrieve an item from the collection by its index
item_t* get_item(collection_t* coll, size_t index) {
    if (index >= coll->count) return NULL; // if the index is out of range, return NULL
    return &coll->items[index];
}

// Define a function to retrieve an item from the collection by its name
item_t* get_item_by_name(collection_t* coll, const char* name) {
    for (size_t i = 0; i < coll->count; i++) {
        if (!strcmp(coll->items[i].name, name)) return &coll->items[i];
    }
    return NULL;
}

// Define a function to update an item in the collection by its index
void update_item(collection_t* coll, size_t index, const char* name, double value, int category) {
    if (index >= coll->count) return; // if the index is out of range, do nothing
    coll->items[index].name = strdup(name);
    coll->items[index].value = value;
    coll->items[index].category = category;
}

// Define a function to update an item in the collection by its name
void update_item_by_name(collection_t* coll, const char* old_name, const char* new_name, double value, int category) {
    for (size_t i = 0; i < coll->count; i++) {
        if (!strcmp(coll->items[i].name, old_name)) {
            update_item(coll, i, new_name, value, category);
            return;
        }
    }
}

// Define a function to persist the collection to disk
void persist_collection(const char* filename) {
    FILE* file = fopen(filename, "wb"); // open the file for writing in binary mode
    if (!file) return; // if the file cannot be opened, do nothing
    size_t count = coll->count; // get the current number of items in the collection
    for (size_t i = 0; i < count; i++) {
        item_t* item = &coll->items[i]; // get the current item
        fwrite(item, sizeof(item_t), 1, file); // write the item to the file
    }
    fclose(file); // close the file
}

// Define a function to load the collection from disk
void load_collection(const char* filename) {
    FILE* file = fopen(filename, "rb"); // open the file for reading in binary mode
    if (!file) return; // if the file cannot be opened, do nothing
    coll->count = 0; // reset the number of items in the collection
    size_t count = (size_t)-1; // get the current number of items from the file
    while ((fread(&coll->items[coll->count], sizeof(item_t), 1, file) == 1) && (coll->count < count)) {
        coll->count++; // increment the number of items in the collection
    }
    fclose(file); // close the file
}

// Define a function to query the collection based on a substring match within the item names
void query_collection(const char* substr) {
    for (size_t i = 0; i < coll->count; i++) {
        if (strstr(coll->items[i].name, substr)) printf("%d: %s\n", i, coll->items[i].name);
    }
}

// Define a function to update the maximum length of names and the acceptable range of values stored in the `item` structures
void update_parameters(size_t max_name_length, double min_value, double max_value) {
    for (size_t i = 0; i < coll->count; i++) {
        if (strlen(coll->items[i].name) > max_name_length) coll->items[i].name[max_name_length] = '\0'; // truncate the name to the maximum length
        if (coll->items[i].value < min_value) coll->items[i].value = min_value; // adjust the value to the minimum acceptable range
        if (coll->items[i].value > max_value) coll->items[i].value = max_value; // adjust the value to the maximum acceptable range
    }
}
