    struct data* out = (struct data*)malloc(sizeof(struct data));
    if (!out) {
        printf("Memory allocation error\n");
        return -6;
    }

    // Initialize output data structure
    out->n = n;
    out->data = (float*)calloc(n, sizeof(float));
    if (!out->data) {
        free(out);
        printf("Memory allocation error\n");
        return -7;
