        case STDDEV:
            stddev(dev_data, out);
            break;
        case CLUSTERING:
            clustering(dev_data, out);
            break;
        case TIME_SERIES_FORECASTING:
            time_series_forecasting(dev_data, out);
            break;
    }

    // Handle errors and edge cases during data processing
    if (out->n == 0) {
        printf("No output generated\n");
        free(out->data);
        free(out);
        return -8;
    } else if (!is_valid(out)) {
        printf("Invalid output generated\n");
        free(out->data);
        free(out);
        return -9;
    }

    // Log successful operation and return output data
    printf("Processed %d points using algorithm '%s'\n", n, options.alg);
    return out;
}

// Convert string to analytics algorithm enum value
enum algo str_to_algo(char* alg) {
    if (!strcmp(alg, "mean")) return MEAN;
    else if (!strcmp(alg, "median")) return MEDIAN;
    else if (!strcmp(alg, "stddev")) return STDDEV;
    else if (!strcmp(alg, "clustering")) return CLUSTERING;
    else if (!strcmp(alg, "time_series_forecasting")) return TIME_SERIES_FORECASTING;
    else return UNKNOWN;
}

// Validate input data structure
int is_valid(struct data* d) {
    // Check for null pointers and 0-length arrays
    if (!d || !d->n || !d->data) return 0;

    // Check for NaN or infinite values
    int n = d->n;
    for (int i = 0; i < n; ++i) {
        if (isnan(d->data[i]) || isinf(d->data[i])) return 0;
    }

    // Check for missing or malformed data
    int missing_count = 0;
    for (int i = 0; i < n; ++i) {
        if (!is_valid(d->data[i]) || isnan(d->data[i])) {
            ++missing_count;
        }
    }
    if (missing_count > 0) return 0;

    // Data is valid
    return 1;
}

// Free memory allocated for input and output data structures
void free_data(struct data** inputs, struct data** outputs) {
    // Check for null pointers
    if (!inputs || !outputs) return;

    // Loop through input and output data structures and free memory
    int n = inputs->n;
    for (int i = 0; i < n; ++i) {
        struct data* dev_data = inputs[i];
        if (!dev_data) continue;
        free(dev_data->data);
        free(dev_data);
    }
    int m = outputs->n;
    for (int i = 0; i < m; ++i) {
        struct data* out = outputs[i];
        if (!out) continue;
        free(out->data);
        free(out);
    }
}
