struct Attack {
  std::string name;
  double value;
};

class DynamicAttackManager {
 private:
  std::vector<Attack> attacks_;
  std::unordered_map<std::string, size_t> attackMap_;
  size_t maxNameLength_;
  double minValue_, maxValue_;
  size_t totalMemoryUsage_;
  bool isPersisting_;
  std::ofstream persistenceFile_;

 public:
  DynamicAttackManager() {
    attacks_.reserve(1000000);
    attackMap_.reserve(1000000);
    maxNameLength_ = 32;
    minValue_ = -1.0;
    maxValue_ = +1.0;
    totalMemoryUsage_ = 0;
    isPersisting_ = false;
    persistenceFile_.open("attack_data.txt", std::ios::out | std::ios::binary);
  }

  ~DynamicAttackManager() {
    if (isPersisting_) {
      persistenceFile_.close();
    }
  }

  void insert(const std::string& name, double value) {
    if (!attackMap_.count(name)) {
      attacks_.push_back({name, value});
      attackMap_[name] = attacks_.size() - 1;
      totalMemoryUsage_ += sizeof(Attack);
      if (name.length() > maxNameLength_) {
        maxNameLength_ = name.length();
      }
      if (value < minValue_) {
        minValue_ = value;
      } else if (value > maxValue_) {
        maxValue_ = value;
      }
    } else {
      attacks_[attackMap_[name]].value = value;
    }
  }

  void delete(const std::string& name) {
    if (attackMap_.count(name)) {
      auto index = attackMap_[name];
      attackMap_.erase(name);
      attacks_.erase(attacks_.begin() + index);
      totalMemoryUsage_ -= sizeof(Attack);
    }
  }

  Attack* findByName(const std::string& name) {
    if (attackMap_.count(name)) {
      return &attacks_[attackMap_[name]];
    } else {
      return nullptr;
    }
  }

  const Attack* findByName(const std::string& name) const {
    if (attackMap_.count(name)) {
      return &attacks_[attackMap_[name]];
    } else {
      return nullptr;
    }
  }

  void printLongestAttackName() const {
    std::cout << attacks_.back().name << '\n';
  }

  double getMinValue() const {
    return minValue_;
  }

  double getMaxValue() const {
    return maxValue_;
  }

  size_t getTotalMemoryUsage() const {
    return totalMemoryUsage_;
  }

  void enablePersistence() {
    isPersisting_ = true;
  }

  void disablePersistence() {
    isPersisting_ = false;
  }

  void persistData() {
    if (isPersisting_) {
      persistenceFile_.write((char*)&attacks_, sizeof(Attack) * attacks_.size());
      persistenceFile_.close();
    }
  }

  bool loadPersistedData() {
    if (!std::ifstream("attack_data.txt", std::ios::in | std::ios::binary).good()) {
      return false;
    }
    attacks_.clear();
    attackMap_.clear();
    totalMemoryUsage_ = 0;
    size_t attackCount = 0;
    while (attackCount < 1000000) {
      Attack attack;
      persistenceFile_.read((char*)&attack, sizeof(Attack));
      if (!persistenceFile_) {
        break;
      }
      attacks_.push_back(attack);
      attackMap_[attack.name] = attackCount++;
      totalMemoryUsage_ += sizeof(Attack);
    }
    return true;
  }

  void randomSelectOneOfTwoPredefinedAttacks() {
    // Implement a mechanism to randomly select one of two predefined attacks for a video game character to use, with a cooldown period between attacks. The function should have no arguments and return nothing. The cooldown period should be 9 seconds, and the function should print the selected attack number to the console.
    // Using a random number generator is recommended to ensure fairness of selection.
    std::srand(std::time(0));
    int attackNumber = std::rand() % 2 + 1;
    printf("Selected attack number: %d\n", attackNumber);
  }

  void testModule(const char* moduleName) {
    // Load the module using the `require` function, run the tests, and then reset a mocking library called `blueslip`.
    // Use the `module.exports` property to access the exported functions of the module.
    require(moduleName);
    const auto& exports = module.exports;
    for (const auto& testFunction : exports) {
      testFunction();
    }
    resetBlueslip();
  }
};
