  fprintf(stderr, "Number of records retained: %d\n", num_records);

  // Clean up and exit
  custom_free(records);
}

// Comparison function for sorting records by their offset values in descending order
int compare_record_offsets(const void* a, const void* b) {
  const Record* record1 = (const Record*)a;
  const Record* record2 = (const Record*)b;
  if (record1->offset > record2->offset) {
    return -1;
  } else if (record1->offset < record2->offset) {
    return 1;
  } else {
    return 0;
  }
}
```
