#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <thread>

using namespace std;

struct DataRecord {
    string key;
    double value;
};

class FlexibleDataProcessing {
private:
    vector<string> keys; // array of strings to store the keys
    vector<double> values; // array of doubles to store the values
    map<string, int> keyIndexMap; // map of key-index pairs for fast lookups
    mutex mut; // mutex for thread safety
public:
    FlexibleDataProcessing() {
        keys.reserve(10000000);
        values.reserve(10000000);
        keyIndexMap.reserve(10000000);
    }

    void insertRecord(const string& key, double value) {
        // mutex lock for thread safety
        unique_lock<mutex> lock(mut);

        // check if the record already exists in the map
        auto it = keyIndexMap.find(key);
        if (it != keyIndexMap.end()) {
            values[it->second] = value;
        } else {
            // insert a new record into the arrays
            keys.push_back(key);
            values.push_back(value);
            keyIndexMap[key] = keys.size() - 1;
        }
    }

    void deleteRecord(const string& key) {
        // mutex lock for thread safety
        unique_lock<mutex> lock(mut);

        // check if the record exists in the map
        auto it = keyIndexMap.find(key);
        if (it != keyIndexMap.end()) {
            // remove the record from the arrays
            int index = it->second;
            keys[index] = "";
            values[index] = 0.0;
            keyIndexMap.erase(it);
        }
    }

    double getRecordValue(const string& key) {
        // mutex lock for thread safety
        unique_lock<mutex> lock(mut);

        // check if the record exists in the map
        auto it = keyIndexMap.find(key);
        if (it != keyIndexMap.end()) {
            return values[it->second];
        } else {
            return 0.0;
        }
    }

    void deallocateMemory() {
        keys.clear();
        values.clear();
        keyIndexMap.clear();
    }
};
```
