#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/resource.h>
#include <pthread.h>

#define MAX_CONCURRENT_TASKS 10
#define MIN_MEMORY_THRESHOLD (5 * 1024 * 1024) // 5 MB

typedef struct {
    int key;
    float value;
    char* label;
    char* json;
} Configuration;

typedef struct {
    Configuration** configurations;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConfigurationList;

void initConfigurationList(ConfigurationList* list) {
    list->configurations = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void freeConfigurationList(ConfigurationList* list) {
    for (size_t i = 0; i < list->count; i++) {
        Configuration* config = list->configurations[i];
        free(config->label);
        free(config->json);
        free(config);
    }
    free(list->configurations);
}

int addConfiguration(ConfigurationList* list, int key, float value, char* label, char* json) {
    Configuration* config = malloc(sizeof(Configuration));
    if (config == NULL) {
        return -1; // Out of memory
    }
    config->key = key;
    config->value = value;
    config->label = strdup(label);
    config->json = strdup(json);
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Configuration** new_configurations = realloc(list->configurations, new_capacity * sizeof(Configuration*));
        if (new_configurations == NULL) {
            free(config);
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }
        list->configurations = new_configurations;
        list->capacity = new_capacity;
    }
    list->configurations[list->count++] = config;
    pthread_cond_broadcast(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeConfiguration(ConfigurationList* list, int key) {
    size_t i;
    for (i = 0; i < list->count; i++) {
        Configuration* config = list->configurations[i];
        if (config->key == key) {
            break;
        }
    }
    if (i >= list->count) {
        return -1; // Key not found
    }
    Configuration* config = list->configurations[i];
    free(config->label);
    free(config->json);
    free(config);
    pthread_mutex_lock(&list->lock);
    if (i < list->count - 1) {
        memmove(&list->configurations[i], &list->configurations[i + 1], (list->count - i - 1) * sizeof(Configuration*));
    }
    list->count--;
    pthread_cond_broadcast(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int getConfiguration(ConfigurationList* list, int key, Configuration** config) {
    size_t i;
    for (i = 0; i < list->count; i++) {
        Configuration* candidate = list->configurations[i];
        if (candidate->key == key) {
            break;
        }
    }
    if (i >= list->count) {
        return -1; // Key not found
    }
    *config = list->configurations[i];
    return 0;
}

int getAllConfigurations(ConfigurationList* list, Configuration*** configs, size_t* count) {
    pthread_mutex_lock(&list->lock);
    if (list->count == 0) {
        *configs = NULL;
        *count = 0;
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    size_t capacity = list->count * sizeof(Configuration*);
    Configuration** config_ptrs = malloc(capacity);
    if (config_ptrs == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Out of memory
    }
    memcpy(config_ptrs, list->configurations, capacity);
    *configs = config_ptrs;
    *count = list->count;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int freeAllConfigurations(ConfigurationList* list) {
    for (size_t i = 0; i < list->count; i++) {
        Configuration* config = list->configurations[i];
        free(config->label);
        free(config->json);
        free(config);
    }
    free(list->configurations);
}

int backgroundTaskHandler(void* arg) {
    struct BackgroundTaskArgs* args = (struct BackgroundTaskArgs*)arg;
    size_t task_id = args->task_id;
    char* api_url = args->api_url;
    char* api_key = args->api_key;
    ConfigurationList* list = args->list;
    int retval = 0;
    while (1) {
        pthread_mutex_lock(&args->lock);
        while (args->pending_tasks < MAX_CONCURRENT_TASKS) {
            pthread_cond_wait(&args->cond, &args->lock);
        }
        args->pending_tasks--;
        pthread_mutex_unlock(&args->lock);
        Configuration* config = list->configurations[task_id];
        char* api_url_suffix = getApiUrlSuffix(config->key);
        if (api_url_suffix == NULL) {
            retval = -1; // Invalid configuration key
            break;
        }
        char* url = malloc((strlen(api_url) + strlen(api_url_suffix) + 1) * sizeof(char));
        if (url == NULL) {
            retval = -1; // Out of memory
            break;
        }
        sprintf(url, "%s%s", api_url, api_url_suffix);
        CURL* curl = curl_easy_init();
        if (curl == NULL) {
            retval = -1; // Failed to initialize cURL handle
            break;
        }
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_USERPWD, api_key);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeToFile);
        FILE* fp = fopen("result.json", "w");
        if (fp == NULL) {
            retval = -1; // Failed to open result file for writing
            break;
        }
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        CURLcode res = curl_easy_perform(curl);
        fclose(fp);
        if (res != CURLE_OK) {
            retval = -1; // cURL request failed
            break;
        }
        Configuration* updated_config = malloc(sizeof(Configuration));
        if (updated_config == NULL) {
            retval = -1; // Out of memory
            break;
        }
        updated_config->key = config->key;
        updated_config->value = config->value;
        char* json = malloc((strlen(api_url_suffix) + 1) * sizeof(char));
        if (json == NULL) {
            retval = -1; // Out of memory
            break;
        }
        sprintf(json, "%s", api_url_suffix);
        updated_config->json = json;
        freeConfigurationList(list);
        retval = addConfiguration(list, updated_config);
        if (retval != 0) {
            break;
        }
    }
    pthread_mutex_lock(&args->lock);
    args->pending_tasks++;
    pthread_cond_signal(&args->cond);
    pthread_mutex_unlock(&args->lock);
    return retval;
}
```
