// Define the logging levels
enum class LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR
};

// Define the logging backends
enum class LogBackend {
    FILE,
    CONSOLE,
    HTTP
};

// Define the logging settings
struct LogSettings {
    LogLevel level; // The minimum log level to be logged
    LogBackend backend; // The logging backend to use
    std::string filename; // The file name for file-based logging
};

// Define the logging message structure
struct LogMessage {
    LogLevel level; // The log level of the message
    std::string message; // The log message itself
};

// Define the logging system class
class Logger {
private:
    // The current settings for the logger
    LogSettings settings_;

    // The mutex to protect the logging messages vector
    std::mutex mtx_;

    // The condition variable to signal when a new message is available
    std::condition_variable cv_;

    // The vector of logging messages
    std::vector<LogMessage> messages_;

    // The file stream for file-based logging
    std::ofstream logfile_;

public:
    // Constructor
    Logger(const LogSettings& settings) : settings_(settings), logfile_() {
        if (settings_.backend == LogBackend::FILE) {
            logfile_.open(settings_.filename);
        }
    }

    // Destructor
    ~Logger() {
        if (logfile_.is_open()) {
            logfile_.close();
        }
    }

    // Set the logging settings
    void setSettings(const LogSettings& settings) {
        std::lock_guard<std::mutex> lock(mtx_);
        settings_ = settings;
    }

    // Get the current logging settings
    const LogSettings& getSettings() const {
        return settings_;
    }

    // Add a log message to the vector
    void addMessage(const LogLevel level, const std::string& message) {
        std::lock_guard<std::mutex> lock(mtx_);
        messages_.emplace_back(LogMessage{level, message});
        cv_.notify_all();
    }

    // Flush the log messages to the console or file
    void flushMessages() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto& msg : messages_) {
            if (settings_.backend == LogBackend::CONSOLE) {
                std::cout << "[" << msg.level << "] " << msg.message << std::endl;
            } else if (settings_.backend == LogBackend::FILE) {
                logfile_ << "[" << msg.level << "] " << msg.message << std::endl;
            }
        }
        messages_.clear();
    }
};

// Define the logging context class
class LoggerContext {
private:
    // The logger instance for this context
    std::shared_ptr<Logger> logger_;

public:
    // Constructor
    LoggerContext(const LogSettings& settings) : logger_(std::make_shared<Logger>(settings)) {}

    // Set the logging settings
    void setSettings(const LogSettings& settings) {
        logger_->setSettings(settings);
    }

    // Get the current logging settings
    const LogSettings& getSettings() const {
        return logger_->getSettings();
    }

    // Add a log message to the logger
    void addMessage(const LogLevel level, const std::string& message) {
        logger_->addMessage(level, message);
    }

    // Flush the log messages to the console or file
    void flushMessages() {
        logger_->flushMessages();
    }
};

// Define a simple program that demonstrates the logging framework
int main() {
    // Set up the logging settings and create the context
    LogSettings settings = {LogLevel::DEBUG, LogBackend::FILE, "example.log"};
    LoggerContext context(settings);

    // Create some log messages
    LogMessage msg1{LogLevel::INFO, "This is a test message"};
    LogMessage msg2{LogLevel::WARN, "This is another test message"};
    LogMessage msg3{LogLevel::ERROR, "This is an error message"};

    // Add the messages to the context and flush them
    context.addMessage(msg1);
    context.addMessage(msg2);
    context.addMessage(msg3);
    context.flushMessages();

    return 0;
}
```
This is a simple logging framework that can be used to log messages at different levels and send them to different backends, such as file-based logging, console logging, or remote logging over HTTP. The framework is designed to be modular and configurable, allowing users to select and switch logging backends and levels at runtime. It also includes a dynamic configuration mechanism that reads logging settings from environment variables or a configuration file, ensuring the system adapts to changes without requiring restarts.

