int max_data_points = 50000000; // Maximum number of data points allowed
struct data_point *data_points; // Array of data points

// Function to allocate memory for the arrays
void allocate_memory(int num_categories, int num_data_points) {
    // Allocate memory for the double array
    total_memory += sizeof(double) * num_data_points;
    if (total_memory > max_memory) {
        printf("Memory usage limit exceeded. Total memory: %ld\n", total_memory);
        exit(1);
    }
    data_points = malloc(sizeof(struct data_point) * num_data_points);
    if (data_points == NULL) {
        printf("Error: Failed to allocate memory for data points.\n");
        exit(1);
    }
}

// Function to deallocate memory for the arrays
void deallocate_memory() {
    free(data_points);
}

// Function to calculate the average value of all double fields across all data points
double get_average_value() {
    double sum = 0;
    for (int i = 0; i < num_data_points; i++) {
        sum += data_points[i].value;
    }
    return sum / num_data_points;
}

// Function to parse a string into a data point structure
void parse_string(char *str, struct data_point *dp) {
    // Split the string into two parts: the double value and the category label
    char *delimiter = " ";
    char *token = strtok(str, delimiter);
    dp->value = atof(token);
    token = strtok(NULL, delimiter);
    dp->category = (char) atoi(token);
}

