    // Synchronize updates to the scale factor with ongoing processing of existing data points
    pthread_mutex_lock(&scale_factor_mutex);
    if (new_scale_factor != scale_factor) {
        scale_factor = new_scale_factor;
        // Notify any threads that are waiting for the scale factor to be updated
        pthread_cond_signal(&scale_factor_cond);
    }
    pthread_mutex_unlock(&scale_factor_mutex);
}

// Function to handle inputs gracefully and provide accurate results even when the list of strings is very large
void input_handler(char *input) {
    // Parse the input string into a data point structure
    struct data_point dp;
    parse_string(input, &dp);
    // Calculate the floating-point value based on the ASCII value of the category label and the scale factor
    dp.value = (double) (dp.category - 'A') / scale_factor;
    // Add the data point to the array
    data_points[num_data_points++] = dp;
}

// Main function to demonstrate effective memory management and efficient processing of input data
