    // Initialize variables for memory management
    total_memory = 0;
    num_data_points = 0;
    max_data_points = 50000000;
    data_points = NULL;
    // Initialize a mutex and condition variable for synchronizing updates to the scale factor
    pthread_mutex_t scale_factor_mutex = PTHREAD_MUTEX_INITIALIZER;
