// Define the structure to store events
typedef struct Event {
    uint64_t offset;
    char* key;
    int* value;
} Event;

// Define the hash function for the event offset
uint64_t hash(Event *event) {
    return event->offset % 1000000007; // Use a prime number as the modulus to ensure uniqueness
}

// Define the comparison function for the event offset
bool compare_offsets(Event *event1, Event *event2) {
    return event1->offset == event2->offset;
}

// Define the hash function for the event key
uint64_t hash_key(char* key) {
    uint64_t hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % 1000000007; // Use a prime number as the modulus to ensure uniqueness
}

// Define the comparison function for the event key
bool compare_keys(char* key1, char* key2) {
    return strcmp(key1, key2) == 0;
}

// Define the hash table data structure
typedef struct HashTable {
    Event** events;
    int capacity;
    int size;
} HashTable;

// Initialize a new hash table with a given capacity
void init_hash_table(HashTable* hash_table, int capacity) {
    hash_table->events = malloc(sizeof(Event*) * capacity);
    hash_table->capacity = capacity;
    hash_table->size = 0;
}

// Insert an event into the hash table
void insert_event(HashTable* hash_table, Event* event) {
    // Check if the hash table is full
    if (hash_table->size >= hash_table->capacity) {
        return;
    }

    // Calculate the hash value for the event offset and key
    uint64_t offset_hash = hash(event);
    uint64_t key_hash = hash_key(event->key);

    // Find the first empty slot in the hash table
    int index = 0;
    while (index < hash_table->capacity && hash_table->events[index] != NULL) {
        index++;
    }

    // If all slots are occupied, resize the hash table
    if (index == hash_table->capacity) {
        HashTable* new_hash_table = malloc(sizeof(HashTable));
        init_hash_table(new_hash_table, 2 * hash_table->capacity);

        // Copy all events from the old hash table to the new one
        for (int i = 0; i < hash_table->capacity; i++) {
            if (hash_table->events[i] != NULL) {
                insert_event(new_hash_table, hash_table->events[i]);
            }
        }

        // Free the old hash table and assign the new one
        free(hash_table->events);
        hash_table = new_hash_table;
    }

    // Insert the event into the hash table at the found index
    hash_table->events[index] = event;
    hash_table->size++;
}

// Look up an event in the hash table by its offset and key
Event* lookup_event(HashTable* hash_table, uint64_t offset, char* key) {
    // Calculate the hash values for the offset and key
    uint64_t offset_hash = hash(offset);
    uint64_t key_hash = hash_key(key);

    // Find the first matching event in the hash table
    int index = 0;
    while (index < hash_table->capacity && hash_table->events[index] != NULL) {
        if (compare_offsets(&(hash_table->events[index]->offset), &offset) && compare_keys(&(hash_table->events[index]->key), key)) {
            break;
        }
        index++;
    }

    // If no matching event is found, return NULL
    if (index == hash_table->capacity) {
        return NULL;
    }

    // Return the found event
    return hash_table->events[index];
}

// Update an existing event in the hash table by its offset and key
void update_event(HashTable* hash_table, uint64_t offset, char* key, int* value) {
    // Look up the existing event in the hash table
    Event* event = lookup_event(hash_table, offset, key);

    // If no matching event is found, create a new one
    if (event == NULL) {
        event = malloc(sizeof(Event));
        event->offset = offset;
        event->key = key;
        event->value = value;
        insert_event(hash_table, event);
    } else {
        // Update the existing event's value
        free(event->value);
        event->value = value;
    }
}

// Remove an event from the hash table by its offset and key
void remove_event(HashTable* hash_table, uint64_t offset, char* key) {
    // Look up the existing event in the hash table
    Event* event = lookup_event(hash_table, offset, key);

    // If no matching event is found, return NULL
    if (event == NULL) {
        return;
    }

    // Find the index of the event in the hash table
    int index = 0;
    while (index < hash_table->capacity && hash_table->events[index] != event) {
        index++;
    }

    // If the found event is not at the end of the hash table, swap it with the last element and decrease the size
    if (index < hash_table->capacity - 1) {
        Event* temp = hash_table->events[index];
        hash_table->events[index] = hash_table->events[hash_table->capacity - 1];
        hash_table->events[hash_table->capacity - 1] = temp;
        hash_table->size--;
    } else {
        // If the found event is at the end of the hash table, simply decrease the size
        hash_table->size--;
    }

    // Free the memory allocated for the removed event
    free(event);
}
