// External data source
struct Attack {
    std::string name;
    double value;
};

class AttackManager {
public:
    // Constructor to initialize the attack collection
    explicit AttackManager(size_t maxAttacks = 10'000'000, size_t maxNameLength = 256) :
        maxAttacks_(maxAttacks), maxNameLength_(maxNameLength), attacks_{} {}

    // Insert an attack into the collection
    void insert(const Attack& attack) {
        if (attacks_.size() >= maxAttacks_) {
            throw std::out_of_range("Maximum number of attacks exceeded");
        }
        auto name = attack.name;
        // Check for invalid characters in the attack name
        if (!std::all_of(name.begin(), name.end(), [](char c) { return c != 0 && c != '\n'; })) {
            throw std::invalid_argument("Invalid character in attack name");
        }
        // Check for attack strength out of range
        if (attack.value < 0 || attack.value > 1) {
            throw std::out_of_range("Attack strength out of range");
        }
        attacks_.emplace(name, attack);
    }

    // Remove an attack from the collection
    void remove(const Attack& attack) {
        auto name = attack.name;
        if (attacks_.find(name) == attacks_.end()) {
            throw std::invalid_argument("Attack not found");
        }
        attacks_.erase(name);
    }

    // Retrieve an attack by its name
    Attack* get(const std::string& name) const {
        auto it = attacks_.find(name);
        if (it == attacks_.end()) {
            return nullptr;
        }
        return &it->second;
    }

    // Retrieve the longest attack name in the collection
    Attack* getLongestAttack() const {
        std::string longestName;
        double longestValue = 0;
        for (const auto& [name, attack] : attacks_) {
            if (name.length() > longestName.length()) {
                longestName = name;
                longestValue = attack.value;
            } else if (name.length() == longestName.length() && attack.value > longestValue) {
                longestName = name;
                longestValue = attack.value;
            }
        }
        return get(longestName);
    }

    // Simulate a cooldown period for the video game character's attack selection
    void simulateCooldown() {
        std::random_device rd;
        std::mt19937 mt(rd());
        std::uniform_int_distribution<size_t> dist(0, 2); // Select one of two attacks randomly
        auto attack = getLongestAttack();
        if (attack == nullptr) {
            return;
        }
        auto cooldownDuration = std::chrono::seconds{9};
        while (true) {
            if (dist(mt) == 0) { // Select attack 1
                std::cout << "Selected attack 1 with strength: " << attack->value << '\n';
                break;
            } else { // Select attack 2
                std::cout << "Selected attack 2 with strength: " << attack->value << '\n';
                break;
            }
        }
    }

private:
    size_t maxAttacks_;
    size_t maxNameLength_;
    std::unordered_map<std::string, Attack> attacks_;
};
