// LogLevel enum
enum class LogLevel { INFO, WARN, ERROR };

// LogEntry struct to store log data
struct LogEntry {
    std::string timestamp;
    std::string message;
    LogLevel level;
};

// LogManager class to manage log collection and storage
class LogManager {
public:
    // Constructor initializes log parameters
    LogManager(size_t max_timestamp_len, size_t max_message_len, LogLevel min_level) :
        max_timestamp_len_(max_timestamp_len), max_message_len_(max_message_len), min_level_(min_level) { }

    // Adds a log entry to the collection
    void addLogEntry(const std::string& timestamp, const std::string& message, LogLevel level) {
        LogEntry entry;
        entry.timestamp = timestamp;
        entry.message = message;
        entry.level = level;

        // Check if the log entry is valid and meets minimum requirements
        if (entry.timestamp.length() > max_timestamp_len_ || entry.message.length() > max_message_len_ || entry.level < min_level_) {
            return;
        }

        // Add the log entry to the vector
        logs_.push_back(std::move(entry));
    }

    // Removes a log entry from the collection based on timestamp and message content
    void removeLogEntry(const std::string& timestamp, const std::string& message) {
        auto it = std::find_if(logs_.begin(), logs_.end(), [=](const LogEntry& entry) {
            return entry.timestamp == timestamp && entry.message == message;
        });

        // If the log entry is found, remove it from the vector
        if (it != logs_.end()) {
            logs_.erase(it);
        }
    }

    // Retrieves a log entry from the collection based on timestamp and message content
    LogEntry retrieveLogEntry(const std::string& timestamp, const std::string& message) {
        auto it = std::find_if(logs_.begin(), logs_.end(), [=](const LogEntry& entry) {
            return entry.timestamp == timestamp && entry.message == message;
        });

        // If the log entry is found, return it
        if (it != logs_.end()) {
            return *it;
        }

        // Otherwise, return an empty LogEntry object
        return {};
    }

    // Persists the log collection to disk periodically
    void persistLogs() {
        // Open a file stream for writing
        std::ofstream ofs("log.txt", std::ios::out | std::ios::app);

        if (ofs) {
            // Write each log entry to the file stream
            for (const auto& entry : logs_) {
                ofs << entry.timestamp << " " << entry.message << " " << static_cast<int>(entry.level) << "\n";
            }
        }
    }

    // Deallocates all allocated memory
    ~LogManager() {
        // Clear the vector of logs
        logs_.clear();

        // Release the memory used by the log entries
        std::for_each(logs_.begin(), logs_.end(), [](auto& entry) {
            entry.timestamp = {};
            entry.message = {};
            entry.level = LogLevel::INFO;
        });
    }

private:
    // Vector to store the log entries
    std::vector<LogEntry> logs_;

    // Maximum allowed length of timestamps and messages
    size_t max_timestamp_len_;
    size_t max_message_len_;

    // Minimum acceptable level for log entries
    LogLevel min_level_;
};
