using namespace std;

struct AttackStrategy {
    long offset;
    int key;
    string label;
    timestamp timestamp;
};

class AttackStrategyManager {
private:
    map<int, AttackStrategy*> uniqueKeys;
    map<string, AttackStrategy*> uniqueLabels;
    set<timestamp> uniqueTimestamps;
    int maxUniqueKeys;
    int maxUniqueLabels;
    int maxUniqueTimestamps;
    customMemoryManager memoryManager;

public:
    AttackStrategyManager(int maxUniqueKeys, int maxUniqueLabels, int maxUniqueTimestamps, customMemoryManager memoryManager) {
        this->maxUniqueKeys = maxUniqueKeys;
        this->maxUniqueLabels = maxUniqueLabels;
        this->maxUniqueTimestamps = maxUniqueTimestamps;
        this->memoryManager = memoryManager;
    }

    ~AttackStrategyManager() {
        for (auto& key : uniqueKeys) {
            delete key.second;
        }
        for (auto& label : uniqueLabels) {
            delete label.second;
        }
    }

    bool allocateRecord(int type, string label, long offset, int cooldown, timestamp timestamp, callback callback = nullptr) {
        if (uniqueKeys.size() == maxUniqueKeys || uniqueLabels.size() == maxUniqueLabels || uniqueTimestamps.size() == maxUniqueTimestamps) {
            return false; // reached maximum number of unique keys, labels, and timestamps
        }

        if (uniqueKeys.find(type) != uniqueKeys.end()) {
            return false; // duplicate type found
        }

        if (uniqueLabels.find(label) != uniqueLabels.end()) {
            return false; // duplicate label found
        }

        if (uniqueTimestamps.find(timestamp) != uniqueTimestamps.end()) {
            return false; // duplicate timestamp found
        }

        auto record = new AttackStrategy{};
        record->type = type;
        record->label = label;
        record->offset = offset;
        record->cooldown = cooldown;
        record->timestamp = timestamp;

        uniqueKeys[type] = record;
        uniqueLabels[label] = record;
        uniqueTimestamps.insert(record->timestamp);

        if (callback) {
            callback(*record);
        }

        return true;
    }

    bool deallocateRecord(AttackStrategy* record) {
        uniqueKeys.erase(record->type);
        uniqueLabels.erase(record->label);
        uniqueTimestamps.erase(record->timestamp);

        delete record;

        return true;
    }

    bool addAttackStrategy(int type, string label, long offset, int cooldown) {
        timestamp timestamp = generateTimestamp();
        if (!allocateRecord(type, label, offset, cooldown, timestamp)) {
            return false; // failed to allocate record
        }

        return true;
    }

    bool removeAttackStrategy(int type, string label) {
        auto record = uniqueKeys[type];
        if (!record || record->label != label) {
            return false; // strategy not found
        }

        deallocateRecord(record);

        return true;
    }

    AttackStrategy* getAttackStrategy(int type, string label) {
        auto record = uniqueKeys[type];
        if (!record || record->label != label) {
            return nullptr; // strategy not found
        }

        return record;
    }

private:
    timestamp generateTimestamp() {
        // generate a random timestamp within the specified range, ensuring no duplicates
        while (true) {
            timestamp = rand() % MAX_TIMESTAMP + MIN_TIMESTAMP;
            if (uniqueTimestamps.find(timestamp) == uniqueTimestamps.end()) {
                break; // found a new unique timestamp
            }
        }
    }
};
