// In-memory data structure to store reservations and attacks
class SystemData {
public:
    // Add a new reservation entry
    void addReservation(const std::string& seatId, unsigned int eventKey, bool isAvailable) {
        reservations.push_back({seatId, eventKey, isAvailable});
    }

    // Remove a reservation entry
    void removeReservation(unsigned int index) {
        reservations.erase(reservations.begin() + index);
    }

    // Check if a seat is available for a specific event
    bool isSeatAvailable(const std::string& seatId, unsigned int eventKey) {
        auto it = std::find_if(reservations.begin(), reservations.end(), [seatId, eventKey](const Reservation& r) {
            return r.seatId == seatId && r.eventKey == eventKey;
        });

        if (it != reservations.end()) {
            return it->isAvailable;
        } else {
            return false;
        }
    }

    // Query reservation entries within a specified key range
    std::vector<Reservation> queryReservations(unsigned int minKey, unsigned int maxKey) {
        std::vector<Reservation> result;
        for (const auto& r : reservations) {
            if (r.eventKey >= minKey && r.eventKey <= maxKey) {
                result.push_back(r);
            }
        }
        return result;
    }

    // Add a new attack to the collection
    void addAttack(const std::string& name, float strength) {
        attacks.push_back({name, strength});
    }

    // Remove an attack from the collection
    void removeAttack(unsigned int index) {
        attacks.erase(attacks.begin() + index);
    }

    // Retrieve an attack by its name
    Attack getAttack(const std::string& name) {
        auto it = std::find_if(attacks.begin(), attacks.end(), [name](const Attack& a) {
            return a.name == name;
        });

        if (it != attacks.end()) {
            return *it;
        } else {
            return {};
        }
    }

private:
    struct Reservation {
        std::string seatId;
        unsigned int eventKey;
        bool isAvailable;
    };

    // In-memory data structure to store reservations
    std::vector<Reservation> reservations;

    // In-memory data structure to store attacks
    std::vector<Attack> attacks;
};

// Class for handling system operations and managing memory usage
