// Define the record structure
typedef struct {
    long offset;
    int key;
    double timestamp;
} record_t;

// Function to dynamically allocate and manage memory for an array of records
void dynamic_record_array(size_t num_records, size_t *memory_usage) {
    // Initialize the arrays for long offset values and int keys
    long *offset_values = calloc(num_records, sizeof(long));
    int *key_values = calloc(num_records, sizeof(int));

    // Populate the records with random values and current system time
    for (size_t i = 0; i < num_records; i++) {
        offset_values[i] = rand() % 1000000;
        key_values[i] = rand() % 1000000;
        record_t *record = (record_t *)calloc(1, sizeof(record_t));
        record->offset = offset_values[i];
        record->key = key_values[i];
        record->timestamp = time(NULL);
        // Add the record to a list or another data structure for easy management
    }

    // Track total memory usage in bytes and log it using an external logging library
    *memory_usage = sizeof(long) * num_records + sizeof(int) * num_records;
    printf("Total memory usage: %zu\n", *memory_usage);

    // Implement a mechanism to periodically verify and compact memory usage
    size_t compacted_size = 0;
    for (size_t i = 0; i < num_records; i++) {
        if (offset_values[i] == offset_values[i+1]) {
            // If two adjacent records have the same offset value, compact them into a single record
            compacted_size++;
            offset_values[i] = 0;
            key_values[i] = 0;
        }
    }

    // Deallocate all allocated memory and reset the arrays to their original size
    free(offset_values);
    free(key_values);
    offset_values = calloc(num_records, sizeof(long));
    key_values = calloc(num_records, sizeof(int));

    // Implement a clean interface for deallocating all allocated memory
    void deallocate() {
        free(offset_values);
        free(key_values);
    }
}
```
In this implementation, the `dynamic_record_array` function takes two arguments: `num_records`, which is the number of records to be allocated, and `memory_usage`, which is a pointer to a variable where the total memory usage in bytes will be stored. The function first initializes two arrays for long offset values and int keys, then populates each record with random values and the current system time. The `record_t` structure is defined as follows:
