    if (query.type == 4) {
        struct hostent* h = gethostbyname(query.hostname);
        if (h == NULL) {
            // handle DNS error
            return;
        }
        addr->sin_family = AF_INET;
        addr->sin_port = htons(53);
        addr->sin_addr.s_addr = htonl(INADDR_ANY);
    } else if (query.type == 6) {
        struct hostent* h = gethostbyname2(query.hostname, AF_INET6);
        if (h == NULL) {
            // handle DNS error
            return;
        }
        addr->sin_family = AF_INET6;
        addr->sin_port = htons(53);
        memcpy(&addr->sin_addr, h->h_addr_list[0], sizeof(struct in6_addr));
    } else {
        // handle invalid query type
        return;
    }
}

