// Dynamic collection of tasks with efficient insertion, deletion, and retrieval based on title and deadline
struct task {
	char *title; // Title of the task
	struct timeval deadline; // Deadline of the task
	int priority; // Priority level of the task
};

// Data structure to store tasks and track total memory usage
struct task_collection {
	struct task **tasks; // Array of pointers to tasks
	size_t num_tasks; // Number of tasks in the collection
	size_t max_tasks; // Maximum number of tasks that can be stored
	size_t mem_usage; // Total memory usage in bytes
};

// Function to initialize a task collection with a given maximum number of tasks
void init_task_collection(struct task_collection *tc, size_t max_tasks) {
	tc->tasks = malloc(sizeof(struct task *) * max_tasks);
	tc->num_tasks = 0;
	tc->max_tasks = max_tasks;
	tc->mem_usage = 0;
}

// Function to insert a new task into the task collection
int insert_task(struct task_collection *tc, char *title, struct timeval deadline, int priority) {
	if (tc->num_tasks == tc->max_tasks) { // Check if maximum number of tasks has been reached
		return -1;
	}
	struct task *new_task = malloc(sizeof(struct task));
	new_task->title = title;
	new_task->deadline = deadline;
	new_task->priority = priority;
	tc->tasks[tc->num_tasks++] = new_task;
	tc->mem_usage += sizeof(struct task); // Update total memory usage
	return 0;
}

// Function to delete a task from the task collection based on its title
int delete_task(struct task_collection *tc, char *title) {
	size_t i;
	for (i = 0; i < tc->num_tasks; i++) { // Find the task with the given title
		if (!strcmp(tc->tasks[i]->title, title)) {
			break;
		}
	}
	if (i == tc->num_tasks) { // Check if the task was not found
		return -1;
	}
	free(tc->tasks[i]); // Free the task's memory
	tc->num_tasks--; // Decrement the number of tasks in the collection
	tc->mem_usage -= sizeof(struct task); // Update total memory usage
	if (i < tc->num_tasks) { // Shift the remaining tasks to fill the gap
		memmove(&tc->tasks[i], &tc->tasks[i+1], (tc->num_tasks - i) * sizeof(struct task));
	}
	return 0;
}

// Function to retrieve a task from the task collection based on its title
struct task *get_task(struct task_collection *tc, char *title) {
	size_t i;
	for (i = 0; i < tc->num_tasks; i++) { // Find the task with the given title
		if (!strcmp(tc->tasks[i]->title, title)) {
			return tc->tasks[i];
		}
	}
	return NULL;
}

// Function to sort tasks in the task collection based on their deadlines
void sort_tasks(struct task_collection *tc) {
	qsort(tc->tasks, tc->num_tasks, sizeof(struct task *), compare_deadlines); // Sort tasks based on deadlines
}

// Function to update the maximum length of titles and acceptable range of priority levels in the task collection
void update_task_collection_params(struct task_collection *tc, size_t max_titles_len, int min_priority, int max_priority) {
	if (max_titles_len > 0) { // Update maximum length of titles if provided
		tc->max_tasks = (size_t)((double)tc->num_tasks * (double)max_titles_len / (double)strlen(tc->tasks[0]->title));
	}
	if (min_priority > 0 || max_priority < 10) { // Update acceptable range of priority levels if provided
		tc->min_priority = min_priority;
		tc->max_priority = max_priority;
	}
}

// Function to retrieve all tasks meeting or exceeding a given priority level from the task collection
struct task **get_tasks_by_priority(struct task_collection *tc, int min_priority) {
	size_t i, j = 0; // Initialize variables for iteration and counting
	for (i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection
		if (tc->tasks[i]->priority >= min_priority) { // Check if the task meets or exceeds the given priority level
			j++; // Increment the number of tasks meeting the priority level criterion
		}
	}
	struct task **filtered_tasks = malloc(sizeof(struct task *) * j); // Allocate memory for the filtered tasks
	j = 0; // Reset the iteration variable
	for (i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection again
		if (tc->tasks[i]->priority >= min_priority) { // Check if the task meets or exceeds the given priority level
			filtered_tasks[j++] = tc->tasks[i]; // Add the task to the filtered task array
		}
	}
	return filtered_tasks; // Return the filtered task array
}

// Function to retrieve all tasks due within a given time frame from the task collection
struct task **get_tasks_by_deadline(struct task_collection *tc, struct timeval deadline) {
	size_t i, j = 0; // Initialize variables for iteration and counting
	for (i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection
		if (compare_deadlines(&tc->tasks[i]->deadline, &deadline) <= 0) { // Check if the task's deadline is due within the given time frame
			j++; // Increment the number of tasks meeting the deadline criterion
		}
	}
	struct task **filtered_tasks = malloc(sizeof(struct task *) * j); // Allocate memory for the filtered tasks
	j = 0; // Reset the iteration variable
	for (i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection again
		if (compare_deadlines(&tc->tasks[i]->deadline, &deadline) <= 0) { // Check if the task's deadline is due within the given time frame
			filtered_tasks[j++] = tc->tasks[i]; // Add the task to the filtered task array
		}
	}
	return filtered_tasks; // Return the filtered task array
}

// Function to retrieve all tasks overdue from the task collection
struct task **get_overdue_tasks(struct task_collection *tc) {
	size_t i, j = 0; // Initialize variables for iteration and counting
	for (i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection
		if (compare_deadlines(&tc->tasks[i]->deadline, &current_time) <= 0) { // Check if the task's deadline is overdue
			j++; // Increment the number of tasks meeting the overdue criterion
		}
	}
	struct task **overdue_tasks = malloc(sizeof(struct task *) * j); // Allocate memory for the overdue tasks
	j = 0; // Reset the iteration variable
	for (i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection again
		if (compare_deadlines(&tc->tasks[i]->deadline, &current_time) <= 0) { // Check if the task's deadline is overdue
			overdue_tasks[j++] = tc->tasks[i]; // Add the task to the overdue task array
		}
	}
	return overdue_tasks; // Return the overdue task array
}

// Function to update the logging mechanism in the task collection based on changes in the collection
void update_logging(struct task_collection *tc, int log_level) {
	switch (log_level) {
		case 1: // Log all inserts and deletions
			tc->log_level = log_level;
			break;
		case 2: // Log all updates and inserts
			tc->log_level = log_level;
			break;
		default: // No logging for the task collection
			tc->log_level = log_level;
	}
}

// Function to save the contents of the task collection to a file
void save_task_collection(struct task_collection *tc, char *filepath) {
	FILE *fp = fopen(filepath, "wb"); // Open the file for writing in binary mode
	if (fp == NULL) { // Check if the file could not be opened
		return;
	}
	fwrite(&tc->num_tasks, sizeof(size_t), 1, fp); // Write the number of tasks to the file
	for (size_t i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection
		fwrite(&tc->tasks[i]->title, sizeof(char), strlen(tc->tasks[i]->title) + 1, fp); // Write the task title to the file
		fwrite(&tc->tasks[i]->deadline, sizeof(struct timeval), 1, fp); // Write the task deadline to the file
		fwrite(&tc->tasks[i]->priority, sizeof(int), 1, fp); // Write the task priority level to the file
	}
	fclose(fp); // Close the file
}

// Function to load the contents of a saved task collection from a file
void load_task_collection(struct task_collection *tc, char *filepath) {
	FILE *fp = fopen(filepath, "rb"); // Open the file for reading in binary mode
	if (fp == NULL) { // Check if the file could not be opened
		return;
	}
	fread(&tc->num_tasks, sizeof(size_t), 1, fp); // Read the number of tasks from the file
	for (size_t i = 0; i < tc->num_tasks; i++) { // Iterate through the tasks in the collection
		char *title = malloc(sizeof(char) * MAX_TITLE_LENGTH); // Allocate memory for the task title
