		fread(&deadline, sizeof(struct timeval), 1, fp); // Read the task deadline from the file
		fread(&priority, sizeof(int), 1, fp); // Read the task priority level from the file
		insert_task(tc, title, deadline, priority); // Insert the task into the collection
	}
	fclose(fp); // Close the file
}

// Function to compare two time values based on their deadlines
int compare_deadlines(struct timeval *t1, struct timeval *t2) {
	if (t1->tv_sec < t2->tv_sec) { // Check if the first time value is before the second one
		return -1;
	} else if (t1->tv_sec > t2->tv_sec) { // Check if the first time value is after the second one
		return 1;
	} else { // If the two time values have the same seconds part
		if (t1->tv_usec < t2->tv_usec) { // Check if the first time value has a smaller microseconds part
			return -1;
		} else if (t1->tv_usec > t2->tv_usec) { // Check if the first time value has a larger microseconds part
			return 1;
		} else { // If the two time values have the same deadline
			return 0;
		}
	}
