// Function to allocate memory for a variable number of geometries
geometry_t* allocate_geometries(int num_geometries) {
    // Calculate the total size of memory needed to store all geometries
    int total_size = num_geometries * sizeof(geometry_t);

    // Allocate memory for the geometries and their associated data
    geometry_t* geometries = (geometry_t*)malloc(total_size);
    if (!geometries) {
        fprintf(stderr, "Failed to allocate memory for %d geometries\n", num_geometries);
        return NULL;
    }

    // Initialize the geometry structures and calculate the x, y, and z coordinates
    int i = 0;
    while (i < num_geometries) {
        geometry_t* current_geometry = &geometries[i];
        current_geometry->x = i / 100;
        current_geometry->y = strlen(current_geometry->label) + i;
        current_geometry->z = i & 255;
        i++;
    }

    // Return a pointer to the allocated memory
    return geometries;
}

// Function to deallocate all allocated memory for a variable number of geometries
void deallocate_geometries(geometry_t* geometries, int num_geometries) {
    // Free the memory for the geometry structures and their associated data
    free(geometries);
}
