// Define the record structure
typedef struct Record {
    int key;
    float offset;
    double sqrt_key;
} Record;

// Define the memory pool for small objects
#define POOL_SIZE 1024
static char pool[POOL_SIZE];
static size_t pool_index = 0;

// Function to allocate a new record from the memory pool
Record* allocate_record() {
    // Check if there is enough space in the pool for a new record
    if (pool_index + sizeof(Record) > POOL_SIZE) {
        // Allocate a new block of memory using malloc
        Record* new_block = (Record*)malloc(POOL_SIZE);
        // Add the new block to the pool
        memcpy(&pool[pool_index], new_block, POOL_SIZE - pool_index);
        free(new_block);
    }
    // Get a pointer to the next available memory in the pool
    Record* record = (Record*)&pool[pool_index];
    // Increment the index for the next allocation
    pool_index += sizeof(Record);
    return record;
}

// Function to deallocate a record from the memory pool
void deallocate_record(Record* record) {
    // Check if the record is in the pool
    if (record >= &pool[0] && record < &pool[POOL_SIZE]) {
        // Decrement the index for the next allocation
        pool_index -= sizeof(Record);
        memcpy(&record, &pool[pool_index], POOL_SIZE - pool_index);
    } else {
        // Free the record using free
        free(record);
    }
}

