            continue;
        }
        if (key > INT_MAX) {
            // Handle the case where the key is too large
            printf("Warning: Key %d exceeds maximum value.\n", key);
            continue;
        }
        records[i]->offset = (float)key / 10.0f;
        records[i]->sqrt_key = sqrt((double)key);
    }
    // Handle memory allocation errors and deallocate the records when they are no longer needed
