// Define structure for geometry data
typedef struct {
    double x, y, z;
    char *label;
} geometry_t;

// Define structure for record data
typedef struct {
    long offset;
    unsigned int key;
    geometry_t geometry;
} record_t;

// Define function to dynamically allocate memory for multiple interdependent data structures
void alloc_memory(record_t **records, size_t num_records) {
    // Calculate total number of bytes needed for all records
    size_t total_bytes = sizeof(record_t) * num_records;

    // Allocate memory for record array and geometry objects
    record_t *records = (record_t *)malloc(total_bytes);

    // Initialize coordinates based on key and label
    for (size_t i = 0; i < num_records; ++i) {
        records[i].geometry.x = records[i].key / 100.0;
        records[i].geometry.y = strlen(records[i].label) + records[i].key;
        records[i].geometry.z = records[i].key & 255;
    }

    // Sort records by offset values in ascending order
    qsort(records, num_records, sizeof(record_t), compare_offsets);

    // Handle edge cases for empty offset array or arrays with duplicate offset values
    if (num_records == 0) {
        free(records);
        return;
    } else if (num_records > 1 && records[0].offset == records[1].offset) {
        // Maintain original order of insertion in case of ties
        for (size_t i = 1; i < num_records; ++i) {
            if (records[i].offset != records[i - 1].offset) {
                break;
            } else {
                records[i].geometry.x += 0.001;
                records[i].geometry.y += 0.001;
                records[i].geometry.z += 1;
            }
        }
    }

    // Free memory for all allocated records and geometry objects upon completion
    free(records);
}

// Define function to deallocate all allocated memory
void dealloc_memory() {
