    double x;
    double y;
    double z;
    time_t timestamp;
} geometry_t;

// Function to allocate memory for geometries
geometry_t* allocate_geometries(int num_geometries) {
    // Allocate memory for the geometry array
    geometry_t *geometries = (geometry_t*) malloc(num_geometries * sizeof(geometry_t));

    if (geometries == NULL) {
        fprintf(stderr, "Failed to allocate memory for geometries\n");
        return NULL;
    }

    // Initialize the geometry array
    for (int i = 0; i < num_geometries; i++) {
        geometries[i].id = i;
        geometries[i].label = malloc(10 * sizeof(char));
        sprintf(geometries[i].label, "Geometry %d", i);
        geometries[i].x = (double) i / 100.0;
        geometries[i].y = strlen(geometries[i].label) + i;
        geometries[i].z = (unsigned char) i & 255;
        geometries[i].timestamp = time(NULL);
    }

    return geometries;
}

// Function to deallocate memory for geometries
void deallocate_geometries(geometry_t *geometries, int num_geometries) {
