        if ($pid) {
            $logger->debug('Configuration update process started');
        } else {
            $logger->debug('Child process starting');
            $updateConfig($config);
            $logger->debug('Child process ended');
            exit(0);
        }
    }

    // Load the configuration from the database if enabled
