        $query = 'SELECT name, value FROM config';
        $stmt = $db->prepare($query);
        $stmt->execute();
        $result = $stmt->fetchAll(PDO::FETCH_ASSOC);
        foreach ($result as $row) {
            $config[$row['name']] = $row['value'];
        }
    }
} catch (Exception $e) {
