// Initialize the dynamic array with a specified size
void init_records(size_t size) {
  pthread_mutex_lock(&mutex);
  // Allocate memory for the dynamic array
  records = (record_t**)malloc(sizeof(record_t*) * size);
  // Initialize each element of the dynamic array to NULL
  for (size_t i = 0; i < size; i++) {
    records[i] = NULL;
  }
  pthread_mutex_unlock(&mutex);
}

// Add a new record to the dynamic array
void add_record(int key, char status, const char* string) {
  // Allocate memory for the record using the custom allocator
  record_t* new_record = (record_t*)my_malloc(sizeof(record_t));
  // Initialize the integer key and status indicator for the record
  new_record->key = key;
  new_record->status = status;
  // Allocate memory for the string using the string pool manager
  size_t strlen = strlen(string);
  char* str = (char*)string_pool_malloc(strlen + 1);
  memcpy(str, string, strlen);
  new_record->string = str;
  // Add the record to the dynamic array
  pthread_mutex_lock(&mutex);
  size_t index = get_free_index();
  records[index] = new_record;
  pthread_mutex_unlock(&mutex);
}

// Get a free index in the dynamic array
size_t get_free_index() {
  for (size_t i = 0; i < MAX_RECORDS; i++) {
    if (records[i] == NULL) {
      return i;
    }
  }
  // Handle out-of-memory conditions by returning -1
  return -1;
}

// Set the integer value of a record to a random value within a specified range
void set_record_key(size_t index, int min, int max) {
  pthread_mutex_lock(&mutex);
  if (records[index] == NULL) {
    // Handle invalid index by returning
    return;
  }
  int key = rand() % (max - min + 1) + min;
  records[index]->key = key;
  pthread_mutex_unlock(&mutex);
}

// Free all memory allocated for the dynamic array and reset it to its initial state
void free_records() {
  pthread_mutex_lock(&mutex);
  // Iterate through each element of the dynamic array and free any allocated memory
  for (size_t i = 0; i < MAX_RECORDS; i++) {
    if (records[i] != NULL) {
      string_pool_free(records[i]->string);
      free(records[i]);
    }
  }
  // Reset the dynamic array to its initial state
  records = NULL;
  pthread_mutex_unlock(&mutex);
}
