    config->max_value = 10.0;
    config->min_id = 1;
    config->max_id = 10;
    for (int i = 0; i < 4; i++) {
        config->status_flags[i] = 'A';
    }
}

Transaction *allocateTransactions(int num_transactions, Config *config) {
    Transaction *transactions = NULL;
    size_t alloc_size = sizeof(Transaction) * num_transactions;
    transactions = malloc(alloc_size);
    if (transactions == NULL) {
        fprintf(stderr, "Failed to allocate memory for %d transactions\n", num_transactions);
        return NULL;
    }

    // Initialize the transaction records with random values within the configured range
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].value = (double) rand() / RAND_MAX * (config->max_value - config->min_value) + config->min_value;
        transactions[i].id = (short) rand() % (config->max_id - config->min_id + 1) + config->min_id;
        transactions[i].status = config->status_flags[rand() % 4];
    }

    return transactions;
}

void freeTransactions(Transaction *transactions, int num_transactions) {
    free(transactions);
}

