void initialize_log(struct log_entry** log, size_t capacity) {
    *log = (struct log_entry*)malloc(capacity * sizeof(struct log_entry));
    if (*log == NULL) {
        fprintf(stderr, "Failed to allocate memory for log\n");
        return;
    }
}

void free_log(struct log_entry** log) {
    free(*log);
    *log = NULL;
}

bool add_data_entry(struct data_entry* entry, struct log_entry** log, size_t capacity) {
    if (capacity == 0 || *log == NULL) {
        return false;
    }

    // Check if we need to expand the log array
    if ((*log)->size + 1 >= capacity) {
        size_t new_capacity = capacity << 1;
        struct log_entry* new_log = (struct log_entry*)realloc(*log, new_capacity * sizeof(struct log_entry));
        if (new_log == NULL) {
            fprintf(stderr, "Failed to reallocate memory for log\n");
            return false;
        }
        *log = new_log;
    }

    // Add the data entry to the log array
    (*log)[(*log)->size].data = entry;
    (*log)[(*log)->size].timestamp = entry->timestamp;
    (*log)[(*log)->size].message = entry->message;
    (*log)[(*log)->size].packet = NULL;
    (*log)->size++;

