#include <time.h>

// Define a custom allocator to optimize memory usage and minimize fragmentation
struct allocator {
    size_t size;
    void *buffer;
};

typedef struct record {
    int key;
} record;

void init(long offset, int length) {
    // Input validation
    if (offset < 0 || length <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Dynamically allocate memory for the offset array
    long *offset_array = malloc(length * sizeof(long));
    if (!offset_array) {
        printf("Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        offset_array[i] = rand() % (offset * 2 + 1) - offset;
    }

    // Dynamically allocate memory for the key array
    int *key_array = malloc(length * sizeof(int));
    if (!key_array) {
        printf("Failed to allocate memory for key array\n");
        return;
    }

    // Initialize the key array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        key_array[i] = rand() % (length * 2 + 1) - length;
    }

    // Dynamically allocate memory for the record array
    struct allocator alloc;
    alloc.size = sizeof(record) * length;
    alloc.buffer = malloc(alloc.size);
    if (!alloc.buffer) {
        printf("Failed to allocate memory for record array\n");
        return;
    }

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        ((struct record *)alloc.buffer)[i].key = rand() % (length * 2 + 1) - length;
    }
}

void cleanup(long offset, int length) {
    // Input validation
    if (offset < 0 || length <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Deallocate memory for the offset array
    long *offset_array = malloc(length * sizeof(long));
    if (!offset_array) {
        printf("Failed to deallocate memory for offset array\n");
        return;
    }
    free(offset_array);

    // Deallocate memory for the key array
    int *key_array = malloc(length * sizeof(int));
    if (!key_array) {
        printf("Failed to deallocate memory for key array\n");
        return;
    }
    free(key_array);

    // Deallocate memory for the record array
    struct allocator alloc;
    alloc.size = sizeof(record) * length;
    alloc.buffer = malloc(alloc.size);
    if (!alloc.buffer) {
        printf("Failed to deallocate memory for record array\n");
        return;
    }
    free(alloc.buffer);
}
```
