// Record structure with an integer key, a status indicator (char), and a dynamically allocated string
typedef struct {
    int key;
    char status;
    char* str;
} record_t;

// Dynamic array to store the records
struct {
    // Array of pointers to the records
    record_t** records;

    // Number of records in the array
    size_t num_records;

    // Maximum number of records that can be stored in the array
    size_t max_num_records;
} dynamic_array = {NULL, 0, 0};

void initialize_dynamic_array(size_t capacity) {
    // Allocate memory for the array of pointers to records
    dynamic_array.records = malloc(capacity * sizeof(record_t*));
    assert(dynamic_array.records != NULL);

    // Initialize the number of records in the array and the maximum capacity
    dynamic_array.num_records = 0;
    dynamic_array.max_num_records = capacity;
}

void resize_dynamic_array(size_t new_capacity) {
    if (new_capacity > dynamic_array.max_num_records) {
        // Double the current maximum capacity to avoid frequent resizing
        new_capacity *= 2;

        // Reallocate memory for the array of pointers to records
        record_t** new_records = realloc(dynamic_array.records, new_capacity * sizeof(record_t*));
        assert(new_records != NULL);

        // Update the maximum capacity and the number of records in the array
        dynamic_array.max_num_records = new_capacity;
        dynamic_array.num_records = 0;
    }
}

void add_record(int key, char status, const char* str) {
    // Check if the maximum capacity has been reached and resize the array if necessary
    if (dynamic_array.num_records == dynamic_array.max_num_records) {
        resize_dynamic_array(dynamic_array.max_num_records * 2);
    }

    // Allocate memory for the new record and initialize it
    record_t* new_record = malloc(sizeof(record_t));
    assert(new_record != NULL);

    new_record->key = key;
    new_record->status = status;
    new_record->str = my_strdup(str);

    // Add the new record to the end of the array
    dynamic_array.records[dynamic_array.num_records++] = new_record;
}
