// Background thread for periodically flushing records to the distributed caching system
typedef struct {
    // Indicates whether the background thread is running
    int running;

    // Lock to synchronize access to the background thread
    spin_lock_t lock;
} bg_thread_t;

void bg_thread(void* arg) {
    bg_thread_t* thread = (bg_thread_t*)arg;

    while (1) {
        if (!thread->running) {
            break;
        }

        // Acquire the lock to synchronize access to the background thread
        acquire_spin_lock(&thread->lock);

        // Periodically flush records to the distributed caching system
        int num_records = dynamic_array.num_records;
