#include <assert.h>

// Logging library for error reporting and monitoring performance metrics
typedef struct {
    // File descriptor for the logging file
    int fd;
} logger_t;

void initialize_logger(const char* log_file) {
    // Open the logging file in append mode
    logger.fd = open(log_file, O_WRONLY | O_CREAT, 0644);

    if (logger.fd < 0) {
        perror("Failed to open logging file");
        exit(1);
    }
}

