/*
 * Dynamic and scalable logging system for managing up to 1 billion log entries
 * with a 'char*' timestamp, 'char*' message, and 'int' severity level
 * Optimized for efficient memory usage, responsiveness under high load, and concurrent access from multiple threads
 */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

// Constants for logging severity levels and message length ranges
#define LOG_SEVERITY_MIN 0
#define LOG_SEVERITY_MAX 5
#define MESSAGE_LEN_MIN 10
#define MESSAGE_LEN_MAX 200

// Log entry structure
typedef struct log_entry {
    char* timestamp;
    char* message;
    int severity;
} log_entry;

// Arrays for storing long offset values, int keys, and record structures
long* offsets = NULL;
int* keys = NULL;
record** records = NULL;

// Lock for synchronizing access to the logging system
pthread_mutex_t lock;

/*
 * Function for allocating and initializing memory for the log arrays
 * Input: number of elements (n) for each array
 * Output: 0 on success, -1 on failure
 */
int init_log(size_t n) {
    // Allocate memory for the offset array
    offsets = (long*) malloc(sizeof(long) * n);
    if (offsets == NULL) {
        return -1;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % (LOG_SEVERITY_MAX - LOG_SEVERITY_MIN + 1) + LOG_SEVERITY_MIN;
    }

    // Allocate memory for the key array
    keys = (int*) malloc(sizeof(int) * n);
    if (keys == NULL) {
        free(offsets);
        return -1;
    }

    // Initialize the key array with random values within the specified range
    for (int i = 0; i < n; i++) {
        keys[i] = rand() % (MESSAGE_LEN_MAX - MESSAGE_LEN_MIN + 1) + MESSAGE_LEN_MIN;
    }

    // Allocate memory for the record array
    records = (record**) malloc(sizeof(record*) * n);
    if (records == NULL) {
        free(offsets);
        free(keys);
        return -1;
    }

    // Initialize each record structure with a single integer value
    for (int i = 0; i < n; i++) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Initialize the lock for synchronizing access to the logging system
    pthread_mutex_init(&lock, NULL);

    return 0;
}

/*
 * Function for adding a new log entry to the array
 * Input: timestamp (char*), message (char*), severity level (int)
 * Output: 0 on success, -1 on failure
 */
int add_log(char* timestamp, char* message, int severity) {
    // Acquire the lock for synchronizing access to the logging system
    pthread_mutex_lock(&lock);

    // Check if there is enough memory available for a new log entry
    if (offsets == NULL || keys == NULL || records == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Allocate memory for the new log entry
    long offset = rand() % (LOG_SEVERITY_MAX - LOG_SEVERITY_MIN + 1) + LOG_SEVERITY_MIN;
    int key = rand() % (MESSAGE_LEN_MAX - MESSAGE_LEN_MIN + 1) + MESSAGE_LEN_MIN;
    record* new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Initialize the new log entry with the given timestamp, message, and severity level
    new_record->timestamp = timestamp;
    new_record->message = message;
    new_record->severity = severity;

    // Add the new log entry to the array of records
    records[key] = new_record;

    // Release the lock for synchronizing access to the logging system
    pthread_mutex_unlock(&lock);

    return 0;
}

/*
 * Function for deleting a log entry from the array
 * Input: index (int) of the log entry to delete
 * Output: 0 on success, -1 on failure
 */
int delete_log(int index) {
    // Acquire the lock for synchronizing access to the logging system
    pthread_mutex_lock(&lock);

    // Check if the given index is valid
    if (index < 0 || index >= keys->size()) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Release the lock for synchronizing access to the logging system
    pthread_mutex_unlock(&lock);

    // Free the memory allocated to the log entry at the given index
    free(records[index]);

    // Remove the record from the array of records
    records.erase(keys[index]);

    return 0;
}

/*
 * Function for retrieving a log entry from the array
 * Input: index (int) of the log entry to retrieve
 * Output: pointer to the log entry structure, NULL on failure
 */
log_entry* get_log(int index) {
    // Acquire the lock for synchronizing access to the logging system
    pthread_mutex_lock(&lock);

    // Check if the given index is valid
    if (index < 0 || index >= keys->size()) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Release the lock for synchronizing access to the logging system
    pthread_mutex_unlock(&lock);

    // Return a pointer to the log entry structure at the given index
    return records[index];
}

/*
 * Function for retrieving all log entries in the array that match a specified time range, severity level, or keyword presence in messages
 * Input: start_time (char*), end_time (char*), severity (int), message_key (char*)
 * Output: pointer to an array of pointers to log entry structures, NULL on failure
 */
log_entry** get_logs(char* start_time, char* end_time, int severity, char* message_key) {
    // Acquire the lock for synchronizing access to the logging system
    pthread_mutex_lock(&lock);

    // Initialize an empty array of pointers to log entry structures
    log_entry** matching_logs = NULL;

    // Iterate through each record structure in the array
    for (int i = 0; i < keys->size(); i++) {
        // Check if the current record structure matches the specified time range, severity level, or keyword presence in messages
        if (records[i]->timestamp >= start_time && records[i]->timestamp <= end_time && records[i]->severity == severity && strstr(records[i]->message, message_key) != NULL) {
            // If it does, add the record structure to the array of pointers to log entry structures
            matching_logs = (log_entry**) realloc(matching_logs, sizeof(log_entry*) * (keys->size() + 1));
            if (matching_logs == NULL) {
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            matching_logs[i] = records[i];
        }
    }

    // Release the lock for synchronizing access to the logging system
    pthread_mutex_unlock(&lock);

    return matching_logs;
}
```
