using namespace std;

struct Attack {
    string name;
    double strength;
};

class DynamicAttackManager {
public:
    DynamicAttackManager(size_t maxNameLength, size_t minStrength, size_t maxStrength) :
        _maxNameLength(maxNameLength),
        _minStrength(minStrength),
        _maxStrength(maxStrength)
    { }

    void insertAttack(const string& name, double strength);
    void deleteAttack(const string& name);
    bool searchAttack(const string& name) const;
    Attack getRandomAttack() const;
    void updateParameters(size_t maxNameLength, size_t minStrength, size_t maxStrength);

private:
    size_t _maxNameLength;
    size_t _minStrength;
    size_t _maxStrength;
    unordered_map<string, Attack> _attacks;
    mutex _mutex;
    atomic<bool> _cooldown;
    chrono::steady_clock::time_point _lastAttackTime;
};

void DynamicAttackManager::insertAttack(const string& name, double strength) {
    if (name.length() > _maxNameLength || strength < _minStrength || strength > _maxStrength) {
        throw invalid_argument("Invalid attack parameters");
    }

    unique_lock<mutex> lock(_mutex);
    _attacks[name] = Attack{name, strength};
}

void DynamicAttackManager::deleteAttack(const string& name) {
    if (_attacks.find(name) == _attacks.end()) {
        throw invalid_argument("Attack not found");
    }

    unique_lock<mutex> lock(_mutex);
    _attacks.erase(name);
}

bool DynamicAttackManager::searchAttack(const string& name) const {
    return _attacks.find(name) != _attacks.end();
}

Attack DynamicAttackManager::getRandomAttack() const {
    unique_lock<mutex> lock(_mutex);
    if (_cooldown && chrono::steady_clock::now() - _lastAttackTime < chrono::seconds(9)) {
        return Attack(); // Return empty attack if cooldown is active
    }

    vector<string> names;
    for (const auto& [name, attack] : _attacks) {
        names.push_back(name);
    }

    random_device rd;
    mt19937 gen(rd());
    shuffle(names.begin(), names.end(), gen);

    string longestName = "";
    double highestStrength = 0.0;
    for (const auto& name : names) {
        if (_attacks[name].strength > highestStrength) {
            longestName = name;
            highestStrength = _attacks[name].strength;
        }
    }

    return Attack{longestName, highestStrength};
}

void DynamicAttackManager::updateParameters(size_t maxNameLength, size_t minStrength, size_t maxStrength) {
    _maxNameLength = maxNameLength;
    _minStrength = minStrength;
    _maxStrength = maxStrength;
}
