typedef struct {
    int id;
    char* content;
    time_t last_modified;
} document_t;

// Define a list data structure to store the documents
typedef struct {
    document_t** documents;
    size_t capacity;
    size_t count;
} document_list_t;

// Function to add a new document to the list
void add_document(document_list_t* list, int id, char* content) {
    // Check if the list is full
    if (list->count == list->capacity) {
        // If the list is full, double its capacity
        list->capacity *= 2;
        list->documents = realloc(list->documents, sizeof(document_t*) * list->capacity);
    }

    // Create a new document and add it to the list
    document_t* doc = malloc(sizeof(document_t));
    doc->id = id;
    doc->content = strdup(content);
    doc->last_modified = time(NULL);
    list->documents[list->count++] = doc;
}

// Function to update an existing document in the list
void update_document(document_list_t* list, int id, char* content) {
    // Search for the document with the given ID
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->documents[i]->id == id) {
            break;
        }
    }

    // If the document is found, update its content and timestamp
    if (i < list->count) {
        free(list->documents[i]->content);
        list->documents[i]->content = strdup(content);
        list->documents[i]->last_modified = time(NULL);
    } else {
        // If the document is not found, add a new one
        add_document(list, id, content);
    }
}

// Function to retrieve a document from the list by its ID
document_t* get_document(document_list_t* list, int id) {
    // Search for the document with the given ID
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->documents[i]->id == id) {
            break;
        }
    }

    // If the document is found, return it
    if (i < list->count) {
        return list->documents[i];
    } else {
        // If the document is not found, return NULL
        return NULL;
    }
}

// Function to delete a document from the list by its ID
void delete_document(document_list_t* list, int id) {
    // Search for the document with the given ID
    size_t i;
    for (i = 0; i < list->count; ++i) {
        if (list->documents[i]->id == id) {
            break;
        }
    }

    // If the document is found, delete it and shift the remaining documents left
    if (i < list->count) {
        free(list->documents[i]->content);
        --list->count;
        for (size_t j = i; j < list->count; ++j) {
            list->documents[j] = list->documents[j + 1];
