#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define data structures
typedef struct {
    unsigned int index;
    char buffer[256];
    time_t timestamp;
} data_point;

typedef struct {
    double* values;
    unsigned int* indices;
    char** buffers;
    data_point* points;
} memory_pool;

// Define memory pool functions
memory_pool* init_pool(int n) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) {
        return NULL;
    }

    // Allocate memory for values, indices, buffers, and points arrays
    pool->values = (double*)calloc(n, sizeof(double));
    pool->indices = (unsigned int*)calloc(n, sizeof(unsigned int));
    pool->buffers = (char**)calloc(n, sizeof(char*));
    pool->points = (data_point*)calloc(n, sizeof(data_point));

    // Initialize timestamp field for each point
    time_t now = time(NULL);
    for (int i = 0; i < n; i++) {
        pool->points[i].timestamp = now + rand() % 60;
    }

    return pool;
}

void free_pool(memory_pool* pool) {
    if (!pool) {
        return;
    }

    // Free memory allocated for values, indices, buffers, and points arrays
    free(pool->values);
    free(pool->indices);
    free(pool->buffers);
    free(pool->points);

    // Free the pool structure itself
    free(pool);
}

// Define memory management functions
int allocate_memory(memory_pool* pool, int n) {
    if (!pool || n < 0) {
        return -1;
    }

    // Check for available memory
    size_t mem_size = (n * sizeof(double)) + (n * sizeof(unsigned int)) +
                      (n * sizeof(char*)) + (n * sizeof(data_point));
    if (mem_size > pool->max_memory_kb) {
        return -2;
    }

    // Allocate memory for values, indices, buffers, and points arrays
    pool->values = realloc(pool->values, n * sizeof(double));
    pool->indices = realloc(pool->indices, n * sizeof(unsigned int));
    pool->buffers = realloc(pool->buffers, n * sizeof(char*));
    pool->points = realloc(pool->points, n * sizeof(data_point));

    // Initialize timestamp field for each point
    time_t now = time(NULL);
    for (int i = 0; i < n; i++) {
        pool->points[i].timestamp = now + rand() % 60;
    }

    return 0;
}

void deallocate_memory(memory_pool* pool) {
    if (!pool) {
        return;
    }

    // Free memory allocated for values, indices, buffers, and points arrays
    free(pool->values);
    free(pool->indices);
    free(pool->buffers);
    free(pool->points);
}
