    coll->capacity = capacity;
    coll->count = 0;
    coll->max_length = max_length;
}

// Insert a new item into the collection, growing the collection if necessary
static void item_collection_insert(struct item_collection *coll, const char *name, double value) {
    // Grow the collection if it is full
    if (coll->count == coll->capacity) {
        size_t new_capacity = coll->capacity * 2;
        struct item *new_items = realloc(coll->items, new_capacity * sizeof(struct item));
        assert(new_items != NULL);
        coll->items = new_items;
        coll->capacity = new_capacity;
    }

    // Add the new item to the collection
    coll->items[coll->count].name = malloc(strlen(name) + 1);
    strcpy(coll->items[coll->count].name, name);
    coll->items[coll->count].value = value;
    coll->count++;
}

// Delete an item from the collection by its index
static void item_collection_delete(struct item_collection *coll, size_t idx) {
    assert(idx < coll->count);
    free(coll->items[idx].name);
    memmove(&coll->items[idx], &coll->items[idx + 1], (coll->count - idx - 1) * sizeof(struct item));
    coll->count--;
}

// Find the longest string in an array of strings
static size_t find_longest_string(const char **strings, size_t count) {
    size_t longest = 0;
    for (size_t i = 0; i < count; i++) {
        if (strlen(strings[i]) > longest) {
            longest = strlen(strings[i]);
        }
    }
    return longest;
}

// Query the collection based on a substring match within item names
static struct item *item_collection_query(struct item_collection *coll, const char *substring) {
    struct item *matches = NULL;
    size_t count = 0;
    for (size_t i = 0; i < coll->count; i++) {
        if (strstr(coll->items[i].name, substring)) {
            matches[count++] = coll->items[i];
        }
    }
    return matches;
}

// Persist the collection to disk periodically to prevent data loss in case of a system crash
static void item_collection_persist(struct item_collection *coll) {
    // Write the collection to a temporary file
    FILE *temp_file = fopen("temp.dat", "wb");
    assert(temp_file != NULL);
    for (size_t i = 0; i < coll->count; i++) {
        fwrite(&coll->items[i], sizeof(struct item), 1, temp_file);
    }
    fclose(temp_file);

    // Replace the original file with the temporary one
    remove("item_collection.dat");
    rename("temp.dat", "item_collection.dat");
}

// Implement a system that allows the maximum length of names and the acceptable range of values stored in the `item` structures to be dynamically adjusted at runtime
static void item_collection_set_parameters(struct item_collection *coll, size_t max_length, double acceptable_range) {
    coll->max_length = max_length;
    coll->acceptable_range = acceptable_range;
}

// Handle edge cases such as very large or very small values gracefully, without introducing numerical instability or overflow conditions
static void item_collection_handle_edge_cases(struct item_collection *coll) {
    if (coll->count == 0) {
        return;
    }

    // Handle very large values by scaling them down to the acceptable range
    for (size_t i = 0; i < coll->count; i++) {
        if (coll->items[i].value > coll->acceptable_range) {
            coll->items[i].value = coll->acceptable_range;
        }
    }
}

// Handle a scenario where the input data stream is extremely large and arrives in chunks, potentially exceeding available memory limits
static void item_collection_process_stream(struct item_collection *coll, const char **strings, size_t count) {
    for (size_t i = 0; i < count; i++) {
        // Add the new item to the collection, growing it if necessary
        item_collection_insert(coll, strings[i], 0);

        // Check for memory exhaustion and process the input data in chunks
        size_t processed = 0;
        while (processed < coll->count) {
            struct item *items = &coll->items[processed];
            size_t batch_size = MIN(10000, coll->count - processed);
            for (size_t j = 0; j < batch_size; j++) {
                // Process the item and move on to the next one
                printf("Processing item %s with value %lf\n", items[j].name, items[j].value);
                processed++;
            }
        }
    }
}

// Ensure that the function can handle simultaneous read and write operations from multiple threads without causing data corruption or race conditions
static void item_collection_thread_safety(struct item_collection *coll) {
    // Use a mutex to protect the collection during writes
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Use a condition variable to signal between threads when new items are added or removed
    pthread_cond_t cv;
    pthread_cond_init(&cv, NULL);

    // Create a thread for each reader and writer
    size_t num_readers = 10;
    size_t num_writers = 5;
    pthread_t readers[num_readers];
    pthread_t writers[num_writers];
    for (size_t i = 0; i < num_readers; i++) {
        pthread_create(&readers[i], NULL, reader_thread, (void *)coll);
    }
    for (size_t i = 0; i < num_writers; i++) {
        pthread_create(&writers[i], NULL, writer_thread, (void *)coll);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < num_readers; i++) {
        pthread_join(readers[i], NULL);
    }
    for (size_t i = 0; i < num_writers; i++) {
        pthread_join(writers[i], NULL);
    }
}
