// Define the struct for temperature records
struct TemperatureRecord {
    int key;
    double weight;
    char* unit;
    int offset;
};

// Define the struct for user accounts
struct UserAccount {
    int id;
    char* username;
    char* password;
};

// Define the struct for JSON response
struct JsonResponse {
    char* message;
};

// Global variables
int total_memory = 0;
int num_records = 0;
int max_num_records = 10 * 1000 * 1000; // 10 million records
struct TemperatureRecord* temperature_records = NULL;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for a new record
void allocate_memory(struct TemperatureRecord* record) {
    pthread_mutex_lock(&memory_lock);
    total_memory += sizeof(struct TemperatureRecord);
    num_records++;
    temperature_records = realloc(temperature_records, num_records * sizeof(struct TemperatureRecord));
    memcpy(temperature_records + (num_records - 1), record, sizeof(struct TemperatureRecord));
    pthread_mutex_unlock(&memory_lock);
}

// Function to deallocate memory for a record
void deallocate_memory(int index) {
    pthread_mutex_lock(&memory_lock);
    total_memory -= sizeof(struct TemperatureRecord);
    num_records--;
    temperature_records = realloc(temperature_records, num_records * sizeof(struct TemperatureRecord));
    pthread_mutex_unlock(&memory_lock);
}

// Function to calculate the offset for a record
int calculate_offset(int key, double weight) {
    return key * 10 + (weight / 10);
}

// Function to sort records based on their offsets in descending order
void sort_records() {
    qsort(temperature_records, num_records, sizeof(struct TemperatureRecord), compare_offsets);
}

// Comparison function for sorting records based on their offsets
int compare_offsets(const void* record1, const void* record2) {
    return ((struct TemperatureRecord*)record2)->offset - ((struct TemperatureRecord*)record1)->offset;
}

// Function to compact memory by removing records that fall outside the specified percentile range of offsets
void compact_memory() {
    int percentile = 95; // adjust this value as needed
    int offset_threshold = calculate_offset(INT_MAX, 0) * percentile / 100;
    struct TemperatureRecord* record = temperature_records;
    while (record < temperature_records + num_records) {
        if (record->offset > offset_threshold) {
            deallocate_memory(record - temperature_records);
            break;
        }
        record++;
    }
}

// Function to update a user account
void update_account(struct UserAccount* account, char* username, char* password) {
    pthread_mutex_lock(&memory_lock);
    if (account != NULL) {
        strcpy(account->username, username);
        strcpy(account->password, password);
    } else {
        // Handle error condition: user account not found
    }
    pthread_mutex_unlock(&memory_lock);
}

// Function to create a new user account
