                    return 1;
                }
            } break;
        }
        free(request); // Free the JSON request structure
    }
}

// Read a JSON request from stdin and validate it
struct JsonRequest* read_json_request() {
    struct JsonRequest* request = malloc(sizeof(struct JsonRequest));
    if (request == NULL) {
        return NULL;
    }
    char line[1024];
    fgets(line, 1024, stdin); // Read JSON string from stdin
    if (line[strlen(line) - 1] != '\n') {
        free(request); // Free the structure and return NULL
        return NULL;
    }
    int len = strlen(line);
    char* json_string = malloc(len + 1);
    if (json_string == NULL) {
        free(request); // Free the structure and return NULL
        return NULL;
    }
    memcpy(json_string, line, len);
    json_string[len] = '\0';
    struct json_object* json_obj = json_tokener_parse(json_string);
    free(json_string); // Free the string and parse the JSON object
    if (json_obj == NULL) {
        return NULL;
    }
    request->temperature_unit = get_json_string(json_obj, "temperature_unit");
    request->weight = get_json_number(json_obj, "weight");
    request->sub_action = get_json_string(json_obj, "sub_action");
    if (request->sub_action != 'create' && request->sub_action != 'update' && request->sub_action != 'delete') {
        free(request); // Free the structure and return NULL
        return NULL;
    }
    if (request->sub_action == 'update' || request->sub_action == 'delete') {
        request->id = get_json_int(json_obj, "id");
        if (request->id < 0) {
            free(request); // Free the structure and return NULL
            return NULL;
        }
    }
    if (request->sub_action == 'create') {
        request->username = get_json_string(json_obj, "username");
        if (request->username == NULL) {
            free(request); // Free the structure and return NULL
            return NULL;
        }
        request->password = get_json_string(json_obj, "password");
        if (request->password == NULL) {
            free(request); // Free the structure and return NULL
            return NULL;
        }
    }
    json_object_put(json_obj); // Free the JSON object
    return request;
}

// Write a JSON response to stdout
void write_json_response(struct JsonResponse* response) {
    if (response == NULL) {
        printf("Error: failed to write JSON response\n");
        return;
    }
    char* json_string = json_object_to_json_string_ext(response, JSON_C_TO_STRING_PRETTY);
    if (json_string == NULL) {
        printf("Error: failed to convert JSON object to string\n");
        return;
    }
    printf("%s\n", json_string); // Write JSON string to stdout
}

// Get a string from a JSON object
char* get_json_string(struct json_object* obj, const char* name) {
    if (obj == NULL || name == NULL) {
        return NULL;
    }
    struct json_object* value = json_object_object_get(obj, name);
    if (value == NULL || json_object_get_type(value) != json_type_string) {
        return NULL;
    }
    const char* string = json_object_get_string(value);
    if (string == NULL) {
        return NULL;
    }
    int len = strlen(string);
    char* result = malloc(len + 1);
    if (result == NULL) {
        return NULL;
    }
    memcpy(result, string, len);
    result[len] = '\0';
    return result;
}

// Get a number from a JSON object
double get_json_number(struct json_object* obj, const char* name) {
    if (obj == NULL || name == NULL) {
        return NAN;
    }
    struct json_object* value = json_object_object_get(obj, name);
    if (value == NULL || json_object_get_type(value) != json_type_double) {
        return NAN;
    }
    return json_object_get_double(value);
}

// Get an integer from a JSON object
int get_json_int(struct json_object* obj, const char* name) {
    if (obj == NULL || name == NULL) {
        return -1;
    }
    struct json_object* value = json_object_object_get(obj, name);
    if (value == NULL || json_object_get_type(value) != json_type_int) {
        return -1;
    }
    return json_object_get_int(value);
}
