    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize each record with a unique random value within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand_range(value_min, value_max);
        records[i].key = &records[i].value;
        records[i].offset = -1;
    }

    // Use a hash table to detect duplicate values and ensure uniqueness of the random values
    int *hash_table = (int *)malloc(num_records * sizeof(int));
    if (!hash_table) {
        printf("Memory allocation failed\n");
        free(records);
        return NULL;
    }
    memset(hash_table, 0, num_records * sizeof(int));

    // Check for duplicates and regenerate the random value if necessary
