#include <ctime>
#include <unordered_map>

using namespace std;

struct LOG_RECORD {
    int logLevel;
    time_t timestamp;
    string sourceModule;
    string message;
    int errorCode;
};

class Logger {
private:
    vector<LOG_RECORD> records;
    mutex mtx;
    condition_variable condVar;
    bool isClearing = false;
    bool isEnabled = true;
    unordered_map<int, int> logLevelPolicies;

public:
    Logger() {
        // Initialize log level policies to defaults
        logLevelPolicies[LOG_EMERG] = LOG_EMERG;
        logLevelPolicies[LOG_ALERT] = LOG_ALERT;
        logLevelPolicies[LOG_CRIT] = LOG_CRIT;
        logLevelPolicies[LOG_ERR] = LOG_ERR;
        logLevelPolicies[LOG_WARNING] = LOG_WARNING;
        logLevelPolicies[LOG_NOTICE] = LOG_NOTICE;
        logLevelPolicies[LOG_INFO] = LOG_INFO;
        logLevelPolicies[LOG_DEBUG] = LOG_DEBUG;
    }

    // Add a new record to the list of records
    void addRecord(int logLevel, time_t timestamp, string sourceModule, string message, int errorCode) {
        // Check if logging is enabled
        if (!isEnabled) return;

        // Validate log level against policy
        if (logLevel < logLevelPolicies[LOG_EMERG] || logLevel > logLevelPolicies[LOG_DEBUG]) return;

        // Create new record
        LOG_RECORD record = {logLevel, timestamp, sourceModule, message, errorCode};

        // Lock mutex and add record to list
        lock_guard<mutex> guard(mtx);
        records.push_back(record);

        // Notify condition variable if clearing is in progress
        if (isClearing) condVar.notify_all();
    }

    // Get the number of records currently stored
    int getRecordCount() {
        lock_guard<mutex> guard(mtx);
        return records.size();
    }

    // Get a record from the list at a specified index
    LOG_RECORD* getRecord(int index) {
        lock_guard<mutex> guard(mtx);
        if (index < 0 || index >= records.size()) return nullptr;
        return &records[index];
    }

    // Clear the list of records
    void clearRecords() {
        // Lock mutex and flag for clearing
        lock_guard<mutex> guard(mtx);
        isClearing = true;

        // Clear list of records
        records.clear();

        // Unflag clearing and notify condition variable
        isClearing = false;
        condVar.notify_all();
    }

    // Enable or disable logging
    void setLoggingEnabled(bool enabled) {
        lock_guard<mutex> guard(mtx);
        isEnabled = enabled;
    }

    // Set the log level policy for a specific log level
    void setLogLevelPolicy(int logLevel, int policy) {
        lock_guard<mutex> guard(mtx);
        logLevelPolicies[logLevel] = policy;
    }
};

// Global logger instance
Logger g_logger;

// Main function
int main() {
    // Initialize logger
    g_logger.setLoggingEnabled(true);

    // Add a new record to the list of records
    g_logger.addRecord(LOG_INFO, time(nullptr), "main", "Hello world!", 0);

    // Get the number of records currently stored
    int count = g_logger.getRecordCount();
    cout << "Number of records: " << count << endl;

    // Get a record from the list at a specified index
    LOG_RECORD* record = g_logger.getRecord(0);
    if (record) {
        cout << "Log level: " << record->logLevel << endl;
        cout << "Timestamp: " << ctime(&record->timestamp) << endl;
        cout << "Source module: " << record->sourceModule << endl;
        cout << "Message: " << record->message << endl;
        cout << "Error code: " << record->errorCode << endl;
    } else {
        cout << "No records to display." << endl;
    }

    // Clear the list of records
    g_logger.clearRecords();

    return 0;
}']

