pub struct Logger {
    destinations: Vec<Box<dyn LogDestination>>,
    log_level: LogLevel,
    max_log_size: usize,
    rotate_policy: RotatePolicy,
}

impl Logger {
    pub fn new() -> Self {
        Self {
            destinations: Vec::new(),
            log_level: LogLevel::Info,
            max_log_size: 10 * 1024 * 1024, // 10 MB
            rotate_policy: RotatePolicy::Size(5 * 1024 * 1024), // 5 MB
        }
