    pub fn add_destination(&mut self, destination: Box<dyn LogDestination>) {
        self.destinations.push(destination);
    }

    pub fn set_log_level(&mut self, log_level: LogLevel) {
        self.log_level = log_level;
    }

    pub fn set_max_log_size(&mut self, max_log_size: usize) {
        self.max_log_size = max_log_size;
    }

    pub fn set_rotate_policy(&mut self, rotate_policy: RotatePolicy) {
        self.rotate_policy = rotate_policy;
    }

    pub fn log(&self, level: LogLevel, message: &str) {
        if self.log_level >= level {
            let mut messages = Vec::new();
            for destination in &self.destinations {
