                    LogLevel::Info => destination.log_info(&mut buf, message),
                    LogLevel::Debug => destination.log_debug(&mut buf, message),
                };
                if let Ok(()) = result {
                    messages.push((buf, level));
                }
            }
            self.rotate_logs(&messages);
        }
    }

