            }
            if let Some((max_count, _)) = self.rotate_policy.get_count() {
                // TODO: implement log rotation based on count
            }
        }
    }
}

pub trait LogDestination {
    fn log_error(&mut self, buf: &mut Vec<u8>, message: &str) -> Result<(), ()>;
    fn log_warn(&mut self, buf: &mut Vec<u8>, message: &str) -> Result<(), ()>;
    fn log_info(&mut self, buf: &mut Vec<u8>, message: &str) -> Result<(), ()>;
    fn log_debug(&mut self, buf: &mut Vec<u8>, message: &str) -> Result<(), ()>;
}

pub enum LogLevel {
    Error,
    Warn,
    Info,
    Debug,
}

pub enum RotatePolicy {
    Size(usize),
    Count(usize),
}

impl RotatePolicy {
    pub fn get_size(&self) -> Option<(usize, usize)> {
        match self {
            Self::Size(max_size) => Some((*max_size, 0)),
            Self::Count(max_count) => None,
        }
    }

    pub fn get_count(&self) -> Option<(usize, usize)> {
        match self {
            Self::Size(_) => None,
            Self::Count(max_count) => Some((*max_count, 0)),
        }
    }
}']

