Here's an example code block that demonstrates how to efficiently traverse a complex DOM structure using JavaScript:
```javascript
function traverseDOM(rootNode, callback) {
  // Use a queue to store nodes that need to be processed
  const queue = [];
  queue.push(rootNode);

  // Set up a list of class names and IDs to filter by
  const filters = [".my-class", "#my-id"];

  // Set up a list of custom attributes to filter by
  const attrFilters = {
    "data-my-attr": "my-value"
  };

  // Loop through the queue and process each node
  while (queue.length > 0) {
    // Get the next node from the queue
    let node = queue.shift();

    // Check if the node matches any of the filters
    if (filters.includes(node.classList.value)) {
      // If the node matches a filter, call the callback function with the node as an argument
      callback(node);
    }

    // If the node has child nodes, add them to the queue
    if (node.hasChildNodes()) {
      for (let i = 0; i < node.childNodes.length; i++) {
        queue.push(node.childNodes[i]);
      }
    }
  }
}
