// Thread-safe cache implementation using atomic operations
class ThemeCache {
    private Map<String, Bitmap> bitmapCache = new ConcurrentHashMap<>();
    private int maxSize; // maximum size of the cache

    public ThemeCache(int maxSize) {
        this.maxSize = maxSize;
    }

    public void addThemeBitmap(String themeId, Bitmap bitmap) {
        if (bitmap == null) {
            throw new IllegalArgumentException("Bitmap cannot be null");
        }

        bitmapCache.putIfAbsent(themeId, bitmap);
    }

    public Bitmap getThemeBitmap(String themeId) {
        return bitmapCache.get(themeId);
    }

    public void clear() {
        bitmapCache.clear();
    }
}

// Theme bitmap recycling policy based on usage patterns
class ThemeBitmapRecycler {
    private Map<String, Bitmap> bitmapCache = new ConcurrentHashMap<>();
    private int maxSize; // maximum size of the cache
    private long inactivityPeriodMs; // period after which a bitmap can be recycled (configurable)
    private ScheduledExecutorService executorService; // for scheduling bitmap recycling tasks

    public ThemeBitmapRecycler(int maxSize, int inactivityPeriodMs) {
        this.maxSize = maxSize;
        this.inactivityPeriodMs = inactivityPeriodMs;
        executorService = Executors.newScheduledThreadPool(1);
    }

    public void addThemeBitmap(String themeId, Bitmap bitmap) {
        if (bitmap == null) {
            throw new IllegalArgumentException("Bitmap cannot be null");
        }

        // Add the bitmap to the cache and schedule a recycling task after inactivity period
        bitmapCache.putIfAbsent(themeId, bitmap);
        executorService.schedule(() -> recycleThemeBitmap(themeId), inactivityPeriodMs, TimeUnit.MILLISECONDS);
    }

    public Bitmap getThemeBitmap(String themeId) {
        return bitmapCache.get(themeId);
    }

    public void clear() {
        bitmapCache.clear();
    }

    private void recycleThemeBitmap(String themeId) {
        // Check if the bitmap is still in use before recycling it
        if (!isThemeBitmapInUse(themeId)) {
            Bitmap bitmap = bitmapCache.remove(themeId);
            bitmap.recycle();
        }
    }

    private boolean isThemeBitmapInUse(String themeId) {
        // Check if any active requests still reference the bitmap
        return false; // TODO: Implement logic to check if a bitmap is in use or not
