// Configuration file location
#define CONFIG_FILE "config.txt"

// Default configuration values
#define DEFAULT_INCREMENT_FACTOR 100
#define DEFAULT_RANGE_MIN 1
#define DEFAULT_RANGE_MAX 1000

// Struct to hold the record data
typedef struct {
    int key;
    long offset;
} record;

// Function to read and parse the configuration file
int readConfigFile(int* increment, int* range_min, int* range_max) {
    // Open the configuration file for reading
    FILE *config = fopen(CONFIG_FILE, "r");
    if (config == NULL) {
        perror("Error opening config file");
        return 1;
    }

    // Parse the configuration file and extract the increment factor, range minimum, and maximum
    char line[256];
    while (fgets(line, sizeof(line), config)) {
        if (strncmp("INCREMENT_FACTOR", line, 15) == 0) {
            int tmp;
            if (sscanf(line + 16, "%d", &tmp) != 1) {
                fprintf(stderr, "Error parsing increment factor\n");
                return 1;
            }
            *increment = tmp;
        } else if (strncmp("RANGE_MIN", line, 9) == 0) {
            int tmp;
            if (sscanf(line + 10, "%d", &tmp) != 1) {
                fprintf(stderr, "Error parsing range minimum\n");
                return 1;
            }
            *range_min = tmp;
        } else if (strncmp("RANGE_MAX", line, 9) == 0) {
            int tmp;
            if (sscanf(line + 10, "%d", &tmp) != 1) {
                fprintf(stderr, "Error parsing range maximum\n");
                return 1;
            }
            *range_max = tmp;
        }
    }

    // Close the configuration file
    fclose(config);

    // Return success
    return 0;
}

// Function to allocate memory for the arrays
int allocateMemory(long** offsets, int** keys, record** records, int num_records) {
    // Calculate the size of each array
    long offset_size = num_records * sizeof(long);
    int key_size = num_records * sizeof(int);
    int record_size = num_records * sizeof(record);

    // Allocate memory for each array
    *offsets = (long*)malloc(offset_size);
    *keys = (int*)malloc(key_size);
    *records = (record*)malloc(record_size);

    // Check for memory allocation failures
    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Error allocating memory\n");
        return 1;
    }

    // Return success
    return 0;
}

// Function to initialize the arrays with random values based on the configuration file
int initArrays(long* offsets, int* keys, record* records, int num_records) {
    // Read and parse the configuration file
    int increment, range_min, range_max;
    if (readConfigFile(&increment, &range_min, &range_max)) {
        fprintf(stderr, "Error reading config file\n");
        return 1;
    }

    // Initialize the offset array with random values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % range_max + range_min;
    }

    // Initialize the key array with random values
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % range_max + range_min;
    }

    // Initialize the record array with the corresponding offset and key values
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i] * increment;
    }

    // Return success
    return 0;
}

// Function to calculate the average of an integer array
int avgArray(int* arr, int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return sum / size;
}

// Main function to handle the input and output of the program
int main() {
    // Initialize the configuration settings from the config file
    int increment, range_min, range_max;
    if (readConfigFile(&increment, &range_min, &range_max)) {
        fprintf(stderr, "Error reading config file\n");
        return 1;
    }

    // Allocate memory for the arrays
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;
    if (allocateMemory(&offsets, &keys, &records, 10000000)) {
        fprintf(stderr, "Error allocating memory\n");
        return 1;
    }

    // Initialize the arrays with random values based on the configuration file
    if (initArrays(offsets, keys, records, 10000000)) {
        fprintf(stderr, "Error initializing arrays\n");
        return 1;
    }

    // Read the list of integers from standard input and store them in an array
    int num_inputs = 0;
    while (scanf("%d", &records[num_inputs].key) == 1) {
        records[num_inputs].offset = rand() % range_max + range_min;
        num_inputs++;
    }

    // Find and print the largest integer in the array
    int largest = 0;
    for (int i = 0; i < num_inputs; i++) {
        if (records[i].key > largest) {
            largest = records[i].key;
        }
    }
    printf("Largest integer in the array: %d\n", largest);

    // Print the average of the input integers
    int sum = 0;
    for (int i = 0; i < num_inputs; i++) {
        sum += records[i].key;
    }
    printf("Average of the input integers: %d\n", sum / num_inputs);

    // Clean up memory
    free(offsets);
    free(keys);
    free(records);

    // Return success
    return 0;
}
