```C
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdio.h>

struct Record {
    int value;
};

typedef struct {
    long *offset_array;
    int *key_array;
    size_t count;
} Records;

Records *allocate_records(size_t count) {
    // Allocate memory for the two arrays
    long *offset_array = malloc(count * sizeof(*offset_array));
    int *key_array = malloc(count * sizeof(*key_array));
    if (offset_array == NULL || key_array == NULL) {
        return NULL;
    }

    // Initialize the arrays with random values within a specified range
    for (size_t i = 0; i < count; ++i) {
        offset_array[i] = rand() % 100;
        key_array[i] = rand() % 100;
    }

    // Allocate memory for the record array and initialize each record with a random value within a specified range
    Records *records = malloc(count * sizeof(*records));
    if (records == NULL) {
        free(offset_array);
        free(key_array);
        return NULL;
    }
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 100;
    }

    // Set the count of records and return the records array
    records->count = count;
    return records;
}

void deallocate_records(Records *records) {
    free(records->offset_array);
    free(records->key_array);
    free(records);
}
```
