// Structure to represent a sensor event
typedef struct {
    double temperature;
    char status;
    char* log_message;
} sensor_event;

// Function to dynamically allocate memory for an array of sensor events
sensor_event* read_json(const char* json_file) {
    // Open the JSON file
    FILE* fp = fopen(json_file, "r");
    if (fp == NULL) {
        printf("Error: failed to open JSON file\n");
        return NULL;
    }

    // Load the JSON data into a json_object
    json_object* root = json_object_from_file(json_file);
    if (root == NULL) {
        printf("Error: failed to parse JSON file\n");
        fclose(fp);
        return NULL;
    }

    // Get the number of sensor events in the JSON data
    int num_events = json_object_array_length(root);

    // Dynamically allocate memory for the array of sensor events
    sensor_event* events = (sensor_event*) malloc(num_events * sizeof(sensor_event));
    if (events == NULL) {
        printf("Error: failed to allocate memory for sensor events\n");
        json_object_put(root);
        fclose(fp);
        return NULL;
    }

    // Iterate through the JSON data and populate the array of sensor events
    for (int i = 0; i < num_events; i++) {
        json_object* event = json_object_array_get_idx(root, i);
        if (event == NULL) {
            printf("Error: failed to get JSON event %d\n", i);
            free(events);
            events = NULL;
            break;
        }

        // Get the temperature reading from the JSON data
        double temperature = json_object_get_double(json_object_object_get(event, "temperature"));
        if (temperature == -1.0) {
            printf("Error: failed to get temperature reading for event %d\n", i);
            free(events);
            events = NULL;
            break;
        }

        // Get the status flag from the JSON data
        char status = json_object_get_boolean(json_object_object_get(event, "status"));
        if (status == -1) {
            printf("Error: failed to get status for event %d\n", i);
            free(events);
            events = NULL;
            break;
        }

        // Get the log message from the JSON data
        json_object* log_message = json_object_object_get(event, "log_message");
        if (log_message == NULL) {
            printf("Error: failed to get log message for event %d\n", i);
            free(events);
            events = NULL;
            break;
        }

        // Populate the current sensor event in the array
        events[i].temperature = temperature;
        events[i].status = status;
        events[i].log_message = (char*) malloc((strlen(json_object_get_string(log_message)) + 1) * sizeof(char));
        strcpy(events[i].log_message, json_object_get_string(log_message));
    }

    // Close the JSON file and free the memory allocated for the json_object
    fclose(fp);
    json_object_put(root);

    return events;
}

// Function to deallocate all allocated memory when done
void deallocate_events(sensor_event* events, int num_events) {
    for (int i = 0; i < num_events; i++) {
        free(events[i].log_message);
    }
    free(events);
}

int main() {
    // Test the read_json function by reading a JSON file with sensor events
    const char* json_file = "sensor_events.json";
    int num_events = 10;

    sensor_event* events = read_json(json_file);
    if (events == NULL) {
        printf("Error: failed to read JSON file\n");
        return -1;
    }

    // Print the temperature readings and status flags for each event
    for (int i = 0; i < num_events; i++) {
        printf("Event %d: Temperature = %.2f, Status = %s, Log Message = %s\n",
                i + 1, events[i].temperature, events[i].status ? "True" : "False", events[i].log_message);
    }

    // Deallocate all allocated memory when done
    deallocate_events(events, num_events);

    return 0;
}']

