/*
 * Dynamic data structure for managing records with varying types and sizes in a high-throughput environment.
 * Each record consists of an integer key, a long offset, a double precision data point, and a custom payload.
 * Supports insertion, deletion, and retrieval operations, ensuring thread-safe access and minimal lock contention.
 * Designed to handle concurrent access safely while optimizing frequent access patterns with caching.
 */

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

/*
 * Structure to represent a record in the data structure.
 * Contains an integer key, a long offset, a double precision data point, and a custom payload.
 */
typedef struct {
    int key;
    long offset;
    double data_point;
    char* payload;
} Record;

/*
 * Structure to represent the data structure itself.
 * Contains an array of records, a cache of recently accessed records, and a mutex for synchronizing access.
 */
typedef struct {
    Record** records;
    int num_records;
    int* cache;
    pthread_mutex_t mutex;
} DataStructure;

/*
 * Function to initialize the data structure with a given number of records.
 * Allocates memory for the records and initializes the cache.
 */
void init(DataStructure* ds, int num_records) {
    // Allocate memory for the records array
    ds->records = (Record**)malloc(sizeof(Record*) * num_records);
    if (ds->records == NULL) {
        printf("Error: Failed to allocate memory for records.\n");
        exit(1);
    }

    // Allocate memory for the cache
    ds->cache = (int*)malloc(sizeof(int) * num_records);
    if (ds->cache == NULL) {
        printf("Error: Failed to allocate memory for cache.\n");
        exit(1);
    }

    // Initialize the cache with -1
    memset(ds->cache, -1, sizeof(int) * num_records);

    // Initialize the mutex
    pthread_mutex_init(&ds->mutex, NULL);
}

/*
 * Function to insert a new record into the data structure.
 * If the key already exists, updates the existing record with the given offset and payload.
 */
void insert(DataStructure* ds, int key, long offset, double data_point, char* payload) {
    // Lock the mutex
    pthread_mutex_lock(&ds->mutex);

    // Check if the key already exists in the cache
    bool found = false;
    for (int i = 0; i < ds->num_records; i++) {
        if (ds->cache[i] == key) {
            // Update the existing record
            Record* record = ds->records[i];
            record->offset = offset;
            record->data_point = data_point;
            strcpy(record->payload, payload);

            found = true;
            break;
        }
    }

    // If the key doesn't exist in the cache, add a new record
    if (!found) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (record == NULL) {
            printf("Error: Failed to allocate memory for new record.\n");
            exit(1);
        }

        // Initialize the record
        record->key = key;
        record->offset = offset;
        record->data_point = data_point;
        record->payload = (char*)malloc(sizeof(char) * strlen(payload));
        if (record->payload == NULL) {
            printf("Error: Failed to allocate memory for payload.\n");
            exit(1);
        }

        // Add the new record to the cache and array
        ds->cache[ds->num_records] = key;
        ds->records[ds->num_records++] = record;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ds->mutex);
}

/*
 * Function to delete a record from the data structure.
 * If the key doesn't exist, does nothing.
 */
void delete(DataStructure* ds, int key) {
    // Lock the mutex
    pthread_mutex_lock(&ds->mutex);

    // Check if the key exists in the cache
    bool found = false;
    for (int i = 0; i < ds->num_records; i++) {
        if (ds->cache[i] == key) {
            found = true;
            break;
        }
    }

    // If the key exists, remove it from the cache and array
    if (found) {
        int index = 0;
        for (int i = 0; i < ds->num_records; i++) {
            if (ds->cache[i] == key) {
                index = i;
                break;
            }
        }

        // Remove the record from the cache and array
        memmove(ds->cache + index, ds->cache + index + 1, sizeof(int) * (ds->num_records - index));
        memmove(ds->records + index, ds->records + index + 1, sizeof(Record*) * (ds->num_records - index));
        ds->num_records--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ds->mutex);
}

/*
 * Function to retrieve a record from the data structure.
 * Returns NULL if the key doesn't exist in the cache.
 */
Record* retrieve(DataStructure* ds, int key) {
    // Lock the mutex
    pthread_mutex_lock(&ds->mutex);

    // Check if the key exists in the cache
    bool found = false;
    for (int i = 0; i < ds->num_records; i++) {
        if (ds->cache[i] == key) {
            found = true;
            break;
        }
    }

    // If the key exists, return the record from the cache and array
    Record* record = NULL;
    if (found) {
        int index = 0;
        for (int i = 0; i < ds->num_records; i++) {
            if (ds->cache[i] == key) {
                index = i;
                break;
            }
        }

        record = ds->records[index];
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ds->mutex);

    return record;
}

/*
 * Function to free the memory allocated for the data structure.
 */
void destroy(DataStructure* ds) {
    // Lock the mutex
    pthread_mutex_lock(&ds->mutex);

    // Free the records and cache
    free(ds->records);
    free(ds->cache);

    // Destroy the mutex
    pthread_mutex_destroy(&ds->mutex);
}']

