#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Task structure definition
typedef struct {
    int task_id;
    int priority;
    char* status;
    time_t last_updated;
} task_t;

// Task queue data structure
typedef struct {
    task_t** tasks;
    size_t capacity;
    size_t count;
} task_queue_t;

// Initialize the task queue with a specified capacity
task_queue_t* task_queue_init(size_t capacity) {
    task_queue_t* q = (task_queue_t*)malloc(sizeof(task_queue_t));
    if (!q) return NULL;
    q->tasks = (task_t**)malloc(capacity * sizeof(task_t*));
    if (!q->tasks) {
        free(q);
        return NULL;
    }
    q->capacity = capacity;
    q->count = 0;
    return q;
}

// Add a new task to the queue
void task_queue_add(task_queue_t* q, int task_id, int priority, char* status) {
    if (q->count == q->capacity) {
        // Double the capacity of the queue if it is full
        size_t new_capacity = q->capacity * 2;
        task_t** new_tasks = (task_t**)realloc(q->tasks, new_capacity * sizeof(task_t*));
        if (!new_tasks) {
            free(q->tasks);
            return;
        }
        q->tasks = new_tasks;
        q->capacity = new_capacity;
    }
    task_t* t = (task_t*)malloc(sizeof(task_t));
    if (!t) {
        free(q);
        return;
    }
    t->task_id = task_id;
    t->priority = priority;
    t->status = status;
    t->last_updated = time(NULL);
    q->tasks[q->count++] = t;
}

// Update a task in the queue
void task_queue_update(task_queue_t* q, int index, int priority, char* status) {
    if (index < 0 || index >= q->count) return;
    task_t* t = q->tasks[index];
    t->priority = priority;
    t->status = status;
    t->last_updated = time(NULL);
}

// Retrieve a task from the queue by index
task_t* task_queue_get(task_queue_t* q, int index) {
    if (index < 0 || index >= q->count) return NULL;
    return q->tasks[index];
}

// Retrieve all tasks from the queue with a given priority level
task_t** task_queue_get_by_priority(task_queue_t* q, int priority) {
    if (q->count == 0) return NULL;
    size_t i = 0;
    for (i = 0; i < q->count; i++) {
        task_t* t = q->tasks[i];
        if (t->priority == priority) return t;
    }
    return NULL;
}

// Retrieve all tasks from the queue with a given status
task_t** task_queue_get_by_status(task_queue_t* q, char* status) {
    if (q->count == 0) return NULL;
    size_t i = 0;
    for (i = 0; i < q->count; i++) {
        task_t* t = q->tasks[i];
        if (!strcmp(t->status, status)) return t;
    }
    return NULL;
}

// Free the memory used by the task queue
void task_queue_free(task_queue_t* q) {
    for (size_t i = 0; i < q->count; i++) {
        free(q->tasks[i]);
    }
    free(q->tasks);
    free(q);
}
```
