            fprintf(stderr, "Error: Failed to allocate memory for input file '%s'\n", entry->d_name);
            continue;
        }
        size_t read_bytes = fread(buffer, 1, image_size, input_file);
        if (read_bytes < image_size) {
            fprintf(stderr, "Error: Failed to read complete input file '%s'\n", entry->d_name);
            continue;
        }

        // Convert the image using a third-party library
        temp_filename = get_temp_filename(config->output_path, ".tmp");
        if (temp_filename == NULL) {
            fprintf(stderr, "Error: Failed to generate temporary filename\n");
            continue;
        }
        FILE* output_file = fopen(temp_filename, "wb");
        if (output_file == NULL) {
            fprintf(stderr, "Error: Failed to open temporary file '%s'\n", temp_filename);
            free(temp_filename);
            continue;
        }
        int result = convert_image(buffer, image_size, format, output_file, config->quality, config->compression_level);
        if (result < 0) {
            fprintf(stderr, "Error: Failed to convert input file '%s'\n", entry->d_name);
            continue;
        }
        free(temp_filename);

        // Create a record for the converted image and store it in the records array
        struct Record* record = &records[i];
        record->value = generate_random_number();
        record->format = format;

        i++;
    }
    closedir(dir);

    // Write the records to the output file
    FILE* out_file = fopen(config->output_path, "wb");
    if (out_file == NULL) {
        fprintf(stderr, "Error: Failed to open output file\n");
        return -1;
    }
    size_t write_bytes = fwrite(records, sizeof(struct Record), i, out_file);
    if (write_bytes < i) {
        fprintf(stderr, "Error: Failed to write complete output file\n");
        return -1;
    }
    fclose(out_file);

    // Clean up temporary files and memory
    for (j = 0; j < i; j++) {
        struct Record* record = &records[j];
        free(record->format);
    }
    free(records);
    return 0;
}
```
This implementation uses a third-party library to convert images from various formats into one of multiple requested formats based on the configuration. It also handles cases where the conversion fails for a specific file gracefully, providing detailed error messages and attempting to convert to the next supported format in the configuration list. Additionally, it implements error handling for file I/O operations, ensuring that temporary files used during the conversion process are properly cleaned up.

