// Define the structure to store record data
typedef struct {
    int key;
    char data[10];
} record;

// Define the linked list node structure
typedef struct {
    record *record_data;
    struct node *next;
} node;

// Function to initialize the 'record' structures with random integer values within a specified range, ensuring all keys are unique.
void init_records(int min, int max) {
    // Initialize the linked list head pointer
    node *head = NULL;

    // Loop until all records have been initialized
    while (1) {
        // Generate a random integer value within the specified range
        int key = rand() % (max - min + 1) + min;

        // Check if the generated key is unique
        node *current = head;
        while (current != NULL) {
            if (current->record_data.key == key) {
                break;
            }
            current = current->next;
        }

        // If the generated key is unique, initialize a new record and add it to the linked list
        if (current == NULL) {
            record *new_record = malloc(sizeof(record));
            new_record->key = key;
            strcpy(new_record->data, "");

            // Add the new record to the linked list
            node *new_node = malloc(sizeof(node));
            new_node->record_data = new_record;
            new_node->next = head;
            head = new_node;
        }
    }
}

// Function to dynamically allocate and manage memory for the 'record' structures
void *allocate_memory(int size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        // Handle the memory allocation failure
        return ptr;
    } else {
        // Initialize the allocated memory with random data
        srand(time(NULL));
        for (int i = 0; i < size; i++) {
            ((char *)ptr)[i] = rand() % 256;
        }

        // Return a pointer to the allocated memory
        return ptr;
    }
}

// Function to read data from a binary file and populate the 'record' structures
void read_data(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle the file opening failure
        return;
    }

    // Read data from the binary file and populate the 'record' structures
    while (1) {
        int key;
        char data[10];
        fread(&key, sizeof(int), 1, file);
        fread(data, sizeof(char), 10, file);

        // Check if the record is already in the linked list
        node *current = head;
        while (current != NULL) {
            if (current->record_data.key == key) {
                strcpy(current->record_data.data, data);
                break;
            }
            current = current->next;
        }

        // If the record is not in the linked list, create a new record and add it to the linked list
        if (current == NULL) {
            record *new_record = malloc(sizeof(record));
            new_record->key = key;
            strcpy(new_record->data, data);

            // Add the new record to the linked list
            node *new_node = malloc(sizeof(node));
            new_node->record_data = new_record;
            new_node->next = head;
            head = new_node;
        }
    }
}

// Function to update the 'record' structures with new data from a binary file
void update_records(const char *filename) {
    // Read the new data from the binary file and populate the 'record' structures
    read_data(filename);

    // Update the linked list by comparing the existing records with the new ones
    node *current = head;
    while (current != NULL) {
        record *new_record = current->record_data;
        int key = new_record->key;
        char data[10];
        strcpy(data, new_record->data);

        // Check if the record is already in the linked list
        node *next = current->next;
        while (next != NULL) {
            if (next->record_data.key == key && strcmp(next->record_data.data, data) == 0) {
                // If the record exists and has the same data, update it in place
                next->record_data = new_record;
                break;
            } else if (next->record_data.key == key && strcmp(next->record_data.data, data) != 0) {
                // If the record exists and has different data, remove it from the linked list and allocate a new record
                node *temp = next;
                next = next->next;
                free(temp);
            }
            next = next->next;
        }

        current = current->next;
    }
}

// Function to print all the records in the linked list
void print_records() {
    node *current = head;
    while (current != NULL) {
        printf("%d %s\n", current->record_data.key, current->record_data.data);
        current = current->next;
    }
}
