['```
#include <iostream>
#include <fstream>
#include <cstring>
#include <cstdlib>
#include <ctime>
#include <algorithm>
#include <vector>
#include <mutex>
#include <condition_variable>

using namespace std;

struct Record {
    long offset;
    int key;
    double value;
};

const size_t MAX_RECORDS = 5000; // maximum number of records to cache
const size_t BUFFER_SIZE = 1024 * 1024 * 30; // 30% of available system memory
const int MIN_BUFFER_SIZE = 1024 * 1024 * 16; // minimum buffer size for records
const double CACHE_HIT_RATIO = 0.75; // ratio of cache hits to total number of records processed
const int MAX_CORRUPTED_ENTRIES = 10; // maximum number of corrupted entries to handle
const int SEED_VALUE = time(NULL); // seed value for random number generator

vector<Record> cache; // cache of records
mutex cacheMutex; // mutex for protecting the cache
condition_variable cacheCondition; // condition variable for signaling available slots in the cache
size_t numRecordsProcessed = 0; // total number of records processed
size_t numCorruptedEntriesHandled = 0; // number of corrupted entries handled
double averageTimePerRecord = 0.0; // average time taken per record to process and cache
int cacheHitCount = 0; // number of cache hits
int cacheMissCount = 0; // number of cache misses
int cacheEvictionCount = 0; // number of cache evictions
int cacheInsertionCount = 0; // number of cache insertions

// custom caching mechanism that stores up to MAX_RECORDS records in memory
void cacheRecord(const Record& record) {
    unique_lock<mutex> lock(cacheMutex);
    while (cache.size() >= MAX_RECORDS) { // if the cache is full, wait for a slot to become available
        cacheCondition.wait(lock);
    }
    cache.push_back(record);
    cacheInsertionCount++;
}

// evicts the least recently used record from the cache
void evictRecord() {
    unique_lock<mutex> lock(cacheMutex);
    if (cache.size() > 0) { // if there are any records in the cache, evict one of them
        Record& evictedRecord = cache[0];
        cache.erase(cache.begin());
        cacheEvictionCount++;
        return evictedRecord;
    } else { // otherwise, do nothing and wait for a record to become available
        cacheCondition.wait(lock);
    }
}

// handles a corrupted entry by logging a warning and skipping it
void handleCorruptedEntry() {
    numCorruptedEntriesHandled++;
    cout << "Corrupted entry encountered, skipping" << endl;
}

// initializes the offset, key, and value fields of a record using data read from a file
bool initRecord(const string& filePath, Record& record) {
    ifstream inFile(filePath);
    if (inFile.is_open()) {
        string line;
        while (getline(inFile, line)) { // for each line in the file
            size_t delimiterPos = line.find(','); // find the position of the first comma
            if (delimiterPos != string::npos) { // if a comma is found
                try {
                    record.offset = stol(line.substr(0, delimiterPos)); // initialize the offset field
                    record.key = stoi(line.substr(delimiterPos + 1)); // initialize the key field
                    record.value = stod(line); // initialize the value field
                    return true; // if all fields are successfully initialized, return true
                } catch (const invalid_argument&) { // if any of the fields cannot be initialized, handle it as a corrupted entry
                    handleCorruptedEntry();
                    continue; // skip to the next line in the file
                }
            } else { // if no comma is found, handle it as a corrupted entry
                handleCorruptedEntry();
                continue;
            }
        }
    }
    return false; // if all entries are corrupted or malformed, return false
}

// processes a record by caching it and logging its processing time
void processRecord(const Record& record) {
    size_t startTime = clock(); // get the starting time of the current record's processing
    cacheRecord(record); // cache the record
    size_t endTime = clock(); // get the ending time of the current record's processing
    averageTimePerRecord += (endTime - startTime) / numRecordsProcessed; // update the average time taken per record
    cacheHitCount++; // increment the cache hit count
}

// processes a file containing records by caching and logging them, as well as handling corrupted entries
void processFile(const string& filePath) {
    Record record; // temporary record variable
    ifstream inFile(filePath); // open the input file
    if (inFile.is_open()) {
        size_t bufferSize = BUFFER_SIZE; // initialize the buffer size to the maximum allowed value
        char* buffer = new char[bufferSize]; // allocate a buffer of the maximum allowed size
        while (!inFile.eof()) { // for each line in the file
            inFile.read(buffer, bufferSize); // read from the current position in the file until the end of the buffer is reached
            string line = buffer; // initialize the line to the contents of the buffer
            if (initRecord(line, record)) { // try to initialize the record using data read from the file
                processRecord(record); // cache and log the record
            } else { // if any entry is corrupted or malformed, handle it as a corrupted entry
                handleCorruptedEntry();
            }
        }
        delete[] buffer; // deallocate the buffer
    }
}

// handles concurrent access from multiple threads safely without causing race conditions
void processFiles(const vector<string>& filePaths) {
    for (const string& filePath : filePaths) { // for each input file
        thread thread(&processFile, filePath); // create a new thread to process the current file
        thread.detach(); // detach the thread from this function so that it can continue processing the file independently
    }
}

int main() {
    srand(SEED_VALUE); // seed the random number generator with the current time in nanoseconds
    vector<string> filePaths = {"file1.txt", "file2.txt", "file3.txt"}; // initialize the vector of input file paths
    processFiles(filePaths); // process each input file using multiple threads
    cout << "Total number of valid records processed: " << numRecordsProcessed << endl;
    cout << "Cache hit rate: " << cacheHitCount * 100.0 / numRecordsProcessed << "%" << endl;
    cout << "Number of corrupted entries handled: " << numCorruptedEntriesHandled << endl;
    cout << "Average time taken per record to process and cache: " << averageTimePerRecord << " nanoseconds" << endl;
}
```']

