// Function to allocate memory for the structures
void* allocate_memory(int num_offsets) {
    // Validate input parameter
    if (num_offsets <= 0) {
        printf("Error: Invalid number of offsets\n");
        return NULL;
    }

    // Allocate memory for the structures in a single call to malloc
    size_t total_size = sizeof(long) * num_offsets + sizeof(int) * num_offsets + sizeof(struct record) * num_offsets;
    if (total_size > MAX_ALLOCATION_SIZE) {
        printf("Error: Total allocation size exceeds maximum allowed\n");
        return NULL;
    }

    void* memory = malloc(total_size);
    if (memory == NULL) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the structures in the allocated memory
    long* offsets = (long*)memory;
    int* keys = (int*)(offsets + num_offsets);
    struct record* records = (struct record*)(keys + num_offsets);
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 100 - 50;
        records[i].ptr = &(offsets[i]);
        records[i].key = keys[i];
    }

    return memory;
}

// Function to safely free all allocated memory
void free_memory(void* memory) {
    if (memory != NULL) {
        free(memory);
