#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Custom memory management system for efficient event record handling
struct MemoryManager {
  // Allocate a block of memory with size bytes
  void* allocate(size_t size) {
    return malloc(size);
  }

  // Free a block of memory at the given address
  void free(void* address) {
    free(address);
  }
};

// Event record structure for storing timestamp, event ID, and message
struct EventRecord {
  int64_t timestamp;   // Timestamp in milliseconds since epoch
  uint32_t id;         // Unique event ID
  char message[256];  // Variable-length message (up to 255 characters)
};

// Map of event IDs to event records, using a custom memory manager for efficient allocation and deallocation
using EventMap = std::unordered_map<uint32_t, struct EventRecord*, MemoryManager>;

// Global map of event IDs to event records, shared among threads
EventMap* globalEvents;

// Lock used for thread-safe access to the global events map
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new event record into the global events map
void insertEvent(uint32_t id, int64_t timestamp, const char* message) {
  // Acquire the lock for thread-safe access to the global events map
  pthread_mutex_lock(&lock);

  struct EventRecord event;
  event.timestamp = timestamp;
  event.id = id;
  strncpy(event.message, message, sizeof(event.message) - 1);

  // Insert the new event record into the global events map
  (*globalEvents)[id] = event;

  // Release the lock for thread-safe access to the global events map
  pthread_mutex_unlock(&lock);
}

// Function to update an existing event record in the global events map
void updateEvent(uint32_t id, int64_t timestamp, const char* message) {
  // Acquire the lock for thread-safe access to the global events map
  pthread_mutex_lock(&lock);

  struct EventRecord event = (*globalEvents)[id];
  event.timestamp = timestamp;
  strncpy(event.message, message, sizeof(event.message) - 1);

  // Update the existing event record in the global events map
  (*globalEvents)[id] = event;

  // Release the lock for thread-safe access to the global events map
  pthread_mutex_unlock(&lock);
}

// Function to retrieve an event record from the global events map by ID
struct EventRecord* getEvent(uint32_t id) {
  // Acquire the lock for thread-safe access to the global events map
  pthread_mutex_lock(&lock);

  struct EventRecord* event = (*globalEvents)[id];

  // Release the lock for thread-safe access to the global events map
  pthread_mutex_unlock(&lock);

  return event;
}

// Function to delete an existing event record from the global events map by ID
void deleteEvent(uint32_t id) {
  // Acquire the lock for thread-safe access to the global events map
  pthread_mutex_lock(&lock);

  struct EventRecord* event = (*globalEvents)[id];
  if (event != nullptr) {
    free(event);
  }

  // Delete the existing event record from the global events map
  (*globalEvents).erase(id);

  // Release the lock for thread-safe access to the global events map
  pthread_mutex_unlock(&lock);
}

// Function to periodically archive older events to disk
void archiveEvents() {
  // Acquire the lock for thread-safe access to the global events map
  pthread_mutex_lock(&lock);

  // Periodically iterate over the event records in the global events map and archive them to disk
  auto it = (*globalEvents).begin();
  while (it != (*globalEvents).end()) {
    struct EventRecord* event = it->second;
    if (event != nullptr && event->timestamp < getCurrentTimeMillis() - ARCHIVE_GRANULARITY) {
      // Archive the event record to disk
      FILE* fp = fopen("archive.dat", "a");
      fwrite(event, sizeof(struct EventRecord), 1, fp);
      fclose(fp);

      // Delete the archived event record from the global events map
      deleteEvent(it->first);
    } else {
      ++it;
    }
  }

  // Release the lock for thread-safe access to the global events map
  pthread_mutex_unlock(&lock);
}

// Main function that initializes the event system and processes initial event data from a compressed binary log file
int main(int argc, char* argv[]) {
  // Initialize the global events map with a custom memory manager
  globalEvents = new EventMap(MemoryManager());

  // Load initial event data from a compressed binary log file and insert each record into the global events map
  FILE* fp = fopen("log.bin", "rb");
  while (true) {
    struct EventRecord event;
    size_t bytes_read = fread(&event, sizeof(struct EventRecord), 1, fp);
    if (bytes_read == 0) {
      break;
    }
    insertEvent(event.id, event.timestamp, event.message);
  }
  fclose(fp);

  // Start the archiving thread to periodically archive older events to disk
  pthread_t archiver;
  pthread_create(&archiver, nullptr, archiveEvents, nullptr);

  return 0;
}
