// Configuration sources and their priorities
struct config_source {
    char *name; // Source name
    int priority; // Priority of the source
};

// Function to dynamically manage network service configurations
int manage_config(struct config_source sources[], int num_sources) {
    // Initialize variables
    struct configuration *configuration = NULL;
    int ret = 0;

    // Load default configuration
    configuration = load_default_config();

    // Apply configurations from environment variables
    for (int i = 0; i < num_sources; i++) {
        if (strcmp(sources[i].name, "ENV") == 0) {
            ret = apply_env_vars(&configuration);
            if (ret != 0) {
                fprintf(stderr, "Failed to apply environment variables: %d\n", ret);
                goto cleanup;
            }
        }
    }

    // Apply configurations from command line arguments
    for (int i = 0; i < num_sources; i++) {
        if (strcmp(sources[i].name, "ARG") == 0) {
            ret = apply_cmdline_args(&configuration);
            if (ret != 0) {
                fprintf(stderr, "Failed to apply command line arguments: %d\n", ret);
                goto cleanup;
            }
        }
    }

    // Apply configurations from configuration file
    for (int i = 0; i < num_sources; i++) {
        if (strcmp(sources[i].name, "FILE") == 0) {
            ret = apply_config_file(&configuration);
            if (ret != 0) {
                fprintf(stderr, "Failed to apply configuration file: %d\n", ret);
                goto cleanup;
            }
        }
    }

    // Apply critical parameters from external API
    for (int i = 0; i < num_sources; i++) {
        if (strcmp(sources[i].name, "EXTERNAL_API") == 0) {
            ret = apply_external_api(&configuration);
            if (ret != 0) {
                fprintf(stderr, "Failed to apply external API: %d\n", ret);
                goto cleanup;
            }
        }
    }

cleanup:
    // Clean up
    free_configuration(&configuration);

    return ret;
}

// Load default configuration from file
struct configuration *load_default_config() {
    struct configuration *configuration = NULL;
    FILE *file = fopen(DEFAULT_CONFIG, "r");
    if (file == NULL) {
        perror("Failed to open default config file");
        return NULL;
    }

    // Read and parse JSON data from the file
