    size_t json_len = fread(json_data, 1, 1024, file);
    if (json_len == 0) {
        perror("Failed to read default config file");
        return NULL;
    }
    configuration = parse_json_data(json_data, json_len);
    free(json_data);

    // Close the file
    fclose(file);

    return configuration;
}

// Apply environment variables to the configuration
int apply_env_vars(struct configuration **configuration) {
    struct configuration *config = *configuration;

