#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define struct for item
struct Item {
    char identifier;
    int value;
    float weight;
};

// Define array to store items
struct Item *items = NULL;
size_t num_items = 0;
size_t max_items = 10000000; // Maximum number of items allowed (10 million)

// Define function to add item
void add_item(char identifier, int value, float weight) {
    // Check if array is full
    if (num_items >= max_items) {
        return;
    }

    // Add new item to array
    items[num_items].identifier = identifier;
    items[num_items].value = value;
    items[num_items].weight = weight;

    // Increment number of items
    num_items++;
}

// Define function to retrieve item based on identifier
struct Item *get_item(char identifier) {
    for (size_t i = 0; i < num_items; i++) {
        if (items[i].identifier == identifier) {
            return &items[i];
        }
    }
    return NULL;
}

// Define function to retrieve total memory usage in bytes
size_t get_memory_usage() {
    return sizeof(struct Item) * num_items;
}

// Define function to read list of identifiers and values from file
void read_file(char *filename, char delimiter) {
    // Open file in read mode
    FILE *file = fopen(filename, "r");

    // Check if file exists
    if (file == NULL) {
        return;
    }

    // Read contents of file line by line
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Split line into tokens using delimiter
        char *token = strtok(line, delimiter);
        char identifier = token[0];
        int value = atoi(token + 1);
        float weight = atof(token + 2);

        // Add item to array
        add_item(identifier, value, weight);
    }

    // Close file
    fclose(file);
}

// Define function to deallocate all allocated memory when done
void deallocate_memory() {
    free(items);
}

int main() {
    read_file("input.txt", ",");

    // Print total memory usage in bytes
    printf("Total memory usage: %lu\n", get_memory_usage());

    // Print first 10 items
    for (size_t i = 0; i < 10; i++) {
        struct Item *item = &items[i];
        printf("%c: %d, %.2f\n", item->identifier, item->value, item->weight);
    }

    // Deallocate all allocated memory when done
    deallocate_memory();

    return 0;
