// Define the structure to store item data
typedef struct {
    char* name;
    double value;
} Item;

// Define a linked list node to store items in the collection
typedef struct Node {
    Item* data;
    struct Node* next;
} Node;

// Define the collection structure
typedef struct {
    Node* head; // Pointer to the first node in the collection
    size_t numItems; // Number of items in the collection
    size_t maxNameLen; // Maximum length of item names
    size_t maxValueRange; // Maximum range of values for each item
    double totalMemoryUsage; // Total memory usage in bytes
} Collection;

// Define the function to allocate and initialize the collection
Collection* createCollection(size_t maxNameLen, size_t maxValueRange) {
    // Allocate memory for the collection structure
    Collection* col = malloc(sizeof(Collection));
    if (col == NULL) {
        fprintf(stderr, "Failed to allocate memory for the collection\n");
        return NULL;
    }

    // Initialize the collection fields
    col->head = NULL;
    col->numItems = 0;
    col->maxNameLen = maxNameLen;
    col->maxValueRange = maxValueRange;
    col->totalMemoryUsage = 0;

    return col;
}

// Define the function to insert an item into the collection
void insertItem(Collection* col, const char* name, double value) {
    // Check if the collection is empty and allocate memory for the first node
    if (col->head == NULL) {
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Failed to allocate memory for the first node\n");
            return;
        }
        col->head = newNode;
    } else {
        // Allocate memory for a new node and link it to the previous node
        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Failed to allocate memory for a new node\n");
            return;
        }
        newNode->next = col->head;
        col->head = newNode;
    }

    // Initialize the data field of the new node
    Item* newItem = malloc(sizeof(Item));
    if (newItem == NULL) {
        fprintf(stderr, "Failed to allocate memory for the item\n");
        return;
    }
    newItem->name = strdup(name);
    newItem->value = value;
    col->head->data = newItem;
    col->numItems++;
    col->totalMemoryUsage += sizeof(Node) + strlen(newItem->name) + sizeof(double);
}

// Define the function to delete an item from the collection
void deleteItem(Collection* col, const char* name) {
    // Find the node with the matching name and unlink it from the list
    Node* current = col->head;
    while (current != NULL) {
        if (strcmp(current->data->name, name) == 0) {
            Node* prev = current;
            current = current->next;
            free(prev);
            break;
        } else {
            current = current->next;
        }
    }
}

// Define the function to retrieve an item from the collection
Item* getItem(Collection* col, const char* name) {
    // Find the node with the matching name and return its data field
    Node* current = col->head;
    while (current != NULL) {
        if (strcmp(current->data->name, name) == 0) {
            return current->data;
        } else {
            current = current->next;
        }
    }
}

// Define the function to search for items in the collection based on a substring match
void searchItems(Collection* col, const char* substr) {
    // Iterate over all nodes and print the names of items that contain the specified substring
    Node* current = col->head;
    while (current != NULL) {
        if (strstr(current->data->name, substr) != NULL) {
            printf("%s\n", current->data->name);
        }
        current = current->next;
    }
}

// Define the function to deallocate all allocated memory for the collection
void destroyCollection(Collection* col) {
    // Free all nodes in the list and the collection structure
    Node* current = col->head;
    while (current != NULL) {
        Node* prev = current;
        current = current->next;
        free(prev);
    }
}
