#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <fstream>
#include <mutex>
#include <condition_variable>

using namespace std;

class DynamicRangeDataHandler {
private:
    struct Attack {
        char* name;
        double value;
    };

    vector<Attack> attacks;
    map<string, int> attackIndexMap;
    double minValue;
    double maxValue;
    int currentRange;
    mutex mtx;
    condition_variable cv;
    bool dirty;

public:
    DynamicRangeDataHandler(double minValue, double maxValue) : minValue(minValue), maxValue(maxValue), currentRange(0), dirty(true) { }

    void setRange(int range) {
        unique_lock<mutex> lock(mtx);
        if (range >= 0 && range <= 1000000000) {
            currentRange = range;
            dirty = true;
        } else {
            throw invalid_argument("Invalid range");
        }
    }

    int getCurrentRange() {
        unique_lock<mutex> lock(mtx);
        return currentRange;
    }

    void addAttack(const char* name, double value) {
        unique_lock<mutex> lock(mtx);
        if (value >= minValue && value <= maxValue) {
            attacks.push_back({name, value});
            attackIndexMap[name] = attacks.size() - 1;
            dirty = true;
        } else {
            throw invalid_argument("Invalid attack value");
        }
    }

    void removeAttack(const char* name) {
        unique_lock<mutex> lock(mtx);
        if (attackIndexMap.find(name) != attackIndexMap.end()) {
            int index = attackIndexMap[name];
            attacks.erase(attacks.begin() + index);
            attackIndexMap.erase(name);
            dirty = true;
        } else {
            throw invalid_argument("Invalid attack name");
        }
    }

    double getAttackValue(const char* name) {
        unique_lock<mutex> lock(mtx);
        if (attackIndexMap.find(name) != attackIndexMap.end()) {
            return attacks[attackIndexMap[name]].value;
        } else {
            throw invalid_argument("Invalid attack name");
        }
    }

    void updateAttackValue(const char* name, double value) {
        unique_lock<mutex> lock(mtx);
        if (attackIndexMap.find(name) != attackIndexMap.end()) {
            int index = attackIndexMap[name];
            attacks[index].value = value;
            dirty = true;
        } else {
            throw invalid_argument("Invalid attack name");
        }
    }

    void serialize() {
        unique_lock<mutex> lock(mtx);
        ofstream outfile("attacks.json");
        if (outfile) {
            for (auto& a : attacks) {
                string name = a.name;
                double value = a.value;
                outfile << "{\"name\":\"" << name << "\",\"value\":" << value << "}" << endl;
            }
            outfile.close();
        } else {
            throw invalid_argument("Error writing to file");
        }
    }

    void deserialize() {
        unique_lock<mutex> lock(mtx);
        ifstream infile("attacks.json");
        if (infile) {
            attacks.clear();
            attackIndexMap.clear();
            string line;
            while (getline(infile, line)) {
                istringstream iss(line);
                string name;
                double value;
                iss >> name >> value;
                attacks.push_back({name, value});
                attackIndexMap[name] = attacks.size() - 1;
            }
            infile.close();
        } else {
            throw invalid_argument("Error reading from file");
        }
    }

    void persistToDisk() {
        unique_lock<mutex> lock(mtx);
        if (dirty) {
            serialize();
            dirty = false;
        }
    }
};
```
