#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Struct for storing data in the linked list
typedef struct Node {
    char* str;
    int value;
    struct Node* next;
} Node;

// Function to dynamically allocate memory for a new node and initialize its fields
Node* create_node(char* str, int value) {
    // Allocate memory for the new node
    Node* node = malloc(sizeof(Node));
    if (!node) {
        printf("Error: Failed to allocate memory for new node\n");
        return NULL;
    }

    // Initialize the string and value fields of the new node
    node->str = strdup(str);
    node->value = value;

    // Set the next pointer of the new node to NULL
    node->next = NULL;

    return node;
}

// Function to add a new node to the linked list with the given string and integer value
void add_node(Node** head, char* str, int value) {
    // Create a new node with the given string and integer value
    Node* new_node = create_node(str, value);
    if (!new_node) {
        printf("Error: Failed to create new node\n");
        return;
    }

    // If the list is empty, set the head pointer to the new node
    if (*head == NULL) {
        *head = new_node;
    } else {
        // Otherwise, add the new node at the end of the list
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to traverse the linked list and print out the string and integer values associated with each node
void traverse_list(Node* head) {
    // If the list is empty, return immediately
    if (head == NULL) {
        return;
    }

    // Otherwise, traverse the list and print out the string and integer values of each node
    Node* current = head;
    while (current != NULL) {
        printf("Node: %s, Value: %d\n", current->str, current->value);
        current = current->next;
    }
}

// Function to free the memory allocated for a linked list
void free_list(Node* head) {
    // If the list is empty, return immediately
    if (head == NULL) {
        return;
    }

    // Otherwise, traverse the list and free the memory allocated for each node
    Node* current = head;
    while (current != NULL) {
        free(current->str);
        current = current->next;
    }
}
```
