    long id;
    int key;
    info_t *info;
} record_t;

static const int MAX_RECORDS = 10000; // maximum number of records allowed
static const size_t RANDOM_VALUE_RANGE = 1000; // valid range for random values

record_t *allocate_records(int num_records) {
    if (num_records > MAX_RECORDS) {
        return NULL;
    }

    size_t record_size = sizeof(record_t);
    size_t info_size = sizeof(info_t);
    size_t total_size = record_size + num_records * info_size;

    // allocate memory for the record array and initialize it
    record_t *records = (record_t *)malloc(total_size);
    if (!records) {
        return NULL;
    }
    memset(records, 0, total_size);

    // allocate memory for individual record structures and initialize them
    for (int i = 0; i < num_records; ++i) {
        records[i].id = i + 1;
        records[i].key = rand() % RANDOM_VALUE_RANGE;
        records[i].info = (info_t *)malloc(info_size);
        if (!records[i].info) {
            return NULL;
        }
        memset(records[i].info, 0, info_size);
    }

    // allocate memory for the struct info instances and initialize them
    for (int i = 0; i < num_records; ++i) {
        records[i].info->key = rand() % RANDOM_VALUE_RANGE;
        records[i].info->value = rand();
    }

    // track the total allocated memory size to prevent resource exhaustion
    static size_t total_allocated = 0;
    total_allocated += total_size;
    if (total_allocated > MAX_MEMORY) {
        return NULL;
    }

    // return a pointer to the first element of the record array
    return records;
}
```
