    double value;
    char *description;
    struct Element *prev, *next;
} Element;

// Function to insert a new element at the end of the list
Element* insert(Element *head, double value, char *description) {
    // Create a new element
    Element *new_element = malloc(sizeof(Element));
    if (new_element == NULL) {
        return NULL;
    }
    new_element->value = value;
    new_element->description = strdup(description);
    new_element->prev = head;
    new_element->next = NULL;

    // Update the pointers in the existing elements
    if (head != NULL) {
        Element *curr = head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_element;
        new_element->prev = curr;
    }

    // Return the new element
    return new_element;
}

// Function to delete an element from the list
void delete(Element *head, Element *element) {
    if (head == NULL || element == NULL) {
        return;
    }
    // Update the pointers in the existing elements
    if (element->prev != NULL) {
        Element *curr = head;
        while (curr->next != element) {
            curr = curr->next;
        }
        curr->next = element->next;
        if (element->next != NULL) {
            element->next->prev = curr;
        }
    } else {
        head = element->next;
    }

    // Free the memory of the deleted element
    free(element->description);
    free(element);
}

// Function to traverse the list and calculate the average value
void traverse(Element *head) {
    if (head == NULL) {
        return;
    }
    double sum = 0.0;
    int count = 0;
    Element *curr = head;
    while (curr != NULL) {
        sum += curr->value;
        count++;
        curr = curr->next;
    }
    printf("Average value: %lf\n", sum / count);
}

// Function to print the list and its elements
void print(Element *head) {
    if (head == NULL) {
        return;
    }
    Element *curr = head;
    while (curr != NULL) {
        printf("%lf: %s\n", curr->value, curr->description);
        curr = curr->next;
    }
}
