using Newtonsoft.Json;

public class ManageAndTransformData {
    private static readonly HttpClient _httpClient = new HttpClient();
    private static readonly string _dataStoragePath = Environment.GetEnvironmentVariable("DATA_STORAGE_PATH");

    public async Task<object> Invoke(Guid recordId, JObject requestBody) {
        var dataRecord = await GetDataRecordAsync(recordId);

        if (dataRecord == null) {
            return new { status = "absent" };
        }

        var transformations = requestBody["transformations"].ToObject<List<string>>();
        foreach (var transformation in transformations) {
            dataRecord = await ApplyTransformationAsync(dataRecord, transformation);
        }

        return dataRecord;
    }

    private async Task<object> GetDataRecordAsync(Guid recordId) {
        var request = new HttpRequestMessage(HttpMethod.Get, $"{_dataStoragePath}/records/{recordId}");
        var response = await _httpClient.SendAsync(request);

        if (response.IsSuccessStatusCode) {
            return JsonConvert.DeserializeObject<object>(await response.Content.ReadAsStringAsync());
        } else {
            throw new Exception($"Failed to retrieve data record with ID {recordId}");
        }
    }

    private async Task<object> ApplyTransformationAsync(object dataRecord, string transformation) {
        var request = new HttpRequestMessage(HttpMethod.Post, $"{_dataStoragePath}/transformations/{transformation}") { Content = JsonConvert.SerializeObject(dataRecord) };
        var response = await _httpClient.SendAsync(request);

        if (response.IsSuccessStatusCode) {
            return JsonConvert.DeserializeObject<object>(await response.Content.ReadAsStringAsync());
        } else {
            throw new Exception($"Failed to apply transformation {transformation}");
        }
    }

    private void ValidateRequestBody(JObject requestBody) {
        var schema = new JsonSchema() {
            Type = JTokenType.Object,
            Properties = new List<JsonProperty> {
                new JsonProperty("transformations", new JsonSchema { Type = JTokenType.Array })
            }
        };

        var validationResult = schema.Validate(requestBody);
        if (!validationResult.IsValid) {
            throw new Exception($"Request body does not conform to JSON schema: {string.Join(", ", validationResult.Errors)}");
        }
    }
}
