    if (tail == NULL) {
        head = tail = node;
    } else {
        tail->next = node;
        tail = node;
    }

    // Allocate memory for the chunks and add them to the linked list
    int chunkSize = 1024;
    ChunkNode* currentChunk = createChunk(chunkSize);
    node->next = currentChunk;
    while (strlen(content) > 0) {
        char* data = strndup(content, chunkSize);
        content += chunkSize;
        currentChunk->data->data = data;
        if (chunk_tail == NULL) {
            chunk_head = chunk_tail = currentChunk;
        } else {
            chunk_tail->next = currentChunk;
            chunk_tail = currentChunk;
        }
    }

    // Update the total memory usage
    total_memory += (sizeof(Node) + sizeof(Document)) * 1024;
}

