        unique_lock<mutex> lock(mutex_);
        auto it = attacks_.find(name);
        if (it != attacks_.end()) {
            throw runtime_error("Duplicate attack name");
        }
        Attack newAttack;
        newAttack.name = name;
        newAttack.strength = strength;
        attacks_[name] = newAttack;
        totalMemoryUsage_ += sizeof(Attack);
    }

    // Delete an attack from the collection
    void deleteAttack(const string& name) {
        unique_lock<mutex> lock(mutex_);
        auto it = attacks_.find(name);
        if (it == attacks_.end()) {
            throw runtime_error("No such attack");
        }
        totalMemoryUsage_ -= sizeof(Attack);
        attacks_.erase(it);
    }

    // Retrieve an attack by name
    const Attack* getAttack(const string& name) {
        unique_lock<mutex> lock(mutex_);
        auto it = attacks_.find(name);
        if (it == attacks_.end()) {
            return nullptr;
        }
        return &it->second;
    }

    // Query attacks based on substring matches in their names
    vector<Attack> queryAttacks(const string& pattern) {
        unique_lock<mutex> lock(mutex_);
        vector<Attack> results;
        for (auto it = attacks_.begin(); it != attacks_.end(); ++it) {
            if (it->first.find(pattern) != string::npos) {
                results.push_back(it->second);
            }
        }
        return results;
    }

    // Update the maximum allowed name length and acceptable range of attack strengths
    void updateConfig(int maxNameLength, double minStrength, double maxStrength) {
        unique_lock<mutex> lock(mutex_);
        this->maxNameLength = maxNameLength;
        this->minStrength = minStrength;
        this->maxStrength = maxStrength;
    }

    // Serialize the attack collection to JSON format
    string serialize() {
        unique_lock<mutex> lock(mutex_);
        Json::Value jsonAttacks;
        for (auto it = attacks_.begin(); it != attacks_.end(); ++it) {
            jsonAttacks[it->first] = Json::Value(Json::objectValue);
            jsonAttacks[it->first]["strength"] = it->second.strength;
        }
        return jsonAttacks.toStyledString();
    }

    // Deserialize the attack collection from JSON format
    void deserialize(const string& json) {
        unique_lock<mutex> lock(mutex_);
        Json::Value jsonAttacks;
        Json::Reader reader;
        if (!reader.parse(json, jsonAttacks)) {
            throw runtime_error("Invalid JSON");
        }
        for (auto it = jsonAttacks.begin(); it != jsonAttacks.end(); ++it) {
            attacks_[it.name()] = Attack{it->strength};
            totalMemoryUsage_ += sizeof(Attack);
        }
    }

private:
    // Map from attack names to their corresponding strengths
    unordered_map<string, Attack> attacks_;

    // Maximum allowed length of an attack name
    int maxNameLength;

    // Minimum and maximum acceptable range of attack strengths
    double minStrength, maxStrength;

    // Total memory usage in bytes for all attacks
    size_t totalMemoryUsage_;

    // Mutex to protect the map and other data structures
    mutex mutex_;
};

void manageDynamicAttackSystem(AttackManager& attackManager) {
    vector<thread> threads;
    condition_variable cv;
    bool done = false;

    // Thread to simulate a cooldown period for a video game character's attack selection
    threads.emplace_back([&]() {
        while (!done) {
            this_thread::sleep_for(9s);
            int selectedAttack = rand() % 2 + 1;
            cout << "Selected attack: " << selectedAttack << endl;
        }
    });

    // Thread to monitor and update the attack collection
    threads.emplace_back([&]() {
        while (!done) {
            unique_lock<mutex> lock(attackManager.mutex_);
            cv.wait(lock, [&]() { return !attackManager.attacks_.empty(); });
            for (auto it = attackManager.attacks_.begin(); it != attackManager.attacks_.end(); ++it) {
                if (it->second.strength < attackManager.minStrength || it->second.strength > attackManager.maxStrength) {
                    // Update the strength of this attack within acceptable range
                    it->second.strength = min(max(attackManager.minStrength, it->second.strength), attackManager.maxStrength);
                }
            }
        }
    });

    // Thread to persist the attack collection to disk periodically
    threads.emplace_back([&]() {
        while (!done) {
            unique_lock<mutex> lock(attackManager.mutex_);
            cv.wait(lock, [&]() { return !attackManager.attacks_.empty(); });
            ofstream outFile("attack_collection.json");
            if (outFile.is_open()) {
                outFile << attackManager.serialize();
                outFile.close();
            } else {
                cerr << "Failed to open output file for writing" << endl;
            }
        }
    });

    // Thread to load and run module tests
    threads.emplace_back([&]() {
        while (!done) {
            unique_lock<mutex> lock(attackManager.mutex_);
            cv.wait(lock, [&]() { return !attackManager.attacks_.empty(); });
            string json = "{\"Attack 1\": {\"strength\": 0.5}, \"Attack 2\": {\"strength\": 0.8}}";
            attackManager.deserialize(json);
        }
    });

    // Wait for all threads to finish
    done = true;
    cv.notify_all();
    for (auto& thread : threads) {
        thread.join();
    }
}
