static std::condition_variable g_fileMapCondVar;

// Function to dynamically manage a collection of text files
void manageAndProcessTextFiles() {
    // Initialize the hash table and vector of text files
    FileMap fileMap;
    TextFiles textFiles;

    // Create a mutex and condition variable for the file map
    std::mutex fileMapMutex;
    std::condition_variable fileMapCondVar;

    // Initialize the maximum length of filenames to 256 characters
    size_t maxFilenameLength = 256;

    // Loop forever, processing files and updating the hash table
    while (true) {
        // Sleep for a random amount of time to simulate cooldown period
        std::this_thread::sleep_for(std::chrono::seconds(rand() % 5));

        // Check if there are any new files to process
        bool hasNewFiles = false;
        {
            std::unique_lock<std::mutex> lock(g_fileMapMutex);
            hasNewFiles = !fileMap.empty();
        }

        // If there are no new files, continue loop
        if (!hasNewFiles) {
            continue;
        }

        // Process the new files concurrently using futures
        std::vector<std::future<void>> futures;
        {
            std::unique_lock<std::mutex> lock(g_fileMapMutex);

            // Iterate over the files in the hash table
            for (const auto& file : fileMap) {
                // Create a future for each file to process concurrently
                futures.emplace_back(std::async(std::launch::async, [=]() {
                    // Load the file into memory and split it into words
                    std::ifstream fileStream(file.first);
                    std::string line;
                    while (getline(fileStream, line)) {
                        // Split the line into words using whitespace as delimiter
                        std::vector<std::string> words = split(line, ' ');
                        for (const auto& word : words) {
                            // Update the hash table with the new word
                            fileMap[word].push_back(file.second);
                        }
                    }
                }));
            }
        }

        // Wait for all futures to complete
        std::for_each(futures.begin(), futures.end(), [](auto& future) { future.wait(); });

        // Remove the files from the hash table and update the vector of text files
        {
            std::unique_lock<std::mutex> lock(g_fileMapMutex);
            for (const auto& file : fileMap) {
                // Update the vector of text files with the new file
                textFiles.push_back({file.first, file.second, {}});
            }

            // Clear the hash table and free up memory
            fileMap.clear();
        }
    }
}
