#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>

// Define the structure to hold the record data
struct Record {
    int key;
    long offset;
};

// Define the linked list node to store the records
struct LinkedListNode {
    struct Record *record;
    struct LinkedListNode *next;
};

// Define the hash table to map keys to linked list nodes
struct HashTable {
    int size;
    struct LinkedListNode **nodes;
};

// Initialize the hash table with a given size
void init_hash_table(struct HashTable *ht, int size) {
    ht->size = size;
    ht->nodes = (struct LinkedListNode**) malloc(sizeof(struct LinkedListNode*) * size);
    memset(ht->nodes, 0, sizeof(struct LinkedListNode*) * size);
}

// Insert a record into the hash table
void insert_record(struct HashTable *ht, struct Record *rec) {
    // Calculate the hash value for the key
    int hash = rec->key % ht->size;

    // Create a new linked list node for the record
    struct LinkedListNode *node = (struct LinkedListNode*) malloc(sizeof(struct LinkedListNode));
    node->record = rec;
    node->next = ht->nodes[hash];

    // Insert the node into the hash table
    ht->nodes[hash] = node;
}

// Lookup a record in the hash table
struct Record *lookup_record(struct HashTable *ht, int key) {
    // Calculate the hash value for the key
    int hash = key % ht->size;

    // Search for the record in the linked list starting from the head node
    struct LinkedListNode *node = ht->nodes[hash];
    while (node != NULL) {
        if (node->record->key == key) {
            return node->record;
        }
        node = node->next;
    }

    // If the record is not found, return NULL
    return NULL;
}

// Update a record in the hash table
void update_record(struct HashTable *ht, struct Record *rec) {
    // Lookup the record in the hash table
    struct Record *old_rec = lookup_record(ht, rec->key);

    // If the record is found, update it
    if (old_rec != NULL) {
        old_rec->offset = rec->offset;
    } else {
        // If the record is not found, insert a new one
        struct LinkedListNode *node = (struct LinkedListNode*) malloc(sizeof(struct LinkedListNode));
        node->record = rec;
        node->next = ht->nodes[rec->key % ht->size];
        ht->nodes[rec->key % ht->size] = node;
    }
}

// Delete a record from the hash table
void delete_record(struct HashTable *ht, int key) {
    // Lookup the record in the hash table
    struct Record *old_rec = lookup_record(ht, key);

    // If the record is found, delete it
    if (old_rec != NULL) {
        // Remove the node from the linked list
        int hash = key % ht->size;
        struct LinkedListNode **node = &ht->nodes[hash];
        while (*node != NULL && (*node)->record != old_rec) {
            node = &(*node)->next;
        }
        if (*node != NULL) {
            *node = (*node)->next;
        }
    }
}

// Persist the records to disk periodically
void persist_records(struct HashTable *ht, char *filename) {
    // Open the file for writing
    int fd = open(filename, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Write the records to disk
    struct LinkedListNode *node = ht->nodes[0];
    while (node != NULL) {
        int written = write(fd, node->record, sizeof(struct Record));
        if (written == -1) {
            perror("write");
            exit(EXIT_FAILURE);
        }
        node = node->next;
    }

    // Close the file
    close(fd);
}

// Load the records from disk
void load_records(struct HashTable *ht, char *filename) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Read the records from disk
    struct Record rec;
    while (read(fd, &rec, sizeof(struct Record)) > 0) {
        insert_record(ht, &rec);
    }

    // Close the file
    close(fd);
}
```
This implementation provides a hash table with a linked list data structure to store the records. The hash table is initialized with a given size and has a vector of pointers to linked list nodes. Each node in the linked list stores a record with an integer key and a long offset. The functions `insert_record`, `lookup_record`, `update_record`, and `delete_record` are used to insert, lookup, update, and delete records in the hash table respectively.

The `persist_records` function is responsible for persisting the records to disk periodically. It opens the file for writing, writes the records to disk using a loop, and closes the file. The `load_records` function is used to load the records from disk. It opens the file for reading, reads the records into the hash table using a loop, and closes the file.

The `main` function demonstrates how to use the functions in the implementation to insert, lookup, update, delete, persist, and load records. The example also shows how to handle edge cases such as invalid input, null pointers, and out-of-memory conditions.']

