public class HttpGetRequestProcessor {
    private static final Logger logger = LoggerFactory.getLogger(HttpGetRequestProcessor.class);

    private DataProcessingService dataProcessingService;
    private Cache<String, Object> cache;

    public HttpGetRequestProcessor(DataProcessingService dataProcessingService, int cacheSize) {
        this.dataProcessingService = dataProcessingService;
        this.cache = new LRUCache<>(cacheSize);
    }

    public void processRequest(String userId, String chartId, JSONObject payload) throws Exception {
        // Validate request against predefined business rules
        if (!isValidRequest(userId, chartId)) {
            throw new IllegalArgumentException("Invalid request");
        }

        // Check cache for existing data
        Object cachedData = cache.get(chartId);
        if (cachedData != null) {
            logger.info("Cache hit for chart ID: " + chartId);
            return;
        }

        // Fetch and process data asynchronously
        CompletableFuture<Object> future = CompletableFuture.supplyAsync(() -> {
            try {
                return dataProcessingService.processData(payload);
            } catch (Exception e) {
                logger.error("Error processing data", e);
                throw new RuntimeException(e);
            }
        });

        // Store future in cache
        cache.put(chartId, future);
    }

    private boolean isValidRequest(String userId, String chartId) {
        return !userId.isEmpty() && !chartId.isEmpty();
    }
}
```
