class EventProcessor {
public:
    EventProcessor(int incrementFactor, int scalingFactor) : incrementFactor_(incrementFactor), scalingFactor_(scalingFactor) {}

    void addRecord(const EventRecord& record);
    void processRecords();
    std::vector<EventRecord> queryRecords(int lowerBoundKey, int upperBoundKey);

private:
