// Define the helper function to find the largest integer in an array of integers
void findLargestInteger(std::vector<int>& input) {
    int largest = std::numeric_limits<int>::min();
    for (auto& num : input) {
        if (num > largest) {
            largest = num;
        }
    }
    std::cout << "The largest integer in the array is: " << largest << std::endl;
}

// Define the function to validate input and prevent invalid data from affecting the operation of the event processor
void validateInput(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("The input vector must not be empty");
    } else if (std::any_of(input.begin(), input.end(), [](auto num){ return num < 0; })) {
        throw std::invalid_argument("All elements in the input vector must be non-negative");
    }
}

// Define the function to allocate memory for a new record and fill it with the given data
void EventProcessor::addRecord(const EventRecord& record) {
    // Acquire the mutex to protect concurrent access to the records vector
    std::lock_guard<std::mutex> lock(mutex_);

    // Validate the input data and prevent invalid data from affecting the operation of the event processor
    validateInput(record.description);

    // Create a new record object with the given data and calculate its key using the increment factor and scaling factor
    EventRecord newRecord;
    newRecord.key = static_cast<int>(std::ceil(record.measurement * scalingFactor_) + incrementFactor_);
    newRecord.measurement = record.measurement;
    newRecord.timestamp = record.timestamp;
    newRecord.description = std::move(record.description);

    // Add the new record to the records vector and update the descriptions map if necessary
    records_.push_back(std::move(newRecord));
    auto& desc = descriptions_[record.description];
    ++desc.count;
}

// Define the function to process all records in the system and apply any necessary scaling or filtering based on timestamps
void EventProcessor::processRecords() {
    // Acquire the mutex to protect concurrent access to the records vector and descriptions map
    std::lock_guard<std::mutex> lock(mutex_);

    // Apply any necessary scaling or filtering based on timestamps

    // Update the descriptions map with the latest usage counts for each description string
    for (auto& desc : descriptions_) {
        auto& count = desc.second.count;
        if (count > 0) {
            --count;
        } else {
            descriptions_.erase(desc.first);
        }
    }
}

// Define the function to query records in the system based on a range of keys, supporting both inclusive and exclusive bounds
std::vector<EventRecord> EventProcessor::queryRecords(int lowerBoundKey, int upperBoundKey) {
    // Acquire the mutex to protect concurrent access to the records vector
    std::lock_guard<std::mutex> lock(mutex_);

    // Filter the records based on the specified range of keys and return the results
    auto lowerIt = std::lower_bound(records_.begin(), records_.end(), lowerBoundKey, [](const EventRecord& record, int key) {
        return record.key < key;
    });
    auto upperIt = std::upper_bound(lowerIt, records_.end(), upperBoundKey, [](int key, const EventRecord& record) {
        return key < record.key;
    });
    return std::vector<EventRecord>(lowerIt, upperIt);
}

