use std::process::Command;
use std::time::Instant;
use std::thread::sleep;

fn compile_and_measure() -> i32 {
    // Load resource bundle from file
    let bundle = load_resource_bundle("path/to/resource.json");
    if bundle.is_err() {
        return 1;
    }

    // Install custom logging hook
    log::set_logger(&bundle.unwrap());
    log::set_max_level(log::LevelFilter::Debug);

    // Measure time and resident set size before compilation
    let start = Instant::now();
    let mut rss_before = 0;
    let mut cmd = Command::new("rustc");
    cmd.arg("--test").arg("src/main.rs");
    match cmd.output() {
        Ok(output) => {
            // Measure time and resident set size after compilation
            let end = Instant::now();
            let mut rss_after = 0;
            if !output.status.success() {
                log!("Compilation failed");
                return 1;
            } else {
                for line in output.stderr.lines() {
                    if line.contains("warning") || line.contains("error") {
                        // Log any warnings or errors from the compilation process
                        log!(line);
                    }
                }
                rss_after = get_rss();
            }

            let duration = end - start;
            let elapsed = duration.as_secs() as f64 + duration.subsec_nanos() as f64 / 1e9;
            log!("Compilation time: {:?} seconds", elapsed);
            log!("Resident set size before: {} bytes", rss_before);
            log!("Resident set size after: {} bytes", rss_after);
        }
        Err(error) => {
            // Log any errors from the compilation process
            log!("Compilation failed with error: {}", error);
            return 1;
        }
    }

    return 0;
}

fn load_resource_bundle(path: &str) -> Result<ResourceBundle, String> {
    // Dynamically allocate memory for the bundle and its items
    let mut bundle = Vec::new();
    let f = File::open(path).unwrap();
    let reader = BufReader::new(f);
    for line in reader.lines() {
        if let Ok(line) = line {
            // Parse each line of the resource file as a logging item
            let item: LoggingItem = serde_json::from_str(&line).unwrap();
            bundle.push(item);
        } else {
            return Err("Failed to parse logging item".to_string());
        }
    }

    // Return the loaded resource bundle
    Ok(bundle)
}
