// Define the record structure
typedef struct {
    int value;
} Record;

// Define the array of records
Record* records = NULL;

// Define the number of records
int num_records = 0;

// Define the maximum number of records
#define MAX_RECORDS 10000000

// Define the range of values for the randomizer
#define MIN_VALUE 1
#define MAX_VALUE 100

// Function to initialize the record array
void initRecords() {
    // Allocate memory for the records
    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));

    // Check if memory allocation failed
    if (records == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the records
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }

    num_records = MAX_RECORDS;
}

// Function to deallocate all allocated memory
void freeRecords() {
    // Check if the records array is not NULL
    if (records != NULL) {
        // Free the memory for the records
        free(records);
        records = NULL;
    }
}

// Function to read a list of integers from standard input and store them in an array
void readInput() {
    int input_size = 0;
    printf("Enter the number of integers to read: ");
    scanf("%d", &input_size);

    // Check if the input size is greater than the maximum number of records
    if (input_size > MAX_RECORDS) {
        printf("Error: Input size exceeds maximum number of records\n");
        return;
    }

    // Allocate memory for the input array
    int* input = (int*)malloc(input_size * sizeof(int));

    // Check if memory allocation failed
    if (input == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Read the integers from standard input and store them in the array
    for (int i = 0; i < input_size; i++) {
        scanf("%d", &input[i]);
    }

    // Find the largest integer in the array
    int largest = -1;
    for (int i = 0; i < input_size; i++) {
        if (input[i] > largest) {
            largest = input[i];
        }
    }

    // Print the largest integer
    printf("Largest integer: %d\n", largest);

    // Free the memory for the input array
    free(input);
}

// Function to resize the record array when necessary
void resizeRecords() {
    // Check if the number of records exceeds the maximum number of records
    if (num_records > MAX_RECORDS) {
        // Reallocate memory for the records with a larger size
        Record* new_records = (Record*)realloc(records, (2 * MAX_RECORDS) * sizeof(Record));

        // Check if memory reallocation failed
        if (new_records == NULL) {
            printf("Error: Memory reallocation failed\n");
            return;
        }

        records = new_records;
        num_records = 2 * MAX_RECORDS;
    }
}

// Main function
int main() {
    initRecords();

    // Loop until the user enters a negative number to indicate that they are done entering integers
    while (1) {
        int input = -1;
        printf("Enter an integer (negative to stop): ");
        scanf("%d", &input);

        if (input < 0) {
            break;
        }

        // Check if the number of records exceeds the maximum number of records
        if (num_records >= MAX_RECORDS) {
            resizeRecords();
        }

        // Add the new integer to the record array
        records[num_records].value = input;
        num_records++;
    }

    readInput();

    freeRecords();

    return 0;
}
