#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

// Define the record structure
struct Record {
    long offset;
    int key;
    int value;
    char data[10];
};

// Define the dynamic array structures for offsets, keys, and records
typedef struct {
    size_t capacity; // current capacity of the array
    size_t size; // current number of elements in the array
    long *offsets; // pointer to the offsets array
} DynamicOffsetArray;

typedef struct {
    size_t capacity; // current capacity of the array
    size_t size; // current number of elements in the array
    int *keys; // pointer to the keys array
} DynamicKeyArray;

typedef struct {
    size_t capacity; // current capacity of the array
    size_t size; // current number of elements in the array
    struct Record *records; // pointer to the records array
} DynamicRecordArray;

// Define the library's main structure
typedef struct {
    pthread_mutex_t mutex; // mutex for thread safety
    DynamicOffsetArray offsets; // dynamic array for offsets
    DynamicKeyArray keys; // dynamic array for keys
    DynamicRecordArray records; // dynamic array for records
} DataManager;

// Define the library's functions
DataManager *data_manager_init(void);
int data_manager_add(DataManager *self, long offset, int key, int value, char *data);
void data_manager_free(DataManager *self);
void data_manager_print(DataManager *self);

// Implementation of the library's functions

// Initialize the DataManager structure and return a pointer to it
DataManager *data_manager_init(void) {
    DataManager *self = (DataManager *)malloc(sizeof(DataManager));
    if (!self) {
        perror("Error allocating memory for data manager");
        exit(1);
    }

    // Initialize the mutex
    pthread_mutex_init(&self->mutex, NULL);

    // Initialize the dynamic arrays
    self->offsets.capacity = 16;
    self->offsets.size = 0;
    self->offsets.offsets = (long *)malloc(self->offsets.capacity * sizeof(long));
    if (!self->offsets.offsets) {
        perror("Error allocating memory for offsets array");
        exit(1);
    }
    self->keys.capacity = 16;
    self->keys.size = 0;
    self->keys.keys = (int *)malloc(self->keys.capacity * sizeof(int));
    if (!self->keys.keys) {
        perror("Error allocating memory for keys array");
        exit(1);
    }
    self->records.capacity = 16;
    self->records.size = 0;
    self->records.records = (struct Record *)malloc(self->records.capacity * sizeof(struct Record));
    if (!self->records.records) {
        perror("Error allocating memory for records array");
        exit(1);
    }

    return self;
}

// Add a record to the DataManager structure and return 0 on success, or -1 on failure
int data_manager_add(DataManager *self, long offset, int key, int value, char *data) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&self->mutex);

    // Check if the dynamic arrays need to be resized
    if (self->records.size >= self->records.capacity) {
        // Resize the records array by a factor of 2
        size_t new_capacity = self->records.capacity * 2;
        struct Record *new_records = (struct Record *)realloc(self->records.records, new_capacity * sizeof(struct Record));
        if (!new_records) {
            perror("Error resizing records array");
            pthread_mutex_unlock(&self->mutex);
            return -1;
        }
        self->records.capacity = new_capacity;
        self->records.records = new_records;
    }

    // Add the record to the records array
    struct Record *record = &self->records.records[self->records.size++];
    record->offset = offset;
    record->key = key;
    record->value = value;
    strncpy(record->data, data, 10);

    // Unlock the mutex
    pthread_mutex_unlock(&self->mutex);

    return 0;
}

// Free all memory allocated by the DataManager structure
void data_manager_free(DataManager *self) {
    if (!self) {
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&self->mutex);

    // Free the dynamic arrays
    free(self->offsets.offsets);
    self->offsets.offsets = NULL;
    free(self->keys.keys);
    self->keys.keys = NULL;
    free(self->records.records);
    self->records.records = NULL;

    // Free the mutex
    pthread_mutex_destroy(&self->mutex);

    // Free the DataManager structure
    free(self);
}

// Print all records in the DataManager structure
void data_manager_print(DataManager *self) {
    if (!self) {
        return;
    }

    printf("Records:\n");
    for (size_t i = 0; i < self->records.size; i++) {
        struct Record *record = &self->records.records[i];
        printf("%ld %d %d %s\n", record->offset, record->key, record->value, record->data);
    }
}
