// C library for managing dynamic collections of network packets
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Packet structure
typedef struct packet {
    uint32_t timestamp; // Timestamp in milliseconds
    uint16_t packet_id; // Unique identifier for the packet
    char payload[150]; // Payload data (up to 150 bytes)
    uint8_t flags; // Packet type (data or control)
} packet_t;

// Linked list node for managing packets
typedef struct node {
    packet_t *packet;
    struct node *next;
} node_t;

// Linked list header for managing packets
typedef struct list {
    node_t *head; // Head of the linked list
    node_t *tail; // Tail of the linked list
    size_t size; // Number of packets in the list
} list_t;

// Initialize a new packet structure with default values
packet_t* init_packet() {
    packet_t *packet = (packet_t*) malloc(sizeof(packet_t));
    if (!packet) {
        printf("Failed to allocate memory for packet\n");
        return NULL;
    }
    memset(packet, 0, sizeof(packet_t));
    return packet;
}

// Initialize a new linked list node with the given packet
node_t* init_node(packet_t *packet) {
    node_t *node = (node_t*) malloc(sizeof(node_t));
    if (!node) {
        printf("Failed to allocate memory for node\n");
        return NULL;
    }
    memset(node, 0, sizeof(node_t));
    node->packet = packet;
    return node;
}

// Initialize a new linked list with the given capacity
list_t* init_list(size_t capacity) {
    list_t *list = (list_t*) malloc(sizeof(list_t));
    if (!list) {
        printf("Failed to allocate memory for list\n");
        return NULL;
    }
    memset(list, 0, sizeof(list_t));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    // Dynamically allocate memory for the linked list nodes
    node_t *node = (node_t*) malloc(sizeof(node_t) * capacity);
    if (!node) {
        printf("Failed to allocate memory for nodes\n");
        free(list);
        return NULL;
    }
    memset(node, 0, sizeof(node_t) * capacity);
    list->head = node;
    list->tail = node + (capacity - 1);
    return list;
}

// Add a packet to the linked list
void add_packet(list_t *list, packet_t *packet) {
    if (!list || !packet) {
        printf("Invalid arguments\n");
        return;
    }
    node_t *node = init_node(packet);
    if (!node) {
        printf("Failed to allocate memory for node\n");
        return;
    }
    // If the linked list is empty, set the head and tail pointers
    if (list->size == 0) {
        list->head = node;
        list->tail = node;
    } else {
        // Add the new node to the end of the linked list
        list->tail->next = node;
        list->tail = node;
    }
    // Increment the size of the linked list
    list->size++;
}

// Remove a packet from the linked list
packet_t* remove_packet(list_t *list) {
    if (!list || list->size == 0) {
        printf("Invalid arguments\n");
        return NULL;
    }
    // Get the head node of the linked list
    packet_t *packet = list->head->packet;
    // Update the head pointer to point to the next node in the linked list
    list->head = list->head->next;
    // Decrement the size of the linked list
    list->size--;
    return packet;
}

// Read a packet from a binary log file and add it to the linked list
void read_packet(list_t *list, FILE *file) {
    if (!list || !file) {
        printf("Invalid arguments\n");
        return;
    }
    // Allocate memory for the packet structure
    packet_t *packet = init_packet();
    if (!packet) {
        printf("Failed to allocate memory for packet\n");
        return;
    }
    // Read the timestamp, packet ID, and payload data from the binary log file
    fread(&(packet->timestamp), sizeof(uint32_t), 1, file);
    fread(&(packet->packet_id), sizeof(uint16_t), 1, file);
    fread(packet->payload, sizeof(char), 150, file);
    // Add the packet to the linked list
    add_packet(list, packet);
}

// Write a packet from the linked list to a binary log file
void write_packet(list_t *list, FILE *file) {
    if (!list || !file) {
        printf("Invalid arguments\n");
        return;
    }
    // Get the head node of the linked list
    packet_t *packet = list->head->packet;
    // Write the timestamp, packet ID, and payload data to the binary log file
    fwrite(&(packet->timestamp), sizeof(uint32_t), 1, file);
    fwrite(&(packet->packet_id), sizeof(uint16_t), 1, file);
    fwrite(packet->payload, sizeof(char), 150, file);
}

// Free the memory allocated for a linked list
void free_list(list_t *list) {
    if (!list) {
        printf("Invalid arguments\n");
        return;
    }
    // Free the memory allocated for each node in the linked list
    while (list->head != NULL) {
        node_t *node = list->head;
        list->head = list->head->next;
        free(node);
    }
    free(list);
}

// Free the memory allocated for a packet structure
void free_packet(packet_t *packet) {
    if (!packet) {
        printf("Invalid arguments\n");
        return;
    }
    free(packet);
}

int main() {
    // Initialize a linked list with the given capacity
    list_t *list = init_list(10);
    if (!list) {
        printf("Failed to initialize the linked list\n");
        return 1;
    }
    // Read packets from a binary log file and add them to the linked list
    FILE *file = fopen("packets.bin", "rb");
    if (file == NULL) {
        printf("Failed to open the binary log file\n");
        free_list(list);
        return 1;
    }
    while (!feof(file)) {
        read_packet(list, file);
    }
    fclose(file);
    // Print the number of packets in the linked list
    printf("Number of packets: %zu\n", list->size);
    // Iterate through the linked list and print each packet
    node_t *node = list->head;
    while (node != NULL) {
        packet_t *packet = node->packet;
        printf("Packet ID: %u, Timestamp: %u\n", packet->packet_id, packet->timestamp);
        node = node->next;
    }
    // Free the memory allocated for the linked list and each packet structure
    free_list(list);
    return 0;
}']

