// Function to initialize and populate an array of file records with random values
file_record** init_file_records(int num_records) {
    // Allocate memory for the array of file records
    file_record** records = malloc(num_records * sizeof(file_record*));
    if (records == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for file record array\n");
        return NULL;
    }

    // Initialize the array of file records with random values
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(file_record));
        if (records[i] == NULL) {
            fprintf(stderr, "Error: unable to allocate memory for file record %d\n", i);
            return NULL;
        }

        // Generate a random file size between 0 and 1024 MB
        records[i]->size = (double)rand() / RAND_MAX * 1024 * 1024;

        // Generate a random last modified timestamp between 1970-01-01 and current time
        records[i]->last_modified.tv_sec = time(NULL) - rand() % (int)(time(NULL) - 631152000); // 631152000 is the number of seconds in 70 years
        records[i]->last_modified.tv_nsec = 0;

        // Generate a random file path
        char* path = malloc(100 * sizeof(char));
        if (path == NULL) {
            fprintf(stderr, "Error: unable to allocate memory for file path\n");
            return NULL;
        }
        srand((unsigned int)time(NULL));
        char* chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        for (int j = 0; j < 100; j++) {
            path[j] = chars[rand() % 62];
        }
        records[i]->path = path;
    }

    return records;
}

// Function to free the memory allocated for an array of file records
void free_file_records(file_record** records, int num_records) {
    if (records == NULL) {
        return;
    }

    // Free each record in the array
    for (int i = 0; i < num_records; i++) {
        free(records[i]->path);
        records[i]->path = NULL;
    }

    // Free the memory allocated for the array of file records
    free(records);
}
