// Struct to represent a sensor data point
struct sensor_data {
    long timestamp;
    float temperature;
    char description[256];
};

// Function to dynamically allocate memory for and initialize the three arrays
void init_sensor_data(int num_sensors, int max_desc_len) {
    // Allocate memory for the timestamps array
    long *timestamps = malloc(num_sensors * sizeof(long));
    if (!timestamps) {
        printf("Failed to allocate memory for timestamps\n");
        return;
    }

    // Initialize the timestamps array with default values
    for (int i = 0; i < num_sensors; i++) {
        timestamps[i] = 0;
    }

    // Allocate memory for the temperature readings array
    float *temperatures = malloc(num_sensors * sizeof(float));
    if (!temperatures) {
        printf("Failed to allocate memory for temperatures\n");
        free(timestamps);
        return;
    }

    // Initialize the temperature readings array with default values
    for (int i = 0; i < num_sensors; i++) {
        temperatures[i] = NAN;
    }

    // Allocate memory for the descriptions array
    char **descriptions = malloc(num_sensors * sizeof(char*));
    if (!descriptions) {
        printf("Failed to allocate memory for descriptions\n");
        free(timestamps);
        free(temperatures);
        return;
    }

    // Initialize the descriptions array with default values
    for (int i = 0; i < num_sensors; i++) {
        descriptions[i] = calloc(max_desc_len, sizeof(char));
        if (!descriptions[i]) {
            printf("Failed to allocate memory for description %d\n", i);
            free(timestamps);
            free(temperatures);
            free(descriptions);
            return;
        }
    }

    // Initialize the linked list of sensor data points
    struct sensor_data *head = NULL, *current = NULL;

    // Iterate over each sensor and initialize its corresponding array elements
    for (int i = 0; i < num_sensors; i++) {
        current = malloc(sizeof(struct sensor_data));
        if (!current) {
            printf("Failed to allocate memory for sensor data point %d\n", i);
            free(timestamps);
            free(temperatures);
            free(descriptions);
            return;
        }

        current->timestamp = timestamps[i];
        current->temperature = temperatures[i];
        strncpy(current->description, descriptions[i], max_desc_len - 1);
        current->description[max_desc_len - 1] = '\0';

        if (head == NULL) {
            head = current;
        } else {
            current->prev = head;
            head->next = current;
            head = head->next;
        }
    }

    // Free the memory allocated for the arrays and return the linked list of sensor data points
    free(timestamps);
    free(temperatures);
    free(descriptions);
    return head;
}

// Function to validate temperature readings and truncate description strings if necessary
void validate_sensor_data(struct sensor_data *head) {
    struct sensor_data *current = head;
    while (current != NULL) {
        // Validate the temperature reading
        if (current->temperature < -50 || current->temperature > 120) {
            printf("Invalid temperature reading: %f\n", current->temperature);
            current->temperature = NAN;
        }

        // Truncate the description string if necessary
        if (strlen(current->description) >= max_desc_len - 1) {
            printf("Truncating description for sensor data point: %d\n", i);
            current->description[max_desc_len - 1] = '\0';
        }

        // Move to the next sensor data point
        current = current->next;
    }
}

// Function to handle potential mismatches between expected and actual data formats
void handle_data_format_mismatch(struct sensor_data *head) {
    struct sensor_data *current = head;
    while (current != NULL) {
        // Check if the data format is mismatched
        if (current->timestamp == 0 || current->temperature == NAN) {
            printf("Data format mismatch detected for sensor data point: %d\n", i);

            // Handle the data format mismatch gracefully
            // ...
        }

        // Move to the next sensor data point
        current = current->next;
    }
}

// Function to manage resources and prevent memory leaks
void cleanup_sensor_data(struct sensor_data *head) {
    struct sensor_data *current = head;
    while (current != NULL) {
        // Free the memory allocated for the timestamp, temperature reading, and description strings
        free(current->timestamp);
        free(current->temperature);
        free(current->description);

        // Move to the next sensor data point
        current = current->next;
    }
}
