        printf("Out-of-range temperature reading: %f. Setting to default value.\n", temperature);
        new_data->temperature = DEFAULT_TEMPERATURE;
    }

    // Add the new node to the linked list
    struct linked_list *new_node = malloc(sizeof(struct linked_list));
    new_node->data = new_data;
    new_node->next = NULL;
    if (*head == NULL) {
        *head = new_node;
    } else {
        struct linked_list *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void remove_oldest_node(struct linked_list **head) {
    // Remove the oldest node from the linked list and free its memory
    struct linked_list *current = *head;
    while (current->next != NULL && current->next->next != NULL) {
        current = current->next;
    }
    if (current->next == NULL) {
        printf("Cannot remove oldest node: list is empty.\n");
    } else {
        struct linked_list *oldest = current->next;
        current->next = NULL;
        free(oldest);
        printf("Removed oldest node from the list.\n");
    }
}

int size_of_linked_list(struct linked_list *head) {
    int size = 0;
    struct linked_list *current = head;
    while (current != NULL) {
        current = current->next;
        size++;
    }
    return size;
}

void free_linked_list(struct linked_list **head) {
    // Free the memory of all nodes in the linked list
    struct linked_list *current = *head;
    while (current != NULL) {
        struct linked_list *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    *head = NULL;
}
