    if (!arr) {
        perror("Failed to allocate memory for array");
        return NULL;
    }
    memset(arr, 0, sizeof(SensorData) * numElements);
    return arr;
}

// Function to dynamically allocate memory for a linked list
Node* allocateLinkedList() {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for linked list");
        return NULL;
    }
    memset(node, 0, sizeof(Node));
    return node;
}

// Function to initialize the linked list with a given number of nodes
void initializeLinkedList(int numNodes) {
    // Allocate memory for the head node and set its next pointer to NULL
    head = allocateLinkedList();
    head->next = NULL;

    // Create a temporary pointer to iterate through the linked list
    Node* current = head;

    // Initialize the sensor data fields in each node
    for (int i = 0; i < numNodes; i++) {
        SensorData* data = &current->data;
        data->timestamp = 0;
        data->temperature = 0.0f;
        memset(data->description, '\0', sizeof(data->description));

        // If there are more nodes to be created, create them and set the next pointer
        if (i < numNodes - 1) {
            current->next = allocateLinkedList();
            current = current->next;
        }
    }
}

// Function to add sensor data to the linked list
void addSensorData(SensorData* data) {
