        *nodeData = *data;

        // If there are more nodes to be created, create them and set the next pointer
        if (i < numNodes - 1) {
            current->next = allocateLinkedList();
            current = current->next;
        } else {
            break;
        }
    }
}

// Function to free memory for a linked list
void freeLinkedList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Function to read sensor data from a file and add it to the linked list
