    while (current != NULL && fscanf(fp, "%ld,%f,%s", &current->data.timestamp, &current->data.temperature, current->data.description) == 3) {
        if (!isValidTemperature(current->data.temperature)) {
            // Handle invalid temperature readings gracefully by ignoring them or storing them in a separate list
            continue;
        }

        // If there are more nodes to be created, create them and set the next pointer
        if (i < numNodes - 1) {
            current->next = allocateLinkedList();
            current = current->next;
        } else {
            break;
        }
    }

    // Close the file
    fclose(fp);
}

// Function to read sensor data from a network stream and add it to the linked list
void readNetworkStream(int socket, int numNodes) {
