```java
import java.util.*;
import java.lang.Math;
import java.util.concurrent.atomic.AtomicLong;

public class EventManager {
  private static final long MAX_MEMORY = 1024 * 1024 * 1024; // 1 GB
  private static final int MAX_RECORDS = 1_000_000_000; // 1 billion records
  private static final String[] CATEGORIES = {"Category A", "Category B", "Category C"};

  private AtomicLong totalMemoryUsage = new AtomicLong();
  private Map<String, EventRecord> eventRecords = new HashMap<>();

  public synchronized void addEvent(long timestamp, String category) {
    if (eventRecords.size() >= MAX_RECORDS) {
      throw new IllegalStateException("Maximum number of records reached");
    }

    EventRecord record = new EventRecord(timestamp, category);
    eventRecords.put(record.getId(), record);

    totalMemoryUsage.addAndGet(Math.max(record.getByteSize(), 0));
  }

  public synchronized void removeEvent(String id) {
    EventRecord record = eventRecords.remove(id);
    if (record != null) {
      totalMemoryUsage.addAndGet(-Math.max(record.getByteSize(), 0));
    }
  }

  public synchronized List<EventRecord> getEvents() {
    return new ArrayList<>(eventRecords.values());
  }

  public synchronized long getTotalMemoryUsage() {
    return totalMemoryUsage.get();
  }

  private static class EventRecord {
    private final long timestamp;
    private final String category;
    private final double duration;

    public EventRecord(long timestamp, String category) {
      this.timestamp = timestamp;
      this.category = category;
      this.duration = randomDuration();
    }

    public long getTimestamp() {
      return timestamp;
    }

    public String getCategory() {
      return category;
    }

    public double getDuration() {
      return duration;
    }

    private double randomDuration() {
      // Custom random value generator
      Random random = new Random();
      return Math.min(random.nextDouble(), 100) * 60 * 1000;
    }
  }
}
```
