    int largest = find_largest_integer(db);
    if (largest != -1) {
        printf("Largest integer: %d\n", largest);
    } else {
        fprintf(stderr, "No integers found\n");
    }

    // Free the memory associated with the database and its records
    free_database(db);

    return 0;
}

// Reads a list of integers from standard input and stores them in an array
void read_list(int* list, size_t* n) {
    // Get the number of integers to read
    printf("Enter the number of integers: ");
    scanf("%zu", n);

    // Check if the number is valid
    if (*n > INT_MAX || *n < 0) {
        fprintf(stderr, "Invalid number of integers\n");
        exit(1);
    }

    // Allocate memory for the array
    list = malloc(*n * sizeof(int));
    if (!list) {
        fprintf(stderr, "Error allocating memory for integer list\n");
        exit(1);
    }

    // Read the integers from standard input and store them in the array
    for (size_t i = 0; i < *n; ++i) {
        printf("Enter integer %zu: ", i + 1);
        scanf("%d", &list[i]);
    }
}

// Prints the largest integer in an array of integers
void print_largest_integer(int* list, size_t n) {
    // Check if the array is empty
    if (n == 0) {
        fprintf(stderr, "No integers found\n");
        return;
    }

    // Initialize the largest integer to the first element in the array
    int largest = list[0];

    // Compare each element in the array with the current largest integer
    for (size_t i = 1; i < n; ++i) {
        if (list[i] > largest) {
            largest = list[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

// Creates a new database with an initial capacity of 1000 records
struct Database* create_database() {
    // Allocate memory for the database and its records
    struct Database* db = malloc(sizeof(struct Database));
    if (!db) {
        fprintf(stderr, "Error allocating memory for database\n");
        exit(1);
    }
    db->records = malloc(POOL_SIZE);
    if (!db->records) {
        fprintf(stderr, "Error allocating memory for records\n");
        exit(1);
    }
    db->num_records = 0;
    db->capacity = POOL_SIZE / sizeof(struct Record);

    return db;
}

// Finds a record in the database with the given ID, or -1 if not found
int find_record(struct Database* db, int id) {
    // Check if the ID is valid
    if (id < 0 || id >= db->num_records) {
        return -1;
    }

    // Linear search for the record with the given ID
    for (size_t i = 0; i < db->num_records; ++i) {
        if (db->records[i].id == id) {
            return i;
        }
    }

    // Return -1 if the record was not found
    return -1;
}

// Adds a new record to the database, or returns 0 on failure
int add_record(struct Database* db, struct Record* rec) {
    // Check if the database is full
    if (db->num_records == db->capacity) {
        resize_database(db, 2 * db->capacity);
    }

    // Add the new record to the end of the database
    db->records[db->num_records++] = *rec;

    return 1;
}

// Removes a record from the database with the given ID, or returns 0 on failure
int remove_record(struct Database* db, int id) {
    // Find the index of the record with the given ID
    size_t idx = find_record(db, id);
    if (idx == -1) {
        return 0;
    }

    // Shift all records after the one to be removed towards the beginning of the array
    for (size_t i = idx + 1; i < db->num_records; ++i) {
        db->records[i - 1] = db->records[i];
    }

    // Decrement the number of records in the database
    --db->num_records;

    return 1;
}

// Frees the memory associated with the database and its records
void free_database(struct Database* db) {
    // Check if the database is empty
    if (db->num_records == 0) {
        fprintf(stderr, "No records found\n");
        return;
    }

    // Free the memory associated with each record in the database
    for (size_t i = 0; i < db->num_records; ++i) {
        free(&db->records[i]);
    }

    // Free the memory associated with the database and its records
    free(db->records);
    free(db);
}

// Resizes the database to have a new capacity, preserving existing records
void resize_database(struct Database* db, size_t new_capacity) {
    // Check if the new capacity is valid
    if (new_capacity < 1 || new_capacity > POOL_SIZE / sizeof(struct Record)) {
        fprintf(stderr, "Invalid new capacity\n");
        return;
    }

    // Allocate memory for the new records array and copy over existing records
    struct Record* new_records = malloc(new_capacity * sizeof(struct Record));
    if (!new_records) {
        fprintf(stderr, "Error allocating memory for new records\n");
        exit(1);
    }
    memcpy(new_records, db->records, db->num_records * sizeof(struct Record));

    // Free the old records array and assign the new one to the database
    free(db->records);
    db->records = new_records;
    db->capacity = new_capacity;
}

// Prints the memory usage of the database, including the number of records and their size
void print_memory_usage() {
    // Print the number of records in the database
    printf("Number of records: %zu\n", db->num_records);

    // Calculate the total size of all records in the database
    size_t record_size = sizeof(struct Record) + BLOCK_SIZE;
    size_t total_size = db->num_records * record_size;

    // Print the total size of all records in the database
    printf("Total size: %zu bytes\n", total_size);
}
