void process_input(const char* input, long offset[], int key[], Record* records, Stats* stats) {
    // Initialize the statistics structure
    stats->total_records = 0;
    stats->max_value = INT_MIN;
    stats->memory_usage = 0;

    // Read the input sequence of integers
    int n = 0;
    while (fscanf(input, "%d", &n) == 1) {
