        if (n > stats->max_value) {
            stats->max_value = n;
        }
        stats->total_records++;

        // Allocate memory for the record
        records[stats->total_records - 1].value = n;
        stats->memory_usage += sizeof(Record);

        // Calculate the offset
        offset[stats->total_records - 1] = (long)key[stats->total_records - 1] * INCREMENT_FACTOR;
    }
}

void generate_random_values(int key[], int max_value, Record* records, size_t num_records) {
