    process_input(input_file, offset, key, records, &stats);

    // Generate random values for the keys and records
    generate_random_values(key, MAX_VALUE, records, stats.total_records);

    // Calculate the offsets
    for (size_t i = 0; i < stats.total_records; i++) {
        offset[i] = key[i] * INCREMENT_FACTOR;
    }

