    while (fscanf(file, "%d %d %s %ld", &((*list)[*size].id), &((*list)[*size].priority), (*list)[*size].status, &((*list)[*size].last_updated)) != EOF) {
        // Increment the size of the list by 1
        *size = *size + 1;
    }
}

