    // Copy non-zero values from the records array into the compressed arrays
    int count = 0;
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset != 0) {
            (*keys)[count] = records[i].key;
            (*offsets)[count++] = records[i].offset;
        }
    }
}

// Persistently store the records to disk periodically
void persist() {
    // Open a file for writing and write each record to it
    FILE *file = fopen("records.dat", "wb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for writing\n");
        return;
    }

    // Write the number of records and each record to the file
    int num_written = fwrite(&num_records, sizeof(int), 1, file);
    if (num_written != 1) {
        fprintf(stderr, "Error: Failed to write %d records\n", num_records);
        return;
    }
    for (int i = 0; i < num_records; i++) {
        int written = fwrite(&records[i], sizeof(struct record), 1, file);
        if (written != 1) {
            fprintf(stderr, "Error: Failed to write record %d\n", i);
            return;
        }
    }

    // Close the file and remove it if there was an error writing to it
    int ret = fclose(file);
    if (ret == EOF) {
        unlink("records.dat");
    }
}

// Initialize the data store with a given number of records
void init(int num_records) {
    // Allocate memory for the array of records
    capacity = num_records;
    records = (struct record *)malloc(capacity * sizeof(struct record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for %d records\n", num_records);
        exit(1);
    }

    // Initialize each record with a random value and offset
    srand(time(NULL));
    for (int i = 0; i < capacity; i++) {
        records[i].value = rand() % config.random_value_range + 1;
        records[i].offset = rand() % config.max_sum + 1;
        records[i].key = i * config.key_increment_factor;
    }
}

// Read a list of integers from standard input and store them in an array
void read_input(int *input, int num_inputs) {
    // Allocate memory for the input array
    if (!input) {
        fprintf(stderr, "Error: Input array is null\n");
        return;
    }

    // Read each integer from standard input and store it in the array
    for (int i = 0; i < num_inputs; i++) {
        scanf("%d", &input[i]);
    }
}

// Find the largest integer in an array of integers
int find_largest(int *arr, int size) {
    // Return the last element if the array is empty
    if (size == 0) {
        return -1;
    }

    // Initialize the largest value to the first element
    int largest = arr[0];

    // Iterate through the rest of the elements and compare with the current largest
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
}

// Dynamically allocate memory for a new record and store it in the array
void insert(struct record *new_record) {
    // Increase the capacity of the array if necessary
    if (num_records == capacity) {
        capacity = capacity * 2;
        records = realloc(records, capacity * sizeof(struct record));
        if (!records) {
            fprintf(stderr, "Error: Failed to allocate memory for %d records\n", capacity);
            exit(1);
        }
    }

    // Store the new record in the array
    records[num_records++] = *new_record;
}

// Update the sum of offset values if it exceeds the maximum sum threshold
void update_sum() {
    pthread_mutex_lock(&mutex);
    long sum = 0;
    for (int i = 0; i < num_records; i++) {
        sum += records[i].offset;
    }
    if (sum > config.max_sum) {
        // Adjust the offset values uniformly to fit within the maximum sum threshold
        long adjustment = sum - config.max_sum;
        for (int i = 0; i < num_records; i++) {
            records[i].offset -= adjustment / num_records;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Remove zero values from the offset and keys arrays and copy them into a compressed data structure
void compress(int **keys, long **offsets) {
    // Initialize the compressed arrays
    *keys = (int *)malloc(num_records * sizeof(int));
    *offsets = (long *)malloc(num_records * sizeof(long));

