import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class LogProcessingFunction {
    private static final int BATCH_SIZE = 5000;
    private static final int SLIDING_WINDOW_SIZE = 60 * 1000; // 1 minute
    private static final long MAX_BATCH_WAIT_TIME = 1000L; // 1 second

    private BlockingQueue<LogEntry> logQueue = new LinkedBlockingQueue<>();
    private Map<String, Integer> messageCounts = new ConcurrentHashMap<>();
    private int batchSize = BATCH_SIZE;

    public void processLog(LogEntry log) {
        logQueue.add(log);
        if (logQueue.size() >= batchSize) {
            processBatch();
        }
    }

    private void processBatch() {
        List<LogEntry> logs = new ArrayList<>();
        long currentTime = System.currentTimeMillis();
        long startTime = currentTime - SLIDING_WINDOW_SIZE;
        while (!logQueue.isEmpty()) {
            LogEntry log = logQueue.poll();
            if (log == null) break;
            if (log.getTimestamp() < startTime) break;
            logs.add(log);
        }

        for (LogEntry log : logs) {
            String message = log.getMessage();
            Integer count = messageCounts.get(message);
            if (count == null) {
                messageCounts.put(message, 1);
            } else {
                messageCounts.put(message, count + 1);
            }
        }
    }

    public void publishResults() {
        List<String> messages = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : messageCounts.entrySet()) {
            String message = entry.getKey();
            int count = entry.getValue();
            if (count > 1) {
                messages.add(message + " (" + count + ")");
            }
        }
        // Publish results to monitoring dashboard and send alerts via notification system for unusual activity patterns
    }
}
