    struct stat buf;
    if (stat(filePath, &buf) == 0 && S_ISREG(buf.st_mode)) {
        // Check if the file is within the specified directory
        if (strncmp(directory, filePath, strlen(directory)) == 0) {
            return 1;
        } else {
            printf("Error: File path %s not within specified directory %s\n", filePath, directory);
            return 0;
        }
    } else {
