    Node* newNode = allocateMemory(sizeof(Node));
    newNode->data = record;
    newNode->next = *headRef;
    *headRef = newNode;
}

// Define the linked list deletion function
void deleteRecord(Record record, Node** headRef) {
    Node* current = *headRef;
    Node* previous = NULL;
    while (current != NULL && current->data.id != record.id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        handleError("Record not found");
    } else {
        freeMemory(current);
        if (previous == NULL) {
            *headRef = current->next;
        } else {
            previous->next = current->next;
        }
    }
}

