#include <stdint.h>

// Structures for the compressed data and record
struct compressed_data {
    int* keys;
    long* offsets;
    char** buffers;
    int size;
};

struct record {
    int key;
    char* buffer;
    long offset;
    uint64_t timestamp;
};

// Custom memory pool for dynamic memory management
struct memory_pool {
    void** blocks;
    size_t block_size;
    size_t total_allocated;
};

// Initialize the custom memory pool with a given maximum memory limit in kilobytes
void init_memory_pool(struct memory_pool* pool, size_t max_mem) {
    pool->blocks = (void**)malloc(sizeof(void*) * 10);
    pool->block_size = max_mem / 10;
    pool->total_allocated = 0;
}

// Allocate a block of memory from the custom memory pool
void* allocate_memory(struct memory_pool* pool, size_t size) {
    if (pool->total_allocated + size <= pool->block_size) {
        void* block = malloc(size);
        pool->blocks[pool->total_allocated++] = block;
        return block;
    } else {
        return NULL;
    }
}

// Deallocate all allocated memory when done
void deallocate_memory(struct memory_pool* pool) {
    for (int i = 0; i < pool->total_allocated; i++) {
        free(pool->blocks[i]);
    }
}

// Function to initialize the compressed data structure based on user-provided parameters
void init_compressed_data(struct compressed_data* data, int n, size_t buffer_size, int min_val, int max_val, size_t max_mem) {
    // Allocate memory for the keys and offsets arrays
    data->keys = (int*)malloc(sizeof(int) * n);
    data->offsets = (long*)malloc(sizeof(long) * n);

    // Initialize the keys array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        int key = rand() % (max_val - min_val + 1) + min_val;
        data->keys[i] = key;
    }

    // Initialize the offset values based on the corresponding keys
    for (int i = 0; i < n; i++) {
        long offset = data->keys[i] * (long)(sizeof(int) + sizeof(char*) + sizeof(uint64_t));
        data->offsets[i] = offset;
    }

    // Allocate memory for the buffers array and populate it with random alphanumeric characters
    char* buffer = (char*)malloc(buffer_size);
    for (int i = 0; i < n; i++) {
        data->buffers[i] = buffer;
        for (int j = 0; j < buffer_size - 1; j++) {
            buffer[j] = rand() % ('Z' - 'A') + 'A';
        }
    }
}

// Function to validate the sum of all long offset values does not exceed a user-defined max sum
void validate_offset_sum(struct compressed_data* data, size_t max_sum) {
    // Calculate the sum of all offset values
    long offset_sum = 0;
    for (int i = 0; i < n; i++) {
        offset_sum += data->offsets[i];
    }

    // Adjust the offset values proportionally if the sum exceeds the max sum
    if (offset_sum > max_sum) {
        int scale = max_sum / offset_sum;
        for (int i = 0; i < n; i++) {
            data->offsets[i] *= scale;
        }
    }
}

// Function to evaluate whether the keys array can be compressed further by removing any common prefix among consecutive elements
void compress_keys(struct compressed_data* data) {
    // Find the longest common prefix for consecutive elements in the keys array
    int current = 0;
    while (current < n - 1) {
        if (data->keys[current] == data->keys[current + 1]) {
            current++;
        } else {
            break;
        }
    }

    // If there is a common prefix, remove it from the keys array and adjust the offset values accordingly
    if (current > 0) {
        for (int i = current + 1; i < n; i++) {
            data->keys[i - current] = data->keys[i];
        }
        int new_size = n - current;
        free(data->offsets);
        data->offsets = (long*)malloc(sizeof(long) * new_size);
        for (int i = 0; i < new_size; i++) {
            long offset = data->keys[i] * (long)(sizeof(int) + sizeof(char*) + sizeof(uint64_t));
            data->offsets[i] = offset;
        }
    }
}

// Function to minimize memory usage by removing zero values from the keys array and using a compact representation for the offsets
void optimize_memory_usage(struct compressed_data* data) {
    // Find the number of non-zero values in the keys array
    int non_zero = 0;
    for (int i = 0; i < n; i++) {
        if (data->keys[i] != 0) {
            non_zero++;
        }
    }

    // Allocate memory for the new keys array and populate it with only non-zero values
    int* new_keys = (int*)malloc(sizeof(int) * non_zero);
    for (int i = 0, j = 0; i < n; i++) {
        if (data->keys[i] != 0) {
            new_keys[j++] = data->keys[i];
        }
    }

    // Adjust the offset values accordingly to reflect the reduced number of keys
    for (int i = 0; i < non_zero; i++) {
        long offset = new_keys[i] * (long)(sizeof(int) + sizeof(char*) + sizeof(uint64_t));
        data->offsets[i] = offset;
    }
}

// Function to manage concurrent access safely on the compressed data structure
void lock_compressed_data(struct compressed_data* data) {
    // Use a mutex to synchronize access to the compressed data structure
    pthread_mutex_lock(&data->mutex);
}

// Function to deallocate all allocated memory when done
void deallocate_memory(struct compressed_data* data) {
    // Free all allocated memory for the keys, offsets, and buffers arrays
    free(data->keys);
    free(data->offsets);
    for (int i = 0; i < n; i++) {
        free(data->buffers[i]);
    }
}
```
