    if (records == NULL) {
        printf("Failed to allocate memory\n");
        return NULL;
    }
    size_t* offsets = malloc(num_records * sizeof(size_t));
    if (offsets == NULL) {
        free(records);
        printf("Failed to allocate memory for offsets array\n");
        return NULL;
    }

    // Initialize the offsets array with the starting position of each record
    size_t offset = 0;
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = offset;
        offset += sizeof(struct record);
    }

    // Initialize the keys array with random values within the specified range
    int* keys = malloc(num_records * sizeof(int));
    if (keys == NULL) {
