        return NULL;
    }
    srand((unsigned int)time(NULL)); // seed random with current time
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Shuffle the keys array to ensure a non-deterministic order of records
    shuffle(keys, num_records);

