    for (size_t i = 0; i < num_records; i++) {
        struct record* rec = (struct record*)((char*)records + offsets[i]);
        if (rec->value == 0) { // check for dependency on another record
            size_t dep_index = i - 1; // index of dependent record
            while (keys[dep_index] > keys[i]) { // move dependent record to end of array
                int temp = keys[dep_index];
                keys[dep_index] = keys[i];
                keys[i] = temp;
                size_t dep_offset = offsets[dep_index];
                offsets[dep_index] = offsets[i];
                offsets[i] = dep_offset;
                rec = (struct record*)((char*)records + offsets[dep_index]);
            }
        }
    }

    // Free memory if requested to do so
    if (!validate_memory) {
        free(keys);
        free(offsets);
        return records;
    }

    // Check for memory allocation failures and handle them gracefully
    size_t allocated = 0;
    for (size_t i = 0; i < num_records; i++) {
        struct record* rec = (struct record*)((char*)records + offsets[i]);
        if (rec->value == 0) { // check for failed allocation of a dependent record
            allocated += sizeof(struct record);
        } else {
            allocated += sizeof(int) * (rec->value - 1);
        }
    }
    if (allocated > total_size) {
        free(keys);
        free(offsets);
        free(records);
        printf("Failed to allocate sufficient memory\n");
        return NULL;
    }

    // Initialize the records with a specific pattern
    if (initialize_sequential) {
        for (size_t i = 0; i < num_records; i++) {
            struct record* rec = (struct record*)((char*)records + offsets[i]);
            rec->value = i + 1; // initialize with sequential values
