// Function to add a new log entry to the system's logging infrastructure
void add_log_entry(char *message, int priority) {
    // Generate a unique message ID for this log entry
    int message_id = rand() % 10000;

    // Create a new log entry structure and populate it with the current time and message details
    struct log_entry *new_log = malloc(sizeof(struct log_entry));
    new_log->timestamp = time(NULL);
    new_log->message_id = message_id;
    new_log->priority_level = priority;

    // Add the new log entry to the array of stored messages
    offset_array[new_log->message_id] = lseek(log_file, 0, SEEK_END);
    write(log_file, new_log, sizeof(struct log_entry));

    // Free up memory used by the log entry structure
    free(new_log);
}

// Function to retrieve a specific log entry from the system's logging infrastructure
struct log_entry *get_log_entry(int message_id) {
    // Check if the requested message ID is within bounds
    if (message_id < 0 || message_id >= LOG_MESSAGES) {
        return NULL;
    }

    // Calculate the offset of the requested log entry in the file
    long offset = offset_array[message_id];

    // Read the log entry structure from the file at the specified offset
    struct log_entry *log = malloc(sizeof(struct log_entry));
    read(log_file, log, sizeof(struct log_entry));

    return log;
}

// Function to filter log entries based on a specified priority level and output them to the specified file
void filter_log_entries(int priority, char *output_file) {
    // Open the output file in append mode
    int out_file = open(output_file, O_WRONLY | O_CREAT | O_APPEND, 0644);

    // Loop through all stored log entries and filter based on priority level
    for (int i = 0; i < LOG_MESSAGES; i++) {
        struct log_entry *log = get_log_entry(i);
        if (log && log->priority_level >= priority) {
            write(out_file, log, sizeof(struct log_entry));
        }
    }

    // Close the output file
    close(out_file);
}

// Function to periodically clean up old log entries based on a specified retention policy
void cleanup_log_entries(int retention) {
    // Open the log file in append mode
    int log_file = open("log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);

    // Loop through all stored log entries and filter based on retention policy
    for (int i = 0; i < LOG_MESSAGES; i++) {
        struct log_entry *log = get_log_entry(i);
        if (log && log->timestamp < time(NULL) - retention) {
            write(log_file, log, sizeof(struct log_entry));
        }
    }

    // Close the log file
    close(log_file);
}

int main() {
    // Initialize the logging infrastructure by creating a new file and allocating memory for arrays
    int log_file = open("log.txt", O_WRONLY | O_CREAT, 0644);
    for (int i = 0; i < LOG_MESSAGES; i++) {
        offset_array[i] = lseek(log_file, 0, SEEK_END);
        key_array[i] = rand() % 10000;
    }

    // Implement real-time logging by continuously reading and processing log messages from the input file
    int in_file = open("input.txt", O_RDONLY, 0644);
    while (1) {
        char message[MESSAGE_SIZE];
        read(in_file, message, sizeof(message));

        // Add the new log entry to the array of stored messages and output it to the console
        add_log_entry(message, 0);
        printf("%s\n", message);
    }

    return 0;
}']

