void* allocate_memory(int num_records, long range, bool validate, void (*log)(char *), void (*storage_write)(void*, int)) {
    // Validate parameters
    if (num_records <= 0) {
        log("Invalid number of records: %d\n", num_records);
        return NULL;
    }
    if (range < 0) {
        log("Invalid range for random initialization: %ld\n", range);
        return NULL;
    }

    // Seed the randomization process uniquely for each call to avoid predictable sequences
    srand(time(NULL));

    // Allocate a single contiguous block of memory for all arrays
    long total_size = (long)num_records * sizeof(struct record) + num_records * sizeof(int) + num_records * sizeof(long);
    void* memory = malloc(total_size);
    if (!memory) {
        log("Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    // Sub-allocate within the contiguous block for each array
    struct record* records = memory;
    int* keys = (int*)((char*)records + num_records * sizeof(struct record));
    long* offsets = (long*)((char*)keys + num_records * sizeof(int));

    // Populate the offsets array with random values within the range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % range;
    }

    // Implement a shuffle algorithm to distribute the keys array randomly before populating the records array
    for (int i = 0; i < num_records - 1; i++) {
        int j = i + rand() % (num_records - i);
        if (j != i) {
            swap(&keys[i], &keys[j]);
        }
    }

    // Populate the records array with values from the keys and offsets arrays
    for (int i = 0; i < num_records; i++) {
        records[i].value = offsets[keys[i]];
    }

    if (validate) {
        // Validate the integrity of the records after populating them
        long checksum = 0;
        for (int i = 0; i < num_records; i++) {
            checksum += records[i].value;
        }
        log("Checksum: %ld\n", checksum);
    }

    if (storage_write) {
        // Asynchronously write the serialized records to an external data storage system
        storage_write(memory, num_records * sizeof(struct record));
    } else {
        // Serialize the records into a binary format for storage or transmission
        char* buffer = malloc(num_records * sizeof(struct record));
        if (!buffer) {
            log("Memory allocation failed: %s\n", strerror(errno));
            return NULL;
        }
        memcpy(buffer, records, num_records * sizeof(struct record));
        free(memory); // Release the memory allocated for the contiguous block of arrays
    }

    log("Memory allocation and manipulation successful\n");
    return buffer;
}

// Function to release all allocated memory when no longer needed
void deallocate_memory(void* memory) {
    free(memory);
}

// Helper function to swap two values of the same type
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
