#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>

// Struct definitions
struct record {
    int key;
    int value;
    char* metadata;
};

struct item {
    char* name;
    double value;
};

// Dataset struct
struct dataset {
    struct record** records; // Dynamic array of records
    size_t num_records; // Number of records in the dataset
    size_t max_num_records; // Maximum number of records allowed in the dataset
    struct item* items; // Dynamic collection of items
    size_t num_items; // Number of items in the dataset
    size_t max_num_items; // Maximum number of items allowed in the dataset
};

// Function prototypes
void initialize_dataset(struct dataset* ds, int min_value, int max_value);
void update_range(struct dataset* ds, int min_value, int max_value);
void query_dataset(struct dataset* ds, char* substring);
void free_dataset(struct dataset* ds);
int longest_string(char** strings, size_t num_strings);

// Main function
int main() {
    struct dataset ds;
    initialize_dataset(&ds, INT_MIN, INT_MAX); // Initialize the dataset with all possible values
    update_range(&ds, 0, 1000000); // Update the range of values to 0-1000000
    query_dataset(&ds, "substring"); // Query the dataset based on a substring match
    free_dataset(&ds); // Free the memory allocated for the dataset
    return 0;
}

// Initialize the dataset with random values within the specified range
void initialize_dataset(struct dataset* ds, int min_value, int max_value) {
    if (min_value > max_value) {
        printf("Invalid range: min value cannot be greater than max value\n");
        return;
    }
    ds->max_num_records = 10000000; // Maximum number of records allowed in the dataset
    ds->num_records = 0; // Initially, no records in the dataset
    ds->records = malloc(sizeof(struct record*) * ds->max_num_records); // Allocate memory for the array of pointers to records
    if (ds->records == NULL) {
        printf("Failed to allocate memory for the array of pointers to records\n");
        return;
    }
    ds->items = malloc(sizeof(struct item*) * ds->max_num_items); // Allocate memory for the array of pointers to items
    if (ds->items == NULL) {
        printf("Failed to allocate memory for the array of pointers to items\n");
        free(ds->records);
        return;
    }
    ds->num_items = 0; // Initially, no items in the dataset
    srand(time(NULL)); // Initialize the random seed
    int i;
    for (i = 0; i < ds->max_num_records && i < 10000000; i++) {
        struct record* rec = malloc(sizeof(struct record)); // Allocate memory for a new record
        if (rec == NULL) {
            printf("Failed to allocate memory for a new record\n");
            free(ds->records);
            free(ds->items);
            return;
        }
        rec->key = rand() % (max_value - min_value + 1) + min_value; // Generate a random key within the specified range
        rec->value = rand() % (max_value - min_value + 1) + min_value; // Generate a random value within the specified range
        ds->records[i] = rec; // Add the record to the dataset
    }
}

// Update the acceptable value range dynamically
void update_range(struct dataset* ds, int min_value, int max_value) {
    if (min_value > max_value) {
        printf("Invalid range: min value cannot be greater than max value\n");
        return;
    }
    ds->max_num_records = 10000000; // Maximum number of records allowed in the dataset
    int i;
    for (i = 0; i < ds->num_records && i < 10000000; i++) {
        struct record* rec = ds->records[i]; // Get a pointer to the current record
        if (rec->key < min_value || rec->key > max_value) { // Check if the key falls outside the new range
            free(rec); // Free the memory allocated for the record
            ds->num_records--; // Decrement the number of records in the dataset
        } else {
            rec->value = rand() % (max_value - min_value + 1) + min_value; // Update the value within the new range
        }
    }
}

// Query the dataset based on a substring match
void query_dataset(struct dataset* ds, char* substring) {
    if (substring == NULL) {
        printf("Invalid substring\n");
        return;
    }
    int i;
    for (i = 0; i < ds->num_records && i < 10000000; i++) {
        struct record* rec = ds->records[i]; // Get a pointer to the current record
        if (strstr(rec->name, substring) != NULL) { // Check if the substring is present in the name of the record
            printf("Record %d: key=%d, value=%.2f\n", rec->key, rec->value); // Print the result
        }
    }
}

// Free the memory allocated for the dataset
void free_dataset(struct dataset* ds) {
    int i;
    for (i = 0; i < ds->num_records && i < 10000000; i++) {
        struct record* rec = ds->records[i]; // Get a pointer to the current record
        free(rec); // Free the memory allocated for the record
    }
    free(ds->records); // Free the memory allocated for the array of pointers to records
    free(ds->items); // Free the memory allocated for the array of pointers to items
}

// Helper function to find and print the longest string in an array of strings
int longest_string(char** strings, size_t num_strings) {
    if (strings == NULL || num_strings == 0) {
        printf("Invalid input\n");
        return -1;
    }
    int longest = 0;
    int i;
    for (i = 0; i < num_strings; i++) {
        if (strlen(strings[i]) > longest) {
            longest = strlen(strings[i]);
        }
    }
    return longest;
}
