// Function to dynamically allocate memory for arrays
void allocate_memory(struct CompressedData* data, size_t num_records) {
    // Allocate memory for the record array
    data->records = (struct Record*) malloc(sizeof(struct Record) * num_records);
    if (!data->records) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    // Allocate memory for the lock mechanism
    data->lock = (pthread_mutex_t*) malloc(sizeof(pthread_mutex_t));
    if (!data->lock) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    // Initialize the lock mechanism
    pthread_mutex_init(&data->lock, NULL);
    pthread_cond_init(&data->cond, NULL);
    data->num_records = num_records;
    data->total_memory = 0;
}

// Function to deallocate memory for arrays
void deallocate_memory(struct CompressedData* data) {
    // Deallocate memory for the record array
    free(data->records);
    // Deallocate memory for the lock mechanism
    pthread_mutex_destroy(&data->lock);
    pthread_cond_destroy(&data->cond);
}

// Function to populate the records array with random values
void populate_records(struct CompressedData* data) {
