}

// Function to compress the data by removing zero values from the keys array and using a compact representation for the offset values
void compress_data(struct CompressedData* data) {
    // Create a temporary array to store the compressed data
    struct Record* temp = (struct Record*) malloc(sizeof(struct Record) * data->num_records);
    if (!temp) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    // Loop through each record and compress the data as needed
