    // Copy the temporary array back to the original records array
    memcpy(data->records, temp, sizeof(struct Record) * temp_count);
}

// Function to evaluate whether the keys array can be compressed further by removing any common prefix among consecutive elements
bool can_compress(struct CompressedData* data) {
    // Loop through each pair of consecutive records and check for a common prefix
    for (int i = 0; i < data->num_records - 1; i++) {
        struct Record record1 = data->records[i];
        struct Record record2 = data->records[i + 1];
        if (record1.key == 0) {
            continue;
        }
        for (int j = 0; j < buffer_size; j++) {
            if (record1.buffer[j] != record2.buffer[j]) {
