    // Iterate over each record and calculate its memory usage
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        totalMemUsage += sizeof(record->key) + sizeof(record->value) + strlen(record->str) + 1; // Add size of key, value, and string representation
    }

    // Log memory usage statistics at specified intervals
    if (totalMemUsage > MEMORY_USAGE_LOGGING_THRESHOLD) {
        printf("Memory usage: %d bytes\n", totalMemUsage);
    }

    // Serialize data to disk in custom binary format for efficient storage and retrieval
    FILE* fp = fopen("data.bin", "wb");
    fwrite(records, sizeof(Record), numRecords, fp);
    fclose(fp);

    // Validate serialized data upon deserialization
    fp = fopen("data.bin", "rb");
    Record* newRecords = malloc(sizeof(Record) * numRecords);
    if (newRecords == NULL) {
        printf("Error: Failed to allocate memory for deserialized records\n");
        return;
    }
    fread(newRecords, sizeof(Record), numRecords, fp);
    fclose(fp);
    int newTotalMemUsage = 0;
    for (int i = 0; i < numRecords; i++) {
        Record* newRecord = &newRecords[i];
        newTotalMemUsage += sizeof(newRecord->key) + sizeof(newRecord->value) + strlen(newRecord->str) + 1; // Add size of key, value, and string representation
    }
    if (totalMemUsage != newTotalMemUsage) {
        printf("Error: Serialized data is corrupted\n");
        return;
    }
}

