    long current_time = time(NULL) + 100; // Replace with appropriate interval increment
    for (size_t i = 0; i < num_records; i++) {
        ((sensor_record_t*)buffer)[i].timestamp = current_time;
        current_time += 100; // Replace with appropriate interval increment
    }

    // Initialize each sensor reading as a random value within a specified range
    for (size_t i = 0; i < num_records; i++) {
        ((sensor_record_t*)buffer)[i].reading = rand() % 100.0f; // Replace with appropriate range
    }

    // Filter records where the sensor reading exceeds a specified threshold
    for (size_t i = 0; i < num_records; i++) {
        if (((sensor_record_t*)buffer)[i].reading > 50.0f) {
            ((sensor_record_t*)buffer)[i].identifier[9] = '\0'; // Replace with appropriate identifier length
        } else {
            // Deallocate the memory for this record and move on to the next one
            free(((sensor_record_t*)buffer) + i);
            num_records--;
            i--;
        }
    }

    // Return a pointer to the first record in the buffer
    return (sensor_record_t*)buffer;
}

// Function to deallocate all allocated memory gracefully
