    // Check if the requested memory is within a reasonable limit
    if (total_mem > 10 * 1024 * 1024) { // 10 MB maximum
        printf("Error: Requested memory size exceeds the maximum allowed.\n");
        return NULL;
    }

    // Allocate memory for all records
    void *memory = malloc(total_mem);

    if (memory == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    return memory;
}

// Function to track the total memory usage in bytes for all records
void update_usage(size_t num_records, size_t record_size) {
    // Calculate the total memory required for all records
    size_t total_mem = num_records * record_size;

    // Update the total usage with the new memory allocation
    total_usage += total_mem;
}

// Function to read a list of integers from standard input and store them in an array
void read_input(Record **records, size_t *num_records) {
    // Read the number of records from standard input
