};

// Define a function to initialize the record list and hash table
struct record_list* init_record_list(int size, int min_value, int max_value, int seed) {
    struct record_list* list = malloc(sizeof(struct record_list));
    if (list == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the head nodes of both the linked list and hash table to NULL
    list->head = NULL;
    for (int i = 0; i < 100; i++) {
        list->hash_table[i] = NULL;
    }

    // Generate random integers within the specified range for each record's int field
    srand(seed);
    for (int i = 0; i < size; i++) {
        struct record* new_record = malloc(sizeof(struct record));
        if (new_record == NULL) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        new_record->offset = i;
        new_record->key = rand() % (max_value - min_value + 1) + min_value;
        new_record->next = NULL;

        // Add the record to both the linked list and hash table
        add_to_list(list, new_record);
        add_to_hash(list, new_record);
    }

    return list;
}

// Define a function to add a record to both the linked list and hash table
void add_to_list(struct record_list* list, struct record* record) {
    // Add the record to the end of the linked list
    if (list->head == NULL) {
        list->head = record;
    } else {
        struct record* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

void add_to_hash(struct record_list* list, struct record* record) {
    // Add the record to the hash table using a simple hash function
    int hash_key = record->key % 100;
    if (list->hash_table[hash_key] == NULL) {
        list->hash_table[hash_key] = record;
    } else {
        struct record* current = list->hash_table[hash_key];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

// Define a function to delete a record from both the linked list and hash table
void delete_from_list(struct record_list* list, struct record* record) {
    // Remove the record from the linked list
    if (list->head == record) {
        list->head = record->next;
    } else {
        struct record* current = list->head;
        while (current->next != NULL && current->next != record) {
            current = current->next;
        }
        if (current->next == record) {
            current->next = record->next;
        }
    }
}

void delete_from_hash(struct record_list* list, struct record* record) {
    // Remove the record from the hash table
    int hash_key = record->key % 100;
    if (list->hash_table[hash_key] == record) {
        list->hash_table[hash_key] = record->next;
    } else {
        struct record* current = list->hash_table[hash_key];
        while (current->next != NULL && current->next != record) {
            current = current->next;
        }
        if (current->next == record) {
            current->next = record->next;
        }
    }
}

// Define a function to lookup a record in the hash table
struct record* lookup_hash(struct record_list* list, int key) {
    // Use a simple hash function to find the corresponding bucket
    int hash_key = key % 100;
    struct record* current = list->hash_table[hash_key];

    // Linear search within the bucket for the matching record
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

// Define a function to traverse the linked list in order
void traverse_list(struct record_list* list, void (*callback)(struct record*)) {
    struct record* current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
}']

