#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define constants for hash table parameters
#define HASH_TABLE_SIZE 1024
#define COLLISION_CHAINING_THRESHOLD 8

// Define data structure for storing records
typedef struct record {
    int id;
    char buffer[256];
    size_t length;
    void *metadata;
} Record;

// Define memory pool allocator parameters
#define MEMORY_POOL_SIZE 1024*1024 // 1MB
#define INITIAL_RECORD_COUNT 1024

// Define hash table data structure
typedef struct hash_table {
    int size;
    int record_count;
    Record *records[HASH_TABLE_SIZE];
} HashTable;

// Define logging mechanism parameters
#define LOG_FILE_NAME "logs.txt"
#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_ERROR 2

// Define serialization and deserialization functions
void serialize(HashTable *ht, FILE *file) {
    // Write hash table size to file
    fwrite(&ht->size, sizeof(int), 1, file);

    // Write record count to file
    fwrite(&ht->record_count, sizeof(int), 1, file);

    // Write each record to file
    for (int i = 0; i < ht->record_count; i++) {
        Record *r = &ht->records[i];
        fwrite(&r->id, sizeof(int), 1, file);
        fwrite(r->buffer, r->length, 1, file);
    }
}

void deserialize(HashTable *ht, FILE *file) {
    // Read hash table size from file
    fread(&ht->size, sizeof(int), 1, file);

    // Read record count from file
    fread(&ht->record_count, sizeof(int), 1, file);

    // Allocate memory for records
    ht->records = (Record *)malloc(sizeof(Record) * ht->record_count);

    // Read each record from file
    for (int i = 0; i < ht->record_count; i++) {
        Record *r = &ht->records[i];
        fread(&r->id, sizeof(int), 1, file);
        fread(r->buffer, r->length, 1, file);
    }
}

// Define memory pool allocator functions
void *pool_allocate(size_t size) {
    void *ptr = NULL;
    ptr = malloc(size);
    return ptr;
}

void pool_deallocate(void *ptr) {
    free(ptr);
}

// Define hash table insertion function
int hash_table_insert(HashTable *ht, int id, char *buffer, size_t length, void *metadata) {
    // Calculate hash value for given ID
    unsigned long hash = id % HASH_TABLE_SIZE;

    // Check if the hash table is full
    if (ht->record_count == ht->size) {
        return -1;
    }

    // Create new record and insert into hash table
    Record *r = (Record *)malloc(sizeof(Record));
    r->id = id;
    strncpy(r->buffer, buffer, length);
    r->length = length;
    r->metadata = metadata;

    // Insert record into hash table at given index
    ht->records[hash] = r;

    // Increment record count and return success
    ht->record_count++;
    return 0;
}

// Define hash table search function
int hash_table_search(HashTable *ht, int id) {
    // Calculate hash value for given ID
    unsigned long hash = id % HASH_TABLE_SIZE;

    // Check if the hash table is empty
    if (ht->record_count == 0) {
        return -1;
    }

    // Search for record in hash table at given index
    for (int i = 0; i < COLLISION_CHAINING_THRESHOLD; i++) {
        if (ht->records[hash] != NULL && ht->records[hash]->id == id) {
            return hash;
        } else {
            // Calculate next index in collision chain
            hash = (hash + 1) % HASH_TABLE_SIZE;
        }
    }

    // Return failure if record not found
    return -1;
}

// Define logging mechanism functions
void log(int level, char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[64];
    strftime(timestamp, 64, "%Y-%m-%d %H:%M:%S", tm);
    FILE *file = fopen(LOG_FILE_NAME, "a");
    if (file != NULL) {
        fprintf(file, "[%s] [%d] %s\n", timestamp, level, message);
        fclose(file);
    } else {
        printf("Failed to open log file for writing: %s\n", LOG_FILE_NAME);
    }
}

// Define main function for testing
int main() {
    // Initialize hash table and memory pool allocator
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->size = INITIAL_RECORD_COUNT;
    ht->record_count = 0;
    ht->records = (Record *)malloc(sizeof(Record) * ht->size);

    // Initialize memory pool allocator
    MemoryPoolAllocator mp = {
        .pool_allocate = pool_allocate,
        .pool_deallocate = pool_deallocate
    };

    // Insert records into hash table
    for (int i = 0; i < 1024; i++) {
        int id = i + 1;
        char buffer[64];
        sprintf(buffer, "Record %d", id);
        void *metadata = NULL;
        hash_table_insert(ht, id, buffer, strlen(buffer), metadata);
    }

    // Search for records in hash table
    int found = hash_table_search(ht, 1024);
    if (found == -1) {
        log(LOG_LEVEL_WARNING, "Record not found");
    } else {
        log(LOG_LEVEL_INFO, "Record found");
    }

    // Serialize and deserialize hash table to file
    FILE *file = fopen("hash_table.bin", "wb+");
    serialize(ht, file);
    fclose(file);
    deserialize(ht, file);
    fclose(file);

    // Clean up memory pool allocator and hash table
    for (int i = 0; i < ht->record_count; i++) {
        Record *r = &ht->records[i];
        free(r);
    }
    free(ht);

    return 0;
}
