        stop_service();
    }
}

void resolve_hostname(const char *hostname, struct sockaddr_in *result) {
    // Initialize DNS parameters
    int dns_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (dns_fd == -1) {
        fprintf(stderr, "Error: unable to create DNS socket\n");
        return;
    }

    // Set the DNS server and port number
    struct sockaddr_in dns_server;
    memset(&dns_server, 0, sizeof(dns_server));
    dns_server.sin_family = AF_INET;
    inet_pton(AF_INET, dns_server, &dns_server);
    dns_server.sin_port = htons(dns_port);

    // Send a DNS request to the server and retrieve the IP address
    struct msghdr dns_message;
    memset(&dns_message, 0, sizeof(dns_message));
    dns_message.msg_name = (void *)&dns_server;
    dns_message.msg_namelen = sizeof(dns_server);

    char *hostname_buffer = malloc(strlen(hostname) + 1);
    strcpy(hostname_buffer, hostname);
    struct iovec dns_vector;
    memset(&dns_vector, 0, sizeof(dns_vector));
    dns_vector.iov_base = (void *)hostname_buffer;
    dns_vector.iov_len = strlen(hostname_buffer);

    struct cmsghdr *control_message = malloc(sizeof(struct cmsghdr) + sizeof(int));
    memset(control_message, 0, sizeof(struct cmsghdr) + sizeof(int));
    control_message->cmsg_len = sizeof(struct cmsghdr) + sizeof(int);
    control_message->cmsg_level = SOL_SOCKET;
    control_message->cmsg_type = SCM_TIMEOUT;
    control_message->SCM_TIMEOUT.tv_sec = timeout;

    dns_message.msg_control = (void *)control_message;
    dns_message.msg_controllen = sizeof(struct cmsghdr) + sizeof(int);

    res = sendmsg(dns_fd, &dns_message, 0);
    if (res == -1) {
        fprintf(stderr, "Error: unable to send DNS message\n");
        close(dns_fd);
        return;
    }

    // Retrieve the IP address from the response
    char *response = malloc(MAXMSGLEN);
    struct msghdr dns_reply;
    memset(&dns_reply, 0, sizeof(dns_reply));
    dns_reply.msg_name = (void *)result;
    dns_reply.msg_namelen = sizeof(*result);

    struct iovec dns_vector;
    memset(&dns_vector, 0, sizeof(dns_vector));
    dns_vector.iov_base = (void *)response;
    dns_vector.iov_len = MAXMSGLEN;

    struct cmsghdr *control_message = malloc(sizeof(struct cmsghdr) + sizeof(int));
    memset(control_message, 0, sizeof(struct cmsghdr) + sizeof(int));
    control_message->cmsg_len = sizeof(struct cmsghdr) + sizeof(int);
    control_message->cmsg_level = SOL_SOCKET;
    control_message->cmsg_type = SCM_TIMEOUT;
    control_message->SCM_TIMEOUT.tv_sec = timeout;

    dns_reply.msg_control = (void *)control_message;
    dns_reply.msg_controllen = sizeof(struct cmsghdr) + sizeof(int);

    res = recvmsg(dns_fd, &dns_reply, 0);
    if (res == -1) {
        fprintf(stderr, "Error: unable to retrieve DNS response\n");
        close(dns_fd);
        return;
    }

    // Close the socket and free memory
    close(dns_fd);
    free(response);
    free(control_message);
}

void generate_random_string(char **str, const char *chars, size_t length) {
    // Generate a random string of variable length from a specified character set
    if (!str || !chars) {
        fprintf(stderr, "Error: invalid parameters\n");
        return;
    }

    *str = malloc(length + 1);
    char *p = *str;
    size_t i;
    for (i = 0; i < length; ++i) {
        *p++ = chars[random() % strlen(chars)];
    }
    *p = '\0';
}

void hash_password(const char *password) {
    // Hash a password provided by the user using SHA-256 hashing algorithm
    if (!password) {
        fprintf(stderr, "Error: invalid password\n");
        return;
    }

    int digest_length = SHA256_DIGEST_LENGTH;
    unsigned char hash[digest_length];
    SHA256((unsigned char *)password, strlen(password), hash);
    char *hashed_password = malloc(digest_length * 2 + 1);
    for (int i = 0; i < digest_length; ++i) {
        sprintf(&hashed_password[i*2], "%02x", hash[i]);
    }
    free(hashed_password);
}

