// Define constants for the event structure
#define EVENT_TYPE_LEN 10
#define PAYLOAD_MAX_LEN 256
#define TIMESTAMP_FACTOR 1000

// Define a struct to represent an event
struct Event {
    char type[EVENT_TYPE_LEN]; // event type (e.g. "login", "logout")
    int id;                   // event ID
    char *payload;            // dynamically allocated payload string
    long timestamp;           // timestamp in milliseconds
};

// Define a struct to represent the event log system
struct EventLog {
    struct Event **events;          // array of events
    size_t num_events;             // number of events
    size_t max_events;             // maximum number of events
    size_t total_memory_usage;     // total memory usage in bytes
};

// Define a function to initialize the event log system
struct EventLog *init_event_log(size_t max_events) {
    struct EventLog *log = malloc(sizeof(struct EventLog));
    if (log == NULL) {
        // handle error: out of memory
        return NULL;
    }

    log->max_events = max_events;
    log->num_events = 0;
    log->total_memory_usage = 0;

    // allocate memory for the events array
    log->events = malloc(sizeof(struct Event *) * max_events);
    if (log->events == NULL) {
        // handle error: out of memory
        return NULL;
    }

    return log;
}

// Define a function to add an event to the log
int add_event(struct EventLog *log, char *type, int id, char *payload) {
    if (log == NULL || type == NULL || payload == NULL) {
        // handle error: invalid input
        return -1;
    }

    // check if there is enough space in the log for a new event
    if (log->num_events >= log->max_events) {
        // handle error: log is full
        return -2;
    }

    struct Event *event = malloc(sizeof(struct Event));
    if (event == NULL) {
        // handle error: out of memory
        return -3;
    }

    strncpy(event->type, type, EVENT_TYPE_LEN);
    event->id = id;
    event->payload = malloc(strlen(payload) + 1);
    if (event->payload == NULL) {
        // handle error: out of memory
        return -3;
    }
    strncpy(event->payload, payload, PAYLOAD_MAX_LEN);

    event->timestamp = log->num_events * TIMESTAMP_FACTOR;

    log->total_memory_usage += sizeof(struct Event) + strlen(payload);

    log->events[log->num_events++] = event;

    return 0;
}

// Define a function to retrieve an event from the log by ID
struct Event *get_event(struct EventLog *log, int id) {
    if (log == NULL || id < 1 || id > log->num_events) {
        // handle error: invalid input
        return NULL;
    }

    for (int i = 0; i < log->num_events; i++) {
        if (log->events[i]->id == id) {
            return log->events[i];
        }
    }

    // handle error: event not found
    return NULL;
}

// Define a function to free the memory used by an event
void free_event(struct Event *event) {
    if (event == NULL) {
        // handle error: invalid input
        return;
    }

    free(event->payload);
    free(event);
}

// Define a function to free the memory used by the event log
void free_event_log(struct EventLog *log) {
    if (log == NULL) {
        // handle error: invalid input
        return;
    }

    for (int i = 0; i < log->num_events; i++) {
        free_event(log->events[i]);
    }

    free(log->events);
    free(log);
}
