using namespace std;

class ServerState {
  public:
    int cpu_usage_;
    int ram_usage_;
    map<string, vector<pair<int, int>>> task_schedule_; // <task type, <duration, resource cost>>
};

ServerState server_state;

void scheduleTask(const string& task_type) {
  // Check if there are available resources for the task
  if (server_state.cpu_usage_ + task_schedule[task_type][0] > 100 ||
      server_state.ram_usage_ + task_schedule[task_type][1] > 16) {
    // Reschedule the task with minimal disruption to ongoing operations
    rescheduleTask(task_type);
    return;
  }

  // Schedule the task and update resource usage
  server_state.cpu_usage_ += task_schedule[task_type][0];
  server_state.ram_usage_ += task_schedule[task_type][1];
  cout << "Scheduled " << task_type << " with CPU usage " << server_state.cpu_usage_ << " and RAM usage " << server_state.ram_usage_ << endl;
}

void rescheduleTask(const string& task_type) {
  // Check if there are available resources for the task
  if (server_state.cpu_usage_ + task_schedule[task_type][0] > 100 ||
      server_state.ram_usage_ + task_schedule[task_type][1] > 16) {
    // If there are no available resources, do not schedule the task
    cout << "Could not schedule " << task_type << ". Resource usage is too high." << endl;
    return;
  }

  // Reschedule the task and update resource usage
  server_state.cpu_usage_ += task_schedule[task_type][0];
  server_state.ram_usage_ += task_schedule[task_type][1];
  cout << "Rescheduled " << task_type << " with CPU usage " << server_state.cpu_usage_ << " and RAM usage " << server_state.ram_usage_ << endl;
}

int main() {
  // Initialize the server state and task schedule
  server_state.cpu_usage_ = 0;
  server_state.ram_usage_ = 0;
  task_schedule["maintenance"] = vector<pair<int, int>>{{30, 50}, {45, 30}};
  task_schedule["backups"] = vector<pair<int, int>>{{45, 30}, {60, 70}};
  task_schedule["updates"] = vector<pair<int, int>>{{60, 70}, {90, 80}};

  // Schedule tasks based on priority and impact on service availability
  while (true) {
    string task_type = getTaskType(); // Get the next task to be scheduled
    scheduleTask(task_type); // Schedule the task
  }

  return 0;
}
