// Define the data structure for a record
typedef struct {
    int key;
    long offset;
} record_t;

// Define the memory pool for allocating records
static const size_t RECORD_POOL_SIZE = 1024 * 1024; // 1 MB
static record_t* record_pool;

// Define the maximum allowed memory allocation
#define MAX_MEMORY_ALLOCATION (1024 * 1024 * 1024) // 1 GB

// Define the data structure for a hash table
typedef struct {
    size_t size;
    record_t** buckets;
} hash_table_t;

// Initialize the hash table with a default size of 65536
hash_table_t* initialize_hash_table(void) {
    return (hash_table_t*)calloc(1, sizeof(hash_table_t));
}

// Add a new record to the hash table
int add_record(hash_table_t* hash_table, int key, long offset) {
    // Check if the hash table is full
    if (hash_table->size >= MAX_MEMORY_ALLOCATION / sizeof(record_t)) {
        return -1;
    }

    // Calculate the bucket index for the new record
    size_t bucket_index = key % hash_table->size;

    // Allocate a new record and add it to the bucket
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->key = key;
    new_record->offset = offset;
    hash_table->buckets[bucket_index] = new_record;

    // Increment the number of records in the hash table
    hash_table->size++;

    return 0;
}

// Retrieve a record from the hash table
int get_record(hash_table_t* hash_table, int key) {
    // Calculate the bucket index for the record
    size_t bucket_index = key % hash_table->size;

    // Check if the bucket exists and has a record with the given key
    if (hash_table->buckets[bucket_index] == NULL || hash_table->buckets[bucket_index]->key != key) {
        return -1;
    }

    return hash_table->buckets[bucket_index]->offset;
}

// Delete a record from the hash table
int delete_record(hash_table_t* hash_table, int key) {
    // Calculate the bucket index for the record
    size_t bucket_index = key % hash_table->size;

    // Check if the bucket exists and has a record with the given key
    if (hash_table->buckets[bucket_index] == NULL || hash_table->buckets[bucket_index]->key != key) {
        return -1;
    }

    // Free the record and remove it from the bucket
    free(hash_table->buckets[bucket_index]);
    hash_table->buckets[bucket_index] = NULL;

    // Decrement the number of records in the hash table
    hash_table->size--;

    return 0;
}

// Free all memory allocated for the hash table
void free_hash_table(hash_table_t* hash_table) {
    for (size_t i = 0; i < hash_table->size; i++) {
        if (hash_table->buckets[i] != NULL) {
            free(hash_table->buckets[i]);
            hash_table->buckets[i] = NULL;
        }
    }
}

int main() {
    // Initialize the record pool and hash table
    record_pool = (record_t*)malloc(RECORD_POOL_SIZE);
    hash_table_t* hash_table = initialize_hash_table();

    // Populate the hash table with random records
    srand(time(NULL));
    for (int i = 0; i < 100000; i++) {
        int key = rand() % 100000;
        long offset = rand() % 100000;
        add_record(hash_table, key, offset);
    }

    // Retrieve a record from the hash table
    int key = 5;
    long offset = get_record(hash_table, key);

    // Delete a record from the hash table
    delete_record(hash_table, key);

    // Free all memory allocated for the hash table and the record pool
    free_hash_table(hash_table);
    free(record_pool);

    return 0;
}
