// Function to initialize the arrays for offset and keys
void init_arrays(int** offsets, int** keys, int num_records) {
    *offsets = (int*)malloc(num_records * sizeof(int));
    *keys = (int*)malloc(num_records * sizeof(int));
}

// Function to dynamically manage memory for the linked list of records
void manage_memory(Record** head, int* num_records, int max_num_records) {
    // Allocate memory for a new node in the linked list
    Record* new_node = (Record*)malloc(sizeof(Record));

    // If there are no records yet, initialize the head pointer and add the first node
    if (*num_records == 0) {
        *head = new_node;
    } else {
        // Add the new node to the end of the linked list
        Record* current_node = *head;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }

    // Increment the number of records and check if we need to resize the linked list
    (*num_records)++;
    if (*num_records == max_num_records) {
        max_num_records *= 2;
        Record* new_head = (Record*)malloc(max_num_records * sizeof(Record));
        // Copy the nodes from the old linked list to the new one
        int i = 0;
        for (Record* current_node = *head; current_node != NULL; current_node = current_node->next) {
            new_head[i].key = current_node->key;
            new_head[i].value = current_node->value;
            if (current_node->next != NULL) {
                new_head[i].next = &new_head[i + 1];
            } else {
                new_head[i].next = NULL;
            }
            i++;
        }
        free(*head);
        *head = new_head;
    }
}

// Function to periodically clean up unused records from the linked list
void cleanup(Record** head, int* num_records, int threshold) {
    // Get the current time in minutes
    time_t t = time(NULL);
    struct tm* now = localtime(&t);
    int cur_minute = now->tm_min;

    // Iterate over the linked list and remove records that are older than the threshold
    Record* current_node = *head;
    while (current_node != NULL) {
        if (cur_minute - current_node->value > threshold) {
            Record* next_node = current_node->next;
            free(current_node);
            (*num_records)--;
            current_node = next_node;
        } else {
            current_node = current_node->next;
        }
    }
}

// Main function to implement the desired functionality
int main() {
    // Initialize the linked list and arrays for offset and keys
    Record* head = NULL;
    int num_records = 0;
    int max_num_records = 1024;
    init_arrays(&offsets, &keys, max_num_records);

    // Simulate data streams with random values and timestamps
    srand(time(NULL));
    while (1) {
        // Generate a new key-value pair
        int key = rand() % INT_MAX;
        int value = rand() % INT_MAX;

        // Add the new record to the linked list and update the offset and key arrays
        manage_memory(&head, &num_records, max_num_records);
        offsets[num_records - 1] = num_records;
        keys[num_records - 1] = key;

        // Periodically clean up unused records from the linked list
        cleanup(&head, &num_records, 60);
    }

    return 0;
}
