typedef struct point {
    double x;
    double y;
} Point;

typedef struct geometry {
    double area;
} Geometry;

typedef struct geo_point {
    Point pt;
    Geometry geom;
} GeoPoint;

int allocate_geo_point(GeoPoint** gp, int index) {
    if (index >= 10000) {
        return -1;
    }

    // Allocate memory for the geometry structure
    *gp = (GeoPoint*)malloc(sizeof(GeoPoint));
    if (*gp == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    // Initialize the geometry structure
    (*gp)->geom.area = 0;

    // Allocate memory for the point coordinates
    (*gp)->pt.x = 0;
    (*gp)->pt.y = 0;

    return index + 1;
}

int add_geo_point(GeoPoint** gps, int npoints, Point pt) {
    if (npoints >= 100000) {
        return -1;
    }

    // Find the first available slot in the array of points
    int index = 0;
    while (index < npoints && gps[index] != NULL) {
        index++;
    }

    if (index == npoints) {
        return -1;
    }

    // Allocate memory for the new point and initialize its coordinates
    GeoPoint* gp = (GeoPoint*)malloc(sizeof(GeoPoint));
    if (gp == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }
    gp->pt.x = pt.x;
    gp->pt.y = pt.y;
    gps[index] = gp;

    // Calculate the geometry properties of the new point
    gp->geom.area = sqrt(pow(gp->pt.x, 2) + pow(gp->pt.y, 2));

    return npoints + 1;
}

int free_geo_point(GeoPoint** gps, int index) {
    if (index >= 10000 || gps[index] == NULL) {
        return -1;
    }

    // Release memory for the geometry structure
    free(gps[index]->geom);
    gps[index]->geom = NULL;

    // Release memory for the point coordinates
    free(gps[index]->pt.x);
    gps[index]->pt.x = 0;
    free(gps[index]->pt.y);
    gps[index]->pt.y = 0;

    // Release memory for the GeoPoint structure
    free(gps[index]);
    gps[index] = NULL;

    return index - 1;
}

int clear_geo_points(GeoPoint** gps, int npoints) {
    if (npoints >= 10000 || gps == NULL) {
        return -1;
    }

    for (int i = 0; i < npoints; i++) {
        // Release memory for the geometry structure
        free(gps[i]->geom);
        gps[i]->geom = NULL;

        // Release memory for the point coordinates
        free(gps[i]->pt.x);
        gps[i]->pt.x = 0;
        free(gps[i]->pt.y);
        gps[i]->pt.y = 0;

        // Release memory for the GeoPoint structure
        free(gps[i]);
        gps[i] = NULL;
    }

    return 0;
}

int main() {
    int npoints = 0;
    GeoPoint* geo_points[10000];

    // Add a new point to the set of points
    Point pt = {0, 0};
    add_geo_point(geo_points, npoints, pt);

    // Access the geometry properties of the first point in the set
    GeoPoint* gp = geo_points[0];
    printf("Area: %f\n", gp->geom.area);

    // Free memory for the first point
    free_geo_point(geo_points, 0);

    // Add a new point to the set of points
    pt = {1, 2};
    add_geo_point(geo_points, npoints, pt);

    // Access the geometry properties of the second point in the set
    gp = geo_points[1];
    printf("Area: %f\n", gp->geom.area);

    // Clear and reuse previously allocated memory to optimize performance and reduce memory usage over time
    clear_geo_points(geo_points, npoints);

    return 0;
}
