#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for an item in the hash table
typedef struct {
    int id;
    double value;
    char *name;
} Item;

// Define the hash table data structure
struct HashTable {
    // The array of items in the hash table
    Item **items;

    // The size of the hash table
    size_t size;

    // The number of items in the hash table
    size_t count;
};

// Define a function to create a new hash table with a given size
struct HashTable *createHashTable(size_t size) {
    struct HashTable *table = malloc(sizeof(struct HashTable));

    // Allocate memory for the array of items in the hash table
    Item **items = malloc(sizeof(Item *) * size);
    if (items == NULL) {
        free(table);
        return NULL;
    }

    table->items = items;
    table->size = size;
    table->count = 0;

    return table;
}

// Define a function to destroy a hash table and free its memory
void destroyHashTable(struct HashTable *table) {
    if (table == NULL) {
        return;
    }

    for (size_t i = 0; i < table->size; i++) {
        Item *item = table->items[i];
        if (item != NULL) {
            free(item);
        }
    }

    free(table->items);
    free(table);
}

// Define a function to insert an item into the hash table
bool insertItem(struct HashTable *table, int id, double value, char *name) {
    if (table == NULL || id < 0 || name == NULL) {
        return false;
    }

    // Calculate the index for the new item in the hash table
    size_t index = id % table->size;

    // Check if there is already an item at the calculated index
    Item *item = table->items[index];
    if (item != NULL) {
        // If there is, check if it has the same ID as the new item
        if (item->id == id) {
            // If it does, update its values and return
            item->value = value;
            strcpy(item->name, name);
            return true;
        } else {
            // If not, insert the new item at the calculated index
            Item *newItem = malloc(sizeof(Item));
            if (newItem == NULL) {
                return false;
            }

            newItem->id = id;
            newItem->value = value;
            strcpy(newItem->name, name);
            table->items[index] = newItem;
            table->count++;

            return true;
        }
    } else {
        // If there is no item at the calculated index, insert the new item
        Item *newItem = malloc(sizeof(Item));
        if (newItem == NULL) {
            return false;
        }

        newItem->id = id;
        newItem->value = value;
        strcpy(newItem->name, name);
        table->items[index] = newItem;
        table->count++;

        return true;
    }
}

// Define a function to lookup an item in the hash table by its ID
bool lookupItem(struct HashTable *table, int id) {
    if (table == NULL || id < 0) {
        return false;
    }

    // Calculate the index for the item in the hash table
    size_t index = id % table->size;

    // Check if there is an item at the calculated index
    Item *item = table->items[index];
    if (item == NULL) {
        return false;
    }

    // If there is, check if it has the same ID as the requested item
    if (item->id == id) {
        return true;
    } else {
        return false;
    }
}

// Define a function to update an item in the hash table by its ID
bool updateItem(struct HashTable *table, int id, double value, char *name) {
    if (table == NULL || id < 0 || name == NULL) {
        return false;
    }

    // Calculate the index for the item in the hash table
    size_t index = id % table->size;

    // Check if there is an item at the calculated index
    Item *item = table->items[index];
    if (item == NULL) {
        return false;
    }

    // If there is, check if it has the same ID as the requested item
    if (item->id == id) {
        // If it does, update its values and return
        item->value = value;
        strcpy(item->name, name);
        return true;
    } else {
        return false;
    }
}

// Define a function to remove an item from the hash table by its ID
bool removeItem(struct HashTable *table, int id) {
    if (table == NULL || id < 0) {
        return false;
    }

    // Calculate the index for the item in the hash table
    size_t index = id % table->size;

    // Check if there is an item at the calculated index
    Item *item = table->items[index];
    if (item == NULL) {
        return false;
    }

    // If there is, check if it has the same ID as the requested item
    if (item->id == id) {
        // If it does, remove it from the hash table and return
        free(item);
        table->items[index] = NULL;
        table->count--;

        return true;
    } else {
        return false;
    }
}

// Define a function to resize the hash table when it reaches a certain load factor
void resizeHashTable(struct HashTable *table) {
    // Check if the hash table is already at its maximum size
    if (table->size == SIZE_MAX) {
        return;
    }

    // Calculate the new size for the hash table based on the current load factor
    size_t newSize = table->size * 2;

    // Create a new array of items in the new hash table
    Item **newItems = malloc(sizeof(Item *) * newSize);
    if (newItems == NULL) {
        return;
    }

    for (size_t i = 0; i < newSize; i++) {
        newItems[i] = NULL;
    }

    // Copy the items from the old hash table to the new one
    for (size_t i = 0; i < table->size; i++) {
        Item *item = table->items[i];
        if (item != NULL) {
            size_t newIndex = item->id % newSize;
            newItems[newIndex] = item;
        }
    }

    // Free the memory used by the old hash table
    free(table->items);

    // Update the hash table with the new array of items
    table->items = newItems;
    table->size = newSize;
}

// Define a function to perform periodic data compression to minimize system latency during high-throughput periods
void compressData(struct HashTable *table) {
    // Check if the hash table is at its minimum size
    if (table->size == SIZE_MIN) {
        return;
    }

    // Calculate the new size for the hash table based on the current load factor
    size_t newSize = table->size / 2;

    // Create a new array of items in the new hash table
    Item **newItems = malloc(sizeof(Item *) * newSize);
    if (newItems == NULL) {
        return;
    }

    for (size_t i = 0; i < newSize; i++) {
        newItems[i] = NULL;
    }

    // Copy the items from the old hash table to the new one
    for (size_t i = 0; i < table->size; i++) {
        Item *item = table->items[i];
        if (item != NULL) {
            size_t newIndex = item->id % newSize;
            newItems[newIndex] = item;
        }
    }

    // Free the memory used by the old hash table
    free(table->items);

    // Update the hash table with the new array of items
    table->items = newItems;
    table->size = newSize;
}

// Define a function to handle concurrent access to the hash table by multiple threads, ensuring thread safety and efficient synchronization mechanisms
void *handleThread(void *args) {
    struct HashTable *table = args;

    // Loop continuously until the thread is terminated
    while (true) {
        // Wait for a signal to perform an operation on the hash table
        pthread_cond_wait(&table->cond, &table->mutex);

        // Acquire a lock on the hash table
        pthread_mutex_lock(&table->mutex);

        // Perform the requested operation on the hash table
        switch (table->operation) {
            case INSERT:
                insertItem(table, table->id, table->value, table->name);
                break;
            case LOOKUP:
                lookupItem(table, table->id);
                break;
            case UPDATE:
                updateItem(table, table->id, table->value, table->name);
                break;
            case REMOVE:
                removeItem(table, table->id);
                break;
        }

        // Release the lock on the hash table
        pthread_mutex_unlock(&table->mutex);
    }
}

// Define a function to create a new thread for handling concurrent access to the hash table
pthread_t createThread(struct HashTable *table) {
    // Create a new thread and pass it a pointer to the hash table
    pthread_t thread;
    pthread_create(&thread, NULL, handleThread, (void *)table);

    return thread;
}

// Define a function to destroy a thread for handling concurrent access to the hash table
void destroyThread(pthread_t thread) {
    // Join the thread with the main thread
    pthread_join(thread, NULL);
}
