struct Record {
    long offset;
    int key;
    double timestamp;
};

// Define the cache structure
struct Cache {
    // Array of records
    struct Record *records;
    // Size of the cache
    size_t size;
    // Number of hits in the cache
    unsigned long hits;
    // Number of misses in the cache
    unsigned long misses;
};

// Define the function to calculate the offset for a given key
long calcOffset(int key, int increment) {
    return key * increment;
}

// Define the function to generate timestamps in seconds since epoch
double getTimestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)(ts.tv_sec + ts.tv_nsec / 1e9);
}

// Define the function to allocate memory for a record
struct Record* allocRecord() {
    struct Record *record = malloc(sizeof(struct Record));
    if (record == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    return record;
}

// Define the function to deallocate memory for a record
void freeRecord(struct Record *record) {
    free(record);
}

// Define the function to add a new record to the cache
void addToCache(struct Cache *cache, struct Record *record) {
    // Check if the cache is full
    if (cache->size == 0) {
        return;
    }
    // Check if the record exists in the cache
    for (int i = 0; i < cache->size; i++) {
        if (record->key == cache->records[i].key) {
            // If the record exists, update its value and return
            cache->records[i] = *record;
            return;
        }
    }
    // If the record does not exist, add it to the end of the cache
    cache->records[cache->size] = *record;
    cache->size++;
}

// Define the function to remove a record from the cache
void removeFromCache(struct Cache *cache, int key) {
    // Check if the cache is empty
    if (cache->size == 0) {
        return;
    }
    // Find the index of the record with the given key
    for (int i = 0; i < cache->size; i++) {
        if (key == cache->records[i].key) {
            // If the record is found, remove it from the cache
            cache->size--;
            for (int j = i; j < cache->size; j++) {
                cache->records[j] = cache->records[j+1];
            }
            return;
        }
    }
}

// Define the function to retrieve a record from the cache
struct Record* getFromCache(struct Cache *cache, int key) {
    // Check if the cache is empty
    if (cache->size == 0) {
        return NULL;
    }
    // Find the index of the record with the given key
    for (int i = 0; i < cache->size; i++) {
        if (key == cache->records[i].key) {
            // If the record is found, update its timestamp and return it
            struct Record *record = &cache->records[i];
            record->timestamp = getTimestamp();
            cache->hits++;
            return record;
        }
    }
    cache->misses++;
    return NULL;
}

// Define the function to handle the cache eviction policy
void evictCache(struct Cache *cache) {
    // Check if the cache is full
    if (cache->size == 0) {
        return;
    }
    // Sort the records by timestamp
    qsort(cache->records, cache->size, sizeof(struct Record), compareRecords);
    // Remove the oldest record from the cache
    removeFromCache(cache, cache->records[0].key);
}

// Define the function to compare two records by timestamp
int compareRecords(const void *a, const void *b) {
    struct Record *recordA = (struct Record *)a;
    struct Record *recordB = (struct Record *)b;
    if (recordA->timestamp < recordB->timestamp) {
        return -1;
    } else if (recordA->timestamp > recordB->timestamp) {
        return 1;
    } else {
        return 0;
    }
}

