// Memory management framework for managing the dataset
struct MemoryManager {
    // Allocate memory for a new record
    void (*allocate)(size_t size);
    // Deallocate memory for an existing record
    void (*deallocate)(void* ptr);
    // Resize memory for an existing record
    bool (*resize)(void* ptr, size_t size);
};

// Define the global memory manager object
