    .allocate = (void (*)(size_t))malloc,
    .deallocate = (void (*)(void*))free,
    .resize = (bool (*)(void*, size_t))realloc
};

// Define the function to manage memory for a dynamic dataset of records
void manage_memory(Record** records, size_t record_count) {
    // Calculate the total memory usage in bytes
    size_t total_size = 0;
    for (int i = 0; i < record_count; i++) {
        total_size += sizeof(Record) + strlen(records[i]->keys) + (sizeof(long) * records[i]->integer);
    }

    // Check if the total memory usage exceeds the predefined threshold
    if (total_size > THRESHOLD) {
        printf("Total memory usage of %zu bytes exceeds the predefined threshold of %d.\n", total_size, THRESHOLD);
        exit(1);
    }

    // Allocate memory for the dataset
    void* memory = memory_manager.allocate(total_size);

    // Initialize each record with a random integer value within the specified range
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i] = memory + total_size - ((sizeof(Record) + strlen(records[i]->keys) + (sizeof(long) * records[i]->integer)));
        records[i]->integer = rand() % MAX_INT;
    }
}

