// Total memory usage in bytes
long total_memory_usage = 0;

// Initialize the event records array and allocate memory for it
void init_event_records() {
    // Allocate memory for the event records array
    event_records = (EventRecord*)malloc(1000000000 * sizeof(EventRecord));

    // Initialize the lock for synchronizing access to the event records array
    pthread_mutex_init(&event_records_lock, NULL);

    // Set the total memory usage to 0
    total_memory_usage = 0;
}

// Add a new event record to the event records array
void add_event_record(long timestamp, char* event_name, double duration) {
    // Acquire the lock for synchronizing access to the event records array
    pthread_mutex_lock(&event_records_lock);

    // Check if there is enough memory available to add a new record
    assert(total_memory_usage + sizeof(EventRecord) <= 1000000000 * sizeof(EventRecord));

    // Add the event record to the array
    event_records[total_memory_usage / sizeof(EventRecord)] = (EventRecord){timestamp, event_name, duration};

    // Update the total memory usage
    total_memory_usage += sizeof(EventRecord);

    // Release the lock for synchronizing access to the event records array
    pthread_mutex_unlock(&event_records_lock);
}

// Remove an event record from the event records array
void remove_event_record(int index) {
    // Acquire the lock for synchronizing access to the event records array
    pthread_mutex_lock(&event_records_lock);

    // Check if the index is valid
    assert(index >= 0 && index < total_memory_usage / sizeof(EventRecord));

    // Remove the event record from the array
    EventRecord* record = &event_records[index];

    // Update the total memory usage
    total_memory_usage -= sizeof(EventRecord);

    // Release the lock for synchronizing access to the event records array
    pthread_mutex_unlock(&event_records_lock);
}

// Get the event record at a given index in the event records array
