#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

#define MAX_KEY 1000000000
#define MIN_SEED 1
#define MAX_SEED 2147483647
#define DEFAULT_SEED 123456789

struct record {
    int key;
    long offset;
};

typedef struct {
    pthread_mutex_t mutex;
    struct record *records;
    size_t count;
} dynamic_data_structure;

int initialize_dynamic_data_structure(dynamic_data_structure *dds, int concurrency_level) {
    dds->count = 0;
    dds->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    dds->records = (struct record *)malloc(sizeof(struct record));
    if (dds->records == NULL) {
        return -1;
    }
    return 0;
}

int insert_record(dynamic_data_structure *dds, int key, long offset) {
    pthread_mutex_lock(&dds->mutex);
    struct record *rec = (struct record *)malloc(sizeof(struct record));
    if (rec == NULL) {
        pthread_mutex_unlock(&dds->mutex);
        return -1;
    }
    rec->key = key;
    rec->offset = offset;
    dds->records[dds->count++] = *rec;
    pthread_mutex_unlock(&dds->mutex);
    free(rec);
    return 0;
}

int find_record(dynamic_data_structure *dds, int key) {
    struct record *rec = NULL;
    pthread_mutex_lock(&dds->mutex);
    for (size_t i = 0; i < dds->count; i++) {
        if (dds->records[i].key == key) {
            rec = &dds->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&dds->mutex);
    return (rec != NULL) ? rec->offset : -1;
}

int delete_record(dynamic_data_structure *dds, int key) {
    struct record *rec = NULL;
    pthread_mutex_lock(&dds->mutex);
    for (size_t i = 0; i < dds->count; i++) {
        if (dds->records[i].key == key) {
            rec = &dds->records[i];
            break;
        }
    }
    if (rec != NULL) {
        for (size_t j = i + 1; j < dds->count; j++) {
            dds->records[j - 1] = dds->records[j];
        }
        dds->count--;
    }
    pthread_mutex_unlock(&dds->mutex);
    free(rec);
    return (rec != NULL) ? 0 : -1;
}

int random_between(int min, int max) {
    if (min > max || min < MIN_SEED || max > MAX_SEED) {
        return DEFAULT_SEED;
    }
    return (rand() % (max - min + 1)) + min;
}

int initialize_offsets(dynamic_data_structure *dds, int concurrency_level, int seed) {
    if (seed > MAX_SEED || seed < MIN_SEED) {
        seed = DEFAULT_SEED;
    }
    srand(seed);
    for (size_t i = 0; i < dds->count; i++) {
        dds->records[i].offset = random_between(MIN_SEED, MAX_SEED);
    }
    return 0;
}

int deallocate_dynamic_data_structure(dynamic_data_structure *dds) {
    pthread_mutex_lock(&dds->mutex);
    for (size_t i = 0; i < dds->count; i++) {
        free(dds->records[i].offset);
    }
    free(dds->records);
    pthread_mutex_unlock(&dds->mutex);
    return 0;
}
