    *head = NULL;

    // Read each line of the CSV file and populate linked list
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines or those starting with '#'
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse data from the line and populate message struct
        char *token = strtok(line, ",");
        int temperature = atoi(token);
        token = strtok(NULL, ",");
        for (int i = 0; i < 8; i++) {
            (*head)->data.bytes[i] = token[i];
        }
        (*head)->priority = getPriority(temperature);
        (*head)->timestamp = time(NULL);

        // Allocate memory for next message struct and update linked list head pointer
        Message *new_node = malloc(sizeof(Message));
        if (new_node == NULL) {
            perror("Error allocating memory for message");
            exit(1);
        }
        new_node->next = (*head);
        *head = new_node;
    }

    // Close CSV file
    fclose(fp);
}

// Function to get priority based on temperature reading
int getPriority(int temperature) {
    if (temperature < 20) {
        return 1;
    } else if (temperature >= 20 && temperature < 30) {
        return 2;
    } else {
        return 3;
    }
}

