#include <boost/algorithm/string/join.hpp>
#include <boost/program_options.hpp>
#include <boost/log/core.hpp>
#include <boost/log/trivial.hpp>
#include <boost/log/expressions.hpp>
#include <boost/log/utility/setup/console.hpp>
#include <boost/log/sinks/sync_frontend.hpp>
#include <boost/log/sinks/text_file_backend.hpp>
#include <boost/log/sinks/text_multifile_backend.hpp>
#include <boost/log/sinks/syslog_backend.hpp>
#include <boost/log/utility/setup/common_attributes.hpp>
#include <boost/log/utility/setup/file.hpp>
#include <boost/log/utility/setup/filter.hpp>
#include <boost/log/sinks/async_frontend.hpp>
#include <boost/log/sources/logger.hpp>
#include <boost/log/sources/record_ostream.hpp>
#include <boost/date_time/posix_time/posix_time.hpp>

using namespace boost::asio;
using namespace boost::property_tree;
using namespace boost::algorithm;
using namespace boost::log;

class DataIngestionClient {
public:
    DataIngestionClient(io_service& ioService, const std::string& configFilePath) :
        ioService_(ioService),
        dataFetcher_(new DataFetcher()),
        connectionPool_(std::make_shared<ConnectionPool>(20000)),
        logger_(boost::log::trivial::severity >= boost::log::trivial::info) {
            init();
    }

    ~DataIngestionClient() = default;

    void init() {
        // Initialize the data fetcher
        dataFetcher_->init(connectionPool_);

        // Initialize the connection pool
        connectionPool_->init(ioService_, 20000);

        // Load the configuration file
        ptree config;
        read_json(configFilePath, config);

        // Set up the logging
        boost::log::core::get()->set_filter(boost::log::trivial::severity >= config.get<int>("LogLevel"));
        if (config.get<bool>("EnableConsoleLogging")) {
            boost::log::add_console_log(std::cout, boost::log::keywords::format = "%TimeStamp% %Severity% [%ThreadID%] %Message%");
        }
        if (config.get<bool>("EnableFileLogging")) {
            boost::log::add_file_log(boost::log::keywords::file_name = "logs/client-%TimeStamp%.log", boost::log::keywords::rotation_size = 10 * 1024 * 1024, boost::log::keywords::time_based_rotation = boost::log::sinks::file::rotation_at_time_point(0, 0, 0), boost::log::keywords::auto_flush = true);
        }
    }

    void run() {
        // Start the data fetcher
        dataFetcher_->start();

        // Start the connection pool
        connectionPool_->start(ioService_);

        // Start the async logging thread
        boost::thread loggerThread([this] {
            while (true) {
                try {
                    ioService_.run();
                } catch (const std::exception& e) {
                    BOOST_LOG_TRIVIAL(error) << "Error running the async logging thread: " << e.what();
                }
            }
        });
    }

private:
    class DataFetcher {
