public MoSTState loadStateOrRecycleTheme(String themeId) throws IOException {
    // Load theme identifiers from configuration file
    String[] themeIds = null;
    synchronized (themeCache) {
        if (themeCache.containsKey(themeId)) {
            return themeCache.get(themeId);
        } else {
            themeIds = loadThemeIdentifiers();
        }
    }

    // Verify default theme directory
    String defaultThemeDir = "default/";
    if (themeIds == null || themeIds.length == 0) {
        defaultThemeDir = "default/";
    } else {
        for (String id : themeIds) {
            if (id.equals(themeId)) {
                defaultThemeDir = "themes/" + id;
                break;
            }
        }
    }

    // Parse PNG file from cache root directory and store in theme cache
    File cacheRoot = new File("cache/");
    File themeFile = new File(cacheRoot, defaultThemeDir);
    MoSTState state = null;
    try (ObjectInputStream inputStream = new ObjectInputStream(new FileInputStream(themeFile))) {
        state = (MoSTState) inputStream.readObject();
    } catch (IOException | ClassNotFoundException e) {
        // Handle exception gracefully
        log.error("Error loading theme: " + themeId, e);
    }

    // Recycle theme bitmap if not already recycled
    if (state != null && state.getBitmap() != null) {
        synchronized (themeCache) {
            if (!state.getBitmap().isRecycled()) {
                state.getBitmap().recycle();
                state.setBitmap(null);
            }
        }
    }

    // Cache theme in memory and return it
    synchronized (themeCache) {
        themeCache.put(themeId, state);
        return state;
    }
}
```
