#include <assert.h>

// Define the structure for holding the items
typedef struct {
    int id;
    double value;
    char* text;
} item_t;

// Define the hash table for storing the items
static item_t* items = NULL;

// Function to dynamically manage memory for the hash table
void resize_items(size_t size) {
    if (items == NULL || size > 0) {
        // Reallocate the memory for the items
        items = realloc(items, size * sizeof(item_t));
        assert(items != NULL);

        // Initialize the new items to empty values
        for (size_t i = 0; i < size; i++) {
            items[i].id = -1;
            items[i].value = 0.0;
            items[i].text = NULL;
        }
    }
}

// Function to add an item to the hash table
void add_item(int id, double value, const char* text) {
    // Check if the item already exists in the hash table
    for (size_t i = 0; i < size; i++) {
        if (items[i].id == id) {
            return;
        }
    }

    // Add the new item to the hash table
    items[size].id = id;
    items[size].value = value;
    items[size].text = strdup(text);
}

// Function to update an item in the hash table
void update_item(int id, double value, const char* text) {
    // Check if the item exists in the hash table
    for (size_t i = 0; i < size; i++) {
        if (items[i].id == id) {
            items[i].value = value;
            items[i].text = strdup(text);
            return;
        }
    }
}

// Function to delete an item from the hash table
void delete_item(int id) {
    // Check if the item exists in the hash table
    for (size_t i = 0; i < size; i++) {
        if (items[i].id == id) {
            items[i] = items[size - 1];
            size--;
            return;
        }
    }
}

// Function to retrieve an item from the hash table
item_t* get_item(int id) {
    // Check if the item exists in the hash table
    for (size_t i = 0; i < size; i++) {
        if (items[i].id == id) {
            return &items[i];
        }
    }
}
