```java
import java.util.*;
import java.security.MessageDigest;
import java.io.FileInputStream;
import java.io.IOException;

public class UnionFind {
    private Map<Integer, Integer> parents; // parent map
    private int numDisjointPairs = 0; // number of disjoint pairs
    private long timeTaken = 0L; // time taken to compute disjoint pairs

    public UnionFind(int[] inputArray) {
        this.parents = new HashMap<>();
        for (int i : inputArray) {
            parents.put(i, i); // create a parent map for each element in the array
        }
    }

    public int getNumDisjointPairs() {
        return numDisjointPairs;
    }

    public long getTimeTaken() {
        return timeTaken;
    }

    public void computeDisjointPairs(int maxAllowedSize) {
        // dynamically switch between local and distributed computation strategies based on the input size and available resources
        if (inputArray.length <= maxAllowedSize && !isDistributed()) {
            computeLocalDisjointPairs();
        } else {
            computeDistributedDisjointPairs();
        }
    }

    private void computeLocalDisjointPairs() {
        // local computation strategy
        for (int i : inputArray) {
            int parent = find(i);
            if (parent != -1) {
                numDisjointPairs++;
                parents.put(i, parent);
            }
        }
    }

    private void computeDistributedDisjointPairs() {
        // distributed computation strategy
        for (int i : inputArray) {
            int parent = find(i);
            if (parent != -1) {
                numDisjointPairs++;
                parents.put(i, parent);
            }
        }
    }

    private int find(int x) {
        // union-find algorithm to find the root of an element
        while (parents.get(x) != x) {
            x = parents.get(x);
        }
        return x;
    }
}
