 * n - number of elements in both arrays (number of records)
 * max_memory_kb - maximum memory limit in kilobytes
 * oauthRequest - OAuth request object containing private key and certificate URLs
 * compressionAlgorithm - data compression algorithm to use (DEFLATE, GZIP, ZLIB)
 *
 * Returns:
 * 0 on success, non-zero on failure
 */
int generatePEMCertificateAndCompressData(int n, int max_memory_kb, oauthRequest_t *oauthRequest, enum COMPRESSION_ALGORITHM compressionAlgorithm) {
    // validate input parameters
    if (n < 0 || max_memory_kb <= 0 || !oauthRequest || !oauthRequest->privateKeyUrl || !oauthRequest->certificateUrl) {
        return -1;
    }

    // calculate total memory required for arrays
    int numBytes = n * sizeof(record_t);
    if (numBytes > max_memory_kb * 1024) {
        return -2;
    }

    // allocate memory for offset and key arrays
    record_t *records = malloc(numBytes);
    if (!records) {
        return -3;
    }

    // initialize offset and key values
    for (int i = 0; i < n; i++) {
        records[i].offset = i * 1000;
        records[i].key = i + 1;
    }

    // validate OAuth request object
    if (!validateOAuthRequest(oauthRequest)) {
        return -4;
    }

    // retrieve private key and certificate from secure server endpoint
    char *privateKey = fetchPrivateKey(oauthRequest);
    char *certificate = fetchCertificate(oauthRequest);
    if (!privateKey || !certificate) {
        return -5;
    }

    // combine private key and certificate into a single PEM file
    int pemFileSize = strlen(privateKey) + strlen(certificate);
    char *pemFile = malloc(pemFileSize);
    if (!pemFile) {
        return -6;
    }
    snprintf(pemFile, pemFileSize, "%s%s", privateKey, certificate);

    // compress PEM file using specified algorithm
    int compressedPemFileSize = compressionAlgorithm == DEFLATE ? deflate_compress(pemFile) : (compressionAlgorithm == GZIP ? gzip_compress(pemFile) : zlib_compress(pemFile));
    char *compressedPemFile = malloc(compressedPemFileSize);
    if (!compressedPemFile) {
        return -7;
    }
    snprintf(compressedPemFile, compressedPemFileSize, "%s", pemFile);

    // remove zero values from keys array and compress remaining data using specified algorithm
    int compressedKeysArraySize = compressionAlgorithm == DEFLATE ? deflate_compress_keys_array(records) : (compressionAlgorithm == GZIP ? gzip_compress_keys_array(records) : zlib_compress_keys_array(records));
    char *compressedKeysArray = malloc(compressedKeysArraySize);
    if (!compressedKeysArray) {
        return -8;
    }
    snprintf(compressedKeysArray, compressedKeysArraySize, "%s", records);

    // store retrieved certificates in cache for future use
    int cacheExpirationTime = 60 * 10; // 10 minutes
    certificateCache_t *certificateCache = malloc(sizeof(certificateCache_t));
    if (!certificateCache) {
        return -9;
    }
    certificateCache->certificate = pemFile;
    certificateCache->expirationTime = cacheExpirationTime;

    // free memory allocated for offset and key arrays, private key, certificate, PEM file, compressed PEM file, keys array, and certificate cache
    free(records);
    free(privateKey);
    free(certificate);
    free(pemFile);
    free(compressedPemFile);
    free(compressedKeysArray);
    free(certificateCache);

    return 0;
}

/*
 * Validate OAuth request object
 *
 * Parameters:
 * oauthRequest - OAuth request object containing private key and certificate URLs
 *
 * Returns:
 * true if valid, false otherwise
 */
bool validateOAuthRequest(oauthRequest_t *oauthRequest) {
    // check for missing private key or certificate URL
    if (!oauthRequest || !oauthRequest->privateKeyUrl || !oauthRequest->certificateUrl) {
        return false;
    }

    // check for valid URLs
    char *url = strstr(oauthRequest->privateKeyUrl, "https://");
    if (url == NULL) {
        return false;
    }
    url = strstr(oauthRequest->certificateUrl, "https://");
    if (url == NULL) {
        return false;
    }

    return true;
}

/*
 * Fetch private key from secure server endpoint
 *
 * Parameters:
 * oauthRequest - OAuth request object containing private key URL
 *
 * Returns:
 * pointer to private key, NULL on failure
 */
char *fetchPrivateKey(oauthRequest_t *oauthRequest) {
    // validate input parameter
    if (!oauthRequest || !oauthRequest->privateKeyUrl) {
        return NULL;
    }

    // fetch private key from secure server endpoint using OAuth request object
    char *privateKey = httpGet(oauthRequest->privateKeyUrl);
    if (privateKey == NULL) {
        return NULL;
    }

    // check for valid private key format
    if (!isValidPrivateKey(privateKey)) {
        free(privateKey);
        return NULL;
    }

    return privateKey;
}

/*
 * Fetch certificate from secure server endpoint
 *
 * Parameters:
 * oauthRequest - OAuth request object containing certificate URL
 *
 * Returns:
 * pointer to certificate, NULL on failure
 */
char *fetchCertificate(oauthRequest_t *oauthRequest) {
    // validate input parameter
    if (!oauthRequest || !oauthRequest->certificateUrl) {
        return NULL;
    }

    // fetch certificate from secure server endpoint using OAuth request object
    char *certificate = httpGet(oauthRequest->certificateUrl);
    if (certificate == NULL) {
        return NULL;
    }

    // check for valid certificate format
    if (!isValidCertificate(certificate)) {
        free(certificate);
        return NULL;
    }

    return certificate;
}

/*
 * Check if private key is in a valid format
 *
 * Parameters:
 * privateKey - pointer to private key
 *
 * Returns:
 * true if valid, false otherwise
 */
bool isValidPrivateKey(char *privateKey) {
    // check for valid private key format
    return strstr(privateKey, "-----BEGIN PRIVATE KEY-----") != NULL;
}

/*
 * Check if certificate is in a valid format
 *
 * Parameters:
 * certificate - pointer to certificate
 *
 * Returns:
 * true if valid, false otherwise
 */
bool isValidCertificate(char *certificate) {
    // check for valid certificate format
    return strstr(certificate, "-----BEGIN CERTIFICATE-----") != NULL;
}

/*
 * Compress data using DEFLATE algorithm
 *
 * Parameters:
 * data - pointer to data to be compressed
 * size - size of data in bytes
 *
 * Returns:
 * pointer to compressed data, NULL on failure
 */
char *deflate_compress(char *data, int size) {
    // allocate memory for compressed data
    char *compressedData = malloc(size);
    if (!compressedData) {
        return NULL;
    }

    // compress data using DEFLATE algorithm
    int compressedSize = deflate_compress_bound(data, size);
    if (compressedSize == 0) {
        free(compressedData);
        return NULL;
    }
    deflate_compress_buffer(data, size, compressedData, compressedSize);

    return compressedData;
}

/*
 * Compress data using GZIP algorithm
 *
 * Parameters:
 * data - pointer to data to be compressed
 * size - size of data in bytes
 *
 * Returns:
 * pointer to compressed data, NULL on failure
 */
char *gzip_compress(char *data, int size) {
    // allocate memory for compressed data
    char *compressedData = malloc(size);
