    return compressedData;
}

/*
 * Compress data using DEFLATE algorithm and remove zero values from keys array
 *
 * Parameters:
 * records - pointer to array of records
 * size - number of elements in the array
 *
 * Returns:
 * number of bytes required for compressed data, 0 on failure
 */
int deflate_compress_keys_array(record_t *records, int size) {
    // remove zero values from keys array and compress remaining data using DEFLATE algorithm
    char *data = malloc(size * sizeof(record_t));
    if (!data) {
        return 0;
    }
    int numBytes = 0;
    for (int i = 0; i < size; i++) {
        if (records[i].key != 0) {
            memcpy(data + numBytes, &records[i], sizeof(record_t));
            numBytes += sizeof(record_t);
        }
    }
    int compressedSize = deflate_compress_bound(data, numBytes);
    if (compressedSize == 0) {
        free(data);
        return 0;
    }

    return numBytes;
}

