 * Returns:
 * true on success, false on failure
 */
bool deflate_compress_to_file(char *data, int size, char *filename) {
    // open output file
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        return false;
    }

    // compress data using DEFLATE algorithm
    int compressedSize = deflate_compress_bound(data, size);
    char *compressedData = malloc(compressedSize);
    if (!compressedData) {
        free(file);
        return false;
    }
    deflate_compress_buffer(data, size, compressedData, compressedSize);

    // write compressed data to output file
    int result = fwrite(compressedData, 1, compressedSize, file);
    free(file);
    if (result != compressedSize) {
        return false;
    }

    return true;
}

