import java.util.*;
import java.lang.*;
import java.io.*;
import java.util.concurrent.locks.*;

public class InventoryManager {
    private Map<Long, Product> products;
    private Map<Long, Order> orders;
    private Lock lock = new ReentrantLock();

    public void manageProductInventory() {
        // Initialize products with random values within specified ranges for identifiers, stock levels, and prices.
        products = new HashMap<>();
        for (int i = 0; i < 1000; i++) {
            Product product = new Product();
            product.setProductID(ThreadLocalRandom.current().nextLong(1, 100));
            product.setSupplierID(ThreadLocalRandom.current().nextLong(1, 100));
            product.setCategory(ThreadLocalRandom.current().nextInt(1, 10));
            product.setStockLevel(ThreadLocalRandom.current().nextInt(1, 100));
            product.setPrice(ThreadLocalRandom.current().nextDouble(1, 100));
            product.setLastUpdatedTimestamp(System.currentTimeMillis());
            products.put(product.getProductID(), product);
        }

        // Initialize orders with random values for order IDs and customer IDs.
        orders = new HashMap<>();
        for (int i = 0; i < 1000; i++) {
            Order order = new Order();
            order.setOrderID(ThreadLocalRandom.current().nextLong(1, 100));
            order.setCustomerID(ThreadLocalRandom.current().nextLong(1, 100));
            orders.put(order.getOrderID(), order);
        }
    }

    public void addProduct(Product product) {
        lock.lock();
        try {
            products.put(product.getProductID(), product);
        } finally {
            lock.unlock();
        }
    }

    public Product getProduct(Long productID) {
        lock.lock();
        try {
            return products.get(productID);
        } finally {
            lock.unlock();
        }
    }

    public void addOrder(Order order) {
        lock.lock();
        try {
            orders.put(order.getOrderID(), order);
        } finally {
            lock.unlock();
        }
    }

    public Order getOrder(Long orderID) {
        lock.lock();
        try {
            return orders.get(orderID);
        } finally {
            lock.unlock();
        }
    }

    public void updateProductStockLevel(Long productID, Integer stockLevel) {
        Product product = getProduct(productID);
        if (product != null) {
            product.setStockLevel(stockLevel);
        }
    }

    public void updateOrderStatus(Long orderID, OrderStatus status) {
        Order order = getOrder(orderID);
        if (order != null) {
            order.setStatus(status);
        }
    }

    public List<Product> getAllProducts() {
        return new ArrayList<>(products.values());
    }

    public List<Order> getAllOrders() {
        return new ArrayList<>(orders.values());
    }

    public void serializeOrdersToJSON(String filePath) throws IOException {
        lock.lock();
        try {
            FileWriter writer = new FileWriter(filePath);
            writer.write("[");
            for (Order order : orders.values()) {
                writer.write(order.toJSON());
                if (orders.size() != 1) {
                    writer.write(", ");
                }
            }
            writer.write("]");
            writer.close();
        } finally {
            lock.unlock();
        }
    }

    public void deserializeOrdersFromJSON(String filePath) throws IOException {
        FileReader reader = new FileReader(filePath);
        BufferedReader bufferedReader = new BufferedReader(reader);
        String line;
        while ((line = bufferedReader.readLine()) != null) {
            if (line.startsWith("[")) {
                break;
            }
        }
        List<Order> orders = new ArrayList<>();
        while ((line = bufferedReader.readLine()) != null) {
            if (!line.startsWith("[")) {
                Order order = new Order();
                order.fromJSON(line);
                orders.add(order);
            }
        }
    }
}
