    if (state) {
        strcpy(state->configParam, configParam);
        state->statusCode = calculateStatus(state->deviceId, state->configParam);
    } else {
        fprintf(stderr, "Device ID %d not found\n", deviceId);
    }

    // Unlock the mutex after accessing the device state
    pthread_mutex_unlock(&memMutex);
}

// Function to calculate the status code based on the device ID and configuration parameter
int calculateStatus(int deviceId, const char* configParam) {
    int status = 0;

    // Calculate the status using the modulus of the device ID and a predefined constant
    if (deviceId % STATUS_CONSTANT == 0) {
        status = 1;
    } else {
        status = 2;
    }

    return status;
}

// Function to deallocate memory for the array of device states
void deallocateDeviceStates(deviceState* states) {
    // Lock the mutex to prevent concurrent access to the memory usage variable
    pthread_mutex_lock(&memMutex);

    // Update the total memory usage after deallocating the memory for the device states
    long memUsage = sizeof(deviceState) * numDevices;
    totalMemUsage -= memUsage;

    // Deallocate memory for the array of device states using aligned memory allocation
    free(states);

    // Unlock the mutex after deallocating the memory for the device states
    pthread_mutex_unlock(&memMutex);
