    // Log the error message
    printf("%s\n", message);

    // Suggest corrections for common input errors
    if (strcmp(message, "Error: Input exceeds maximum limit. Please enter a valid value.") == 0) {
        printf("Suggestion: Decrease the maximum limit or use a smaller number of measurements.\n");
    } else if (strcmp(message, "Error: Invalid device ID. Please enter a valid ID.") == 0) {
        printf("Suggestion: Check the device ID again and make sure it is not negative.\n");
    } else if (strcmp(message, "Warning: Incorrect time zone for timestamp. Please check the current location.") == 0) {
        printf("Suggestion: Ensure that the current location matches the time zone used in the simulation.\n");
    } else if (strcmp(message, "Error: Incorrect latitude or longitude value. Please enter a valid value.") == 0) {
        printf("Suggestion: Check the latitude and longitude values again and make sure they are within the range of -90 to 90 for latitude and -180 to 180 for longitude.\n");
    } else if (strcmp(message, "Error: Missing or erroneous data from external data source. Using default value.") == 0) {
        printf("Suggestion: Check the external data source again and make sure it is providing accurate information.\n");
    }
}

// Function to validate user inputs for the sizes of all arrays to ensure they do not exceed a predefined maximum limit, which should be configurable at runtime
void validate_inputs(int *energy_measurements, int *timestamp_array, int *device_id_array, int *latitude_longitude_array) {
    // Validate user input for energy measurements array size
    if (*energy_measurements > MAXIMUM_MEASUREMENTS) {
        error_handling("Error: Input exceeds maximum limit. Please enter a valid value.");
    }

    // Validate user input for timestamp array size
    if (*timestamp_array > MAXIMUM_TIMESTAMPS) {
        error_handling("Error: Input exceeds maximum limit. Please enter a valid value.");
    }

    // Validate user input for device ID array size
    if (*device_id_array > MAXIMUM_DEVICE_IDS) {
        error_handling("Error: Input exceeds maximum limit. Please enter a valid value.");
    }

    // Validate user input for latitude and longitude arrays size
    if (*latitude_longitude_array > MAXIMUM_LATITUDE_LONGITUDE) {
        error_handling("Error: Input exceeds maximum limit. Please enter a valid value.");
    }
}

