  struct tm* current_time = get_current_time();

  // Calculate time difference between the current timestamp and the last timestamp
  double time_diff = (current_time->tm_year - last_time.tm_year) * 12 + (current_time->tm_mon - last_time.tm_mon) * 30 +
                     (current_time->tm_mday - last_time.tm_mday) * 24 + (current_time->tm_hour - last_time.tm_hour) * 60 +
                     (current_time->tm_min - last_time.tm_min) * 60 + (current_time->tm_sec - last_time.tm_sec);

  // Update last timestamp
  memcpy(&last_time, current_time, sizeof(struct tm));

  // Calculate memory and CPU usage
  struct sysinfo info;
  int res = sysinfo(&info);
  if (res == -1) {
    log_error("Error getting system information");
    return;
  }
  double memory_usage = ((double)info.mem_unit * info.totalram - (double)info.mem_unit * info.freeram) /
                        ((double)info.mem_unit * info.totalram);
  double cpu_usage = (double)info.procs / (double)info.uptime;

  // Print monitoring information
  printf("Memory usage: %.2f%%\nCPU usage: %.2f%%\n", memory_usage, cpu_usage);
}

// Update cached energy records with recent energy consumption values
void update_cache() {
