// Handle memory exhaustion scenarios gracefully by reducing memory usage and performance
void handle_memory_exhaustion() {
  // Check if the maximum size of the list of energy measurements has been exceeded
  if (energy_records_count >= MAX_MEASUREMENTS) {
    // Reduce the size of the string pool to prevent memory exhaustion
    string_pool = realloc(string_pool, MEMORY_LIMIT);
    if (string_pool == NULL) {
