    fprintf(fp, "%lu %lf %d %d %d %d %d %d %lf %lf\n", record->device_id, record->consumption,
            record->timestamp.tm_year, record->timestamp.tm_mon, record->timestamp.tm_mday, record->timestamp.tm_hour,
