#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define struct for task data
typedef struct {
    char* description;
    time_t dueDate;
    int priorityLevel;
    char* category;
} Task;

// Define array to store tasks
Task* tasks = NULL;
int capacity = 500; // Default maximum capacity of tasks
int count = 0; // Current number of tasks stored in the array

// Define custom comparison function for sorting tasks by category and priority level
int compareTasks(const void* task1, const void* task2) {
    Task* t1 = (Task*)task1;
    Task* t2 = (Task*)task2;
    int cmp = strcmp(t1->category, t2->category);
    if (cmp != 0) return cmp;
    return t1->priorityLevel - t2->priorityLevel;
}

// Define function to create a new task
int createTask(const char* description, time_t dueDate, int priorityLevel, const char* category) {
    // Check if the maximum capacity has been reached
    if (count == capacity) return -1;
    // Allocate memory for the new task
    Task* newTask = malloc(sizeof(Task));
    if (!newTask) return -2;
    // Initialize the task data
    newTask->description = strdup(description);
    newTask->dueDate = dueDate;
    newTask->priorityLevel = priorityLevel;
    newTask->category = strdup(category);
    // Add the new task to the array
    tasks[count++] = newTask;
    return 0;
}

// Define function to modify an existing task
int modifyTask(int index, const char* description, time_t dueDate, int priorityLevel, const char* category) {
    // Check if the index is out of bounds
    if (index < 0 || index >= count) return -1;
    // Update the task data
    Task* task = tasks[index];
    free(task->description);
    task->description = strdup(description);
    task->dueDate = dueDate;
    task->priorityLevel = priorityLevel;
    task->category = strdup(category);
    return 0;
}

// Define function to delete an existing task
int deleteTask(int index) {
    // Check if the index is out of bounds
    if (index < 0 || index >= count) return -1;
    // Remove the task from the array
    Task* task = tasks[index];
    free(task->description);
    free(task->category);
    memmove(&tasks[index], &tasks[index+1], (count-index-1)*sizeof(Task));
    count--;
    return 0;
}

// Define function to sort the tasks by category and priority level
void sortTasks() {
    qsort(tasks, count, sizeof(Task), compareTasks);
}

// Define function to report summary statistics after each session
void printSummaryStats() {
    printf("Total number of tasks: %d\n", count);
    int sumPriorityLevels = 0;
    for (int i = 0; i < count; i++) {
        sumPriorityLevels += tasks[i]->priorityLevel;
    }
    double avgPriorityLevel = (double)sumPriorityLevels / count;
    printf("Average priority level: %.2f\n", avgPriorityLevel);
    int mostFrequentCategory = -1;
    int frequency = 0;
    for (int i = 0; i < count; i++) {
        if (tasks[i]->category == NULL) continue;
        int currFreq = 0;
        for (int j = i+1; j < count; j++) {
            if (strcmp(tasks[j]->category, tasks[i]->category) == 0) {
                currFreq++;
            }
        }
        if (currFreq > frequency) {
            mostFrequentCategory = i;
            frequency = currFreq;
        }
    }
    printf("Most frequent category: %s (%d tasks)\n", tasks[mostFrequentCategory]->category, frequency);
}

int main() {
    // Load existing data from a file or database
    FILE* fp = fopen("tasks.txt", "r");
    if (fp) {
        while (!feof(fp)) {
            Task* task = malloc(sizeof(Task));
            fscanf(fp, "%s %d %d %s\n", task->description, &task->dueDate, &task->priorityLevel, task->category);
            createTask(task->description, task->dueDate, task->priorityLevel, task->category);
        }
    }
    fclose(fp);

    // Process tasks as required
    while (1) {
        // Handle user input or interrupts gracefully
        int choice;
        printf("Enter your choice: ");
        scanf("%d", &choice);
        switch (choice) {
            case 0: // Create new task
                char* description = readString();
                time_t dueDate = readTime();
                int priorityLevel = readInt();
                const char* category = readString();
                createTask(description, dueDate, priorityLevel, category);
                break;
            case 1: // Modify existing task
                int index = readInt();
                if (index < 0 || index >= count) {
                    printf("Invalid task index\n");
                    continue;
                }
                char* description = readString();
                time_t dueDate = readTime();
                int priorityLevel = readInt();
                const char* category = readString();
                modifyTask(index, description, dueDate, priorityLevel, category);
                break;
            case 2: // Delete existing task
                int index = readInt();
                if (index < 0 || index >= count) {
                    printf("Invalid task index\n");
                    continue;
                }
                deleteTask(index);
                break;
            case 3: // Sort tasks by category and priority level
                sortTasks();
                break;
            case 4: // Report summary statistics
                printSummaryStats();
                break;
        }
    }

    return 0;
}
