#include <string>
#include <vector>
#include <iostream>
#include <fstream>
#include <sstream>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <algorithm>
#include <chrono>
#include <cstdlib>

using namespace std;

struct Record {
    string name;
    double value;
};

class DynamicDataFlow {
public:
    DynamicDataFlow(const string& file_path) : file_path_(file_path) {
        // Initialize buffer with an empty vector
        buffer_.resize(0);

        // Open the file for reading
        ifstream file(file_path_);
        if (!file.is_open()) {
            cerr << "Error: Could not open file " << file_path_ << endl;
            return;
        }

        // Read and parse the file contents into the buffer
        string line;
        while (getline(file, line)) {
            Record record;
            stringstream ss(line);
            ss >> record.name >> record.value;
            buffer_.push_back(record);
        }

        // Close the file
        file.close();
    }

    void handleDynamicDataFlow() {
        // Set up a mutex for thread safety
        mutex mtx;

        // Set up a condition variable to signal new records
        condition_variable cv;

        // Create a vector of threads to read from the file and process the records concurrently
        vector<thread> threads(10);
        for (int i = 0; i < 10; ++i) {
            threads[i] = thread([this, &mtx, &cv]() {
                // Read and parse the file contents into the buffer
                string line;
                while (getline(file_, line)) {
                    Record record;
                    stringstream ss(line);
                    ss >> record.name >> record.value;
                    mtx.lock();
                    buffer_.push_back(record);
                    mtx.unlock();
                }
            });
        }

        // Join all the threads to ensure they have finished processing the file
        for (int i = 0; i < 10; ++i) {
            threads[i].join();
        }
    }

    void search(const string& substr) {
        // Set up a mutex for thread safety
        mutex mtx;

        // Set up a condition variable to signal new records
        condition_variable cv;

        // Create a vector of threads to read from the buffer and perform searches concurrently
        vector<thread> threads(10);
        for (int i = 0; i < 10; ++i) {
            threads[i] = thread([this, &mtx, &cv, substr]() {
                // Search the buffer for records with names containing the given substring
                Record record;
                mtx.lock();
                auto it = find_if(buffer_.begin(), buffer_.end(), [substr](const Record& r) { return r.name.find(substr) != string::npos; });
                if (it != buffer_.end()) {
                    record = *it;
                }
                mtx.unlock();
            });
        }

        // Join all the threads to ensure they have finished searching the buffer
        for (int i = 0; i < 10; ++i) {
            threads[i].join();
        }
    }

    void printLargestRecord() {
        // Set up a mutex for thread safety
        mutex mtx;

        // Set up a condition variable to signal new records
        condition_variable cv;

        // Create a vector of threads to read from the buffer and print the largest record concurrently
        vector<thread> threads(10);
        for (int i = 0; i < 10; ++i) {
            threads[i] = thread([this, &mtx, &cv]() {
                // Print the largest record in the buffer
                Record largest_record;
                mtx.lock();
                auto it = max_element(buffer_.begin(), buffer_.end(), [](const Record& lhs, const Record& rhs) { return lhs.value < rhs.value; });
                if (it != buffer_.end()) {
                    largest_record = *it;
                }
                mtx.unlock();
            });
        }

        // Join all the threads to ensure they have finished printing the largest record
        for (int i = 0; i < 10; ++i) {
            threads[i].join();
        }
    }

private:
    ifstream file_;
    vector<Record> buffer_;
