        e.printStackTrace();
    }

    // Set up product inventory collection
    Map<String, Product> products = new HashMap<>();
    for (int i = 0; i < args[0]; i++) {
        int id = RandomUtils.nextInt(1000, 9999);
        int supplierId = RandomUtils.nextInt(1, 10);
        String category = RandomUtils.getRandomItem(Arrays.asList("Electronics", "Clothing", "Home goods", "Beauty"));
        int stockLevel = RandomUtils.nextInt(1, 20);
        double price = RandomUtils.nextDouble(100, 500);
        long lastUpdatedTimestamp = System.currentTimeMillis();
        Product product = new Product(id, supplierId, category, stockLevel, price, lastUpdatedTimestamp);
        products.put(product.getId(), product);
    }

    // Set up order collection
    Map<String, Order> orders = new HashMap<>();
    for (int i = 0; i < args[1]; i++) {
        int id = RandomUtils.nextInt(1000, 9999);
        int customerId = RandomUtils.nextInt(1, 50);
        List<ProductDetails> productDetails = new ArrayList<>();
        for (int j = 0; j < args[2]; j++) {
            Product product = products.get(RandomUtils.nextInt(0, products.size()));
            int quantity = RandomUtils.nextInt(1, 5);
            ProductDetails details = new ProductDetails(product.getId(), quantity);
            productDetails.add(details);
        }
        Order order = new Order(id, customerId, productDetails);
        orders.put(order.getId(), order);
    }

    // Set up synchronization mechanisms
    ReadWriteLock inventoryLock = new ReentrantReadWriteLock();
    Lock readLock = inventoryLock.readLock();
    Lock writeLock = inventoryLock.writeLock();

    // Set up thread pool for concurrent order processing
    ExecutorService executor = Executors.newCachedThreadPool();

    // Set up cooldown period to prevent overlapping order processing
    int cooldownPeriod = 10; // in minutes
    Map<String, Long> lastOrderProcessedTimestamps = new HashMap<>();

    // Set up caching mechanism for frequently accessed product details
    Map<String, ProductDetails> cachedProductDetails = new HashMap<>();

    while (true) {
        readLock.lock();
        try {
            // Process pending orders
            for (Map.Entry<String, Order> entry : orders.entrySet()) {
                String orderId = entry.getKey();
                Order order = entry.getValue();
                if (!lastOrderProcessedTimestamps.containsKey(orderId) ||
                        lastOrderProcessedTimestamps.get(orderId) + cooldownPeriod * 60 * 1000 < System.currentTimeMillis()) {
                    executor.execute(() -> processOrder(order, inventoryLock));
                }
            }

            // Update cached product details
            for (Map.Entry<String, ProductDetails> entry : products.entrySet()) {
                String productId = entry.getKey();
                ProductDetails details = entry.getValue();
                cachedProductDetails.put(productId, details);
            }

            // Log order processing metrics
            long startTime = System.currentTimeMillis();
            for (Map.Entry<String, Order> entry : orders.entrySet()) {
                String orderId = entry.getKey();
                Order order = entry.getValue();
                if (!lastOrderProcessedTimestamps.containsKey(orderId) ||
                        lastOrderProcessedTimestamps.get(orderId) + cooldownPeriod * 60 * 1000 < System.currentTimeMillis()) {
                    long processingTime = System.currentTimeMillis() - startTime;
                    logger.info("Processed order " + orderId + " in " + processingTime + " ms");
                }
            }

            // Log memory usage metrics
            Runtime runtime = Runtime.getRuntime();
            long totalMemory = runtime.totalMemory() - runtime.freeMemory();
            logger.info("Total memory used: " + totalMemory);
        } finally {
            readLock.unlock();
        }
    }
}

private static void processOrder(Order order, ReadWriteLock inventoryLock) {
    writeLock.lock();
    try {
        // Process order
        for (ProductDetails details : order.getProductDetails()) {
            Product product = products.get(details.getId());
            if (product != null && product.getStockLevel() >= details.getQuantity()) {
                product.setStockLevel(product.getStockLevel() - details.getQuantity());
                lastOrderProcessedTimestamps.put(order.getId(), System.currentTimeMillis());
            } else {
                // Add order to the pending orders list for retry
                pendingOrders.add(order);
            }
        }
    } finally {
        writeLock.unlock();
    }
}

private static void updateProductInventory(String[] args) {
    // Update product inventory collection
    Map<String, Product> products = new HashMap<>();
    for (int i = 0; i < args[0]; i++) {
        int id = RandomUtils.nextInt(1000, 9999);
        int supplierId = RandomUtils.nextInt(1, 10);
        String category = RandomUtils.getRandomItem(Arrays.asList("Electronics", "Clothing", "Home goods", "Beauty"));
        int stockLevel = RandomUtils.nextInt(1, 20);
        double price = RandomUtils.nextDouble(100, 500);
        long lastUpdatedTimestamp = System.currentTimeMillis();
        Product product = new Product(id, supplierId, category, stockLevel, price, lastUpdatedTimestamp);
        products.put(product.getId(), product);
    }

    // Update inventory collection with the new product inventory
    inventoryLock.writeLock().lock();
    try {
        for (Map.Entry<String, Product> entry : products.entrySet()) {
            String productId = entry.getKey();
            Product product = entry.getValue();
            if (product != null) {
                Product updatedProduct = new Product(product.getId(), product.getSupplierId(), product.getCategory(),
                        product.getStockLevel(), product.getPrice(), System.currentTimeMillis());
                products.put(updatedProduct.getId(), updatedProduct);
            } else {
                products.remove(productId);
            }
        }
    } finally {
        inventoryLock.writeLock().unlock();
    }
}

