struct Attack {
    char* name;
    double value;
};

class DynamicAttackManager {
private:
    vector<Attack> attacks;
    size_t maxNameLength = 0;
    double minStrength = 0.0;
    double maxStrength = 0.0;
    size_t totalBytesAllocated = 0;
    bool initialized = false;
public:
    DynamicAttackManager() {}
    ~DynamicAttackManager() {
        for (auto& attack : attacks) {
            delete[] attack.name;
        }
    }
    void init(size_t numAttacks, size_t maxNameLength, double minStrength, double maxStrength) {
        if (!initialized) {
            initialized = true;
            this->maxNameLength = maxNameLength;
            this->minStrength = minStrength;
            this->maxStrength = maxStrength;
            attacks.resize(numAttacks);
            for (auto& attack : attacks) {
                attack.name = new char[maxNameLength + 1];
                attack.value = minStrength + (rand() % static_cast<int>((maxStrength - minStrength) * 100)) / 100;
            }
        } else {
            throw "DynamicAttackManager already initialized!";
        }
    }
    void addAttack(const char* name, double value) {
        if (name.length() > maxNameLength) {
            throw "Name exceeds maximum length!";
        }
        if (value < minStrength || value > maxStrength) {
            throw "Value out of range!";
        }
        Attack newAttack;
        newAttack.name = new char[maxNameLength + 1];
        strcpy(newAttack.name, name);
        newAttack.value = value;
        attacks.push_back(newAttack);
    }
    void removeAttack(size_t index) {
        if (index >= attacks.size()) {
            throw "Invalid attack index!";
        }
        delete[] attacks[index].name;
        attacks.erase(attacks.begin() + index);
    }
    const char* getLongestAttackName() {
        const char* longestName = "";
        for (auto& attack : attacks) {
            if (strlen(attack.name) > strlen(longestName)) {
                longestName = attack.name;
            }
        }
        return longestName;
    }
    void selectAttackForCharacter() {
        // Select one of two predefined attacks for the character using a 9-second cooldown period between selections
        size_t attackIndex = rand() % 2;
        cout << "Selected attack index: " << attackIndex << endl;
    }
    void updateMaxNameLength(size_t newMaxNameLength) {
        // Update the maximum length of attack names without reallocating the entire structure
        if (newMaxNameLength > maxNameLength) {
            maxNameLength = newMaxNameLength;
            for (auto& attack : attacks) {
                delete[] attack.name;
                attack.name = new char[maxNameLength + 1];
            }
        }
    }
    void updateStrengthRange(double newMinStrength, double newMaxStrength) {
        // Update the acceptable range of strength values without reallocating the entire structure
        if (newMinStrength < minStrength || newMaxStrength > maxStrength) {
            throw "New strength range exceeds existing bounds!";
        }
        minStrength = newMinStrength;
        maxStrength = newMaxStrength;
    }
    size_t getNumAttacks() {
        // Return the number of attacks in the collection
        return attacks.size();
    }
    size_t getTotalBytesAllocated() {
        // Return the total number of bytes allocated for all attacks
        return totalBytesAllocated;
    }
    void printAttacks() {
        // Print all attacks in the collection, including name and value
        cout << "Total number of attacks: " << getNumAttacks() << endl;
        for (auto& attack : attacks) {
            cout << "Name: " << attack.name << ", Value: " << attack.value << endl;
        }
    }
};

void testDynamicAttackManager() {
