// Custom key filters based on regular expressions
static const char* KEY_FILTERS[] = {
    "^key1$", // Matches keys that exactly match the given string
    "^key2[0-9]+$", // Matches keys that start with "key2" and end with a number (e.g., "key21", "key22")
};

// Thread-safe data structures for managing shared resources
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static char** keys = NULL;
static size_t num_keys = 0;
static size_t capacity = 0;

// Logging configuration
#define LOG_FILE "/var/log/config-parser.log"
#define LOG_LEVEL LOG_INFO // Supported levels: LOG_DEBUG, LOG_INFO, LOG_WARNING, LOG_ERROR

static void log(const char* message) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    const size_t timestamp = (size_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
    fprintf(stderr, "[%zu] %s\n", timestamp, message);
}

static void log_debug(const char* message) {
    if (LOG_LEVEL >= LOG_DEBUG) {
        log(message);
    }
}

static void log_info(const char* message) {
    if (LOG_LEVEL >= LOG_INFO) {
        log(message);
    }
}

static void log_warning(const char* message) {
    if (LOG_LEVEL >= LOG_WARNING) {
        log(message);
    }
}

static void log_error(const char* message) {
    if (LOG_LEVEL >= LOG_ERROR) {
        log(message);
    }
}

// Monitor configuration file for changes and re-parse it when necessary
static void monitor_file(const char* path) {
    struct stat st;
    while (1) {
        // Wait for a change in the file's modification time
        sleep(1);
        if (stat(path, &st)) {
            log_warning("Failed to get file status");
            continue;
        }
        time_t mtime = st.st_mtime;
        // Check if the file has been modified since last parsed
        if (mtime != last_parsed_mtime) {
            log_info("Configuration file has changed, re-parsing...");
            parse_file(path);
            last_parsed_mtime = mtime;
        }
    }
}

// Parse a configuration file and populate the key list
static void parse_file(const char* path) {
    // Initialize variables for parsing
    FILE* fp = NULL;
    struct stat st;
    const size_t BUF_SIZE = 1024 * 1024; // 1 MB
    char buffer[BUF_SIZE];
    size_t num_read = 0;
    size_t i = 0;
    int ret = 0;

    // Open the file for reading
    if ((fp = fopen(path, "r")) == NULL) {
        log_warning("Failed to open configuration file");
        return;
    }

    // Get the file size and allocate memory for the buffer
    if (stat(path, &st)) {
        log_warning("Failed to get file status");
        fclose(fp);
        return;
    }
    const size_t file_size = st.st_size;
    if (file_size > BUF_SIZE) {
        log_info("Parsing large configuration file...");
    }

    // Read and parse the file in chunks, handling race conditions with locks
    pthread_mutex_lock(&mutex);
    while ((num_read = fread(buffer, 1, BUF_SIZE, fp)) > 0) {
        for (i = 0; i < num_read; ++i) {
            if (buffer[i] == '\n') {
                // Process the current line
                ret = parse_line(buffer + i);
                if (ret != 0) {
                    log_error("Failed to parse line");
                    break;
                }
            }
        }
    }
    pthread_mutex_unlock(&mutex);

    // Close the file and free resources
    fclose(fp);
}

// Parse a single line of the configuration file
static int parse_line(const char* line) {
    const char* delim = "=";
    char* key = NULL;
    char* value = NULL;
    // Split the line into key and value
    if ((key = strtok(line, delim)) == NULL || (value = strtok(NULL, delim)) == NULL) {
        return -1;
    }
    // Check if the key is a valid filter pattern
    size_t i = 0;
    for (i = 0; i < sizeof(KEY_FILTERS) / sizeof(char*); ++i) {
        regex_t filter;
        if ((ret = regcomp(&filter, KEY_FILTERS[i], REG_EXTENDED)) != 0) {
            log_error("Failed to compile regular expression");
            continue;
        }
        if (regexec(&filter, key, 0, NULL, 0) == 0) {
            // Add the key to the list
            pthread_mutex_lock(&mutex);
            if (num_keys >= capacity) {
                const size_t new_capacity = num_keys + BUF_SIZE;
                char** new_keys = realloc(keys, new_capacity * sizeof(char*));
                if (new_keys == NULL) {
                    log_error("Failed to allocate memory");
                    pthread_mutex_unlock(&mutex);
                    return -1;
                }
                keys = new_keys;
                capacity = new_capacity;
            }
            keys[num_keys] = strdup(key);
            ++num_keys;
            pthread_mutex_unlock(&mutex);
        }
    }
    return 0;
}

// Get a list of all unique keys in the configuration file, optionally filtered by regular expressions
char** get_keys(const char* path) {
    // Initialize variables for parsing
    FILE* fp = NULL;
    struct stat st;
    const size_t BUF_SIZE = 1024 * 1024; // 1 MB
    char buffer[BUF_SIZE];
    size_t num_read = 0;
    size_t i = 0;
    int ret = 0;

    // Open the file for reading
    if ((fp = fopen(path, "r")) == NULL) {
        log_warning("Failed to open configuration file");
        return NULL;
    }

    // Get the file size and allocate memory for the buffer
    if (stat(path, &st)) {
        log_warning("Failed to get file status");
        fclose(fp);
        return NULL;
    }
    const size_t file_size = st.st_size;
    if (file_size > BUF_SIZE) {
        log_info("Parsing large configuration file...");
    }

    // Read and parse the file in chunks, handling race conditions with locks
    pthread_mutex_lock(&mutex);
    while ((num_read = fread(buffer, 1, BUF_SIZE, fp)) > 0) {
        for (i = 0; i < num_read; ++i) {
            if (buffer[i] == '\n') {
                // Process the current line
                ret = parse_line(buffer + i);
                if (ret != 0) {
                    log_error("Failed to parse line");
                    break;
                }
            }
        }
    }
    pthread_mutex_unlock(&mutex);

    // Close the file and free resources
    fclose(fp);

    // Return a copy of the key list, ensuring that all memory is properly freed
    char** keys_copy = malloc(num_keys * sizeof(char*));
    if (keys_copy == NULL) {
        log_error("Failed to allocate memory");
        free(keys);
        return NULL;
    }
    memcpy(keys_copy, keys, num_keys * sizeof(char*));
    for (i = 0; i < num_keys; ++i) {
        char* key = keys[i];
        free(key);
    }
    free(keys);
    return keys_copy;
}
