    char line[500];
    while (fgets(line, sizeof(line), csv_file)) {
        // Check for header row
        if (row == 1) {
            row++;
            continue;
        }

        // Parse CSV line
        struct timestamp *temp_ts = strtok(line, ",");
        struct temperature *temp_temp = strtok(NULL, ",");
        struct weatherEvent *weatherEvent = strtok(NULL, ",");
        struct climateReport *climateReport = strtok(NULL, ",");

        // Check for NULL values
        if (temp_ts == NULL || temp_temp == NULL || weatherEvent == NULL || climateReport == NULL) {
            continue;
        }

        // Update structures
        ts->value = atoi(temp_ts);
        temp->value = (float)atof(temp_temp);
        we->description = strdup(weatherEvent->description);
        we->severity_level = weatherEvent->severity_level;
        we->wind_speed = (float)atof(weatherEvent->wind_speed);
        cr->average_temperature = (float)atof(climateReport->average_temperature);
        cr->season = strdup(climateReport->season);
        cr->coordinates.latitude = (float)atof(climateReport->coordinates.latitude);
        cr->coordinates.longitude = (float)atof(climateReport->coordinates.longitude);
    }
}

void exportDataToJSON(struct timestamp *ts, struct temperature *temp, struct weatherEvent *we, struct climateReport *cr) {
    // JSON output schema
    const char *json_schema = "{\"timestamp\": %lu,\"temperature\": %.2f,\"weatherEvent\": {\"description\": \"%s\",\"severityLevel\": %d,\"windSpeed\": %.2f},\"climateReport\": {\"averageTemperature\": %.2f,\"season\": \"%s\",\"coordinates\": {\"latitude\": %.2f,\"longitude\": %.2f}}}";

    // Convert structures to JSON strings
    char *ts_json = malloc(50);
    sprintf(ts_json, json_schema, ts->value, temp->value);
    char *we_json = malloc(100);
    sprintf(we_json, json_schema, we->description, we->severity_level, we->wind_speed);
    char *cr_json = malloc(200);
    sprintf(cr_json, json_schema, cr->average_temperature, cr->season, cr->coordinates.latitude, cr->coordinates.longitude);

    // Combine JSON strings into a single string
    char *output = malloc(strlen(ts_json) + strlen(we_json) + strlen(cr_json) + 10);
    sprintf(output, "%s,%s,%s", ts_json, we_json, cr_json);

    // Free memory
    free(ts_json);
    free(we_json);
    free(cr_json);

    return output;
}
