// Structure to hold weather data
typedef struct {
    float temperature;
    int timestamp;
    char description[256];
    double humidity;
} WeatherRecord;

// Function to process and print average temperature and humidity over time window
void processWeatherData(int numRecords, WeatherRecord *records) {
    // Initialize variables for average temperature and humidity
    float avgTemp = 0.0f;
    double avgHumidity = 0.0;

    // Calculate average temperature and humidity over time window
    for (int i = 0; i < numRecords; i++) {
        WeatherRecord *record = &records[i];
        // Calculate temperature based on timestamp and humidity level
        record->temperature = calculateTemperature(record->humidity, record->timestamp);
        // Add temperature to average
        avgTemp += record->temperature;
        // Add humidity to average
        avgHumidity += record->humidity;
    }

    // Calculate average temperature and humidity
    avgTemp /= numRecords;
    avgHumidity /= numRecords;

    // Print average temperature and humidity
    printf("Average temperature: %.2f\n", avgTemp);
    printf("Average humidity: %.2f\n", avgHumidity);
}

// Function to calculate temperature based on humidity level and timestamp
float calculateTemperature(double humidity, int timestamp) {
    // Calculate random noise within specified range
    double noise = (double)(rand() % NOISE_RANGE - NOISE_RANGE / 2.0);
    // Calculate fixed rate factor and add noise to humidity level
    humidity += RATE_FACTOR + noise;
    // Calculate temperature based on humidity level and timestamp
    float temperature = (float)(humidity * 1.8 + 32.0);
    return temperature;
}

// Function to validate input data and print error message if necessary
void validateInputData(int numRecords, WeatherRecord *records) {
    // Validate humidity levels are within predefined range
    for (int i = 0; i < numRecords; i++) {
        WeatherRecord *record = &records[i];
        if (record->humidity < 0.0 || record->humidity > 100.0) {
            printf("Invalid humidity level: %f\n", record->humidity);
            return;
        }
    }

    // Validate timestamps are in chronological order
    for (int i = 0; i < numRecords - 1; i++) {
        WeatherRecord *record1 = &records[i];
        WeatherRecord *record2 = &records[i + 1];
        if (record1->timestamp > record2->timestamp) {
            printf("Invalid timestamp order: %d, %d\n", record1->timestamp, record2->timestamp);
            return;
        }
    }
}

// Main function to manage weather data processing pipeline
int main() {
    // Initialize variables for number of records and array of records
    int numRecords = 0;
    WeatherRecord *records = NULL;

    // Read temperature, humidity, and timestamp values from standard input
    while (scanf("%d %lf %s %lf", &numRecords, &(records[numRecords].temperature), records[numRecords].description, &(records[numRecords].humidity)) == 4) {
        numRecords++;
    }

    // Dynamically allocate memory for array of weather records
    records = (WeatherRecord *)malloc(numRecords * sizeof(WeatherRecord));
    if (records == NULL) {
        printf("Error: Could not allocate memory for weather records\n");
        return 1;
    }

    // Process and print average temperature and humidity over time window
    processWeatherData(numRecords, records);

    // Free dynamically allocated memory for array of weather records
    free(records);

    return 0;
}
