Here is an example implementation of a C library that manages a flexible and scalable configuration registry:
```
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define the maximum capacity of the configuration registry
#define MAX_CONFIGURATIONS 100

// Structure to represent a configuration
typedef struct Configuration {
    char *name;
    char type;
    void *default_value;
    int num_parameters;
    char **parameters;
} Configuration;

// Comparison function for sorting configurations by name
int compare_configurations(const void *a, const void *b) {
    return strcmp(((Configuration *)a)->name, ((Configuration *)b)->name);
}

// Function to create a new configuration with the given name and type
Configuration *create_configuration(char *name, char type) {
    Configuration *config = malloc(sizeof(Configuration));
    config->name = strdup(name);
    config->type = type;
    config->default_value = NULL;
    config->num_parameters = 0;
    config->parameters = NULL;
    return config;
}

// Function to update the default value of a configuration
void update_configuration_default_value(Configuration *config, void *new_default_value) {
    assert(config != NULL);
    free(config->default_value);
    config->default_value = new_default_value;
}

// Function to add a parameter to a configuration
void add_parameter(Configuration *config, char *name, void *value) {
    assert(config != NULL);
    if (config->num_parameters == 0) {
        config->parameters = malloc(sizeof(char *) * MAX_CONFIGURATIONS);
    } else if (config->num_parameters >= MAX_CONFIGURATIONS) {
        fprintf(stderr, "Maximum capacity of configuration reached\n");
        return;
    }
    config->parameters[config->num_parameters] = strdup(name);
    config->parameters[config->num_parameters + 1] = value;
    config->num_parameters += 2;
}

// Function to delete a parameter from a configuration
void delete_parameter(Configuration *config, char *name) {
    assert(config != NULL);
    int i = 0;
    while (i < config->num_parameters && strcmp(config->parameters[i], name)) {
        i += 2;
    }
    if (i >= config->num_parameters) {
        fprintf(stderr, "Parameter not found\n");
        return;
    }
    int j = i + 1;
    while (j < config->num_parameters - 2) {
        config->parameters[j - 1] = config->parameters[j];
        config->parameters[j + 1] = config->parameters[j + 2];
        j += 2;
    }
    free(config->parameters[i]);
    free(config->parameters[i + 1]);
    config->num_parameters -= 2;
}

// Function to delete a configuration from the registry
void delete_configuration(Configuration *config) {
    assert(config != NULL);
    for (int i = 0; i < MAX_CONFIGURATIONS; i++) {
        if (strcmp(config->name, configurations[i].name)) {
            continue;
        }
        free(configurations[i].default_value);
        for (int j = 0; j < configurations[i].num_parameters; j += 2) {
            free(configurations[i].parameters[j]);
            free(configurations[i].parameters[j + 1]);
        }
        free(configurations[i].parameters);
        configurations[i] = NULL;
    }
}

// Function to print summary statistics for the registry
void print_summary_statistics() {
    int total_count = 0;
    int sum_memory_footprints = 0;
    int average_memory_footprint = 0;
    int num_parameters_per_configuration = 0;
    for (int i = 0; i < MAX_CONFIGURATIONS; i++) {
        if (!configurations[i]) {
            continue;
        }
        total_count++;
        sum_memory_footprints += sizeof(Configuration) + sizeof(char *) * configurations[i].num_parameters;
        num_parameters_per_configuration += configurations[i].num_parameters;
    }
    average_memory_footprint = sum_memory_footprints / total_count;
    printf("Summary statistics:\n");
    printf("Total count: %d\n", total_count);
    printf("Sum of memory footprints: %d bytes\n", sum_memory_footprints);
    printf("Average memory footprint: %.2f bytes/configuration\n", average_memory_footprint);
    printf("Number of parameters per configuration: %d\n", num_parameters_per_configuration / total_count);
}

// External API to add a new configuration
void add_configuration(char *name, char type) {
    Configuration *config = create_configuration(name, type);
    configurations[config->num_parameters] = config;
}

// External API to update the default value of a configuration
