// Define a custom memory pool for efficient allocation and deallocation
struct MemoryPool {
    size_t size;   // Size of the memory pool in bytes
    char* buffer;  // Pointer to the start of the memory pool
};

// Allocate memory from the memory pool using a first-fit algorithm
void* allocate(struct MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    size_t offset = 0;

    // Search for a contiguous block of free memory in the pool
    while (offset < pool->size) {
        if ((pool->buffer[offset] & 0x80) == 0) {
            // Found a free block, allocate memory from it
            ptr = pool->buffer + offset;
            break;
        }
        offset++;
    }

    // If no free block was found, return NULL
    if (ptr == NULL) {
        return NULL;
    }

    // Mark the allocated block as in use and return a pointer to it
    pool->buffer[offset] |= 0x80;
    return ptr;
}

// Deallocate memory from the memory pool using a first-fit algorithm
void deallocate(struct MemoryPool* pool, void* ptr) {
    size_t offset = (char*)ptr - pool->buffer;
    assert(offset < pool->size && (pool->buffer[offset] & 0x80) != 0);
    pool->buffer[offset] &= ~0x80;
}

