void deleteReading(SensorReading *readings, int numReadings, int index) {
    // Check if reading exists at specified index
    if (index < 0 || index >= numReadings) {
        return;
    }
    // Shift readings to the left by one position and update array size
    for (int i = index; i < numReadings - 1; i++) {
        readings[i] = readings[i + 1];
    }
    numReadings--;
}

// Define function to retrieve all readings from the data structure
void retrieveAllReadings(SensorReading *readings, int numReadings) {
    // Iterate through each reading and print its details
    for (int i = 0; i < numReadings; i++) {
        SensorReading *reading = readings + i;
        printf("Timestamp: %s\n", ctime(&reading->timestamp));
        printf("Temperature: %.2f\n", reading->temperature);
        printf("Humidity: %.2f\n", reading->humidity);
        printf("Pressure: %.2f\n", reading->pressure);
        printf("Status: %c\n", reading->status);
    }
}
