// Define the structure for sensor data
struct sensor_data {
    unsigned long timestamp;
    double measurement;
    enum status_code status_code;
};

// Define the low-pass filter parameters
#define FILTER_ALPHA 0.5 // adjustable parameter to balance noise reduction and signal fidelity
#define SEED 1234 // seed for the random number generator

// Define the error codes for memory allocation failures and invalid input data
#define MEMORY_ALLOCATION_ERROR -1
#define INVALID_DATA_ERROR -2

// Function to initialize the sensor data structures with a provided set of timestamps, measurements, and status codes
int init_sensor_data(struct sensor_data **data, size_t num_points, unsigned long *timestamps, double *measurements, enum status_code *status_codes) {
    // Check if the input data is valid
    if (num_points == 0 || timestamps == NULL || measurements == NULL || status_codes == NULL) {
        return INVALID_DATA_ERROR;
    }

    // Allocate memory for the sensor data structures
    *data = malloc(num_points * sizeof(**data));
    if (*data == NULL) {
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the sensor data structures with the provided timestamps, measurements, and status codes
    size_t i;
    for (i = 0; i < num_points; ++i) {
        (*data)[i].timestamp = timestamps[i];
        (*data)[i].measurement = measurements[i];
        (*data)[i].status_code = status_codes[i];
    }

    // Sort the sensor data structures by timestamp in ascending order
    qsort(*data, num_points, sizeof(**data), compare_sensor_data);

    // Apply the low-pass filter to smooth the measurements while preserving the integrity of the timestamps and status codes
    apply_low_pass_filter(data, num_points, FILTER_ALPHA, SEED);

    return 0;
}

// Comparison function for sorting the sensor data structures by timestamp in ascending order
int compare_sensor_data(const void *a, const void *b) {
    struct sensor_data *sa = (struct sensor_data *) a;
    struct sensor_data *sb = (struct sensor_data *) b;
    return sa->timestamp - sb->timestamp;
}

// Function to apply the low-pass filter to smooth the measurements while preserving the integrity of the timestamps and status codes
void apply_low_pass_filter(struct sensor_data **data, size_t num_points, double alpha, unsigned int seed) {
    // Initialize the random number generator with the provided seed
    srand(seed);

    // Define the filter coefficients for the low-pass filter
    const double a0 = 1 - alpha;
    const double a1 = alpha;
    const double b0 = 2 * (a0 - a1) / a0;
    const double b1 = -2 * (a0 + a1) / a0;

    // Define the state variables for the filter
    double x_prev = (*data)[0].measurement;
    double y_prev = x_prev;

    // Apply the low-pass filter to each measurement in the data set
    size_t i;
    for (i = 1; i < num_points; ++i) {
        double x = (*data)[i].measurement;
        double y = a0 * x + a1 * x_prev + b0 * y_prev + b1 * y;
        (*data)[i].measurement = y;
        x_prev = x;
        y_prev = y;
    }
}

// Main function to demonstrate the use of the init_sensor_data() function
int main() {
    // Define the maximum size of the data set and the time constraint for initialization
    const size_t num_points = 50000;
    unsigned long *timestamps = malloc(num_points * sizeof(*timestamps));
    double *measurements = malloc(num_points * sizeof(*measurements));
    enum status_code *status_codes = malloc(num_points * sizeof(*status_codes));

    // Generate a random seed for the random number generator
    unsigned int seed = (unsigned int) time(NULL);

    // Initialize the sensor data structures with a provided set of timestamps, measurements, and status codes
    struct sensor_data *data;
    if (init_sensor_data(&data, num_points, timestamps, measurements, status_codes) != 0) {
        printf("Error initializing the sensor data structures\n");
        return -1;
    }

    // Apply the low-pass filter to smooth the measurements while preserving the integrity of the timestamps and status codes
    apply_low_pass_filter(&data, num_points, FILTER_ALPHA, SEED);

    // Print the resulting sensor data structures
    for (size_t i = 0; i < num_points; ++i) {
        printf("Sensor data %lu: measurement = %.2f, status code = %d\n", data[i].timestamp, data[i].measurement, data[i].status_code);
    }

    // Free the memory allocated for the sensor data structures
    free(data);
    free(timestamps);
    free(measurements);
    free(status_codes);

    return 0;
}
```
