#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define a structure to represent a record in the configuration registry
typedef struct {
    int value;
} record_t;

// Define a structure to represent a configuration in the configuration registry
typedef struct {
    char* name;
    char type;
    void* default_value;
    size_t num_params;
    record_t* params;
} config_t;

// Function to create a new configuration registry and initialize it with the given number of configurations
config_t* create_registry(size_t num_configs) {
    // Allocate memory for an array of 'num_configs' config structures
    config_t* registry = malloc(sizeof(config_t) * num_configs);
    if (!registry) {
        fprintf(stderr, "Failed to allocate memory for configuration registry\n");
        exit(1);
    }

    // Initialize each configuration in the registry with default values
    for (size_t i = 0; i < num_configs; ++i) {
        config_t* config = &registry[i];
        config->name = NULL;
        config->type = '\0';
        config->default_value = NULL;
        config->num_params = 0;
        config->params = NULL;
    }

    return registry;
}

// Function to create a new configuration and add it to the given configuration registry
void add_config(config_t* registry, char* name, char type, void* default_value, size_t num_params) {
    // Check if there is enough space in the registry for the new configuration
    if (registry->num_configs >= registry->capacity) {
        // Reallocate memory for the registry to make room for the new configuration
        registry = realloc(registry, sizeof(config_t) * registry->capacity * 2);
        if (!registry) {
            fprintf(stderr, "Failed to reallocate memory for configuration registry\n");
            exit(1);
        }
        // Update the capacity of the registry
        registry->capacity = registry->capacity * 2;
    }

    // Create a new configuration and add it to the registry
    config_t* config = &registry[registry->num_configs];
    config->name = name;
    config->type = type;
    config->default_value = default_value;
    config->num_params = num_params;
    // Allocate memory for the parameters of the new configuration
    config->params = malloc(sizeof(record_t) * num_params);
    if (!config->params) {
        fprintf(stderr, "Failed to allocate memory for configuration parameters\n");
        exit(1);
    }

    registry->num_configs++;
}

// Function to update a configuration in the given configuration registry with new parameters
void update_config(config_t* registry, char* name, size_t num_params) {
    // Find the index of the configuration to be updated
    int idx = -1;
    for (size_t i = 0; i < registry->num_configs; ++i) {
        if (!strcmp(registry[i].name, name)) {
            idx = i;
            break;
        }
    }
    if (idx == -1) {
        fprintf(stderr, "Failed to find configuration with name '%s'\n", name);
        exit(1);
    }

    // Update the parameters of the configuration
    config_t* config = &registry[idx];
    if (config->params != NULL) {
        free(config->params);
    }
    config->num_params = num_params;
    config->params = malloc(sizeof(record_t) * num_params);
    if (!config->params) {
        fprintf(stderr, "Failed to allocate memory for configuration parameters\n");
        exit(1);
    }
}

// Function to delete a configuration from the given configuration registry
void delete_config(config_t* registry, char* name) {
    // Find the index of the configuration to be deleted
    int idx = -1;
    for (size_t i = 0; i < registry->num_configs; ++i) {
        if (!strcmp(registry[i].name, name)) {
            idx = i;
            break;
        }
    }
    if (idx == -1) {
        fprintf(stderr, "Failed to find configuration with name '%s'\n", name);
        exit(1);
    }

    // Shift all configurations after the one to be deleted towards the beginning of the array
    for (size_t i = idx; i < registry->num_configs - 1; ++i) {
        memcpy(&registry[i], &registry[i + 1], sizeof(config_t));
    }
    registry->num_configs--;
}

// Function to retrieve a configuration from the given configuration registry by name
void* get_config(config_t* registry, char* name) {
    // Find the index of the requested configuration
    int idx = -1;
    for (size_t i = 0; i < registry->num_configs; ++i) {
        if (!strcmp(registry[i].name, name)) {
            idx = i;
            break;
        }
    }
    if (idx == -1) {
        fprintf(stderr, "Failed to find configuration with name '%s'\n", name);
        exit(1);
    }

    // Return a pointer to the requested configuration
    return &registry[idx];
}

// Function to retrieve the total count of configurations in the given configuration registry
size_t get_num_configs(config_t* registry) {
    return registry->num_configs;
}

// Function to allocate memory for an array of 'long' offset values with the given size
long* alloc_offset_array(size_t size) {
    long* arr = malloc(sizeof(long) * size);
    if (!arr) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        exit(1);
    }

    return arr;
}

// Function to allocate memory for an array of 'int' keys with the given size
int* alloc_key_array(size_t size) {
    int* arr = malloc(sizeof(int) * size);
    if (!arr) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        exit(1);
    }

    return arr;
}

// Function to allocate memory for an array of 'record' structures with the given size
record_t* alloc_record_array(size_t size) {
    record_t* arr = malloc(sizeof(record_t) * size);
