// Define the structure to store user profiles
typedef struct UserProfile {
    char* name;
    char* email;
    char* hashed_password;
    int num_preferences;
    char** preferences;
} UserProfile;

// Define the function to create a new user profile
UserProfile* create_user_profile(char* name, char* email, char* password, int num_preferences) {
    // Allocate memory for the user profile
    UserProfile* profile = (UserProfile*) malloc(sizeof(UserProfile));
    if (!profile) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    // Copy the name, email and password to the user profile structure
    profile->name = strdup(name);
    profile->email = strdup(email);
    profile->hashed_password = strdup(password);

    // Allocate memory for the preferences array
    int size = num_preferences * sizeof(char*);
    char** preferences = (char**) malloc(size);
    if (!preferences) {
        fprintf(stderr, "Error: Out of memory\n");
        free(profile->name);
        free(profile->email);
        free(profile->hashed_password);
        free(profile);
        return NULL;
    }

    // Initialize the preferences array with null pointers
    for (int i = 0; i < num_preferences; ++i) {
        preferences[i] = NULL;
    }

    // Set the number of preferences and the preferences array
    profile->num_preferences = num_preferences;
    profile->preferences = preferences;

    return profile;
}

// Define the function to add a preference to a user profile
int add_preference(UserProfile* profile, char* preference) {
    // Check if the preference is already in the array
    for (int i = 0; i < profile->num_preferences; ++i) {
        if (!strcmp(profile->preferences[i], preference)) {
            return -1;
        }
    }

    // If not, add it to the end of the array
    profile->preferences[profile->num_preferences] = strdup(preference);
    ++profile->num_preferences;

    return 0;
}

// Define the function to remove a preference from a user profile
int remove_preference(UserProfile* profile, char* preference) {
    // Check if the preference is in the array
    for (int i = 0; i < profile->num_preferences; ++i) {
        if (!strcmp(profile->preferences[i], preference)) {
            // If so, remove it from the array
            free(profile->preferences[i]);
            --profile->num_preferences;

            for (int j = i; j < profile->num_preferences; ++j) {
                profile->preferences[j] = profile->preferences[j + 1];
            }

            return 0;
        }
    }

    // If not, return an error code
    return -1;
}

// Define the function to validate a user profile
int validate_user_profile(UserProfile* profile) {
    // Check if the email is valid
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_flags = AI_NUMERICHOST | AI_NUMERICSERV;

    struct addrinfo* result;
    int error = getaddrinfo(profile->email, NULL, &hints, &result);
    if (error != 0) {
        fprintf(stderr, "Error: Invalid email address\n");
        return -1;
    }

    freeaddrinfo(result);

    // Check if the password is valid
    if (!profile->hashed_password) {
        fprintf(stderr, "Error: Password not set\n");
        return -2;
    }

    return 0;
}

// Define the function to update a user profile
int update_user_profile(UserProfile* profile) {
    // Validate the user profile before updating it
    int error = validate_user_profile(profile);
    if (error != 0) {
        fprintf(stderr, "Error: Invalid user profile\n");
        return -1;
    }

    // Update the user profile in the registry
    // ...

    return 0;
}

// Define the function to delete a user profile
int delete_user_profile(UserProfile* profile) {
    // Validate the user profile before deleting it
    int error = validate_user_profile(profile);
    if (error != 0) {
        fprintf(stderr, "Error: Invalid user profile\n");
        return -1;
    }

    // Delete the user profile from the registry
    // ...

    return 0;
}

