// C code for a dynamic collection of records with integer keys, unique identifier strings, and long offset values
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

#define ID_LEN 10 // length of the unique identifier string
#define INT_MIN -2147483648 // minimum integer value
#define INT_MAX 2147483647 // maximum integer value
#define OFFSET_MIN -9223372036854775808L // minimum long offset value
#define OFFSET_MAX 9223372036854775807L // maximum long offset value
#define DEFAULT_RECORD_COUNT 1000 // default number of records to initialize
#define RECORD_COUNT_VAR "RECORD_COUNT" // environment variable for record count

// structure to store each record with integer key, unique identifier string, and long offset value
typedef struct {
    int key;
    char id[ID_LEN];
    long offset;
} Record;

// function to generate a random alphanumeric string of specified length
char* generateRandomId(int len) {
    // check if length is valid
    if (len < 1 || len > ID_LEN) {
        return NULL;
    }

    char* id = malloc(len + 1);
    for (int i = 0; i < len; i++) {
        id[i] = 'A' + ((rand() % 26) - 1); // random uppercase letter between A and Z
    }
    id[len] = '\0';

    return id;
}

// function to initialize a dynamic collection of records with specified record count and constraints on integer keys and offset values
void initRecords(int recordCount, int keyMin, int keyMax, long offsetMin, long offsetMax) {
    // check if record count is valid
    if (recordCount < 1 || recordCount > DEFAULT_RECORD_COUNT) {
        fprintf(stderr, "Invalid number of records: %d\n", recordCount);
        return;
    }

    // check if key constraints are valid
    if (keyMin > keyMax || keyMin < INT_MIN || keyMax > INT_MAX) {
        fprintf(stderr, "Invalid integer key range: [%d, %d]\n", keyMin, keyMax);
        return;
    }

    // check if offset constraints are valid
    if (offsetMin > offsetMax || offsetMin < OFFSET_MIN || offsetMax > OFFSET_MAX) {
        fprintf(stderr, "Invalid offset value range: [%ld, %ld]\n", offsetMin, offsetMax);
        return;
    }

    // allocate memory for records and initialize with random values
    Record* records = malloc(recordCount * sizeof(Record));
    for (int i = 0; i < recordCount; i++) {
        records[i].key = rand() % (keyMax - keyMin + 1) + keyMin; // generate random integer key within range
        records[i].id = generateRandomId(ID_LEN); // generate random unique identifier string
        records[i].offset = rand() % (offsetMax - offsetMin + 1) + offsetMin; // generate random long offset value within range
    }

    // log initialization and memory usage
    printf("Initialized %d records with key constraints [%d, %d] and offset constraints [%ld, %ld].\n", recordCount, keyMin, keyMax, offsetMin, offsetMax);
    printf("Used %lu bytes of memory.\n", (unsigned long)recordCount * sizeof(Record));
}

// main function for testing the initRecords function
int main() {
    // test with default record count and constraints
    initRecords(DEFAULT_RECORD_COUNT, INT_MIN, INT_MAX, OFFSET_MIN, OFFSET_MAX);

    // test with custom record count and constraints
    int recordCount = atoi(getenv(RECORD_COUNT_VAR));
    if (recordCount > 0) {
        initRecords(recordCount, INT_MIN, INT_MAX, OFFSET_MIN, OFFSET_MAX);
    } else {
        fprintf(stderr, "Invalid record count: %d\n", recordCount);
    }

    return 0;
}']

