#include <pthread.h>

// Define the sensor reading struct
typedef struct {
    long timestamp; // in milliseconds
    float temperature;
    int status;
} sensor_reading_t;

// Define the collection of sensor readings
static sensor_reading_t *sensor_readings = NULL;

// Define a mutex lock to ensure thread-safe access to the data structure
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to insert a new sensor reading into the collection
void insert_sensor_reading(long timestamp, float temperature, int status) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the collection has been initialized
    if (sensor_readings == NULL) {
        // Initialize the collection with a default capacity of 100 readings
        sensor_readings = malloc(sizeof(sensor_reading_t) * 100);
    }

    // Check if the collection is full and needs to be resized
    if (sensor_readings->size == sensor_readings->capacity) {
        // Double the capacity of the collection
        sensor_readings = realloc(sensor_readings, sizeof(sensor_reading_t) * 2 * sensor_readings->capacity);
    }

    // Insert the new sensor reading into the collection
    sensor_readings[sensor_readings->size++] = (sensor_reading_t){.timestamp = timestamp, .temperature = temperature, .status = status};

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define a function to traverse the collection of sensor readings
void traverse_sensor_readings() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Print each sensor reading in the collection
    for (int i = 0; i < sensor_readings->size; i++) {
        printf("Sensor %d: timestamp=%ld, temperature=%.2f, status=%d\n", i + 1, sensor_readings[i].timestamp, sensor_readings[i].temperature, sensor_readings[i].status);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define a function to print details of each sensor reading while maintaining efficient memory usage and performance
void print_sensor_readings(int index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the collection has been initialized
    if (sensor_readings == NULL || sensor_readings->size <= index) {
        printf("Sensor reading not found\n");
        return;
    }

    // Print the details of the requested sensor reading
    printf("Sensor %d: timestamp=%ld, temperature=%.2f, status=%d\n", index + 1, sensor_readings[index].timestamp, sensor_readings[index].temperature, sensor_readings[index].status);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
```
