#include "logging.h" // External logging library

typedef struct {
    int value;
    char* id;
} record;

void init_data(int num_records, long seed) {
    srand(seed);
    size_t key_size = sizeof(int) * num_records;
    size_t offset_size = sizeof(long) * num_records;
    size_t record_size = sizeof(record) * num_records;

    // Allocate memory for the arrays
    int* keys = malloc(key_size);
    long* offsets = malloc(offset_size);
    record* records = malloc(record_size);

    if (!keys || !offsets || !records) {
        log_error("Failed to allocate memory for the data structures");
        return;
    }

    // Initialize the arrays with random values
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100;
        offsets[i] = i * sizeof(record);
        records[i].value = rand() % 10000;
    }

    // Initialize the strings with random alphanumeric characters
    for (int i = 0; i < num_records; i++) {
        char* id = malloc(20);
        if (!id) {
            log_error("Failed to allocate memory for string %d", i);
            continue;
        }
        for (int j = 0; j < 20; j++) {
            int c = rand() % ('Z' - 'A') + 'A';
            id[j] = (c >= 'a' && c <= 'z') ? 'a' : c;
        }
        records[i].id = id;
    }
}

void free_data(int num_records) {
    // Free the memory allocated for the arrays
    free(keys);
    free(offsets);
    free(records);
}
```
