    int key;
    long offset;
    float weight;
} Record;

// Array of records to store instances
Record* records[1024 * 1024]; // Maximum number of records is 1024 * 1024
int num_records = 0; // Number of active records

// Mutex for synchronizing access to the record array
pthread_mutex_t mutex;

// Synchronized function to add a new record with a customizable key and scaling factors
void addRecord(int key, long offset_scale, float weight_scale) {
    pthread_mutex_lock(&mutex);
    // Ensure there is enough space for the new record
    if (num_records >= 1024 * 1024) {
        fprintf(stderr, "Error: Maximum number of records exceeded\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Generate a random integer value for the key
    int rand_key = (int)((float)rand() / RAND_MAX * offset_scale + offset_scale / 2);

    // Calculate the offset and weight based on the customizable key and scaling factors
    long offset = (long)(((float)rand_key / offset_scale) * offset_scale);
    float weight = ((float)rand_key / offset_scale) * weight_scale;

    // Create a new record with the generated values
    records[num_records] = malloc(sizeof(Record));
    records[num_records]->key = rand_key;
    records[num_records]->offset = offset;
    records[num_records]->weight = weight;

    // Increment the number of active records
    num_records++;

    pthread_mutex_unlock(&mutex);
}

// Synchronized function to retrieve a record by key
Record* getRecord(int key) {
    pthread_mutex_lock(&mutex);
    // Search for the record with the given key
    for (int i = 0; i < num_records; i++) {
        if (records[i]->key == key) {
            Record* record = records[i];
            pthread_mutex_unlock(&mutex);
            return record;
        }
    }

    // Return NULL if the record is not found
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Synchronized function to deallocate all allocated memory
void deallocateRecords() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    num_records = 0;
    pthread_mutex_unlock(&mutex);
}

// Logging function to monitor memory usage and performance metrics
void logMemoryUsage() {
    // TODO: Implement logging mechanism here
}
