        return -1;
    }

    // Parse the port parameter and validate its range
    char* port = json_object_get_string(json, "port");
    if (!isdigit(*port)) {
        fprintf(stderr, "Port is not an integer\n");
        return -1;
    }

    val = strtol(port, &endptr, 10);
    if (*endptr != '\0' || val < 1 || val > 65535) {
