        return -1;
    }

    // Parse the protocol parameter and validate its value
    char* protocol = json_object_get_string(json, "protocol");
    if (!isalpha(*protocol) || strcasecmp("http", protocol) != 0 && strcasecmp("https", protocol) != 0 && strcasecmp("grpc", protocol) != 0) {
        fprintf(stderr, "Protocol is not valid (must be 'http', 'https', or 'grpc')\n");
        return -1;
    }

    // Parse the timeout parameter and validate its value if present
    char* timeout = json_object_get_string(json, "timeout");
    if (timeout != NULL && (!isdigit(*timeout) || *endptr != '\0' || val < 1)) {
        fprintf(stderr, "Timeout is not a positive integer\n");
        return -1;
    }

    // Initialize the offset array with the number of elements found in the JSON string
    offset_val = json_object_length(json);
    *offset = offset_val;

    // Allocate memory for the key and values arrays based on the length of the JSON string
    *key = malloc(sizeof(int) * offset_val);
    *values = malloc(sizeof(record_t) * offset_val);

    // Initialize the key array with the indices of the elements found in the JSON string
    for (int i = 0; i < offset_val; ++i) {
        (*key)[i] = i;
    }

    // Initialize the values array with random integers within the specified range
    srand(time(NULL));
    for (int i = 0; i < offset_val; ++i) {
        (*values)[i].value = rand() % 10 + 1;
    }

    return 0;
}

int generate_random_string(char* buffer, size_t length, const char* charset) {
    // Generate a random string of the specified length using the given character set
    for (size_t i = 0; i < length; ++i) {
        int index = rand() % strlen(charset);
        buffer[i] = charset[index];
    }

    return 0;
}

void init_logging(const char* log_file, const char* logging_level) {
    // Initialize a custom logging mechanism using the specified file and level
    FILE* fp = fopen(log_file, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

