#define MAX_MEMORY 1024 * 1024 * 10 // 10 MB
#define MAX_RECORDS 1000

typedef struct {
    long offset;
    char identifier[30];
    int value;
} record;

record* allocate_records(int n_offsets) {
    // Check if n_offsets is within the allowed range
    if (n_offsets < 1 || n_offsets > MAX_RECORDS) {
        fprintf(stderr, "Error: Invalid number of offsets provided\n");
        return NULL;
    }

    // Calculate the size of the record array
    int record_size = sizeof(record) * n_offsets;

    // Check if the total memory allocation would exceed MAX_MEMORY
    if (record_size > MAX_MEMORY) {
        fprintf(stderr, "Error: Total memory allocation exceeds maximum allowed\n");
        return NULL;
    }

    // Allocate memory for the record array
    record* records = malloc(record_size);
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record structure with a default value of 0
    for (int i = 0; i < n_offsets; ++i) {
        records[i].offset = 0;
        records[i].value = 0;
        strcpy(records[i].identifier, "");
    }

    // Return the pointer to the first element of the record array
    return records;
}
