        free(processors);
        free(entries);
        return NULL;
    }

    // Initialize each processor to process a subset of the data_entries based on their status codes
    for (int i = 0; i < num_processors; i++) {
        // Set the number of entries processed by this processor to zero
        num_entries[i] = 0;

        // Set the start and end indices for this processor's subset of data_entries
        processors[i].start_index = i * size / num_processors;
        processors[i].end_index = (i + 1) * size / num_processors;
