// Structure to hold record data
struct record {
    int value;
    long offset;
    float weight;
};

// Global variables for managing records and threads
static struct record* records = NULL;
static size_t num_records = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for records
void allocate_records(size_t num) {
    assert(num > 0);
    records = malloc(sizeof(struct record) * num);
    if (records == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    num_records = num;
}

// Function to release memory for records
void free_records() {
    if (records != NULL) {
        free(records);
        records = NULL;
        num_records = 0;
    }
}

// Function to add a new record with customizable key and scaling factors
int add_record(int value, long offset, float weight) {
    pthread_mutex_lock(&lock);
    if (num_records >= 10 * 1024 * 1024) { // Resize records if more than 10 million records exist
        allocate_records(num_records * 2);
    }
    int index = num_records++;
    records[index].value = value;
    records[index].offset = offset;
    records[index].weight = weight;
    pthread_mutex_unlock(&lock);
    return index;
}

// Function to retrieve a record by its index
struct record* get_record(int index) {
    if (index < 0 || index >= num_records) {
        return NULL;
    }
    return &records[index];
}

// Function to update the value, offset, and weight of a record by its index
void update_record(int index, int value, long offset, float weight) {
    if (index < 0 || index >= num_records) {
        return;
    }
    pthread_mutex_lock(&lock);
    records[index].value = value;
    records[index].offset = offset;
    records[index].weight = weight;
    pthread_mutex_unlock(&lock);
}

// Function to delete a record by its index
void delete_record(int index) {
    if (index < 0 || index >= num_records) {
        return;
    }
    pthread_mutex_lock(&lock);
    records[index] = records[--num_records];
    pthread_mutex_unlock(&lock);
}
