                throw new ArgumentException($"File size is too large: {fileSize}. Maximum file size is {MAX_FILE_SIZE} bytes.", "filePath");

            // extract metadata
            var metadata = pdfReader.GetInfo();
            var author = metadata.Author;
            var title = metadata.Title;
            var subject = metadata.Subject;
            var keywords = metadata.Keywords;

            // parse PDF content
            var textExtractor = new iTextSharp.text.pdf.PdfTextExtractor(pdfReader);
            var pageCount = pdfReader.NumberOfPages;
            var pages = new List<string>(pageCount);

            for (var i = 1; i <= pageCount; i++)
            {
                var page = textExtractor.GetPageText(i);
                if (!String.IsNullOrEmpty(page))
                    pages.Add(page);
            }

            // extract embedded fonts, images, and links
            var fontInfo = pdfReader.GetFontInfo();
            var imageInfo = pdfReader.GetImageInfo();
            var linkInfo = pdfReader.GetLinkInfo();

            var fonts = new List<string>(fontInfo.Count);
            foreach (var font in fontInfo)
                fonts.Add(font.FontName);

            var images = new List<string>(imageInfo.Count);
            foreach (var image in imageInfo)
                images.Add(image.ImageName);

            var links = new List<string>(linkInfo.Count);
            foreach (var link in linkInfo)
                links.Add($"{link.LinkUrl} - {link.ActionType}");

            // convert scanned PDF pages to text using OCR service
            var ocrService = new OCRService();
            var ocrResponse = await ocrService.ConvertAsync(filePath, maxPages);
            if (ocrResponse.Status != HttpStatusCode.OK)
                throw new Exception($"OCR service error: {ocrResponse.Status} - {ocrResponse.ReasonPhrase}");

            var ocrText = ocrResponse.Content;

            // compute SHA-256 hash of PDF document
            using (var sha = new SHA256Managed())
            {
                var fileBytes = File.ReadAllBytes(filePath);
                var hash = sha.ComputeHash(fileBytes);
                return $"{hash} - {fileSize} bytes";
            }
        }
        catch (Exception ex)
        {
            // handle error gracefully and return meaningful error message
            Console.WriteLine($"Error processing PDF file: {ex.Message}");
            return "PDF processing failed.";
        }
    }
}
```
