import java.util.*;
import java.util.concurrent.*;

public class InventoryManagementSystem {
    private static final int PRODUCT_COUNT = 1000;
    private static final int MIN_STOCK_LEVEL = 10;
    private static final int MAX_STOCK_LEVEL = 500;
    private static final double DISCOUNT_RATE = 0.10;
    private static final int RESTOCK_THRESHOLD = 20;
    private static final int ORDER_ID_MAX_LENGTH = 16;

    private final Map<String, Product> products = new ConcurrentHashMap<>();
    private final Set<Order> orders = new CopyOnWriteArraySet<>();
    private final BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();

    public InventoryManagementSystem() {
        initializeProducts();
    }

    public void placeOrder(String orderId, String productId, int quantity) {
        queue.offer(() -> {
            Product product = products.get(productId);
            if (product == null || product.getStockLevel() < quantity) {
                System.out.println("Product out of stock or invalid order");
                return;
            }

            int totalPrice = (int) Math.round(quantity * product.getPrice() * (1 - DISCOUNT_RATE));
            Order order = new Order(orderId, product, quantity, totalPrice);
            orders.add(order);

            product.setStockLevel(product.getStockLevel() - quantity);
            product.setLastUpdatedTimestamp(new Date());
        });
    }

    public void cancelOrder(String orderId) {
        queue.offer(() -> {
            Optional<Order> order = orders.stream().filter(o -> o.getId().equals(orderId)).findAny();
            if (order.isPresent()) {
                Order cancelledOrder = order.get();
                Product product = products.get(cancelledOrder.getProduct().getId());
                product.setStockLevel(product.getStockLevel() + cancelledOrder.getQuantity());
                product.setLastUpdatedTimestamp(new Date());
                orders.remove(order);
            } else {
                System.out.println("Invalid order");
            }
        });
    }

    public void queryProductStockLevel(String productId) {
        queue.offer(() -> {
            Product product = products.get(productId);
            if (product != null) {
                System.out.println("Product stock level: " + product.getStockLevel());
            } else {
                System.out.println("Invalid product ID");
            }
        });
    }

    public void queryOrderStatus(String orderId) {
        queue.offer(() -> {
            Optional<Order> order = orders.stream().filter(o -> o.getId().equals(orderId)).findAny();
            if (order.isPresent()) {
                System.out.println("Order status: " + order.get().getStatus());
            } else {
                System.out.println("Invalid order ID");
            }
        });
    }

    private void initializeProducts() {
        for (int i = 0; i < PRODUCT_COUNT; i++) {
            Product product = new Product(UUID.randomUUID().toString(), UUID.randomUUID().toString(),
                    ThreadLocalRandom.current().nextInt(MIN_STOCK_LEVEL, MAX_STOCK_LEVEL + 1),
                    ThreadLocalRandom.current().nextDouble(50, 100));
            products.put(product.getId(), product);
        }
    }

    private class Order {
        private String id;
        private Product product;
        private int quantity;
        private int totalPrice;
        private OrderStatus status;

        public Order(String id, Product product, int quantity, int totalPrice) {
            this.id = id;
            this.product = product;
            this.quantity = quantity;
            this.totalPrice = totalPrice;
            this.status = OrderStatus.PLACED;
        }

        public String getId() { return id; }
        public Product getProduct() { return product; }
        public int getQuantity() { return quantity; }
        public int getTotalPrice() { return totalPrice; }
        public OrderStatus getStatus() { return status; }
    }

    private enum OrderStatus { PLACED, CANCELLED, COMPLETED }
}
