#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

const int MAX_ATTACKS = 10 * 1000 * 1000; // maximum number of attacks
const double COOLDOWN_SECONDS = 9.0; // cooldown period in seconds
const string ATTACK_CSV_PATH = "attacks.csv"; // path to CSV file with attack names

struct Attack {
    string name;
    double strength;
};

class AttackSystem {
private:
    vector<Attack> attacks; // dynamic collection of attacks
    unordered_map<string, int> attackMap; // map of attack names to indices in the attacks vector
    mutex mu; // mutex for protecting concurrent access to the attacks vector
    condition_variable cv; // condition variable for notifying threads of changes to the attacks vector
    size_t maxNameLength = 0; // maximum length of attack names (used for dynamic allocation)
    double minStrength = -1.0, maxStrength = -1.0; // minimum and maximum strength values (used for dynamic allocation)
public:
    AttackSystem() {
        loadAttacks(); // load attacks from CSV file
    }

    void manageDynamicAttackSystem(function<void(vector<int>&)> callback) {
        while (true) {
            vector<int> updatedAttacks;
            {
                lock_guard<mutex> lk(mu);
                auto it = attackMap.begin();
                advance(it, rand() % attackMap.size());
                auto attackIdx = it->second;
                Attack &attack = attacks[attackIdx];
                // check cooldown period and select one of two predefined attacks
                double cooldown = chrono::duration_cast<chrono::seconds>(chrono::system_clock::now() - attack.cooldownStart).count();
                if (cooldown < COOLDOWN_SECONDS) continue;
                int selectedAttackIdx = (attackIdx + 1) % attacks.size(); // select next attack from the same category
                if (cooldown > 2 * COOLDOWN_SECONDS && attacks[selectedAttackIdx].category == attack.category) {
                    selectedAttackIdx = (attackIdx + 2) % attacks.size(); // select next attack from the same category
                }
                Attack &selectedAttack = attacks[selectedAttackIdx];
                updatedAttacks.push_back(selectedAttackIdx);
                attack.cooldownStart = chrono::system_clock::now();
            }
            cv.notify_all(); // notify all threads of the updated attacks vector
            callback(updatedAttacks); // callback function to process the updated attacks
        }
    }

    void insertAttack(const string& name, double strength) {
        lock_guard<mutex> lk(mu);
        if (attackMap.find(name) != attackMap.end()) return; // attack already exists
        attackMap[name] = attacks.size(); // add new attack to the map
        attacks.push_back({ name, strength }); // add new attack to the vector
    }

    void deleteAttack(const string& name) {
        lock_guard<mutex> lk(mu);
        auto it = attackMap.find(name);
        if (it == attackMap.end()) return; // attack does not exist
        swap(attacks[it->second], attacks.back()); // swap with the last element
        attacks.pop_back(); // delete the last element
        attackMap.erase(it); // delete the element from the map
    }

    void retrieveAttack(const string& name, Attack& out) {
        lock_guard<mutex> lk(mu);
        auto it = attackMap.find(name);
        if (it == attackMap.end()) return; // attack does not exist
        out = attacks[it->second];
    }

    void serialize() {
        ofstream ofs(ATTACK_CSV_PATH, ios::binary);
        for (const auto& attack : attacks) {
            ofs << attack.name << "," << attack.strength << endl;
        }
        ofs.close();
    }

    void deserialize() {
        ifstream ifs(ATTACK_CSV_PATH, ios::binary);
        string line;
        while (getline(ifs, line)) {
            auto tokens = split(line, ',');
            insertAttack(tokens[0], stod(tokens[1]));
        }
        ifs.close();
    }
};
