// Define log levels
const int LOG_LEVEL_DEBUG = 0;
const int LOG_LEVEL_ERROR = 1;

// Define log entry structure
struct LogEntry {
    std::string timestamp;
    std::string message;
    int priority;
};

// Define log storage class
class LogStorage {
public:
    // Add a new log entry to the storage
    void addLogEntry(const LogEntry& entry) {
        // Check if maximum number of entries has been reached
        if (entries.size() >= maxEntries) {
            // Remove oldest entry
            entries.pop_front();
        }
        // Add new entry to the end of the storage
        entries.push_back(entry);
    }

    // Delete a log entry based on its timestamp and message content
    void deleteLogEntry(const std::string& timestamp, const std::string& message) {
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            if (it->timestamp == timestamp && it->message == message) {
                // Remove the entry from the storage
                entries.erase(it);
                break;
            }
        }
    }

    // Retrieve a log entry based on its timestamp and message content
    LogEntry retrieveLogEntry(const std::string& timestamp, const std::string& message) {
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            if (it->timestamp == timestamp && it->message == message) {
                return *it;
            }
        }
        // Return an empty entry if no match was found
        return LogEntry{};
    }

    // Update the maximum number of log entries allowed
    void setMaxEntries(int max) {
        maxEntries = max;
    }

    // Get the total memory usage in bytes for all log entries
    int getTotalMemoryUsage() {
        return totalMemoryUsage;
    }

private:
    std::deque<LogEntry> entries;
    int maxEntries = 10000000;
    int totalMemoryUsage = 0;
};

// Define custom comparator for sorting log entries by timestamp
struct TimestampComparator {
    bool operator()(const LogEntry& a, const LogEntry& b) {
        return a.timestamp < b.timestamp;
    }
};

// Define a smart pointer for managing memory effectively
using LogStoragePtr = std::shared_ptr<LogStorage>;

// Define custom allocator for managing memory efficiently
class CustomAllocator : public std::allocator<void> {
public:
    // Override allocate and deallocate methods to handle allocation and deallocation of log entries
    void* allocate(std::size_t n) {
        totalMemoryUsage += n;
        return std::malloc(n);
    }

    void deallocate(void* p, std::size_t n) {
        totalMemoryUsage -= n;
        std::free(p);
    }
};

// Define a log manager class that manages the logging system
class LogManager {
public:
    // Constructor that initializes the log storage and custom allocator
    LogManager() : storage(std::make_shared<LogStorage>()), allocator(CustomAllocator()) {}

    // Add a new log entry to the storage
    void addLogEntry(const LogEntry& entry) {
        // Allocate memory for the log entry using the custom allocator
        LogEntry* newEntry = allocator.allocate(sizeof(LogEntry));
        // Copy the log entry data into the allocated memory
        std::memcpy(newEntry, &entry, sizeof(LogEntry));
        // Add the log entry to the storage
        storage->addLogEntry(*newEntry);
    }

    // Delete a log entry based on its timestamp and message content
    void deleteLogEntry(const std::string& timestamp, const std::string& message) {
        storage->deleteLogEntry(timestamp, message);
    }

    // Retrieve a log entry based on its timestamp and message content
    LogEntry retrieveLogEntry(const std::string& timestamp, const std::string& message) {
        return storage->retrieveLogEntry(timestamp, message);
    }

    // Update the maximum number of log entries allowed
    void setMaxEntries(int max) {
        storage->setMaxEntries(max);
    }

    // Get the total memory usage in bytes for all log entries
    int getTotalMemoryUsage() {
        return storage->getTotalMemoryUsage();
    }

private:
    LogStoragePtr storage;
    CustomAllocator allocator;
};

// Define a random logger that selects one of two predefined log levels randomly
class RandomLogger {
public:
    // Constructor that initializes the probability of selecting the DEBUG level
    RandomLogger() : debugProbability(0.3) {}

    // Log a message with either the DEBUG or ERROR level based on the configured probability
    void log(const std::string& message) {
        if (std::uniform_real_distribution<double>(0, 1)(gen) <= debugProbability) {
            LOG_LEVEL_DEBUG;
        } else {
            LOG_LEVEL_ERROR;
        }
    }

private:
    std::random_device rd;
    std::mt19937 gen(rd());
    double debugProbability;
};

// Define a log query class that allows external clients to query the collection based on a substring match within the log messages
class LogQuery {
public:
    // Constructor that initializes the log manager and the custom comparator for sorting log entries by timestamp
    LogQuery(LogManager& manager) : manager(manager), comparator(TimestampComparator()) {}

    // Query the collection based on a substring match within the log messages
    void query(const std::string& message) {
        // Sort the log entries by their timestamps using the custom comparator
        std::vector<LogEntry> sortedEntries = manager.retrieveAllLogEntries();
        std::sort(sortedEntries.begin(), sortedEntries.end(), comparator);

        // Search for log entries that contain the specified substring in their messages
        for (auto it = sortedEntries.begin(); it != sortedEntries.end(); ++it) {
            if (it->message.find(message) != std::string::npos) {
                // Print the matching log entry
                std::cout << "Log Entry: " << *it << std::endl;
            }
        }
    }

private:
    LogManager& manager;
    TimestampComparator comparator;
};

// Define a log persistence class that periodically persists the log data to disk
class LogPersistence {
public:
    // Constructor that initializes the log manager and the file stream for writing to disk
    LogPersistence(LogManager& manager) : manager(manager), fileStream("logs.txt") {}

    // Periodically persist the log data to disk every 10 minutes
    void persist() {
        // Retrieve all log entries from the storage
        std::vector<LogEntry> logEntries = manager.retrieveAllLogEntries();
        // Write each log entry to the file stream
        for (auto& entry : logEntries) {
            fileStream << entry.timestamp << " - " << entry.message << std::endl;
        }
    }

private:
    LogManager& manager;
    std::ofstream fileStream;
};

// Define a concurrent logger class that allows multiple threads to log and query the collection simultaneously without conflicts
class ConcurrentLogger {
public:
    // Constructor that initializes the log manager and the custom allocator for managing memory efficiently
    ConcurrentLogger(LogManager& manager) : manager(manager), allocator(CustomAllocator()) {}

    // Log a message with either the DEBUG or ERROR level based on the configured probability, using a thread-safe smart pointer to manage memory effectively
    void log(const std::string& message) {
        LogEntry* newEntry = allocator.allocate(sizeof(LogEntry));
        std::memcpy(newEntry, &message, sizeof(LogEntry));
        manager.addLogEntry(*newEntry);
    }

    // Query the collection based on a substring match within the log messages, using a thread-safe smart pointer to manage memory effectively
    void query(const std::string& message) {
        manager.retrieveAllLogEntries();
    }

private:
    LogManager& manager;
    CustomAllocator allocator;
};
