static size_t g_mem_budget = 0; // Maximum allowed memory budget (in bytes)

// Function to allocate memory for an array of long integers
void* alloc_long_array(size_t num_elements, size_t max_element_size) {
    assert(num_elements > 0 && max_element_size > 0);

    // Calculate the total size required for the array
    size_t total_size = num_elements * max_element_size;

    // Check if the total size exceeds the memory budget
    assert(total_size <= g_mem_budget);

    // Allocate memory from the custom memory pool allocator
    void* mem_block = g_mem_pool->alloc(g_mem_pool, total_size);

    // Return a pointer to the allocated memory block
    return mem_block;
}

// Function to free memory for an array of long integers
