2. Function: Manage Memory for an Array of Integers with Hash-Based Collision Resolution
------------------------------------------------------------------------------------

```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Custom hash table struct
struct hash_table {
    void* base; // Base address of the allocated memory block
    size_t size; // Size of the allocated memory block (in bytes)
};

// Global variables
static struct hash_table* g_hash_table = NULL;
static const int MAX_NUM_KEYS = 1000; // Maximum number of unique keys allowed
static const int MAX_NUM_DUPLICATES = 5; // Maximum number of duplicates allowed for a key

// Function to insert an integer key into the hash table
int insert_key(int key) {
    assert(key > 0 && key <= MAX_NUM_KEYS);

    // Calculate the hash value for the given key
    int hash = key % g_hash_table->size;

    // Check if there are any collisions in the hash table
    while (g_hash_table[hash].key != NULL && g_hash_table[hash].key != key) {
        // Increment the hash value and try again
        hash = (hash + 1) % g_hash_table->size;
    }

    // Check if the maximum number of duplicates has been reached for this key
    int num_duplicates = g_hash_table[hash].num_duplicates;
    if (num_duplicates >= MAX_NUM_DUPLICATES) {
        return -1;
    }

    // Insert the new key and increment the number of duplicates for this key
    g_hash_table[hash].key = key;
    g_hash_table[hash].num_duplicates++;

    // Return success
    return 0;
}

// Function to retrieve an integer value from the hash table
int get_value(int key) {
    assert(key > 0 && key <= MAX_NUM_KEYS);

    // Calculate the hash value for the given key
    int hash = key % g_hash_table->size;

    // Check if there are any collisions in the hash table
    while (g_hash_table[hash].key != NULL && g_hash_table[hash].key != key) {
        // Increment the hash value and try again
        hash = (hash + 1) % g_hash_table->size;
    }

    // Return the value associated with the given key
    return g_hash_table[hash].value;
}
