// Function to populate an array of record structures with random values
void populate_records(size_t num_records) {
    assert(num_records > 0 && num_records <= MAX_NUM_RECORDS);

    // Allocate memory for the record array
    g_records = malloc(num_records * RECORD_SIZE);

    // Initialize the record values to random integers between 0 and 1000
    for (size_t i = 0; i < num_records; i++) {
        g_records[i].value = rand() % 1000;
    }
}

// Function to track the frequency of each record value in the array
void track_frequency(size_t num_records) {
    assert(num_records > 0 && num_records <= MAX_NUM_RECORDS);

    // Allocate memory for the frequency array
    size_t* frequencies = malloc(MAX_NUM_RECORDS * sizeof(size_t));

    // Initialize the frequency array to zeroes
    memset(frequencies, 0, MAX_NUM_RECORDS * sizeof(size_t));

    // Count the frequency of each record value in the array
