using namespace std;

// CombatAction structure to represent combat actions
struct CombatAction {
    string name;
    float power;
};

// Reservation record type to store seat number, event ID, and ticket availability status
using ReservationRecord = tuple<long, int, int>;

// Map to store reservation records by event ID
map<int, vector<ReservationRecord>> reservations;

// Mutex for thread safety
mutex reservationsMutex;

// Condition variable to signal changes in reservations
condition_variable reservationsCondVar;

// Vector to store combat actions
vector<CombatAction> combatActions;

// Map to store combat actions by name
map<string, CombatAction> combatActionsByName;

// Mutex for thread safety
mutex combatActionsMutex;

