condition_variable combatActionsCondVar;

// JSON serializer and deserializer
nlohmann::json jsonSerializer;

// Event ID increment
int eventIDIncrement = 0;

// Ticket availability status
bool ticketAvailabilityStatus = true;

// Query ranges for reservations
int queryLowerBound = 0;
int queryUpperBound = 0;

// Memory usage tracker
size_t memoryUsage = 0;

// Function to handle event ticket reservations and combat actions
void handleEventAndCombatSystem(const string& actionName, const string& actionPower) {
    // Lock reservations mutex
    lock_guard<mutex> reservationLock(reservationsMutex);

    // Check if the event ID increment has changed
    if (eventIDIncrement != 0) {
        // Update the event ID increment in all reservations
        for (auto& record : reservations) {
            record.second[1] += eventIDIncrement;
        }

        // Reset the event ID increment to zero
        eventIDIncrement = 0;
    }

    // Check if the ticket availability status has changed
    if (!ticketAvailabilityStatus) {
        // Update the ticket availability status in all reservations
        for (auto& record : reservations) {
            record.second[2] = 0;
        }

        // Reset the ticket availability status to true
        ticketAvailabilityStatus = true;
    }

    // Check if there are any queries pending
    if (queryLowerBound != 0 || queryUpperBound != 0) {
        // Lock combat actions mutex
        lock_guard<mutex> combatActionsLock(combatActionsMutex);

        // Check if the query range is within the bounds of the reservation records
        for (auto& record : reservations) {
            if (record.second[0] >= queryLowerBound && record.second[0] <= queryUpperBound) {
                // Serialize the combat actions and append them to the JSON string
                auto jsonString = jsonSerializer.dump(combatActions);
                cout << "Query result: " << jsonString << endl;

                // Reset the query bounds to zero
                queryLowerBound = 0;
                queryUpperBound = 0;
            }
        }
    }

    // Check if there are any combat actions pending
    if (!combatActions.empty()) {
        // Lock combat actions mutex
        lock_guard<mutex> combatActionsLock(combatActionsMutex);

        // Insert the new combat action into the map
        combatActionsByName[actionName] = CombatAction{ actionName, stof(actionPower) };

        // Serialize the combat actions and append them to the JSON string
        auto jsonString = jsonSerializer.dump(combatActions);
        cout << "Combat action added: " << jsonString << endl;
    }
}

// Function to update the reservation records
void updateReservations(const vector<ReservationRecord>& newRecords) {
    // Lock reservations mutex
    lock_guard<mutex> reservationLock(reservationsMutex);

    // Update the reservation records
    for (auto& record : newRecords) {
        // Check if the event ID exists in the map
        auto it = reservations.find(record[1]);
        if (it != reservations.end()) {
            // Update the seat number and ticket availability status
            it->second[0] = record[0];
            it->second[2] = record[2];
        } else {
            // Add a new reservation record to the map
            reservations.insert(make_pair(record[1], vector<ReservationRecord>{ record[0], record[1], record[2] }));
        }
    }
}

// Function to update the combat actions
void updateCombatActions(const vector<CombatAction>& newActions) {
    // Lock combat actions mutex
    lock_guard<mutex> combatActionsLock(combatActionsMutex);

    // Update the combat actions
    for (auto& action : newActions) {
        // Check if the action name exists in the map
        auto it = combatActionsByName.find(action.name);
        if (it != combatActionsByName.end()) {
            // Update the action power
            it->second.power = action.power;
        } else {
            // Add a new combat action to the map
            combatActionsByName[action.name] = action;
        }
    }
}

