void parse_args(int argc, char** argv) {
  // Check if the correct number of arguments was provided
  if (argc != 3) {
    printf("Usage: %s <min> <max>\n", argv[0]);
    exit(1);
  }

  // Parse min and max values from command-line arguments
  int min = atoi(argv[1]);
  int max = atoi(argv[2]);

  // Initialize random number generator with the seed
  srand(time(NULL));

  // Allocate memory for offset, key, and record arrays
  long* offsets = (long*) malloc(sizeof(long) * min);
  int* keys = (int*) malloc(sizeof(int) * max);
  Record* records = (Record*) malloc(sizeof(Record) * max);

  // Initialize offset values to random numbers within the specified range
  for (int i = 0; i < min; i++) {
    offsets[i] = rand() % (max - min + 1) + min;
  }

  // Initialize key and record values to random integers within the specified range
  for (int i = 0; i < max; i++) {
    keys[i] = rand() % (max - min + 1) + min;
    records[i].value = rand() % (max - min + 1) + min;
  }
}

// Free memory allocated for arrays
void free_arrays(long* offsets, int* keys, Record* records) {
  free(offsets);
  free(keys);
  free(records);
}

int main(int argc, char** argv) {
