```c++
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <fstream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace std;

// Resource structure
struct Resource {
    string name;
    float capacity;
};

// Collection of resources
class ResourceCollection {
public:
    // Constructor
    ResourceCollection() {
        totalCapacity = 0;
        numResources = 0;
    }

    // Insert a new resource into the collection
    void insert(const string& name, float capacity) {
        unique_lock<mutex> lock(mutex);
        resources[name] = capacity;
        totalCapacity += capacity;
        numResources++;
    }

    // Delete a resource from the collection
    void delete(const string& name) {
        unique_lock<mutex> lock(mutex);
        auto it = resources.find(name);
        if (it != resources.end()) {
            totalCapacity -= it->second;
            numResources--;
            resources.erase(it);
        }
    }

    // Retrieve a resource from the collection
    float get(const string& name) {
        unique_lock<mutex> lock(mutex);
        auto it = resources.find(name);
        if (it != resources.end()) {
            return it->second;
        } else {
            return 0;
        }
    }

    // Update the capacity of a resource in the collection
    void updateCapacity(const string& name, float newCapacity) {
        unique_lock<mutex> lock(mutex);
        auto it = resources.find(name);
        if (it != resources.end()) {
            totalCapacity -= it->second;
            it->second = newCapacity;
            totalCapacity += it->second;
        }
    }

    // Query the collection based on substring matches within resource names
    vector<Resource> query(const string& substr, bool exact) {
        unique_lock<mutex> lock(mutex);
        vector<Resource> results;
        for (auto it = resources.begin(); it != resources.end(); ++it) {
            if (!exact && it->first.find(substr) != string::npos || exact && it->first == substr) {
                results.push_back({it->first, it->second});
            }
        }
        return results;
    }

    // Persist the collection to disk periodically
    void persist() {
        ofstream outfile("resources.json");
        unique_lock<mutex> lock(mutex);
        for (auto it = resources.begin(); it != resources.end(); ++it) {
            outfile << "{\"name\": \"" << it->first << "\", \"capacity\": " << it->second << "}" << endl;
        }
        outfile.close();
    }

private:
    // Map of resource names to capacities
    map<string, float> resources;

    // Total capacity of all resources
    float totalCapacity;

    // Number of resources in the collection
    int numResources;

    // Mutex for concurrent access to the collection
    mutex mutex;
};

// DNS resolution function using standard library functions
u_char* resolve(const char* hostname, bool& error) {
    // Resolve hostname to IP address
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;

    struct addrinfo* result;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        error = true;
        return nullptr;
    }

    // Create a socket and connect to the remote address
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        error = true;
        return nullptr;
    }

    struct addrinfo* ptr = result;
    while (connect(sockfd, ptr->ai_addr, ptr->ai_addrlen) == -1) {
        if (!ptr->ai_next) {
            break;
        }
        ptr = ptr->ai_next;
    }

    freeaddrinfo(result);
    return (u_char*)&sockfd;
}

// Read a large text file line by line, dynamically allocating memory for each line
void readFileLineByLine(const char* filename, vector<string>& lines) {
    ifstream infile(filename);
    string line;
    while (getline(infile, line)) {
        lines.push_back(line);
    }
}

// Compute the average of the last two numeric fields in each line
float computeAverage(const vector<string>& lines) {
    float sum = 0;
    int count = 0;
    for (int i = lines.size() - 1; i >= 0 && count < 2; i--) {
        string line = lines[i];
        size_t pos = line.find_last_of("0123456789");
        if (pos != string::npos) {
            sum += stof(line.substr(pos));
            count++;
        }
    }
    return sum / count;
}

// Implement a system to manage a dynamic collection of resources
void manageResources() {
    // Initialize the resource collection
    ResourceCollection resources;

    // Periodically persist the collection to disk
    thread persistThread([&] {
        while (true) {
            this_thread::sleep_for(chrono::seconds(30));
            resources.persist();
        }
    });

    // Simulate a maintenance window for a server's resource pool
    thread maintenanceThread([&] {
        while (true) {
            this_thread::sleep_for(chrono::hours(24));
            bool trigger = resources.getTotalCapacity() > 0.8 * resources.getMaximumCapacity();
            if (trigger) {
                for (auto it = resources.begin(); it != resources.end(); ++it) {
                    float capacity = it->second;
                    it->second *= 0.95;
                    resources.updateCapacity(it->first, it->second);
                }
            }
        }
    });
}
```

This code implements the given programming task using C++11 and standard library functions. It includes a `ResourceCollection` class to manage a dynamic collection of resources, which can be queried based on substring matches within resource names. The program also includes a maintenance window simulator that triggers a maintenance event if the total capacity of all resources exceeds 80% of their maximum capacity.

The `resolve()` function is used to perform DNS resolution and create a socket for connecting to the remote address. The `readFileLineByLine()` function reads a large text file line by line, dynamically allocating memory for each line using `vector<string>`. The `computeAverage()` function computes the average of the last two numeric fields in each line.

