// Profile Service

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_PROFILES 1000000 // maximum number of profiles to be stored in memory
#define PROFILE_SIZE sizeof(struct Profile)
#define MAX_USER_ID_LENGTH 20 // maximum length of a user ID string

// structure for storing profile information
struct Profile {
    char *user_id; // unique user ID string
    char *name; // name string
    time_t last_login_time; // last login timestamp
};

// hash map for caching frequently accessed profiles
struct HashMap {
    struct Profile *profiles[MAX_PROFILES];
    int num_profiles;
    int capacity;
};

// function to dynamically allocate memory and initialize profiles with default values
void init_profile(struct Profile **profile) {
    *profile = (struct Profile *) malloc(sizeof(struct Profile));
    (*profile)->user_id = NULL;
    (*profile)->name = NULL;
    (*profile)->last_login_time = 0;
}

// function to update the last login time of a profile
void update_last_login_time(struct Profile *profile) {
    profile->last_login_time = time(NULL);
}

// function to add a new profile
bool add_profile(char *user_id, char *name) {
    struct Profile *profile;
    init_profile(&profile);
    profile->user_id = user_id;
    profile->name = name;
    update_last_login_time(profile);

    // add the new profile to the hash map for caching
    if (hashmap.num_profiles < MAX_PROFILES) {
        hashmap.profiles[hashmap.num_profiles++] = profile;
        return true;
    } else {
        return false;
    }
}

// function to remove a profile by user ID
bool remove_profile(char *user_id) {
    int i;
    for (i = 0; i < hashmap.num_profiles; i++) {
        if (strcmp(hashmap.profiles[i]->user_id, user_id) == 0) {
            free(hashmap.profiles[i]);
            hashmap.profiles[i] = NULL;
            hashmap.num_profiles--;
            return true;
        }
    }
    return false;
}

// function to search for a profile by user ID
struct Profile *search_profile(char *user_id) {
    int i;
    for (i = 0; i < hashmap.num_profiles; i++) {
        if (strcmp(hashmap.profiles[i]->user_id, user_id) == 0) {
            update_last_login_time(hashmap.profiles[i]);
            return hashmap.profiles[i];
        }
    }
    return NULL;
}

// function to persist profiles to disk
void persist_profiles() {
    FILE *fp = fopen("profile_data", "w");
    int i;
    for (i = 0; i < hashmap.num_profiles; i++) {
        struct Profile *profile = hashmap.profiles[i];
        fprintf(fp, "%s\t%s\t%ld\n", profile->user_id, profile->name, profile->last_login_time);
    }
    fclose(fp);
}

// function to deserialize profiles from disk
void deserialize_profiles() {
    FILE *fp = fopen("profile_data", "r");
    char line[MAX_USER_ID_LENGTH + 1];
    while (fgets(line, MAX_USER_ID_LENGTH + 1, fp) != NULL) {
        char *user_id = strtok(line, "\t");
        char *name = strtok(NULL, "\t");
        time_t last_login_time = atol(strtok(NULL, "\n"));
        struct Profile profile;
        profile.user_id = user_id;
        profile.name = name;
        profile.last_login_time = last_login_time;
        add_profile(&profile);
    }
    fclose(fp);
}

// function to update the parameters of the profile service
void update_parameters() {
    // read the new parameters from a configuration file
    FILE *fp = fopen("config.txt", "r");
    char line[MAX_USER_ID_LENGTH + 1];
    while (fgets(line, MAX_USER_ID_LENGTH + 1, fp) != NULL) {
        if (strcmp(line, "max_profiles\n") == 0) {
            // update the maximum number of profiles to be stored in memory
            hashmap.capacity = atoi(fgets(line, MAX_USER_ID_LENGTH + 1, fp));
        } else if (strcmp(line, "profile_size\n") == 0) {
            // update the size of a profile structure
            PROFILE_SIZE = atoi(fgets(line, MAX_USER_ID_LENGTH + 1, fp));
        }
    }
    fclose(fp);
}

// main function for the profile service
