#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure to store temperature records
typedef struct {
    double temperature;
    time_t timestamp;
} TempRecord;

// Define the maximum number of records that can be stored in the cache
#define MAX_RECORDS 1000

// Define the memory limit for the cache
#define MEMORY_LIMIT (10 * 1024 * 1024) // 10 MB

// Define a linked list to store temperature records
typedef struct {
    TempRecord* head;
    TempRecord* tail;
} TempRecordList;

// Function to initialize the cache
void initCache() {
    // Allocate memory for the linked list
    cache = (TempRecordList*)malloc(sizeof(TempRecordList));
    if (!cache) {
        printf("Error: failed to allocate memory for the cache\n");
        exit(1);
    }
    cache->head = NULL;
    cache->tail = NULL;
}

// Function to add a new temperature record to the cache
void addRecord(double temperature, time_t timestamp) {
    // Create a new record and append it to the end of the linked list
    TempRecord* newRecord = (TempRecord*)malloc(sizeof(TempRecord));
    if (!newRecord) {
        printf("Error: failed to allocate memory for the new record\n");
        exit(1);
    }
    newRecord->temperature = temperature;
    newRecord->timestamp = timestamp;
    if (cache->tail == NULL) {
        cache->head = newRecord;
        cache->tail = newRecord;
    } else {
        cache->tail->next = newRecord;
        cache->tail = newRecord;
    }
    // Update the statistics
    ++numRecords;
    totalMemory += sizeof(TempRecord);
}

// Function to remove the oldest record from the cache
void removeOldestRecord() {
    // Remove the head of the linked list and update the statistics
    TempRecord* oldRecord = cache->head;
    if (oldRecord == NULL) {
        return;
    }
    --numRecords;
    totalMemory -= sizeof(TempRecord);
    cache->head = oldRecord->next;
    if (cache->head == NULL) {
        cache->tail = NULL;
    }
    free(oldRecord);
}

// Function to retrieve the current number of records in the cache
int getNumRecords() {
    return numRecords;
}

// Function to retrieve the total memory usage of the cache
long getTotalMemory() {
    return totalMemory;
}

// Function to retrieve the average temperature of the records in the cache
double getAverageTemperature() {
    if (numRecords == 0) {
        return NAN;
    }
    double sum = 0.0;
    TempRecord* record = cache->head;
    while (record != NULL) {
        sum += record->temperature;
        record = record->next;
    }
    return sum / numRecords;
}

// Main function to demonstrate the usage of the cache
int main() {
    initCache();
    for (int i = 0; i < MAX_RECORDS; ++i) {
        addRecord(rand() % 100, time(NULL));
    }
    printf("Number of records: %d\n", getNumRecords());
    printf("Total memory usage: %ld bytes\n", getTotalMemory());
    printf("Average temperature: %f\n", getAverageTemperature());
    for (int i = 0; i < MAX_RECORDS - 10; ++i) {
        removeOldestRecord();
    }
    printf("Number of records after removing the oldest 10 records: %d\n", getNumRecords());
    printf("Total memory usage after removing the oldest 10 records: %ld bytes\n", getTotalMemory());
    printf("Average temperature after removing the oldest 10 records: %f\n", getAverageTemperature());
    return 0;
}
