#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <sys/time.h>
#include <pthread.h>

typedef struct log_entry {
    time_t timestamp;
    enum severity level;
    char message[256];
} log_entry;

typedef struct metadata {
    time_t timestamp;
    int status;
    log_entry* entry;
    int version;
} metadata;

typedef struct log_manager {
    size_t num_entries;
    size_t total_memory;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    log_entry* entries;
    metadata* metadata;
} log_manager;

void log_entry_init(log_entry* entry) {
    entry->timestamp = time(NULL);
    entry->level = rand() % 5;
    sprintf(entry->message, "Message: %d", rand() % 1000);
}

void metadata_init(metadata* metadata, log_entry* entry) {
    metadata->timestamp = time(NULL);
    metadata->status = rand() % 5;
    metadata->entry = entry;
    metadata->version = rand();
}

log_manager* log_manager_create() {
    log_manager* manager = malloc(sizeof(log_manager));
    manager->num_entries = 0;
    manager->total_memory = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->entries = malloc(1024 * sizeof(log_entry));
    manager->metadata = malloc(1024 * sizeof(metadata));
    return manager;
}

void log_manager_destroy(log_manager* manager) {
    free(manager->entries);
    free(manager->metadata);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

void log_manager_add(log_manager* manager, log_entry* entry) {
    // Acquire lock
    pthread_mutex_lock(&manager->lock);

    // Check for overflow
    if (manager->num_entries >= 1024) {
        printf("Log manager overflow\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Initialize log entry and metadata structures
    log_entry* new_entry = malloc(sizeof(log_entry));
    log_entry_init(new_entry);
    manager->entries[manager->num_entries] = *new_entry;
    metadata* new_metadata = malloc(sizeof(metadata));
    metadata_init(new_metadata, new_entry);
    manager->metadata[manager->num_entries] = *new_metadata;

    // Update total memory usage
    manager->total_memory += sizeof(log_entry) + sizeof(metadata);

    // Increment number of entries
    manager->num_entries++;

    // Release lock and signal condition variable
    pthread_mutex_unlock(&manager->lock);
    pthread_cond_signal(&manager->cond);
}

void log_manager_remove(log_manager* manager, size_t index) {
    // Acquire lock
    pthread_mutex_lock(&manager->lock);

    // Check for underflow
    if (index >= manager->num_entries || manager->num_entries == 0) {
        printf("Log manager underflow\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Free memory for log entry and metadata structures
    free(manager->entries[index]);
    free(manager->metadata[index]);

    // Update total memory usage
    manager->total_memory -= sizeof(log_entry) + sizeof(metadata);

    // Shift elements to maintain ordering
    for (size_t i = index; i < manager->num_entries - 1; i++) {
        manager->entries[i] = manager->entries[i + 1];
        manager->metadata[i] = manager->metadata[i + 1];
    }

    // Decrement number of entries
    manager->num_entries--;

    // Release lock and signal condition variable
    pthread_mutex_unlock(&manager->lock);
    pthread_cond_signal(&manager->cond);
}

void log_manager_print(log_manager* manager) {
    // Acquire lock
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_entries; i++) {
        printf("Log Entry %d: Timestamp: %lu, Severity Level: %d, Message: %s\n", i,
               manager->entries[i].timestamp, manager->entries[i].level, manager->entries[i].message);
    }

    for (size_t i = 0; i < manager->num_entries; i++) {
        printf("Metadata %d: Timestamp: %lu, Status: %d, Entry Reference: %p\n", i,
               manager->metadata[i].timestamp, manager->metadata[i].status, manager->metadata[i].entry);
    }

    // Release lock
    pthread_mutex_unlock(&manager->lock);
}

void* log_manager_consumer(void* args) {
    log_manager* manager = (log_manager*)args;

    while (1) {
        // Acquire lock
        pthread_mutex_lock(&manager->lock);

        if (manager->num_entries > 0) {
            size_t index = rand() % manager->num_entries;
            log_entry* entry = manager->entries[index];
            printf("Log Entry Consumed: Timestamp: %lu, Severity Level: %d, Message: %s\n", entry->timestamp,
                   entry->level, entry->message);
            metadata* metadata = manager->metadata[index].entry;
            printf("Metadata Consumed: Timestamp: %lu, Status: %d, Entry Reference: %p\n", metadata->timestamp,
                   metadata->status, metadata->entry);
        } else {
            // Wait for signal
            pthread_cond_wait(&manager->cond, &manager->lock);
        }

        // Release lock
        pthread_mutex_unlock(&manager->lock);
    }
}
