// Define the structure for a record
typedef struct {
    long offset;
    int key;
    char status;
} Record;

// Function to manage memory for multiple records
Record* allocateRecords(int numRecords, int maxOffset, int maxKey) {
    // Check if the input parameters are valid
    if (numRecords <= 0 || maxOffset <= 0 || maxKey <= 0) {
        return NULL;
    }

    // Initialize an array to store the records
    Record* records = malloc(sizeof(Record) * numRecords);
    if (!records) {
        return NULL;
    }

    // Set the offset, key, and status for each record
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];

        // Generate a random offset within the specified range
        record->offset = rand() % maxOffset + 1;

        // Set the key to a unique value based on its index in the array
        record->key = i + 1;

        // Initialize the status based on the sum of the current index and offset
        int sum = record->key + record->offset;
        if (sum % 2 == 0) {
            record->status = 'A';
        } else {
            record->status = 'B';
        }

        // Handle cases where the sum exceeds a certain threshold, setting status to 'C'
        if (sum > maxOffset) {
            record->status = 'C';
        }
    }

    return records;
}
