// Initializes a new cache with specified capacity
struct cache *cache_init(int capacity) {
    struct cache *cache = malloc(sizeof(struct cache));
    cache->records = malloc(capacity * sizeof(struct record *));
    for (int i = 0; i < capacity; i++) {
        cache->records[i] = NULL;
    }
    cache->capacity = capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Frees the memory allocated to the cache
void cache_free(struct cache *cache) {
    for (int i = 0; i < cache->capacity; i++) {
        free(cache->records[i]);
    }
    free(cache->records);
    pthread_mutex_destroy(&cache->lock);
}

// Inserts a new record into the cache, evicting the least recently used record if necessary
void cache_insert(struct cache *cache, struct record *record) {
    pthread_mutex_lock(&cache->lock);
    // Evict the least recently used record if the cache is full
    if (cache->size == cache->capacity) {
        for (int i = 0; i < cache->capacity; i++) {
            if (cache->records[i] == NULL || cache->records[i]->timestamp < record->timestamp) {
                free(cache->records[i]);
                cache->records[i] = record;
                pthread_mutex_unlock(&cache->lock);
                return;
            }
        }
    }
    // Add the new record to the end of the array if there is space
    else {
        cache->records[cache->size++] = record;
    }
    pthread_mutex_unlock(&cache->lock);
}

