#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <pthread.h>
#include <unistd.h>

// Define the data structure for storing temperature readings
typedef struct {
    double temperature;
    time_t timestamp;
} TemperatureReading;

// Define the data structure for storing the temperature log
typedef struct {
    int capacity; // Maximum number of temperature readings to store
    int num_readings; // Current number of temperature readings stored
    int mem_usage; // Memory usage in bytes
    TemperatureReading* readings; // Array of temperature readings
    pthread_mutex_t mutex; // Mutex for thread-safe access to the log
} TemperatureLog;

// Define the data structure for storing statistics about the temperature log
typedef struct {
    int num_records; // Current number of records in the log
    int mem_usage; // Memory usage in bytes
    double average_temperature; // Average temperature of all records
} TemperatureLogStats;

// Function to initialize a new temperature log with the specified capacity
void init_log(TemperatureLog* log, int capacity) {
    log->capacity = capacity;
    log->num_readings = 0;
    log->mem_usage = 0;
    log->readings = (TemperatureReading*)malloc(sizeof(TemperatureReading) * capacity);
    if (log->readings == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for temperature log\n");
        exit(1);
    }
}

// Function to add a new temperature reading to the log
void add_reading(TemperatureLog* log, double temperature, time_t timestamp) {
    pthread_mutex_lock(&log->mutex);
    if (log->num_readings < log->capacity) {
        TemperatureReading* new_reading = &log->readings[log->num_readings];
        new_reading->temperature = temperature;
        new_reading->timestamp = timestamp;
        log->num_readings++;
        log->mem_usage += sizeof(TemperatureReading);
    } else {
        // Handle cache overflow by removing the oldest record
        TemperatureReading* old_reading = &log->readings[0];
        free(old_reading);
        for (int i = 1; i < log->num_readings; i++) {
            TemperatureReading* reading = &log->readings[i];
            memcpy(old_reading, reading, sizeof(TemperatureReading));
            old_reading++;
        }
        log->num_readings--;
    }
    pthread_mutex_unlock(&log->mutex);
}

// Function to remove the oldest record from the log
void remove_oldest(TemperatureLog* log) {
    pthread_mutex_lock(&log->mutex);
    TemperatureReading* old_reading = &log->readings[0];
    free(old_reading);
    for (int i = 1; i < log->num_readings; i++) {
        TemperatureReading* reading = &log->readings[i];
        memcpy(old_reading, reading, sizeof(TemperatureReading));
        old_reading++;
    }
    log->num_readings--;
    pthread_mutex_unlock(&log->mutex);
}

// Function to retrieve the total memory usage of the temperature log in bytes
int get_mem_usage(TemperatureLog* log) {
    int mem_usage = 0;
    pthread_mutex_lock(&log->mutex);
    for (int i = 0; i < log->num_readings; i++) {
        TemperatureReading* reading = &log->readings[i];
        mem_usage += sizeof(TemperatureReading);
    }
    pthread_mutex_unlock(&log->mutex);
    return mem_usage;
}

// Function to retrieve the average temperature of all records in the log
double get_average_temperature(TemperatureLog* log) {
    double sum = 0.0;
    pthread_mutex_lock(&log->mutex);
    for (int i = 0; i < log->num_readings; i++) {
        TemperatureReading* reading = &log->readings[i];
        sum += reading->temperature;
    }
    pthread_mutex_unlock(&log->mutex);
    return sum / (double)log->num_readings;
}

// Function to retrieve the number of records in the log
int get_num_records(TemperatureLog* log) {
    int num_records = 0;
    pthread_mutex_lock(&log->mutex);
    num_records = log->num_readings;
    pthread_mutex_unlock(&log->mutex);
    return num_records;
}

// Function to clear the temperature log by removing all records
void clear_log(TemperatureLog* log) {
    pthread_mutex_lock(&log->mutex);
    for (int i = 0; i < log->num_readings; i++) {
        TemperatureReading* reading = &log->readings[i];
        free(reading);
    }
    log->num_readings = 0;
    pthread_mutex_unlock(&log->mutex);
}

// Function to retrieve statistics about the temperature log
void get_stats(TemperatureLog* log, TemperatureLogStats* stats) {
    stats->num_records = get_num_records(log);
    stats->mem_usage = get_mem_usage(log);
    stats->average_temperature = get_average_temperature(log);
}
```
