// Function to update the sensor readings array, handling race conditions and synchronization between threads
void update_sensor_readings(const char *config_file) {
    // Open the configuration file for reading
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Read each line and extract the sensor ID, timestamp, and reading value
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip lines that do not contain a sensor ID
        if (strchr(line, '=') == NULL) {
            continue;
        }

        // Parse the line to extract the sensor ID, timestamp, and reading value
