            }
            delim++;
        }

        // Update the sensor reading in the array of structures
        if (sensor_id > 0 && timestamp > 0 && reading_value > 0.0f) {
            pthread_mutex_lock(&sensor_readings[sensor_id - 1]->mutex);
            if (timestamp > sensor_readings[sensor_id - 1]->timestamp ||
                (timestamp == sensor_readings[sensor_id - 1]->timestamp && reading_value > sensor_readings[sensor_id - 1]->reading_value)) {
                sensor_readings[sensor_id - 1]->timestamp = timestamp;
                sensor_readings[sensor_id - 1]->reading_value = reading_value;
            }
            pthread_mutex_unlock(&sensor_readings[sensor_id - 1]->mutex);
        }
    }
    free(line);
    fclose(fp);
}

// Function to clean up the sensor readings array, releasing memory and synchronizing between threads
void cleanup_sensor_readings() {
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (sensor_readings[i] != NULL) {
            pthread_mutex_lock(&sensor_readings[i]->mutex);
            free(sensor_readings[i]);
            sensor_readings[i] = NULL;
            pthread_mutex_unlock(&sensor_readings[i]->mutex);
        }
    }
}

