    // Start a thread to update the sensor readings array in real-time
    pthread_t thread;
    if (pthread_create(&thread, NULL, &update_sensor_readings, argv[1]) != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }

    // Wait for the thread to finish before cleaning up the sensor readings array
    if (pthread_join(thread, NULL) != 0) {
        perror("pthread_join");
        exit(EXIT_FAILURE);
    }

    // Clean up the sensor readings array and free memory
    cleanup_sensor_readings();

    return EXIT_SUCCESS;
}
