    if (temperature < MIN_TEMPERATURE || temperature > MAX_TEMPERATURE) {
        printf("Invalid temperature reading: %f\n", temperature);
        return;
    }

    // Update the temperature offset array
    updateTemperatureOffsetArray(temperature - MIN_TEMPERATURE);

