        pthread_cond_wait(&data_processing_cv, &data_processing_cv);

        // Release the mutex for the data processing condition variable
        pthread_mutex_unlock(&data_processing_cv);

        // Process the temperature readings
        for (i = 0; i < BUFFER_SIZE && temperature_reading_count > 0; i++) {
