    if (list->hash_table[index] == NULL) {
        list->hash_table[index] = new_node;
    } else {
        struct Node* temp = list->hash_table[index];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

