struct Node* find(struct List* list, const char* id) {
    unsigned int index = hash(id) % min_size;
    struct Node* temp = list->hash_table[index];
    while (temp != NULL && strcmp(temp->id, id) != 0) {
        temp = temp->next;
    }
    return temp;
}

// Define a function to update the weight of a node in the linked list
void update_weight(struct List* list, const char* id, double new_weight) {
