void delete(struct List* list, const char* id) {
    struct Node* target = find(list, id);
    if (target != NULL) {
        // Remove the node from the hash table
        unsigned int index = hash(id) % min_size;
        struct Node** temp = &list->hash_table[index];
        while (*temp != NULL && (*temp)->next != target) {
            temp = &(*temp)->next;
