            *temp = target->next;
        }
        // Remove the node from the linked list
        struct Node* prev = target->prev;
        struct Node* next = target->next;
        if (prev != NULL) {
            prev->next = next;
        } else {
            list->head = next;
        }
        if (next != NULL) {
            next->prev = prev;
        } else {
            list->tail = prev;
        }
        free(target);
        list->count--;
    }
}

// Define a function to serialize the data structure to a file in binary format
void serialize_list(struct List* list, FILE* fp) {
    assert(list != NULL && fp != NULL);
    // Write the size of the linked list to the file
    size_t count = 0;
    struct Node* curr = list->head;
    while (curr != NULL) {
        count++;
        curr = curr->next;
    }
    fwrite(&count, sizeof(size_t), 1, fp);
    // Write each node in the linked list to the file
