    while (curr != NULL) {
        fwrite(curr->id, strlen(curr->id), 1, fp);
        fwrite(&curr->timestamp, sizeof(int), 1, fp);
        fwrite(&curr->weight, sizeof(double), 1, fp);
        curr = curr->next;
    }
}

// Define a function to deserialize the data structure from a file in binary format
void deserialize_list(struct List* list, FILE* fp) {
    assert(list != NULL && fp != NULL);
    // Read the size of the linked list from the file
    size_t count;
    fread(&count, sizeof(size_t), 1, fp);
    init_list(list, count);
