// Define a structure to represent a record in the system
typedef struct Record {
    int key;
    double measurement;
} Record;

// Define a linked list node to store records
typedef struct ListNode {
    Record *record;
    struct ListNode *next;
} ListNode;

// Define a function to dynamically manage memory for the system of records
void manageRecords(int numRecords, int keyRangeMin, int keyRangeMax) {
    // Initialize variables for tracking memory usage and linked list nodes
    long totalMemoryUsage = 0;
    ListNode *head = NULL;
    ListNode *tail = NULL;

    // Loop through each record to be managed
    for (int i = 0; i < numRecords; i++) {
        // Generate a random key within the specified range
        int key = rand() % keyRangeMax + keyRangeMin;

        // Calculate the corresponding offset based on the key and fixed increment factor
        long offset = key * 10000000;

        // Allocate memory for a new record using the offset as its unique identifier
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            continue;
        }

        // Initialize the record fields with the generated key and measurement value
        record->key = key;
        record->measurement = rand() / (double)RAND_MAX;

        // Add the record to the linked list
        ListNode *node = malloc(sizeof(ListNode));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for node %d\n", i);
            continue;
        }
        node->record = record;
        node->next = NULL;
        if (head == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;

        // Update the total memory usage and log the new record insertion
        totalMemoryUsage += sizeof(Record);
        printf("Inserted record %d with key %d and measurement %.2f\n", i, key, record->measurement);
    }

    // Loop through each record to be deleted based on their keys
    for (int i = 0; i < numRecords; i++) {
        // Generate a random key within the specified range
        int key = rand() % keyRangeMax + keyRangeMin;

        // Find the corresponding node in the linked list and delete it
        ListNode *node = head;
        while (node != NULL && node->record->key != key) {
            node = node->next;
        }
        if (node == NULL) {
            printf("Error: Failed to find record with key %d for deletion\n", key);
            continue;
        }
        totalMemoryUsage -= sizeof(Record);
        head = node->next;
        free(node);

        // Log the deleted record
        printf("Deleted record with key %d and measurement %.2f\n", key, node->record->measurement);
    }

    // Deallocate memory for all records and nodes in the linked list
    while (head != NULL) {
        ListNode *node = head;
        head = head->next;
        free(node->record);
