// Function to dynamically allocate memory for two arrays: one for doubles and another for unsigned ints
data_point* allocate_memory(size_t num_points) {
    // Calculate the total size of the memory needed for both arrays
    size_t double_mem = num_points * sizeof(double);
    size_t uint_mem = num_points * sizeof(unsigned int);
    size_t total_mem = double_mem + uint_mem;

    // Allocate the memory using malloc() and initialize both arrays to 0
    data_point* arr = (data_point*)malloc(total_mem);
    memset(arr, 0, total_mem);

    // Initialize the double array with random values within a specified range
    for (size_t i = 0; i < num_points; i++) {
        arr[i].value = rand() / (double)RAND_MAX;
    }

    return arr;
}

// Function to deallocate all allocated memory when done
void deallocate_memory(data_point* arr, size_t num_points) {
    // Calculate the total size of the memory needed for both arrays
    size_t double_mem = num_points * sizeof(double);
    size_t uint_mem = num_points * sizeof(unsigned int);
    size_t total_mem = double_mem + uint_mem;

    // Deallocate the memory using free()
    free(arr);
}

// Function to find and print the largest integer in an array of unsigned integers
void find_largest(unsigned int* arr, size_t num_ints) {
    unsigned int largest = 0;
    for (size_t i = 0; i < num_ints; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    printf("The largest integer in the array is: %u\n", largest);
}

