    *offset = malloc(size * sizeof(long));

    // Initialize the offset array with the corresponding keys multiplied by a fixed increment factor
    for (int i = 0; i < size; i++) {
        (*offset)[i] = ((*key)[i]) * INC_FACTOR;
    }

    // Allocate memory for the key array and initialize it with random values within a specified range
    *key = malloc(size * sizeof(int));
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*key)[i] = RANDOM_MIN + rand() % (RANDOM_MAX - RANDOM_MIN);
    }

    // Allocate memory for the record array and initialize each element with a random value within a specified range and decimal precision
    *record = malloc(size * sizeof(Record));
    for (int i = 0; i < size; i++) {
        (*record)[i].key = (*key)[i];
        (*record)[i].decimal = RANDOM_MIN + rand() % (RANDOM_MAX - RANDOM_MIN) / 10.0f;
    }
}

// Function to find and print the largest integer in an array
void findLargest(Record* record, int size) {
    // Initialize variables for tracking largest value and its index
    int largest = INT_MIN;
    int index = -1;

    // Iterate over the array and find the largest value
    for (int i = 0; i < size; i++) {
        if (record[i].key > largest) {
            largest = record[i].key;
            index = i;
        }
    }

    // Print the largest value and its index
    printf("Largest integer: %d\n", largest);
    printf("Index of largest integer: %d\n", index);
}

// Function to calculate the average of decimal precision fields in an array
void calculateAverage(Record* record, int size) {
    // Initialize variables for tracking sum and count of values
    float sum = 0;
    int count = 0;

    // Iterate over the array and calculate the sum and count of values
    for (int i = 0; i < size; i++) {
        sum += record[i].decimal;
        count++;
    }

    // Print the average value
    printf("Average decimal precision: %f\n", sum / count);
}

// Main function to handle inputs, allocate memory, and calculate results
int main() {
    int size = 0;
    Record* offset = NULL;
    int* key = NULL;
    Record** record = NULL;

    // Read the size of the input array from standard input
    scanf("%d", &size);

    // Allocate memory for arrays and initialize them with values
    allocateArrays(&offset, &key, &record, size);

    // Find and print the largest integer in the array
    findLargest(record, size);

    // Calculate the average of decimal precision fields in the array
    calculateAverage(record, size);

    // Free memory allocated for arrays
    free(offset);
    free(key);
    free(record);

    return 0;
}
