// Define memory management functions for reservation arrays
void resizeReservationArray(ReservationArray *array, size_t new_capacity) {
    // Reallocate the reservation array with the specified capacity
    array->reservations = realloc(array->reservations, new_capacity * sizeof(Reservation));
    if (array->reservations == NULL) {
        fprintf(stderr, "Error: failed to resize reservation array\n");
        exit(EXIT_FAILURE);
    }
    // Update the capacity and size of the reservation array
    array->capacity = new_capacity;
    array->size = (array->size > new_capacity) ? new_capacity : array->size;
}

void addReservation(ReservationArray *array, long seat, int key) {
    // Check if the reservation array is full
    if (array->size == array->capacity) {
        // Resize the reservation array by a factor of INCREMENT_FACTOR
        resizeReservationArray(array, array->capacity * INCREMENT_FACTOR);
    }
    // Add the new reservation to the end of the reservation array
    array->reservations[array->size].seat = seat;
    array->reservations[array->size].key = key;
    array->reservations[array->size].ticket = (rand() % AVAILABLE_TICKETS) + 1;
    array->size++;
}

void removeReservation(ReservationArray *array, long seat, int key) {
    // Find the index of the reservation to be removed
    size_t i = 0;
    for (i = 0; i < array->size && (array->reservations[i].seat != seat || array->reservations[i].key != key); i++);
    // Check if the reservation was found
    if (i == array->size) {
        fprintf(stderr, "Error: reservation not found\n");
        return;
    }
    // Shift subsequent reservations to fill the gap
    for (size_t j = i; j < array->size - 1; j++) {
        array->reservations[j] = array->reservations[j + 1];
    }
    // Decrement the size of the reservation array
    array->size--;
}

// Define query functions for reservation arrays
Reservation *queryReservations(ReservationArray *array, long start_seat, long end_seat) {
    // Check if the specified seat range is valid
    if (start_seat > end_seat || start_seat < SEAT_RANGE_MIN || end_seat > SEAT_RANGE_MAX) {
        fprintf(stderr, "Error: invalid seat range\n");
        return NULL;
    }
    // Initialize the query result
    Reservation *result = malloc(sizeof(Reservation));
    if (result == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for reservation query\n");
        exit(EXIT_FAILURE);
    }
    // Iterate over the reservations in the array and add them to the query result
    size_t i = 0;
    for (i = 0; i < array->size && (array->reservations[i].seat <= end_seat || array->reservations[i].key != key); i++) {
        if (array->reservations[i].seat >= start_seat) {
            result = realloc(result, (i + 1) * sizeof(Reservation));
            if (result == NULL) {
                fprintf(stderr, "Error: failed to allocate memory for reservation query\n");
                exit(EXIT_FAILURE);
            }
            result[i] = array->reservations[i];
        }
    }
    // Return the query result
