// Variable to track total memory usage in bytes
size_t total_memory = 0;

// Function to execute a command-line operation in the background without blocking
int execute(char* command) {
    pid_t child_pid = fork();

    if (child_pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, (char*)NULL);
        exit(127);
    } else if (child_pid > 0) { // Parent process
        waitpid(child_pid, NULL, WNOHANG);
    } else {
        printf("Failed to execute command: %s\n", command);
        return -1;
    }
}

// Function to handle SIGCHLD signals and clean up child processes
void sigchld_handler(int signum) {
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

// Function to allocate memory for an array of long integers
long* allocLongArray(size_t size) {
    long* arr = malloc(sizeof(long) * size);
    total_memory += sizeof(long) * size;
    return arr;
}

// Function to free memory allocated by allocLongArray()
void freeLongArray(long* arr, size_t size) {
    free(arr);
    total_memory -= sizeof(long) * size;
}

// Function to allocate memory for an array of integers
int* allocIntArray(size_t size) {
    int* arr = malloc(sizeof(int) * size);
    total_memory += sizeof(int) * size;
    return arr;
}

// Function to free memory allocated by allocIntArray()
void freeIntArray(int* arr, size_t size) {
    free(arr);
    total_memory -= sizeof(int) * size;
}

// Function to allocate memory for an array of characters
char* allocCharArray(size_t size) {
    char* arr = malloc(sizeof(char) * size);
    total_memory += sizeof(char) * size;
    return arr;
}

// Function to free memory allocated by allocCharArray()
void freeCharArray(char* arr, size_t size) {
    free(arr);
    total_memory -= sizeof(char) * size;
}

