}

// Function to handle dynamic changes to the increment factor and ticket availability without reallocating memory
void updateIncrementFactor(int new_factor) {
    INCREMENT_FACTOR = new_factor;
    for (int i = 0; i < MAX_RESERVATIONS; i++) {
        reservations[i].offset *= new_factor;
    }
}

