}

int queryReservations(int start, int end) {
    if (start < 0 || start > MAX_RESERVATIONS || end < 0 || end > MAX_RESERVATIONS || start > end) {
        printf("Invalid query range: %d - %d\n", start, end);
        return -1;
    }

