// Define the data structure for a single data point
typedef struct {
  double value;
  unsigned int identifier;
} data_point;

// Define the power factor for initializing the floating-point values
#define POWER_FACTOR 2.0

// Define the maximum number of data points to be stored in memory
#define MAX_DATA_POINTS 1000000000

// Define the acceptable range of values for the identifiers
#define MIN_IDENTIFIER 0
#define MAX_IDENTIFIER UINT_MAX

// Define the filename for storing and loading the data points
#define FILENAME "data.bin"

// Define the number of bytes to allocate for each data point in memory
#define DATA_POINT_SIZE (sizeof(double) + sizeof(unsigned int))

// Define the number of bytes to read from standard input at a time
#define READ_BUFFER_SIZE 1024

// Function to initialize a dynamic collection of data points
void init_data_points(data_point **data, unsigned int num_points) {
  // Allocate memory for the data points and set the initial capacity
  *data = malloc(num_points * DATA_POINT_SIZE);
  (*data)->size = 0;
}

// Function to insert a new data point into the collection
void insert_data_point(data_point **data, unsigned int identifier) {
  // Check if the number of data points exceeds the maximum capacity
  if ((*data)->size >= MAX_DATA_POINTS) {
    printf("Error: Maximum capacity exceeded.\n");
    return;
  }

  // Calculate the floating-point value for the identifier
  double value = pow(identifier, POWER_FACTOR);

  // Allocate memory for the new data point and assign the values
  data_point *new_data = malloc(DATA_POINT_SIZE);
  new_data->value = value;
  new_data->identifier = identifier;

  // Add the new data point to the end of the collection
  (*data)->data[(*data)->size++] = new_data;
}

// Function to delete a data point from the collection based on its identifier
void delete_data_point(data_point **data, unsigned int identifier) {
  // Find the index of the data point with the specified identifier
  int index = -1;
  for (int i = 0; i < (*data)->size; i++) {
    if ((*data)->data[i]->identifier == identifier) {
      index = i;
      break;
    }
  }

  // Check if the data point was found and remove it from the collection
  if (index != -1) {
    free((*data)->data[index]);
    (*data)->size--;
  } else {
    printf("Error: Data point with identifier %u not found.\n", identifier);
  }
}

// Function to retrieve a data point from the collection based on its identifier
data_point *get_data_point(data_point **data, unsigned int identifier) {
  // Find the index of the data point with the specified identifier
  for (int i = 0; i < (*data)->size; i++) {
    if ((*data)->data[i]->identifier == identifier) {
      return (*data)->data[i];
    }
  }

  // Return NULL if the data point was not found
  return NULL;
}

// Function to read a list of unsigned integers from standard input and store them in an optimized data structure for quick access
void read_input(data_point **data) {
  // Allocate memory for the input buffer
  char *buffer = malloc(READ_BUFFER_SIZE);

  // Read the input from standard input and convert it to integers
  while (fgets(buffer, READ_BUFFER_SIZE, stdin)) {
    // Ignore any leading or trailing whitespace characters
    int start = 0;
    while (isspace(buffer[start])) {
      start++;
    }
    int end = strlen(buffer) - 1;
    while (isspace(buffer[end])) {
      end--;
    }
    buffer[end + 1] = '\0';

    // Convert the input string to an integer and add it to the collection
    unsigned int identifier = atoi(&buffer[start]);
    if (identifier >= MIN_IDENTIFIER && identifier <= MAX_IDENTIFIER) {
      insert_data_point(data, identifier);
    } else {
      printf("Error: Invalid identifier %u.\n", identifier);
    }
  }

  // Free the input buffer memory
  free(buffer);
}

// Function to determine the largest integer in a list of unsigned integers stored in an optimized data structure for quick access
unsigned int get_largest_identifier(data_point **data) {
  // Initialize the largest identifier to zero
  unsigned int largest = 0;

  // Iterate over the data points and find the largest identifier
  for (int i = 0; i < (*data)->size; i++) {
    if ((*data)->data[i]->identifier > largest) {
      largest = (*data)->data[i]->identifier;
    }
  }

  // Return the largest identifier
  return largest;
}

// Function to persist the collection to disk periodically, ensuring data integrity and consistency in the face of potential system crashes
void save_data(data_point **data) {
  // Open a file for writing and truncate it if it already exists
  int fd = open(FILENAME, O_CREAT | O_TRUNC | O_WRONLY, S_IRUSR | S_IWUSR);
  if (fd < 0) {
    printf("Error: Failed to open file for writing.\n");
    return;
  }

  // Write the data points to the file
  for (int i = 0; i < (*data)->size; i++) {
    // Allocate memory for the data point and copy its values
    data_point *new_data = malloc(DATA_POINT_SIZE);
    memcpy(new_data, (*data)->data[i], DATA_POINT_SIZE);

    // Write the data point to the file
    if (write(fd, new_data, DATA_POINT_SIZE) < 0) {
      printf("Error: Failed to write to file.\n");
      return;
    }
  }

  // Close the file and free the memory for the data points
  if (close(fd) < 0) {
    printf("Error: Failed to close file.\n");
    return;
  }
}

// Function to load a resource bundle from a file and return the number of items in the bundle
unsigned int get_resource_bundle(char *filename) {
  // Open the file for reading
  int fd = open(filename, O_RDONLY);
  if (fd < 0) {
    printf("Error: Failed to open file for reading.\n");
    return 0;
  }

  // Read the data points from the file and add them to the collection
  while (1) {
    // Allocate memory for the input buffer
    char *buffer = malloc(DATA_POINT_SIZE);

    // Read a single data point from the file
    if (read(fd, buffer, DATA_POINT_SIZE) < 0) {
      printf("Error: Failed to read from file.\n");
      return 0;
    }

    // Check if the end of the file has been reached
    if (feof(fd)) {
      break;
    }

    // Convert the input buffer to an integer and add it to the collection
    unsigned int identifier = atoi(buffer);
    if (identifier >= MIN_IDENTIFIER && identifier <= MAX_IDENTIFIER) {
      insert_data_point(&data, identifier);
    } else {
      printf("Error: Invalid identifier %u.\n", identifier);
    }
  }

  // Close the file and return the number of items in the collection
  if (close(fd) < 0) {
    printf("Error: Failed to close file.\n");
  }
  return (*data)->size;
}
