// Define constants for memory management
#define RECORD_SIZE 8 // sizeof(long) + sizeof(int) + sizeof(char) + sizeof(int)
#define MAX_RECORDS 10000000
#define MIN_KEY 0
#define MAX_KEY 100
#define INITIAL_OFFSET 0
#define OFFSET_INCREMENT 50

// Define a struct to represent a record
typedef struct {
    long offset;
    int key;
    char label[20];
    int value;
} Record;

// Define a global variable to store the records
Record records[MAX_RECORDS];

// Define a function to allocate memory for the records
void alloc_records(int num_records) {
    // Allocate memory for the records using calloc
    Record *new_records = (Record *)calloc(num_records, RECORD_SIZE);
    if (new_records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Copy the old records to the new allocation and free the old records
    memcpy(new_records, records, num_records * RECORD_SIZE);
    free(records);
    records = new_records;
}

// Define a function to deallocate memory for the records
void dealloc_records() {
    // Deallocate the memory for the records
    free(records);
    records = NULL;
}

// Define a function to generate random records
void gen_random_records(int num_records) {
    // Generate random keys, labels, and values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        strcpy(records[i].label, "");
        records[i].value = rand();
    }
}

// Define a function to print the records
void print_records() {
    // Print each record using printf
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key != -1) {
            printf("%ld %d %s %d\n", records[i].offset, records[i].key, records[i].label, records[i].value);
        }
    }
}

// Define a function to calculate the average memory usage per record
float get_avg_mem_usage() {
    // Calculate the total number of allocations and the total size of the allocated memory
    int num_allocs = 0;
    int mem_size = 0;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key != -1) {
            num_allocs++;
            mem_size += RECORD_SIZE;
        }
    }

    // Calculate the average memory usage per record
    return (float)mem_size / (float)num_allocs;
}

// Define a function to track and log memory usage
void track_mem_usage() {
    // Print the total number of allocations and the average memory usage per record
    printf("Total number of allocations: %d\n", num_allocs);
    printf("Average memory usage per record: %.2f\n", get_avg_mem_usage());
}

// Define a function to cache previously allocated memory
void cache_memory() {
    // Create a cache of previously allocated records
    Record *cache = (Record *)calloc(MAX_RECORDS, RECORD_SIZE);
    if (cache == NULL) {
        printf("Error: Failed to create cache\n");
        exit(1);
    }

    // Copy the old records to the cache and free the old records
    memcpy(cache, records, MAX_RECORDS * RECORD_SIZE);
    free(records);
    records = cache;
}

// Define a function to handle edge cases
void handle_edge_cases() {
    // Handle out-of-memory scenarios by allocating more memory and reallocating the records
    if (num_allocs >= MAX_RECORDS) {
        alloc_records(MAX_RECORDS * 2);
    }

    // Handle invalid configurations by printing an error message and exiting
    if (MIN_KEY >= MAX_KEY || INITIAL_OFFSET < 0 || OFFSET_INCREMENT <= 0) {
        printf("Error: Invalid configuration\n");
        exit(1);
    }
}

// Define a function to deallocate all allocated memory
void dealloc_memory() {
    // Deallocate the memory for the records and the cache
    free(records);
    free(cache);
}

int main() {
    // Initialize variables for managing memory
    int num_allocs = 0;
    Record *cache = NULL;

    // Generate random records and print them to the console
    gen_random_records(MAX_RECORDS);
    print_records();

    // Track and log memory usage
    track_mem_usage();

    // Cache previously allocated memory
    cache_memory();

    // Handle edge cases
    handle_edge_cases();

    // Deallocate all allocated memory
    dealloc_memory();

    return 0;
}
