typedef struct {
    long* offset;
    int* keys;
} array_t;

array_t allocate_and_initialize_arrays(int n, int max_memory_kb) {
    // Allocate memory for the arrays using a custom memory pool
    size_t offset_size = n * sizeof(long);
    size_t keys_size = n * sizeof(int);
    long* offset = (long*) malloc(offset_size);
    int* keys = (int*) malloc(keys_size);

    // Initialize the arrays with unique values and no duplicate values
    for (int i = 0; i < n; i++) {
        offset[i] = i + 1;
        keys[i] = i + 1;
    }

    // Sort the keys array in ascending order and remove any duplicate values
    qsort(keys, n, sizeof(int), compare_ints);
    int last_key = INT_MIN;
    for (int i = 0; i < n; i++) {
        if (keys[i] != last_key) {
            last_key = keys[i];
        } else {
            keys[i] = 0;
        }
    }

    // Check if the total memory allocation exceeds the maximum memory limit
    size_t total_size = offset_size + keys_size;
    if (total_size > max_memory_kb * 1024) {
        free(offset);
        free(keys);
        return NULL;
    }

    // Create a new array structure to hold the pointers to the arrays
    array_t result = {offset, keys};
    return result;
}
