    // Calculate the sum of all offset values
    long sum = 0;
    for (int i = 0; i < array->n; i++) {
        sum += array->offset[i];
    }

    // Return true if the sum is less than or equal to max_sum
    return sum <= max_sum;
}

void adjust_offset(array_t* array, long max_sum) {
    // Calculate the total number of elements in the offset array
    int n = array->n;

    // Calculate the maximum number of offset values that can be adjusted
    int max_adjustable = (int)(max_sum / (n - 1));

    // Adjust each offset value by at most max_adjustable
    for (int i = 0; i < n; i++) {
        if (array->offset[i] > max_adjustable) {
            array->offset[i] = max_adjustable;
        }
    }
}

bool is_keys_compressible(array_t* array) {
    // Calculate the number of elements in the keys array
    int n = array->n;

    // Initialize a hash table to store unique keys
    size_t hash_table_size = n * sizeof(int);
    int* hash_table = (int*) malloc(hash_table_size);
    memset(hash_table, 0, hash_table_size);

    // Iterate over each key and check if it is a prefix of another key
    for (int i = 0; i < n - 1; i++) {
        int key = array->keys[i];
        int next_key = array->keys[i + 1];
        while (next_key > key) {
            if (hash_table[key]) {
                free(hash_table);
                return false;
            } else {
                hash_table[key] = 1;
                next_key = next_key >> 1;
            }
        }
    }

    // Free the hash table and return true if no duplicates were found
    free(hash_table);
    return true;
}
