int initialize_items(size_t num_items, size_t max_item_id, size_t step_size, int data_type) {
    if (num_items > max_item_id || step_size <= 0 || data_type < 0 || data_type >= NUM_DATA_TYPES) {
        return -1;
    }

    // Allocate memory for the arrays
    float* floats = malloc(num_items * sizeof(float));
    unsigned int* ints = malloc(num_items * sizeof(unsigned int));
    struct item* items = malloc(num_items * sizeof(struct item));
    struct config* configs = malloc(num_items * sizeof(struct config));

    // Initialize the arrays
    for (size_t i = 0; i < num_items; ++i) {
        items[i].type = data_type;

        if (data_type == FLOAT) {
            floats[i] = generate_float(step_size);
        } else if (data_type == UINT) {
            ints[i] = generate_uint(step_size);
        }

        configs[i].timestamp = time(NULL);
        configs[i].configuration = "initial configuration";
    }

    return 0;
}

float generate_float(size_t step_size) {
    // Generate a random float between 0 and 1, with the specified step size
    return (float)(rand() % RAND_MAX) / (RAND_MAX / step_size);
}

unsigned int generate_uint(size_t step_size) {
    // Generate a random unsigned integer between 0 and UINT_MAX, with the specified step size
    return (unsigned int)(rand() % UINT_MAX) / (UINT_MAX / step_size);
}

int update_item(struct item* item, const char* configuration) {
    if (!item || !configuration) {
        return -1;
    }

    // Update the configuration string
    free(item->config.configuration);
    size_t len = strlen(configuration);
    item->config.configuration = malloc(len + 1);
    memcpy(item->config.configuration, configuration, len + 1);

    return 0;
}

int retrieve_item(struct item* item) {
    if (!item) {
        return -1;
    }

    // Retrieve the data buffer
    void* data = NULL;
    switch (item->type) {
        case FLOAT:
            data = &floats[item->index];
            break;
        case UINT:
            data = &ints[item->index];
            break;
    }

    if (!data) {
        return -1;
    }

    // Copy the data buffer to the output pointer
    memcpy(item->data, data, item->size);

    return 0;
}

int destroy_items(struct item* items) {
    if (!items) {
        return -1;
    }

    // Free the memory for the arrays
    free(floats);
    free(ints);
    free(items);
    free(configs);

    return 0;
}
