// Dynamic memory management structure for records
typedef struct record {
    long offset;
    int key;
    char buffer[];
} record_t;

// Memory allocation function for records
record_t* alloc_records(int num_records, size_t max_buffer_size) {
    // Allocate memory for the records array
    record_t* records = malloc(num_records * sizeof(record_t));

    // Initialize each record's offset and key values
    for (int i = 0; i < num_records; i++) {
        records[i].offset = 0;
        records[i].key = -1;
    }

    // Allocate memory for the char buffers
    size_t buffer_size = max_buffer_size * sizeof(char);
    for (int i = 0; i < num_records; i++) {
        records[i].buffer = malloc(buffer_size);
    }

    // Return the pointer to the first record
    return records;
}

// Memory deallocation function for records
void free_records(record_t* records, int num_records) {
    // Free each record's char buffer
    for (int i = 0; i < num_records; i++) {
        free(records[i].buffer);
    }

    // Free the records array
    free(records);
}

// Function to add a new record with a given offset and key value
record_t* add_record(record_t** records, int num_records, long offset, int key) {
    // Check if there is enough memory for the new record
    size_t buffer_size = sizeof(char) * (key + 1);
    if (!has_memory(num_records, buffer_size)) {
        return NULL;
    }

    // Create a new record and copy the offset and key values
    record_t* new_record = malloc(sizeof(record_t));
    new_record->offset = offset;
    new_record->key = key;

    // Allocate memory for the char buffer and copy the string representation of the offset
    new_record->buffer = malloc(buffer_size);
    snprintf(new_record->buffer, buffer_size, "%ld", offset);

    // Add the new record to the records array
    if (records == NULL) {
        *records = new_record;
    } else {
        record_t* temp = *records;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_record;
    }

    // Return the pointer to the first record
    return records;
}

// Function to remove a record with a given offset and key value
void remove_record(record_t** records, int num_records, long offset, int key) {
    // Find the record with the matching offset and key values
    record_t* temp = *records;
    while (temp != NULL && !(temp->offset == offset && temp->key == key)) {
        temp = temp->next;
    }

    // Remove the record from the records array
    if (temp != NULL) {
        // If there are no records left, free the entire array
        if (*records == temp) {
            free_records(*records, num_records);
            *records = NULL;
        } else {
            record_t* previous = *records;
            while (previous->next != temp) {
                previous = previous->next;
            }
            previous->next = temp->next;
            free(temp->buffer);
            free(temp);
        }
    }
}

// Function to check if there is enough memory for a new record with the given offset and key value
int has_memory(int num_records, size_t buffer_size) {
    // Calculate the total size of all records
    int total_size = sizeof(record_t) * num_records + buffer_size * num_records;

    // Check if there is enough memory available
    return (total_size < get_memory_budget());
}

// Function to set the memory budget for the function
void set_memory_budget(int budget) {
    global_memory_budget = budget;
}

// Global variable to store the memory budget
int global_memory_budget = 0;
```
This implementation includes a `record_t` structure to represent each record, with fields for the offset and key values. The `alloc_records()` function allocates memory for an array of `record_t` structs, initializes each record's offset and key values, and returns a pointer to the first record in the array. The `free_records()` function frees the memory allocated by `alloc_records()`.

The `add_record()` function adds a new record with the given offset and key value to the records array. It checks if there is enough memory for the new record, and if not, it releases all existing records and attempts to reallocate resources to meet the new requirements. If the memory budget is zero or negative keys are present, the function returns `NULL`.

The `remove_record()` function removes a record with the given offset and key value from the records array. It finds the matching record and removes it from the array. If there are no records left, it frees the entire array.

The `has_memory()` function checks if there is enough memory available for a new record with the given offset and key value. It calculates the total size of all records and compares it to the current memory budget. The `set_memory_budget()` function sets the memory budget for the function.

This implementation handles cases where the memory budget is zero, negative keys are present, or repeated allocation and deallocation cycles occur. It also minimizes fragmentation and optimizes cache usage. Additionally, it ensures thread safety if the function may be called concurrently from multiple threads.']

