#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a struct to represent each record
typedef struct {
    int key;
    long offset;
    char *description;
} Record;

// Define a data store for the records
typedef struct {
    Record *records;
    size_t numRecords;
    size_t capacity;
} DataStore;

DataStore *initializeDataStore(size_t capacity) {
    // Initialize the data store with the specified capacity
    DataStore *store = (DataStore *)malloc(sizeof(DataStore));
    if (!store) {
        fprintf(stderr, "Failed to allocate memory for data store\n");
        return NULL;
    }
    store->records = (Record *)calloc(capacity, sizeof(Record));
    if (!store->records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        free(store);
        return NULL;
    }
    store->numRecords = 0;
    store->capacity = capacity;
    return store;
}

int addRecord(DataStore *store, int key, long offset, char *description) {
    // Check if the data store is full before adding a new record
    if (store->numRecords >= store->capacity) {
        fprintf(stderr, "Failed to add record: data store is full\n");
        return 1;
    }

    // Generate a random value for the key within the specified range
    int minKey = 0;
    int maxKey = 10000;
    while (key >= maxKey || key <= minKey) {
        key = rand() % (maxKey - minKey + 1) + minKey;
    }

    // Initialize the new record with the generated key and other values
    store->records[store->numRecords].key = key;
    store->records[store->numRecords].offset = offset;
    store->records[store->numRecords].description = description;

    // Increment the number of records in the data store
    store->numRecords++;

    return 0;
}

int findRecord(DataStore *store, int key) {
    // Linear search for the record with the specified key
    for (size_t i = 0; i < store->numRecords; i++) {
        if (store->records[i].key == key) {
            return i;
        }
    }
    return -1;
}

int deleteRecord(DataStore *store, int index) {
    // Check if the specified index is valid
    if (index < 0 || index >= store->numRecords) {
        fprintf(stderr, "Invalid record index: %d\n", index);
        return 1;
    }

    // Shift all records after the deleted one back by one position
    for (size_t i = index; i < store->numRecords - 1; i++) {
        store->records[i] = store->records[i + 1];
    }

    // Decrement the number of records in the data store
    store->numRecords--;

    return 0;
}

void freeDataStore(DataStore *store) {
    // Free the memory allocated for the record array and the data store itself
    free(store->records);
    free(store);
}

int main() {
    // Test the functionality of the functions
    DataStore *store = initializeDataStore(10000);
    if (!store) {
        fprintf(stderr, "Failed to initialize data store\n");
        return 1;
    }
    addRecord(store, 50, 1000, "Hello World");
    addRecord(store, 100, 2000, "Goodbye World");
    int index = findRecord(store, 50);
    if (index >= 0) {
        printf("Found record at index %d\n", index);
    } else {
        printf("Failed to find record with key 50\n");
    }
    deleteRecord(store, 1);
    freeDataStore(store);
    return 0;
}']

