#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Thread-safe memory allocation and access methods to ensure robustness under high-concurrency conditions
void* thread_malloc(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&mem_lock);
    ptr = malloc(size);
    pthread_mutex_unlock(&mem_lock);
    return ptr;
}

void thread_free(void* ptr) {
    pthread_mutex_lock(&mem_lock);
    free(ptr);
    pthread_mutex_unlock(&mem_lock);
}

// Enum for status type
typedef enum StatusType {
    ACTIVE,
    INACTIVE,
    ERROR
} StatusType;

// Struct for record
typedef struct Record {
    int value;
    char* string;
    StatusType status;
} Record;

// Function to initialize arrays of longs, integers, and records
Record** init_arrays(int num_records, int max_string_length) {
    // Allocate memory for the arrays
    long** offset_array = (long**)thread_malloc(sizeof(long*) * num_records);
    int** key_array = (int**)thread_malloc(sizeof(int*) * num_records);
    Record** record_array = (Record**)thread_malloc(sizeof(Record*) * num_records);

    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = (long*)thread_malloc(sizeof(long));
        key_array[i] = (int*)thread_malloc(sizeof(int));
        record_array[i] = (Record*)thread_malloc(sizeof(Record));

        // Set the value of each record to a random number within the specified range
        int min_value = 0;
        int max_value = 100;
        record_array[i]->value = rand() % (max_value - min_value + 1) + min_value;

        // Allocate memory for the string and set its value to a random length string
        char* str = (char*)thread_malloc(sizeof(char) * max_string_length);
        for (int j = 0; j < max_string_length; j++) {
            str[j] = rand() % ('z' - 'a') + 'a';
        }
        record_array[i]->string = str;

        // Set the status of each record to ACTIVE
        record_array[i]->status = ACTIVE;
    }

    return record_array;
}

// Function to concatenate all strings in the arrays and allocate memory for the result
char* concat_strings(Record** record_array, int num_records) {
    // Calculate the total length of all strings
    int total_length = 0;
    for (int i = 0; i < num_records; i++) {
        total_length += strlen(record_array[i]->string);
    }

    // Allocate memory for the concatenated string
    char* result = (char*)thread_malloc(sizeof(char) * (total_length + 1));

    // Concatenate all strings into the result string
    int offset = 0;
    for (int i = 0; i < num_records; i++) {
        strcpy(result + offset, record_array[i]->string);
        offset += strlen(record_array[i]->string);
    }

    // Add a null terminator to the end of the string
    result[total_length] = '\0';

    return result;
}

// Function to clean up memory allocated by init_arrays and concat_strings
void freeMemory(Record** record_array, int num_records) {
    // Free the memory for the offset array
    for (int i = 0; i < num_records; i++) {
        thread_free(offset_array[i]);
    }
    thread_free(offset_array);

    // Free the memory for the key array
    for (int i = 0; i < num_records; i++) {
        thread_free(key_array[i]);
    }
    thread_free(key_array);

    // Free the memory for the record array
    for (int i = 0; i < num_records; i++) {
        thread_free(record_array[i]->string);
        thread_free(record_array[i]);
    }
    thread_free(record_array);
}
```
