            if (keys[i] >= offset_n) {
                report_error("Invalid key value");
                free(memory);
                return NULL;
            }
            memory[keys[i]]++;
        }
    }
    // Allocate memory for the records array
    if (record_n > 0) {
        void* records = allocate_records(record_n);
        if (!records) {
            report_error("Failed to allocate memory for records");
            free(memory);
            return NULL;
