    if (memory_budget <= 0) {
        return false;
    }

    // Allocate memory for the record
    size_t buffer_size = strlen(record->buffer);
    Record* new_record = malloc(sizeof(Record) + buffer_size + 1);
    if (new_record == NULL) {
        return false;
    }

    // Copy the contents of the record to the new memory block
    memcpy(new_record, record, sizeof(Record));
    new_record->buffer = malloc(buffer_size + 1);
    if (new_record->buffer == NULL) {
        free(new_record);
        return false;
    }
    strncpy(new_record->buffer, record->buffer, buffer_size);

    // Add the new record to the list of records
    Record* current_record = record_list;
    if (current_record == NULL) {
        record_list = new_record;
    } else {
        while (current_record->next != NULL) {
            current_record = current_record->next;
        }
        current_record->next = new_record;
    }

    // Update the memory budget and return success
    memory_budget -= sizeof(Record) + buffer_size + 1;
    return true;
}

// Function to release all records, returns true if successful and false otherwise
bool release_all_records() {
    // Check if there are any records to release
    if (record_list == NULL) {
        return true;
    }

    // Release each record in the list
    Record* current_record = record_list;
    while (current_record != NULL) {
        Record* next_record = current_record->next;
        free(current_record);
        current_record = next_record;
    }

    // Reset the memory budget and return success
    memory_budget = 0;
    return true;
}

// Function to handle a logging message, returns true if successful and false otherwise
bool log_message(const char* message) {
    // Check if the logging system is available
    if (logging_system == NULL) {
        return false;
    }

    // Check if the memory budget has been exceeded
    if (memory_budget <= 0) {
        return false;
    }

    // Allocate memory for the message
    size_t buffer_size = strlen(message);
    char* new_buffer = malloc(buffer_size + 1);
    if (new_buffer == NULL) {
        return false;
    }
    strncpy(new_buffer, message, buffer_size);
    new_buffer[buffer_size] = '\0';

    // Log the message using the logging system
    int result = logging_system->log(logging_system, new_buffer);
    if (result != 0) {
        free(new_buffer);
        return false;
    }

    // Update the memory budget and return success
    memory_budget -= buffer_size + 1;
    return true;
}

// Main function to integrate with the third-party logging system
void third_party_logging(const char* message) {
    // Check if the message is null or empty
    if (message == NULL || strlen(message) == 0) {
        return;
    }

    // Handle the message using the logging function
    bool result = log_message(message);
    if (!result) {
        // Release all records and try again if the memory budget has been exceeded
        release_all_records();
        result = log_message(message);
    }

    // Check if the logging was successful
    if (result) {
        return;
    } else {
        // Print an error message and exit if the logging failed
        printf("Error: Unable to log message '%s'", message);
        exit(1);
    }
}
