struct LogEntry* allocLogEntry(int severity, const char* message) {
    if (bufferSize + sizeof(struct LogEntry) > maxBufferSize) {
        // Handle overflow scenarios gracefully by dropping the least recent entries
        struct LogEntry* droppedEntries = logBuffer + numEntries - 1;
        numEntries--;
        bufferSize -= sizeof(struct LogEntry);
        free(droppedEntries);
    }

