using System;
using System.Collections.Generic;

namespace DataStructureManager {
  public class DataStructureManager {
    private readonly List<offset_t> offsets;
    private readonly Dictionary<key_t, int> keys;
    private readonly List<record_t> records;

    // Seed for random number generation. Set to the current time by default.
    private readonly int seed = (int)DateTime.Now.Ticks;

    // Minimum and maximum values for the random value range.
    private readonly int minValue;
    private readonly int maxValue;

    public DataStructureManager(int minimum, int maximum) {
      this.minValue = minimum;
      this.maxValue = maximum;
      this.offsets = new List<offset_t>();
      this.keys = new Dictionary<key_t, int>();
      this.records = new List<record_t>();
    }

    public void Allocate(int size) {
      // Check if the input is valid.
      if (size < 0) {
        throw new ArgumentException("Size must be non-negative.", nameof(size));
      }

      // Allocate memory for the offsets and records.
      this.offsets.AddRange(new offset_t[size]);
      this.records.AddRange(new record_t[size]);

      // Initialize the random number generator with the current time.
      Random rng = new Random(this.seed);

      // Fill the records with random values within the specified range.
      for (int i = 0; i < size; ++i) {
        this.records[i].value = rng.Next(this.minValue, this.maxValue + 1);
      }
    }

    public void Deallocate() {
      // Check if there are any allocated records.
      if (this.records.Count == 0) {
        throw new InvalidOperationException("No records have been allocated.");
      }

      // Free the memory for the offsets and records.
      this.offsets.Clear();
      this.records.Clear();
    }

    public record_t GetRecord(int index) {
      // Check if the input is valid.
      if (index < 0 || index >= this.records.Count) {
        throw new ArgumentException("Index must be non-negative and less than or equal to the number of records.", nameof(index));
      }

      return this.records[index];
    }

    public void AddKey(key_t key) {
      // Check if the input is valid.
      if (this.keys.ContainsKey(key)) {
        throw new ArgumentException("The key already exists.", nameof(key));
      }

      this.keys.Add(key, this.offsets.Count);
    }

    public void RemoveKey(key_t key) {
      // Check if the input is valid.
      if (!this.keys.ContainsKey(key)) {
        throw new ArgumentException("The key does not exist.", nameof(key));
      }

      this.keys.Remove(key);
    }

    public int GetOffset(key_t key) {
      // Check if the input is valid.
      if (!this.keys.ContainsKey(key)) {
        throw new ArgumentException("The key does not exist.", nameof(key));
      }

      return this.offsets[this.keys[key]];
    }

    public void SetOffset(key_t key, int offset) {
      // Check if the input is valid.
      if (!this.keys.ContainsKey(key)) {
        throw new ArgumentException("The key does not exist.", nameof(key));
      }

      this.offsets[this.keys[key]] = offset;
    }

    public override string ToString() {
      return $"DataStructureManager: MinValue={this.minValue}, MaxValue={this.maxValue}, Seed={this.seed}, OffsetCount={this.offsets.Count}, RecordCount={this.records.Count}";
    }
  }
}
