```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define record structure for storing key-value pairs
typedef struct {
    int key;
    long offset;
} Record;

// Define configuration structure for each unique configuration
typedef struct {
    int increment_factor;
    long min_offset;
    long max_offset;
} Configuration;

// Define an array of records for each configuration
Record *records[10]; // Maximum number of configurations supported is 10

// Define a mutex for synchronizing access to records
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_memory(Configuration config) {
    int num_records = (config.max_offset - config.min_offset) / config.increment_factor + 1;

    // Allocate memory for records in this configuration
    Record *new_records = (Record *)malloc(num_records * sizeof(Record));

    if (!new_records) {
        return -1; // Memory allocation failed
    }

    // Initialize records with random keys and offsets within the specified range
    for (int i = 0; i < num_records; i++) {
        new_records[i].key = rand() % 100;
        new_records[i].offset = config.min_offset + config.increment_factor * i;
    }

    // Add new records to the array of records for this configuration
    pthread_mutex_lock(&mutex);
    records[config.increment_factor] = new_records;
    pthread_mutex_unlock(&mutex);

    return num_records;
}

int get_record(Configuration config, int key) {
    // Search for the record with the specified key in the array of records for this configuration
    Record *record = NULL;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[config.increment_factor][i].key == key) {
            record = &records[config.increment_factor][i];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return record ? record->offset : -1; // Return the offset of the found record, or -1 if not found
}

int update_record(Configuration config, int key) {
    // Search for the record with the specified key in the array of records for this configuration
    Record *record = NULL;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[config.increment_factor][i].key == key) {
            record = &records[config.increment_factor][i];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    // If the record is found, update its offset with a new random value within the specified range
    if (record) {
        int old_offset = record->offset;
        record->offset = rand() % config.max_offset + 1;
        return old_offset;
    } else {
        return -1; // Record not found
    }
}

int delete_record(Configuration config, int key) {
    // Search for the record with the specified key in the array of records for this configuration
    Record *record = NULL;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[config.increment_factor][i].key == key) {
            record = &records[config.increment_factor][i];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    // If the record is found, delete it from the array of records for this configuration
    if (record) {
        int index = (record - records[config.increment_factor]) / sizeof(Record);
        memmove(records[config.increment_factor] + index, records[config.increment_factor] + index + 1, sizeof(Record));
        return 0;
    } else {
        return -1; // Record not found
    }
}

int free_memory() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < 10; i++) {
        free(records[i]);
    }
    pthread_mutex_unlock(&mutex);
}
