} Record;

void dynamic_array_allocation(int num_records, int range_min, int range_max) {
    // Initialize random number generator with current time
    srand(time(NULL));

    // Allocate memory for arrays of offsets and keys
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    Record *records = malloc(num_records * sizeof(Record));

    // Initialize offsets based on keys and random number generation
    for (int i = 0; i < num_records; i++) {
        offsets[i] = keys[i] * 10;
        records[i].value = rand() % (range_max - range_min) + range_min;
    }

    // Print largest integer in array using helper function
    print_largest_integer(records, num_records);

    // Deallocate memory for arrays of offsets and keys
    free(offsets);
    free(keys);
    free(records);
}

void print_largest_integer(Record *records, int num_records) {
    // Find largest integer in array
    int largest = 0;
    for (int i = 1; i < num_records; i++) {
        if (records[i].value > records[largest].value) {
            largest = i;
        }
    }

    // Print largest integer
    printf("Largest integer: %d\n", records[largest].value);
}

int main() {
    // Set custom range for random number generation
    int range_min = 10;
    int range_max = 50;

    // Set seed for random number generator
    srand(time(NULL));

    // Allocate memory for arrays of offsets and keys
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    Record *records = malloc(num_records * sizeof(Record));

    // Initialize offsets based on keys and random number generation
    for (int i = 0; i < num_records; i++) {
        offsets[i] = keys[i] * 10;
        records[i].value = rand() % (range_max - range_min) + range_min;
    }

    // Print largest integer in array using helper function
    print_largest_integer(records, num_records);

    // Deallocate memory for arrays of offsets and keys
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
