#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

// Define constants for logging levels and file path
#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_ERROR 2
#define LOG_FILE_PATH "/var/log/distributed-cache.log"

// Define data structures for offset, key, and record arrays
typedef long offset;
typedef int key;
typedef struct {
    int value;
    char* string;
} record;

// Define a cache structure to hold the arrays and manage memory
typedef struct {
    offset* offsets;
    key* keys;
    record** records;
    size_t capacity;
    semaphore_t lock; // Use a semaphore to synchronize access to the cache
} cache_t;

// Initialize and allocate memory for the cache
void init_cache(cache_t* cache, size_t capacity) {
    // Allocate memory for the offset array
    cache->offsets = (offset*)malloc(capacity * sizeof(offset));
    if (!cache->offsets) {
        log_error("Failed to allocate memory for offset array");
        return;
    }

    // Initialize all offsets to -1
    memset(cache->offsets, -1, capacity * sizeof(offset));

    // Allocate memory for the key array
    cache->keys = (key*)malloc(capacity * sizeof(key));
    if (!cache->keys) {
        log_error("Failed to allocate memory for key array");
        return;
    }

    // Initialize all keys to -1
    memset(cache->keys, -1, capacity * sizeof(key));

    // Allocate memory for the record array
    cache->records = (record**)malloc(capacity * sizeof(record*));
    if (!cache->records) {
        log_error("Failed to allocate memory for record array");
        return;
    }

    // Initialize all records to NULL
    memset(cache->records, 0, capacity * sizeof(record*));

    cache->capacity = capacity;

    // Create a semaphore to synchronize access to the cache
    cache->lock = sem_open("cache_sem", O_CREAT, 0644, 1);
    if (cache->lock == SEM_FAILED) {
        log_error("Failed to create semaphore");
        return;
    }
}

// Add a new record to the cache
void add_record(cache_t* cache, int value, char* string) {
    // Acquire the semaphore to synchronize access to the cache
    sem_wait(cache->lock);

    // Check if there is enough space in the cache for a new record
    if (cache->capacity == cache->offsets[cache->capacity - 1]) {
        log_warning("Cache is full, cannot add more records");
        sem_post(cache->lock);
        return;
    }

    // Allocate memory for the new record
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        log_error("Failed to allocate memory for new record");
        sem_post(cache->lock);
        return;
    }

    // Initialize the new record with the provided value and string
    new_record->value = value;
    new_record->string = strdup(string);
    if (!new_record->string) {
        log_error("Failed to allocate memory for string");
        free(new_record);
        sem_post(cache->lock);
        return;
    }

    // Add the new record to the cache
    cache->offsets[cache->capacity] = cache->offsets[cache->capacity - 1] + 1;
    cache->keys[cache->capacity] = cache->keys[cache->capacity - 1] + 1;
    cache->records[cache->capacity] = new_record;

    // Release the semaphore to release access to the cache
    sem_post(cache->lock);
}

// Get a record from the cache
void* get_record(cache_t* cache, int key) {
    // Acquire the semaphore to synchronize access to the cache
    sem_wait(cache->lock);

    // Check if the requested key is in the cache
    size_t index = 0;
    while (index < cache->capacity && cache->keys[index] != key) {
        index++;
    }

    // If the requested key is not found, return NULL
    if (index == cache->capacity) {
        log_warning("Key %d not found in cache", key);
        sem_post(cache->lock);
        return NULL;
    }

    // Return a copy of the record at the requested index
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        log_error("Failed to allocate memory for new record");
        sem_post(cache->lock);
        return NULL;
    }

    new_record->value = cache->records[index]->value;
    new_record->string = strdup(cache->records[index]->string);
    if (!new_record->string) {
        log_error("Failed to allocate memory for string");
        free(new_record);
        sem_post(cache->lock);
        return NULL;
    }

    // Release the semaphore to release access to the cache
    sem_post(cache->lock);

    return new_record;
}

// Update a record in the cache
void update_record(cache_t* cache, int key, int value) {
    // Acquire the semaphore to synchronize access to the cache
    sem_wait(cache->lock);

    // Check if the requested key is in the cache
    size_t index = 0;
    while (index < cache->capacity && cache->keys[index] != key) {
        index++;
    }

    // If the requested key is not found, return NULL
    if (index == cache->capacity) {
        log_warning("Key %d not found in cache", key);
        sem_post(cache->lock);
        return;
    }

    // Update the value of the record at the requested index
    cache->records[index]->value = value;

    // Release the semaphore to release access to the cache
    sem_post(cache->lock);
}

// Free memory for a record in the cache
void free_record(cache_t* cache, void* record) {
    // Acquire the semaphore to synchronize access to the cache
    sem_wait(cache->lock);

    // Find the index of the requested record
    size_t index = 0;
    while (index < cache->capacity && cache->records[index] != record) {
        index++;
    }

    // If the requested record is not found, return NULL
    if (index == cache->capacity) {
        log_warning("Record not found in cache");
        sem_post(cache->lock);
        return;
    }

    // Free the string field of the record at the requested index
    free(((record*)record)->string);

    // Free the memory for the record itself
    free(record);

    // Release the semaphore to release access to the cache
    sem_post(cache->lock);
}

// Close and destroy the cache
void close_cache(cache_t* cache) {
    // Acquire the semaphore to synchronize access to the cache
    sem_wait(cache->lock);

    // Free all memory allocated for the arrays and records
    free(cache->offsets);
    free(cache->keys);
    for (size_t i = 0; i < cache->capacity; i++) {
        free((char*)cache->records[i]->string);
        free(cache->records[i]);
    }
    free(cache->records);

    // Close and destroy the semaphore
    if (sem_close(cache->lock) == -1) {
        log_error("Failed to close semaphore");
    }
    if (sem_unlink("cache_sem") == -1) {
        log_error("Failed to unlink semaphore file");
    }

    // Release the semaphore to release access to the cache
    sem_post(cache->lock);
}
```
This code implements a distributed cache system that uses an external key-value store for persisting strings. It defines a `cache_t` structure to hold arrays of `offset` values, `key` values, and `record` structures, as well as a semaphore to synchronize access to the cache. The `init_cache` function initializes and allocates memory for the arrays and records, while the `add_record`, `get_record`, `update_record`, `free_record`, and `close_cache` functions add, get, update, free, and close records in the cache, respectively. The code also defines helper functions for logging errors and warnings to a specified file without crashing the system.']

