#include <stdio.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

void* initializeDataStructures(long offsets[], int keys[], Record records[], long nRecords, long maxValue) {
    if (nRecords <= 0 || maxValue <= 0) {
        printf("Invalid input size: %ld\n", nRecords);
        return NULL;
    }

    // Allocate memory for the offsets array
    long* pOffsets = malloc(nRecords * sizeof(long));
    if (!pOffsets) {
        printf("Failed to allocate memory for offsets array\n");
        return NULL;
    }

    // Allocate memory for the keys array
    int* pKeys = malloc(nRecords * sizeof(int));
    if (!pKeys) {
        free(pOffsets);
        printf("Failed to allocate memory for keys array\n");
        return NULL;
    }

    // Allocate memory for the records array
    Record* pRecords = malloc(nRecords * sizeof(Record));
    if (!pRecords) {
        free(pOffsets);
        free(pKeys);
        printf("Failed to allocate memory for records array\n");
        return NULL;
    }

    // Validate the input sizes and handle out-of-memory scenarios
    long totalSize = nRecords * sizeof(Record) + nRecords * sizeof(int) + nRecords * sizeof(long);
    if (totalSize > SIZE_MAX - 1024 /* extra memory for error handling */) {
        free(pOffsets);
        free(pKeys);
        free(pRecords);
        printf("Input size is too large to fit in available system memory\n");
        return NULL;
    }

    // Initialize the keys array
    for (long i = 0; i < nRecords; ++i) {
        pKeys[i] = i % maxValue;
    }

    // Validate the offsets array and handle out-of-memory scenarios
    long offsetSum = 0;
    for (long i = 0; i < nRecords; ++i) {
        if (offsets[i] > maxValue || offsets[i] < 0) {
            printf("Offset %ld is invalid\n", offsets[i]);
            free(pOffsets);
            free(pKeys);
            free(pRecords);
            return NULL;
        }
        offsetSum += offsets[i];
    }
    if (offsetSum > nRecords) {
        printf("Invalid offsets sum: %ld\n", offsetSum);
        free(pOffsets);
        free(pKeys);
        free(pRecords);
        return NULL;
    }

    // Initialize the records array
    srand(time(NULL)); /* seed for random initialization */
    long recordIdx = 0;
    for (long i = 0; i < nRecords; ++i) {
        if (offsetSum == nRecords) {
            break;
        }
        pRecords[recordIdx].value = rand() % maxValue;
        offsetSum += offsets[i];
        recordIdx++;
    }

    // Return a pointer to the first element of the records array or NULL if memory allocation fails
    return (void*)pRecords;
}
