void manage_resources(config* config, window* windows) {
    // Initialize and allocate memory for the array of windows
    windows = (window*)malloc(sizeof(window) * config->window_size);

    // Loop through each window in the array
    for (int i = 0; i < config->window_size; i++) {
        // Allocate memory for the event array in each window
        windows[i].events = (event*)malloc(sizeof(event) * config->num_nodes);

        // Initialize the timestamp and event array in each window
        windows[i].timestamp = time(NULL);
        memset(windows[i].events, 0, sizeof(event) * config->num_nodes);
