    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(config->broker_url);
    if (inet_pton(AF_INET, config->broker_url, &server_address.sin_addr) <= 0) {
        perror("inet_pton failed");
        return;
    }

    if (connect(sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("connect failed");
        close(sock);
        return;
    }

    // Handle network latency and potential connection failures gracefully
    while (1) {
        char buffer[BUFSIZ];
        int read_size = recv(sock, buffer, BUFSIZ, 0);
        if (read_size < 0) {
            perror("recv failed");
            break;
        } else if (read_size == 0) {
            // End of file, exit the loop
            break;
        } else {
            // Process the received events and add them to the appropriate window
            char* token = strtok(buffer, " ");
            while (token != NULL) {
                // Get the event ID and value from the token
                int id = atoi(token);
                float value = atof(token);

                // Get the next token, which is the message string
                token = strtok(NULL, " ");

                // Add the event to the appropriate window
                windows[id % config->window_size].events[id].id = id;
                windows[id % config->window_size].events[id].value = value;
                strcpy(windows[id % config->window_size].events[id].message, token);
            }
        }
    }

    // Log errors to a specified file without crashing the system
    FILE* logfile = fopen(config->log_file_path, "a");
    if (logfile == NULL) {
        perror("fopen failed");
        return;
    }

    // Handle different logging levels efficiently within an existing logging framework
    int logging_level = 3; // Debug level
    if (logging_level >= 1) {
        fprintf(logfile, "Received %d events from the message broker\n", read_size);
    }

    if (logging_level >= 2) {
        for (int i = 0; i < config->window_size; i++) {
            window* window = windows + i;
            fprintf(logfile, "Window %d: timestamp=%ld\n", i, window->timestamp);
            for (int j = 0; j < config->num_nodes; j++) {
                event* event = window->events + j;
                fprintf(logfile, "Event %d: id=%d, value=%.2f, message='%s'\n", j, event->id, event->value, event->message);
            }
        }
    }

    // Robust error handling is required, ensuring that the system does not crash upon allocation failures
