// Define memory pool management functions
void double_pool_init(struct double_pool *p) {
    p->pool = malloc(POOL_SIZE);
    p->pool_size = POOL_SIZE;
    p->used_memory = 0;
}

void point_pool_init(struct point_pool *p) {
    p->pool = malloc(POOL_SIZE);
    p->pool_size = POOL_SIZE;
    p->used_memory = 0;
}

void record_pool_init(struct record_pool *p) {
    p->pool = malloc(POOL_SIZE);
    p->pool_size = POOL_SIZE;
    p->used_memory = 0;
}

void double_pool_free(struct double_pool *p) {
    free(p->pool);
}

void point_pool_free(struct point_pool *p) {
    free(p->pool);
}

void record_pool_free(struct record_pool *p) {
    free(p->pool);
}

// Define memory allocation functions for each data structure type
void *double_alloc(struct double_pool *p, size_t size) {
    if (size > p->pool_size - p->used_memory) {
        // Reallocate pool to fit new allocation request
        p->pool = realloc(p->pool, p->pool_size + size);
        p->pool_size += size;
    }

    void *ptr = (void *)((char *)p->pool + p->used_memory);
    p->used_memory += size;

    return ptr;
}

void *point_alloc(struct point_pool *p, size_t size) {
    if (size > p->pool_size - p->used_memory) {
        // Reallocate pool to fit new allocation request
        p->pool = realloc(p->pool, p->pool_size + size);
        p->pool_size += size;
    }

    void *ptr = (void *)((char *)p->pool + p->used_memory);
    p->used_memory += size;

    return ptr;
}

void *record_alloc(struct record_pool *p, size_t size) {
    if (size > p->pool_size - p->used_memory) {
        // Reallocate pool to fit new allocation request
        p->pool = realloc(p->pool, p->pool_size + size);
        p->pool_size += size;
    }

    void *ptr = (void *)((char *)p->pool + p->used_memory);
    p->used_memory += size;

    return ptr;
}

// Define serialization/deserialization functions for each data structure type
void double_serialize(struct double_pool *p, void *data) {
    struct double *d = (struct double *)data;
    char *buf = (char *)malloc(sizeof(double));
    memcpy(buf, &d->value, sizeof(double));
}

void point_serialize(struct point_pool *p, void *data) {
    struct point *pt = (struct point *)data;
