    memcpy(buf, &r->id, sizeof(unsigned long));
    memcpy(buf + sizeof(unsigned long), r->data, r->size);
}

void double_deserialize(struct double_pool *p, void *data, char *buf) {
    struct double *d = (struct double *)data;
    memcpy(&d->value, buf, sizeof(double));
}

void point_deserialize(struct point_pool *p, void *data, char *buf) {
    struct point *pt = (struct point *)data;
    memcpy(&pt->x, buf, sizeof(float));
    memcpy(&pt->y, buf + sizeof(float), sizeof(float));
}

void record_deserialize(struct record_pool *p, void *data, char *buf) {
