void double_file_write(struct double_pool *p, void *data) {
    struct double *d = (struct double *)data;
    char *buf = (char *)malloc(sizeof(double));
    double_serialize(p, data, buf);
    write(p->fd, buf, sizeof(double));
}

void point_file_write(struct point_pool *p, void *data) {
    struct point *pt = (struct point *)data;
    char *buf = (char *)malloc(sizeof(float) * 2);
    point_serialize(p, data, buf);
    write(p->fd, buf, sizeof(float) * 2);
}

void record_file_write(struct record_pool *p, void *data) {
    struct record *r = (struct record *)data;
    char *buf = (char *)malloc(sizeof(unsigned long) + r->size);
    record_serialize(p, data, buf);
    write(p->fd, buf, sizeof(unsigned long) + r->size);
