    for (int i = 0; i < MAX_LENGTH; i++) {
        // Update the moving average filter
        sum += array_of_data[i];
        moving_average[current_index] = sum / (current_index + 1);
        current_index++;

        // Detect anomalies using statistical methods
        if (moving_average[current_index - 1] > 2 * moving_average[current_index - 2]) {
            is_anomaly = true;
        }

        // Add the event log to the linked list
        struct EventLog* new_event_log = (struct EventLog*)malloc(sizeof(struct EventLog));
        new_event_log->timestamp = timestamp;
        new_event_log->event_type = is_anomaly ? 1 : 0; // 1 for anomaly, 0 for normal
        new_event_log->metadata = metadata;
        event_logs[i] = new_event_log;
    }

    // Free the memory allocated for the arrays and linked list
    free(moving_average);
    free(sensor_data);
    free(event_logs);
}
