#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a software component
typedef struct Component {
    char *name;
    char *description;
    char licenseType;
    char *copyrightHolder;
    time_t releaseDate;
} Component;

// Define a registry to store components
static Component **registry = NULL;
static size_t capacity = 1000; // default maximum capacity
static size_t count = 0; // current number of components in the registry

// Custom comparison function for sorting components based on release date
int compareComponents(const void *a, const void *b) {
    Component *compA = (Component *)a;
    Component *compB = (Component *)b;
    return compA->releaseDate - compB->releaseDate;
}

// Add a new component to the registry
void addComponent(const char *name, const char *description, char licenseType, const char *copyrightHolder, time_t releaseDate) {
    // Check if the registry is full and needs to be resized
    if (count == capacity) {
        capacity += 1000; // increase the maximum capacity by 1000 components
        Component **newRegistry = realloc(registry, sizeof(Component *) * capacity);
        if (!newRegistry) {
            printf("Error: unable to allocate memory for component registry\n");
            exit(EXIT_FAILURE);
        }
        registry = newRegistry;
    }

    // Create a new component structure and add it to the registry
    Component *component = malloc(sizeof(Component));
    if (!component) {
        printf("Error: unable to allocate memory for component\n");
        exit(EXIT_FAILURE);
    }
    component->name = strdup(name);
    component->description = strdup(description);
    component->licenseType = licenseType;
    component->copyrightHolder = strdup(copyrightHolder);
    component->releaseDate = releaseDate;
    registry[count++] = component;
}

// Update an existing component in the registry
void updateComponent(size_t index, const char *name, const char *description, char licenseType, const char *copyrightHolder, time_t releaseDate) {
    Component *component = registry[index];
    if (component) {
        free(component->name);
        component->name = strdup(name);
        free(component->description);
        component->description = strdup(description);
        component->licenseType = licenseType;
        free(component->copyrightHolder);
        component->copyrightHolder = strdup(copyrightHolder);
        component->releaseDate = releaseDate;
    }
}

// Delete a component from the registry
void deleteComponent(size_t index) {
    Component *component = registry[index];
    if (component) {
        free(component->name);
        free(component->description);
        free(component->copyrightHolder);
        memset(component, 0, sizeof(Component));
        registry[index] = NULL;
    }
}

// Print summary statistics for the component registry
void printSummary() {
    printf("Total components: %zu\n", count);
    printf("Most recent release date: ");
    if (count > 0) {
        Component *component = registry[count - 1];
        char timeBuf[32];
        strftime(timeBuf, sizeof(timeBuf), "%F", localtime(&component->releaseDate));
        printf("%s\n", timeBuf);
    } else {
        printf("No components in the registry\n");
    }
    printf("Average duration since release: ");
    if (count > 0) {
        time_t now = time(NULL);
        double avgDuration = 0;
        for (size_t i = 0; i < count; i++) {
            Component *component = registry[i];
            avgDuration += difftime(now, component->releaseDate);
        }
        avgDuration /= count;
        printf("%.2f days\n", avgDuration);
    } else {
        printf("No components in the registry\n");
    }
    printf("Active licenses per component: ");
    if (count > 0) {
        size_t numLicenses = 0;
        for (size_t i = 0; i < count; i++) {
            Component *component = registry[i];
            if (component->licenseType == 'A' || component->licenseType == 'B') {
                numLicenses++;
            }
        }
        printf("%zu\n", numLicenses);
    } else {
        printf("No components in the registry\n");
    }
}

// Handle memory allocation errors gracefully
void handleMemoryError(const char *msg) {
    printf("Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

// Reset memory tracking to zero after freeing all allocated memory
void resetMemoryTracking() {
    for (size_t i = 0; i < capacity; i++) {
        Component *component = registry[i];
        if (component) {
            free(component->name);
            free(component->description);
            free(component->copyrightHolder);
            memset(component, 0, sizeof(Component));
        }
    }
}
```
