#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define a structure to store packet data
typedef struct {
  uint32_t timestamp;
  uint16_t packet_id;
  char payload[150];
} packet_t;

// Define a dynamic buffer for storing packets
typedef struct {
  packet_t* buffer;
  size_t capacity;
  size_t size;
} packet_buffer_t;

// Initialize a dynamic buffer with the given capacity
packet_buffer_t* init_packet_buffer(size_t capacity) {
  packet_buffer_t* buffer = (packet_buffer_t*)malloc(sizeof(packet_buffer_t));
  if (buffer == NULL) {
    return NULL;
  }

  buffer->buffer = (packet_t*)malloc(capacity * sizeof(packet_t));
  if (buffer->buffer == NULL) {
    free(buffer);
    return NULL;
  }

  buffer->capacity = capacity;
  buffer->size = 0;

  return buffer;
}

// Add a packet to the dynamic buffer
int add_packet_to_buffer(packet_buffer_t* buffer, packet_t packet) {
  if (buffer == NULL || buffer->size >= buffer->capacity) {
    return -1;
  }

  buffer->buffer[buffer->size++] = packet;

  return 0;
}

// Remove a packet from the dynamic buffer
int remove_packet_from_buffer(packet_buffer_t* buffer, size_t index) {
  if (buffer == NULL || index >= buffer->size) {
    return -1;
  }

  for (size_t i = index; i < buffer->size - 1; ++i) {
    buffer->buffer[i] = buffer->buffer[i + 1];
  }

  --buffer->size;

  return 0;
}

// Read packets from the binary log file and add them to the dynamic buffer
int read_packets_from_file(const char* filename, packet_buffer_t* buffer) {
  FILE* file = fopen(filename, "rb");
  if (file == NULL) {
    return -1;
  }

  while (!feof(file)) {
    uint32_t timestamp;
    uint16_t packet_id;
    char payload[150];
    size_t bytes_read = fread(&timestamp, sizeof(uint32_t), 1, file);
    if (bytes_read != sizeof(uint32_t)) {
      break;
    }
    bytes_read += fread(&packet_id, sizeof(uint16_t), 1, file);
    if (bytes_read != sizeof(uint32_t) + sizeof(uint16_t)) {
      break;
    }
    bytes_read += fread(payload, sizeof(char), 150, file);
    if (bytes_read != sizeof(uint32_t) + sizeof(uint16_t) + 150) {
      break;
    }

    packet_t packet = {timestamp, packet_id, payload};
    add_packet_to_buffer(buffer, packet);
  }

  fclose(file);

  return buffer->size;
}

// Write packets from the dynamic buffer to the binary log file
int write_packets_to_file(const char* filename, packet_buffer_t* buffer) {
  FILE* file = fopen(filename, "wb");
  if (file == NULL) {
    return -1;
  }

  for (size_t i = 0; i < buffer->size; ++i) {
    packet_t packet = buffer->buffer[i];
    size_t bytes_written = fwrite(&packet.timestamp, sizeof(uint32_t), 1, file);
    if (bytes_written != sizeof(uint32_t)) {
      break;
    }
    bytes_written += fwrite(&packet.packet_id, sizeof(uint16_t), 1, file);
    if (bytes_written != sizeof(uint32_t) + sizeof(uint16_t)) {
      break;
    }
    bytes_written += fwrite(packet.payload, sizeof(char), 150, file);
    if (bytes_written != sizeof(uint32_t) + sizeof(uint16_t) + 150) {
      break;
    }
  }

  fclose(file);

  return buffer->size;
}

// Free the memory allocated to the dynamic buffer
void free_packet_buffer(packet_buffer_t* buffer) {
  if (buffer != NULL) {
    free(buffer->buffer);
    free(buffer);
  }
}

