    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(config->port);

    struct sockaddr_in client;
    socklen_t client_len = sizeof(client);
    int accept_socket = -1;
    while (accept_socket == -1) {
        if ((accept_socket = accept(socket, (struct sockaddr *)&client, &client_len)) == -1) {
            perror("accept");
            sleep(5);
        }
    }
}

// Add a new packet to the collection, allocating memory as needed
void add_packet(struct packet *packet) {
    // Increment the count of packets in the collection
    ++collection->count;

    // Allocate more memory for the array if necessary
    if (collection->count > collection->max_size) {
        size_t new_size = collection->max_size * 2;
        struct packet *new_packets = realloc(collection->packets, new_size);
        if (new_packets == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        collection->packets = new_packets;
        collection->max_size = new_size;
    }

    // Add the packet to the array and set its timestamp and ID
    collection->packets[collection->count - 1] = *packet;
    collection->packets[collection->count - 1].timestamp = get_timestamp();
    collection->packets[collection->count - 1].id = get_next_id();
}

// Remove a packet from the collection, freeing its memory as necessary
void remove_packet(struct packet *packet) {
    // Find the index of the packet in the array and decrement the count
    int i;
    for (i = 0; i < collection->count; ++i) {
        if (collection->packets[i].id == packet->id) {
            --collection->count;
            break;
        }
    }

    // Move the last packet to the removed position and free its memory
    struct packet *last_packet = &collection->packets[collection->count];
    if (i < collection->count - 1) {
        memcpy(packet, last_packet, sizeof(*packet));
        free(last_packet);
    } else {
        free(packet);
    }
}

// Parse a configuration file in INI format and return a dynamically allocated array of strings containing all unique keys
struct config *parse_ini(const char* filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Read the first line of the file and parse it as a key-value pair
    char *line = malloc(1024);
    int line_num = 0;
    struct config *config = malloc(sizeof(struct config));
    while (fgets(line, 1024, file) != NULL) {
        // Skip comments and empty lines
        if (line[0] == '#' || strlen(line) == 0) {
            continue;
        }

        // Split the line into key and value using the '=' character
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        // Add the key-value pair to the config struct
        if (key != NULL && value != NULL) {
            add_key_value_pair(config, key, value);
        } else {
            fprintf(stderr, "Error parsing line %d of file %s\n", line_num + 1, filename);
        }
    }

    // Close the file and return the config struct
    free(line);
    fclose(file);
    return config;
}

// Parse a configuration file in JSON format and return a dynamically allocated array of strings containing all unique keys
struct config *parse_json(const char* filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Read the first line of the file and parse it as a JSON object
    char *line = malloc(1024);
    int line_num = 0;
    struct config *config = malloc(sizeof(struct config));
    while (fgets(line, 1024, file) != NULL) {
        // Skip comments and empty lines
        if (line[0] == '#' || strlen(line) == 0) {
            continue;
        }

        // Parse the line as a JSON object and add its keys to the config struct
        json_object *json = json_tokener_parse(line);
        if (json != NULL && json->type == json_object) {
            json_object_object_foreach(json, key, value) {
                add_key_value_pair(config, key, value);
            }
        } else {
            fprintf(stderr, "Error parsing line %d of file %s\n", line_num + 1, filename);
        }
    }

    // Close the file and return the config struct
    free(line);
    fclose(file);
    return config;
}

// Parse a configuration file in YAML format and return a dynamically allocated array of strings containing all unique keys
struct config *parse_yaml(const char* filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Read the first line of the file and parse it as a YAML object
    char *line = malloc(1024);
    int line_num = 0;
    struct config *config = malloc(sizeof(struct config));
    while (fgets(line, 1024, file) != NULL) {
        // Skip comments and empty lines
        if (line[0] == '#' || strlen(line) == 0) {
            continue;
        }

        // Parse the line as a YAML object and add its keys to the config struct
        yaml_document *document = yaml_parse_file(filename);
        if (document != NULL) {
            yaml_node *root = document->root;
            if (root->type == YAML_MAPPING_NODE) {
                yaml_mapping_foreach(root, key, value) {
                    add_key_value_pair(config, key, value);
                }
            }
        } else {
            fprintf(stderr, "Error parsing line %d of file %s\n", line_num + 1, filename);
        }
    }

    // Close the file and return the config struct
    free(line);
    fclose(file);
    return config;
}

// Add a key-value pair to the configuration struct
void add_key_value_pair(struct config *config, const char *key, const char *value) {
    // Check if the key is already present in the config struct
    int i;
    for (i = 0; i < config->count; ++i) {
        if (strcmp(key, config->keys[i]) == 0) {
            break;
        }
    }

    // Add a new key-value pair to the config struct
    if (i == config->count) {
        ++config->count;
        config->keys = realloc(config->keys, config->count * sizeof(char*));
        if (config->keys == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        config->values = realloc(config->values, config->count * sizeof(char*));
        if (config->values == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        config->keys[i] = strdup(key);
        config->values[i] = strdup(value);
    } else {
        free(config->values[i]);
        config->values[i] = strdup(value);
    }
}

// Get the next available ID for a packet, ensuring uniqueness across all interfaces
uint16_t get_next_id() {
    uint16_t id;
    do {
        // Generate a random number between 0 and 65535 (inclusive)
        srand(timestamp);
        id = rand() % 65535;

        // Check if the ID is already in use by any interface
        for (int i = 0; i < config->num_interfaces; ++i) {
            if (config->interfaces[i].id == id) {
                break;
            } else if (i == config->num_interfaces - 1) {
                return id;
            }
        }
    } while (true);
}

// Get the current timestamp in milliseconds, using a time service for accurate timestamps
uint64_t get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t timestamp = (uint64_t)ts.tv_sec * 1000 + (uint64_t)(ts.tv_nsec / 1000000);
    return timestamp;
}
