// Data structure for storing sessions
typedef struct Session {
    char id[32];
    uint8_t metadata[64];
} Session;

// Function to create a new session and store it in memory
int createSession(const char *id) {
    int fd, size = sizeof(Session);
    void *ptr;

    // Open file descriptor for session storage
    if ((fd = open("session.dat", O_RDWR | O_CREAT, 0644)) == -1) {
        perror("open");
        return errno;
    }

    // Map memory for session data
    ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        return errno;
    }

    // Initialize session data and update memory usage tracking
    Session *session = ptr;
    strcpy(session->id, id);
    memset(session->metadata, 0, sizeof(session->metadata));
    __sync_fetch_and_add(&memory_usage, size);

    // Close file descriptor and return session ID
    close(fd);
    return strdup(session->id);
}

