Session *getSession(const char *id) {
    int fd;
    void *ptr;

    // Open file descriptor for session storage
    if ((fd = open("session.dat", O_RDONLY, 0644)) == -1) {
        perror("open");
        return NULL;
    }

    // Map memory for session data and find corresponding entry
    ptr = mmap(NULL, sizeof(Session), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    // Search for session with matching ID and return it
    Session *session = ptr;
    while (session->id[0] != '\0') {
        if (!strcmp(id, session->id))
            return session;
        session++;
    }

    // Close file descriptor and return NULL for invalid ID
    close(fd);
    return NULL;
}

// Function to delete a session from memory based on its ID
void deleteSession(const char *id) {
    int fd, size = sizeof(Session);
    void *ptr;

    // Open file descriptor for session storage
    if ((fd = open("session.dat", O_RDWR | O_CREAT, 0644)) == -1) {
        perror("open");
        return;
    }

    // Map memory for session data and find corresponding entry
    ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        return;
    }

    // Search for session with matching ID and delete it
    Session *session = ptr;
    while (session->id[0] != '\0') {
        if (!strcmp(id, session->id)) {
            memset(session, 0, size);
            __sync_fetch_and_add(&memory_usage, -size);
            break;
        }
        session++;
    }

    // Unmap memory and close file descriptor
    munmap(ptr, size);
    close(fd);
}

