                new_config.port = port;
            } else if (!strcmp(document.nodes[0].children[i].tag, "protocol")) {
                int err = validate_protocol(document.nodes[0].children[i].data);
                if (err) {
                    return err;
                }
                strcpy(new_config.protocol, document.nodes[0].children[i].data);
            } else if (!strcmp(document.nodes[0].children[i].tag, "timeout")) {
                int timeout = atoi(document.nodes[0].children[i].data);
