// Configuration fields for network service
static const char *fields[] = {"host", "port", "protocol", "timeout"};
static const size_t field_count = sizeof(fields) / sizeof(*fields);
static const size_t max_field_size = 255; // Maximum length of hostname or port
static const int min_port = 1, max_port = 65535; // Valid range for port
static const char *protocols[] = {"http", "https", "grpc"}; // Supported protocols

// Function to validate and parse JSON configuration file
bool configureNetworkServiceAndInitializeData(const char *json_config) {
    // Allocate memory for offsets, keys, and records arrays
    long *offsets = malloc(sizeof(*offsets) * field_count);
    int *keys = malloc(sizeof(*keys) * (field_count + 1));
    Record *records = malloc(sizeof(*records) * (field_count - 2)); // -2 to exclude timeout

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        return false;
    }

    // Initialize offsets for sorting and maximum value checks
    for (int i = 0; i < field_count - 1; i++) {
        offsets[i] = i;
    }

    // Parse JSON configuration file and validate fields
    int field_index = 0;
    while (*json_config != '\0') {
        char *field_name = strsep(&json_config, ":");
        if (strcmp(field_name, fields[field_index]) != 0) {
            printf("Invalid field name: %s\n", field_name);
            free(offsets);
            free(keys);
            free(records);
            return false;
        }
        char *value = strsep(&json_config, "\n");
        if (strlen(value) > max_field_size) {
            printf("Field value too long: %s\n", value);
            free(offsets);
            free(keys);
            free(records);
            return false;
        }
        switch (field_index) {
            case 0: // Hostname
                if (strlen(value) > max_field_size || !isValidHostname(value)) {
                    printf("Invalid hostname: %s\n", value);
                    free(offsets);
                    free(keys);
                    free(records);
                    return false;
                }
                break;
            case 1: // Port
                if (!isValidPort(value)) {
                    printf("Invalid port: %s\n", value);
                    free(offsets);
                    free(keys);
                    free(records);
                    return false;
                }
                break;
            case 2: // Protocol
                if (!isValidProtocol(value)) {
                    printf("Invalid protocol: %s\n", value);
                    free(offsets);
                    free(keys);
                    free(records);
                    return false;
                }
                break;
            case 3: // Timeout
                if (!isValidTimeout(value)) {
                    printf("Invalid timeout: %s\n", value);
                    free(offsets);
                    free(keys);
                    free(records);
                    return false;
                }
                break;
        }
        field_index++;
    }

    // Initialize keys array with unique values within specified range
    int key = 1;
    for (int i = 0; i < field_count - 2; i++) {
        keys[i] = key;
        key = (key + rand() % max_field_size) % (max_field_size + 1); // Randomize value within range
    }
    // Set last element of keys array to maximum value of field count - 2
    keys[field_count - 2] = max_field_size;

    // Initialize records with random values within specified range
    for (int i = 0; i < field_count - 3; i++) {
        Record record = {rand() % max_field_size};
        records[i] = record;
    }

    free(offsets);
    free(keys);
    free(records);
    return true;
}

// Function to check if hostname is valid
bool isValidHostname(const char *hostname) {
    for (int i = 0; i < strlen(hostname); i++) {
        if (!isalnum(hostname[i]) && hostname[i] != '-' && hostname[i] != '.') {
            return false;
        }
    }
    return true;
}

// Function to check if port is valid
bool isValidPort(const char *port) {
    int value = atoi(port);
    return value >= min_port && value <= max_port;
}

// Function to check if protocol is valid
bool isValidProtocol(const char *protocol) {
    for (int i = 0; i < sizeof(protocols) / sizeof(*protocols); i++) {
        if (strcmp(protocol, protocols[i]) == 0) {
            return true;
        }
    }
    return false;
}

// Function to check if timeout is valid
bool isValidTimeout(const char *timeout) {
    int value = atoi(timeout);
    return value > 0;
}
