void init_records(struct record records[], size_t num_offsets, size_t num_values) {
    assert(num_offsets > 0 && num_values > 0);
    assert(num_offsets <= INT_MAX && num_values <= INT_MAX);

    // Initialize random seed for generating keys and values
    srand(time(NULL));

    // Allocate memory for the arrays of offsets, keys, and values
    long *offsets = malloc(sizeof(long) * num_offsets);
    int *keys = malloc(sizeof(int) * num_offsets);
    double *values = malloc(sizeof(double) * num_values);

    // Check for allocation failures and handle them gracefully
    if (!offsets || !keys || !values) {
        fprintf(stderr, "Failed to allocate memory for arrays\n");
        return;
    }

    // Initialize the offsets array with random values
    for (size_t i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % num_values;
    }

    // Initialize the keys and values arrays randomly
    for (size_t i = 0; i < num_offsets; i++) {
        keys[i] = rand();
        values[i] = ((double)rand()) / RAND_MAX;
    }

    // Set the active flag of some records to true randomly
    for (size_t i = 0; i < num_offsets; i++) {
        if (rand() % 2 == 0) {
            records[i].active = true;
            records[i].key = &keys[i];
            records[i].value = &values[i];
            records[i].index = offsets[i];
        } else {
            records[i].active = false;
        }
    }
}

void cleanup_records(struct record records[]) {
    free(records);
}
