#include <limits.h>
#include <math.h>
#include <pthread.h>

// Define constants for log size and compression ratio
#define LOG_SIZE 1000000000 // 1 billion records
#define COMPRESSION_RATIO 5 // compress data to save disk space

// Define data structure for log entries
typedef struct {
    long offset;
    int key;
    double value;
} LogEntry;

// Define data structure for metadata
typedef struct {
    unsigned long num_records;
    unsigned long mem_usage;
    unsigned long compression_ratio;
} Metadata;

// Define function to initialize log and metadata structures
void init(LogEntry *log, Metadata *metadata) {
    // Initialize log entries with default values
    for (int i = 0; i < LOG_SIZE; i++) {
        log[i].offset = -1;
        log[i].key = 0;
        log[i].value = 0.0;
    }

    // Initialize metadata with default values
    metadata->num_records = 0;
    metadata->mem_usage = sizeof(LogEntry) * LOG_SIZE;
    metadata->compression_ratio = COMPRESSION_RATIO;
}

// Define function to insert new log entries
void insert(LogEntry *log, Metadata *metadata, int key, double value) {
    // Find the next available slot in the log
    unsigned long offset = metadata->num_records++;

    // Update log entry with new key and value
    log[offset].key = key;
    log[offset].value = value;

    // Update metadata with new record count and memory usage
    metadata->mem_usage += sizeof(LogEntry);
}

// Define function to retrieve log entries by key
void retrieve(LogEntry *log, Metadata *metadata, int key) {
    // Iterate through the log until we find a matching key
    for (int i = 0; i < metadata->num_records; i++) {
        if (log[i].key == key) {
            printf("Key: %d\nValue: %.2f\n", key, log[i].value);
            return;
        }
    }
}

// Define function to update existing log entries by key
void update(LogEntry *log, Metadata *metadata, int key, double value) {
    // Iterate through the log until we find a matching key
    for (int i = 0; i < metadata->num_records; i++) {
        if (log[i].key == key) {
            log[i].value = value;
            return;
        }
    }
}

// Define function to delete log entries by key
void delete(LogEntry *log, Metadata *metadata, int key) {
    // Iterate through the log until we find a matching key
    for (int i = 0; i < metadata->num_records; i++) {
        if (log[i].key == key) {
            // Shift all subsequent records down by one index
            for (int j = i; j < metadata->num_records - 1; j++) {
                log[j] = log[j + 1];
            }

            // Decrement the number of records and update memory usage
            metadata->num_records--;
            metadata->mem_usage -= sizeof(LogEntry);
        }
    }
}

// Define function to compress log entries
void compress(LogEntry *log, Metadata *metadata) {
    // Calculate the new compression ratio based on the current usage
    double new_compression_ratio = (double) metadata->mem_usage / LOG_SIZE;

