#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>
#include <yaml.h>

struct Config {
    char *server_host;
    int server_port;
    int log_level;
    size_t max_buffer_size;
    char compression_type[4]; // 3 characters + null terminator
};

struct EnvConfig {
    struct Config config;
    char *env_name;
};

// Function to parse a YAML file and validate its contents
int parse_yaml(const char *filename, struct EnvConfig **configs) {
    yaml_parser_t parser;
    yaml_document_t document;
    yaml_node_t *root;
    int i = 0;

    // Initialize the YAML parser and load the file
    yaml_parser_initialize(&parser);
    if (!yaml_parser_load_file(&parser, filename)) {
        fprintf(stderr, "Error: %s\n", yaml_parser_get_error(&parser));
        return -1;
    }

    // Get the root node of the YAML file
    root = yaml_document_get_root_node(&document);

    // Iterate over each environment in the YAML file
    for (i = 0; i < root->nodes.top->nodes.size; i++) {
        yaml_node_t *env_node = root->nodes.top->nodes[i];
        char *env_name = env_node->data.scalar.value;
        struct Config config;

        // Iterate over each field in the environment node
        for (j = 0; j < env_node->children.size; j++) {
            yaml_node_t *field_node = env_node->children[j];
            char *field_name = field_node->data.scalar.value;

            // Handle mandatory fields
            if (strcmp(field_name, "server_host") == 0) {
                config.server_host = malloc(sizeof(char) * (strlen(field_node->data.scalar.value) + 1));
                strcpy(config.server_host, field_node->data.scalar.value);
            } else if (strcmp(field_name, "server_port") == 0) {
                config.server_port = atoi(field_node->data.scalar.value);
            } else if (strcmp(field_name, "log_level") == 0) {
                config.log_level = atoi(field_node->data.scalar.value);
            } else if (strcmp(field_name, "max_buffer_size") == 0) {
                config.max_buffer_size = atol(field_node->data.scalar.value);
            } else {
                // Handle optional fields
                if (strcmp(field_name, "compression_type") == 0) {
                    strcpy(config.compression_type, field_node->data.scalar.value);
                } else {
                    fprintf(stderr, "Warning: unknown field '%s' in environment %s\n", field_name, env_name);
                }
            }
        }

        // Add the configuration for this environment to the list
        struct EnvConfig *env_config = malloc(sizeof(struct EnvConfig));
        env_config->config = config;
        env_config->env_name = env_name;
        configs[i] = env_config;
    }

    // Clean up the YAML parser and return the configuration list
    yaml_parser_delete(&parser);
    return i;
}
```
