        } else if (strcmp(token, "timeout") == 0) {
            token = strtok(NULL, " \t\n");
            if (token != NULL && sscanf(token, "%d", &config.timeout) == 1) {
                ret = -1;
                goto cleanup;
            }
        } else {
            ret = -1;
            goto cleanup;
        }
    }

    // Allocate an array for the file records
    records = (file_record_t*) malloc(MAX_RECORDS * sizeof(file_record_t));
    if (records == NULL) {
        perror("Error allocating memory for file records");
        ret = -1;
        goto cleanup;
    }

    // Initialize the array with default values
    memset(records, 0, MAX_RECORDS * sizeof(file_record_t));

    // Load the file metadata from disk
    gettimeofday(&start, NULL);
    for (size_t i = 0; i < num_records; ++i) {
        ret = read_file_metadata(records[i].path);
        if (ret != 0) break;
    }
    gettimeofday(&end, NULL);

    // Log the time taken for loading metadata
    printf("Loading metadata took %ld.%06ld seconds\n", end.tv_sec - start.tv_sec, end.tv_usec - start.tv_usec);

cleanup:
    if (fp != NULL) fclose(fp);
    if (ret < 0) {
        // Handle error cleanup here
    }
    return ret;
}

