        char* token = strtok(line, " \t\n");
        if (token == NULL) continue;
        if (strcmp(token, "size") == 0) {
            token = strtok(NULL, " \t\n");
            if (token != NULL && sscanf(token, "%lf", &record->size) == 1) {
                ret = -1;
                goto cleanup;
