public class HostMetadataProcessor
{
    private string _directoryPath;
    private List<string> _supportedFileExtensions;
    private CloudStorageClient _cloudStorageClient;
    private MetadataTransformer _metadataTransformer;
    private HostnameResolver _hostnameResolver;

    public HostMetadataProcessor(string directoryPath = null)
    {
        if (directoryPath != null)
        {
            _directoryPath = directoryPath;
        }
        else
        {
            _directoryPath = DEFAULT_DIRECTORY_PATH;
        }

        // Initialize supported file extensions and cloud storage client
        _supportedFileExtensions = new List<string> { ".txt", ".pdf", ".docx" };
        _cloudStorageClient = new CloudStorageClient();

        // Initialize metadata transformer and hostname resolver
        _metadataTransformer = new MetadataTransformer();
        _hostnameResolver = new HostnameResolver();
    }

    public void ExtractAndTransformMetadata(string directoryPath)
    {
        var filesInDirectory = Directory.GetFiles(directoryPath, "*.*", SearchOption.AllDirectories);

        foreach (var file in filesInDirectory)
        {
            // Resolve hostname to IP address
            var ipAddress = _hostnameResolver.ResolveHostname(file);

            // Extract metadata from file
            var metadata = _metadataTransformer.ExtractMetadataFromFile(file);

            // Transform metadata into JSON format
            var jsonData = _metadataTransformer.TransformMetadataToJson(metadata, ipAddress);

            // Send serialized metadata to cloud storage service
            _cloudStorageClient.SendSerializedData(jsonData);
        }
    }

    public void UpdateDirectoryPath(string newDirectoryPath)
    {
        _directoryPath = newDirectoryPath;

        // Reset cloud storage client and metadata transformer with new directory path
        _cloudStorageClient.Reset();
        _metadataTransformer.Reset(_directoryPath);
    }

    public void Reset()
    {
        _directoryPath = DEFAULT_DIRECTORY_PATH;

        // Reset cloud storage client, metadata transformer, and hostname resolver with default directory path
        _cloudStorageClient.Reset();
        _metadataTransformer.Reset(_directoryPath);
        _hostnameResolver.Reset();
    }

    public override string ToString()
    {
        return $"Directory Path: {_directoryPath}\nSupported File Extensions: {string.Join(", ", _supportedFileExtensions)}\nCloud Storage Client: {_cloudStorageClient}\nMetadata Transformer: {_metadataTransformer}\nHostname Resolver: {_hostnameResolver}";
    }

    private void PrivateHelperMethod()
    {
        // Add any necessary helper methods here
    }
}
