import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class ExecuteCommand {
    public static void main(String[] args) throws IOException {
        // Check input arguments
        if (args.length < 2) {
            System.err.println("Usage: java ExecuteCommand <command> <filename>");
            System.exit(1);
        }

        // Read the command and filename from the arguments
        String command = args[0];
        String filename = args[1];

        // Initialize a list to store the records
        List<String> records = new ArrayList<>();

        // Check if the file exists before executing the command
        if (new File(filename).exists()) {
            System.out.println("File " + filename + " already exists");
            System.exit(1);
        }

        // Execute the command and read the output stream
        ProcessBuilder pb = new ProcessBuilder(command);
        Process process = pb.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            records.add(line);
        }

        // Parse the output stream and find the largest integer greater than a specified minimum threshold
        int min = 10; // specified minimum threshold
        int largest = 0;
        for (String record : records) {
            int key = Integer.parseInt(record);
            if (key > min && key > largest) {
                largest = key;
            }
        }
        System.out.println("Largest integer greater than " + min + ": " + largest);

        // Clean up resources
        reader.close();
    }
}
