// Custom allocator function that handles memory allocation and deallocation efficiently
void* custom_alloc(size_t size) {
    void* ptr = NULL;
    if (size > 0) {
        ptr = malloc(size);
        if (!ptr) {
            errno = ENOMEM;
        }
    }
    return ptr;
}

// Custom deallocator function that handles memory deallocation efficiently
void custom_dealloc(void* ptr) {
