// Structure to store the record data
typedef struct record {
    int value;
} Record;

// Function to allocate memory for an array of records
Record* alloc_records(size_t n_records, size_t n_keys, size_t n_ids) {
    // Calculate the total number of bytes required for the arrays
    size_t total_bytes = (n_records * sizeof(Record)) + (n_keys * sizeof(int)) + (n_ids * sizeof(unsigned int));

    // Allocate memory for the record array
    Record* records = custom_alloc(total_bytes);
    if (!records) {
        return NULL;
    }

    // Initialize the offset values based on the corresponding key and ID
    unsigned int* offsets = (unsigned int*) (records + n_records);
    for (size_t i = 0; i < n_keys; i++) {
        for (size_t j = 0; j < n_ids; j++) {
            *(offsets + i) = ((unsigned int) *(keys + i)) * ((unsigned int) *(ids + j));
            offsets += n_records;
        }
    }

    // Initialize the key and ID arrays
    int* keys = (int*) (offsets + n_records);
    for (size_t i = 0; i < n_keys; i++) {
        *(keys + i) = random() % INT_MAX + 1;
    }

    unsigned int* ids = (unsigned int*) (keys + n_keys);
    for (size_t i = 0; i < n_ids; i++) {
        *(ids + i) = random() % UINT_MAX;
    }

    // Return the pointer to the record array
    return records;
}

// Function to deallocate memory for an array of records
void dealloc_records(Record* records) {
    custom_dealloc(records);
}

