struct memory_pool* create_memory_pool(size_t capacity) {
    struct memory_pool* pool = malloc(sizeof(struct memory_pool));
    pool->capacity = capacity;
    pool->count = 0;
    pool->records = malloc(capacity * sizeof(struct record));
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Define a function to add a new record to the memory pool
int add_record(struct memory_pool* pool, int key, long offset, double precision) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count == pool->capacity) {
        // resize the pool if necessary
        size_t new_capacity = pool->capacity * 2;
        struct record* new_records = realloc(pool->records, new_capacity * sizeof(struct record));
        if (new_records == NULL) {
