            pool->records[i].offset = offset;
            pool->records[i].precision = precision;
            pthread_mutex_unlock(&pool->mutex);
            return 0; // success
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1; // record not found
}

// Define a function to remove an existing record from the memory pool
int remove_record(struct memory_pool* pool, int key) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->records[i].key == key) {
            // remove the record by shifting all subsequent records back one index
            for (size_t j = i + 1; j < pool->count; j++) {
                pool->records[j - 1] = pool->records[j];
            }
            pool->count--;
            pthread_mutex_unlock(&pool->mutex);
            return 0; // success
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1; // record not found
}

// Define a function to retrieve an existing record from the memory pool
