    }
    printf("Memory usage: %zu bytes\n", total_memory);
    printf("Operation count: %zu\n", pool->count);
}

// Define a function to serialize the memory pool to a file
int serialize_pool(struct memory_pool* pool, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        return -1; // failed to open file for writing
    }
    pthread_mutex_lock(&pool->mutex);
    size_t num_records = pool->count;
    fwrite(&num_records, sizeof(size_t), 1, fp);
    for (size_t i = 0; i < pool->count; i++) {
        struct record* record = &pool->records[i];
        fwrite(record, sizeof(struct record), 1, fp);
    }
    pthread_mutex_unlock(&pool->mutex);
    fclose(fp);
    return 0; // success
}

// Define a function to deserialize the memory pool from a file
int deserialize_pool(struct memory_pool* pool, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return -1; // failed to open file for reading
    }
    size_t num_records = 0;
    fread(&num_records, sizeof(size_t), 1, fp);
    pool->capacity = num_records * 2;
    pool->count = num_records;
    pool->records = malloc(pool->capacity * sizeof(struct record));
    for (size_t i = 0; i < num_records; i++) {
        struct record* record = &pool->records[i];
        fread(record, sizeof(struct record), 1, fp);
    }
    fclose(fp);
    return 0; // success
}

// Define a function to destroy the memory pool and release resources
void destroy_memory_pool(struct memory_pool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->mutex);
