    // Lock the hash table and delete list to ensure thread safety
    pthread_mutex_lock(&ht->mutex);
    pthread_mutex_lock(&delete_list->mutex);

    // Iterate through the hash table and linked list, deallocating memory for records that have been marked for deletion
