// Define functions for tracking memory usage and managing concurrency
void *tracked_malloc(size_t size) {
    // Allocate memory and track it in a list of allocated blocks
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Failed to allocate %zu bytes of memory\n", size);
        return NULL;
    }
    struct block {
        void *ptr;
        size_t size;
    };
    struct block* new_block = allocate_memory(sizeof(struct block));
    if (!new_block) {
        free(ptr);
        fprintf(stderr, "Error: Failed to allocate memory for tracking\n");
        return NULL;
    }
    new_block->ptr = ptr;
    new_block->size = size;
    tracked_memory_usage += size;
}

void *tracked_realloc(void *ptr, size_t size) {
    // Reallocate memory and update tracking information
    void *new_ptr = realloc(ptr, size);
    if (!new_ptr) {
        fprintf(stderr, "Error: Failed to reallocate %zu bytes of memory\n", size);
        return NULL;
    }
    struct block* old_block = get_tracked_memory(ptr);
    if (!old_block) {
        free(new_ptr);
        fprintf(stderr, "Error: Failed to reallocate memory for tracking\n");
        return NULL;
    }
    tracked_memory_usage -= old_block->size;
    tracked_memory_usage += size;
}

void tracked_free(void *ptr) {
    // Free memory and update tracking information
    free(ptr);
    struct block* old_block = get_tracked_memory(ptr);
    if (!old_block) {
        fprintf(stderr, "Error: Failed to track freed memory\n");
        return;
    }
    tracked_memory_usage -= old_block->size;
}

struct block* get_tracked_memory(void *ptr) {
    // Find and return the tracking information for a given pointer
    struct block* current = allocated_blocks.head;
    while (current) {
        if (current->ptr == ptr) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}
