struct LogEntry {
    char* timestamp;
    char* message;
    int severity_level;
};

class LogCollection {
private:
    vector<LogEntry> log_entries_;
    unordered_map<string, int> message_index_;
    int max_message_length_;
    int min_severity_level_;
    int max_severity_level_;
    mutex lock_;

public:
    LogCollection(int max_message_length = 1024, int min_severity_level = 0, int max_severity_level = 10) {
        max_message_length_ = max_message_length;
        min_severity_level_ = min_severity_level;
        max_severity_level_ = max_severity_level;
    }

    void add(LogEntry& entry) {
        lock_.lock();
        log_entries_.push_back(entry);
        message_index_.insert({entry.message, (int)log_entries_.size() - 1});
        lock_.unlock();
    }

    void remove(LogEntry& entry) {
        lock_.lock();
        log_entries_.erase(log_entries_.begin() + message_index_[entry.message]);
        message_index_.erase(entry.message);
        lock_.unlock();
    }

    void update(LogEntry& entry) {
        lock_.lock();
        log_entries_[message_index_[entry.message]] = entry;
        lock_.unlock();
    }

    vector<LogEntry> query(int min_severity_level, int max_severity_level) {
        vector<LogEntry> result;
        lock_.lock();
        for (auto& entry : log_entries_) {
            if (entry.severity_level >= min_severity_level && entry.severity_level <= max_severity_level) {
                result.push_back(entry);
            }
        }
        lock_.unlock();
        return result;
    }

    vector<LogEntry> query(int min_severity_level, int max_severity_level, string& message) {
        vector<LogEntry> result;
        lock_.lock();
        for (auto& entry : log_entries_) {
            if (entry.severity_level >= min_severity_level && entry.severity_level <= max_severity_level && strstr(entry.message, message)) {
                result.push_back(entry);
            }
        }
        lock_.unlock();
        return result;
    }
};

// Example usage:
LogCollection collection(1024, 0, 10);
collection.add({"timestamp", "message", 5});
collection.query(0, 10); // returns all log entries with severity level in [0, 10]
collection.update({"timestamp", "updated message", 7});
collection.remove({"timestamp", "updated message", 7});']

