        // Allocate memory for the new attacks
        for (size_t i = 0; i < attack_names.size(); ++i) {
            attacks.push_back({new char[attack_names[i].length() + 1], attack_values[i]});
            memcpy(attacks[i].name, attack_names[i].c_str(), attack_names[i].length() + 1);
        }

        // Update the maximum name length and acceptable values range
        max_name_length = max(max_name_length, attacks.size());
        acceptable_values = {min(acceptable_values.first, attack_values[0]), max(acceptable_values.second, attack_values[attack_values.size() - 1])};
    }

    void query_attacks(const string& substring) const {
        // Create a map to store the attacks that contain the specified substring
        unordered_map<string, vector<int>> matching_attacks;

        // Search for matching attacks and add them to the map
        for (size_t i = 0; i < attacks.size(); ++i) {
            if (strstr(attacks[i].name, substring.c_str()) != nullptr) {
                matching_attacks[substring].push_back(i);
            }
