        size_t longest_name = 0;
        for (size_t i = 0; i < attacks.size(); ++i) {
            if (strlen(attacks[i].name) > longest_name) {
                longest_name = strlen(attacks[i].name);
            }
        }
        cout << "Longest attack name: " << attacks[longest_name].name << endl;
    }

    void random_selection() {
        // Select one of the two predefined attacks randomly with a cooldown period of 9 seconds
        static int selected_attack = -1;
        static unsigned long last_selected = 0;

        if (last_selected + 9 < chrono::steady_clock::now().time_since_epoch().count()) {
            // Select a new attack and update the last selection time
            selected_attack = rand() % 2;
            last_selected = chrono::steady_clock::now().time_since_epoch().count();
