#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    char status_indicator;
} record;

// Define a global variable to store the number of unique keys processed
static int num_unique_keys = 0;

// Define a global variable to store the total memory usage in bytes
static size_t total_memory_usage = 0;

// Define a mutex to prevent race conditions when updating the data structures
pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;

/*
 * Function to initialize a record with random values and check for duplicates.
 * If a duplicate is detected, all previously allocated memory is freed and an error code is returned.
 */
int init_record(record* r) {
    // Generate a random key between 1 and 1000
    int key = rand() % 999 + 1;

    // Check if the key already exists in the collection
    bool duplicate = false;
    for (int i = 0; i < num_unique_keys; i++) {
        if (r[i].key == key) {
            duplicate = true;
            break;
        }
    }

    // If a duplicate is detected, free all previously allocated memory and return an error code
    if (duplicate) {
        for (int i = 0; i < num_unique_keys; i++) {
            free(r[i].offset);
        }
        return -1;
    }

    // If no duplicates are detected, initialize the record with random values and add it to the collection
    r->key = key;
    r->status_indicator = 0;
    total_memory_usage += sizeof(record);
    num_unique_keys++;

    return 0;
}

/*
 * Function to allocate memory for a record and initialize it with random values.
 * If memory allocation fails, an error code is returned.
 */
int alloc_record() {
    // Allocate memory for the record
    record* r = malloc(sizeof(record));
    if (r == NULL) {
        return -1;
    }

    // Initialize the record with random values and check for duplicates
    int result = init_record(r);
    if (result < 0) {
        free(r);
        return -1;
    }

    // Return a pointer to the first element of the record array
    return r;
}

/*
 * Function to deallocate memory for a record.
 */
void dealloc_record(record* r) {
    free(r);
    num_unique_keys--;
    total_memory_usage -= sizeof(record);
}

/*
 * Function to insert a record into the collection.
 * If memory allocation fails, an error code is returned.
 */
int insert_record(record* r) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&mem_lock);

    // Check if the maximum memory usage has been reached
    if (total_memory_usage > 0.8 * system_memory()) {
        pthread_mutex_unlock(&mem_lock);
        return -1;
    }

    // Allocate memory for the record and initialize it with random values
    int result = alloc_record();
    if (result < 0) {
        pthread_mutex_unlock(&mem_lock);
        return -1;
    }

    // Insert the record into the collection
    r[num_unique_keys - 1] = *r;

    // Release the lock and return success
    pthread_mutex_unlock(&mem_lock);
    return 0;
}

/*
 * Function to remove a record from the collection.
 */
void remove_record(record* r) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&mem_lock);

    // Find the index of the record in the collection and deallocate its memory
    int i;
    for (i = 0; i < num_unique_keys; i++) {
        if (r[i].key == r->key) {
            dealloc_record(r + i);
            break;
        }
    }

    // Release the lock and return success
    pthread_mutex_unlock(&mem_lock);
}

/*
 * Function to update a record in the collection.
 */
void update_record(record* r) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&mem_lock);

    // Find the index of the record in the collection and update its fields
    int i;
    for (i = 0; i < num_unique_keys; i++) {
        if (r[i].key == r->key) {
            r[i] = *r;
            break;
        }
    }

    // Release the lock and return success
    pthread_mutex_unlock(&mem_lock);
}

/*
 * Function to retrieve a record from the collection.
 */
record* get_record(int key) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&mem_lock);

    // Find the index of the record in the collection and return its pointer
    int i;
    for (i = 0; i < num_unique_keys; i++) {
        if (r[i].key == key) {
            break;
        }
    }

    // Release the lock and return success
    pthread_mutex_unlock(&mem_lock);
    return r + i;
}

/*
 * Function to retrieve the total number of unique keys in the collection.
 */
int get_num_unique_keys() {
    return num_unique_keys;
}

/*
 * Function to retrieve the total memory usage in bytes.
 */
size_t get_total_memory_usage() {
    return total_memory_usage;
}

/*
 * Function to log memory usage and unique key count information to a file named "memory_usage.log".
 */
void log_stats(FILE* f) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&mem_lock);

    // Write the current time, memory usage, and unique key count to the file
    time_t rawtime;
    struct tm* timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(f, "%s Memory usage: %zu bytes\n", buffer, total_memory_usage);
    fprintf(f, "Unique key count: %d\n", num_unique_keys);

    // Release the lock and return success
    pthread_mutex_unlock(&mem_lock);
}

// Define a function to retrieve the total system memory in bytes
size_t system_memory() {
    FILE* f = fopen("/proc/meminfo", "r");
    size_t mem_total = 0;
    while (true) {
        char line[128];
        if (fgets(line, 128, f) == NULL) break;
        if (strncmp(line, "MemTotal:", 9) == 0) {
            char* endptr;
            mem_total = strtoul(line + 9, &endptr, 10);
            break;
        }
    }
    fclose(f);
    return mem_total * 1024;
}']

