// Define a structure to store an item and its value
typedef struct {
    char *name;
    double value;
} item_t;

// Define a dynamic collection of items
typedef struct {
    size_t capacity; // current capacity of the collection
    size_t size;     // number of items in the collection
    item_t *items;   // array of items
} item_collection_t;

// Function to initialize a new item collection with the given capacity
item_collection_t* init_item_collection(size_t capacity) {
    assert(capacity > 0);
    item_collection_t *collection = malloc(sizeof(item_collection_t));
    collection->capacity = capacity;
    collection->size = 0;
    collection->items = calloc(capacity, sizeof(item_t));
    return collection;
}

// Function to insert a new item into the collection
void insert_item(item_collection_t *collection, char *name, double value) {
    assert(collection != NULL && name != NULL);
    if (collection->size == collection->capacity) {
        // Increase the capacity of the collection by 50%
        size_t new_capacity = (size_t)(ceil(collection->capacity * 1.5));
        item_t *new_items = realloc(collection->items, sizeof(item_t) * new_capacity);
        if (new_items == NULL) {
            printf("Error: failed to allocate memory for the collection.\n");
            exit(EXIT_FAILURE);
        }
        collection->capacity = new_capacity;
        collection->items = new_items;
    }
    item_t *item = &collection->items[collection->size++];
    item->name = strdup(name);
    item->value = value;
}

// Function to delete an item from the collection by its name
void delete_item(item_collection_t *collection, char *name) {
    assert(collection != NULL && name != NULL);
    for (size_t i = 0; i < collection->size; i++) {
        if (strcmp(name, collection->items[i].name) == 0) {
            // Shift the remaining items down by one position
            memmove(&collection->items[i], &collection->items[i + 1], sizeof(item_t) * (collection->size - i));
            collection->size--;
            break;
        }
    }
}

// Function to retrieve an item from the collection by its name
item_t* get_item(item_collection_t *collection, char *name) {
    assert(collection != NULL && name != NULL);
    for (size_t i = 0; i < collection->size; i++) {
        if (strcmp(name, collection->items[i].name) == 0) {
            return &collection->items[i];
        }
    }
    return NULL;
}

// Function to update the value of an item in the collection by its name
void set_item_value(item_collection_t *collection, char *name, double value) {
    assert(collection != NULL && name != NULL);
    for (size_t i = 0; i < collection->size; i++) {
        if (strcmp(name, collection->items[i].name) == 0) {
            collection->items[i].value = value;
            return;
        }
    }
}

// Function to persist the collection to disk periodically
void save_collection(item_collection_t *collection) {
    assert(collection != NULL);
    FILE *file = fopen("collection.dat", "wb");
    if (file == NULL) {
        printf("Error: failed to open file for writing.\n");
        exit(EXIT_FAILURE);
    }
    // Write the size of the collection to the file
    fwrite(&collection->size, sizeof(size_t), 1, file);
    // Write each item in the collection to the file
    for (size_t i = 0; i < collection->size; i++) {
        fwrite(collection->items[i].name, strlen(collection->items[i].name) + 1, 1, file);
        fwrite(&collection->items[i].value, sizeof(double), 1, file);
    }
    fclose(file);
}

// Function to load the collection from disk
void load_collection(item_collection_t *collection) {
    assert(collection != NULL);
    FILE *file = fopen("collection.dat", "rb");
    if (file == NULL) {
        printf("Error: failed to open file for reading.\n");
        exit(EXIT_FAILURE);
    }
    // Read the size of the collection from the file
    fread(&collection->size, sizeof(size_t), 1, file);
    // Allocate memory for the items in the collection
    item_t *items = calloc(collection->capacity, sizeof(item_t));
    if (items == NULL) {
        printf("Error: failed to allocate memory for the collection.\n");
        exit(EXIT_FAILURE);
    }
    // Read each item in the collection from the file
    for (size_t i = 0; i < collection->size; i++) {
        fread(&items[i].name, strlen(items[i].name) + 1, 1, file);
        fread(&items[i].value, sizeof(double), 1, file);
    }
    // Set the items in the collection to the loaded items
    collection->items = items;
}

// Function to update the maximum length of names and the acceptable range of values stored in the item structures
void set_parameters(item_collection_t *collection, size_t max_name_length, double min_value, double max_value) {
    assert(collection != NULL);
    for (size_t i = 0; i < collection->size; i++) {
        char *new_name = malloc(sizeof(char) * (max_name_length + 1));
        if (new_name == NULL) {
            printf("Error: failed to allocate memory for the item name.\n");
            exit(EXIT_FAILURE);
        }
        strncpy(new_name, collection->items[i].name, max_name_length);
        new_name[max_name_length] = '\0';
        free(collection->items[i].name);
        collection->items[i].name = new_name;
    }
}
