struct Resource {
    std::string name;
    int type;
    double availability;
};

class ResourceManager {
public:
    ResourceManager() {}

    void insertResource(const Resource& resource) {
        // Insert the new resource into the map
        resources_.insert({resource.name, resource});
    }

    void deleteResource(const std::string& name) {
        // Remove the resource from the map
        resources_.erase(name);
    }

    const Resource* getResource(const std::string& name) const {
        // Find the resource in the map and return a pointer to it
        auto iter = resources_.find(name);
        if (iter != resources_.end()) {
            return &iter->second;
        } else {
            return nullptr;
        }
    }

private:
    // Use an unordered map to store the resources by name
    std::unordered_map<std::string, Resource> resources_;
};

int main() {
    // Create a resource manager instance
    ResourceManager rm;

    // Read the list of resource types from standard input and add them to the map
    while (true) {
        std::string type;
        std::cin >> type;
        if (type == "") {
            break;
        }
        // Create a new resource with the given name, type, and availability
        Resource resource = {type, 0, 1.0};
        rm.insertResource(resource);
    }

    // Compute the average availability of resources grouped by type
    std::unordered_map<int, double> avgAvailability;
    for (const auto& resource : resources_) {
        int type = resource.first;
        double availability = resource.second.availability;
        if (avgAvailability.find(type) == avgAvailability.end()) {
            avgAvailability[type] = availability;
        } else {
            avgAvailability[type] += availability;
        }
    }
    for (const auto& pair : avgAvailability) {
        std::cout << "Type: " << pair.first << ", Avg Availability: " << pair.second / resources_.size() << "\n";
    }

    // Handle real-time updates on resource types and availability
    while (true) {
        std::string update;
        std::cin >> update;
        if (update == "") {
            break;
        }
        // Update the resource collection with the new information
        // ...
    }

    // Periodically save the resource collection to disk
    while (true) {
        std::this_thread::sleep_for(std::chrono::minutes(5));
        rm.saveResourcesToDisk();
    }

    return 0;
}
