#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <memory>
#include <fstream>

using namespace std;

struct Attack {
    char* name;
    double value;
};

class DynamicAttackSystem {
private:
    vector<unique_ptr<Attack>> attacks;
    unordered_map<string, unique_ptr<Attack>> attackMap;
    size_t capacity = 10000000; // 10 million attacks
    size_t memoryUsage = 0;
    string longestName;

public:
    DynamicAttackSystem() {}

    void insert(const char* name, double value) {
        if (attacks.size() >= capacity || memoryUsage > 50 * 1024 * 1024) { // 50 MB
            return;
        }

        unique_ptr<Attack> attack = make_unique<Attack>();
        attack->name = strdup(name);
        attack->value = value;
        attacks.push_back(move(attack));

        attackMap[string(name)] = move(attacks.back());
        memoryUsage += sizeof(Attack);
    }

    void deleteByName(const char* name) {
        auto it = attackMap.find(string(name));
        if (it != attackMap.end()) {
            attacks.erase(attacks.begin() + it->second->index);
            attackMap.erase(it);
            memoryUsage -= sizeof(Attack);
        }
    }

    double retrieveByName(const char* name) {
        auto it = attackMap.find(string(name));
        if (it != attackMap.end()) {
            return it->second->value;
        } else {
            return -1;
        }
    }

    string longestAttackName() {
        return longestName;
    }

    void updateLongestAttackName(const char* name) {
        auto attack = attackMap.find(string(name));
        if (attack != attackMap.end()) {
            longestName = attack->second->name;
        }
    }
};

void manageDynamicAttackSystem(ifstream& input, ofstream& output) {
    DynamicAttackSystem system;

    string line;
    while (getline(input, line)) {
        istringstream iss(line);
        string command;
        iss >> command;

        if (command == "insert") {
            string name;
            double value;
            iss >> name >> value;
            system.insert(name.c_str(), value);
        } else if (command == "delete") {
            string name;
            iss >> name;
            system.deleteByName(name.c_str());
        } else if (command == "retrieve") {
            string name;
            iss >> name;
            output << system.retrieveByName(name.c_str()) << endl;
        } else if (command == "longest") {
            output << system.longestAttackName() << endl;
        }
    }
}

int main() {
    ifstream input("input.txt");
    ofstream output("output.txt");
    manageDynamicAttackSystem(input, output);
    return 0;
}']

