import os
import time
from concurrent.futures import ThreadPoolExecutor
from contextlib import contextmanager

class ThemeCache:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    @contextmanager
    def lock_cache(self):
        with self.lock:
            yield

    def get_theme(self, theme_name):
        with self.lock_cache():
            return self.cache.get(theme_name)

    def set_theme(self, theme_name, theme):
        with self.lock_cache():
            self.cache[theme_name] = theme

    def recycle_themes(self):
        with self.lock_cache():
            for theme_name in list(self.cache.keys()):
                if time.time() - self.cache[theme_name]['last_access'] > 15 * 60:
                    del self.cache[theme_name]

    def fetch_theme(self, theme_name, external_provider):
        with self.lock_cache():
            if theme_name in self.cache:
                return self.cache[theme_name]
            else:
                try:
                    theme = external_provider.get_theme(theme_name)
                    self.cache[theme_name] = theme
                    return theme
                except Exception as e:
                    print("Error fetching theme {}: {}".format(theme_name, e))
                    return None

    def cleanup_themes(self):
        with self.lock_cache():
            for theme_name in list(self.cache.keys()):
                if time.time() - self.cache[theme_name]['last_access'] > 15 * 60:
                    del self.cache[theme_name]

    def get_checksum(self, theme):
        return hashlib.sha256(theme).hexdigest()

    def verify_theme(self, theme):
        checksum = self.get_checksum(theme)
        if checksum in self.cache:
            return True
        else:
            return False

    def get_cached_theme(self, theme_name, external_provider):
        with self.lock_cache():
            if theme_name in self.cache:
                self.cache[theme_name]['last_access'] = time.time()
                return self.cache[theme_name]
            else:
                try:
                    theme = external_provider.get_theme(theme_name)
                    if self.verify_theme(theme):
                        self.cache[theme_name] = theme
                        self.cache[theme_name]['last_access'] = time.time()
                        return theme
                    else:
                        del self.cache[theme_name]
                except Exception as e:
                    print("Error fetching theme {}: {}".format(theme_name, e))
                    return None

class ThemeProvider:
    def __init__(self, external_provider):
        self.external_provider = external_provider

    def get_theme(self, theme_name):
        try:
            theme = self.external_provider.get_theme(theme_name)
            return theme
        except Exception as e:
            print("Error fetching theme {}: {}".format(theme_name, e))
            return None

class ThemeCacheLogger:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    def log_operation(self, operation, result):
        if result is not None:
            self.logger.info("{}: {}".format(operation, result))
        else:
            self.logger.warning("{} returned no results".format(operation))
