  }

  // Sort records based on their offsets in descending order
  qsort(*records, num_records, sizeof(record), compare_offsets);

  // Compact memory by removing records that fall outside a specified percentile range of the offset values
  long percentile_range = (long) (num_records * 0.1);
  for (int i = 0; i < num_records; i++) {
    if ((*records)[i].offset < percentile_range || (*records)[i].offset > (num_records - percentile_range)) {
      free(&(*records)[i]);
      num_records--;
    }
  }
}

