void handle_request(record** records, int num_records) {
  // Acquire lock for updating the dataset
  pthread_mutex_lock(&dataset_lock);

  // Update or create user account data based on the request structure
  record* curr_record = &(*records)[0];
  if (curr_record->key == -1) {
    // Create new user account
    (*records)[0].key = 1;
    (*records)[0].weight = (double) rand() / RAND_MAX;
    (*records)[0].unit = "C";
    (*records)[0].offset = 0;
  } else {
    // Update existing user account
    curr_record->weight += (double) rand() / RAND_MAX;
    curr_record->unit = "C";
    curr_record->offset = 1;
  }

  // Release lock for updating the dataset
  pthread_mutex_unlock(&dataset_lock);
}

// Define a function to deallocate all allocated memory
void cleanup(record** records) {
  free(*records);
  *records = NULL;
}

int main() {
