    // Sort the records and geometries based on their offset values in descending order
    qsort(recs, num_recs, sizeof(record), compare_records);
    qsort(geos, num_geos, sizeof(geometry), compare_geometries);

    // Compact memory by removing records and geometries that fall outside the specified percentile range of the offset values
    int percentile = 0.1; // Set the percentile range to 10%
    int lower_bound = num_recs * (1 - percentile);
    int upper_bound = num_recs * percentile;
    record* compacted_records = (record*)malloc((upper_bound - lower_bound) * sizeof(record));
    geometry* compacted_geometries = (geometry*)malloc((num_geos - lower_bound) * sizeof(geometry));
    int j = 0;
    for (i = lower_bound; i < upper_bound; i++) {
        compacted_records[j] = recs[i];
        compacted_geometries[j] = geos[i];
        j++;
    }
    free(recs);
    free(geos);
    recs = compacted_records;
    geos = compacted_geometries;

    // Track total memory usage and deallocate all allocated memory when done
    long total_memory_usage = (upper_bound - lower_bound) * sizeof(record) + (num_geos - lower_bound) * sizeof(geometry);
    printf("Total memory usage: %ld bytes\n", total_memory_usage);
    free(recs);
    free(geos);
}

// Define the compare functions for sorting records and geometries based on their offset values
int compare_records(const void* a, const void* b) {
    record* rec1 = (record*)a;
    record* rec2 = (record*)b;
    if (rec1->offset < rec2->offset) return -1;
    else if (rec1->offset > rec2->offset) return 1;
    else return 0;
}
int compare_geometries(const void* a, const void* b) {
    geometry* geo1 = (geometry*)a;
    geometry* geo2 = (geometry*)b;
    if (geo1->offset < geo2->offset) return -1;
    else if (geo1->offset > geo2->offset) return 1;
    else return 0;
}
```
