    int key;
    char buffer[]; // variable length buffer based on the key value
};

// Define a list of records
typedef struct List {
    size_t size;
    size_t capacity;
    struct Record *records;
} List;

// Initialize an empty list
List* list_init() {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;

    list->size = 0;
    list->capacity = 0;
    list->records = NULL;

    return list;
}

// Add a new record to the list
int list_add(List *list, int key, char *buffer) {
    // Check if the list is full
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        struct Record *new_records = realloc(list->records, new_capacity * sizeof(struct Record));
        if (!new_records) return -1; // out of memory
        list->records = new_records;
        list->capacity = new_capacity;
    }

    // Initialize the offset based on the key
    long offset = (long)key * 256 + rand() % 256;

    // Allocate memory for the record
    struct Record *record = malloc(sizeof(struct Record) + key);
    if (!record) return -1; // out of memory

    // Copy the buffer into the record
    memcpy(record->buffer, buffer, key);

    // Set the other fields in the record
    record->offset = offset;
    record->key = key;

    // Add the record to the list
    list->records[list->size++] = *record;

    return 0;
}

// Remove a record from the list by index
void list_remove(List *list, int index) {
    if (index < 0 || index >= list->size) return; // invalid index

    struct Record *record = &list->records[index];

    // Decrement the size of the list
    list->size--;

    // Copy the last record to the removed position
    memmove(record, record + 1, sizeof(struct Record) + (list->size - index));
}

// Update a record in the list by key
void list_update(List *list, int key, char *buffer) {
    for (int i = 0; i < list->size; i++) {
        struct Record *record = &list->records[i];
        if (record->key == key) {
            // Free the old buffer and allocate a new one
            free(record->buffer);
            record->buffer = malloc(key);
            if (!record->buffer) return; // out of memory

            // Copy the new buffer into the record
            memcpy(record->buffer, buffer, key);

            break;
        }
    }
}

// Print a list of records to stdout
void list_print(List *list) {
    for (int i = 0; i < list->size; i++) {
        struct Record *record = &list->records[i];
        printf("Record %d: offset=%ld, key=%d, buffer=%s\n", i, record->offset, record->key, record->buffer);
    }
}

// Free the memory allocated for a list
void list_free(List *list) {
    free(list->records);
    free(list);
}
