#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <assert.h>

// Configuration JSON format:
// {
//     "host": "example.com",
//     "port": 80,
//     "protocol": "http",
//     "timeout": 1000,
//     "logLevel": "info",
//     "maxConnections": 100,
//     "threadPoolSize": 5
// }

// Macros for configuration defaults:
#define DEFAULT_HOST "localhost"
#define DEFAULT_PORT 80
#define DEFAULT_PROTOCOL "http"
#define DEFAULT_TIMEOUT 3000
#define DEFAULT_LOG_LEVEL "info"
#define DEFAULT_MAX_CONNECTIONS 100
#define DEFAULT_THREAD_POOL_SIZE 5

// Struct for network service configuration:
struct NetworkServiceConfig {
    char *host;
    int port;
    char *protocol;
    int timeout;
    char *logLevel;
    int maxConnections;
    int threadPoolSize;
};

// Function to dynamically allocate memory for a network service based on JSON configuration:
struct NetworkServiceConfig* createNetworkService(const char *json) {
    // Parse the JSON string into a struct:
    struct NetworkServiceConfig config = parseJson(json);

    // Validate the config parameters:
    validateConfigParameters(&config);

    // Allocate memory for the network service:
    struct NetworkServiceConfig *service = (struct NetworkServiceConfig*)malloc(sizeof(struct NetworkServiceConfig));
    if (!service) {
        fprintf(stderr, "Error: Failed to allocate memory for network service.\n");
        return NULL;
    }

    // Copy the config parameters into the new struct:
    service->host = strdup(config.host);
    service->port = config.port;
    service->protocol = strdup(config.protocol);
    service->timeout = config.timeout;
    service->logLevel = strdup(config.logLevel);
    service->maxConnections = config.maxConnections;
    service->threadPoolSize = config.threadPoolSize;

    // Initialize offset values:
    int offset = 0;
    for (int i = 0; i < config.maxConnections; ++i) {
        // Allocate memory for the record structures:
        struct NetworkServiceConfig *record = (struct NetworkServiceConfig*)malloc(sizeof(struct NetworkServiceConfig));
        if (!record) {
            fprintf(stderr, "Error: Failed to allocate memory for network service records.\n");
            return NULL;
        }

        // Initialize the record values:
        record->host = strdup(config.host);
        record->port = config.port;
        record->protocol = strdup(config.protocol);
        record->timeout = config.timeout;
        record->logLevel = strdup(config.logLevel);
        record->maxConnections = config.maxConnections;
        record->threadPoolSize = config.threadPoolSize;

        // Add the record to the service:
        service->records[offset] = record;
        offset++;
    }

    return service;
}

// Function to validate the configuration parameters:
void validateConfigParameters(struct NetworkServiceConfig *config) {
    if (!config) {
        fprintf(stderr, "Error: Invalid network service config.\n");
        exit(EXIT_FAILURE);
    }

    // Check for host length exceeding 255 characters:
    if (strlen(config->host) > 255) {
        fprintf(stderr, "Error: Host name is too long. Maximum allowed length is 255 characters.\n");
        exit(EXIT_FAILURE);
    }

    // Check for port value being out of range (1-65535):
    if (!(config->port >= 1 && config->port <= 65535)) {
        fprintf(stderr, "Error: Port value is out of range. Must be between 1 and 65535.\n");
        exit(EXIT_FAILURE);
    }

    // Check for timeout value being non-positive:
    if (config->timeout <= 0) {
        fprintf(stderr, "Error: Timeout value must be a positive integer.\n");
        exit(EXIT_FAILURE);
    }

    // Check for log level value being invalid:
    if (!strcmp(config->logLevel, "info") || !strcmp(config->logLevel, "warn") || !strcmp(config->logLevel, "error")) {
        fprintf(stderr, "Error: Invalid log level. Must be one of 'info', 'warn', or 'error'.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to parse a JSON string into a struct:
struct NetworkServiceConfig parseJson(const char *json) {
