        fprintf(stderr, "Error: failed to allocate %ld bytes\n", total_size);
        return NULL;
    }

    // Initialize the records
    Record* records = (Record*)chunk;
    for (int i = 0; i < num_records; i++) {
        records[i].key = i;
        records[i].offset = i * SLAB_SIZE;
        records[i].measurement = 0.0;
    }

    // Return the allocated records
    return records;
}

// Function to deallocate memory for a set of records
void free_records(Record* records, int num_records) {
    // Lock the mutex before dealing with the records
    pthread_mutex_lock(&lock);

    // Free each record in the allocation
