        char *filepath = malloc(strlen(directory) + strlen(entry->d_name) + 2);
        if (filepath == NULL) {
            fprintf(stderr, "Error allocating memory for file path: %s\n", strerror(errno));
            return 1;
        }
        sprintf(filepath, "%s/%s", directory, entry->d_name);
