            return 1;
        }

        // Append new RX indications structure to array
        rx_indications[num_offsets * num_keys - 1].RX_UE_INFORMATION_TAG = result;
        rx_indications[num_offsets * num_keys - 1].RNTI = (long)result;
        rx_indications[num_offsets * num_keys - 1].CGI = cgi;
    }

    // Return success
    return 0;
