transaction_t *init_transaction(void) {
    transaction_t *tx = malloc(sizeof(transaction_t));
    assert(tx != NULL);
    tx->amount = rand_range(MIN_AMOUNT, MAX_AMOUNT);
    tx->id = malloc(100 * sizeof(char)); // allocate memory for the transaction ID string
