    tx->timestamp = time(NULL); // get the current timestamp in nanoseconds since epoch
    return tx;
}

// function to allocate memory for a new transaction and initialize it with a random amount and ID
transaction_t *allocate_transaction(void) {
    transaction_t *tx = init_transaction();
    size_t mem_size = TRANSACTION_SIZE; // calculate the memory size for the transaction record
    void *mem = malloc(mem_size); // allocate memory for the transaction record
    assert(mem != NULL);
    memcpy(mem, tx, mem_size); // copy the transaction record to the allocated memory
    free(tx); // free the original transaction record
    return (transaction_t *)mem; // return the pointer to the allocated memory
}

// function to deallocate a transaction record and its associated memory
