    // initialize variables and structures
    int total = 0; // total transaction amount
    transaction_t *tx = NULL; // pointer to the current transaction record
    size_t mem_size = MAX_MEMORY_LIMIT * MEMORY_LIMIT_PERCENTAGE / TRANSACTION_SIZE; // maximum memory limit for transactions in bytes
    void *mem = malloc(mem_size); // allocate memory for the transaction records
    assert(mem != NULL);
    int i = 0; // counter for the number of transactions

    // start processing transactions
    while (i < MAX_TRANSACTIONS) {
        tx = allocate_transaction(); // allocate a new transaction record
        update_total(tx, &total); // update the total transaction amount
        i++; // increment the counter for the number of transactions
    }

    // print the total transaction amount
    print_total(total);

    // deallocate memory for the transaction records and exit
    free(mem);
    return 0;
}
