long calculate_offset(int key, unsigned int* identifiers, int identifier_count) {
    // Calculate the total memory needed to store the records
    size_t mem_size = sizeof(Record) * identifier_count;

    // Allocate memory for the records
    Record* records = malloc(mem_size);

    // Check if memory allocation failed
    if (records == NULL) {
        printf("Error: Failed to allocate memory for %d records\n", identifier_count);
        exit(1);
    }

    long offset = 0;

    // Calculate the offset for each record based on the key and precision
    for (int i = 0; i < identifier_count; i++) {
        Record* record = &records[i];
        record->key = identifiers[i];
        record->offset = ((long)record->key * pow(2, 16)) / pow(identifiers[i], 16);
        offset += record->offset;
    }

    return offset;
}

