    // Calculate the total size of memory needed to store the records
    size_t mem_size = sizeof(Record) * num_records;

    // Allocate memory for the records
    Record* records = malloc(mem_size);

    // Check if memory allocation failed
    if (records == NULL) {
        printf("Error: Failed to allocate memory for %d records\n", num_records);
        exit(1);
    }

    long offset = calculate_offset(0, identifiers, identifier_count);

    // Calculate the offsets for each record based on the input parameters
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        record->key = i + offset;
        record->offset = calculate_offset(record->key, identifiers, identifier_count);
    }

    return records;
}
