```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Structure to represent each record
typedef struct Record {
    size_t offset;
    int key;
    int* value;
} Record;

// Function to dynamically allocate memory for a flexible number of records
void allocRecords(size_t num_records, Record** records) {
    // Validate input parameters
    assert(num_records > 0 && records != NULL);

    // Determine the total memory required for the specified number of records
    size_t total_memory = sizeof(Record) * num_records;

    // Check if the total memory required exceeds system limits
    if (total_memory > SIZE_MAX) {
        return NULL;
    }

    // Allocate memory for the records
    void* mem = malloc(total_memory);
    if (!mem) {
        return NULL;
    }

    // Initialize each record's offset and key within predefined ranges
    for (size_t i = 0; i < num_records; i++) {
        Record* record = (Record*)((char*)mem + i * sizeof(Record));
        record->offset = random();
        record->key = random() % 1000;
    }

    // Allocate and initialize the integer value pointed to by each record's pointer within a specified range
    for (size_t i = 0; i < num_records; i++) {
        Record* record = (Record*)((char*)mem + i * sizeof(Record));
        int val = random() % 1000;
        record->value = malloc(sizeof(int));
        if (!record->value) {
            free(mem);
            return NULL;
        }
        *record->value = val;
    }

    // Provide a robust mechanism to handle memory deallocation for all allocated records
    struct RecordDeallocator {
        Record* record;
        struct RecordDeallocator* next;
    };
    struct RecordDeallocator* head = NULL;
    struct RecordDeallocator* tail = NULL;
    for (size_t i = 0; i < num_records; i++) {
        Record* record = (Record*)((char*)mem + i * sizeof(Record));
        if (!record->value) {
            continue;
        }
        struct RecordDeallocator* deallocator = malloc(sizeof(struct RecordDeallocator));
        if (!deallocator) {
            free(mem);
            return NULL;
        }
        deallocator->record = record;
        deallocator->next = NULL;
        if (tail) {
            tail->next = deallocator;
        } else {
            head = deallocator;
        }
        tail = deallocator;
