// Define function to handle memory deallocation with concurrency support
void dynDeallocateConcurrency(void *ptrArrayPtr) {
  // Get the number of pointers in the array
  size_t ptrSize = sizeof(void *);
  size_t numPtrs = ((char *)ptrArrayPtr - (char *)NULL) / ptrSize;

  // Create an array of locks to protect each record's string value while we deallocate it
  pthread_mutex_t *locks = malloc(sizeof(pthread_mutex_t) * numPtrs);
