#include <time.h>

struct FILE_SYSTEM_INFO {
    char *file_path;
    time_t modification_time;
    int access_permissions;
};

struct FILE_SYSTEM_ARRAY {
    struct FILE_SYSTEM_INFO **array;
    size_t size;
    pthread_mutex_t mutex;
};

void init_file_system_info(struct FILE_SYSTEM_INFO *info, const char *file_path) {
    info->file_path = strdup(file_path);
    info->modification_time = 0;
    info->access_permissions = 0;
}

void init_file_system_array(struct FILE_SYSTEM_ARRAY *array) {
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void cleanup_file_system_info(struct FILE_SYSTEM_INFO *info) {
    free(info->file_path);
    info->modification_time = 0;
    info->access_permissions = 0;
}

void cleanup_file_system_array(struct FILE_SYSTEM_ARRAY *array) {
    for (size_t i = 0; i < array->size; ++i) {
        cleanup_file_system_info(&array->array[i]);
    }
    free(array->array);
}

int append_to_file_system_array(struct FILE_SYSTEM_ARRAY *array, const char *file_path) {
    struct stat stat_buf;
    int ret = 0;

    if (stat(file_path, &stat_buf) != 0) {
        return -1;
    }

    pthread_mutex_lock(&array->mutex);

    // Grow the array if necessary
    if (array->size == 0 || array->size < array->size + 1) {
        size_t new_size = array->size * 2;
        struct FILE_SYSTEM_INFO **new_array = realloc(array->array, sizeof(struct FILE_SYSTEM_INFO *) * new_size);
        if (new_array == NULL) {
            ret = -1;
        } else {
            array->array = new_array;
            array->size = new_size;
        }
    }

    // If there was no error, add the new element to the array
    if (ret == 0) {
        struct FILE_SYSTEM_INFO *new_info = &array->array[array->size - 1];
        init_file_system_info(new_info, file_path);
        array->size++;
    }

    pthread_mutex_unlock(&array->mutex);

    return ret;
}

void clear_file_system_array(struct FILE_SYSTEM_ARRAY *array) {
    for (size_t i = 0; i < array->size; ++i) {
        cleanup_file_system_info(&array->array[i]);
    }
    array->size = 0;
}
