    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
    }
    int *recordKeys = malloc(sizeof(int) * numRecords);
    if (recordKeys == NULL) {
        free(records);
        fprintf(stderr, "Error: Failed to allocate memory for record keys\n");
        return NULL;
    }
    long *recordOffsets = malloc(sizeof(long) * numRecords);
    if (recordOffsets == NULL) {
        free(records);
        free(recordKeys);
        fprintf(stderr, "Error: Failed to allocate memory for record offsets\n");
        return NULL;
    }

    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = malloc(sizeof(int));
        if (records[i].key == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record key\n");
            return NULL;
        }
        *(records[i].key) = rand() % 100 + 1;

        records[i].offset = malloc(sizeof(long));
        if (records[i].offset == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record offset\n");
            return NULL;
        }
        *(records[i].offset) = rand() % 1000 + 1;
    }

    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        recordKeys[i] = rand() % 200 - 100;
        recordOffsets[i] = rand() % 1000 + 1;
    }

    // Check if there are any duplicate keys
    for (int i = 0; i < numRecords; i++) {
        for (int j = i + 1; j < numRecords; j++) {
            if (*(records[i].key) == *(records[j].key)) {
                fprintf(stderr, "Error: Duplicate key found\n");
                return NULL;
            }
        }
    }

    // Return the array of records
    return records;
}

// Function to deallocate memory for the arrays
void deallocateMemory(Record *records) {
    if (records == NULL) {
        fprintf(stderr, "Error: Records are not allocated\n");
        return;
    }

    // Deallocate the memory for each record
    for (int i = 0; i < numRecords; i++) {
        free(records[i].key);
        records[i].key = NULL;
        free(records[i].offset);
        records[i].offset = NULL;
    }

    // Deallocate the memory for the arrays
    free(records);
    records = NULL;
}
