 * The function must ensure that the total memory usage does not exceed a predefined limit to prevent resource exhaustion, and it should validate input parameters to ensure they are within acceptable ranges.
 */
void init_data_structures(int num_records, int max_offset, int max_key, double max_weight, size_t max_memory) {
    // Validate input parameters
    if (num_records <= 0 || max_offset <= 0 || max_key <= 0 || max_weight < 0.0 || max_memory == 0) {
        LOG("Invalid input parameters");
        return;
    }

    // Calculate the total memory usage for the data structures
    size_t total_mem = (num_records * sizeof(record_t)) + (3 * num_records * sizeof(int)) + (3 * num_records * sizeof(double));
    if (total_mem > max_memory) {
        LOG("Total memory usage exceeds the maximum allowed");
        return;
    }

    // Allocate memory for the record array
    record_t* records = my_malloc(num_records * sizeof(record_t));
    if (records == NULL) {
        LOG("Failed to allocate memory for record array");
        return;
    }

    // Allocate memory for the offset, key, and weight arrays
    int* offsets = my_malloc(num_records * sizeof(int));
    if (offsets == NULL) {
        LOG("Failed to allocate memory for offset array");
        return;
    }
    int* keys = my_malloc(num_records * sizeof(int));
    if (keys == NULL) {
        LOG("Failed to allocate memory for key array");
        return;
    }
    double* weights = my_malloc(num_records * sizeof(double));
    if (weights == NULL) {
        LOG("Failed to allocate memory for weight array");
        return;
    }

    // Initialize the record array, offset, key, and weight arrays, and set the initial values
    for (int i = 0; i < num_records; i++) {
        records[i].offset = my_rand(max_offset);
        records[i].key = my_rand(max_key);
        records[i].weight = my_random_double(max_weight);

        offsets[i] = records[i].offset;
        keys[i] = records[i].key;
        weights[i] = records[i].weight;
    }

    // Perform operations where, for each record, its value is incremented based on a weighted probability distribution derived from the corresponding key, offset, and weight.
    for (int i = 0; i < num_records; i++) {
        int idx = my_rand(num_records - i);
        if (idx != i) {
            record_t temp = records[i];
            records[i] = records[idx];
            records[idx] = temp;

            int temp2 = offsets[i];
            offsets[i] = offsets[idx];
            offsets[idx] = temp2;

            int temp3 = keys[i];
            keys[i] = keys[idx];
            keys[idx] = temp3;

            double temp4 = weights[i];
            weights[i] = weights[idx];
            weights[idx] = temp4;
        }
    }

    // Free the memory allocated for the record array, offset, key, and weight arrays.
    my_free(records);
    my_free(offsets);
    my_free(keys);
    my_free(weights);
}
