// Struct to represent a measurement record
struct measurement {
    float reading;
    char quality_flag;
};

// Function to initialize the memory for the sensor datasets
void init_memory(int num_datasets, int num_entries) {
    // Allocate memory for each dataset
    for (int i = 0; i < num_datasets; i++) {
        datasets[i] = malloc(num_entries * sizeof(struct measurement));
        if (!datasets[i]) {
            printf("Error: failed to allocate memory for dataset %d\n", i);
            return;
        }
    }
}

// Function to add a new measurement record to the specified dataset
void add_record(int dataset, struct measurement record) {
    // Check if the dataset is within bounds
    if (dataset < 0 || dataset >= num_datasets) {
        printf("Error: invalid dataset index %d\n", dataset);
        return;
    }

    // Add the record to the end of the dataset
    datasets[dataset][num_entries++] = record;
}

// Function to get the measurement record from the specified dataset and entry
struct measurement get_record(int dataset, int entry) {
    // Check if the dataset and entry are within bounds
    if (dataset < 0 || dataset >= num_datasets || entry < 0 || entry >= num_entries) {
        printf("Error: invalid index %d for dataset %d\n", entry, dataset);
        return;
    }

    // Return the record at the specified entry
    return datasets[dataset][entry];
}

// Function to serialize the sensor datasets into JSON format
void serialize_datasets(char* json) {
    int i, j;
    struct measurement* data = malloc(num_datasets * sizeof(struct measurement));
    char* p = json;
    if (!data) {
        printf("Error: failed to allocate memory for JSON string\n");
        return;
    }

    // Add the header to the JSON string
    p += sprintf(p, "{\"datasets\": [");

    // Iterate over each dataset and add its records to the JSON string
    for (i = 0; i < num_datasets; i++) {
        data[i] = datasets[i];
        p += sprintf(p, "{ \"dataset\": %d, \"records\": [", i);
        for (j = 0; j < num_entries; j++) {
            struct measurement record = data[i][j];
            p += sprintf(p, "{\"reading\": %f, \"quality_flag\": \"%c\"}", record.reading, record.quality_flag);
        }
        p += sprintf(p, "]},");
    }

    // Add the closing bracket to the JSON string
    p--;
    *p = ']';

    // Free the temporary data array
    free(data);
}

// Function to deserialize a JSON-formatted string into sensor datasets
void deserialize_datasets(char* json) {
    int i, j;
    struct measurement* data = malloc(num_datasets * sizeof(struct measurement));
    if (!data) {
        printf("Error: failed to allocate memory for JSON string\n");
        return;
    }

    // Iterate over each dataset in the JSON string and add its records to the datasets array
    json = strtok(json, "{\"datasets\": [");
    while (json) {
        int dataset_index = atoi(strtok(json, ","));
        data[dataset_index] = malloc(num_entries * sizeof(struct measurement));
        if (!data[dataset_index]) {
            printf("Error: failed to allocate memory for dataset %d\n", dataset_index);
            return;
        }

        json = strtok(NULL, "{\"records\": [");
        while (json) {
            int entry_index = atoi(strtok(json, ","));
            struct measurement record = {atof(strtok(json, ",\"quality_flag\"")), *strtok(json, "}]}");
            data[dataset_index][entry_index] = record;
        }
    }

    // Free the temporary data array
    free(data);
}
