// Custom hash table implementation with dynamic resizing
struct HashTable {
    struct Entry* entries;  // Array of hash table entries
    int capacity;          // Current capacity of the hash table
    int size;              // Current number of elements in the hash table
};

struct Entry {
    int key;      // Key value for the entry
    int value;    // Value associated with the key
    struct Entry* next;  // Pointer to the next entry in the bucket chain
};

// Memory allocation function for dynamic arrays
void* allocateMemory(int size, int type) {
    void* ptr = NULL;
    if (type == LONG_OFFSET) {
        ptr = malloc(size * sizeof(long));
    } else if (type == INT_KEY) {
        ptr = malloc(size * sizeof(int));
    }
    return ptr;
}

// Memory deallocation function for dynamic arrays
void deallocateMemory(void* ptr, int size, int type) {
    if (ptr != NULL) {
        if (type == LONG_OFFSET) {
            free(ptr);
        } else if (type == INT_KEY) {
            free(ptr);
        }
    }
}

// Initializes the memory management system
void initializeMemoryManagementSystem() {
    // Initialize the hash table capacity to 1024 entries
    struct HashTable* hashTable = malloc(sizeof(struct HashTable));
    hashTable->capacity = 1024;
    hashTable->size = 0;
    hashTable->entries = malloc(hashTable->capacity * sizeof(struct Entry));
}

// Deallocates the memory management system
void deallocateMemoryManagementSystem() {
    // Free all allocated memory for the hash table and its entries
    free(hashTable);
}

// Adds a new entry to the hash table with the given key and value
void addEntryToHashTable(int key, int value) {
    struct Entry* newEntry = malloc(sizeof(struct Entry));
    newEntry->key = key;
    newEntry->value = value;
    // Check if there is enough space in the hash table to add a new entry
    if (hashTable->size < hashTable->capacity) {
        // Add the new entry to the hash table and increment the size counter
        newEntry->next = NULL;
        int index = hash(key);
        struct Entry* currentEntry = hashTable->entries[index];
        while (currentEntry != NULL && currentEntry->next != NULL) {
            currentEntry = currentEntry->next;
        }
        if (currentEntry == NULL) {
            hashTable->entries[index] = newEntry;
        } else {
            currentEntry->next = newEntry;
        }
        hashTable->size++;
    } else {
        // If the hash table is full, dynamically resize it by 50%
        int newCapacity = hashTable->capacity * 3 / 2;
        struct Entry* newEntries = malloc(newCapacity * sizeof(struct Entry));
        for (int i = 0; i < newCapacity; i++) {
            newEntries[i] = NULL;
        }
        int index = hash(key);
        struct Entry* currentEntry = hashTable->entries[index];
        while (currentEntry != NULL) {
            int newIndex = hash(currentEntry->key);
            newEntries[newIndex] = currentEntry;
            currentEntry = currentEntry->next;
        }
        free(hashTable->entries);
        hashTable->entries = newEntries;
        hashTable->capacity = newCapacity;
    }
}

// Gets the value associated with the given key in the hash table
int getValueFromHashTable(int key) {
    int index = hash(key);
    struct Entry* currentEntry = hashTable->entries[index];
    while (currentEntry != NULL && currentEntry->next != NULL) {
        if (currentEntry->key == key) {
            return currentEntry->value;
        }
        currentEntry = currentEntry->next;
    }
    return -1;
}

// Deletes the entry with the given key from the hash table
void deleteEntryFromHashTable(int key) {
    int index = hash(key);
    struct Entry* currentEntry = hashTable->entries[index];
    if (currentEntry != NULL && currentEntry->next != NULL) {
        while (currentEntry->next != NULL && currentEntry->next->key != key) {
            currentEntry = currentEntry->next;
        }
        if (currentEntry->next != NULL) {
            struct Entry* entryToDelete = currentEntry->next;
            currentEntry->next = entryToDelete->next;
            free(entryToDelete);
        } else {
            hashTable->size--;
        }
    } else if (currentEntry != NULL && currentEntry->key == key) {
        free(currentEntry);
        hashTable->entries[index] = NULL;
    }
}

// Implements the memory management system for the given programming task
