    *keys = (int *)malloc(num_keys * sizeof(int));
    *values = (double *)malloc(num_keys * sizeof(double));

    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        (*keys)[i] = rand() % 100;
        (*values)[i] = ((double)rand()) / RAND_MAX * 100;
    }

    // Allocate memory for the data structures
    *data = (struct data *)malloc(num_keys * sizeof(struct data));

    // Initialize the data structures with the random values
    for (int i = 0; i < num_keys; i++) {
        (*data)[i].offset = i;
        (*data)[i].key = (*keys)[i];
        (*data)[i].value = (*values)[i];
    }

    // Verify the integrity of the data
    for (int i = 0; i < num_keys; i++) {
        if ((*data)[i].key == (*data)[i + 1].key) {
            printf("Error: duplicate key found\n");
            exit(1);
        }
    }
}

// Function to free the allocated memory
void free_memory(int *keys, double *values, struct data **data) {
    free(*keys);
    free(*values);
    free(*data);
}
