#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the status array for active/inactive records
enum Status { INACTIVE, ACTIVE };

// Define the hash table structure
struct HashTable {
    int size;
    int count;
    pthread_mutex_t* mutexes;
    Record** buckets;
};

// Function to allocate and initialize memory for records, keys, offsets, and status array
void init(HashTable* ht, int numRecords) {
    // Initialize the size of the hash table
    ht->size = numRecords;

    // Allocate and initialize memory for the record structs
    ht->buckets = malloc(sizeof(Record*) * numRecords);
    memset(ht->buckets, 0, sizeof(Record*) * numRecords);

    // Initialize the status array to INACTIVE
    ht->status = malloc(sizeof(enum Status) * numRecords);
    memset(ht->status, INACTIVE, sizeof(enum Status) * numRecords);

    // Initialize the mutexes for each bucket
    ht->mutexes = malloc(sizeof(pthread_mutex_t) * numRecords);
    for (int i = 0; i < numRecords; i++) {
        pthread_mutex_init(&ht->mutexes[i], NULL);
    }
}

// Function to insert a new record into the hash table
void insert(HashTable* ht, int key, long offset) {
    // Obtain a lock on the bucket index
    pthread_mutex_lock(&ht->mutexes[key % ht->size]);

    // Check if the key already exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->buckets[i] != NULL && ht->buckets[i]->key == key) {
            pthread_mutex_unlock(&ht->mutexes[key % ht->size]);
            return;
        }
    }

    // Insert the new record into the hash table
    int index = key % ht->size;
    Record* rec = malloc(sizeof(Record));
    rec->key = key;
    rec->offset = offset;
    ht->buckets[index] = rec;

    // Update the status of the record to ACTIVE
    ht->status[index] = ACTIVE;

    pthread_mutex_unlock(&ht->mutexes[key % ht->size]);
}

// Function to update an existing record in the hash table
void update(HashTable* ht, int key, long offset) {
    // Obtain a lock on the bucket index
    pthread_mutex_lock(&ht->mutexes[key % ht->size]);

    // Check if the key exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->buckets[i] != NULL && ht->buckets[i]->key == key) {
            ht->buckets[i]->offset = offset;
            pthread_mutex_unlock(&ht->mutexes[key % ht->size]);
            return;
        }
    }

    // Insert the new record into the hash table if it doesn't exist
    insert(ht, key, offset);
}

// Function to lookup a record in the hash table
Record* lookup(HashTable* ht, int key) {
    pthread_mutex_lock(&ht->mutexes[key % ht->size]);

    // Search for the record in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->buckets[i] != NULL && ht->buckets[i]->key == key) {
            pthread_mutex_unlock(&ht->mutexes[key % ht->size]);
            return ht->buckets[i];
        }
    }

    // Return null if the record is not found
    pthread_mutex_unlock(&ht->mutexes[key % ht->size]);
    return NULL;
}

// Function to delete an existing record from the hash table
void delete(HashTable* ht, int key) {
    // Obtain a lock on the bucket index
    pthread_mutex_lock(&ht->mutexes[key % ht->size]);

    // Search for the record in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->buckets[i] != NULL && ht->buckets[i]->key == key) {
            free(ht->buckets[i]);
            ht->buckets[i] = NULL;
            break;
        }
    }

    // Update the status of the record to INACTIVE
    ht->status[key % ht->size] = INACTIVE;

    pthread_mutex_unlock(&ht->mutexes[key % ht->size]);
}

// Function to clean up all allocated resources when the function completes execution
void destroy(HashTable* ht) {
    // Clean up the buckets and status array
    for (int i = 0; i < ht->size; i++) {
        if (ht->buckets[i] != NULL) free(ht->buckets[i]);
        ht->status[i] = INACTIVE;
    }
    free(ht->buckets);
    free(ht->status);

    // Clean up the mutexes
    for (int i = 0; i < ht->size; i++) {
        pthread_mutex_destroy(&ht->mutexes[i]);
    }
    free(ht->mutexes);
}
```
This code implements a thread-safe hash table for managing records in a multi-threaded environment. It uses a mutex for each bucket to prevent data corruption during concurrent operations, and it utilizes a hash table for efficient key-based lookups and duplicate key detection. The hash table is implemented using an array of record pointers and a status array indicating the active/inactive state of each record.

The `init` function initializes the hash table with the given number of records and allocates memory for the record structs, keys, offsets, and status array. It also initializes the mutexes for each bucket.

The `insert` function inserts a new record into the hash table if it doesn't exist. It first checks if the key already exists in the hash table, and if so, returns without inserting anything. Otherwise, it searches for an empty slot in the hash table, initializes a new record with the given key and offset, and updates the status of the record to ACTIVE.

The `update` function updates an existing record in the hash table. It first checks if the key exists in the hash table, and if so, updates the offset of the record. Otherwise, it inserts a new record with the given key and offset.

The `lookup` function looks up a record in the hash table by its key. It first obtains a lock on the bucket index, searches for the record in the hash table, and returns the record if it's found. If the record is not found, it returns null.

The `delete` function deletes an existing record from the hash table. It first obtains a lock on the bucket index, searches for the record in the hash table, and frees the memory allocated to the record.

Finally, the `destroy` function cleans up all allocated resources when the function completes execution. It frees the memory allocated to the buckets, status array, and mutexes, and destroys each mutex."]

