    // Initialize the log buffer with a default size
    logBuffer.bufferSize = MAX_LOG_BUFFER_SIZE;
    logBuffer.buffer = (char*)malloc(logBuffer.bufferSize);

    // Set up a mutex to synchronize access to the log buffer
    pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutexattr_t logAttr;
    pthread_mutexattr_settype(&logAttr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&logMutex, &logAttr);

    // Log some messages
    logMessage(&logBuffer, "Hello, world!");
    logMessage(&logBuffer, "This is a test message.");
    logMessage(&logBuffer, "Error: %s", strerror(errno));

    // Flush the buffer
    flushBuffer(&logBuffer);

    return 0;
}

void logMessage(LogBuffer* buffer, const char* format, ...) {
    pthread_mutex_lock(&logMutex);

    va_list args;
    va_start(args, format);
    vsnprintf(buffer->buffer + buffer->currentSize, buffer->bufferSize - buffer->currentSize, format, args);
    va_end(args);

    // Check if the buffer is full and needs to be resized
    if (buffer->currentSize >= MAX_LOG_BUFFER_SIZE) {
        resizeBuffer(buffer);
    }

    pthread_mutex_unlock(&logMutex);
}

bool flushBuffer(LogBuffer* buffer) {
    pthread_mutex_lock(&logMutex);

    // Check if the buffer needs to be compressed
    if (buffer->currentSize >= COMPRESSION_THRESHOLD) {
        compressBuffer(buffer);
    }

    // Rotate the log file if necessary
    rotateBuffer(buffer);

    pthread_mutex_unlock(&logMutex);
}

void resizeBuffer(LogBuffer* buffer) {
    buffer->bufferSize *= 2;
    char* newBuffer = (char*)realloc(buffer->buffer, buffer->bufferSize);
    if (newBuffer == NULL) {
        // Handle allocation failure
    } else {
        buffer->buffer = newBuffer;
    }
}

