    public static class RecordProcessor
    {
        private const int MaxRecordCount = 10_000; // Maximum number of records to process at once
        private const int RandomSeed = 42; // Seed for the random number generator

        public static async Task<IDataReader> ProcessAndShuffleRecords(List<int> keys, List<int> offsets, SqlConnection connection, string commandText)
        {
            if (keys.Count != offsets.Count)
                throw new ArgumentException("Keys and offsets must have the same length.");

            // Initialize records using provided sets of keys and offsets
            var records = Enumerable.Range(0, keys.Count).Select(i => new Record { Key = keys[i], Offset = offsets[i] }).ToList();

            // Shuffle the records in place randomly while maintaining their association with the corresponding key and offset
            var rng = new Random(RandomSeed);
            for (int i = 0; i < records.Count; i++)
            {
                int randomIndex = rng.Next(i, records.Count);
                records[i].Offset = records[randomIndex].Offset;
                records[i].Key = records[randomIndex].Key;
            }

            // Construct parameterized SQL command using the provided keys and offsets
            var command = new SqlCommand(commandText, connection) { CommandType = CommandType.StoredProcedure };
            for (int i = 0; i < records.Count; i++)
                command.Parameters.AddWithValue($"Key{i + 1}", records[i].Key);
            for (int i = 0; i < records.Count; i++)
                command.Parameters.AddWithValue($"Offset{i + 1}", records[i].Offset);

            // Execute the SQL command and return an IDataReader
            var dataReader = await command.ExecuteReaderAsync();

            // Handle memory allocation failures gracefully by returning an appropriate error code without resource leaks
            if (dataReader == null)
                throw new Exception("Failed to execute SQL command.");

            return dataReader;
        }
    }

    public class Record
    {
        public int Key { get; set; }
        public int Offset { get; set; }
    }
}
