// Custom configuration structure for initialize_records()
typedef struct {
    int max_records;   // Maximum number of records to initialize
    long seed;        // Seed value for the custom pseudo-random number generator
    int verbosity;    // Verbosity level for logging each record's initialization process
} init_config_t;

// Record structure for storing data
typedef struct {
    int key;          // Key value of the record
    long offset;     // Offset value of the record
    int val;         // Integer value of the record
} record_t;

// Initialize a buffer for storing intermediate results
#define INIT_BUFFER_SIZE 1024
static char init_buffer[INIT_BUFFER_SIZE];

// Initialize an array of long values
long* initialize_longs(int max_records) {
    long* long_array = malloc(max_records * sizeof(long));
    if (long_array == NULL) {
        printf("Error: Failed to allocate memory for long array.\n");
        return NULL;
    }
    for (int i = 0; i < max_records; i++) {
        long_array[i] = i + 1; // Initialize each element with a unique value
    }
    return long_array;
}

// Initialize an array of int keys
int* initialize_keys(int max_records) {
    int* key_array = malloc(max_records * sizeof(int));
    if (key_array == NULL) {
        printf("Error: Failed to allocate memory for key array.\n");
        return NULL;
    }
    for (int i = 0; i < max_records; i++) {
        key_array[i] = i + 1; // Initialize each element with a unique value
    }
    return key_array;
}

// Initialize an array of record structures
record_t* initialize_records(int max_records, init_config_t config) {
    record_t* record_array = malloc(max_records * sizeof(record_t));
    if (record_array == NULL) {
        printf("Error: Failed to allocate memory for record array.\n");
        return NULL;
    }
    // Generate random values within the specified range for each element
    srand(config.seed);
    for (int i = 0; i < max_records; i++) {
        record_array[i].key = config.verbosity >= 1 ? printf("Initializing key %d...", i + 1) : 0;
        record_array[i].offset = i + 1; // Initialize each element with a unique offset value
        record_array[i].val = rand() % (config.max_records - i); // Generate random integer value within the specified range
    }
    return record_array;
}

// Free memory allocated for an array of long values
void free_longs(long* long_array) {
    if (long_array != NULL) {
        free(long_array);
        long_array = NULL;
    }
}

// Free memory allocated for an array of int keys
void free_keys(int* key_array) {
    if (key_array != NULL) {
        free(key_array);
        key_array = NULL;
    }
}

// Free memory allocated for an array of record structures
void free_records(record_t* record_array) {
    if (record_array != NULL) {
        free(record_array);
        record_array = NULL;
    }
}
