long init_random(int seed) {
  srand(seed);
  return rand() % (2 * MAX_UNIQUE_VALUES + 1) - MAX_UNIQUE_VALUES;
}

// Allocate memory for an array of long integers, and initialize each element to a random value between -1000 and 1000
