Record *allocate_records(int size) {
  Record *records = malloc(sizeof(Record) * size);
  if (records == NULL) {
    perror("Failed to allocate memory for records");
    exit(EXIT_FAILURE);
  }
  for (int i = 0; i < size; i++) {
    records[i].values = allocate_values(VALUE_ARRAY_SIZE);
    records[i].key = i;
    records[i].timestamp = time(NULL);
  }
  return records;
}

// Free the memory allocated for a record array and its elements
void free_records(Record *records, int size) {
  if (records == NULL || size <= 0) {
    perror("Failed to free memory for records");
    exit(EXIT_FAILURE);
  }
  for (int i = 0; i < size; i++) {
    free(records[i].values);
  }
  free(records);
}

// Add a new user profile to the repository, and return the ID of the newly added record
int add_user(Record *records, int size, long value) {
  if (size >= MAX_USERS || records == NULL) {
    perror("Failed to add user: Repository full");
    exit(EXIT_FAILURE);
  }
  Record *record = &records[size];
  record->values = malloc(sizeof(long) * VALUE_ARRAY_SIZE);
  if (record->values == NULL) {
    perror("Failed to allocate memory for new record");
    exit(EXIT_FAILURE);
  }
  record->key = size;
  record->timestamp = time(NULL);
  records[size].values[0] = value;
  return size++;
}

// Remove a user profile from the repository, and update the usage statistics accordingly
void remove_user(Record *records, int *size, long value) {
  if (*size <= 0 || records == NULL) {
    perror("Failed to remove user: Repository empty");
    exit(EXIT_FAILURE);
  }
  for (int i = 0; i < *size; i++) {
    if (records[i].values[0] == value) {
      records[i].timestamp = time(NULL);
      break;
    }
  }
}

// Update a user profile in the repository, and return the updated record
Record *update_user(Record *records, int size, long old_value, long new_value) {
  if (size <= 0 || records == NULL) {
    perror("Failed to update user: Repository empty");
    exit(EXIT_FAILURE);
  }
  for (int i = 0; i < size; i++) {
    if (records[i].values[0] == old_value) {
      records[i].values[0] = new_value;
      return &records[i];
    }
  }
}

// Export the current state of the record array to a file in a specified format
void export_records(Record *records, int size) {
  FILE *file = fopen(RECORD_EXPORT_FILE, "w");
  if (file == NULL) {
    perror("Failed to open record export file");
    exit(EXIT_FAILURE);
  }
  for (int i = 0; i < size; i++) {
    fprintf(file, RECORD_EXPORT_FORMAT, records[i].key, records[i].values[0], records[i].timestamp);
  }
  fclose(file);
}

