struct EnvConfig {
    map<string, string> values;
};

// Cache entry structure
struct CacheEntry {
    string key;
    EnvConfig config;
    chrono::system_clock::time_point lastUpdated;
};

// Configuration manager class
class ConfigManager {
public:
    // Add configuration file to the system
    void addFile(const string& path, ConfigFileFormat format);

    // Update cache with latest configuration values for given environment
    EnvConfig getEnvConfig(const string& env) const;

private:
    // Configuration files map
    map<string, ConfigFile> configFiles;

    // Cache of environment-specific configurations
    map<string, CacheEntry> cache;

    // Mutex for thread safety
    mutex mutex;

    // Condition variable for cache invalidation
    condition_variable cv;

