struct Record {
  int key;
  long offset;
  bool active;
};

class DynamicCollection {
public:
  DynamicCollection(int maxSize, int maxConcurrency) : maxSize_(maxSize), maxConcurrency_(maxConcurrency) {}

  // Insert a new record with the given key and offset. Returns true if successful, false otherwise.
  bool insert(int key, long offset) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (records_.size() >= maxSize_) {
      return false;
    }
    records_.emplace_back(Record{key, offset, true});
    hashTable_.insert({key, &records_.back()});
    return true;
  }

  // Update the offset value for the record with the given key. Returns true if successful, false otherwise.
  bool update(int key, long offset) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = hashTable_.find(key);
    if (it == hashTable_.end()) {
      return false;
    }
    (*it).second->offset = offset;
    return true;
  }

  // Look up the record with the given key. Returns a pointer to the Record struct, or nullptr if not found.
  Record* lookup(int key) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = hashTable_.find(key);
    if (it == hashTable_.end()) {
      return nullptr;
    }
    return (*it).second;
  }

  // Remove the record with the given key. Returns true if successful, false otherwise.
  bool remove(int key) {
    std::unique_lock<std::mutex> lock(mutex_);
    auto it = hashTable_.find(key);
    if (it == hashTable_.end()) {
      return false;
    }
    (*it).second->active = false;
    return true;
  }

  // Clean up all allocated resources when the function completes execution.
  void cleanup() {
    for (auto it = records_.begin(); it != records_.end(); ++it) {
      if ((*it).active) {
        hashTable_.erase((*it).key);
      }
    }
    records_.clear();
    hashTable_.clear();
  }

private:
  int maxSize_;
  int maxConcurrency_;
  std::vector<Record> records_;
  std::unordered_map<int, Record*> hashTable_;
  std::mutex mutex_;
};
