// Global variables for managing memory and synchronizing access
static void *memory = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static metadata_t offset_metadata;
static metadata_t key_metadata;
static metadata_t record_metadata;

// Function to allocate memory for the data structures
void *allocate_memory(size_t num_records, size_t record_size) {
    // Calculate the total size of the data structures
    size_t total_size = (num_records * record_size + sizeof(struct metadata));

    // Allocate memory for the data structures and store the pointer in a global variable
    memory = malloc(total_size);
    assert(memory != NULL);

    // Initialize the metadata for each data structure
    offset_metadata.num_records = 0;
    offset_metadata.total_size = total_size - sizeof(struct metadata);
    key_metadata.num_records = 0;
    key_metadata.total_size = total_size - sizeof(struct metadata);
    record_metadata.num_records = num_records;
    record_metadata.total_size = total_size - sizeof(struct metadata);

    // Initialize the arrays for each data structure
    long *offsets = memory + sizeof(struct metadata);
    int *keys = memory + sizeof(struct metadata) + offset_metadata.total_size;
    struct record *records = memory + sizeof(struct metadata) + offset_metadata.total_size + key_metadata.total_size;

    // Initialize the offsets, keys, and records with default values
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i].value = 0;
        records[i].key = &keys[i];
        records[i].offset = &offsets[i];
    }

    return memory;
}

// Function to deallocate memory for the data structures
void deallocate_memory() {
    // Acquire a lock on the mutex before modifying global variables
    pthread_mutex_lock(&mutex);

    // Deallocate the memory allocated for the data structures
    free(memory);

    // Reset the metadata for each data structure to zero
    offset_metadata.num_records = 0;
    offset_metadata.total_size = 0;
    key_metadata.num_records = 0;
    key_metadata.total_size = 0;
    record_metadata.num_records = 0;
    record_metadata.total_size = 0;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to add a new record to the data structures
void add_record(int value, int *key) {
    // Acquire a lock on the mutex before modifying global variables
    pthread_mutex_lock(&mutex);

    // Increment the number of records in each data structure
    offset_metadata.num_records++;
    key_metadata.num_records++;
    record_metadata.num_records++;

    // Calculate the total size of each data structure
    offset_metadata.total_size += sizeof(long);
    key_metadata.total_size += sizeof(int);
    record_metadata.total_size += sizeof(struct record);

    // Reallocate memory for each data structure if necessary
    long *offsets = memory + sizeof(struct metadata);
    int *keys = memory + sizeof(struct metadata) + offset_metadata.total_size;
    struct record *records = memory + sizeof(struct metadata) + offset_metadata.total_size + key_metadata.total_size;

