    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i].value = value;
        records[i].key = key;
        records[i].offset = &offsets[i];
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove a record from the data structures
void remove_record(int value) {
    // Acquire a lock on the mutex before modifying global variables
    pthread_mutex_lock(&mutex);

    // Decrement the number of records in each data structure
    offset_metadata.num_records--;
    key_metadata.num_records--;
    record_metadata.num_records--;

    // Calculate the total size of each data structure
    offset_metadata.total_size -= sizeof(long);
    key_metadata.total_size -= sizeof(int);
    record_metadata.total_size -= sizeof(struct record);

    // Reallocate memory for each data structure if necessary
    long *offsets = memory + sizeof(struct metadata);
    int *keys = memory + sizeof(struct metadata) + offset_metadata.total_size;
    struct record *records = memory + sizeof(struct metadata) + offset_metadata.total_size + key_metadata.total_size;

    // Update the offsets, keys, and records with new values
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i].value = value;
        records[i].key = &keys[i];
        records[i].offset = &offsets[i];
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to update a record in the data structures
void update_record(int value, int *key) {
    // Acquire a lock on the mutex before modifying global variables
    pthread_mutex_lock(&mutex);

    // Update the offsets and keys with new values
    for (size_t i = 0; i < num_records; i++) {
        if (offsets[i] == value) {
            offsets[i] = -1;
            keys[i] = key;
        }
    }

    // Update the records with new values
    for (size_t i = 0; i < num_records; i++) {
        if (records[i].value == value) {
            records[i].value = -1;
            records[i].key = key;
            records[i].offset = &offsets[i];
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to search for a record in the data structures
void *search_record(int value) {
    // Acquire a lock on the mutex before modifying global variables
    pthread_mutex_lock(&mutex);

    // Search for the record with the specified value
    for (size_t i = 0; i < num_records; i++) {
        if (offsets[i] == value) {
            return &records[i];
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    // Return NULL if the record is not found
    return NULL;
}

// Function to track and report total memory usage in bytes for each of the three data structures separately
size_t get_total_memory_usage(int type) {
    switch (type) {
        case OFFSET:
            return offset_metadata.total_size;
        case KEY:
            return key_metadata.total_size;
        case RECORD:
            return record_metadata.total_size;
        default:
            return 0;
    }
}

// Function to calculate the average memory usage per record type
double get_average_memory_usage() {
    return (offset_metadata.total_size + key_metadata.total_size + record_metadata.total_size) / (num_records * 3);
}
