// create a new record hash with an initial capacity of 1000
RecordHash *create_record_hash() {
    RecordHash *record_hash = (RecordHash *)malloc(sizeof(RecordHash));
    record_hash->capacity = 1000;
    record_hash->load_factor = 0.75;
    record_hash->nodes = (RecordNode **)calloc(record_hash->capacity, sizeof(RecordNode *));
    return record_hash;
}

// create a new item list with an initial capacity of 1000
ItemList *create_item_list() {
    ItemList *item_list = (ItemList *)malloc(sizeof(ItemList));
    item_list->head = NULL;
    item_list->tail = NULL;
    item_list->size = 0;
    return item_list;
}

// create a new query list with an initial capacity of 1000
QueryList *create_query_list() {
    QueryList *query_list = (QueryList *)malloc(sizeof(QueryList));
    query_list->head = NULL;
    query_list->tail = NULL;
    query_list->size = 0;
    return query_list;
}

// insert an item into the item list
void insert_item(Item *item, ItemList *item_list) {
    // create a new node for the item
    ItemNode *new_node = (ItemNode *)malloc(sizeof(ItemNode));
    new_node->item = item;
    new_node->next = NULL;

    // if there are no items in the list, make the new node the head and tail
    if (item_list->head == NULL) {
        item_list->head = new_node;
        item_list->tail = new_node;
    } else {
        // otherwise, add the new node to the end of the list
        item_list->tail->next = new_node;
        item_list->tail = new_node;
    }

    // increment the size of the list
    item_list->size++;
}

// insert a record into the hash table
void insert_record(Record *record, RecordHash *record_hash) {
    // calculate the hash value for the record's integer value
    unsigned long hash = (unsigned long)record->int_val % record_hash->capacity;

    // if there are no records in the table with this hash value, create a new node
    // and set it as the head of the linked list for that hash value
    if (record_hash->nodes[hash] == NULL) {
        RecordNode *new_node = (RecordNode *)malloc(sizeof(RecordNode));
        new_node->record = record;
        new_node->next = NULL;
        record_hash->nodes[hash] = new_node;
    } else {
        // otherwise, find the end of the linked list for this hash value and add the new record
        RecordNode *cursor = record_hash->nodes[hash];
        while (cursor->next != NULL) {
            cursor = cursor->next;
        }
        RecordNode *new_node = (RecordNode *)malloc(sizeof(RecordNode));
        new_node->record = record;
        new_node->next = NULL;
        cursor->next = new_node;
    }
}

// search for items with a specified substring in their names and add them to the query list
void search_items(char *substring, ItemList *item_list, QueryList *query_list) {
    // loop through each item in the list
    for (ItemNode *cursor = item_list->head; cursor != NULL; cursor = cursor->next) {
        // if the substring is found in the item's name, create a new query node and add it to the list
        if (strstr(cursor->item->name, substring) != NULL) {
            QueryNode *new_node = (QueryNode *)malloc(sizeof(QueryNode));
            new_node->record = cursor->item;
            new_node->next = NULL;

            // if there are no queries in the list, make the new node the head and tail
            if (query_list->head == NULL) {
                query_list->head = new_node;
                query_list->tail = new_node;
            } else {
                // otherwise, add the new node to the end of the list
                query_list->tail->next = new_node;
                query_list->tail = new_node;
            }

            // increment the size of the list
            query_list->size++;
        }
    }
}

// find a node in the item list with a specified name and return its address
ItemNode *find_item_node(char *name, ItemList *item_list) {
    // loop through each item in the list until the correct node is found
    for (ItemNode *cursor = item_list->head; cursor != NULL; cursor = cursor->next) {
        if (!strcmp(cursor->item->name, name)) {
            return cursor;
        }
    }

    // if no matching node was found, return NULL
    return NULL;
}

// delete a node from the item list and deallocate its memory
void delete_item_node(ItemNode *item_node, ItemList *item_list) {
    // if the node is the head of the list, make the next node the new head
    if (item_node == item_list->head) {
        item_list->head = item_node->next;
    }

    // if the node is the tail of the list, make the previous node the new tail
    if (item_node == item_list->tail) {
        ItemNode *previous_node = item_list->tail;
        while (previous_node->next != NULL && previous_node->next != item_node) {
            previous_node = previous_node->next;
        }
        if (previous_node->next == NULL) {
            item_list->tail = previous_node;
        } else {
            previous_node->next = item_node->next;
        }
    }

    // otherwise, remove the node from the list by linking its predecessor and successor
    if (item_node->next != NULL) {
        ItemNode *previous_node = item_node->next;
        while (previous_node->next != item_node) {
            previous_node = previous_node->next;
        }
        previous_node->next = item_node->next;
    }

    // decrement the size of the list and deallocate the node's memory
    item_list->size--;
    free(item_node);
}

// create a new record structure with random integer values in its `int` field
Record *create_record() {
    Record *record = (Record *)malloc(sizeof(Record));
    record->int_val = rand() % 100 + 1;
    return record;
}

// create a new item structure with random integer values in its `int` field
Item *create_item() {
    Item *item = (Item *)malloc(sizeof(Item));
    item->name = "example";
    item->value.int_val = rand() % 100 + 1;
    return item;
}

// destroy a record hash and deallocate its memory
void destroy_record_hash(RecordHash *record_hash) {
    // loop through each linked list in the hash table
    for (int i = 0; i < record_hash->capacity; i++) {
        RecordNode *cursor = record_hash->nodes[i];
        while (cursor != NULL) {
            RecordNode *next = cursor->next;
            free(cursor);
            cursor = next;
        }
    }
    free(record_hash->nodes);
    free(record_hash);
}

// destroy an item list and deallocate its memory
void destroy_item_list(ItemList *item_list) {
    // loop through each node in the list
    for (ItemNode *cursor = item_list->head; cursor != NULL; cursor = cursor->next) {
        free(cursor);
    }
    free(item_list);
}

// destroy a query list and deallocate its memory
void destroy_query_list(QueryList *query_list) {
    // loop through each node in the list
    for (QueryNode *cursor = query_list->head; cursor != NULL; cursor = cursor->next) {
        free(cursor);
    }
    free(query_list);
}
