```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

// Define the structure for a task schedule record
struct task_record {
    int priority;
    char *key;
};

// Define the function to manage task schedules
void manage_task_schedules(struct task_record **records, int num_records) {
    // Initialize the random seed for generating priorities
    srand(time(NULL));

    // Allocate memory for the array of records
    records = malloc(sizeof(struct task_record *) * num_records);

    // Initialize each record with a random priority between 1 and 100
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(struct task_record));
        records[i]->priority = rand() % 100 + 1;
        records[i]->key = NULL;
    }

    // Implement a mechanism to track and manage usage of the array
    int max_usage = 0;
    for (int i = 0; i < num_records; i++) {
        if (max_usage < records[i]->priority) {
            max_usage = records[i]->priority;
        }
    }
    int usage[max_usage + 1];
    memset(usage, 0, sizeof(int) * (max_usage + 1));

    for (int i = 0; i < num_records; i++) {
        usage[records[i]->priority]++;
    }

    // Implement a retry mechanism to handle failed allocations
    int failed_allocations = 0;
    while (failed_allocations < num_records) {
        for (int i = 0; i < num_records; i++) {
            if (usage[i] >= 10000) {
                continue;
            }
            records[i]->key = malloc(sizeof(char *) * 256);
            if (records[i]->key == NULL) {
                failed_allocations++;
                break;
            }
        }
    }

    // Implement a garbage collection strategy to periodically clean up records flagged for deletion
    int gc_interval = 1000;
    while (1) {
        sleep(gc_interval);
        for (int i = 0; i < num_records; i++) {
            if (usage[i] == 0 && records[i]->key != NULL) {
                free(records[i]->key);
                usage[i]--;
            }
        }
    }

    // Thread-safe access to the 'record' array and secondary data structures
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_records; i++) {
        records[i]->key = malloc(sizeof(char *) * 256);
        pthread_mutex_lock(&mutex);
        usage[i]++;
        pthread_mutex_unlock(&mutex);
    }

    // Ensure all dynamically allocated memory is properly managed and freed upon function exit, even in the presence of errors, to prevent memory leaks and resource exhaustion.
    for (int i = 0; i < num_records; i++) {
        free(records[i]->key);
    }
    free(records);
}
