struct WeatherRecord {
    char *location;
    double temperature;
    time_t timestamp;
};

// function to dynamically allocate memory for a variable number of weather records
// each consisting of a location name, a temperature reading, and a timestamp
struct WeatherRecord* allocateWeatherRecords(int numRecords) {
    // calculate the size of memory required to store all records
    int totalSize = sizeof(struct WeatherRecord) * numRecords;

    // allocate memory for the records using malloc()
    struct WeatherRecord *records = (struct WeatherRecord*)malloc(totalSize);

    // check if memory allocation was successful
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for weather records\n");
        return NULL;
    }

    // initialize the records with empty values
    memset(records, 0, totalSize);

    return records;
}

// function to generate temperature readings using a sine wave pattern
// adjusted by a random factor to account for natural variability
double generateTemperatureReading(double baseTemp, time_t timestamp) {
    // calculate the sine wave value based on the timestamp
    double sinValue = (sin((timestamp / 10.0) * M_PI) + 1.0) / 2.0;

    // adjust the temperature reading based on the random factor
    double tempReading = baseTemp + (sinValue * 5.0);

    return tempReading;
}

