        fprintf(stderr, "Error: failed to allocate memory for weather records\n");
        return -1;
    }

    // read location names and temperature readings from the input file
    int i = 0;
    while (fscanf(fp, "%s %lf", (*records)[i].location, &(*records)[i].temperature) == 2) {
        // generate a random factor for adjusting the temperature reading based on natural variability
        double randFactor = (double)(rand() % 10) / 10.0;

        // calculate the base temperature reading and add the random factor
        (*records)[i].temperature += randFactor;

        // generate a timestamp for each record using the current time
        (*records)[i].timestamp = time(NULL);

        i++;
    }

    // close the input file
    fclose(fp);

    return i;
}

// function to deallocate all allocated memory when done
void deallocateWeatherRecords(struct WeatherRecord *records) {
    free(records);
}

// function to calculate and print the average temperature for each location
void calculateAverageTemperature(struct WeatherRecord *records, int numRecords) {
    // initialize a map to track the number of records for each location
    // use a linked list to store the records in order of appearance
    struct MapNode {
        char *location;
        int count;
        struct WeatherRecord *records;
        struct MapNode *next;
    } *map = NULL;

    // iterate over all records and update the map for each location
    for (int i = 0; i < numRecords; i++) {
        struct MapNode *node = malloc(sizeof(struct MapNode));
        node->location = strdup(records[i].location);
        node->count = 1;
        node->records = &records[i];
        node->next = map;
        map = node;
    }

    // iterate over all locations in the map and calculate the average temperature
    double totalTemp = 0.0;
    int count = 0;
    for (struct MapNode *node = map; node != NULL; node = node->next) {
        totalTemp += node->records[0].temperature;
        count++;

        printf("Average temperature for %s: %f\n", node->location, totalTemp / count);
    }

    // deallocate the map and all records associated with it
    struct MapNode *curr = map;
    while (curr != NULL) {
        free(curr->location);
        free(curr->records);
        curr = curr->next;
    }
}

int main(int argc, char **argv) {
