void init_record(weather_record *record, const char *location, double temperature, time_t timestamp) {
    strncpy(record->location, location, MAX_NAME_LEN);
    record->temperature = temperature;
    record->timestamp = timestamp;
}

void add_record(weather_record *records, size_t num_records, weather_record record) {
    if (num_records < MAX_RECORDS) {
        records[num_records] = record;
        num_records++;
    } else {
        fprintf(stderr, "Maximum number of records exceeded\n");
    }
}

void print_record(weather_record *record) {
    printf("%s: %lf at %ld\n", record->location, record->temperature, record->timestamp);
}

void print_average_temperature(weather_record *records, size_t num_records) {
    double sum = 0;
    for (size_t i = 0; i < num_records; i++) {
        sum += records[i].temperature;
    }
    printf("Average temperature: %lf\n", sum / num_records);
}

void free_hash_table(htable *table) {
    free(table->bucket);
    free(table);
}

typedef struct {
    char *key;
    weather_record value;
} htable_entry;

typedef struct {
    size_t num_buckets;
    size_t num_entries;
    htable_entry **bucket;
} htable;

htable *create_hash_table(size_t num_buckets) {
    htable *table = malloc(sizeof(htable));
    if (table == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        exit(EXIT_FAILURE);
    }
    table->num_buckets = num_buckets;
    table->num_entries = 0;
    table->bucket = malloc(num_buckets * sizeof(htable_entry *));
    if (table->bucket == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table buckets\n");
        exit(EXIT_FAILURE);
    }
    return table;
}

int hash(const char *key) {
    int hash = 0;
    size_t i = 0;
    while (key[i] != '\0') {
        hash = (hash << 5) - hash + key[i];
        i++;
    }
    return hash % table->num_buckets;
}

htable_entry *find(const char *key, htable *table) {
    int index = hash(key);
    htable_entry *entry = table->bucket[index];
    while (entry != NULL && strcmp(entry->key, key) != 0) {
        entry = entry->next;
    }
    return entry;
}

void insert(const char *key, weather_record value, htable *table) {
    int index = hash(key);
    htable_entry *entry = find(key, table);
    if (entry != NULL) {
        entry->value = value;
    } else {
        htable_entry *new_entry = malloc(sizeof(htable_entry));
        new_entry->key = strdup(key);
        new_entry->value = value;
        new_entry->next = table->bucket[index];
        table->bucket[index] = new_entry;
        table->num_entries++;
    }
}

void delete(const char *key, htable *table) {
    int index = hash(key);
    htable_entry **prev = &table->bucket[index];
    while (*prev != NULL && strcmp((*prev)->key, key) != 0) {
        prev = &(*prev)->next;
    }
    if (*prev == NULL) {
        fprintf(stderr, "Key not found: %s\n", key);
    } else {
        htable_entry *entry = *prev;
        *prev = entry->next;
        free(entry->key);
        free(entry);
        table->num_entries--;
    }
}

void lookup(const char *key, htable *table) {
    htable_entry *entry = find(key, table);
    if (entry == NULL) {
        fprintf(stderr, "Key not found: %s\n", key);
    } else {
        print_record(&entry->value);
    }
}

int main() {
    // Initialize the hash table with a large number of buckets to handle large datasets efficiently
    htable *table = create_hash_table(10000000);

    // Allocate memory for and initialize an array of weather records
    size_t num_records = 0;
    weather_record *records = allocate_records(num_records);

    // Read a list of location names from standard input
    char *location;
    while (scanf("%s", location) == 1) {
        // Generate a sine wave function with added noise to simulate environmental data over time
        double temperature = sin(2 * M_PI * (time(NULL) / 86400)) + rand() % 10;
        // Initialize a new weather record using the sine wave function and a random factor
        init_record(&records[num_records], location, temperature, time(NULL));
        num_records++;
    }

    // Insert each weather record into the hash table for fast lookups
    for (size_t i = 0; i < num_records; i++) {
        insert(records[i].location, records[i], table);
    }

    // Find and print the average temperature for each location using the hash table
    char *location;
    while (scanf("%s", location) == 1) {
        lookup(location, table);
    }

    // Clean up memory and deallocate all allocated records when done
    free_hash_table(table);
    deallocate_records(records);

    return 0;
}
