// Define the structure to store records
typedef struct Record {
    long offset;
    int key;
    float value;
    char status;
} Record;

// Define a linked list node for storing record pointers
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Define the data structure to store records and their offsets
struct DataStructure {
    // The head node of the linked list containing record pointers
    Node *head;
    // The tail node of the linked list containing record pointers
    Node *tail;
    // The total number of records stored in the data structure
    int num_records;
};

// Define a hash table to store records and their keys
struct HashTable {
    // The head node of the linked list containing record pointers
    Node *head;
    // The tail node of the linked list containing record pointers
    Node *tail;
    // The total number of records stored in the hash table
    int num_records;
};

// Define a mechanism to track memory usage and I/O operations
struct Metrics {
    // The total amount of memory allocated for all records
    size_t memory_usage;
    // The total number of bytes written to disk
    size_t disk_bytes_written;
};

// Define a function to dynamically manage memory for a variable number of records
void manage_memory(struct DataStructure *ds, int key, float value, char status) {
    // Calculate the offset for the new record using the key and increment factor
    long offset = (key % ds->increment_factor) * ds->increment_factor;

    // Allocate memory for the new record
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        printf("Error: Failed to allocate memory for a new record.\n");
        return;
    }

    // Initialize the fields of the new record
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    new_record->status = status;

    // Add the new record to the linked list and update metrics
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for a new node.\n");
        free(new_record);
        return;
    }
    new_node->record = new_record;
    new_node->next = NULL;
    ds->tail->next = new_node;
    ds->tail = new_node;
    ds->num_records++;
    ds->metrics.memory_usage += sizeof(Record);
}

// Define a function to deallocate all allocated memory when done
void deallocate_memory(struct DataStructure *ds) {
    // Free the memory for each record in the linked list and reset metrics
    Node *node = ds->head;
    while (node != NULL) {
        Record *record = node->record;
        free(record);
        node = node->next;
    }
    ds->num_records = 0;
    ds->metrics.memory_usage = 0;
}

// Define a function to find and print the largest integer in an array
void find_largest_integer(int *arr, int size) {
    // Initialize variables for tracking the largest value and its index
    int largest_value = INT_MIN;
    int largest_index = -1;

    // Iterate through the array and find the largest integer
    for (int i = 0; i < size; i++) {
        if (arr[i] > largest_value) {
            largest_value = arr[i];
            largest_index = i;
        }
    }

