        ht->records[i] = NULL;
    }

    ht->capacity = capacity;
    ht->count = 0;
}

// Insert a new key-offset pair into the hash table, expanding the table if necessary
void insert(HashTable* ht, int key, long offset) {
    assert(ht != NULL);
    assert(key >= 0 && key < ht->capacity);

    // If the hash table is full, resize it and rehash all keys
    if (ht->count == ht->capacity) {
        resize(ht, GROWTH_FACTOR);
    }

    // Find the slot where the key-offset pair will be stored
    size_t index = hash(key);

    // If a collision occurs, probe for an empty slot using quadratic probing
    while (ht->keys[index] != EMPTY && ht->keys[index] != DELETED) {
