    }

    // Store the key-offset pair in the found slot
    ht->offsets[index] = offset;
    ht->keys[index] = key;
    ht->records[index] = malloc(sizeof(Record));
    ht->records[index]->key = key;
    ht->records[index]->offset = offset;

    // Increment the count of occupied slots in the hash table
    ++ht->count;
}

// Remove a key-offset pair from the hash table, shrinking the table if necessary
void remove(HashTable* ht, int key) {
    assert(ht != NULL);
    assert(key >= 0 && key < ht->capacity);

    // If the key is not found in the hash table, return immediately
    size_t index = hash(key);
    if (ht->keys[index] == EMPTY || ht->keys[index] == DELETED) {
        return;
    }

    // Store the offset value associated with the key in a temporary variable
    long offset = ht->offsets[index];

    // Mark the slot as deleted
    ht->keys[index] = DELETED;

    // Decrement the count of occupied slots in the hash table
    --ht->count;

    // If the hash table is 1/4 empty, resize it and rehash all keys
    if (ht->count < ht->capacity / GROWTH_FACTOR) {
        resize(ht, GROWTH_FACTOR);
    }

    return offset;
}

// Search for a key-offset pair in the hash table and return its associated value
long search(HashTable* ht, int key) {
    assert(ht != NULL);
    assert(key >= 0 && key < ht->capacity);

    // Find the slot where the key is stored
    size_t index = hash(key);

    // If the key is not found in the hash table, return immediately
    if (ht->keys[index] == EMPTY || ht->keys[index] == DELETED) {
        return NULL;
    }

    // Return the offset value associated with the key
    return ht->offsets[index];
}

// Update a key-offset pair in the hash table and return its associated value
long update(HashTable* ht, int key, long offset) {
    assert(ht != NULL);
    assert(key >= 0 && key < ht->capacity);

    // Find the slot where the key is stored
    size_t index = hash(key);

    // If the key is not found in the hash table, return immediately
    if (ht->keys[index] == EMPTY || ht->keys[index] == DELETED) {
        return NULL;
    }

    // Store the new offset value associated with the key in a temporary variable
    long old_offset = ht->offsets[index];

    // Update the offset value associated with the key
    ht->offsets[index] = offset;
    ht->records[index]->offset = offset;

    return old_offset;
}

// Resize the hash table to a specified size, rehashing all keys and updating the capacity
void resize(HashTable* ht, size_t new_capacity) {
    assert(ht != NULL);
    assert(new_capacity > 0);

    // Allocate memory for the new hash table structure and its components
    HashTable new_ht = {
        .offsets = malloc(sizeof(long) * new_capacity),
        .keys = malloc(sizeof(int) * new_capacity),
        .records = malloc(sizeof(Record*) * new_capacity),
        .capacity = new_capacity,
        .count = 0,
    };

    // Initialize the offset array with random values within the specified range
    for (size_t i = 0; i < new_capacity; ++i) {
        new_ht.offsets[i] = rand() % new_capacity;
    }

    // Initialize the key array with unique values
    for (size_t i = 0; i < new_capacity; ++i) {
        new_ht.keys[i] = i;
    }

    // Initialize the record array with empty structures
    for (size_t i = 0; i < new_capacity; ++i) {
        new_ht.records[i] = NULL;
    }

    // Rehash all keys from the old hash table into the new one
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->keys[i] != EMPTY && ht->keys[i] != DELETED) {
            insert(&new_ht, ht->keys[i], ht->offsets[i]);
        }
    }

    // Free the memory allocated for the old hash table
    free(ht->offsets);
    free(ht->keys);
    free(ht->records);

    // Update the capacity and pointer to the hash table
    ht->capacity = new_capacity;
    ht->offsets = new_ht.offsets;
    ht->keys = new_ht.keys;
    ht->records = new_ht.records;
}

// Free all memory allocated for the hash table and its components
void free(HashTable* ht) {
    assert(ht != NULL);

    // Release the memory allocated for the offset array, key array, and record array
    free(ht->offsets);
    free(ht->keys);
    free(ht->records);

    // Set the pointer to the hash table to NULL
    ht = NULL;
}
